SECTION "Maps 2", ROMX

;@ path: scripts/PalletTown
;@ def PalletTown_Script()
;@ Pallet Town's map script: once Oak has handed out the Poké Balls, note it for the town's people, then run
;@ the current step of the town's script (Oak stopping the player at the edge of the tall grass).
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PalletTown_Script:
;> if event(EVENT_GOT_POKEBALLS_FROM_OAK):
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEBALLS_FROM_OAK) % 8, a
	jr z, .next
;>     set_event(EVENT_PALLET_AFTER_GETTING_POKEBALLS)
	ld hl, wEventFlags + $0
	set (EVENT_PALLET_AFTER_GETTING_POKEBALLS) % 8, [hl]
.next
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> CallFunctionInTable(wPalletTownCurScript, PalletTown_ScriptPointers)
	ld hl, PalletTown_ScriptPointers
	ld a, [wPalletTownCurScript]
	jp CallFunctionInTable

;@ path: scripts/PalletTown
PalletTown_ScriptPointers:
	dw PalletTownDefaultScript
DEF SCRIPT_PALLETTOWN_DEFAULT EQU 0
	dw PalletTownOakHeyWaitScript
DEF SCRIPT_PALLETTOWN_OAK_HEY_WAIT EQU 1
	dw PalletTownOakWalksToPlayerScript
DEF SCRIPT_PALLETTOWN_OAK_WALKS_TO_PLAYER EQU 2
	dw PalletTownOakNotSafeComeWithMeScript
DEF SCRIPT_PALLETTOWN_OAK_NOT_SAFE_COME_WITH_ME EQU 3
	dw PalletTownPlayerFollowsOakScript
DEF SCRIPT_PALLETTOWN_PLAYER_FOLLOWS_OAK EQU 4
	dw PalletTownDaisyScript
DEF SCRIPT_PALLETTOWN_DAISY EQU 5
	dw PalletTownNoopScript
DEF SCRIPT_PALLETTOWN_NOOP EQU 6

;@ path: scripts/PalletTown
;@ def PalletTownDefaultScript()
;@ Until the player has followed Oak to his lab: stepping onto the north exit (row 1) freezes the controls,
;@ starts Oak's music and sets off his "Hey! Wait!" scene.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PalletTownDefaultScript:
;> if event(EVENT_FOLLOWED_OAK_INTO_LAB) or wYCoord != 1:
;>     return
	ld a, [wEventFlags + $0]
	bit (EVENT_FOLLOWED_OAK_INTO_LAB) % 8, a
	ret nz
	ld a, [wYCoord]
	cp 1 ; is player near north exit?
	ret nz
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wPlayerMovingDirection = PLAYER_DIR_DOWN
	ld a, PLAYER_DIR_DOWN
	ld [wPlayerMovingDirection], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	ld a, SFX_STOP_ALL_MUSIC
	call PlaySound
;> PlayMusic(MUSIC_MEET_PROF_OAK, BANK(Music_MeetProfOak))
	ld a, BANK(Music_MeetProfOak)
	ld c, a
	ld a, MUSIC_MEET_PROF_OAK ; "oak appears" music
	call PlayMusic
;> wJoyIgnore = PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld a, PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> set_event(EVENT_OAK_APPEARED_IN_PALLET)
	ld hl, wEventFlags + $4
	set (EVENT_OAK_APPEARED_IN_PALLET) % 8, [hl]

;> wPalletTownCurScript = SCRIPT_PALLETTOWN_OAK_HEY_WAIT
	; trigger the next script
	ld a, SCRIPT_PALLETTOWN_OAK_HEY_WAIT
	ld [wPalletTownCurScript], a
	ret

;@ path: scripts/PalletTown
;@ def PalletTownOakHeyWaitScript()
;@ Oak calls out "Hey! Wait! Don't go out!" and appears at the edge of town.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PalletTownOakHeyWaitScript:
;> wOakWalkedToPlayer = 0
	xor a
	ld [wOakWalkedToPlayer], a
;> hTextID = TEXT_PALLETTOWN_OAK
	ld a, TEXT_PALLETTOWN_OAK
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wToggleableObjectIndex = TOGGLE_PALLET_TOWN_OAK
	ld a, TOGGLE_PALLET_TOWN_OAK
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef

;> wPalletTownCurScript = SCRIPT_PALLETTOWN_OAK_WALKS_TO_PLAYER
	; trigger the next script
	ld a, SCRIPT_PALLETTOWN_OAK_WALKS_TO_PLAYER
	ld [wPalletTownCurScript], a
	ret

;@ path: scripts/PalletTown
;@ def PalletTownOakWalksToPlayerScript()
;@ Oak looks up, works out the path to the player (stopping one step short) and starts walking it.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PalletTownOakWalksToPlayerScript:
;> hSpriteIndex = PALLETTOWN_OAK
	ld a, PALLETTOWN_OAK
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> Delay3()
	call Delay3
;> wYCoord = 1
	ld a, 1
	ld [wYCoord], a
;> hNPCPlayerRelativePosPerspective = 1
	ld a, 1
	ldh [hNPCPlayerRelativePosPerspective], a
;> hNPCSpriteOffset = 1 << 4                    # Oak is sprite 1
	ld a, 1
	swap a
	ldh [hNPCSpriteOffset], a
;> predef(CalcPositionOfPlayerRelativeToNPC)
	ld a, (CalcPositionOfPlayerRelativeToNPCPredef - PredefPointers) / 3
	call Predef
;> hNPCPlayerYDistance = (hNPCPlayerYDistance - 1) & 0xFF
	ld hl, hNPCPlayerYDistance
	dec [hl]
;> predef(FindPathToPlayer)                     # Oak's steps into wNPCMovementDirections2
	; load Oak's movement into wNPCMovementDirections2
	ld a, (FindPathToPlayerPredef - PredefPointers) / 3
	call Predef
;> hSpriteIndex = PALLETTOWN_OAK
	ld de, wNPCMovementDirections2
	ld a, PALLETTOWN_OAK
	ldh [hSpriteIndex], a
;> MoveSprite(addr(wNPCMovementDirections2))
	call MoveSprite
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a

;> wPalletTownCurScript = SCRIPT_PALLETTOWN_OAK_NOT_SAFE_COME_WITH_ME
	; trigger the next script
	ld a, SCRIPT_PALLETTOWN_OAK_NOT_SAFE_COME_WITH_ME
	ld [wPalletTownCurScript], a
	ret

;@ path: scripts/PalletTown
;@ def PalletTownOakNotSafeComeWithMeScript()
;@ When Oak has reached the player: "It's unsafe! Come with me!", then set up the walk that makes the player
;@ follow him to his lab.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PalletTownOakNotSafeComeWithMeScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return                                    # Oak is still walking
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> mem[wSpritePlayerStateData1FacingDirection] = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
	ld [wSpritePlayerStateData1FacingDirection], a
;> wOakWalkedToPlayer = TRUE
	ld a, TRUE
	ld [wOakWalkedToPlayer], a
;> wJoyIgnore = PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld a, PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hTextID = TEXT_PALLETTOWN_OAK
	ld a, TEXT_PALLETTOWN_OAK
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
; set up movement script that causes the player to follow Oak to his lab
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wSpriteIndex = PALLETTOWN_OAK
	ld a, PALLETTOWN_OAK
	ld [wSpriteIndex], a
;> wNPCMovementScriptFunctionNum = 0
	xor a
	ld [wNPCMovementScriptFunctionNum], a
;> wNPCMovementScriptPointerTableNum = 1        # the walk to Oak's lab
	ld a, 1
	ld [wNPCMovementScriptPointerTableNum], a
;> wNPCMovementScriptBank = hLoadedROMBank
	ldh a, [hLoadedROMBank]
	ld [wNPCMovementScriptBank], a

;> wPalletTownCurScript = SCRIPT_PALLETTOWN_PLAYER_FOLLOWS_OAK
	; trigger the next script
	ld a, SCRIPT_PALLETTOWN_PLAYER_FOLLOWS_OAK
	ld [wPalletTownCurScript], a
	ret

;@ path: scripts/PalletTown
;@ def PalletTownPlayerFollowsOakScript()
;@ Wait until the walk to the lab is over, then go on to the Daisy step.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PalletTownPlayerFollowsOakScript:
;> if wNPCMovementScriptPointerTableNum:   # the walk is still going on
;>     return
	ld a, [wNPCMovementScriptPointerTableNum]
	and a ; is the movement script over?
	ret nz

	; trigger the next script
;> wPalletTownCurScript = SCRIPT_PALLETTOWN_DAISY
	ld a, SCRIPT_PALLETTOWN_DAISY
	ld [wPalletTownCurScript], a
	ret

;@ path: scripts/PalletTown
;@ def PalletTownDaisyScript()
;@ Once the player has the Town Map and has been in Blue's house, Daisy gets up from her chair and walks
;@ around; after the Poké Balls from Oak, note that for the town's people too.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PalletTownDaisyScript:
;> if not event(EVENT_DAISY_WALKING) and event(EVENT_GOT_TOWN_MAP) and event(EVENT_ENTERED_BLUES_HOUSE):
	ld a, [wEventFlags + $3]
	bit (EVENT_DAISY_WALKING) % 8, a
	jr nz, .next
	and (1 << ((EVENT_GOT_TOWN_MAP) % 8)) | (1 << ((EVENT_ENTERED_BLUES_HOUSE) % 8))
	cp (1 << ((EVENT_GOT_TOWN_MAP) % 8)) | (1 << ((EVENT_ENTERED_BLUES_HOUSE) % 8))
	jr nz, .next
;>     set_event(EVENT_DAISY_WALKING)
	ld hl, wEventFlags + $3
	set (EVENT_DAISY_WALKING) % 8, [hl]
;>     wToggleableObjectIndex = TOGGLE_DAISY_SITTING
	ld a, TOGGLE_DAISY_SITTING
	ld [wToggleableObjectIndex], a
;>     predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;>     wToggleableObjectIndex = TOGGLE_DAISY_WALKING
	ld a, TOGGLE_DAISY_WALKING
	ld [wToggleableObjectIndex], a
;>     return predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	jp Predef
.next
;> if event(EVENT_GOT_POKEBALLS_FROM_OAK):
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEBALLS_FROM_OAK) % 8, a
	ret z
;>     set_event(EVENT_PALLET_AFTER_GETTING_POKEBALLS_2)
	ld hl, wEventFlags + $4
	set (EVENT_PALLET_AFTER_GETTING_POKEBALLS_2) % 8, [hl]
