;@ path: scripts/PalletTown
;@ def PalletTownOakText() -> hl
;@ Oak in Pallet Town: first "Hey! Wait! Don't go out!" (the player turns round with a "!" over his head),
;@ then, once he has walked up, "It's unsafe! Wild Pokémon live in tall grass!".
;@ test: skip a text script: the code after text_asm is run by the text engine
PalletTownOakText:
	db TX_START_ASM
;> if not wOakWalkedToPlayer:
	ld a, [wOakWalkedToPlayer]
	and a
	jr nz, .next
;>     wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, 1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;>     PrintText(PalletTownOakText.HeyWaitDontGoOutText)   # its own code turns the player round
	ld hl, .HeyWaitDontGoOutText
	jr .done
.next
;> else:
;>     PrintText(PalletTownOakText.ItsUnsafeText)
	ld hl, .ItsUnsafeText
.done
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.HeyWaitDontGoOutText:
	db TX_FAR
	dw _PalletTownOakHeyWaitDontGoOutText
	db BANK(_PalletTownOakHeyWaitDontGoOutText)
	db TX_START_ASM
;> def HeyWaitDontGoOutText():          # runs after "Hey! Wait! Don't go out!"
;>     DelayFrames(10)
	ld c, 10
	call DelayFrames
;>     wEmotionBubbleSpriteIndex = 0     # over the player
;>     wWhichEmotionBubble = EXCLAMATION_BUBBLE
	xor a
	ld [wEmotionBubbleSpriteIndex], a ; player's sprite
	ld [wWhichEmotionBubble], a ; EXCLAMATION_BUBBLE
;>     predef(EmotionBubble)
	ld a, (EmotionBubblePredef - PredefPointers) / 3
	call Predef
;>     wPlayerMovingDirection = PLAYER_DIR_DOWN   # the player turns round to face Oak
	ld a, PLAYER_DIR_DOWN
	ld [wPlayerMovingDirection], a
;>     return TextScriptEnd()
	jp TextScriptEnd

.ItsUnsafeText:
	db TX_FAR
	dw _PalletTownOakItsUnsafeText
	db BANK(_PalletTownOakItsUnsafeText)
	db TX_END

