;@ path: scripts/ViridianCity
;@ def ViridianCity_Script()
;@ Viridian City's map script: run the current step of the city's script (the locked gym, the sleepy old
;@ man blocking the road, his catching lesson).
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
ViridianCity_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wViridianCityCurScript, ViridianCity_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld hl, ViridianCity_ScriptPointers
	ld a, [wViridianCityCurScript]
	jp CallFunctionInTable

;@ path: scripts/ViridianCity
ViridianCity_ScriptPointers:
	dw ViridianCityDefaultScript
DEF SCRIPT_VIRIDIANCITY_DEFAULT EQU 0
