DEF SCRIPT_VIRIDIANCITY_OLD_MAN_START_CATCH_TRAINING EQU 1
	dw ViridianCityOldManEndCatchTrainingScript
DEF SCRIPT_VIRIDIANCITY_OLD_MAN_END_CATCH_TRAINING EQU 2
