;@ path: scripts/ViridianCity
;@ def ViridianCityDefaultScript()
;@ Every step in the city: check the gym door and the road blocked by the old man.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
ViridianCityDefaultScript:
;> ViridianCityCheckGymOpenScript()
;> return ViridianCityCheckGotPokedexScript()
	call ViridianCityCheckGymOpenScript
	jp ViridianCityCheckGotPokedexScript

;@ path: scripts/ViridianCity
;@ def ViridianCityCheckGymOpenScript()
;@ The gym opens once the player has the other seven badges; until then, walking up to its door shows the
;@ "gym is locked" sign and pushes the player one step back down.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
ViridianCityCheckGymOpenScript:
;> if event(EVENT_VIRIDIAN_GYM_OPEN):
;>     return
	ld a, [wEventFlags + $5]
	bit (EVENT_VIRIDIAN_GYM_OPEN) % 8, a
	ret nz
;> if wObtainedBadges == ~(1 << BIT_EARTHBADGE) & 0xFF:
	ld a, [wObtainedBadges]
	cp ~(1 << BIT_EARTHBADGE)
	jr nz, .gym_closed
;>     set_event(EVENT_VIRIDIAN_GYM_OPEN)
	ld hl, wEventFlags + $5
	set (EVENT_VIRIDIAN_GYM_OPEN) % 8, [hl]
;>     return
	ret
.gym_closed
;> if wYCoord != 8 or wXCoord != 32:
;>     return
	ld a, [wYCoord]
	cp 8
	ret nz
	ld a, [wXCoord]
	cp 32
	ret nz
;> hTextID = TEXT_VIRIDIANCITY_GYM_LOCKED
	ld a, TEXT_VIRIDIANCITY_GYM_LOCKED
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> ViridianCityMovePlayerDownScript()
	call ViridianCityMovePlayerDownScript
;> wViridianCityCurScript = SCRIPT_VIRIDIANCITY_PLAYER_MOVING_DOWN
	ld a, SCRIPT_VIRIDIANCITY_PLAYER_MOVING_DOWN
	ld [wViridianCityCurScript], a
	ret

;@ path: scripts/ViridianCity
;@ def ViridianCityCheckGotPokedexScript()
;@ Until the player has the Pokédex, the old man lying on the road north of town says it is private
;@ property, and the player is pushed one step back down.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
ViridianCityCheckGotPokedexScript:
;> if event(EVENT_GOT_POKEDEX):
;>     return
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEDEX) % 8, a
	ret nz
;> if wYCoord != 9:                # not right below the old man
;>     return
	ld a, [wYCoord]
	cp 9
	ret nz
;> if wXCoord != 19:
;>     return
	ld a, [wXCoord]
	cp 19
	ret nz
;> hTextID = TEXT_VIRIDIANCITY_OLD_MAN_SLEEPY
	ld a, TEXT_VIRIDIANCITY_OLD_MAN_SLEEPY
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> ViridianCityMovePlayerDownScript()
	call ViridianCityMovePlayerDownScript
;> wViridianCityCurScript = SCRIPT_VIRIDIANCITY_PLAYER_MOVING_DOWN
	ld a, SCRIPT_VIRIDIANCITY_PLAYER_MOVING_DOWN
	ld [wViridianCityCurScript], a
	ret

;@ path: scripts/ViridianCity
;@ def ViridianCityOldManStartCatchTrainingScript()
;@ Start the old man's catching demonstration: keep his sprite's place for afterwards, and set up the
;@ special battle in which he catches a level 5 Weedle.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
ViridianCityOldManStartCatchTrainingScript:
;> hSpriteScreenYCoord = mem[wSprite03StateData1YPixels]
	ld a, [wSprite03StateData1YPixels]
	ldh [hSpriteScreenYCoord], a
;> hSpriteScreenXCoord = mem[wSprite03StateData1XPixels]
	ld a, [wSprite03StateData1XPixels]
	ldh [hSpriteScreenXCoord], a
;> hSpriteMapYCoord = mem[wSprite03StateData2MapY]
	ld a, [wSprite03StateData2MapY]
	ldh [hSpriteMapYCoord], a
;> hSpriteMapXCoord = mem[wSprite03StateData2MapX]
	ld a, [wSprite03StateData2MapX]
	ldh [hSpriteMapXCoord], a
;> wListScrollOffset = 0
	xor a
	ld [wListScrollOffset], a

;> wBattleType = BATTLE_TYPE_OLD_MAN
	; set up battle for Old Man
	ld a, BATTLE_TYPE_OLD_MAN
	ld [wBattleType], a
;> wCurEnemyLevel = 5
	ld a, 5
	ld [wCurEnemyLevel], a
;> wCurOpponent = WEEDLE
	ld a, WEEDLE
	ld [wCurOpponent], a
;> wViridianCityCurScript = SCRIPT_VIRIDIANCITY_OLD_MAN_END_CATCH_TRAINING
	ld a, SCRIPT_VIRIDIANCITY_OLD_MAN_END_CATCH_TRAINING
	ld [wViridianCityCurScript], a
	ret

;@ path: scripts/ViridianCity
;@ def ViridianCityOldManEndCatchTrainingScript()
;@ After the demonstration: put the old man's sprite back and let him explain that you weaken a Pokémon
;@ before throwing the ball.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
ViridianCityOldManEndCatchTrainingScript:
;> mem[wSprite03StateData1YPixels] = hSpriteScreenYCoord
	ldh a, [hSpriteScreenYCoord]
	ld [wSprite03StateData1YPixels], a
;> mem[wSprite03StateData1XPixels] = hSpriteScreenXCoord
	ldh a, [hSpriteScreenXCoord]
	ld [wSprite03StateData1XPixels], a
;> mem[wSprite03StateData2MapY] = hSpriteMapYCoord
	ldh a, [hSpriteMapYCoord]
	ld [wSprite03StateData2MapY], a
;> mem[wSprite03StateData2MapX] = hSpriteMapXCoord
	ldh a, [hSpriteMapXCoord]
	ld [wSprite03StateData2MapX], a
;> UpdateSprites()
	call UpdateSprites
;> Delay3()
	call Delay3
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> hTextID = TEXT_VIRIDIANCITY_OLD_MAN_YOU_NEED_TO_WEAKEN_THE_TARGET
	ld a, TEXT_VIRIDIANCITY_OLD_MAN_YOU_NEED_TO_WEAKEN_THE_TARGET
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wBattleType = 0
	xor a
	ld [wBattleType], a
;> wJoyIgnore = 0
	ld [wJoyIgnore], a
;> wViridianCityCurScript = SCRIPT_VIRIDIANCITY_DEFAULT
	ld a, SCRIPT_VIRIDIANCITY_DEFAULT
	ld [wViridianCityCurScript], a
	ret

;@ path: scripts/ViridianCity
;@ def ViridianCityPlayerMovingDownScript()
;@ Wait until the push back down has been walked, then back to the default step.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
ViridianCityPlayerMovingDownScript:
;> if wSimulatedJoypadStatesIndex:     # still walking
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> Delay3()
	call Delay3
;> wViridianCityCurScript = SCRIPT_VIRIDIANCITY_DEFAULT
	ld a, SCRIPT_VIRIDIANCITY_DEFAULT
	ld [wViridianCityCurScript], a
	ret

;@ path: scripts/ViridianCity
;@ def ViridianCityMovePlayerDownScript()
;@ Make the player walk one step down by simulated joypad input.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
ViridianCityMovePlayerDownScript:
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wSimulatedJoypadStatesIndex = 1       # one simulated input:
;> wSimulatedJoypadStatesEnd = PAD_DOWN   # a step down
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
	ld a, PAD_DOWN
	ld [wSimulatedJoypadStatesEnd], a
;> wSpritePlayerStateData1FacingDirection = SPRITE_FACING_DOWN
;> wJoyIgnore = 0
	xor a
	ld [wSpritePlayerStateData1FacingDirection], a
	ld [wJoyIgnore], a
	ret

