;@ def ViridianCityGambler1Text() -> hl
;@ The man by the gym: it is always closed - or, once the player has the other seven badges (or has beaten
;@ Giovanni), the leader is back.
;@ test: skip a text script: the code after text_asm is run by the text engine
ViridianCityGambler1Text:
	db TX_START_ASM
;> if wObtainedBadges == ~(1 << BIT_EARTHBADGE) & 0xFF:    # all badges but the Earth Badge
;>     text = ViridianCityGambler1Text.GymLeaderReturnedText
	ld a, [wObtainedBadges]
	cp ~(1 << BIT_EARTHBADGE)
	ld hl, .GymLeaderReturnedText
	jr z, .print_text
;> elif event(EVENT_BEAT_VIRIDIAN_GYM_GIOVANNI):
;>     text = ViridianCityGambler1Text.GymLeaderReturnedText
	ld a, [wEventFlags + $A]
	bit (EVENT_BEAT_VIRIDIAN_GYM_GIOVANNI) % 8, a
	jr nz, .print_text
;> else:
;>     text = ViridianCityGambler1Text.GymAlwaysClosedText
	ld hl, .GymAlwaysClosedText
.print_text
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

