;@ The fisher: gives TM42 (DREAM EATER) once, if the bag has room, and explains it afterwards.
;@ test: skip a text script: the code after text_asm is run by the text engine
ViridianCityFisherText:
	db TX_START_ASM
;> if event(EVENT_GOT_TM42):
	ld a, [wEventFlags + $5]
	bit (EVENT_GOT_TM42) % 8, a
	jr nz, .got_item
;>@expl     PrintText(ViridianCityFisherText.TM42ExplanationText)
;> else:
;>     PrintText(ViridianCityFisherText.YouCanHaveThisText)
	ld hl, .YouCanHaveThisText
	call PrintText
;>     if GiveItem(TM_DREAM_EATER, 1):
	ld bc, ((TM_DREAM_EATER) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         PrintText(ViridianCityFisherText.ReceivedTM42Text)
	ld hl, .ReceivedTM42Text
	call PrintText
;>         set_event(EVENT_GOT_TM42)
	ld hl, wEventFlags + $5
	set (EVENT_GOT_TM42) % 8, [hl]
	jr .done
.bag_full
;>     else:
;>         PrintText(ViridianCityFisherText.TM42NoRoomText)
	ld hl, .TM42NoRoomText
	call PrintText
	jr .done
.got_item
;=@expl
	ld hl, .TM42ExplanationText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

