;> if wCurrentMenuItem != 0:                    # "no": he shows you
	ld a, [wCurrentMenuItem]
	and a
	jr z, .refused
;>     PrintText(ViridianCityOldManText.KnowHowToCatchPokemonText)
	ld hl, .KnowHowToCatchPokemonText
	call PrintText
;>     wViridianCityCurScript = SCRIPT_VIRIDIANCITY_OLD_MAN_START_CATCH_TRAINING
	ld a, SCRIPT_VIRIDIANCITY_OLD_MAN_START_CATCH_TRAINING
	ld [wViridianCityCurScript], a
	jr .done
.refused
;> else:
;>     PrintText(ViridianCityOldManText.TimeIsMoneyText)
	ld hl, .TimeIsMoneyText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

