;@ path: scripts/PewterCity
;@ def PewterCity_Script()
;@ Pewter City's map script: run the current step of the city's script (the two guides who lead the player
;@ to the museum and to the gym).
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PewterCity_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wPewterCityCurScript, PewterCity_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld hl, PewterCity_ScriptPointers
	ld a, [wPewterCityCurScript]
	jp CallFunctionInTable

;@ path: scripts/PewterCity
PewterCity_ScriptPointers:
	dw PewterCityDefaultScript
DEF SCRIPT_PEWTERCITY_DEFAULT EQU 0
	dw PewterCitySuperNerd1ShowsPlayerMuseumScript
DEF SCRIPT_PEWTERCITY_SUPER_NERD1_SHOWS_PLAYER_MUSEUM EQU 1
	dw PewterCityHideSuperNerd1Script
DEF SCRIPT_PEWTERCITY_HIDE_SUPER_NERD1 EQU 2
	dw PewterCityResetSuperNerd1Script
DEF SCRIPT_PEWTERCITY_RESET_SUPER_NERD1 EQU 3
	dw PewterCityYoungsterShowsPlayerGymScript
DEF SCRIPT_PEWTERCITY_YOUNGSTER_SHOWS_PLAYER_GYM EQU 4
	dw PewterCityHideYoungsterScript
DEF SCRIPT_PEWTERCITY_HIDE_YOUNGSTER EQU 5
	dw PewterCityResetYoungsterScript
DEF SCRIPT_PEWTERCITY_RESET_YOUNGSTER EQU 6

;@ path: scripts/PewterCity
;@ def PewterCityDefaultScript()
;@ Every step in the city: the museum forgets the bought ticket (and its script starts over), and the player
;@ may be stopped on the way out east.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PewterCityDefaultScript:
;> wMuseum1FCurScript = 0
	xor a
	ld [wMuseum1FCurScript], a
;> reset_event(EVENT_BOUGHT_MUSEUM_TICKET)
	ld hl, wEventFlags + $D
	res (EVENT_BOUGHT_MUSEUM_TICKET) % 8, [hl]
;> PewterCityCheckPlayerLeavingEastScript()
	call PewterCityCheckPlayerLeavingEastScript
	ret

;@ path: scripts/PewterCity
;@ def PewterCityCheckPlayerLeavingEastScript()
;@ Until Brock is beaten, walking to the east exit makes the youngster stop the player (he then leads the way
;@ to the gym).
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PewterCityCheckPlayerLeavingEastScript:
;> if event(EVENT_BEAT_BROCK):
;>     return
	ld a, [wEventFlags + $E]
	bit (EVENT_BEAT_BROCK) % 8, a
	ret nz
;> if not ArePlayerCoordsInArray(PewterCityPlayerLeavingEastCoords):
;>     return
	ld hl, PewterCityPlayerLeavingEastCoords
	call ArePlayerCoordsInArray
	ret nc
;> wJoyIgnore = PAD_CTRL_PAD              # the player stops
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hTextID = TEXT_PEWTERCITY_YOUNGSTER
;> return DisplayTextID()
	ld a, TEXT_PEWTERCITY_YOUNGSTER
	ldh [hTextID], a
	jp DisplayTextID

;@ path: scripts/PewterCity
PewterCityPlayerLeavingEastCoords:
	db 17, 35
	db 17, 36
	db 18, 37
	db 19, 37
	db -1 ; end

;@ path: scripts/PewterCity
;@ def PewterCitySuperNerd1ShowsPlayerMuseumScript()
;@ Once the walk to the museum is over: the guide turns to the door, says "It's right here!", is put back at
;@ his spot by the door and walks away.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PewterCitySuperNerd1ShowsPlayerMuseumScript:
;> if wNPCMovementScriptPointerTableNum:
;>     return                                    # still walking to the museum
	ld a, [wNPCMovementScriptPointerTableNum]
	and a
	ret nz
;> hSpriteIndex = PEWTERCITY_SUPER_NERD1
	ld a, PEWTERCITY_SUPER_NERD1
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hSpriteImageIndex = 3 << 4 | SPRITE_FACING_UP
	ld a, ($3 << 4) | SPRITE_FACING_UP
	ldh [hSpriteImageIndex], a
;> SetSpriteImageIndexAfterSettingFacingDirection(wSpriteStateData1 + PEWTERCITY_SUPER_NERD1 * 16 + SPRITESTATEDATA1_FACINGDIRECTION, hSpriteImageIndex)
	call SetSpriteImageIndexAfterSettingFacingDirection
;> PlayDefaultMusic()
	call PlayDefaultMusic
;> wMiscFlags |= 1 << BIT_NO_SPRITE_UPDATES
	ld hl, wMiscFlags
	set BIT_NO_SPRITE_UPDATES, [hl]
;> hTextID = TEXT_PEWTERCITY_SUPER_NERD1_ITS_RIGHT_HERE
	ld a, TEXT_PEWTERCITY_SUPER_NERD1_ITS_RIGHT_HERE
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hSpriteScreenYCoord = 0x3C
	ld a, $3c
	ldh [hSpriteScreenYCoord], a
;> hSpriteScreenXCoord = 0x30
	ld a, $30
	ldh [hSpriteScreenXCoord], a
;> hSpriteMapYCoord = 12
	ld a, 12
	ldh [hSpriteMapYCoord], a
;> hSpriteMapXCoord = 17
	ld a, 17
	ldh [hSpriteMapXCoord], a
;> wSpriteIndex = PEWTERCITY_SUPER_NERD1
	ld a, PEWTERCITY_SUPER_NERD1
	ld [wSpriteIndex], a
;> SetSpritePosition1()
	call SetSpritePosition1
;> hSpriteIndex = PEWTERCITY_SUPER_NERD1
	ld a, PEWTERCITY_SUPER_NERD1
	ldh [hSpriteIndex], a
;> MoveSprite(MovementData_PewterMuseumGuyExit)
	ld de, MovementData_PewterMuseumGuyExit
	call MoveSprite
;> wPewterCityCurScript = SCRIPT_PEWTERCITY_HIDE_SUPER_NERD1
	ld a, SCRIPT_PEWTERCITY_HIDE_SUPER_NERD1
	ld [wPewterCityCurScript], a
	ret

;@ path: scripts/PewterCity
MovementData_PewterMuseumGuyExit:
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db -1 ; end

;@ path: scripts/PewterCity
;@ def PewterCityHideSuperNerd1Script()
;@ When the museum guide has walked off: hide him.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PewterCityHideSuperNerd1Script:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:   # still walking
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> wToggleableObjectIndex = TOGGLE_MUSEUM_GUY
;> predef(HideObject)
	ld a, TOGGLE_MUSEUM_GUY
	ld [wToggleableObjectIndex], a
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wPewterCityCurScript = SCRIPT_PEWTERCITY_RESET_SUPER_NERD1
	ld a, SCRIPT_PEWTERCITY_RESET_SUPER_NERD1
	ld [wPewterCityCurScript], a
	ret

;@ path: scripts/PewterCity
;@ def PewterCityResetSuperNerd1Script()
;@ Put the museum guide back where he stood before the walk, show him again and give the controls back.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PewterCityResetSuperNerd1Script:
;> wSpriteIndex = PEWTERCITY_SUPER_NERD1
	ld a, PEWTERCITY_SUPER_NERD1
	ld [wSpriteIndex], a
;> SetSpritePosition2()
	call SetSpritePosition2
;> wToggleableObjectIndex = TOGGLE_MUSEUM_GUY
	ld a, TOGGLE_MUSEUM_GUY
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wPewterCityCurScript = SCRIPT_PEWTERCITY_DEFAULT
	ld a, SCRIPT_PEWTERCITY_DEFAULT
	ld [wPewterCityCurScript], a
	ret

;@ path: scripts/PewterCity
;@ def PewterCityYoungsterShowsPlayerGymScript()
;@ Once the walk to the gym is over: the youngster turns to it, says "Go take on Brock!", is put back at a
;@ spot by the gym and walks away. (His screen X is $40 where $50 would match, so he shows up misaligned.)
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
PewterCityYoungsterShowsPlayerGymScript:
;> if wNPCMovementScriptPointerTableNum:
;>     return
	ld a, [wNPCMovementScriptPointerTableNum]
	and a
	ret nz
;> hSpriteIndex = PEWTERCITY_YOUNGSTER
	ld a, PEWTERCITY_YOUNGSTER
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_LEFT
	ld a, SPRITE_FACING_LEFT
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hSpriteImageIndex = 1 << 4 | SPRITE_FACING_LEFT
	ld a, ($1 << 4) | SPRITE_FACING_LEFT
	ldh [hSpriteImageIndex], a
;> SetSpriteImageIndexAfterSettingFacingDirection(wSpriteStateData1 + PEWTERCITY_YOUNGSTER * 16 + SPRITESTATEDATA1_FACINGDIRECTION, hSpriteImageIndex)
	call SetSpriteImageIndexAfterSettingFacingDirection
;> PlayDefaultMusic()
	call PlayDefaultMusic
;> wMiscFlags |= 1 << BIT_NO_SPRITE_UPDATES
	ld hl, wMiscFlags
	set BIT_NO_SPRITE_UPDATES, [hl]
;> hTextID = TEXT_PEWTERCITY_YOUNGSTER_GO_TAKE_ON_BROCK
	ld a, TEXT_PEWTERCITY_YOUNGSTER_GO_TAKE_ON_BROCK
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hSpriteScreenYCoord = 0x3C
	ld a, $3c
	ldh [hSpriteScreenYCoord], a
;> hSpriteScreenXCoord = 0x40
	ld a, $40 ; BUG: should load $50, using $40 causes sprite misalignment
	ldh [hSpriteScreenXCoord], a
;> hSpriteMapYCoord = 22
	ld a, 22
	ldh [hSpriteMapYCoord], a
;> hSpriteMapXCoord = 16
	ld a, 16
	ldh [hSpriteMapXCoord], a
;> wSpriteIndex = PEWTERCITY_YOUNGSTER
	ld a, PEWTERCITY_YOUNGSTER
	ld [wSpriteIndex], a
;> SetSpritePosition1()
	call SetSpritePosition1
;> hSpriteIndex = PEWTERCITY_YOUNGSTER
	ld a, PEWTERCITY_YOUNGSTER
	ldh [hSpriteIndex], a
;> MoveSprite(MovementData_PewterGymGuyExit)
	ld de, MovementData_PewterGymGuyExit
	call MoveSprite
;> wPewterCityCurScript = SCRIPT_PEWTERCITY_HIDE_YOUNGSTER
	ld a, SCRIPT_PEWTERCITY_HIDE_YOUNGSTER
	ld [wPewterCityCurScript], a
	ret

