;@ path: scripts/PewterCity
;@ def PewterCitySuperNerd1Text() -> hl
;@ The man near the museum: asks if you have been to the museum; on "no" he takes you there himself.
;@ test: skip a text script: the code after text_asm is run by the text engine
PewterCitySuperNerd1Text:
	db TX_START_ASM
;> PrintText(PewterCitySuperNerd1Text.DidYouCheckOutMuseumText)
	ld hl, .DidYouCheckOutMuseumText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem == 0:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .playerDidNotGoIntoMuseum
;>     PrintText(PewterCitySuperNerd1Text.WerentThoseFossilsAmazingText)
	ld hl, .WerentThoseFossilsAmazingText
	call PrintText
;>     return TextScriptEnd()
;> PrintText(PewterCitySuperNerd1Text.YouHaveToGoText)
	jr .done
.playerDidNotGoIntoMuseum
	ld hl, .YouHaveToGoText
	call PrintText
;> hJoyPressed = hJoyHeld = 0
	xor a
	ldh [hJoyPressed], a
	ldh [hJoyHeld], a
;> wNPCMovementScriptFunctionNum = 0
	ld [wNPCMovementScriptFunctionNum], a
;> wNPCMovementScriptPointerTableNum = 2        # the walk to the museum
	ld a, $2
	ld [wNPCMovementScriptPointerTableNum], a
;> wNPCMovementScriptBank = hLoadedROMBank
	ldh a, [hLoadedROMBank]
	ld [wNPCMovementScriptBank], a
;> wSpriteIndex = PEWTERCITY_SUPER_NERD1
	ld a, PEWTERCITY_SUPER_NERD1
	ld [wSpriteIndex], a
;> GetSpritePosition2()                         # remember where he stands
	call GetSpritePosition2
;> wPewterCityCurScript = SCRIPT_PEWTERCITY_SUPER_NERD1_SHOWS_PLAYER_MUSEUM
	ld a, SCRIPT_PEWTERCITY_SUPER_NERD1_SHOWS_PLAYER_MUSEUM
	ld [wPewterCityCurScript], a
.done
;> return TextScriptEnd()
	jp TextScriptEnd

