;@ path: scripts/CeruleanCity
;@ def CeruleanCity_Script()
;@ Cerulean City's map script: run the current step of the city's script (the Rocket thief, the rival on the bridge).
CeruleanCity_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wCeruleanCityCurScript, CeruleanCity_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld hl, CeruleanCity_ScriptPointers
	ld a, [wCeruleanCityCurScript]
	jp CallFunctionInTable

;@ path: scripts/CeruleanCity
;@ def CeruleanCityClearScripts()
;@ Back to the default step after a lost battle: give the controls back and hide the rival.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
CeruleanCityClearScripts:
;> wJoyIgnore = 0
	xor a ; SCRIPT_CERULEANCITY_DEFAULT
	ld [wJoyIgnore], a
;> wCeruleanCityCurScript = SCRIPT_CERULEANCITY_DEFAULT     # (also 0)
	ld [wCeruleanCityCurScript], a
;> wToggleableObjectIndex = TOGGLE_CERULEAN_RIVAL
	ld a, TOGGLE_CERULEAN_RIVAL
	ld [wToggleableObjectIndex], a
;> HideObject()
	ld a, (HideObjectPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/CeruleanCity
CeruleanCity_ScriptPointers:
	dw CeruleanCityDefaultScript
DEF SCRIPT_CERULEANCITY_DEFAULT EQU 0
	dw CeruleanCityRivalBattleScript
DEF SCRIPT_CERULEANCITY_RIVAL_BATTLE EQU 1
	dw CeruleanCityRivalDefeatedScript
DEF SCRIPT_CERULEANCITY_RIVAL_DEFEATED EQU 2
	dw CeruleanCityRivalCleanupScript
DEF SCRIPT_CERULEANCITY_RIVAL_CLEANUP EQU 3
	dw CeruleanCityRocketDefeatedScript
DEF SCRIPT_CERULEANCITY_ROCKET_DEFEATED EQU 4

;@ path: scripts/CeruleanCity
;@ def CeruleanCityRocketDefeatedScript()
;@ After the fight with the Rocket who stole TM28: lost, start over; won, mark him beaten and let him speak.
CeruleanCityRocketDefeatedScript:
;> if wIsInBattle == LOST_BATTLE:
	ld a, [wIsInBattle]
	cp LOST_BATTLE
;>     return CeruleanCityClearScripts()
	jp z, CeruleanCityClearScripts
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> set_event(EVENT_BEAT_CERULEAN_ROCKET_THIEF)
	ld hl, wEventFlags + $14
	set (EVENT_BEAT_CERULEAN_ROCKET_THIEF) % 8, [hl]
;> hTextID = TEXT_CERULEANCITY_ROCKET
	ld a, TEXT_CERULEANCITY_ROCKET
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wJoyIgnore = 0
	xor a ; SCRIPT_CERULEANCITY_DEFAULT
	ld [wJoyIgnore], a
;> wCeruleanCityCurScript = SCRIPT_CERULEANCITY_DEFAULT
	ld [wCeruleanCityCurScript], a
	ret

;@ path: scripts/CeruleanCity
;@ def CeruleanCityDefaultScript()
;@ Every step in the city: walking past the Rocket thief makes him face you and talk; stepping on the bridge
;@ (until the rival is beaten) plays the rival's music and sends him walking down to you.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
CeruleanCityDefaultScript:
;> if not event(EVENT_BEAT_CERULEAN_ROCKET_THIEF) and ArePlayerCoordsInArray(CeruleanCityCoords1):
	ld a, [wEventFlags + $14]
	bit (EVENT_BEAT_CERULEAN_ROCKET_THIEF) % 8, a
	jr nz, .skipRocketThiefEncounter
	ld hl, CeruleanCityCoords1
	call ArePlayerCoordsInArray
	jr nc, .skipRocketThiefEncounter
;>     # the player and the thief turn to face each other
;>     direction, facing = PLAYER_DIR_UP, SPRITE_FACING_DOWN     # the player is below him
;>     if wCoordIndex == 1:                                      # the player is above him
	ld a, [wCoordIndex]
	cp $1
	ld a, PLAYER_DIR_UP
	ld b, SPRITE_FACING_DOWN
	jr nz, .playerBelowRocketThief
;>         direction, facing = PLAYER_DIR_DOWN, SPRITE_FACING_UP
	ld a, PLAYER_DIR_DOWN
	ld b, SPRITE_FACING_UP
.playerBelowRocketThief
;>     wPlayerMovingDirection = direction
	ld [wPlayerMovingDirection], a
;>     wSprite02StateData1FacingDirection = facing
	ld a, b
	ld [wSprite02StateData1FacingDirection], a
;>     Delay3()
	call Delay3
;>     hTextID = TEXT_CERULEANCITY_ROCKET
	ld a, TEXT_CERULEANCITY_ROCKET
	ldh [hTextID], a
;>     return DisplayTextID()
	jp DisplayTextID
.skipRocketThiefEncounter
;> if event(EVENT_BEAT_CERULEAN_RIVAL):
;>     return
	ld a, [wEventFlags + $13]
	bit (EVENT_BEAT_CERULEAN_RIVAL) % 8, a
	ret nz
;> if not ArePlayerCoordsInArray(CeruleanCityCoords2):     # not on the bridge
;>     return
	ld hl, CeruleanCityCoords2
	call ArePlayerCoordsInArray
	ret nc
;> if wWalkBikeSurfState:                  # cycling: stop the bike music first
	ld a, [wWalkBikeSurfState]
	and a
	jr z, .walking
;>     wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;>     PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
.walking
;> PlayMusic(MUSIC_MEET_RIVAL, BANK(Music_MeetRival))
	ld c, BANK(Music_MeetRival)
	ld a, MUSIC_MEET_RIVAL
	call PlayMusic
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> if wXCoord != 20:                       # the player is on the left side of the bridge:
	ld a, [wXCoord]
	cp 20 ; is the player standing on the right side of the bridge?
	jr z, .playerOnRightSideOfBridge
;>     hSpriteIndex = CERULEANCITY_RIVAL   # the rival comes down the left side too
	ld a, CERULEANCITY_RIVAL
	ldh [hSpriteIndex], a
;>     hSpriteDataOffset = SPRITESTATEDATA2_MAPX
	ld a, SPRITESTATEDATA2_MAPX
	ldh [hSpriteDataOffset], a
;>     mem[GetPointerWithinSpriteStateData2()] = 25
	call GetPointerWithinSpriteStateData2
	ld [hl], 25
.playerOnRightSideOfBridge
;> wToggleableObjectIndex = TOGGLE_CERULEAN_RIVAL
	ld a, TOGGLE_CERULEAN_RIVAL
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> hSpriteIndex = CERULEANCITY_RIVAL
;> MoveSprite(CeruleanCityMovement1)
	ld de, CeruleanCityMovement1
	ld a, CERULEANCITY_RIVAL
	ldh [hSpriteIndex], a
	call MoveSprite
;> wCeruleanCityCurScript = SCRIPT_CERULEANCITY_RIVAL_BATTLE
	ld a, SCRIPT_CERULEANCITY_RIVAL_BATTLE
	ld [wCeruleanCityCurScript], a
	ret

