;@ path: scripts/CeruleanCity
;@ def CeruleanCityFaceRivalScript()
;@ Turn the rival to face down (towards the player).
CeruleanCityFaceRivalScript:
;> hSpriteIndex = CERULEANCITY_RIVAL
	ld a, CERULEANCITY_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	jp SetSpriteFacingDirectionAndDelay ; face object

;@ path: scripts/CeruleanCity
;@ def CeruleanCityRivalBattleScript()
;@ Once the rival has walked up: his text, then the battle, with the team that beats your starter.
CeruleanCityRivalBattleScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:   # still walking up
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> hTextID = TEXT_CERULEANCITY_RIVAL
	ld a, TEXT_CERULEANCITY_RIVAL
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(CeruleanCityRivalDefeatedText, CeruleanCityRivalVictoryText)
	ld hl, CeruleanCityRivalDefeatedText
	ld de, CeruleanCityRivalVictoryText
	call SaveEndBattleTextPointers
;> wCurOpponent = OPP_RIVAL1
	ld a, OPP_RIVAL1
	ld [wCurOpponent], a

	; select which team to use during the encounter
;> if wRivalStarter == STARTER2:
	ld a, [wRivalStarter]
	cp STARTER2
	jr nz, .NotSquirtle
;>     team = 7
	ld a, $7
	jr .done
.NotSquirtle
;> elif wRivalStarter == STARTER3:
	cp STARTER3
	jr nz, .Charmander
;>     team = 8
	ld a, $8
	jr .done
.Charmander
;> else:
;>     team = 9
	ld a, $9
.done
;> wTrainerNo = team
	ld [wTrainerNo], a

;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> CeruleanCityFaceRivalScript()
	call CeruleanCityFaceRivalScript
;> wCeruleanCityCurScript = SCRIPT_CERULEANCITY_RIVAL_DEFEATED
	ld a, SCRIPT_CERULEANCITY_RIVAL_DEFEATED
	ld [wCeruleanCityCurScript], a
	ret

;@ path: scripts/CeruleanCity
;@ def CeruleanCityRivalDefeatedScript()
;@ After the rival battle: lost, start over; won, his parting words, his tune, and he walks off the bridge.
CeruleanCityRivalDefeatedScript:
;> if wIsInBattle == LOST_BATTLE:
	ld a, [wIsInBattle]
	cp LOST_BATTLE
;>     return CeruleanCityClearScripts()
	jp z, CeruleanCityClearScripts
;> CeruleanCityFaceRivalScript()
	call CeruleanCityFaceRivalScript
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> set_event(EVENT_BEAT_CERULEAN_RIVAL)
	ld hl, wEventFlags + $13
	set (EVENT_BEAT_CERULEAN_RIVAL) % 8, [hl]
;> hTextID = TEXT_CERULEANCITY_RIVAL
	ld a, TEXT_CERULEANCITY_RIVAL
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> Music_RivalAlternateStart()
	ld b, BANK(Music_RivalAlternateStart)
	ld hl, Music_RivalAlternateStart
	call Bankswitch
;> hSpriteIndex = CERULEANCITY_RIVAL
	ld a, CERULEANCITY_RIVAL
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> if wXCoord == 20:                       # the player stands on the right side of the bridge
	ld a, [wXCoord]
	cp 20 ; is the player standing on the right side of the bridge?
	jr nz, .playerOnRightSideOfBridge
;>     movement = CeruleanCityMovement4
	ld de, CeruleanCityMovement4
	jr .skip
.playerOnRightSideOfBridge
;> else:
;>     movement = CeruleanCityMovement3
	ld de, CeruleanCityMovement3
.skip
;> hSpriteIndex = CERULEANCITY_RIVAL
	ld a, CERULEANCITY_RIVAL
	ldh [hSpriteIndex], a
;> MoveSprite(movement)
	call MoveSprite
;> wCeruleanCityCurScript = SCRIPT_CERULEANCITY_RIVAL_CLEANUP
	ld a, SCRIPT_CERULEANCITY_RIVAL_CLEANUP
	ld [wCeruleanCityCurScript], a
	ret

