;@ path: scripts/CeruleanCity
;@ def CeruleanCityRivalText() -> hl
;@ The rival: his challenge before the battle, then talk about Bill.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeruleanCityRivalText:
	db TX_START_ASM
;> if event(EVENT_BEAT_CERULEAN_RIVAL):
	ld a, [wEventFlags + $13]
	bit (EVENT_BEAT_CERULEAN_RIVAL) % 8, a
	; do pre-battle text
	jr z, .PreBattle
	; or talk about bill
;>     PrintText(CeruleanCityRivalIWentToBillsText)
	ld hl, CeruleanCityRivalIWentToBillsText
	call PrintText
	jr .end
.PreBattle
;> else:
;>     PrintText(CeruleanCityRivalText.PreBattleText)
	ld hl, .PreBattleText
	call PrintText
.end
;> return TextScriptEnd()
	jp TextScriptEnd

.PreBattleText:
	db TX_FAR
	dw _CeruleanCityRivalPreBattleText
	db BANK(_CeruleanCityRivalPreBattleText)
	db TX_END

