	db TX_END

;@ path: scripts/CeruleanCity
;@ def CeruleanCityRocketText() -> hl
;@ The Rocket thief: before the fight he engages you; afterwards he hands back TM28 (DIG), if there is room.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeruleanCityRocketText:
	db TX_START_ASM
;> if not event(EVENT_BEAT_CERULEAN_ROCKET_THIEF):
	ld a, [wEventFlags + $14]
	bit (EVENT_BEAT_CERULEAN_ROCKET_THIEF) % 8, a
	jr nz, .beatRocketThief
;>     PrintText(CeruleanCityRocketText.Text)
	ld hl, .Text
	call PrintText
;>     wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;>     SaveEndBattleTextPointers(CeruleanCityRocketText.IGiveUpText, CeruleanCityRocketText.IGiveUpText)
	ld hl, .IGiveUpText
	ld de, .IGiveUpText
	call SaveEndBattleTextPointers
;>     wSpriteIndex = hTextID
	ldh a, [hTextID]
	ld [wSpriteIndex], a
;>     EngageMapTrainer()
	call EngageMapTrainer
;>     InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;>     wCeruleanCityCurScript = SCRIPT_CERULEANCITY_ROCKET_DEFEATED
	ld a, SCRIPT_CERULEANCITY_ROCKET_DEFEATED
	ld [wCeruleanCityCurScript], a
;>     return TextScriptEnd()
	jp TextScriptEnd
.beatRocketThief
;> PrintText(CeruleanCityRocketText.IllReturnTheTMText)
	ld hl, .IllReturnTheTMText
	call PrintText
;> if GiveItem(TM_DIG, 1):
	ld bc, ((TM_DIG) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr c, .Success
	ld hl, .TM28NoRoomText
	call PrintText
	jr .Done
.Success
;>     wDoNotWaitForButtonPressAfterDisplayingText = 1
;>     PrintText(CeruleanCityRocketText.ReceivedTM28Text)
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
	ld hl, .ReceivedTM28Text
	call PrintText
;>     CeruleanHideRocket()
	ld b, BANK(CeruleanHideRocket)
	ld hl, CeruleanHideRocket
	call Bankswitch
;> else:
.Done
;>     PrintText(CeruleanCityRocketText.TM28NoRoomText)
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _CeruleanCityRocketText
	db BANK(_CeruleanCityRocketText)
	db TX_END

.ReceivedTM28Text:
	db TX_FAR
	dw _CeruleanCityRocketReceivedTM28Text
	db BANK(_CeruleanCityRocketReceivedTM28Text)
	db TX_SOUND_GET_ITEM_1
	db TX_FAR
	dw _CeruleanCityRocketIBetterGetMovingText
	db BANK(_CeruleanCityRocketIBetterGetMovingText)
	db TX_WAIT_BUTTON
	db TX_END

.TM28NoRoomText:
	db TX_FAR
	dw _CeruleanCityRocketTM28NoRoomText
	db BANK(_CeruleanCityRocketTM28NoRoomText)
	db TX_END

.IGiveUpText:
	db TX_FAR
	dw _CeruleanCityRocketIGiveUpText
	db BANK(_CeruleanCityRocketIGiveUpText)
	db TX_END

.IllReturnTheTMText:
	db TX_FAR
	dw _CeruleanCityRocketIllReturnTheTMText
	db BANK(_CeruleanCityRocketIllReturnTheTMText)
	db TX_END

