;@ path: scripts/CeruleanCity
;@ def CeruleanCityCooltrainerF1Text() -> hl
;@ The girl with the Slowbro: one of three lines, picked at random.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeruleanCityCooltrainerF1Text:
	db TX_START_ASM
;> r = hRandomAdd
	ldh a, [hRandomAdd]
;> if r >= 180:
	cp 180 ; 76/256 chance of 1st dialogue
	jr c, .notFirstText
;>     PrintText(CeruleanCityCooltrainerF1Text.SlowbroUseSonicboomText)
	ld hl, .SlowbroUseSonicboomText
	call PrintText
	jr .end
;> elif r >= 100:
.notFirstText
	cp 100 ; 80/256 chance of 2nd dialogue
	jr c, .notSecondText
;>     PrintText(CeruleanCityCooltrainerF1Text.SlowbroPunchText)
	ld hl, .SlowbroPunchText
	call PrintText
	jr .end
;> else:
.notSecondText
;>     PrintText(CeruleanCityCooltrainerF1Text.SlowbroWithdrawText)
	; 100/256 chance of 3rd dialogue
	ld hl, .SlowbroWithdrawText
	call PrintText
;> return TextScriptEnd()
.end
	jp TextScriptEnd

.SlowbroUseSonicboomText:
	db TX_FAR
	dw _CeruleanCityCooltrainerF1SlowbroUseSonicboomText
	db BANK(_CeruleanCityCooltrainerF1SlowbroUseSonicboomText)
	db TX_END

