;@ path: scripts/CeruleanCity
;@ def CeruleanCitySlowbroText() -> hl
;@ Her Slowbro: one of four reactions, picked at random.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeruleanCitySlowbroText:
	db TX_START_ASM
;> r = hRandomAdd
	ldh a, [hRandomAdd]
;> if r >= 180:
	cp 180 ; 76/256 chance of 1st dialogue
	jr c, .notFirstText
;>     PrintText(CeruleanCitySlowbroText.TookASnoozeText)
	ld hl, .TookASnoozeText
	call PrintText
	jr .end
;> elif r >= 120:
.notFirstText
	cp 120 ; 60/256 chance of 2nd dialogue
	jr c, .notSecondText
;>     PrintText(CeruleanCitySlowbroText.IsLoafingAroundText)
	ld hl, .IsLoafingAroundText
	call PrintText
	jr .end
;> elif r >= 60:
.notSecondText
	cp 60 ; 60/256 chance of 3rd dialogue
	jr c, .notThirdText
;>     PrintText(CeruleanCitySlowbroText.TurnedAwayText)
	ld hl, .TurnedAwayText
	call PrintText
	jr .end
;> else:
.notThirdText
;>     PrintText(CeruleanCitySlowbroText.IgnoredOrdersText)
	; 60/256 chance of 4th dialogue
	ld hl, .IgnoredOrdersText
	call PrintText
;> return TextScriptEnd()
.end
	jp TextScriptEnd

