;@ path: scripts/VermilionCity
;@ def VermilionCity_Script()
;@ Vermilion City's map script: after coming back from the departed S.S. Anne, walk the player off the dock;
;@ on entering, pick which trash can in the gym hides the first switch; then run the current script step.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
VermilionCity_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> loaded2 = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if loaded2:
;>     VermilionCityLeftSSAnneCallbackScript()
	push hl
	call nz, VermilionCityLeftSSAnneCallbackScript
;> loaded1 = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	pop hl
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if loaded1:
;>@rnd     Random()
;>@can     wFirstLockTrashCanIndex = hRandomSub & 0x0E     # an even index: the can with the first switch
	call nz, .setFirstLockTrashCanIndex
;> CallFunctionInTable(wVermilionCityCurScript, VermilionCity_ScriptPointers)
	ld hl, VermilionCity_ScriptPointers
	ld a, [wVermilionCityCurScript]
	jp CallFunctionInTable

.setFirstLockTrashCanIndex
;=@rnd
	call Random
;=@can
	ldh a, [hRandomSub]
	and $e
	ld [wFirstLockTrashCanIndex], a
	ret

;@ path: scripts/VermilionCity
;@ def VermilionCityLeftSSAnneCallbackScript()
;@ The first time the player comes back to town after the S.S. Anne has sailed, walk him two steps off the
;@ dock.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
VermilionCityLeftSSAnneCallbackScript:
;> if not event(EVENT_SS_ANNE_LEFT):
;>     return
	ld hl, wEventFlags + $BC
	bit (EVENT_SS_ANNE_LEFT) % 8, [hl]
	ret z
;> walked = event(EVENT_WALKED_PAST_GUARD_AFTER_SS_ANNE_LEFT)
	bit (EVENT_WALKED_PAST_GUARD_AFTER_SS_ANNE_LEFT) % 8, [hl]
;> set_event(EVENT_WALKED_PAST_GUARD_AFTER_SS_ANNE_LEFT)
	set (EVENT_WALKED_PAST_GUARD_AFTER_SS_ANNE_LEFT) % 8, [hl]
;> if not walked:
	ret nz
;>     wVermilionCityCurScript = SCRIPT_VERMILIONCITY_PLAYER_EXIT_SHIP
	ld a, SCRIPT_VERMILIONCITY_PLAYER_EXIT_SHIP
	ld [wVermilionCityCurScript], a
	ret

;@ path: scripts/VermilionCity
VermilionCity_ScriptPointers:
	dw VermilionCityDefaultScript
DEF SCRIPT_VERMILIONCITY_DEFAULT EQU 0
	dw VermilionCityPlayerMovingUp1Script
DEF SCRIPT_VERMILIONCITY_PLAYER_MOVING_UP1 EQU 1
	dw VermilionCityPlayerExitShipScript
DEF SCRIPT_VERMILIONCITY_PLAYER_EXIT_SHIP EQU 2
	dw VermilionCityPlayerMovingUp2Script
DEF SCRIPT_VERMILIONCITY_PLAYER_MOVING_UP2 EQU 3
	dw VermilionCityPlayerAllowedToPassScript
DEF SCRIPT_VERMILIONCITY_PLAYER_ALLOWED_TO_PASS EQU 4

;@ path: scripts/VermilionCity
;@ def VermilionCityDefaultScript()
;@ Walking down onto the guard at the dock: the sailor asks for the ticket. Without an S.S. Ticket (or once the
;@ ship has sailed) the player is pushed one step back up.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
VermilionCityDefaultScript:
;> if mem[wSpritePlayerStateData1FacingDirection] != SPRITE_FACING_DOWN:
;>     return
	ld a, [wSpritePlayerStateData1FacingDirection]
	and a ; cp SPRITE_FACING_DOWN
	ret nz
;> if not ArePlayerCoordsInArray(SSAnneTicketCheckCoords):
;>     return
	ld hl, SSAnneTicketCheckCoords
	call ArePlayerCoordsInArray
	ret nc
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wSavedCoordIndex = 0
	ld [wSavedCoordIndex], a ; unnecessary
;> hTextID = TEXT_VERMILIONCITY_SAILOR1
	ld a, TEXT_VERMILIONCITY_SAILOR1
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> if not event(EVENT_SS_ANNE_LEFT):
	ld a, [wEventFlags + $BC]
	bit (EVENT_SS_ANNE_LEFT) % 8, a
	jr nz, .ship_departed
;>     count = predef(GetQuantityOfItemInBag, bc=S_S_TICKET << 8)     # the count comes back in b
	ld b, S_S_TICKET
	ld a, (GetQuantityOfItemInBagPredef - PredefPointers) / 3
	call Predef
;>     if count:                                 # has the ticket: may pass
;>         return
	ld a, b
	and a
	ret nz
.ship_departed
;> wSimulatedJoypadStatesEnd = PAD_UP
	ld a, PAD_UP
	ld [wSimulatedJoypadStatesEnd], a
;> wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wVermilionCityCurScript = SCRIPT_VERMILIONCITY_PLAYER_MOVING_UP1
	ld a, SCRIPT_VERMILIONCITY_PLAYER_MOVING_UP1
	ld [wVermilionCityCurScript], a
	ret

;@ path: scripts/VermilionCity
SSAnneTicketCheckCoords:
	db 30, 18
	db -1 ; end

;@ path: scripts/VermilionCity
;@ def VermilionCityPlayerAllowedToPassScript()
;@ After showing the ticket: the player may walk past the guard; once off those spots, back to the default.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
VermilionCityPlayerAllowedToPassScript:
;> if ArePlayerCoordsInArray(SSAnneTicketCheckCoords):
;>     return
	ld hl, SSAnneTicketCheckCoords
	call ArePlayerCoordsInArray
	ret c
;> wVermilionCityCurScript = SCRIPT_VERMILIONCITY_DEFAULT
	ld a, SCRIPT_VERMILIONCITY_DEFAULT
	ld [wVermilionCityCurScript], a
	ret

;@ path: scripts/VermilionCity
;@ def VermilionCityPlayerExitShipScript()
;@ Walk the player two steps up, off the dock, with the controls locked.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
VermilionCityPlayerExitShipScript:
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wSimulatedJoypadStatesEnd = PAD_UP
	ld a, PAD_UP
	ld [wSimulatedJoypadStatesEnd], a
;> mem[addr(wSimulatedJoypadStatesEnd) + 1] = PAD_UP
	ld [wSimulatedJoypadStatesEnd + 1], a
;> wSimulatedJoypadStatesIndex = 2
	ld a, 2
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wVermilionCityCurScript = SCRIPT_VERMILIONCITY_PLAYER_MOVING_UP2
	ld a, SCRIPT_VERMILIONCITY_PLAYER_MOVING_UP2
	ld [wVermilionCityCurScript], a
	ret

;@ path: scripts/VermilionCity
;@ def VermilionCityPlayerMovingUp2Script()
;@ Once the two steps off the dock are walked, give the controls back.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
VermilionCityPlayerMovingUp2Script:
;> if wSimulatedJoypadStatesIndex:       # still walking
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> wJoyIgnore = 0
;> hJoyHeld = 0
	xor a
	ld [wJoyIgnore], a
	ldh [hJoyHeld], a
;> wVermilionCityCurScript = SCRIPT_VERMILIONCITY_DEFAULT
	ld a, SCRIPT_VERMILIONCITY_DEFAULT
	ld [wVermilionCityCurScript], a
	ret

;@ path: scripts/VermilionCity
;@ def VermilionCityPlayerMovingUp1Script()
;@ Once the push back from the guard is walked, wait 10 frames and go back to the default step.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
VermilionCityPlayerMovingUp1Script:
;> if wSimulatedJoypadStatesIndex:     # still walking
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> DelayFrames(10)
	ld c, 10
	call DelayFrames
;> wVermilionCityCurScript = SCRIPT_VERMILIONCITY_DEFAULT
	ld a, SCRIPT_VERMILIONCITY_DEFAULT
	ld [wVermilionCityCurScript], a
	ret

