;@ path: scripts/VermilionCity
;@ def VermilionCitySailor1Text() -> hl
;@ The sailor guarding the dock: welcomes the player, and when the player stands in front of or behind him,
;@ asks for the ticket and lets him pass if he has one. After the ship has sailed, he says so.
;@ test: skip a text script: the code after text_asm is run by the text engine
VermilionCitySailor1Text:
	db TX_START_ASM
;> if event(EVENT_SS_ANNE_LEFT):
	ld a, [wEventFlags + $BC]
	bit (EVENT_SS_ANNE_LEFT) % 8, a
	jr nz, .ship_departed
;>@sail     PrintText(VermilionCitySailor1Text.ShipSetSailText)
;> elif (mem[wSpritePlayerStateData1FacingDirection] == SPRITE_FACING_RIGHT
;>       or not ArePlayerCoordsInArray(VermilionCitySailor1Text.inFrontOfOrBehindGuardCoords)):
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_RIGHT
	jr z, .greet_player
	ld hl, .inFrontOfOrBehindGuardCoords
	call ArePlayerCoordsInArray
	jr nc, .greet_player_and_check_ticket
.greet_player
;>     PrintText(VermilionCitySailor1Text.WelcomeToSSAnneText)
	ld hl, .WelcomeToSSAnneText
	call PrintText
	jr .end
.greet_player_and_check_ticket
;> else:
;>     PrintText(VermilionCitySailor1Text.DoYouHaveATicketText)
	ld hl, .DoYouHaveATicketText
	call PrintText
;>     count = predef(GetQuantityOfItemInBag, bc=S_S_TICKET << 8)     # the count comes back in b
	ld b, S_S_TICKET
	ld a, (GetQuantityOfItemInBagPredef - PredefPointers) / 3
	call Predef
;>     if count:
	ld a, b
	and a
	jr nz, .player_has_ticket
;>@flash         PrintText(VermilionCitySailor1Text.FlashedTicketText)
;>@pass         wVermilionCityCurScript = SCRIPT_VERMILIONCITY_PLAYER_ALLOWED_TO_PASS
;>     else:
;>         PrintText(VermilionCitySailor1Text.YouNeedATicketText)
	ld hl, .YouNeedATicketText
	call PrintText
	jr .end
.player_has_ticket
;=@flash
	ld hl, .FlashedTicketText
	call PrintText
;=@pass
	ld a, SCRIPT_VERMILIONCITY_PLAYER_ALLOWED_TO_PASS
	ld [wVermilionCityCurScript], a
	jr .end
.ship_departed
;=@sail
	ld hl, .ShipSetSailText
	call PrintText
.end
;> return TextScriptEnd()
	jp TextScriptEnd

.inFrontOfOrBehindGuardCoords
	; in front of guard
	db 29, 19
	; behind guard
	db 31, 19
	db -1 ; end

