	db TX_START_ASM
;> if event(EVENT_GOT_TM41):
	ld a, [wEventFlags + $30]
	bit (EVENT_GOT_TM41) % 8, a
	jr nz, .gotTM41
;>     PrintText(CeladonCityGramps3Text.TM41ExplanationText)
;> else:
;>     PrintText(CeladonCityGramps3Text.Text)
	ld hl, .Text
	call PrintText
;>     if GiveItem(TM_SOFTBOILED, 1):
	ld bc, ((TM_SOFTBOILED) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr c, .Success
	ld hl, .TM41NoRoomText
	call PrintText
	jr .Done
.Success
;>         PrintText(CeladonCityGramps3Text.ReceivedTM41Text)
	ld hl, .ReceivedTM41Text
	call PrintText
;>         set_event(EVENT_GOT_TM41)
	ld hl, wEventFlags + $30
	set (EVENT_GOT_TM41) % 8, [hl]
	jr .Done
.gotTM41
	ld hl, .TM41ExplanationText
	call PrintText
;>     else:
;>         PrintText(CeladonCityGramps3Text.TM41NoRoomText)
;> return TextScriptEnd()
.Done
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _CeladonCityGramps3Text
	db BANK(_CeladonCityGramps3Text)
	db TX_END

.ReceivedTM41Text:
	db TX_FAR
	dw _CeladonCityGramps3ReceivedTM41Text
	db BANK(_CeladonCityGramps3ReceivedTM41Text)
	db TX_SOUND_GET_ITEM_1
	db TX_END

.TM41ExplanationText:
