BluesHouse_h::
	db HOUSE
	db $4, $4
	dw BluesHouse_Blocks
	dw BluesHouse_TextPointers
	dw BluesHouse_Script
	db 0
	dw BluesHouse_Object
;@ path: scripts/BluesHouse
;@ def BluesHouse_Script()
;@ The rival's house map script: run the current step of the house's script.
BluesHouse_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wBluesHouseCurScript, BluesHouse_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld hl, BluesHouse_ScriptPointers
	ld a, [wBluesHouseCurScript]
	jp CallFunctionInTable

;@ path: scripts/BluesHouse
BluesHouse_ScriptPointers:
	dw BluesHouseDefaultScript
DEF SCRIPT_BLUESHOUSE_DEFAULT EQU 0
	dw BluesHouseNoopScript
DEF SCRIPT_BLUESHOUSE_NOOP EQU 1

;@ path: scripts/BluesHouse
;@ def BluesHouseDefaultScript()
;@ First visit: note that the player has been in the house, then switch to the step that does nothing.
BluesHouseDefaultScript:
;> set_event(EVENT_ENTERED_BLUES_HOUSE)
;> wBluesHouseCurScript = SCRIPT_BLUESHOUSE_NOOP
	ld hl, wEventFlags + $3
	set (EVENT_ENTERED_BLUES_HOUSE) % 8, [hl]
	ld a, SCRIPT_BLUESHOUSE_NOOP
	ld [wBluesHouseCurScript], a
	ret

;@ path: scripts/BluesHouse
;@ def BluesHouseNoopScript()
;@ The house's idle step: nothing happens.
BluesHouseNoopScript:
;> return
	ret

;@ path: scripts/BluesHouse
BluesHouse_TextPointers:
	dw BluesHouseDaisySittingText
DEF TEXT_BLUESHOUSE_DAISY_SITTING EQU 1
	dw BluesHouseDaisyWalkingText
DEF TEXT_BLUESHOUSE_DAISY_WALKING EQU 2
	dw BluesHouseTownMapText
DEF TEXT_BLUESHOUSE_TOWN_MAP EQU 3

;@ path: scripts/BluesHouse
;@ def BluesHouseDaisySittingText() -> hl
;@ Daisy at the table: before the Pokédex she says her brother is at the lab; after it she gives the
;@ Town Map (if the bag has room) and then explains how to use it.
;@ test: skip a text script: the code after text_asm is run by the text engine
BluesHouseDaisySittingText:
	db TX_START_ASM
;> if event(EVENT_GOT_TOWN_MAP):
	ld a, [wEventFlags + $3]
	bit (EVENT_GOT_TOWN_MAP) % 8, a
	jr nz, .got_town_map
;>     PrintText(BluesHouseDaisyUseMapText)
;> elif not event(EVENT_GOT_POKEDEX):
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEDEX) % 8, a
	jr nz, .give_town_map
;>     PrintText(BluesHouseDaisyRivalAtLabText)
	ld hl, BluesHouseDaisyRivalAtLabText
	call PrintText
	jr .done
;> else:

.give_town_map
;>     PrintText(BluesHouseDaisyOfferMapText)
	ld hl, BluesHouseDaisyOfferMapText
	call PrintText
;>     if GiveItem(TOWN_MAP, 1):
	ld bc, ((TOWN_MAP) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         wToggleableObjectIndex = TOGGLE_TOWN_MAP
	ld a, TOGGLE_TOWN_MAP
	ld [wToggleableObjectIndex], a
;>         HideObject()
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;>         PrintText(GotMapText)
	ld hl, GotMapText
	call PrintText
;>         set_event(EVENT_GOT_TOWN_MAP)
	ld hl, wEventFlags + $3
	set (EVENT_GOT_TOWN_MAP) % 8, [hl]
	jr .done

.got_town_map
	ld hl, BluesHouseDaisyUseMapText
	call PrintText
	jr .done

.bag_full
;>     else:
;>         PrintText(BluesHouseDaisyBagFullText)
	ld hl, BluesHouseDaisyBagFullText
	call PrintText
;> return TextScriptEnd()
.done
	jp TextScriptEnd

;@ path: scripts/BluesHouse
BluesHouseDaisyRivalAtLabText:
	db TX_FAR
	dw _BluesHouseDaisyRivalAtLabText
	db BANK(_BluesHouseDaisyRivalAtLabText)
	db TX_END

;@ path: scripts/BluesHouse
BluesHouseDaisyOfferMapText:
	db TX_FAR
	dw _BluesHouseDaisyOfferMapText
	db BANK(_BluesHouseDaisyOfferMapText)
	db TX_END

;@ path: scripts/BluesHouse
GotMapText:
	db TX_FAR
	dw _GotMapText
	db BANK(_GotMapText)
	db TX_SOUND_GET_KEY_ITEM
	db TX_END

;@ path: scripts/BluesHouse
BluesHouseDaisyBagFullText:
	db TX_FAR
	dw _BluesHouseDaisyBagFullText
	db BANK(_BluesHouseDaisyBagFullText)
	db TX_END

