	db TX_FAR
	dw _BluesHouseTownMapText
	db BANK(_BluesHouseTownMapText)
	db TX_END
DEF BLUESHOUSE_DAISY1 EQU 1
	EXPORT BLUESHOUSE_DAISY1
DEF BLUESHOUSE_DAISY2 EQU 2
	EXPORT BLUESHOUSE_DAISY2
DEF BLUESHOUSE_TOWN_MAP EQU 3
	EXPORT BLUESHOUSE_TOWN_MAP

;@ path: data/maps/objects/BluesHouse
BluesHouse_Object:
	db $a ; border block

	db 2
	db 7, 2, 2 - 1, LAST_MAP
	db 7, 3, 2 - 1, LAST_MAP

	db 0

	db 3
	db SPRITE_DAISY
	db 3 + 4
	db 2 + 4
	db STAY
	db RIGHT
	db TEXT_BLUESHOUSE_DAISY_SITTING
	db SPRITE_DAISY
	db 4 + 4
	db 6 + 4
	db WALK
	db UP_DOWN
	db ITEM | TEXT_BLUESHOUSE_DAISY_WALKING
	db 0
	db SPRITE_POKEDEX
	db 3 + 4
	db 3 + 4
	db STAY
	db NONE
	db ITEM | TEXT_BLUESHOUSE_TOWN_MAP
	db 0

	dw (wOverworldMap + 7 + (BLUES_HOUSE_WIDTH) + ((BLUES_HOUSE_WIDTH) + 6) * ((7) >> 1) + ((2) >> 1))
	db 7, 2
	dw (wOverworldMap + 7 + (BLUES_HOUSE_WIDTH) + ((BLUES_HOUSE_WIDTH) + 6) * ((7) >> 1) + ((3) >> 1))
	db 7, 3
;@ path: maps
BluesHouse_Blocks:
	db $04, $0e, $05, $09, $0f, $01, $02, $0f, $0f, $0c, $0d, $0f, $06, $0b, $0f, $07

