	dw IndigoPlateauLobby_Object
;@ path: scripts/IndigoPlateauLobby
;@ def IndigoPlateauLobby_Script()
;@ The Pokémon League lobby: when the map has just loaded, put the Victory Road boulder switch back, and
;@ if the player had started on the Elite Four, reset all their events so the challenge starts over.
IndigoPlateauLobby_Script:
;> Serial_TryEstablishingExternallyClockedConnection()
	call Serial_TryEstablishingExternallyClockedConnection
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if not loaded:
;>     return
	ret z
;> reset_event(EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH)
	ld hl, wEventFlags + $122
	res (EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH) % 8, [hl]
	; Reset Elite Four events if the player started challenging them before
;> started = wElite4Flags >> BIT_STARTED_ELITE_4 & 1
	ld hl, wElite4Flags
	bit BIT_STARTED_ELITE_4, [hl]
;> wElite4Flags &= ~(1 << BIT_STARTED_ELITE_4)
	res BIT_STARTED_ELITE_4, [hl]
;> if not started:
;>     return
	ret z
;> flags = wEventFlags + INDIGO_PLATEAU_EVENTS_START // 8     # the Elite Four's four bytes of event flags
	ld hl, wEventFlags + $11C
;> mem[flags:flags + 4] = [0] * 4      # resets INDIGO_PLATEAU_EVENTS_START .. EVENT_LANCES_ROOM_LOCK_DOOR
	xor a
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
	ret

