;@ path: scripts/SilphCo4F
;@ def SilphCo4F_Script()
;@ Silph Co. 4F's map script: on entering, redraw the card-key doors; then run the current step of the
;@ floor's script (its trainers).
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
SilphCo4F_Script:
;> SilphCo4FGateCallbackScript()
	call SilphCo4FGateCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSilphCo4FCurScript = ExecuteCurMapScriptInTable(wSilphCo4FCurScript, SilphCo4TrainerHeaders, SilphCo4F_ScriptPointers)
	ld hl, SilphCo4TrainerHeaders
	ld de, SilphCo4F_ScriptPointers
	ld a, [wSilphCo4FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSilphCo4FCurScript], a
	ret

;@ path: scripts/SilphCo4F
;@ def SilphCo4FGateCallbackScript()
;@ On entering the floor: if a card-key door here was just opened, note it, then draw every door still
;@ locked (block $54) into the map.
;@ test: skip the door list sits under a local label, which the pseudo-code can only name
SilphCo4FGateCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> SilphCo4F_SetCardKeyDoorYScript(SilphCo4FGateCallbackScript.GateCoordinates)
	ld hl, .GateCoordinates
	call SilphCo4F_SetCardKeyDoorYScript
;> SilphCo4FUnlockedDoorEventScript()
	call SilphCo4FUnlockedDoorEventScript
;> if not event(EVENT_SILPH_CO_4_UNLOCKED_DOOR1):
	ld a, [wEventFlags + $E3]
	bit (EVENT_SILPH_CO_4_UNLOCKED_DOOR1) % 8, a
	jr nz, .unlock_door1
;>     wNewTileBlockID = 0x54
	push af
	ld a, $54
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=6 << 8 | 2)
	ld bc, ((6) & $ff) << 8 + ((2) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	pop af
.unlock_door1
;> if not event(EVENT_SILPH_CO_4_UNLOCKED_DOOR2):
	bit (EVENT_SILPH_CO_4_UNLOCKED_DOOR2) % 8, a
	ret nz
;>     wNewTileBlockID = 0x54
	ld a, $54
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=4 << 8 | 6)
	ld bc, ((4) & $ff) << 8 + ((6) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

.GateCoordinates:
	db 6, 2
	db 4, 6
	db -1 ; end

;@ path: scripts/SilphCo4F
;@ def SilphCo4F_SetCardKeyDoorYScript(doors: hl)
;@ Look up the door the card key just opened (wCardKeyDoorY/X) in the floor's door list: hUnlockedSilphCoDoors
;@ becomes its number (1, 2...) and the opened door is forgotten; 0 if it is not one of them.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
SilphCo4F_SetCardKeyDoorYScript:
;> y = wCardKeyDoorY
	push hl
	ld hl, wCardKeyDoorY
	ld a, [hli]
	ld b, a
;> x = wCardKeyDoorX
	ld a, [hl]
	ld c, a
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
;> while mem[doors] != 0xFF:
	pop hl
.loop_check_doors
	ld a, [hli]
	cp $ff
	jr z, .exit_loop
;>     hUnlockedSilphCoDoors += 1
	push hl
	ld hl, hUnlockedSilphCoDoors
	inc [hl]
	pop hl
;>@match     if mem[doors] == y and mem[doors + 1] == x:
	cp b
	jr z, .check_y_coord
;>@clear         wCardKeyDoorY = wCardKeyDoorX = 0
;>@ret         return
;>     doors += 2
	inc hl
	jr .loop_check_doors
.check_y_coord
;=@match
	ld a, [hli]
	cp c
	jr nz, .loop_check_doors
;=@clear
	ld hl, wCardKeyDoorY
	xor a
	ld [hli], a
	ld [hl], a
;=@ret
	ret
.exit_loop
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
	ret

;@ path: scripts/SilphCo4F
;@ def SilphCo4FUnlockedDoorEventScript()
;@ Note the door the card key just opened (door 1 or 2 of this floor) as an event.
;@ test: hLoadedROMBank = 0x06    # the bank this code runs in
SilphCo4FUnlockedDoorEventScript:
;> if hUnlockedSilphCoDoors == 0:      # (hl: the byte holding both door flags)
;>     return
	ld hl, wEventFlags + $E3
	ldh a, [hUnlockedSilphCoDoors]
	and a
	ret z
;> if hUnlockedSilphCoDoors == 1:
	cp $1
	jr nz, .unlock_door1
;>     set_event(EVENT_SILPH_CO_4_UNLOCKED_DOOR1)
	set (EVENT_SILPH_CO_4_UNLOCKED_DOOR1) % 8, [hl]
	ret
.unlock_door1
;> else:
;>     set_event(EVENT_SILPH_CO_4_UNLOCKED_DOOR2)
	set (EVENT_SILPH_CO_4_UNLOCKED_DOOR2) % 8, [hl]
	ret

