SilphCo5F_h::
	db FACILITY
	db $9, $F
	dw SilphCo5F_Blocks
	dw SilphCo5F_TextPointers
	dw SilphCo5F_Script
	db 0
	dw SilphCo5F_Object
;@ path: scripts/SilphCo5F
;@ def SilphCo5F_Script()
;@ Silph Co. 5F's map script: on entering, redraw the card-key doors; then run the current step of the
;@ floor's script (its trainers).
;@ test: skip runs the floor's door callback, whose door list sits under a local label
SilphCo5F_Script:
;> SilphCo5FGateCallbackScript()
	call SilphCo5FGateCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSilphCo5FCurScript = ExecuteCurMapScriptInTable(wSilphCo5FCurScript, SilphCo5TrainerHeaders, SilphCo5F_ScriptPointers)
	ld hl, SilphCo5TrainerHeaders
	ld de, SilphCo5F_ScriptPointers
	ld a, [wSilphCo5FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSilphCo5FCurScript], a
	ret

;@ path: scripts/SilphCo5F
;@ def SilphCo5FGateCallbackScript()
;@ On entering the floor: if a card-key door here was just opened, note it, then draw each of the three doors
;@ still locked (block $5F) into the map.
;@ test: skip the door list sits under a local label, which the pseudo-code can only name
SilphCo5FGateCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> SilphCo4F_SetCardKeyDoorYScript(SilphCo5FGateCallbackScript.GateCoordinates)
	ld hl, .GateCoordinates
	call SilphCo4F_SetCardKeyDoorYScript
;> SilphCo5F_SetUnlockedSilphCoDoorsScript()
	call SilphCo5F_SetUnlockedSilphCoDoorsScript
;> if not event(EVENT_SILPH_CO_5_UNLOCKED_DOOR1):     # door 1 still locked
	ld a, [wEventFlags + $E5]
	bit (EVENT_SILPH_CO_5_UNLOCKED_DOOR1) % 8, a
	jr nz, .unlock_door1
;>     wNewTileBlockID = 0x5F
	push af
	ld a, $5f
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=2 << 8 | 3)        # at row 2, column 3
	ld bc, ((2) & $ff) << 8 + ((3) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	pop af
.unlock_door1
;> if not event(EVENT_SILPH_CO_5_UNLOCKED_DOOR2):
	bit (EVENT_SILPH_CO_5_UNLOCKED_DOOR2) % 8, a
	jr nz, .unlock_door2
;>     wNewTileBlockID = 0x5F
	push af
	ld a, $5f
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=6 << 8 | 3)
	ld bc, ((6) & $ff) << 8 + ((3) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	pop af
.unlock_door2
;> if event(EVENT_SILPH_CO_5_UNLOCKED_DOOR3):
;>     return
	bit (EVENT_SILPH_CO_5_UNLOCKED_DOOR3) % 8, a
	ret nz
;> wNewTileBlockID = 0x5F
	ld a, $5f
	ld [wNewTileBlockID], a
;> return predef(ReplaceTileBlock, bc=5 << 8 | 7)
	ld bc, ((5) & $ff) << 8 + ((7) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

.GateCoordinates:
	db 2, 3
	db 6, 3
	db 5, 7
	db -1 ; end

;@ path: scripts/SilphCo5F
;@ def SilphCo5F_SetUnlockedSilphCoDoorsScript()
;@ Note the door the card key just opened (door 1, 2 or 3 of this floor) as an event.
SilphCo5F_SetUnlockedSilphCoDoorsScript:
;> if hUnlockedSilphCoDoors == 1:
	ld hl, wEventFlags + $E5
	ldh a, [hUnlockedSilphCoDoors]
	and a
	ret z
	cp $1
	jr nz, .unlock_door1
;>     set_event(EVENT_SILPH_CO_5_UNLOCKED_DOOR1)
	set (EVENT_SILPH_CO_5_UNLOCKED_DOOR1) % 8, [hl]
	ret
.unlock_door1
;> elif hUnlockedSilphCoDoors == 2:
	cp $2
	jr nz, .unlock_door2
;>     set_event(EVENT_SILPH_CO_5_UNLOCKED_DOOR2)
	set (EVENT_SILPH_CO_5_UNLOCKED_DOOR2) % 8, [hl]
	ret
.unlock_door2
;> elif hUnlockedSilphCoDoors:
;>     set_event(EVENT_SILPH_CO_5_UNLOCKED_DOOR3)
	set (EVENT_SILPH_CO_5_UNLOCKED_DOOR3) % 8, [hl]
	ret

