;@ def SilphCo6F_Script()
;@ Silph Co. 6F's map script: on entering, redraw the card-key door; then run the current step of the
;@ floor's script (its trainers).
;@ test: skip runs the floor's door callback, whose door list sits under a local label
SilphCo6F_Script:
;> SilphCo6F_GateCallbackScript()
	call SilphCo6F_GateCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSilphCo6FCurScript = ExecuteCurMapScriptInTable(wSilphCo6FCurScript, SilphCo6TrainerHeaders, SilphCo6F_ScriptPointers)
	ld hl, SilphCo6TrainerHeaders
	ld de, SilphCo6F_ScriptPointers
	ld a, [wSilphCo6FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSilphCo6FCurScript], a
	ret

;@ path: scripts/SilphCo6F
;@ def SilphCo6F_GateCallbackScript()
;@ On entering the floor: if the card-key door here was just opened, note it; while it is locked, draw it
;@ (block $5F) into the map.
;@ test: skip the door list sits under a local label, which the pseudo-code can only name
SilphCo6F_GateCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> SilphCo4F_SetCardKeyDoorYScript(SilphCo6F_GateCallbackScript.GateCoordinates)
	ld hl, .GateCoordinates
	call SilphCo4F_SetCardKeyDoorYScript
;> SilphCo6F_UnlockedDoorEventScript()
	call SilphCo6F_UnlockedDoorEventScript
;> if not event(EVENT_SILPH_CO_6_UNLOCKED_DOOR):
	ld a, [wEventFlags + $E7]
	bit (EVENT_SILPH_CO_6_UNLOCKED_DOOR) % 8, a
	ret nz
;>     wNewTileBlockID = 0x5F
	ld a, $5f
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=6 << 8 | 2)
	ld bc, ((6) & $ff) << 8 + ((2) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

.GateCoordinates:
	db 6, 2
	db -1 ; end

;@ path: scripts/SilphCo6F
;@ def SilphCo6F_UnlockedDoorEventScript()
;@ If the card key just opened this floor's door, note it as an event.
SilphCo6F_UnlockedDoorEventScript:
;> if hUnlockedSilphCoDoors:
;>     set_event(EVENT_SILPH_CO_6_UNLOCKED_DOOR)
	ldh a, [hUnlockedSilphCoDoors]
	and a
	ret z
	ld hl, wEventFlags + $E7
	set (EVENT_SILPH_CO_6_UNLOCKED_DOOR) % 8, [hl]
	ret

