;@ path: scripts/SilphCo6F
SilphCo6TrainerHeaders:
;@ path: scripts/SilphCo6F
SilphCo6TrainerHeader0:
	db $6
	db 2 << 4
	dw wEventFlags + (EVENT_BEAT_SILPH_CO_6F_TRAINER_0 - $6) / 8
	dw SilphCo6FRocket1BattleText, SilphCo6FRocket1AfterBattleText, SilphCo6FRocket1EndBattleText, SilphCo6FRocket1EndBattleText
;@ path: scripts/SilphCo6F
SilphCo6TrainerHeader1:
	db $7
	db 3 << 4
	dw wEventFlags + (EVENT_BEAT_SILPH_CO_6F_TRAINER_1 - $7) / 8
	dw SilphCo6FScientistBattleText, SilphCo6FScientistAfterBattleText, SilphCo6FScientistEndBattleText, SilphCo6FScientistEndBattleText
;@ path: scripts/SilphCo6F
SilphCo6TrainerHeader2:
	db $8
	db 2 << 4
	dw wEventFlags + (EVENT_BEAT_SILPH_CO_6F_TRAINER_2 - $8) / 8
	dw SilphCo6FRocket2BattleText, SilphCo6FRocket2AfterBattleText, SilphCo6FRocket2EndBattleText, SilphCo6FRocket2EndBattleText
	db -1 ; end

;@ path: scripts/SilphCo6F
;@ def SilphCo6FBeatGiovanniPrintDEOrPrintHLScript(before: hl, after: de)
;@ Print one of two texts: `before` while Team Rocket holds Silph Co., `after` once Giovanni there is beaten.
;@ Shared by the Silph workers on several floors.
SilphCo6FBeatGiovanniPrintDEOrPrintHLScript:
;> text = before
;> if event(EVENT_BEAT_SILPH_CO_GIOVANNI):
	ld a, [wEventFlags + $F1]
	bit (EVENT_BEAT_SILPH_CO_GIOVANNI) % 8, a
	jr nz, .beat_giovanni
	jr .print_text
.beat_giovanni
;>     text = after
	ld h, d
	ld l, e
.print_text
;> PrintText(text)
	jp PrintText

;@ path: scripts/SilphCo6F
;@ def SilphCo6FSilphWorkerM1Text() -> hl
;@ A Silph worker on 6F: Team Rocket took over the building - later, back to work.
;@ test: skip a text script: the code after text_asm is run by the text engine
SilphCo6FSilphWorkerM1Text:
	db TX_START_ASM
;> SilphCo6FBeatGiovanniPrintDEOrPrintHLScript(SilphCo6FSilphWorkerM1Text.TookOverTheBuildingText, SilphCo6FSilphWorkerM1Text.BackToWorkText)
;> return TextScriptEnd()
	ld hl, .TookOverTheBuildingText
	ld de, .BackToWorkText
	call SilphCo6FBeatGiovanniPrintDEOrPrintHLScript
	jp TextScriptEnd

.TookOverTheBuildingText:
	db TX_FAR
	dw _SilphCo6FSilphWorkerM1TookOverTheBuildingText
	db BANK(_SilphCo6FSilphWorkerM1TookOverTheBuildingText)
	db TX_END

.BackToWorkText:
	db TX_FAR
	dw _SilphCo6FSilphWorkerM1BackToWorkText
	db BANK(_SilphCo6FSilphWorkerM1BackToWorkText)
	db TX_END

;@ path: scripts/SilphCo6F
;@ def SilphCo6FSilphWorkerM2Text() -> hl
;@ A Silph worker on 6F: help me please - later, he got engaged.
;@ test: skip a text script: the code after text_asm is run by the text engine
SilphCo6FSilphWorkerM2Text:
	db TX_START_ASM
;> SilphCo6FBeatGiovanniPrintDEOrPrintHLScript(SilphCo6FSilphWorkerM2Text.HelpMePleaseText, SilphCo6FSilphWorkerM2Text.WeGotEngagedText)
;> return TextScriptEnd()
	ld hl, .HelpMePleaseText
	ld de, .WeGotEngagedText
	call SilphCo6FBeatGiovanniPrintDEOrPrintHLScript
	jp TextScriptEnd

.HelpMePleaseText:
	db TX_FAR
	dw _SilphCo6FSilphWorkerMHelpMePleaseText
	db BANK(_SilphCo6FSilphWorkerMHelpMePleaseText)
	db TX_END

.WeGotEngagedText:
	db TX_FAR
	dw _SilphCo6FSilphWorkerMWeGotEngagedText
	db BANK(_SilphCo6FSilphWorkerMWeGotEngagedText)
	db TX_END

