SECTION "Maps 4", ROMX

;@ path: scripts/CinnabarIsland
;@ def CinnabarIsland_Script()
;@ Cinnabar Island's map script: turn the mansion's switch off and end the fossil revival in the lab
;@ whenever the player is on the island, then run the current step.
CinnabarIsland_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
;> reset_event(EVENT_MANSION_SWITCH_ON)
;> reset_event(EVENT_LAB_STILL_REVIVING_FOSSIL)
	ld hl, wEventFlags + $4F
	res (EVENT_MANSION_SWITCH_ON) % 8, [hl]
	ld hl, wEventFlags + $5C
	res (EVENT_LAB_STILL_REVIVING_FOSSIL) % 8, [hl]
;> CallFunctionInTable(wCinnabarIslandCurScript, CinnabarIsland_ScriptPointers)
	ld hl, CinnabarIsland_ScriptPointers
	ld a, [wCinnabarIslandCurScript]
	jp CallFunctionInTable

;@ path: scripts/CinnabarIsland
CinnabarIsland_ScriptPointers:
	dw CinnabarIslandDefaultScript
DEF SCRIPT_CINNABARISLAND_DEFAULT EQU 0
	dw CinnabarIslandPlayerMovingScript
DEF SCRIPT_CINNABARISLAND_PLAYER_MOVING EQU 1

;@ path: scripts/CinnabarIsland
;@ def CinnabarIslandDefaultScript()
;@ Standing in front of the Gym door without the Secret Key: "the door is locked", then the player is
;@ made to step back down.
;@ test: skip IsItemInBag calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
CinnabarIslandDefaultScript:
;> if not IsItemInBag(SECRET_KEY):            # zero flag clear: the key is in the bag
	ld b, SECRET_KEY
	call IsItemInBag
;>     return
	ret nz
;> if wYCoord != 4 or wXCoord != 18:
	ld a, [wYCoord]
	cp 4
	ret nz
	ld a, [wXCoord]
	cp 18
;>     return
	ret nz
;> wPlayerMovingDirection = PLAYER_DIR_UP
	ld a, PLAYER_DIR_UP
	ld [wPlayerMovingDirection], a
;> hTextID = TEXT_CINNABARISLAND_DOOR_IS_LOCKED
	ld a, TEXT_CINNABARISLAND_DOOR_IS_LOCKED
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> wSimulatedJoypadStatesEnd = PAD_DOWN
	ld a, PAD_DOWN
	ld [wSimulatedJoypadStatesEnd], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wSpritePlayerStateData1FacingDirection = 0
	xor a
	ld [wSpritePlayerStateData1FacingDirection], a
;> wJoyIgnore = 0
	ld [wJoyIgnore], a
;> wCinnabarIslandCurScript = SCRIPT_CINNABARISLAND_PLAYER_MOVING
	ld a, SCRIPT_CINNABARISLAND_PLAYER_MOVING
	ld [wCinnabarIslandCurScript], a
	ret

;@ path: scripts/CinnabarIsland
;@ def CinnabarIslandPlayerMovingScript()
;@ Wait until the step back is done, then return to the default step.
CinnabarIslandPlayerMovingScript:
;> if wSimulatedJoypadStatesIndex:     # still walking
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> Delay3()
	call Delay3
;> wCinnabarIslandCurScript = SCRIPT_CINNABARISLAND_DEFAULT
	ld a, SCRIPT_CINNABARISLAND_DEFAULT
	ld [wCinnabarIslandCurScript], a
	ret

;@ path: scripts/CinnabarIsland
CinnabarIsland_TextPointers:
	dw CinnabarIslandGirlText
DEF TEXT_CINNABARISLAND_GIRL EQU 1
	dw CinnabarIslandGamblerText
DEF TEXT_CINNABARISLAND_GAMBLER EQU 2
	dw CinnabarIslandSignText
DEF TEXT_CINNABARISLAND_SIGN EQU 3
	dw MartSignText
DEF TEXT_CINNABARISLAND_MART_SIGN EQU 4
	dw PokeCenterSignText
DEF TEXT_CINNABARISLAND_POKECENTER_SIGN EQU 5
	dw CinnabarIslandPokemonLabSignText
DEF TEXT_CINNABARISLAND_POKEMONLAB_SIGN EQU 6
	dw CinnabarIslandGymSignText
DEF TEXT_CINNABARISLAND_GYM_SIGN EQU 7
	dw CinnabarIslandDoorIsLockedText
DEF TEXT_CINNABARISLAND_DOOR_IS_LOCKED EQU 8

;@ path: scripts/CinnabarIsland
CinnabarIslandDoorIsLockedText:
	db TX_FAR
	dw _CinnabarIslandDoorIsLockedText
	db BANK(_CinnabarIslandDoorIsLockedText)
	db TX_END

;@ path: scripts/CinnabarIsland
CinnabarIslandGirlText:
	db TX_FAR
