	dw _CinnabarIslandSignText
	db BANK(_CinnabarIslandSignText)
	db TX_END

;@ path: scripts/CinnabarIsland
CinnabarIslandPokemonLabSignText:
	db TX_FAR
	dw _CinnabarIslandPokemonLabSignText
	db BANK(_CinnabarIslandPokemonLabSignText)
	db TX_END

;@ path: scripts/CinnabarIsland
CinnabarIslandGymSignText:
	db TX_FAR
