;@ path: scripts/Route1
;@ def Route1_Script()
;@ Route 1's map script: only lets texts draw their box.
Route1_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/Route1
Route1_TextPointers:
	dw Route1Youngster1Text
DEF TEXT_ROUTE1_YOUNGSTER1 EQU 1
	dw Route1Youngster2Text
DEF TEXT_ROUTE1_YOUNGSTER2 EQU 2
	dw Route1SignText
DEF TEXT_ROUTE1_SIGN EQU 3

;@ path: scripts/Route1
;@ def Route1Youngster1Text() -> hl
;@ The Poké Mart clerk handing out samples: a free Potion the first time (the offer is used up even when the
;@ bag is full), afterwards a word about Poké Balls.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route1Youngster1Text:
	db TX_START_ASM
;> got = event(EVENT_GOT_POTION_SAMPLE)
	ld hl, wEventFlags + $78
	bit (EVENT_GOT_POTION_SAMPLE) % 8, [hl]
;> set_event(EVENT_GOT_POTION_SAMPLE)
	set (EVENT_GOT_POTION_SAMPLE) % 8, [hl]
;> if got:
	jr nz, .got_item
;>@also     text = Route1Youngster1Text.AlsoGotPokeballsText
;> else:
;>     PrintText(Route1Youngster1Text.MartSampleText)
	ld hl, .MartSampleText
	call PrintText
;>     if GiveItem(POTION, 1):
	ld bc, ((POTION) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         text = Route1Youngster1Text.GotPotionText
	ld hl, .GotPotionText
	jr .done
.bag_full
;>     else:
;>         text = Route1Youngster1Text.NoRoomText
	ld hl, .NoRoomText
	jr .done
.got_item
;=@also
	ld hl, .AlsoGotPokeballsText
.done
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.MartSampleText:
	db TX_FAR
	dw _Route1Youngster1MartSampleText
	db BANK(_Route1Youngster1MartSampleText)
	db TX_END

.GotPotionText:
	db TX_FAR
	dw _Route1Youngster1GotPotionText
	db BANK(_Route1Youngster1GotPotionText)
	db TX_SOUND_GET_ITEM_1
	db TX_END

.AlsoGotPokeballsText:
	db TX_FAR
	dw _Route1Youngster1AlsoGotPokeballsText
	db BANK(_Route1Youngster1AlsoGotPokeballsText)
	db TX_END

.NoRoomText:
	db TX_FAR
	dw _Route1Youngster1NoRoomText
	db BANK(_Route1Youngster1NoRoomText)
	db TX_END

;@ path: scripts/Route1
Route1Youngster2Text:
	db TX_FAR
	dw _Route1Youngster2Text
	db BANK(_Route1Youngster2Text)
	db TX_END

;@ path: scripts/Route1
Route1SignText:
	db TX_FAR
	dw _Route1SignText
	db BANK(_Route1SignText)
	db TX_END

OaksLab_h::
	db DOJO
	db $6, $5
	dw OaksLab_Blocks
	dw OaksLab_TextPointers
	dw OaksLab_Script
	db 0
	dw OaksLab_Object
;@ path: scripts/OaksLab
;@ def OaksLab_Script()
;@ Oak's lab map script: after the Poké Balls from Oak, switch to the lab's later set of texts; the lab draws
;@ its own text boxes. Then run the current step of the lab's script (choosing a starter, the first rival
;@ battle, the Pokédex).
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLab_Script:
;> if event(EVENT_PALLET_AFTER_GETTING_POKEBALLS_2):
;>     OaksLabLoadTextPointers2Script()
	ld a, [wEventFlags + $4]
	bit (EVENT_PALLET_AFTER_GETTING_POKEBALLS_2) % 8, a
	call nz, OaksLabLoadTextPointers2Script
;> wAutoTextBoxDrawingControl = 1 << BIT_NO_AUTO_TEXT_BOX
;> wDoNotWaitForButtonPressAfterDisplayingText = 0
	ld a, 1 << BIT_NO_AUTO_TEXT_BOX
	ld [wAutoTextBoxDrawingControl], a
	xor a
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> CallFunctionInTable(wOaksLabCurScript, OaksLab_ScriptPointers)
	ld hl, OaksLab_ScriptPointers
	ld a, [wOaksLabCurScript]
	jp CallFunctionInTable

;@ path: scripts/OaksLab
OaksLab_ScriptPointers:
	dw OaksLabDefaultScript
DEF SCRIPT_OAKSLAB_DEFAULT EQU 0
	dw OaksLabOakEntersLabScript
DEF SCRIPT_OAKSLAB_OAK_ENTERS_LAB EQU 1
	dw OaksLabToggleOaksScript
DEF SCRIPT_OAKSLAB_TOGGLE_OAKS EQU 2
	dw OaksLabPlayerEntersLabScript
DEF SCRIPT_OAKSLAB_PLAYER_ENTERS_LAB EQU 3
	dw OaksLabFollowedOakScript
DEF SCRIPT_OAKSLAB_FOLLOWED_OAK EQU 4
	dw OaksLabOakChooseMonSpeechScript
DEF SCRIPT_OAKSLAB_OAK_CHOOSE_MON_SPEECH EQU 5
	dw OaksLabPlayerDontGoAwayScript
DEF SCRIPT_OAKSLAB_PLAYER_DONT_GO_AWAY_SCRIPT EQU 6
	dw OaksLabPlayerForcedToWalkBackScript
DEF SCRIPT_OAKSLAB_PLAYER_FORCED_TO_WALK_BACK_SCRIPT EQU 7
	dw OaksLabChoseStarterScript
DEF SCRIPT_OAKSLAB_CHOSE_STARTER_SCRIPT EQU 8
	dw OaksLabRivalChoosesStarterScript
DEF SCRIPT_OAKSLAB_RIVAL_CHOOSES_STARTER EQU 9
	dw OaksLabRivalChallengesPlayerScript
DEF SCRIPT_OAKSLAB_RIVAL_CHALLENGES_PLAYER EQU $A
	dw OaksLabRivalStartBattleScript
DEF SCRIPT_OAKSLAB_RIVAL_START_BATTLE EQU $B
	dw OaksLabRivalEndBattleScript
DEF SCRIPT_OAKSLAB_RIVAL_END_BATTLE EQU $C
	dw OaksLabRivalStartsExitScript
DEF SCRIPT_OAKSLAB_RIVAL_STARTS_EXIT EQU $D
	dw OaksLabPlayerWatchRivalExitScript
DEF SCRIPT_OAKSLAB_PLAYER_WATCH_RIVAL_EXIT EQU $E
	dw OaksLabRivalArrivesAtOaksRequestScript
DEF SCRIPT_OAKSLAB_RIVAL_ARRIVES_AT_OAKS_REQUEST EQU $F
	dw OaksLabOakGivesPokedexScript
DEF SCRIPT_OAKSLAB_OAK_GIVES_POKEDEX EQU $10
	dw OaksLabRivalLeavesWithPokedexScript
DEF SCRIPT_OAKSLAB_RIVAL_LEAVES_WITH_POKEDEX EQU $11
	dw OaksLabNoopScript
DEF SCRIPT_OAKSLAB_NOOP EQU $12

;@ path: scripts/OaksLab
;@ def OaksLabDefaultScript()
;@ Once Oak has met the player in town and the walk to the lab is over: Oak appears at the door and battles
;@ are allowed again.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabDefaultScript:
;> if not event(EVENT_OAK_APPEARED_IN_PALLET) or wNPCMovementScriptFunctionNum:
;>     return
	ld a, [wEventFlags + $4]
	bit (EVENT_OAK_APPEARED_IN_PALLET) % 8, a
	ret z
	ld a, [wNPCMovementScriptFunctionNum]
	and a
	ret nz
;> wToggleableObjectIndex = TOGGLE_OAKS_LAB_OAK_2
	ld a, TOGGLE_OAKS_LAB_OAK_2
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> wStatusFlags4 &= ~(1 << BIT_NO_BATTLES)
	ld hl, wStatusFlags4
	res BIT_NO_BATTLES, [hl]

;> wOaksLabCurScript = SCRIPT_OAKSLAB_OAK_ENTERS_LAB
	ld a, SCRIPT_OAKSLAB_OAK_ENTERS_LAB
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabOakEntersLabScript()
;@ Oak walks from the door up to his desk.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabOakEntersLabScript:
;> hSpriteIndex = OAKSLAB_OAK2
	ld a, OAKSLAB_OAK2
	ldh [hSpriteIndex], a
;> MoveSprite(OakEntryMovement)
	ld de, OakEntryMovement
	call MoveSprite

;> wOaksLabCurScript = SCRIPT_OAKSLAB_TOGGLE_OAKS
	ld a, SCRIPT_OAKSLAB_TOGGLE_OAKS
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
OakEntryMovement:
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db -1 ; end

;@ path: scripts/OaksLab
;@ def OaksLabToggleOaksScript()
;@ When Oak has reached his desk, swap the walking Oak for the one standing at the desk.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabToggleOaksScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> wToggleableObjectIndex = TOGGLE_OAKS_LAB_OAK_2
	ld a, TOGGLE_OAKS_LAB_OAK_2
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_OAKS_LAB_OAK_1
	ld a, TOGGLE_OAKS_LAB_OAK_1
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef

;> wOaksLabCurScript = SCRIPT_OAKSLAB_PLAYER_ENTERS_LAB
	ld a, SCRIPT_OAKSLAB_PLAYER_ENTERS_LAB
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabPlayerEntersLabScript()
;@ The player walks in after Oak (simulated input from PlayerEntryMovementRLE); the rival and Oak face down
;@ towards him.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabPlayerEntersLabScript:
;> Delay3()
	call Delay3
;> wSimulatedJoypadStatesIndex = (DecodeRLEList(addr(wSimulatedJoypadStatesEnd), PlayerEntryMovementRLE) - 1) & 0xFF
	ld hl, wSimulatedJoypadStatesEnd
	ld de, PlayerEntryMovementRLE
	call DecodeRLEList
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_DOWN
	xor a
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hSpriteIndex = OAKSLAB_OAK1
	ld a, OAKSLAB_OAK1
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_DOWN
	xor a
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay

;> wOaksLabCurScript = SCRIPT_OAKSLAB_FOLLOWED_OAK
	ld a, SCRIPT_OAKSLAB_FOLLOWED_OAK
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
PlayerEntryMovementRLE:
	db PAD_UP, 8
	db -1 ; end

;@ path: scripts/OaksLab
;@ def OaksLabFollowedOakScript()
;@ When the player has walked up to Oak: note it, turn the rival to Oak and bring back the lab's music.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabFollowedOakScript:
;> if wSimulatedJoypadStatesIndex:
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> set_event(EVENT_FOLLOWED_OAK_INTO_LAB)
	ld hl, wEventFlags + $0
	set (EVENT_FOLLOWED_OAK_INTO_LAB) % 8, [hl]
;> set_event(EVENT_FOLLOWED_OAK_INTO_LAB_2)
	ld hl, wEventFlags + $4
	set (EVENT_FOLLOWED_OAK_INTO_LAB_2) % 8, [hl]
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> UpdateSprites()
	call UpdateSprites
;> wStatusFlags7 &= ~(1 << BIT_NO_MAP_MUSIC)
	ld hl, wStatusFlags7
	res BIT_NO_MAP_MUSIC, [hl]
;> PlayDefaultMusic()
	call PlayDefaultMusic

;> wOaksLabCurScript = SCRIPT_OAKSLAB_OAK_CHOOSE_MON_SPEECH
	ld a, SCRIPT_OAKSLAB_OAK_CHOOSE_MON_SPEECH
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabOakChooseMonSpeechScript()
;@ The scene before choosing: the rival is fed up with waiting, Oak tells the player to choose a Pokémon,
;@ the rival asks "What about me?" and Oak tells him to be patient.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabOakChooseMonSpeechScript:
;> wJoyIgnore = PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld a, PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hTextID = TEXT_OAKSLAB_RIVAL_FED_UP_WITH_WAITING
	ld a, TEXT_OAKSLAB_RIVAL_FED_UP_WITH_WAITING
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> Delay3()
	call Delay3
;> hTextID = TEXT_OAKSLAB_OAK_CHOOSE_MON
	ld a, TEXT_OAKSLAB_OAK_CHOOSE_MON
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> Delay3()
	call Delay3
;> hTextID = TEXT_OAKSLAB_RIVAL_WHAT_ABOUT_ME
	ld a, TEXT_OAKSLAB_RIVAL_WHAT_ABOUT_ME
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> Delay3()
	call Delay3
;> hTextID = TEXT_OAKSLAB_OAK_BE_PATIENT
	ld a, TEXT_OAKSLAB_OAK_BE_PATIENT
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_OAK_ASKED_TO_CHOOSE_MON)
	ld hl, wEventFlags + $4
	set (EVENT_OAK_ASKED_TO_CHOOSE_MON) % 8, [hl]
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a

;> wOaksLabCurScript = SCRIPT_OAKSLAB_PLAYER_DONT_GO_AWAY_SCRIPT
	ld a, SCRIPT_OAKSLAB_PLAYER_DONT_GO_AWAY_SCRIPT
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabPlayerDontGoAwayScript()
;@ Trying to leave before choosing a Pokémon (row 6): Oak and the rival face the player, Oak says "Don't go
;@ away yet!" and the player walks one step back up.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabPlayerDontGoAwayScript:
;> if wYCoord != 6:
;>     return
	ld a, [wYCoord]
	cp 6
	ret nz
;> hSpriteIndex = OAKSLAB_OAK1                     # Oak faces down, to the player
	ld a, OAKSLAB_OAK1
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hSpriteIndex = OAKSLAB_RIVAL                    # and so does the rival
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> UpdateSprites()
	call UpdateSprites
;> hTextID = TEXT_OAKSLAB_OAK_DONT_GO_AWAY_YET
	ld a, TEXT_OAKSLAB_OAK_DONT_GO_AWAY_YET
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> wSimulatedJoypadStatesEnd = PAD_UP
	ld a, PAD_UP
	ld [wSimulatedJoypadStatesEnd], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wPlayerMovingDirection = PLAYER_DIR_UP
	ld a, PLAYER_DIR_UP
	ld [wPlayerMovingDirection], a

;> wOaksLabCurScript = SCRIPT_OAKSLAB_PLAYER_FORCED_TO_WALK_BACK_SCRIPT
	ld a, SCRIPT_OAKSLAB_PLAYER_FORCED_TO_WALK_BACK_SCRIPT
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabPlayerForcedToWalkBackScript()
;@ Once the step back is walked, go back to watching for the player trying to leave.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabPlayerForcedToWalkBackScript:
;> if wSimulatedJoypadStatesIndex:     # still walking
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> Delay3()
	call Delay3

;> wOaksLabCurScript = SCRIPT_OAKSLAB_PLAYER_DONT_GO_AWAY_SCRIPT
	ld a, SCRIPT_OAKSLAB_PLAYER_DONT_GO_AWAY_SCRIPT
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabChoseStarterScript()
;@ After the player's choice the rival walks to the ball he wants (the one stronger against the player's
;@ Pokémon), taking a shorter or longer path depending on where the player stands at the table.
;@ test: skip the walking paths sit under local labels, which the pseudo-code can only name
OaksLabChoseStarterScript:
;> if wPlayerStarter == STARTER1:                # rival takes the middle ball
	ld a, [wPlayerStarter]
	cp STARTER1
	jr z, .Charmander
	cp STARTER2
	jr z, .Squirtle
	jr .Bulbasaur
.Charmander
;>     moves = OaksLabChoseStarterScript.MiddleBallMovement1 if wYCoord == 4 else OaksLabChoseStarterScript.MiddleBallMovement2
	ld de, .MiddleBallMovement1
	ld a, [wYCoord]
	cp 4 ; is the player standing below the table?
	jr z, .moveBlue
	ld de, .MiddleBallMovement2
	jr .moveBlue

.MiddleBallMovement1
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_UP
	db -1 ; end

.MiddleBallMovement2
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db -1 ; end

.Squirtle
;> elif wPlayerStarter == STARTER2:              # rival takes the right ball
;>     moves = OaksLabChoseStarterScript.RightBallMovement1 if wYCoord == 4 else OaksLabChoseStarterScript.RightBallMovement2
	ld de, .RightBallMovement1
	ld a, [wYCoord]
	cp 4 ; is the player standing below the table?
	jr z, .moveBlue
	ld de, .RightBallMovement2
	jr .moveBlue

.RightBallMovement1
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_UP
	db -1 ; end

.RightBallMovement2
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db -1 ; end

.Bulbasaur
;> else:                                         # rival takes the left ball
;>     moves = OaksLabChoseStarterScript.LeftBallMovement1
	ld de, .LeftBallMovement1
;>     if wXCoord == 9:                          # player right of the table: the rival is off screen
	ld a, [wXCoord]
	cp 9 ; is the player standing to the right of the table?
	jr nz, .moveBlue
;>         hSpriteIndex = OAKSLAB_RIVAL
	push hl
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;>         hSpriteDataOffset = SPRITESTATEDATA1_YPIXELS
	ld a, SPRITESTATEDATA1_YPIXELS
	ldh [hSpriteDataOffset], a
;>         p = GetPointerWithinSpriteStateData1()
	call GetPointerWithinSpriteStateData1
;>         mem[p] = 0x4C                         # y pixels
	push hl
	ld [hl], $4c ; SPRITESTATEDATA1_YPIXELS
;>         mem[p + 2] = 0                        # x pixels
	inc hl
	inc hl
	ld [hl], $0 ; SPRITESTATEDATA1_XPIXELS
;>         mem[p + 0x100] = 8                    # map y (state data 2)
	pop hl
	inc h
	ld [hl], 8 ; SPRITESTATEDATA2_MAPY
;>         mem[p + 0x101] = 9                    # map x
	inc hl
	ld [hl], 9 ; SPRITESTATEDATA2_MAPX
;>         moves = OaksLabChoseStarterScript.LeftBallMovement2
	ld de, .LeftBallMovement2 ; the rival is not currently onscreen, so account for that
	pop hl
	jr .moveBlue

.LeftBallMovement1
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_RIGHT
.LeftBallMovement2
	db NPC_MOVEMENT_RIGHT
	db -1 ; end

.moveBlue
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> MoveSprite(moves)
	call MoveSprite

;> wOaksLabCurScript = SCRIPT_OAKSLAB_RIVAL_CHOOSES_STARTER
	ld a, SCRIPT_OAKSLAB_RIVAL_CHOOSES_STARTER
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabRivalChoosesStarterScript()
;@ When the rival reaches his ball: "I'll take this one!", the ball disappears, and he receives his Pokémon.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabRivalChoosesStarterScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> wJoyIgnore = PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld a, PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hTextID = TEXT_OAKSLAB_RIVAL_ILL_TAKE_THIS_ONE
	ld a, TEXT_OAKSLAB_RIVAL_ILL_TAKE_THIS_ONE
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> ball = wRivalStarterBallSpriteIndex
	ld a, [wRivalStarterBallSpriteIndex]
;> if ball == OAKSLAB_CHARMANDER_POKE_BALL:
	cp OAKSLAB_CHARMANDER_POKE_BALL
	jr nz, .not_charmander
;>     wToggleableObjectIndex = TOGGLE_STARTER_BALL_1
	ld a, TOGGLE_STARTER_BALL_1
	jr .hideBallAndContinue
.not_charmander
;> elif ball == OAKSLAB_SQUIRTLE_POKE_BALL:
	cp OAKSLAB_SQUIRTLE_POKE_BALL
	jr nz, .not_squirtle
;>     wToggleableObjectIndex = TOGGLE_STARTER_BALL_2
	ld a, TOGGLE_STARTER_BALL_2
	jr .hideBallAndContinue
.not_squirtle
;> else:
;>     wToggleableObjectIndex = TOGGLE_STARTER_BALL_3
	ld a, TOGGLE_STARTER_BALL_3
.hideBallAndContinue
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> Delay3()
	call Delay3
;> wRivalStarter = wCurPartySpecies = wNamedObjectIndex = wRivalStarterTemp
	ld a, [wRivalStarterTemp]
	ld [wRivalStarter], a
	ld [wCurPartySpecies], a
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hTextID = TEXT_OAKSLAB_RIVAL_RECEIVED_MON
	ld a, TEXT_OAKSLAB_RIVAL_RECEIVED_MON
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_GOT_STARTER)
	ld hl, wEventFlags + $4
	set (EVENT_GOT_STARTER) % 8, [hl]
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a

;> wOaksLabCurScript = SCRIPT_OAKSLAB_RIVAL_CHALLENGES_PLAYER
	ld a, SCRIPT_OAKSLAB_RIVAL_CHALLENGES_PLAYER
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabRivalChallengesPlayerScript()
;@ When the player heads for the exit (row 6): the rival's music, "I'll take you on!", and he walks up to the
;@ player (stopping one step short).
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabRivalChallengesPlayerScript:
;> if wYCoord != 6:
;>     return
	ld a, [wYCoord]
	cp 6
	ret nz
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> wPlayerMovingDirection = PLAYER_DIR_UP
	ld a, PLAYER_DIR_UP
	ld [wPlayerMovingDirection], a
;> PlayMusic(MUSIC_MEET_RIVAL, BANK(Music_MeetRival))
	ld c, BANK(Music_MeetRival)
	ld a, MUSIC_MEET_RIVAL
	call PlayMusic
;> hTextID = TEXT_OAKSLAB_RIVAL_ILL_TAKE_YOU_ON
	ld a, TEXT_OAKSLAB_RIVAL_ILL_TAKE_YOU_ON
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hNPCPlayerRelativePosPerspective = 1
	ld a, $1
	ldh [hNPCPlayerRelativePosPerspective], a
;> hNPCSpriteOffset = 1 << 4                    # the rival is sprite 1
	ld a, $1
	swap a
	ldh [hNPCSpriteOffset], a
;> predef(CalcPositionOfPlayerRelativeToNPC)
	ld a, (CalcPositionOfPlayerRelativeToNPCPredef - PredefPointers) / 3
	call Predef
;> hNPCPlayerYDistance = (hNPCPlayerYDistance - 1) & 0xFF
	ldh a, [hNPCPlayerYDistance]
	dec a
	ldh [hNPCPlayerYDistance], a
;> predef(FindPathToPlayer)
	ld a, (FindPathToPlayerPredef - PredefPointers) / 3
	call Predef
;> hSpriteIndex = OAKSLAB_RIVAL
	ld de, wNPCMovementDirections2
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> MoveSprite(addr(wNPCMovementDirections2))
	call MoveSprite

;> wOaksLabCurScript = SCRIPT_OAKSLAB_RIVAL_START_BATTLE
	ld a, SCRIPT_OAKSLAB_RIVAL_START_BATTLE
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabRivalStartBattleScript()
;@ When the rival has reached the player: set up the first rival battle, his team chosen by his starter.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabRivalStartBattleScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz

;> wCurOpponent = OPP_RIVAL1
	; define which team rival uses, and fight it
	ld a, OPP_RIVAL1
	ld [wCurOpponent], a
;> if wRivalStarter == STARTER2:
	ld a, [wRivalStarter]
	cp STARTER2
	jr nz, .not_squirtle
;>     wTrainerNo = 1
	ld a, $1
	jr .done
.not_squirtle
;> elif wRivalStarter == STARTER3:
	cp STARTER3
	jr nz, .not_bulbasaur
;>     wTrainerNo = 2
	ld a, $2
	jr .done
.not_bulbasaur
;> else:
;>     wTrainerNo = 3
	ld a, $3
.done
	ld [wTrainerNo], a
;> wSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ld [wSpriteIndex], a
;> GetSpritePosition1()
	call GetSpritePosition1
;> SaveEndBattleTextPointers(OaksLabRivalIPickedTheWrongPokemonText, OaksLabRivalAmIGreatOrWhatText)
	ld hl, OaksLabRivalIPickedTheWrongPokemonText
	ld de, OaksLabRivalAmIGreatOrWhatText
	call SaveEndBattleTextPointers
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wPlayerMovingDirection = PLAYER_DIR_UP
	ld a, PLAYER_DIR_UP
	ld [wPlayerMovingDirection], a
;> wOaksLabCurScript = SCRIPT_OAKSLAB_RIVAL_END_BATTLE
	ld a, SCRIPT_OAKSLAB_RIVAL_END_BATTLE
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabRivalEndBattleScript()
;@ After the first rival battle (won or lost): put the rival back in place, heal the party and note the
;@ battle.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabRivalEndBattleScript:
