	call UpdateSprites
;> wSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ld [wSpriteIndex], a
;> SetSpritePosition1()
	call SetSpritePosition1
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> predef(HealParty)
	ld a, (HealPartyPredef - PredefPointers) / 3
	call Predef
;> set_event(EVENT_BATTLED_RIVAL_IN_OAKS_LAB)
	ld hl, wEventFlags + $4
	set (EVENT_BATTLED_RIVAL_IN_OAKS_LAB) % 8, [hl]

;> wOaksLabCurScript = SCRIPT_OAKSLAB_RIVAL_STARTS_EXIT
	ld a, SCRIPT_OAKSLAB_RIVAL_STARTS_EXIT
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabRivalStartsExitScript()
;@ "Smell you later!": the rival's tune, and he steps aside (right or left, around the player) and walks out.
;@ test: skip the walking path sits under a local label, which the pseudo-code can only name
OaksLabRivalStartsExitScript:
;> DelayFrames(20)
	ld c, 20
	call DelayFrames
;> hTextID = TEXT_OAKSLAB_RIVAL_SMELL_YOU_LATER
	ld a, TEXT_OAKSLAB_RIVAL_SMELL_YOU_LATER
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> farcall(Music_RivalAlternateStart)
	ld b, BANK(Music_RivalAlternateStart)
	ld hl, Music_RivalAlternateStart
	call Bankswitch
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> MoveSprite(OaksLabRivalStartsExitScript.RivalExitMovement)
	ld de, .RivalExitMovement
	call MoveSprite
;> if wXCoord == 4:                    # his first step goes around the player
	ld a, [wXCoord]
	cp 4
	; move left or right depending on where the player is standing
	jr nz, .moveLeft
;>     step = NPC_MOVEMENT_RIGHT
	ld a, NPC_MOVEMENT_RIGHT
	jr .next
.moveLeft
;> else:
;>     step = NPC_MOVEMENT_LEFT
	ld a, NPC_MOVEMENT_LEFT
.next
;> mem[addr(wNPCMovementDirections)] = step
	ld [wNPCMovementDirections], a

;> wOaksLabCurScript = SCRIPT_OAKSLAB_PLAYER_WATCH_RIVAL_EXIT
	ld a, SCRIPT_OAKSLAB_PLAYER_WATCH_RIVAL_EXIT
	ld [wOaksLabCurScript], a
	ret

.RivalExitMovement
	db NPC_CHANGE_FACING
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db -1 ; end

;@ path: scripts/OaksLab
;@ def OaksLabPlayerWatchRivalExitScript()
;@ While the rival walks out the player turns to follow him; once he is gone, hide him and give back the
;@ controls and the map music.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabPlayerWatchRivalExitScript:
;> if not wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:     # he is out
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	jr nz, .checkRivalPosition
;>     wToggleableObjectIndex = TOGGLE_OAKS_LAB_RIVAL
	ld a, TOGGLE_OAKS_LAB_RIVAL
	ld [wToggleableObjectIndex], a
;>     predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;>     wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;>     PlayDefaultMusic()
	call PlayDefaultMusic ; reset to map music
;>     wOaksLabCurScript = SCRIPT_OAKSLAB_NOOP
	ld a, SCRIPT_OAKSLAB_NOOP
	ld [wOaksLabCurScript], a
	jr .done
; make the player keep facing the rival as he walks away
.checkRivalPosition
;> elif wNPCNumScriptedSteps == 5:
	ld a, [wNPCNumScriptedSteps]
	cp $5
	jr nz, .turnPlayerDown
;>     if wXCoord == 4:
	ld a, [wXCoord]
	cp 4
	jr nz, .turnPlayerLeft
;>         mem[wSpritePlayerStateData1FacingDirection] = SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_RIGHT
	ld [wSpritePlayerStateData1FacingDirection], a
	jr .done
.turnPlayerLeft
;>     else:
;>         mem[wSpritePlayerStateData1FacingDirection] = SPRITE_FACING_LEFT
	ld a, SPRITE_FACING_LEFT
	ld [wSpritePlayerStateData1FacingDirection], a
	jr .done
.turnPlayerDown
;> elif wNPCNumScriptedSteps == 4:
	cp $4
	ret nz
;>     mem[wSpritePlayerStateData1FacingDirection] = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
	ld [wSpritePlayerStateData1FacingDirection], a
.done
	ret

