	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> wSavedNPCMovementDirections2Index = wNPCMovementDirections2Index
	ld a, [wNPCMovementDirections2Index]
	ld [wSavedNPCMovementDirections2Index], a
;> end = FillMemory(addr(wNPCMovementDirections2), wNPCMovementDirections2Index, NPC_MOVEMENT_UP)
	ld b, 0
