	ld a, NPC_MOVEMENT_UP
	call FillMemory
;> mem[end] = 0xFF
	ld [hl], $ff
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> MoveSprite(addr(wNPCMovementDirections2))
	ld de, wNPCMovementDirections2
