;@ path: scripts/OaksLab
;@ def OaksLabOakGivesPokedexScript()
;@ When the rival stands before Oak: the Pokédex scene - Oak's request, the two Pokédexes handed out, his
;@ dream - then the rival leaves. The old man in Viridian is now awake and the road north is open.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabOakGivesPokedexScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:     # the rival is still walking
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> PlayDefaultMusic()
	call PlayDefaultMusic
;> wJoyIgnore = PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld a, PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> OaksLabRivalFaceUpOakFaceDownScript()
	call OaksLabRivalFaceUpOakFaceDownScript
;> hTextID = TEXT_OAKSLAB_RIVAL_WHAT_DID_YOU_CALL_ME_FOR
	ld a, TEXT_OAKSLAB_RIVAL_WHAT_DID_YOU_CALL_ME_FOR
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> DelayFrame()
	call DelayFrame
;> OaksLabRivalFaceUpOakFaceDownScript()
	call OaksLabRivalFaceUpOakFaceDownScript
;> hTextID = TEXT_OAKSLAB_OAK_I_HAVE_A_REQUEST
	ld a, TEXT_OAKSLAB_OAK_I_HAVE_A_REQUEST
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> DelayFrame()
	call DelayFrame
;> OaksLabRivalFaceUpOakFaceDownScript()
	call OaksLabRivalFaceUpOakFaceDownScript
;> hTextID = TEXT_OAKSLAB_OAK_MY_INVENTION_POKEDEX
	ld a, TEXT_OAKSLAB_OAK_MY_INVENTION_POKEDEX
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> DelayFrame()
	call DelayFrame
;> hTextID = TEXT_OAKSLAB_OAK_GOT_POKEDEX
	ld a, TEXT_OAKSLAB_OAK_GOT_POKEDEX
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> Delay3()
	call Delay3
;> wToggleableObjectIndex = TOGGLE_POKEDEX_1
	ld a, TOGGLE_POKEDEX_1
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_POKEDEX_2
	ld a, TOGGLE_POKEDEX_2
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> OaksLabRivalFaceUpOakFaceDownScript()
	call OaksLabRivalFaceUpOakFaceDownScript
;> hTextID = TEXT_OAKSLAB_OAK_THAT_WAS_MY_DREAM
	ld a, TEXT_OAKSLAB_OAK_THAT_WAS_MY_DREAM
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_RIGHT
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> Delay3()
	call Delay3
;> hTextID = TEXT_OAKSLAB_RIVAL_LEAVE_IT_ALL_TO_ME
	ld a, TEXT_OAKSLAB_RIVAL_LEAVE_IT_ALL_TO_ME
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_GOT_POKEDEX)
	ld hl, wEventFlags + $4
	set (EVENT_GOT_POKEDEX) % 8, [hl]
;> set_event(EVENT_OAK_GOT_PARCEL)
	ld hl, wEventFlags + $7
	set (EVENT_OAK_GOT_PARCEL) % 8, [hl]
;> wToggleableObjectIndex = TOGGLE_LYING_OLD_MAN
	ld a, TOGGLE_LYING_OLD_MAN
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_OLD_MAN
	ld a, TOGGLE_OLD_MAN
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> end = FillMemory(addr(wNPCMovementDirections2), wSavedNPCMovementDirections2Index, NPC_MOVEMENT_DOWN)
	ld a, [wSavedNPCMovementDirections2Index]
	ld b, 0
	ld c, a
	ld hl, wNPCMovementDirections2
	xor a ; NPC_MOVEMENT_DOWN
	call FillMemory
;> mem[end] = 0xFF                               # walk back down the way he came
	ld [hl], $ff
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> farcall(Music_RivalAlternateStart)
	ld b, BANK(Music_RivalAlternateStart)
	ld hl, Music_RivalAlternateStart
	call Bankswitch
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> MoveSprite(addr(wNPCMovementDirections2))
	ld de, wNPCMovementDirections2
	call MoveSprite

;> wOaksLabCurScript = SCRIPT_OAKSLAB_RIVAL_LEAVES_WITH_POKEDEX
	ld a, SCRIPT_OAKSLAB_RIVAL_LEAVES_WITH_POKEDEX
	ld [wOaksLabCurScript], a
	ret

;@ path: scripts/OaksLab
;@ def OaksLabRivalLeavesWithPokedexScript()
;@ When the rival has walked out: hide him and post him on Route 22 for the first battle there; Daisy's
;@ step in Pallet Town comes next.
