OaksLabRivalLeavesWithPokedexScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> PlayDefaultMusic()
	call PlayDefaultMusic
;> wToggleableObjectIndex = TOGGLE_OAKS_LAB_RIVAL
	ld a, TOGGLE_OAKS_LAB_RIVAL
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> set_event(EVENT_1ST_ROUTE22_RIVAL_BATTLE)
	ld hl, wEventFlags + $A4
	set (EVENT_1ST_ROUTE22_RIVAL_BATTLE) % 8, [hl]
;> reset_event(EVENT_2ND_ROUTE22_RIVAL_BATTLE)
	res (EVENT_2ND_ROUTE22_RIVAL_BATTLE) % 8, [hl]
;> set_event(EVENT_ROUTE22_RIVAL_WANTS_BATTLE)
	set (EVENT_ROUTE22_RIVAL_WANTS_BATTLE) % 8, [hl]
;> wToggleableObjectIndex = TOGGLE_ROUTE_22_RIVAL_1
	ld a, TOGGLE_ROUTE_22_RIVAL_1
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> wPalletTownCurScript = SCRIPT_PALLETTOWN_DAISY
	ld a, SCRIPT_PALLETTOWN_DAISY
	ld [wPalletTownCurScript], a
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a

;> wOaksLabCurScript = SCRIPT_OAKSLAB_NOOP
	ld a, SCRIPT_OAKSLAB_NOOP
	ld [wOaksLabCurScript], a
	ret

