	ret

;@ path: scripts/OaksLab
;@ def OaksLabScript_RemoveParcel()
;@ Take Oak's Parcel out of the bag (if it is there).
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabScript_RemoveParcel:
;> i = 0
	ld hl, wBagItems
	ld bc, 0
;> while wBagItems[2 * i] != 0xFF:
.loop
	ld a, [hli]
	cp $ff
	ret z
;>     if wBagItems[2 * i] == OAKS_PARCEL:
	cp OAKS_PARCEL
	jr z, .foundParcel
;>@which         wWhichPokemon = i
;>@qty         wItemQuantity = 1
;>@remove         return RemoveItemFromInventory(addr(wNumBagItems))
;>     i += 1
	inc hl
	inc c
	jr .loop
.foundParcel
;=@remove
	ld hl, wNumBagItems
;=@which
	ld a, c
	ld [wWhichPokemon], a
;=@qty
	ld a, 1
	ld [wItemQuantity], a
;=@remove
	jp RemoveItemFromInventory

;@ path: scripts/OaksLab
;@ def OaksLabCalcRivalMovementScript()
;@ Place the rival at the lab's door and work out how many steps up he walks to Oak, from where the player
;@ stands (below Oak, above, or beside him).
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabCalcRivalMovementScript:
;> hSpriteScreenYCoord = 0x7C
	ld a, $7c
	ldh [hSpriteScreenYCoord], a
;> hSpriteMapXCoord = 8
	ld a, 8
	ldh [hSpriteMapXCoord], a
;> if wYCoord == 3:                    # below Oak
	ld a, [wYCoord]
	cp 3
	jr nz, .not_below_oak
;>     wNPCMovementDirections2Index = 4     # steps
	ld a, $4
	ld [wNPCMovementDirections2Index], a
;>     x, y = 0x30, 11
	ld a, $30
	ld b, 11
	jr .done
.not_below_oak
;> elif wYCoord == 1:                  # above Oak
	cp 1
	jr nz, .not_above_oak
;>     wNPCMovementDirections2Index = 2
	ld a, $2
	ld [wNPCMovementDirections2Index], a
;>     x, y = 0x30, 9
	ld a, $30
	ld b, 9
	jr .done
.not_above_oak
;> else:                               # beside him
;>     wNPCMovementDirections2Index = 3
	ld a, $3
	ld [wNPCMovementDirections2Index], a
;>     y = 10
	ld b, 10
;>     if wXCoord == 4:
	ld a, [wXCoord]
	cp 4
	jr nz, .not_left_of_oak
;>         x = 0x40
	ld a, $40
	jr .done
.not_left_of_oak
;>     else:
;>         x = 0x20
	ld a, $20
.done
;> hSpriteScreenXCoord = x
	ldh [hSpriteScreenXCoord], a
;> hSpriteMapYCoord = y
	ld a, b
	ldh [hSpriteMapYCoord], a
;> wSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ld [wSpriteIndex], a
;> SetSpritePosition1()
	call SetSpritePosition1
	ret

;@ path: scripts/OaksLab
;@ def OaksLabLoadTextPointers2Script()
;@ Use the lab's second text pointer table (the texts after the Poké Balls from Oak).
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabLoadTextPointers2Script:
