;@ path: scripts/OaksLab
;@ def OaksLabRivalText() -> hl
;@ The rival in the lab: Gramps isn't around - then "go ahead and choose" - then his Pokémon looks stronger.
;@ test: skip a text script: the code after text_asm is run by the text engine
OaksLabRivalText:
	db TX_START_ASM
;> if not event(EVENT_FOLLOWED_OAK_INTO_LAB_2):
	ld a, [wEventFlags + $4]
	bit (EVENT_FOLLOWED_OAK_INTO_LAB_2) % 8, a
	jr nz, .beforeChooseMon
;>     PrintText(OaksLabRivalText.GrampsIsntAroundText)
	ld hl, .GrampsIsntAroundText
	call PrintText
	jr .done
.beforeChooseMon
;> elif not event(EVENT_GOT_STARTER):
	bit (EVENT_GOT_STARTER) % 8, a
	jr nz, .afterChooseMon
;>     PrintText(OaksLabRivalText.GoAheadAndChooseText)
	ld hl, .GoAheadAndChooseText
	call PrintText
	jr .done
.afterChooseMon
;> else:
;>     PrintText(OaksLabRivalText.MyPokemonLooksStrongerText)
	ld hl, .MyPokemonLooksStrongerText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.GrampsIsntAroundText:
	db TX_FAR
	dw _OaksLabRivalGrampsIsntAroundText
	db BANK(_OaksLabRivalGrampsIsntAroundText)
	db TX_END

.GoAheadAndChooseText:
	db TX_FAR
	dw _OaksLabRivalGoAheadAndChooseText
	db BANK(_OaksLabRivalGoAheadAndChooseText)
	db TX_END

.MyPokemonLooksStrongerText:
	db TX_FAR
	dw _OaksLabRivalMyPokemonLooksStrongerText
	db BANK(_OaksLabRivalMyPokemonLooksStrongerText)
	db TX_END

;@ path: scripts/OaksLab
;@ def OaksLabCharmanderPokeBallText() -> hl
;@ The left ball (Charmander): if the player picks it, the rival will take Squirtle.
;@ test: skip a text script: the code after text_asm is run by the text engine
OaksLabCharmanderPokeBallText:
	db TX_START_ASM
;> wRivalStarterTemp = STARTER2
	ld a, STARTER2
	ld [wRivalStarterTemp], a
;> wRivalStarterBallSpriteIndex = OAKSLAB_SQUIRTLE_POKE_BALL
	ld a, OAKSLAB_SQUIRTLE_POKE_BALL
	ld [wRivalStarterBallSpriteIndex], a
;> return OaksLabSelectedPokeBallScript(STARTER1, OAKSLAB_CHARMANDER_POKE_BALL)
	ld a, STARTER1
	ld b, OAKSLAB_CHARMANDER_POKE_BALL
	jr OaksLabSelectedPokeBallScript

