;@ path: scripts/OaksLab
;@ def OaksLabSelectedPokeBallScript(species: a, ball: b) -> hl
;@ Looking at a starter's ball: before Oak's speech they are just Poké Balls; during the choice, show the
;@ Pokémon; once both have chosen, the last one is Oak's.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabSelectedPokeBallScript:
;> wCurPartySpecies = wPokedexNum = species
	ld [wCurPartySpecies], a
	ld [wPokedexNum], a
;> wSpriteIndex = ball
	ld a, b
	ld [wSpriteIndex], a
;> if event(EVENT_GOT_STARTER):
;>     return OaksLabLastMonScript()
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_STARTER) % 8, a
	jp nz, OaksLabLastMonScript
;> if event(EVENT_OAK_ASKED_TO_CHOOSE_MON):
;>     return OaksLabShowPokeBallPokemonScript()
	bit (EVENT_OAK_ASKED_TO_CHOOSE_MON) % 8, a
	jr nz, OaksLabShowPokeBallPokemonScript
;> PrintText(OaksLabThoseArePokeBallsText)
	ld hl, OaksLabThoseArePokeBallsText
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: scripts/OaksLab
OaksLabThoseArePokeBallsText:
	db TX_FAR
	dw _OaksLabThoseArePokeBallsText
	db BANK(_OaksLabThoseArePokeBallsText)
	db TX_END

;@ path: scripts/OaksLab
;@ def OaksLabShowPokeBallPokemonScript() -> hl
;@ Oak looks down and the rival to the right; the Pokémon's Pokédex entry is shown (text at full speed),
;@ then Oak asks whether the player wants it.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabShowPokeBallPokemonScript:
;> hSpriteIndex = OAKSLAB_OAK1
	ld a, OAKSLAB_OAK1
	ldh [hSpriteIndex], a
;> hSpriteDataOffset = SPRITESTATEDATA1_FACINGDIRECTION
	ld a, SPRITESTATEDATA1_FACINGDIRECTION
	ldh [hSpriteDataOffset], a
;> mem[GetPointerWithinSpriteStateData1()] = SPRITE_FACING_DOWN
	call GetPointerWithinSpriteStateData1
	ld [hl], SPRITE_FACING_DOWN
;> hSpriteIndex = OAKSLAB_RIVAL
	ld a, OAKSLAB_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteDataOffset = SPRITESTATEDATA1_FACINGDIRECTION
	ld a, SPRITESTATEDATA1_FACINGDIRECTION
	ldh [hSpriteDataOffset], a
;> mem[GetPointerWithinSpriteStateData1()] = SPRITE_FACING_RIGHT
	call GetPointerWithinSpriteStateData1
	ld [hl], SPRITE_FACING_RIGHT
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> predef(StarterDex)
	ld a, (StarterDexPredef - PredefPointers) / 3
	call Predef
;> wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY)
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> ReloadMapData()
	call ReloadMapData
;> DelayFrames(10)
	ld c, 10
	call DelayFrames
;> if wSpriteIndex == OAKSLAB_CHARMANDER_POKE_BALL:
;>     return OaksLabYouWantCharmanderText()
	ld a, [wSpriteIndex]
	cp OAKSLAB_CHARMANDER_POKE_BALL
	jr z, OaksLabYouWantCharmanderText
;> if wSpriteIndex == OAKSLAB_SQUIRTLE_POKE_BALL:
;>     return OaksLabYouWantSquirtleText()
	cp OAKSLAB_SQUIRTLE_POKE_BALL
	jr z, OaksLabYouWantSquirtleText
;> return OaksLabYouWantBulbasaurText()
	jr OaksLabYouWantBulbasaurText

;@ path: scripts/OaksLab
;@ def OaksLabYouWantCharmanderText() -> hl
;@ "So! You want the fire Pokémon, Charmander?" and the yes/no choice.
;@ test: skip the text sits under a local label, which the pseudo-code can only name
