;@ path: scripts/OaksLab
;@ def OaksLabMonChoiceMenu(question: hl) -> hl
;@ Ask whether the player wants this starter; on "yes" its ball disappears, the player receives it at level 5
;@ and the rival's choice comes next.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabMonChoiceMenu:
;> PrintText(question)
	call PrintText
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> YesNoChoice()
	call YesNoChoice ; yes/no menu
;> if wCurrentMenuItem:
;>     return OaksLabMonChoiceEnd()
	ld a, [wCurrentMenuItem]
	and a
	jr nz, OaksLabMonChoiceEnd
;> wPlayerStarter = wNamedObjectIndex = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wPlayerStarter], a
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> if wSpriteIndex == OAKSLAB_CHARMANDER_POKE_BALL:
	ld a, [wSpriteIndex]
	cp OAKSLAB_CHARMANDER_POKE_BALL
	jr nz, .not_charmander
;>     wToggleableObjectIndex = TOGGLE_STARTER_BALL_1
	ld a, TOGGLE_STARTER_BALL_1
	jr .continue
.not_charmander
;> elif wSpriteIndex == OAKSLAB_SQUIRTLE_POKE_BALL:
	cp OAKSLAB_SQUIRTLE_POKE_BALL
	jr nz, .not_squirtle
;>     wToggleableObjectIndex = TOGGLE_STARTER_BALL_2
	ld a, TOGGLE_STARTER_BALL_2
	jr .continue
.not_squirtle
;> else:
;>     wToggleableObjectIndex = TOGGLE_STARTER_BALL_3
	ld a, TOGGLE_STARTER_BALL_3
.continue
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> PrintText(OaksLabMonEnergeticText)
	ld hl, OaksLabMonEnergeticText
	call PrintText
;> PrintText(OaksLabReceivedMonText)
	ld hl, OaksLabReceivedMonText
	call PrintText
;> wMonDataLocation = PLAYER_PARTY_DATA
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
;> wCurEnemyLevel = 5
	ld a, 5
	ld [wCurEnemyLevel], a
;> wPokedexNum = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wPokedexNum], a
;> AddPartyMon()
	call AddPartyMon
;> wStatusFlags4 |= 1 << BIT_GOT_STARTER
	ld hl, wStatusFlags4
	set BIT_GOT_STARTER, [hl]
;> wJoyIgnore = PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld a, PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wOaksLabCurScript = SCRIPT_OAKSLAB_CHOSE_STARTER_SCRIPT
	ld a, SCRIPT_OAKSLAB_CHOSE_STARTER_SCRIPT
	ld [wOaksLabCurScript], a

;> return OaksLabMonChoiceEnd()
;@ path: scripts/OaksLab
;@ def OaksLabMonChoiceEnd() -> hl
;@ End of the starter choice text.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabMonChoiceEnd:
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: scripts/OaksLab
OaksLabMonEnergeticText:
	db TX_FAR
	dw _OaksLabMonEnergeticText
	db BANK(_OaksLabMonEnergeticText)
	db TX_END

;@ path: scripts/OaksLab
OaksLabReceivedMonText:
	db TX_FAR
	dw _OaksLabReceivedMonText
	db BANK(_OaksLabReceivedMonText)
	db TX_SOUND_GET_KEY_ITEM
	db TX_END

;@ path: scripts/OaksLab
;@ def OaksLabLastMonScript() -> hl
;@ The last ball after both have chosen: Oak looks down and says it is his last Pokémon.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
OaksLabLastMonScript:
;> hSpriteIndex = OAKSLAB_OAK1
;> hSpriteDataOffset = SPRITESTATEDATA1_FACINGDIRECTION
	ld a, OAKSLAB_OAK1
	ldh [hSpriteIndex], a
	ld a, SPRITESTATEDATA1_FACINGDIRECTION
	ldh [hSpriteDataOffset], a
;> mem[GetPointerWithinSpriteStateData1()] = SPRITE_FACING_DOWN   # Oak looks down
	call GetPointerWithinSpriteStateData1
	ld [hl], SPRITE_FACING_DOWN
;> PrintText(OaksLabLastMonText)
;> return TextScriptEnd()
	ld hl, OaksLabLastMonText
	call PrintText
	jp TextScriptEnd

;@ path: scripts/OaksLab
OaksLabLastMonText:
	db TX_FAR
	dw _OaksLabLastMonText
	db BANK(_OaksLabLastMonText)
	db TX_END

;@ path: scripts/OaksLab
;@ def OaksLabOak1Text() -> hl
;@ Oak at his desk, depending on the story: which Pokémon do you want / your Pokémon can fight / deliver the
;@ parcel (which starts the Pokédex scene) / Pokémon around the world / five Poké Balls once the rival on
;@ Route 22 is beaten / and later, how the Pokédex is coming along with its rating.
;@ test: skip a text script: the code after text_asm is run by the text engine
OaksLabOak1Text:
	db TX_START_ASM
;> if (event(EVENT_PALLET_AFTER_GETTING_POKEBALLS)
	ld a, [wEventFlags + $0]
	bit (EVENT_PALLET_AFTER_GETTING_POKEBALLS) % 8, a
	jr nz, .already_got_poke_balls
;>         or CountSetBits(addr(wPokedexOwned), wPokedexOwnedEnd - wPokedexOwned) >= 2
	ld hl, wPokedexOwned
	ld b, wPokedexOwnedEnd - wPokedexOwned
	call CountSetBits
	ld a, [wNumSetBits]
	cp 2
	jr c, .check_for_poke_balls
;>         and event(EVENT_GOT_POKEDEX)):    # two Pokémon caught with the Pokédex
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEDEX) % 8, a
	jr z, .check_for_poke_balls
.already_got_poke_balls
;>     PrintText(OaksLabOak1Text.HowIsYourPokedexComingText)
	ld hl, .HowIsYourPokedexComingText
	call PrintText
;>     wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;>     predef(DisplayDexRating)              # and Oak rates it
	ld a, (DisplayDexRatingPredef - PredefPointers) / 3
	call Predef
;=@end
	jp .done
.check_for_poke_balls
;> elif not IsItemInBag(POKE_BALL):         # (zero means none) the player has Poké Balls
;>@come     PrintText(OaksLabOak1Text.ComeSeeMeSometimesText)
	ld b, POKE_BALL
	call IsItemInBag
	jr nz, .come_see_me_sometimes
;> elif event(EVENT_BEAT_ROUTE22_RIVAL_1ST_BATTLE):   # the five Poké Balls, only once
;>@got     got = event(EVENT_GOT_POKEBALLS_FROM_OAK)
;>@set     set_event(EVENT_GOT_POKEBALLS_FROM_OAK)
;>@ifgot     if got:
;>@come2         PrintText(OaksLabOak1Text.ComeSeeMeSometimesText)
;>     else:
;>@give         GiveItem(POKE_BALL, 5)
;>@balls         PrintText(OaksLabOak1Text.GivePokeballsText)
	ld a, [wEventFlags + $A4]
	bit (EVENT_BEAT_ROUTE22_RIVAL_1ST_BATTLE) % 8, a
	jr nz, .give_poke_balls
;> elif event(EVENT_GOT_POKEDEX):
;>@world     PrintText(OaksLabOak1Text.PokemonAroundTheWorldText)
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEDEX) % 8, a
	jr nz, .mon_around_the_world
;> elif event(EVENT_BATTLED_RIVAL_IN_OAKS_LAB):
;>@parcel     if not IsItemInBag(OAKS_PARCEL):    # the parcel is in the bag: Oak takes it
;>@deliver         PrintText(OaksLabOak1Text.DeliverParcelText)
;>@remove         OaksLabScript_RemoveParcel()
;>@next         wOaksLabCurScript = SCRIPT_OAKSLAB_RIVAL_ARRIVES_AT_OAKS_REQUEST   # the Pokédex scene
;>     else:
;>@raise         PrintText(OaksLabOak1Text.RaiseYourYoungPokemonText)
	bit (EVENT_BATTLED_RIVAL_IN_OAKS_LAB) % 8, a
	jr nz, .check_got_parcel
;> elif wStatusFlags4 >> BIT_GOT_STARTER & 1:
;>@fight     PrintText(OaksLabOak1Text.YourPokemonCanFightText)
	ld a, [wStatusFlags4]
	bit BIT_GOT_STARTER, a
	jr nz, .already_got_pokemon
;> else:
;>     PrintText(OaksLabOak1Text.WhichPokemonDoYouWantText)
	ld hl, .WhichPokemonDoYouWantText
	call PrintText
;=@end
	jr .done
.already_got_pokemon
;=@fight
	ld hl, .YourPokemonCanFightText
	call PrintText
;=@end
	jr .done
.check_got_parcel
;=@parcel
	ld b, OAKS_PARCEL
	call IsItemInBag
	jr nz, .got_parcel
;=@raise
	ld hl, .RaiseYourYoungPokemonText
	call PrintText
;=@end
	jr .done
.got_parcel
;=@deliver
	ld hl, .DeliverParcelText
	call PrintText
;=@remove
	call OaksLabScript_RemoveParcel
;=@next
	ld a, SCRIPT_OAKSLAB_RIVAL_ARRIVES_AT_OAKS_REQUEST
	ld [wOaksLabCurScript], a
;=@end
	jr .done
.mon_around_the_world
;=@world
	ld hl, .PokemonAroundTheWorldText
	call PrintText
;=@end
	jr .done
.give_poke_balls
;=@got
	ld hl, wEventFlags + $4
	bit (EVENT_GOT_POKEBALLS_FROM_OAK) % 8, [hl]
;=@set
	set (EVENT_GOT_POKEBALLS_FROM_OAK) % 8, [hl]
;=@ifgot
	jr nz, .come_see_me_sometimes
;=@give
	ld bc, ((POKE_BALL) & $ff) << 8 + ((5) & $ff)
	call GiveItem
;=@balls
	ld hl, .GivePokeballsText
	call PrintText
;=@end
	jr .done
.come_see_me_sometimes
;=@come
	ld hl, .ComeSeeMeSometimesText
	call PrintText
.done
;>@end return TextScriptEnd()
	jp TextScriptEnd

.WhichPokemonDoYouWantText:
	db TX_FAR
	dw _OaksLabOak1WhichPokemonDoYouWantText
	db BANK(_OaksLabOak1WhichPokemonDoYouWantText)
	db TX_END

