;> # the numbers of the lab's objects: the rival, then the three Poké Balls on the table
DEF OAKSLAB_RIVAL EQU 1
	EXPORT OAKSLAB_RIVAL
DEF OAKSLAB_CHARMANDER_POKE_BALL EQU 2
	EXPORT OAKSLAB_CHARMANDER_POKE_BALL
;> # (continued)
DEF OAKSLAB_SQUIRTLE_POKE_BALL EQU 3
	EXPORT OAKSLAB_SQUIRTLE_POKE_BALL
DEF OAKSLAB_BULBASAUR_POKE_BALL EQU 4
	EXPORT OAKSLAB_BULBASAUR_POKE_BALL
;> # Oak at his desk, the two Pokédexes, Oak at the door
DEF OAKSLAB_OAK1 EQU 5
	EXPORT OAKSLAB_OAK1
DEF OAKSLAB_POKEDEX1 EQU 6
	EXPORT OAKSLAB_POKEDEX1
;> # (continued)
DEF OAKSLAB_POKEDEX2 EQU 7
	EXPORT OAKSLAB_POKEDEX2
DEF OAKSLAB_OAK2 EQU 8
	EXPORT OAKSLAB_OAK2
;> # the girl and the two aides
DEF OAKSLAB_GIRL EQU 9
	EXPORT OAKSLAB_GIRL
DEF OAKSLAB_SCIENTIST1 EQU $A
	EXPORT OAKSLAB_SCIENTIST1
DEF OAKSLAB_SCIENTIST2 EQU $B
	EXPORT OAKSLAB_SCIENTIST2

;@ path: data/maps/objects/OaksLab
OaksLab_Object:
	db $3 ; border block

	db 2
	db 11, 4, 3 - 1, LAST_MAP
	db 11, 5, 3 - 1, LAST_MAP

	db 0

	db $B
	db SPRITE_BLUE
	db 3 + 4
	db 4 + 4
	db STAY
	db NONE
	db TRAINER | TEXT_OAKSLAB_RIVAL
	db OPP_RIVAL1
	db 1
	db SPRITE_POKE_BALL
	db 3 + 4
	db 6 + 4
	db STAY
	db NONE
	db TEXT_OAKSLAB_CHARMANDER_POKE_BALL
	db SPRITE_POKE_BALL
	db 3 + 4
	db 7 + 4
	db STAY
	db NONE
	db TEXT_OAKSLAB_SQUIRTLE_POKE_BALL
	db SPRITE_POKE_BALL
	db 3 + 4
	db 8 + 4
	db STAY
	db NONE
	db TEXT_OAKSLAB_BULBASAUR_POKE_BALL
	db SPRITE_OAK
	db 2 + 4
	db 5 + 4
	db STAY
	db DOWN
	db TEXT_OAKSLAB_OAK1
	db SPRITE_POKEDEX
	db 1 + 4
	db 2 + 4
	db STAY
	db NONE
	db TEXT_OAKSLAB_POKEDEX1
	db SPRITE_POKEDEX
	db 1 + 4
	db 3 + 4
	db STAY
	db NONE
	db TEXT_OAKSLAB_POKEDEX2
	db SPRITE_OAK
	db 10 + 4
	db 5 + 4
	db STAY
	db UP
	db TEXT_OAKSLAB_OAK2
	db SPRITE_GIRL
