ViridianMart_h::
	db MART
	db $4, $4
	dw ViridianMart_Blocks
	dw ViridianMart_TextPointers
	dw ViridianMart_Script
	db 0
	dw ViridianMart_Object
;@ path: scripts/ViridianMart
;@ def ViridianMart_Script()
;@ Viridian Mart's map script: pick the clerk's texts (before or after Oak got his parcel), then run the
;@ current step of the shop's script (handing the player Oak's Parcel).
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
ViridianMart_Script:
;> ViridianMartCheckParcelDeliveredScript()
	call ViridianMartCheckParcelDeliveredScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> CallFunctionInTable(wViridianMartCurScript, ViridianMart_ScriptPointers)
	ld hl, ViridianMart_ScriptPointers
	ld a, [wViridianMartCurScript]
	jp CallFunctionInTable

;@ path: scripts/ViridianMart
;@ def ViridianMartCheckParcelDeliveredScript()
;@ Until Oak has his parcel the shop uses texts in which it does not sell anything; afterwards the normal
;@ shop texts.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
ViridianMartCheckParcelDeliveredScript:
;> if not event(EVENT_OAK_GOT_PARCEL):
;>     texts = ViridianMart_TextPointers
	ld a, [wEventFlags + $7]
	bit (EVENT_OAK_GOT_PARCEL) % 8, a
	jr nz, .delivered_parcel
	ld hl, ViridianMart_TextPointers
	jr .done
.delivered_parcel
;> else:
;>     texts = ViridianMart_TextPointers2
	ld hl, ViridianMart_TextPointers2
.done
;> mem16[addr(wCurMapTextPtr)] = texts
	ld a, l
	ld [wCurMapTextPtr], a
	ld a, h
	ld [wCurMapTextPtr+1], a
	ret

;@ path: scripts/ViridianMart
ViridianMart_ScriptPointers:
	dw ViridianMartDefaultScript
DEF SCRIPT_VIRIDIANMART_DEFAULT EQU 0
	dw ViridianMartOaksParcelScript
DEF SCRIPT_VIRIDIANMART_OAKS_PARCEL EQU 1
	dw ViridianMartNoopScript
DEF SCRIPT_VIRIDIANMART_NOOP EQU 2

;@ path: scripts/ViridianMart
;@ def ViridianMartDefaultScript()
;@ Entering the shop for the first time: the clerk asks "You came from Pallet Town?" and the player walks up
;@ to the counter.
;@ test: skip the walking path sits under a local label, which the pseudo-code can only name
ViridianMartDefaultScript:
;> UpdateSprites()
	call UpdateSprites
;> hTextID = TEXT_VIRIDIANMART_CLERK_YOU_CAME_FROM_PALLET_TOWN
	ld a, TEXT_VIRIDIANMART_CLERK_YOU_CAME_FROM_PALLET_TOWN
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> n = DecodeRLEList(addr(wSimulatedJoypadStatesEnd), ViridianMartDefaultScript.PlayerMovement)   # left 1, up 2
	ld hl, wSimulatedJoypadStatesEnd
	ld de, .PlayerMovement
	call DecodeRLEList
;> wSimulatedJoypadStatesIndex = (n - 1) & 0xFF
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wViridianMartCurScript = SCRIPT_VIRIDIANMART_OAKS_PARCEL
	ld a, SCRIPT_VIRIDIANMART_OAKS_PARCEL
	ld [wViridianMartCurScript], a
	ret

.PlayerMovement:
	db PAD_LEFT, 1
	db PAD_UP, 2
	db -1 ; end

;@ path: scripts/ViridianMart
;@ def ViridianMartOaksParcelScript()
;@ At the counter: the clerk asks the player to take this parcel to Oak, and gives it.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
ViridianMartOaksParcelScript:
;> if wSimulatedJoypadStatesIndex:
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> Delay3()
	call Delay3
;> hTextID = TEXT_VIRIDIANMART_CLERK_PARCEL_QUEST
	ld a, TEXT_VIRIDIANMART_CLERK_PARCEL_QUEST
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> GiveItem(OAKS_PARCEL, 1)
	ld bc, ((OAKS_PARCEL) & $ff) << 8 + ((1) & $ff)
	call GiveItem
;> set_event(EVENT_GOT_OAKS_PARCEL)
	ld hl, wEventFlags + $7
	set (EVENT_GOT_OAKS_PARCEL) % 8, [hl]
;> wViridianMartCurScript = SCRIPT_VIRIDIANMART_NOOP
	ld a, SCRIPT_VIRIDIANMART_NOOP
	ld [wViridianMartCurScript], a
	; fallthrough
;@ path: scripts/ViridianMart
;@ def ViridianMartNoopScript()
;@ The shop's last step: nothing more happens.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
ViridianMartNoopScript:
;> return
	ret

