;@ def CeruleanTrashedHouse_Script()
;@ The robbed house's map script: only lets texts draw their box.
CeruleanTrashedHouse_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
	ret

;@ path: scripts/CeruleanTrashedHouse
CeruleanTrashedHouse_TextPointers:
	dw CeruleanTrashedHouseFishingGuruText
DEF TEXT_CERULEANTRASHEDHOUSE_FISHING_GURU EQU 1
	dw CeruleanTrashedHouseGirlText
DEF TEXT_CERULEANTRASHEDHOUSE_GIRL EQU 2
	dw CeruleanTrashedHouseWallHoleText
DEF TEXT_CERULEANTRASHEDHOUSE_WALL_HOLE EQU 3

;@ path: scripts/CeruleanTrashedHouse
;@ def CeruleanTrashedHouseFishingGuruText() -> hl
;@ The robbed man: complains about the stolen TM until the player has TM28 (DIG), then lets it go.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeruleanTrashedHouseFishingGuruText:
	db TX_START_ASM
;> count = GetQuantityOfItemInBag()           # b = TM_DIG through the predef
	ld b, TM_DIG
	ld a, (GetQuantityOfItemInBagPredef - PredefPointers) / 3
	call Predef
	and b
;> if count:
	jr z, .no_dig_tm
;>     PrintText(CeruleanTrashedHouseFishingGuruText.WhatsLostIsLostText)
	ld hl, .WhatsLostIsLostText
	call PrintText
	jr .done
;> else:
.no_dig_tm
;>     PrintText(CeruleanTrashedHouseFishingGuruText.TheyStoleATMText)
	ld hl, .TheyStoleATMText
	call PrintText
;> return TextScriptEnd()
.done
	jp TextScriptEnd

.TheyStoleATMText:
	db TX_FAR
	dw _CeruleanTrashedHouseFishingGuruTheyStoleATMText
	db BANK(_CeruleanTrashedHouseFishingGuruTheyStoleATMText)
	db TX_END

.WhatsLostIsLostText:
	db TX_FAR
	dw _CeruleanTrashedHouseFishingGuruWhatsLostIsLostText
	db BANK(_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText)
	db TX_END

