CeruleanTrashedHouseGirlText:
	db TX_FAR
	dw _CeruleanTrashedHouseGirlText
	db BANK(_CeruleanTrashedHouseGirlText)
	db TX_END

;@ path: scripts/CeruleanTrashedHouse
