BikeShop_h::
	db CLUB
	db $4, $4
	dw BikeShop_Blocks
	dw BikeShop_TextPointers
	dw BikeShop_Script
	db 0
	dw BikeShop_Object
;@ path: scripts/BikeShop
;@ def BikeShop_Script()
;@ The bike shop's map script: only lets texts draw their box.
BikeShop_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/BikeShop
BikeShop_TextPointers:
	dw BikeShopClerkText
DEF TEXT_BIKESHOP_CLERK EQU 1
	dw BikeShopMiddleAgedWomanText
DEF TEXT_BIKESHOP_MIDDLE_AGED_WOMAN EQU 2
	dw BikeShopYoungsterText
DEF TEXT_BIKESHOP_YOUNGSTER EQU 3

;@ path: scripts/BikeShop
;@ def BikeShopClerkText() -> hl
;@ The bike shop clerk: swaps the Bike Voucher for a Bicycle (if the bag has room); without a voucher he
;@ offers the bike for ¥1,000,000, which the player can never afford.
;@ test: skip a text script: the code after text_asm is run by the text engine
BikeShopClerkText:
	db TX_START_ASM
;> if event(EVENT_GOT_BICYCLE):
	ld a, [wEventFlags + $18]
	bit (EVENT_GOT_BICYCLE) % 8, a
	jr z, .dontHaveBike
;>     PrintText(BikeShopClerkHowDoYouLikeYourBicycleText)
	ld hl, BikeShopClerkHowDoYouLikeYourBicycleText
	call PrintText
;>     return TextScriptEnd()
	jp .Done
;> if not IsItemInBag(BIKE_VOUCHER):          # zero flag clear: the voucher is in the bag
.dontHaveBike
	ld b, BIKE_VOUCHER
	call IsItemInBag
	jr z, .dontHaveVoucher
;>     PrintText(BikeShopClerkOhThatsAVoucherText)
	ld hl, BikeShopClerkOhThatsAVoucherText
	call PrintText
;>     if GiveItem(BICYCLE, 1):
	ld bc, ((BICYCLE) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .BagFull
;>         hItemToRemoveID = BIKE_VOUCHER
	ld a, BIKE_VOUCHER
	ldh [hItemToRemoveID], a
;>         RemoveItemByID()
	ld b, BANK(RemoveItemByID)
	ld hl, RemoveItemByID
	call Bankswitch
;>         set_event(EVENT_GOT_BICYCLE)
	ld hl, wEventFlags + $18
	set (EVENT_GOT_BICYCLE) % 8, [hl]
;>         PrintText(BikeShopExchangedVoucherText)
	ld hl, BikeShopExchangedVoucherText
	call PrintText
	jr .Done
;>     else:
.BagFull
;>         PrintText(BikeShopBagFullText)
	ld hl, BikeShopBagFullText
	call PrintText
;>     return TextScriptEnd()
	jr .Done
.dontHaveVoucher
;> PrintText(BikeShopClerkWelcomeText)
	ld hl, BikeShopClerkWelcomeText
	call PrintText
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wLastMenuItem = 0
	ld [wLastMenuItem], a
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = 1
	ld a, $1
	ld [wMaxMenuItem], a
;> wTopMenuItemY = 2
	ld a, $2
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 1
	ld a, $1
	ld [wTopMenuItemX], a
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> TextBoxBorder(coord(0, 0), 4, 15)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 4
	ld c, 15
	call TextBoxBorder
;> UpdateSprites()
	call UpdateSprites
;> PlaceString(BikeShopMenuText, coord(2, 2))
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ld de, BikeShopMenuText
	call PlaceString
;> PlaceString(BikeShopMenuPrice, coord(8, 3))
	ld hl, (3) * SCREEN_WIDTH + (8) + wTileMap
	ld de, BikeShopMenuPrice
	call PlaceString
;> PrintText(BikeShopClerkDoYouLikeItText)
	ld hl, BikeShopClerkDoYouLikeItText
	call PrintText
;> if not HandleMenuInput() >> B_PAD_B & 1:
	call HandleMenuInput
	bit B_PAD_B, a
	jr nz, .cancel
;>     wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY)
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;>     if wCurrentMenuItem == 0:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .cancel
;>         PrintText(BikeShopCantAffordText)
	ld hl, BikeShopCantAffordText
	call PrintText
.cancel
;> PrintText(BikeShopComeAgainText)
	ld hl, BikeShopComeAgainText
	call PrintText
;> return TextScriptEnd()
.Done
	jp TextScriptEnd

;@ path: scripts/BikeShop
BikeShopMenuText:
	db   "BICYCLE"
	db "<NEXT>", "CANCEL@"

;@ path: scripts/BikeShop
BikeShopMenuPrice:
	db "¥1000000@"

;@ path: scripts/BikeShop
BikeShopClerkWelcomeText:
	db TX_FAR
	dw _BikeShopClerkWelcomeText
	db BANK(_BikeShopClerkWelcomeText)
	db TX_END

