;@ path: scripts/BikeShop
;@ def BikeShopYoungsterText() -> hl
;@ A boy in the bike shop: the bikes are expensive, or, once the player has one, a cool bike.
;@ test: skip a text script: the code after text_asm is run by the text engine
BikeShopYoungsterText:
	db TX_START_ASM
;> if event(EVENT_GOT_BICYCLE):
;>     text = BikeShopYoungsterText.CoolBikeText
	ld a, [wEventFlags + $18]
	bit (EVENT_GOT_BICYCLE) % 8, a
	ld hl, .CoolBikeText
	jr nz, .gotBike
;> else:
;>     text = BikeShopYoungsterText.TheseBikesAreExpensiveText
	ld hl, .TheseBikesAreExpensiveText
.gotBike
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.TheseBikesAreExpensiveText:
	db TX_FAR
	dw _BikeShopYoungsterTheseBikesAreExpensiveText
	db BANK(_BikeShopYoungsterTheseBikesAreExpensiveText)
	db TX_END

.CoolBikeText:
	db TX_FAR
	dw _BikeShopYoungsterCoolBikeText
	db BANK(_BikeShopYoungsterCoolBikeText)
	db TX_END
