	db TX_START_ASM
;> if not event(EVENT_RESCUED_MR_FUJI):
	ld a, [wEventFlags + $99]
	bit (EVENT_RESCUED_MR_FUJI) % 8, a
	jr nz, .rescued_mr_fuji
;>     PrintText(MrFujisHouseSuperNerdText.MrFujiIsntHereText)
	ld hl, .MrFujiIsntHereText
	call PrintText
	jr .done
.rescued_mr_fuji
;> else:
;>     PrintText(MrFujisHouseSuperNerdText.MrFujiHadBeenPrayingText)
	ld hl, .MrFujiHadBeenPrayingText
	call PrintText
.done
