;@ path: scripts/MrFujisHouse
;@ def MrFujisHouseMrFujiText() -> hl
;@ Mr. Fuji, back home: gives the Poké Flute once, if the bag has room; later asks whether it has helped.
;@ test: skip a text script: the code after text_asm is run by the text engine
MrFujisHouseMrFujiText:
	db TX_START_ASM
;> if event(EVENT_GOT_POKE_FLUTE):
	ld a, [wEventFlags + $25]
	bit (EVENT_GOT_POKE_FLUTE) % 8, a
	jr nz, .got_item
;>@helped     PrintText(MrFujisHouseMrFujiText.HasMyFluteHelpedYouText)
;> else:
;>     PrintText(MrFujisHouseMrFujiText.IThinkThisMayHelpYourQuestText)
	ld hl, .IThinkThisMayHelpYourQuestText
	call PrintText
;>     if GiveItem(POKE_FLUTE, 1):
	ld bc, ((POKE_FLUTE) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         PrintText(MrFujisHouseMrFujiText.ReceivedPokeFluteText)
	ld hl, .ReceivedPokeFluteText
	call PrintText
;>         set_event(EVENT_GOT_POKE_FLUTE)
	ld hl, wEventFlags + $25
	set (EVENT_GOT_POKE_FLUTE) % 8, [hl]
	jr .done
.bag_full
;>     else:
;>         PrintText(MrFujisHouseMrFujiText.PokeFluteNoRoomText)
	ld hl, .PokeFluteNoRoomText
	call PrintText
	jr .done
.got_item
;=@helped
	ld hl, .HasMyFluteHelpedYouText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

