NameRatersHouse_h::
	db HOUSE
	db $4, $4
	dw NameRatersHouse_Blocks
	dw NameRatersHouse_TextPointers
	dw NameRatersHouse_Script
	db 0
	dw NameRatersHouse_Object
;@ path: scripts/NameRatersHouse
;@ def NameRatersHouse_Script()
;@ The Name Rater's house: only lets texts draw their box.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
NameRatersHouse_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/NameRatersHouse
;@ def NameRatersHouseYesNoScript(question: hl) -> zero
;@ Print a question and the yes/no menu; the zero flag means "yes".
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
NameRatersHouseYesNoScript:
;> PrintText(question)
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> return wCurrentMenuItem == 0
	ld a, [wCurrentMenuItem]
	and a
	ret

;@ path: scripts/NameRatersHouse
;@ def NameRatersHouseCheckMonOTScript() -> carry
;@ Whether party Pokémon wWhichPokemon came from someone else: carry if its original trainer's name or ID
;@ differ from the player's (the Name Rater only renames the player's own Pokémon).
;@ test: wWhichPokemon = rand(0, 5)
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
NameRatersHouseCheckMonOTScript:
;> ot = AddNTimes(addr(wPartyMonOT), NAME_LENGTH, wWhichPokemon)
; return carry if mon's OT name or OT ID do not match the player's
	ld hl, wPartyMonOT
	ld bc, NAME_LENGTH
	ld a, [wWhichPokemon]
	call AddNTimes
;> if mem[ot:ot + NAME_LENGTH] != mem[addr(wPlayerName):addr(wPlayerName) + NAME_LENGTH]:   # (the loop below)
;>     return True
	ld de, wPlayerName
	ld c, NAME_LENGTH
	call .check_match_loop
	jr c, .no_match
;> otid = AddNTimes(addr(wPartyMon1OTID), PARTYMON_STRUCT_LENGTH, wWhichPokemon)
	ld hl, wPartyMon1OTID
	ld bc, PARTYMON_STRUCT_LENGTH
	ld a, [wWhichPokemon]
	call AddNTimes
;>@loop for i in range(2):
	ld de, wPlayerID
	ld c, $2
.check_match_loop
;>     if mem[addr(wPlayerID) + i] != mem[otid + i]:
	ld a, [de]
	cp [hl]
	jr nz, .no_match
;>@yes         return True
;=@loop
	inc hl
	inc de
	dec c
	jr nz, .check_match_loop
;> return False
	and a
	ret
.no_match
;=@yes
	scf
	ret

;@ path: scripts/NameRatersHouse
NameRatersHouse_TextPointers:
	dw NameRatersHouseNameRaterText
DEF TEXT_NAMERATERSHOUSE_NAME_RATER EQU 1

;@ path: scripts/NameRatersHouse
;@ def NameRatersHouseNameRaterText() -> hl
;@ The Name Rater: pick a party Pokémon; a traded one has "a truly impeccable name", the player's own can
;@ be given a new nickname on the naming screen.
;@ test: skip a text script: the code after text_asm is run by the text engine
NameRatersHouseNameRaterText:
	db TX_START_ASM
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> if not NameRatersHouseYesNoScript(NameRatersHouseNameRaterText.WantMeToRateText):     # "no"
	ld hl, .WantMeToRateText
	call NameRatersHouseYesNoScript
	jr nz, .did_not_rename
;>@no     text = NameRatersHouseNameRaterText.ComeAnyTimeYouLikeText
;> else:
;>     PrintText(NameRatersHouseNameRaterText.WhichPokemonText)
	ld hl, .WhichPokemonText
	call PrintText
;>     wPartyMenuTypeOrMessageID = 0
	xor a
	ld [wPartyMenuTypeOrMessageID], a
;>     wUpdateSpritesEnabled = 0
	ld [wUpdateSpritesEnabled], a
;>     wMenuItemToSwap = 0
	ld [wMenuItemToSwap], a
;>     cancelled = DisplayPartyMenu()
	call DisplayPartyMenu
	push af
;>     GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;>     RestoreScreenTilesAndReloadTilePatterns()
	call RestoreScreenTilesAndReloadTilePatterns
;>     LoadGBPal()
	call LoadGBPal
;>     if cancelled:
;>         text = NameRatersHouseNameRaterText.ComeAnyTimeYouLikeText
	pop af
	jr c, .did_not_rename
;>     else:
;>         GetPartyMonName2()
	call GetPartyMonName2
;>         if NameRatersHouseCheckMonOTScript():          # a traded Pokémon
;>             text = NameRatersHouseNameRaterText.ATrulyImpeccableNameText
	call NameRatersHouseCheckMonOTScript
	ld hl, .ATrulyImpeccableNameText
	jr c, .done
;>         elif not NameRatersHouseYesNoScript(NameRatersHouseNameRaterText.GiveItANiceNameText):
;>             text = NameRatersHouseNameRaterText.ComeAnyTimeYouLikeText
	ld hl, .GiveItANiceNameText
	call NameRatersHouseYesNoScript
	jr nz, .did_not_rename
;>         else:
;>             PrintText(NameRatersHouseNameRaterText.WhatShouldWeNameItText)
	ld hl, .WhatShouldWeNameItText
	call PrintText
;>             if DisplayNameRaterScreen():               # carry: no new name given
;>                 text = NameRatersHouseNameRaterText.ComeAnyTimeYouLikeText
	ld b, BANK(DisplayNameRaterScreen)
	ld hl, DisplayNameRaterScreen
	call Bankswitch
	jr c, .did_not_rename
;>             else:
;>                 text = NameRatersHouseNameRaterText.PokemonHasBeenRenamedText
	ld hl, .PokemonHasBeenRenamedText
.done
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd
.did_not_rename
;=@no
	ld hl, .ComeAnyTimeYouLikeText
	jr .done

.WantMeToRateText:
	db TX_FAR
	dw _NameRatersHouseNameRaterWantMeToRateText
	db BANK(_NameRatersHouseNameRaterWantMeToRateText)
	db TX_END

.WhichPokemonText:
	db TX_FAR
	dw _NameRatersHouseNameRaterWhichPokemonText
	db BANK(_NameRatersHouseNameRaterWhichPokemonText)
	db TX_END

.GiveItANiceNameText:
	db TX_FAR
	dw _NameRatersHouseNameRaterGiveItANiceNameText
	db BANK(_NameRatersHouseNameRaterGiveItANiceNameText)
	db TX_END

.WhatShouldWeNameItText:
	db TX_FAR
	dw _NameRatersHouseNameRaterWhatShouldWeNameItText
	db BANK(_NameRatersHouseNameRaterWhatShouldWeNameItText)
	db TX_END

.PokemonHasBeenRenamedText:
	db TX_FAR
	dw _NameRatersHouseNameRaterPokemonHasBeenRenamedText
	db BANK(_NameRatersHouseNameRaterPokemonHasBeenRenamedText)
	db TX_END

.ComeAnyTimeYouLikeText:
	db TX_FAR
	dw _NameRatersHouseNameRaterComeAnyTimeYouLikeText
	db BANK(_NameRatersHouseNameRaterComeAnyTimeYouLikeText)
	db TX_END

.ATrulyImpeccableNameText:
	db TX_FAR
	dw _NameRatersHouseNameRaterATrulyImpeccableNameText
	db BANK(_NameRatersHouseNameRaterATrulyImpeccableNameText)
	db TX_END
