VermilionDock_h::
	db SHIP_PORT
	db $6, $E
	dw VermilionDock_Blocks
	dw VermilionDock_TextPointers
	dw VermilionDock_Script
	db 0
	dw VermilionDock_Object
;@ path: scripts/VermilionDock
;@ def VermilionDock_Script()
;@ Vermilion's dock: the first time the player comes down from the S.S. Anne with HM01, the ship sails away;
;@ coming back later, the player walks three steps up and off the dock on his own.
;@ test: mem[wEventFlags + EVENT_SS_ANNE_LEFT // 8] |= 1 << EVENT_SS_ANNE_LEFT % 8    # the ship's departure scene polls LCD lines
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
VermilionDock_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> if event(EVENT_STARTED_WALKING_OUT_OF_DOCK):         # the walk off the dock is under way
;>@done     if event(EVENT_WALKED_OUT_OF_DOCK):
;>@done2         return
;>@steps     if wSimulatedJoypadStatesIndex:            # steps still to walk
;>@steps2         return
;>@joy     wJoyIgnore = 0
;>@walked     set_event(EVENT_WALKED_OUT_OF_DOCK)
;>@ret     return
	ld hl, wEventFlags + $BC
	bit (EVENT_STARTED_WALKING_OUT_OF_DOCK) % 8, [hl]
	jr nz, .walking_out_of_dock
;> if not event(EVENT_GOT_HM01):
;>     return
	bit (EVENT_GOT_HM01) % 8, [hl]
	ret z
;> if wDestinationWarpID != 1:              # not come down the ship's gangway
;>     return
	ld a, [wDestinationWarpID]
	cp $1
	ret nz
;> if not event(EVENT_SS_ANNE_LEFT):        # the first time: the ship sails away
;>     return VermilionDockSSAnneLeavesScript()
	bit (EVENT_SS_ANNE_LEFT) % 8, [hl]
	jp z, VermilionDockSSAnneLeavesScript
;> set_event(EVENT_STARTED_WALKING_OUT_OF_DOCK)
	set (EVENT_STARTED_WALKING_OUT_OF_DOCK) % 8, [hl]
;> Delay3()
	call Delay3
;> wStatusFlags5 |= 1 << BIT_SCRIPTED_MOVEMENT_STATE
	ld hl, wStatusFlags5
	set BIT_SCRIPTED_MOVEMENT_STATE, [hl]
;> for i in range(3):                       # three steps up
;>     mem[addr(wSimulatedJoypadStatesEnd) + i] = PAD_UP
	ld hl, wSimulatedJoypadStatesEnd
	ld a, PAD_UP
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wSimulatedJoypadStatesIndex = 3
	ld a, $3
	ld [wSimulatedJoypadStatesIndex], a
;> wSpritePlayerStateData2MovementByte1 = 0
	xor a
	ld [wSpritePlayerStateData2MovementByte1], a
;> wOverrideSimulatedJoypadStatesMask = 0
	ld [wOverrideSimulatedJoypadStatesMask], a
;> wJoyIgnore = 0xFF
	dec a
	ld [wJoyIgnore], a
	ret
.walking_out_of_dock
;=@done
	bit (EVENT_WALKED_OUT_OF_DOCK) % 8, [hl]
;=@done2
	ret nz
;=@steps
	ld a, [wSimulatedJoypadStatesIndex]
	and a
;=@steps2
	ret nz
;=@joy
	ld [wJoyIgnore], a
;=@walked
	set (EVENT_WALKED_OUT_OF_DOCK) % 8, [hl]
;=@ret
	ret

;@ path: scripts/VermilionDock
;@ def VermilionDockSSAnneLeavesScript()
;@ The S.S. Anne sails away: the surf music, the horn, the ship scrolls off to the right column by column
;@ while smoke puffs drift from its stack, then it is erased and the dock loses its warp to the ship.
;@ test: skip waits for LCD lines (VermilionDock_SyncScrollWithLY polls rLY)
VermilionDockSSAnneLeavesScript:
;> set_event(EVENT_SS_ANNE_LEFT)
	set (EVENT_SS_ANNE_LEFT) % 8, [hl]
;> wJoyIgnore = wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wJoyIgnore], a
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> PlayMusic(MUSIC_SURFING, BANK(Music_Surfing))
	ld c, BANK(Music_Surfing)
	ld a, MUSIC_SURFING
	call PlayMusic
;> farcall(LoadSmokeTileFourTimes)
	ld b, BANK(LoadSmokeTileFourTimes)
	ld hl, LoadSmokeTileFourTimes
	call Bankswitch
;> mem[wSpritePlayerStateData1ImageIndex] = 0
	xor a
	ld [wSpritePlayerStateData1ImageIndex], a
;> DelayFrames(120)
	ld c, 120
	call DelayFrames
;> CopyScreenTileBufferToVRAM(vBGMap1 >> 8)
	ld b, HIGH(vBGMap1)
	call CopyScreenTileBufferToVRAM
;> FillMemory(coord(0, 10), SCREEN_WIDTH * 6, 0x14)     # water under the ship
	ld hl, (10) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, SCREEN_WIDTH * 6
	ld a, $14 ; water tile
	call FillMemory
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	call Delay3
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> wSSAnneSmokeDriftAmount = 0
	ld [wSSAnneSmokeDriftAmount], a
;> rOBP1 = 0
	ldh [rOBP1], a
;> wSSAnneSmokeX = 88
	ld a, 88
	ld [wSSAnneSmokeX], a
;> saved = view = mem16[addr(wMapViewVRAMPointer)]
	ld hl, wMapViewVRAMPointer
	ld c, [hl]
	inc hl
	ld b, [hl]
	push bc
	push hl
;> PlaySoundWaitForCurrent(SFX_SS_ANNE_HORN)
	ld a, SFX_SS_ANNE_HORN
	call PlaySoundWaitForCurrent
;> wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a
;> scroll = 0
	ld d, $0
;> for column in range(8):
	ld e, $8
.shift_columns_up
;>     view += 2
	ld hl, $2
	add hl, bc
;>     mem16[addr(wMapViewVRAMPointer)] = view
	ld a, l
	ld [wMapViewVRAMPointer], a
	ld a, h
	ld [wMapViewVRAMPointer + 1], a
;>     ScheduleEastColumnRedraw()
	push hl
	push de
	call ScheduleEastColumnRedraw
;>     VermilionDock_EmitSmokePuff()
	call VermilionDock_EmitSmokePuff
	pop de
;>     for step in range(16):
	ld b, $10
.smoke_puff_drift_loop
;>         VermilionDock_AnimSmokePuffDriftRight()
	call VermilionDock_AnimSmokePuffDriftRight
;>         for _ in range(8):
	ld c, $8
.delay_between_drifts
;>             VermilionDock_SyncScrollWithLY(scroll)
	call VermilionDock_SyncScrollWithLY
	dec c
	jr nz, .delay_between_drifts
;>         scroll += 1
	inc d
	dec b
	jr nz, .smoke_puff_drift_loop
	pop bc
	dec e
	jr nz, .shift_columns_up
;> rWY = hWY = 0
	xor a
	ldh [rWY], a
	ldh [hWY], a
;> VermilionDock_EraseSSAnne()
	call VermilionDock_EraseSSAnne
;> hWY = 0x90
	ld a, $90
	ldh [hWY], a
;> wUpdateSpritesEnabled = 1
	ld a, $1
	ld [wUpdateSpritesEnabled], a
;> mem16[addr(wMapViewVRAMPointer)] = saved
	pop hl
	pop bc
	ld [hl], b
	dec hl
	ld [hl], c
;> LoadPlayerSpriteGraphics()
	call LoadPlayerSpriteGraphics
;> wNumberOfWarps -= 1                           # the warp onto the ship
	ld hl, wNumberOfWarps
	dec [hl]
	ret

;@ path: scripts/VermilionDock
;@ def VermilionDock_AnimSmokePuffDriftRight()
;@ Move every smoke puff sprite so far 2 pixels to the right (each puff is 16 OAM entries).
;@ test: wSSAnneSmokeDriftAmount = rand(1, 8)
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
VermilionDock_AnimSmokePuffDriftRight:
;> p = addr(wShadowOAMSprite04XCoord)
	push bc
	push de
	ld hl, wShadowOAMSprite04XCoord
;>@loop for i in range(wSSAnneSmokeDriftAmount * 16):   # 16 sprites per puff
	ld a, [wSSAnneSmokeDriftAmount]
	swap a
	ld c, a
	ld de, OBJ_SIZE
.drift_loop
;>     mem[p] = (mem[p] + 2) & 0xFF
	inc [hl]
	inc [hl]
;>     p += OBJ_SIZE
	add hl, de
;=@loop
	dec c
	jr nz, .drift_loop
	pop de
	pop bc
	ret

;@ path: scripts/VermilionDock
;@ def VermilionDock_EmitSmokePuff()
;@ A new smoke puff above the ship's front smokestack, 16 pixels left of the last one.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
VermilionDock_EmitSmokePuff:
; new smoke puff above the S.S. Anne's front smokestack
;> wSSAnneSmokeX = (wSSAnneSmokeX - 16) & 0xFF
	ld a, [wSSAnneSmokeX]
	sub 16
	ld [wSSAnneSmokeX], a
;>@oam WriteOAMBlock(1, 100, wSSAnneSmokeX, VermilionDockOAMBlock)   # one 2x2 block at Y 100
	ld c, a
	ld b, 100 ; Y
;> wSSAnneSmokeDriftAmount = (wSSAnneSmokeDriftAmount + 1) & 0xFF     # one more puff drifting
	ld a, [wSSAnneSmokeDriftAmount]
	inc a
	ld [wSSAnneSmokeDriftAmount], a
;=@oam
	ld a, $1
	ld de, VermilionDockOAMBlock
	call WriteOAMBlock
	ret

;@ path: scripts/VermilionDock
VermilionDockOAMBlock:
; tile ID, attributes
	db $fc, OAM_PAL1
	db $fd, OAM_PAL1
	db $fe, OAM_PAL1
	db $ff, OAM_PAL1

;@ path: scripts/VermilionDock
;@ def VermilionDock_SyncScrollWithLY(scroll: d)
;@ One frame's split scroll: from line $50 down the screen (the ship) is shifted by `scroll`, from line $80
;@ on it is not shifted.
;@ test: skip waits for LCD lines (polls rLY)
VermilionDock_SyncScrollWithLY:
;> for line, scx in ((0x50, scroll), (0x80, 0)):
	ld h, d
	ld l, $50
	call .sync_scroll_ly
	ld h, $0
	ld l, $80
;>     while rLY != line:
.sync_scroll_ly
	ldh a, [rLY]
	cp l
	jr nz, .sync_scroll_ly
;>         pass
;>     rSCX = scx
	ld a, h
	ldh [rSCX], a
;>     while rLY == scx:
.wait_for_ly_match
	ldh a, [rLY]
	cp h
	jr z, .wait_for_ly_match
;>         pass
	ret

;@ path: scripts/VermilionDock
;@ def VermilionDock_EraseSSAnne()
;@ Draw water over the ship in BG map 0 and in the map's blocks, then the horn and a 2-second pause.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
VermilionDock_EraseSSAnne:
;> FillMemory(addr(wVermilionDockTileMapBuffer), wVermilionDockTileMapBufferEnd - wVermilionDockTileMapBuffer, 0x14)
; Fill the area the S.S. Anne occupies in BG map 0 with water tiles.
	ld hl, wVermilionDockTileMapBuffer
	ld bc, wVermilionDockTileMapBufferEnd - wVermilionDockTileMapBuffer
	ld a, $14 ; water tile
	call FillMemory
;> CopyVideoData(bgcoord(0, 10), addr(wVermilionDockTileMapBuffer), BANK(wVermilionDockTileMapBuffer), 12)
	ld hl, (10) * TILEMAP_WIDTH + (0) + vBGMap0
	ld de, wVermilionDockTileMapBuffer
	ld bc, ((BANK(wVermilionDockTileMapBuffer)) & $ff) << 8 + ((12) & $ff)
	call CopyVideoData

;> blocks = addr(wOverworldMap) + (5 + 3) + (2 + 3) * (VERMILION_DOCK_WIDTH + 6)
; Replace the blocks of the lower half of the ship with water blocks. This
; leaves the upper half alone, but that doesn't matter because replacing any of
; the blocks is unnecessary because the blocks the ship occupies are south of
; the player and won't be redrawn when the player automatically walks north and
; exits the map. This code could be removed without affecting anything.
	ld hl, wOverworldMap + ((5) + 3) + (((2) + 3) * ((VERMILION_DOCK_WIDTH) + (3 * 2)))
;> for i in range(4):
;>     mem[blocks + i] = 0x0D                    # water block
	ld a, $d ; water block
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a

;> PlaySound(SFX_SS_ANNE_HORN)
	ld a, SFX_SS_ANNE_HORN
	call PlaySound
;> DelayFrames(120)
	ld c, 120
	call DelayFrames
	ret

