	dw (wOverworldMap + 7 + (VERMILION_DOCK_WIDTH) + ((VERMILION_DOCK_WIDTH) + 6) * ((0) >> 1) + (($E) >> 1))
	db 0, $E
	dw (wOverworldMap + 7 + (VERMILION_DOCK_WIDTH) + ((VERMILION_DOCK_WIDTH) + 6) * ((2) >> 1) + (($E) >> 1))
	db 2, $E
