VermilionDock_Blocks:
	db $0e, $0c, $0c, $0c, $0c, $0c, $16, $15, $0c, $0c, $03, $0c, $0c, $0e, $13, $01
	db $01, $01, $01, $04, $05, $06, $07, $01, $01, $01, $01, $0c, $11, $0d, $0d, $0d
	db $0d, $08, $09, $0a, $0b, $0d, $0d, $0d, $0d, $0c, $11, $0d, $0d, $0d, $0d, $0d
	db $0d, $0d, $0d, $0d, $0d, $0d, $0d, $0c, $11, $0d, $0d, $0d, $0d, $0d, $0d, $0d
	db $0d, $0d, $0d, $0d, $0d, $0c, $10, $12, $12, $12, $12, $12, $12, $12, $12, $12
