;@ The Poké Ball on the table: an Eevee at level 25; the ball disappears if it went to the party or the PC.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeladonMansionRoofHouseEeveePokeballText:
	db TX_START_ASM
;> if GivePokemon(EEVEE, 25):              # carry: the Eevee went to the party or the PC
	ld bc, ((EEVEE) & $ff) << 8 + ((25) & $ff)
	call GivePokemon
	jr nc, .party_full
;>     wToggleableObjectIndex = TOGGLE_CELADON_MANSION_EEVEE_GIFT
;>     predef(HideObject)
	ld a, TOGGLE_CELADON_MANSION_EEVEE_GIFT
	ld [wToggleableObjectIndex], a
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
.party_full
;> return TextScriptEnd()
	jp TextScriptEnd
