MrPsychicsHouse_h::
	db HOUSE
	db $4, $4
	dw MrPsychicsHouse_Blocks
	dw MrPsychicsHouse_TextPointers
	dw MrPsychicsHouse_Script
	db 0
	dw MrPsychicsHouse_Object
;@ path: scripts/MrPsychicsHouse
;@ def MrPsychicsHouse_Script()
;@ Mr. Psychic's house: only lets texts draw their box.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
MrPsychicsHouse_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/MrPsychicsHouse
MrPsychicsHouse_TextPointers:
	dw MrPsychicsHouseMrPsychicText
DEF TEXT_MRPSYCHICSHOUSE_MR_PSYCHIC EQU 1

;@ path: scripts/MrPsychicsHouse
;@ def MrPsychicsHouseMrPsychicText() -> hl
;@ Mr. Psychic: gives TM29 (PSYCHIC) once, if the bag has room, and explains it afterwards.
;@ test: skip a text script: the code after text_asm is run by the text engine
MrPsychicsHouseMrPsychicText:
	db TX_START_ASM
;> if event(EVENT_GOT_TM29):
	ld a, [wEventFlags + $76]
	bit (EVENT_GOT_TM29) % 8, a
	jr nz, .got_item
;>@early     PrintText(MrPsychicsHouseMrPsychicText.TM29ExplanationText)
;> else:
;>     PrintText(MrPsychicsHouseMrPsychicText.YouWantedThisText)
	ld hl, .YouWantedThisText
	call PrintText
;>     if GiveItem(TM_PSYCHIC_M, 1):
	ld bc, ((TM_PSYCHIC_M) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         PrintText(MrPsychicsHouseMrPsychicText.ReceivedTM29Text)
	ld hl, .ReceivedTM29Text
	call PrintText
;>         set_event(EVENT_GOT_TM29)
	ld hl, wEventFlags + $76
	set (EVENT_GOT_TM29) % 8, [hl]
	jr .done
.bag_full
;>     else:
;>         PrintText(MrPsychicsHouseMrPsychicText.TM29NoRoomText)
	ld hl, .TM29NoRoomText
	call PrintText
	jr .done
.got_item
;=@early
	ld hl, .TM29ExplanationText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.YouWantedThisText:
	db TX_FAR
	dw _MrPsychicsHouseMrPsychicYouWantedThisText
	db BANK(_MrPsychicsHouseMrPsychicYouWantedThisText)
	db TX_END

.ReceivedTM29Text:
	db TX_FAR
	dw _MrPsychicsHouseMrPsychicReceivedTM29Text
	db BANK(_MrPsychicsHouseMrPsychicReceivedTM29Text)
	db TX_SOUND_GET_ITEM_1
	db TX_END

.TM29ExplanationText:
	db TX_FAR
	dw _MrPsychicsHouseMrPsychicTM29ExplanationText
	db BANK(_MrPsychicsHouseMrPsychicTM29ExplanationText)
	db TX_END

.TM29NoRoomText:
	db TX_FAR
	dw _MrPsychicsHouseMrPsychicTM29NoRoomText
	db BANK(_MrPsychicsHouseMrPsychicTM29NoRoomText)
	db TX_END
DEF MRPSYCHICSHOUSE_MR_PSYCHIC EQU 1
	EXPORT MRPSYCHICSHOUSE_MR_PSYCHIC

