;> wWhichTrade = TRADE_FOR_MARCEL
	ld a, TRADE_FOR_MARCEL
	ld [wWhichTrade], a
;> DoInGameTradeDialogue()
	ld a, (DoInGameTradeDialoguePredef - PredefPointers) / 3
	call Predef
;> return TextScriptEnd()
	jp TextScriptEnd
DEF ROUTE2TRADEHOUSE_SCIENTIST EQU 1
	EXPORT ROUTE2TRADEHOUSE_SCIENTIST
DEF ROUTE2TRADEHOUSE_GAMEBOY_KID EQU 2
	EXPORT ROUTE2TRADEHOUSE_GAMEBOY_KID

;@ path: data/maps/objects/Route2TradeHouse
Route2TradeHouse_Object:
	db $a ; border block

	db 2
	db 7, 2, 3 - 1, LAST_MAP
	db 7, 3, 3 - 1, LAST_MAP

	db 0

	db 2
	db SPRITE_SCIENTIST
	db 4 + 4
	db 2 + 4
	db STAY
	db RIGHT
	db TEXT_ROUTE2TRADEHOUSE_SCIENTIST
	db SPRITE_GAMEBOY_KID
	db 1 + 4
	db 4 + 4
	db STAY
	db DOWN
	db TEXT_ROUTE2TRADEHOUSE_GAMEBOY_KID

	dw (wOverworldMap + 7 + (ROUTE_2_TRADE_HOUSE_WIDTH) + ((ROUTE_2_TRADE_HOUSE_WIDTH) + 6) * ((7) >> 1) + ((2) >> 1))
	db 7, 2
	dw (wOverworldMap + 7 + (ROUTE_2_TRADE_HOUSE_WIDTH) + ((ROUTE_2_TRADE_HOUSE_WIDTH) + 6) * ((7) >> 1) + ((3) >> 1))
	db 7, 3

Route5Gate_h::
	db GATE
	db $3, $4
	dw Route5Gate_Blocks
	dw Route5Gate_TextPointers
	dw Route5Gate_Script
	db 0
	dw Route5Gate_Object
;@ path: scripts/Route5Gate
;@ def Route5Gate_Script()
;@ The gate between Route 5 and Saffron City: run the current step of its script (the thirsty guard).
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route5Gate_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wRoute5GateCurScript, Route5Gate_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld a, [wRoute5GateCurScript]
	ld hl, Route5Gate_ScriptPointers
	jp CallFunctionInTable

;@ path: scripts/Route5Gate
Route5Gate_ScriptPointers:
	dw Route5GateDefaultScript
DEF SCRIPT_ROUTE5GATE_DEFAULT EQU 0
	dw Route5GatePlayerMovingScript
DEF SCRIPT_ROUTE5GATE_PLAYER_MOVING EQU 1

;@ path: scripts/Route5Gate
;@ def Route5GateMovePlayerUpScript()
;@ Push the player one step back up, away from Saffron, by simulated input.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route5GateMovePlayerUpScript:
;> wSimulatedJoypadStatesEnd = PAD_UP
	ld a, PAD_UP
	ld [wSimulatedJoypadStatesEnd], a
;> wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> return StartSimulatingJoypadStates()
	jp StartSimulatingJoypadStates

;@ path: scripts/Route5Gate
;@ def Route5GateDefaultScript()
;@ Until the guards have had a drink: stepping up to the guard, he takes a drink from the bag if there is one
;@ (and the way to Saffron opens), otherwise he says he is thirsty and the player is pushed back.
;@ test: skip the guard's spots sit under a local label, which the pseudo-code can only name
Route5GateDefaultScript:
;> if wStatusFlags1 >> BIT_GAVE_SAFFRON_GUARDS_DRINK & 1:
;>     return
	ld a, [wStatusFlags1]
	bit BIT_GAVE_SAFFRON_GUARDS_DRINK, a
	ret nz
;> if not ArePlayerCoordsInArray(Route5GateDefaultScript.PlayerInCoordsArray):
;>     return
	ld hl, .PlayerInCoordsArray
	call ArePlayerCoordsInArray
	ret nc
;> wPlayerMovingDirection = PLAYER_DIR_LEFT
	ld a, PLAYER_DIR_LEFT
	ld [wPlayerMovingDirection], a
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> farcall(RemoveGuardDrink)                     # hItemToRemoveID: the drink taken, or 0
	ld b, BANK(RemoveGuardDrink)
	ld hl, RemoveGuardDrink
	call Bankswitch
;> if not hItemToRemoveID:
	ldh a, [hItemToRemoveID]
	and a
	jr nz, .have_drink
;>     hTextID = TEXT_ROUTE5GATE_GUARD_GEE_IM_THIRSTY
	ld a, TEXT_ROUTE5GATE_GUARD_GEE_IM_THIRSTY
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     Route5GateMovePlayerUpScript()
	call Route5GateMovePlayerUpScript
;>     wRoute5GateCurScript = SCRIPT_ROUTE5GATE_PLAYER_MOVING
	ld a, SCRIPT_ROUTE5GATE_PLAYER_MOVING
	ld [wRoute5GateCurScript], a
;>     return
	ret
.have_drink
;> hTextID = TEXT_ROUTE5GATE_GUARD_GIVE_DRINK
	ld a, TEXT_ROUTE5GATE_GUARD_GIVE_DRINK
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wStatusFlags1 |= 1 << BIT_GAVE_SAFFRON_GUARDS_DRINK
	ld hl, wStatusFlags1
	set BIT_GAVE_SAFFRON_GUARDS_DRINK, [hl]
	ret

.PlayerInCoordsArray:
	db 3, 3
	db 3, 4
	db -1 ; end

;@ path: scripts/Route5Gate
;@ def Route5GatePlayerMovingScript()
;@ Once the push back is walked, give the controls back and return to the default step.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route5GatePlayerMovingScript:
;> if wSimulatedJoypadStatesIndex:       # still walking
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> Delay3()
	call Delay3
;> wJoyIgnore = 0
;> wRoute5GateCurScript = SCRIPT_ROUTE5GATE_DEFAULT
	xor a
	ld [wJoyIgnore], a
	ld [wRoute5GateCurScript], a
	ret

;@ path: scripts/Route5Gate
Route5Gate_TextPointers:
	dw SaffronGateGuardText
DEF TEXT_ROUTE5GATE_GUARD EQU 1
	dw SaffronGateGuardGeeImThirstyText
DEF TEXT_ROUTE5GATE_GUARD_GEE_IM_THIRSTY EQU 2
	dw SaffronGateGuardGiveDrinkText
DEF TEXT_ROUTE5GATE_GUARD_GIVE_DRINK EQU 3

;@ path: scripts/Route5Gate
;@ def SaffronGateGuardText() -> hl
;@ The guard in any of Saffron's gates: thirsty - he takes a drink if the player has one, or pushes the
;@ player back - and thanks for the drink afterwards.
;@ test: skip a text script: the code after text_asm is run by the text engine
SaffronGateGuardText:
	db TX_START_ASM
;> if wStatusFlags1 >> BIT_GAVE_SAFFRON_GUARDS_DRINK & 1:
	ld a, [wStatusFlags1]
	bit BIT_GAVE_SAFFRON_GUARDS_DRINK, a
	jr nz, .thanks_for_drink
;>@early     PrintText(SaffronGateGuardThanksForTheDrinkText)
;>@earlyend     return TextScriptEnd()
;> farcall(RemoveGuardDrink)
	ld b, BANK(RemoveGuardDrink)
	ld hl, RemoveGuardDrink
	call Bankswitch
;> if not hItemToRemoveID:
	ldh a, [hItemToRemoveID]
	and a
	jr nz, .have_drink
;>     PrintText(SaffronGateGuardGeeImThirstyText)
	ld hl, SaffronGateGuardGeeImThirstyText
	call PrintText
;>     Route5GateMovePlayerUpScript()
	call Route5GateMovePlayerUpScript
;>     wRoute5GateCurScript = SCRIPT_ROUTE5GATE_PLAYER_MOVING
	ld a, SCRIPT_ROUTE5GATE_PLAYER_MOVING
	ld [wRoute5GateCurScript], a
;>     return TextScriptEnd()
	jp TextScriptEnd

.have_drink
;> PrintText(SaffronGateGuardGiveDrinkText)
	ld hl, SaffronGateGuardGiveDrinkText
	call PrintText
;> wStatusFlags1 |= 1 << BIT_GAVE_SAFFRON_GUARDS_DRINK
	ld hl, wStatusFlags1
	set BIT_GAVE_SAFFRON_GUARDS_DRINK, [hl]
;> return TextScriptEnd()
	jp TextScriptEnd

.thanks_for_drink
;=@early
	ld hl, SaffronGateGuardThanksForTheDrinkText
	call PrintText
;=@earlyend
	jp TextScriptEnd

;@ path: scripts/Route5Gate
SaffronGateGuardGeeImThirstyText:
	db TX_FAR
	dw _SaffronGateGuardGeeImThirstyText
	db BANK(_SaffronGateGuardGeeImThirstyText)
	db TX_END

;@ path: scripts/Route5Gate
SaffronGateGuardGiveDrinkText:
	db TX_FAR
	dw _SaffronGateGuardImParchedText
	db BANK(_SaffronGateGuardImParchedText)
	db TX_SOUND_GET_KEY_ITEM
	db TX_FAR
	dw _SaffronGateGuardYouCanGoOnThroughText
	db BANK(_SaffronGateGuardYouCanGoOnThroughText)
	db TX_END

;@ path: scripts/Route5Gate
SaffronGateGuardThanksForTheDrinkText:
	db TX_FAR
	dw _SaffronGateGuardThanksForTheDrinkText
	db BANK(_SaffronGateGuardThanksForTheDrinkText)
	db TX_END
