;@ Push the player one step right, away from Saffron, as a scripted move.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route8GateMovePlayerRightScript:
;> wStatusFlags5 |= 1 << BIT_SCRIPTED_MOVEMENT_STATE
	ld hl, wStatusFlags5
	set BIT_SCRIPTED_MOVEMENT_STATE, [hl]
;> wSimulatedJoypadStatesEnd = PAD_RIGHT  # one step right
;> wSimulatedJoypadStatesIndex = 1
	ld a, PAD_RIGHT
	ld [wSimulatedJoypadStatesEnd], a
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> wSpritePlayerStateData2MovementByte1 = 0
;> wOverrideSimulatedJoypadStatesMask = 0
	xor a
	ld [wSpritePlayerStateData2MovementByte1], a
	ld [wOverrideSimulatedJoypadStatesMask], a
	ret

;@ path: scripts/Route8Gate
;@ def Route8GateDefaultScript()
;@ Until the guards have had a drink: stepping up to the guard, he takes a drink from the bag if there is one,
;@ otherwise he says he is thirsty and the player is pushed back right.
;@ test: skip the guard's spots sit under a local label, which the pseudo-code can only name
Route8GateDefaultScript:
;> if wStatusFlags1 >> BIT_GAVE_SAFFRON_GUARDS_DRINK & 1:
;>     return
	ld a, [wStatusFlags1]
	bit BIT_GAVE_SAFFRON_GUARDS_DRINK, a
	ret nz
;> if not ArePlayerCoordsInArray(Route8GateDefaultScript.PlayerInCoordsArray):
;>     return
	ld hl, .PlayerInCoordsArray
	call ArePlayerCoordsInArray
	ret nc
;> wPlayerMovingDirection = PLAYER_DIR_LEFT
	ld a, PLAYER_DIR_LEFT
	ld [wPlayerMovingDirection], a
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> farcall(RemoveGuardDrink)
	ld b, BANK(RemoveGuardDrink)
	ld hl, RemoveGuardDrink
	call Bankswitch
;> if not hItemToRemoveID:
	ldh a, [hItemToRemoveID]
	and a
	jr nz, .have_drink
;>     hTextID = TEXT_ROUTE8GATE_GUARD_GEE_IM_THIRSTY
	ld a, TEXT_ROUTE8GATE_GUARD_GEE_IM_THIRSTY
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     Route8GateMovePlayerRightScript()
	call Route8GateMovePlayerRightScript
;>     wRoute8GateCurScript = SCRIPT_ROUTE8GATE_PLAYER_MOVING
	ld a, SCRIPT_ROUTE8GATE_PLAYER_MOVING
	ld [wRoute8GateCurScript], a
;>     return
	ret
.have_drink
;> wStatusFlags1 |= 1 << BIT_GAVE_SAFFRON_GUARDS_DRINK
	ld hl, wStatusFlags1
	set BIT_GAVE_SAFFRON_GUARDS_DRINK, [hl]
;> hTextID = TEXT_ROUTE8GATE_GUARD_GIVE_DRINK
	ld a, TEXT_ROUTE8GATE_GUARD_GIVE_DRINK
	ldh [hTextID], a
;> return DisplayTextID()
	jp DisplayTextID

.PlayerInCoordsArray:
	db 3, 2
	db 4, 2
	db -1 ; end

;@ path: scripts/Route8Gate
;@ def Route8GatePlayerMovingScript()
;@ Once the push back is walked, give the controls back and return to the default step.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route8GatePlayerMovingScript:
;> if wSimulatedJoypadStatesIndex:       # still walking
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> Delay3()
	call Delay3
;> wJoyIgnore = 0
;> wRoute8GateCurScript = SCRIPT_ROUTE8GATE_DEFAULT
	xor a
	ld [wJoyIgnore], a
	ld [wRoute8GateCurScript], a
	ret

