;@ path: scripts/PowerPlant
;@ def PowerPlant_Script()
;@ The Power Plant's map script: run the current step (the Voltorb, Electrode and Zapdos that wait there as
;@ "trainers").
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
PowerPlant_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> mem[addr(wPowerPlantCurScript)] = ExecuteCurMapScriptInTable(mem[addr(wPowerPlantCurScript)], PowerPlantTrainerHeaders, PowerPlant_ScriptPointers)
	ld hl, PowerPlantTrainerHeaders
	ld de, PowerPlant_ScriptPointers
	ld a, [wPowerPlantCurScript]
	call ExecuteCurMapScriptInTable
	ld [wPowerPlantCurScript], a
	ret

