;@ def PowerPlantInitBattleScript(header: hl) -> hl
;@ Talking to one of the plant's Pokémon: its battle through the trainer header, and the plant's script
;@ follows the map script step it set.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
PowerPlantInitBattleScript:
;> TalkToTrainer(header)
	call TalkToTrainer
;> wPowerPlantCurScript = wCurMapScript
	ld a, [wCurMapScript]
	ld [wPowerPlantCurScript], a
;> return TextScriptEnd()
	jp TextScriptEnd

