Route16FlyHouse_h::
	db HOUSE
	db $4, $4
	dw Route16FlyHouse_Blocks
	dw Route16FlyHouse_TextPointers
	dw Route16FlyHouse_Script
	db 0
	dw Route16FlyHouse_Object
;@ path: scripts/Route16FlyHouse
;@ def Route16FlyHouse_Script()
;@ The house with HM02 on Route 16: only lets texts draw their box.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route16FlyHouse_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/Route16FlyHouse
Route16FlyHouse_TextPointers:
	dw Route16FlyHouseBrunetteGirlText
DEF TEXT_ROUTE16FLYHOUSE_BRUNETTE_GIRL EQU 1
	dw Route16FlyHouseFearowText
DEF TEXT_ROUTE16FLYHOUSE_FEAROW EQU 2

;@ path: scripts/Route16FlyHouse
;@ def Route16FlyHouseBrunetteGirlText() -> hl
;@ The girl in the Fly house: gives HM02 (FLY) once, if the bag has room, and explains it afterwards.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route16FlyHouseBrunetteGirlText:
	db TX_START_ASM
;> if event(EVENT_GOT_HM02):
	ld a, [wEventFlags + $99]
	bit (EVENT_GOT_HM02) % 8, a
;>     text = Route16FlyHouseBrunetteGirlText.HM02ExplanationText
	ld hl, .HM02ExplanationText
	jr nz, .got_item
;> else:
;>     PrintText(Route16FlyHouseBrunetteGirlText.Text)
	ld hl, .Text
	call PrintText
;>     if GiveItem(HM_FLY, 1):
	ld bc, ((HM_FLY) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         set_event(EVENT_GOT_HM02)
	ld hl, wEventFlags + $99
	set (EVENT_GOT_HM02) % 8, [hl]
;>         text = Route16FlyHouseBrunetteGirlText.ReceivedHM02Text
	ld hl, .ReceivedHM02Text
	jr .got_item
.bag_full
;>     else:
;>         text = Route16FlyHouseBrunetteGirlText.HM02NoRoomText
	ld hl, .HM02NoRoomText
.got_item
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _Route16FlyHouseBrunetteGirlText
	db BANK(_Route16FlyHouseBrunetteGirlText)
	db TX_END

.ReceivedHM02Text:
	db TX_FAR
	dw _Route16FlyHouseBrunetteGirlReceivedHM02Text
	db BANK(_Route16FlyHouseBrunetteGirlReceivedHM02Text)
	db TX_SOUND_GET_KEY_ITEM
	db TX_END

.HM02ExplanationText:
	db TX_FAR
	dw _Route16FlyHouseBrunetteGirlHM02ExplanationText
	db BANK(_Route16FlyHouseBrunetteGirlHM02ExplanationText)
	db TX_END

.HM02NoRoomText:
	db TX_FAR
	dw _Route16FlyHouseBrunetteGirlHM02NoRoomText
	db BANK(_Route16FlyHouseBrunetteGirlHM02NoRoomText)
	db TX_END

;@ path: scripts/Route16FlyHouse
;@ def Route16FlyHouseFearowText() -> hl
;@ The Fearow: its line, then its cry.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route16FlyHouseFearowText:
	db TX_START_ASM
;> PrintText(Route16FlyHouseFearowText.Text)
	ld hl, .Text
	call PrintText
;> PlayCry(FEAROW)
	ld a, FEAROW
	call PlayCry
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _Route16FlyHouseFearowText
	db BANK(_Route16FlyHouseFearowText)
	db TX_END
DEF ROUTE16FLYHOUSE_BRUNETTE_GIRL EQU 1
	EXPORT ROUTE16FLYHOUSE_BRUNETTE_GIRL
DEF ROUTE16FLYHOUSE_FEAROW EQU 2
	EXPORT ROUTE16FLYHOUSE_FEAROW

;@ path: data/maps/objects/Route16FlyHouse
Route16FlyHouse_Object:
	db $a ; border block

	db 2
	db 7, 2, 9 - 1, LAST_MAP
	db 7, 3, 9 - 1, LAST_MAP

	db 0

	db 2
	db SPRITE_BRUNETTE_GIRL
	db 3 + 4
	db 2 + 4
	db STAY
	db RIGHT
	db TEXT_ROUTE16FLYHOUSE_BRUNETTE_GIRL
	db SPRITE_BIRD
	db 4 + 4
	db 6 + 4
	db WALK
	db ANY_DIR
	db TEXT_ROUTE16FLYHOUSE_FEAROW

	dw (wOverworldMap + 7 + (ROUTE_16_FLY_HOUSE_WIDTH) + ((ROUTE_16_FLY_HOUSE_WIDTH) + 6) * ((7) >> 1) + ((2) >> 1))
	db 7, 2
	dw (wOverworldMap + 7 + (ROUTE_16_FLY_HOUSE_WIDTH) + ((ROUTE_16_FLY_HOUSE_WIDTH) + 6) * ((7) >> 1) + ((3) >> 1))
	db 7, 3

Route22Gate_h::
	db GATE
	db $4, $5
	dw Route22Gate_Blocks
	dw Route22Gate_TextPointers
	dw Route22Gate_Script
	db 0
	dw Route22Gate_Object
;@ path: scripts/Route22Gate
;@ def Route22Gate_Script()
;@ The gate between Route 22 and Route 23: run the current step (the guard who checks for the Boulder
;@ Badge), and leaving goes to Route 23 from the north half, to Route 22 from the south half.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route22Gate_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> CallFunctionInTable(wRoute22GateCurScript, Route22Gate_ScriptPointers)
	ld hl, Route22Gate_ScriptPointers
	ld a, [wRoute22GateCurScript]
	call CallFunctionInTable
;> if wYCoord < 4:                    # the north half: the gate's exits lead to Route 23
;>     last_map = ROUTE_23
	ld a, [wYCoord]
	cp 4
	ld a, ROUTE_23
	jr c, .set_last_map
;> else:
;>     last_map = ROUTE_22
	ld a, ROUTE_22
.set_last_map
;> wLastMap = last_map
	ld [wLastMap], a
	ret

;@ path: scripts/Route22Gate
Route22Gate_ScriptPointers:
	dw Route22GateDefaultScript
DEF SCRIPT_ROUTE22GATE_DEFAULT EQU 0
	dw Route22GatePlayerMovingScript
DEF SCRIPT_ROUTE22GATE_PLAYER_MOVING EQU 1
	dw Route22GateNoopScript
DEF SCRIPT_ROUTE22GATE_NOOP EQU 2

;@ path: scripts/Route22Gate
;@ def Route22GateDefaultScript()
;@ Stepping in front of the guard makes him speak.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route22GateDefaultScript:
;> if not ArePlayerCoordsInArray(Route22GateScriptCoords):
;>     return
	ld hl, Route22GateScriptCoords
	call ArePlayerCoordsInArray
	ret nc
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hTextID = TEXT_ROUTE22GATE_GUARD
;> return DisplayTextID()
	ld a, TEXT_ROUTE22GATE_GUARD
	ldh [hTextID], a
	jp DisplayTextID

;@ path: scripts/Route22Gate
Route22GateScriptCoords:
	db 2, 4
	db 2, 5
	db -1 ; end

;@ path: scripts/Route22Gate
;@ def Route22GateMovePlayerDownScript()
;@ Push the player one step back down by simulated input (the same PAD_DOWN value also goes into the
;@ facing direction and wJoyIgnore).
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route22GateMovePlayerDownScript:
;> wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> wSimulatedJoypadStatesEnd = PAD_DOWN
	ld a, PAD_DOWN
	ld [wSimulatedJoypadStatesEnd], a
;> wSpritePlayerStateData1FacingDirection = PAD_DOWN
;> wJoyIgnore = PAD_DOWN
	ld [wSpritePlayerStateData1FacingDirection], a
	ld [wJoyIgnore], a
;> return StartSimulatingJoypadStates()
	jp StartSimulatingJoypadStates

;@ path: scripts/Route22Gate
;@ def Route22GatePlayerMovingScript()
;@ Once the push back is walked, give the controls back and return to the default step.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route22GatePlayerMovingScript:
;> if wSimulatedJoypadStatesIndex:       # still walking
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> Delay3()
	call Delay3
;> wRoute22GateCurScript = SCRIPT_ROUTE22GATE_DEFAULT
	ld a, SCRIPT_ROUTE22GATE_DEFAULT
	ld [wRoute22GateCurScript], a
;@ path: scripts/Route22Gate
;@ def Route22GateNoopScript()
;@ After the guard let the player pass: nothing more happens.
;@ test: hLoadedROMBank = 0x07    # the bank this code runs in
Route22GateNoopScript:
;> return
	ret

;@ path: scripts/Route22Gate
Route22Gate_TextPointers:
	dw Route22GateGuardText
DEF TEXT_ROUTE22GATE_GUARD EQU 1

;@ path: scripts/Route22Gate
;@ def Route22GateGuardText() -> hl
;@ The guard: without the Boulder Badge he refuses (a buzzer sound) and pushes the player back; with it,
;@ "go right ahead".
;@ test: skip a text script: the code after text_asm is run by the text engine
Route22GateGuardText:
	db TX_START_ASM
;> if wObtainedBadges >> BIT_BOULDERBADGE & 1:
;>@ahead     PrintText(Route22GateGuardGoRightAheadText)
;>@noop     script = SCRIPT_ROUTE22GATE_NOOP
	ld a, [wObtainedBadges]
	bit BIT_BOULDERBADGE, a
	jr nz, .has_boulderbadge
;> else:
;>     PrintText(Route22GateGuardNoBoulderbadgeText)
	ld hl, Route22GateGuardNoBoulderbadgeText
	call PrintText
;>     Route22GateMovePlayerDownScript()     # pushed back down
	call Route22GateMovePlayerDownScript
;>     script = SCRIPT_ROUTE22GATE_PLAYER_MOVING
	ld a, SCRIPT_ROUTE22GATE_PLAYER_MOVING
	jr .set_current_script
.has_boulderbadge
;=@ahead
	ld hl, Route22GateGuardGoRightAheadText
	call PrintText
;=@noop
	ld a, SCRIPT_ROUTE22GATE_NOOP
.set_current_script
;> wRoute22GateCurScript = script
	ld [wRoute22GateCurScript], a
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: scripts/Route22Gate
;@ def Route22GateGuardNoBoulderbadgeText() -> hl
;@ "Only trainers with the Boulder Badge may pass", the buzzer, then "I can't let you pass" as the next text.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route22GateGuardNoBoulderbadgeText:
	db TX_FAR
	dw _Route22GateGuardNoBoulderbadgeText
	db BANK(_Route22GateGuardNoBoulderbadgeText)
	db TX_START_ASM
;> PlaySoundWaitForCurrent(SFX_DENIED)
	ld a, SFX_DENIED
	call PlaySoundWaitForCurrent
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> return Route22GateGuardICantLetYouPassText
	ld hl, Route22GateGuardICantLetYouPassText
	ret

;@ path: scripts/Route22Gate
Route22GateGuardICantLetYouPassText:
	db TX_FAR
	dw _Route22GateGuardICantLetYouPassText
	db BANK(_Route22GateGuardICantLetYouPassText)
	db TX_END

;@ path: scripts/Route22Gate
Route22GateGuardGoRightAheadText:
	db TX_FAR
	dw _Route22GateGuardGoRightAheadText
	db BANK(_Route22GateGuardGoRightAheadText)
	db TX_SOUND_GET_ITEM_1
	db TX_END
DEF ROUTE22GATE_GUARD EQU 1
	EXPORT ROUTE22GATE_GUARD

;@ path: data/maps/objects/Route22Gate
Route22Gate_Object:
	db $a ; border block

	db 4
	db 7, 4, 1 - 1, LAST_MAP
	db 7, 5, 1 - 1, LAST_MAP
	db 0, 4, 1 - 1, LAST_MAP
	db 0, 5, 2 - 1, LAST_MAP

	db 0

	db 1
	db SPRITE_GUARD
	db 2 + 4
	db 6 + 4
	db STAY
	db LEFT
	db TEXT_ROUTE22GATE_GUARD

	dw (wOverworldMap + 7 + (ROUTE_22_GATE_WIDTH) + ((ROUTE_22_GATE_WIDTH) + 6) * ((7) >> 1) + ((4) >> 1))
	db 7, 4
	dw (wOverworldMap + 7 + (ROUTE_22_GATE_WIDTH) + ((ROUTE_22_GATE_WIDTH) + 6) * ((7) >> 1) + ((5) >> 1))
	db 7, 5
	dw (wOverworldMap + 7 + (ROUTE_22_GATE_WIDTH) + ((ROUTE_22_GATE_WIDTH) + 6) * ((0) >> 1) + ((4) >> 1))
	db 0, 4
	dw (wOverworldMap + 7 + (ROUTE_22_GATE_WIDTH) + ((ROUTE_22_GATE_WIDTH) + 6) * ((0) >> 1) + ((5) >> 1))
	db 0, 5
;@ path: maps
Route22Gate_Blocks:
	db $03, $2e, $28, $2f, $03, $00, $00, $04, $00, $00, $00, $00, $04, $00, $00, $00
	db $2c, $04, $2d, $00

BillsHouse_h::
	db INTERIOR
	db $4, $4
	dw BillsHouse_Blocks
	dw BillsHouse_TextPointers
	dw BillsHouse_Script
	db 0
	dw BillsHouse_Object
;@ path: scripts/BillsHouse
;@ def BillsHouse_Script()
;@ Bill's house map script: run the current step (Bill as a Pokémon walking into his machine and out again).
BillsHouse_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wBillsHouseCurScript, BillsHouse_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld a, [wBillsHouseCurScript]
	ld hl, BillsHouse_ScriptPointers
	jp CallFunctionInTable

;@ path: scripts/BillsHouse
BillsHouse_ScriptPointers:
	dw BillsHouseDefaultScript
DEF SCRIPT_BILLSHOUSE_DEFAULT EQU 0
	dw BillsHousePokemonWalkToMachineScript
DEF SCRIPT_BILLSHOUSE_POKEMON_WALK_TO_MACHINE EQU 1
	dw BillsHousePokemonEntersMachineScript
DEF SCRIPT_BILLSHOUSE_POKEMON_ENTERS_MACHINE EQU 2
	dw BillsHouseBillExitsMachineScript
DEF SCRIPT_BILLSHOUSE_BILL_EXITS_MACHINE EQU 3
	dw BillsHouseCleanupScript
DEF SCRIPT_BILLSHOUSE_CLEANUP EQU 4
	dw BillsHousePCScript
DEF SCRIPT_BILLSHOUSE_PC EQU 5

;@ path: scripts/BillsHouse
;@ def BillsHouseDefaultScript()
;@ Bill's house idle step: nothing happens.
BillsHouseDefaultScript:
;> return
	ret

;@ path: scripts/BillsHouse
;@ def BillsHousePokemonWalkToMachineScript()
;@ Bill, still a Pokémon, walks into the Cell Separator: straight up, or around the player if the player
;@ is facing down (standing in the way).
;@ test: skip the movement lists sit under local labels, which the pseudo-code cannot reach
BillsHousePokemonWalkToMachineScript:
;> if wSpritePlayerStateData1FacingDirection == SPRITE_FACING_DOWN:
	ld a, [wSpritePlayerStateData1FacingDirection]
	and a ; cp SPRITE_FACING_DOWN
	ld de, .PokemonWalkToMachineMovement
	jr nz, .notDown
;>     moves = BillsHousePokemonWalkToMachineScript.PokemonWalkAroundPlayerMovement
	ld de, .PokemonWalkAroundPlayerMovement
;> else:
.notDown
;>     moves = BillsHousePokemonWalkToMachineScript.PokemonWalkToMachineMovement
;> hSpriteIndex = BILLSHOUSE_BILL_POKEMON
	ld a, BILLSHOUSE_BILL_POKEMON
	ldh [hSpriteIndex], a
;> MoveSprite(moves)
	call MoveSprite
;> wBillsHouseCurScript = SCRIPT_BILLSHOUSE_POKEMON_ENTERS_MACHINE
	ld a, SCRIPT_BILLSHOUSE_POKEMON_ENTERS_MACHINE
	ld [wBillsHouseCurScript], a
	ret

.PokemonWalkToMachineMovement:
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db -1 ; end

; make Bill walk around the player
.PokemonWalkAroundPlayerMovement:
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_LEFT
	db NPC_MOVEMENT_UP
	db -1 ; end

;@ path: scripts/BillsHouse
;@ def BillsHousePokemonEntersMachineScript()
;@ Once Bill has walked into the machine: hide his Pokémon form and wait for the player to use the PC.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
BillsHousePokemonEntersMachineScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
;>     return
	ret nz
;> wToggleableObjectIndex = TOGGLE_BILL_POKEMON
	ld a, TOGGLE_BILL_POKEMON
	ld [wToggleableObjectIndex], a
;> HideObject()
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> set_event(EVENT_BILL_SAID_USE_CELL_SEPARATOR)
	ld hl, wEventFlags + $AB
	set (EVENT_BILL_SAID_USE_CELL_SEPARATOR) % 8, [hl]
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wBillsHouseCurScript = SCRIPT_BILLSHOUSE_BILL_EXITS_MACHINE
	ld a, SCRIPT_BILLSHOUSE_BILL_EXITS_MACHINE
	ld [wBillsHouseCurScript], a
	ret

;@ path: scripts/BillsHouse
;@ def BillsHouseBillExitsMachineScript()
;@ After the player ran the Cell Separator: Bill appears in human form at the machine and steps out.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
BillsHouseBillExitsMachineScript:
;> if not event(EVENT_USED_CELL_SEPARATOR_ON_BILL):
	ld a, [wEventFlags + $AB]
	bit (EVENT_USED_CELL_SEPARATOR_ON_BILL) % 8, a
;>     return
	ret z
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wSpriteIndex = BILLSHOUSE_BILL1
	ld a, BILLSHOUSE_BILL1
	ld [wSpriteIndex], a
;> hSpriteScreenYCoord = 0x0C
	ld a, $c
	ldh [hSpriteScreenYCoord], a
;> hSpriteScreenXCoord = 0x40
	ld a, $40
	ldh [hSpriteScreenXCoord], a
;> hSpriteMapYCoord = 6
	ld a, 6
	ldh [hSpriteMapYCoord], a
;> hSpriteMapXCoord = 5
	ld a, 5
	ldh [hSpriteMapXCoord], a
;> SetSpritePosition1()
	call SetSpritePosition1
;> wToggleableObjectIndex = TOGGLE_BILL_1
	ld a, TOGGLE_BILL_1
	ld [wToggleableObjectIndex], a
;> ShowObject()
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> DelayFrames(8)
	ld c, 8
	call DelayFrames
;> hSpriteIndex = BILLSHOUSE_BILL1
	ld a, BILLSHOUSE_BILL1
	ldh [hSpriteIndex], a
;> MoveSprite(BillsHouseBillExitsMachineScript.BillExitMachineMovement)
	ld de, .BillExitMachineMovement
	call MoveSprite
;> wBillsHouseCurScript = SCRIPT_BILLSHOUSE_CLEANUP
	ld a, SCRIPT_BILLSHOUSE_CLEANUP
	ld [wBillsHouseCurScript], a
	ret

.BillExitMachineMovement:
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_DOWN
	db -1 ; end

;@ path: scripts/BillsHouse
;@ def BillsHouseCleanupScript()
;@ When Bill has stepped out: give the controls back and note that the player has met Bill.
BillsHouseCleanupScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
;>     return
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> set_event(EVENT_MET_BILL_2)
	; this event seems redundant
	ld hl, wEventFlags + $AB
	set (EVENT_MET_BILL_2) % 8, [hl]
;> set_event(EVENT_MET_BILL)
	ld hl, wEventFlags + $AA
	set (EVENT_MET_BILL) % 8, [hl]
;> wBillsHouseCurScript = SCRIPT_BILLSHOUSE_DEFAULT
	ld a, SCRIPT_BILLSHOUSE_DEFAULT
	ld [wBillsHouseCurScript], a
	ret

;@ path: scripts/BillsHouse
;@ def BillsHousePCScript()
;@ The player uses the Cell Separator's PC; then back to the idle step.
BillsHousePCScript:
;> hTextID = TEXT_BILLSHOUSE_ACTIVATE_PC
	ld a, TEXT_BILLSHOUSE_ACTIVATE_PC
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wBillsHouseCurScript = SCRIPT_BILLSHOUSE_DEFAULT
	ld a, SCRIPT_BILLSHOUSE_DEFAULT
	ld [wBillsHouseCurScript], a
	ret

;@ path: scripts/BillsHouse
BillsHouse_TextPointers:
	dw BillsHouseBillPokemonText
DEF TEXT_BILLSHOUSE_BILL_POKEMON EQU 1
	dw BillsHouseBillSSTicketText
DEF TEXT_BILLSHOUSE_BILL_SS_TICKET EQU 2
	dw BillsHouseBillCheckOutMyRarePokemonText
DEF TEXT_BILLSHOUSE_BILL_CHECK_OUT_MY_RARE_POKEMON EQU 3
	dw BillsHouseActivatePCScript
DEF TEXT_BILLSHOUSE_ACTIVATE_PC EQU 4

;@ path: scripts/BillsHouse
BillsHouseActivatePCScript:
	db TX_SCRIPT_BILLS_PC

;@ path: scripts/BillsHouse
;@ def BillsHouseBillPokemonText() -> hl
;@ Bill as a Pokémon asks for help; whatever the answer, he goes into the Cell Separator.
;@ test: skip a text script: the code after text_asm is run by the text engine
BillsHouseBillPokemonText:
	db TX_START_ASM
;> PrintText(BillsHouseBillPokemonText.ImNotAPokemonText)
	ld hl, .ImNotAPokemonText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .answered_no
;>     PrintText(BillsHouseBillPokemonText.NoYouGottaHelpText)
;> PrintText(BillsHouseBillPokemonText.UseSeparationSystemText)
.use_machine
	ld hl, .UseSeparationSystemText
	call PrintText
;> wBillsHouseCurScript = SCRIPT_BILLSHOUSE_POKEMON_WALK_TO_MACHINE
	ld a, SCRIPT_BILLSHOUSE_POKEMON_WALK_TO_MACHINE
	ld [wBillsHouseCurScript], a
	jr .text_script_end
.answered_no
	ld hl, .NoYouGottaHelpText
	call PrintText
	jr .use_machine
.text_script_end
;> return TextScriptEnd()
	jp TextScriptEnd

.ImNotAPokemonText:
	db TX_FAR
	dw _BillsHouseBillImNotAPokemonText
	db BANK(_BillsHouseBillImNotAPokemonText)
	db TX_END

.UseSeparationSystemText:
	db TX_FAR
	dw _BillsHouseBillUseSeparationSystemText
	db BANK(_BillsHouseBillUseSeparationSystemText)
	db TX_END

.NoYouGottaHelpText:
	db TX_FAR
	dw _BillsHouseBillNoYouGottaHelpText
	db BANK(_BillsHouseBillNoYouGottaHelpText)
	db TX_END

;@ path: scripts/BillsHouse
;@ def BillsHouseBillSSTicketText() -> hl
;@ Bill, human again: gives the S.S. Ticket (if the bag has room) and moves Cerulean City's guard to his
;@ other post; afterwards he suggests the player go to the ship's party in his place.
;@ test: skip a text script: the code after text_asm is run by the text engine
BillsHouseBillSSTicketText:
	db TX_START_ASM
;> if not event(EVENT_GOT_SS_TICKET):
	ld a, [wEventFlags + $AB]
	bit (EVENT_GOT_SS_TICKET) % 8, a
	jr nz, .got_ss_ticket
;>     PrintText(BillsHouseBillSSTicketText.ThankYouText)
	ld hl, .ThankYouText
	call PrintText
;>     if not GiveItem(S_S_TICKET, 1):
	ld bc, ((S_S_TICKET) & $ff) << 8 + ((1) & $ff)
	call GiveItem
;>         PrintText(BillsHouseBillSSTicketText.SSTicketNoRoomText)
;>         return TextScriptEnd()
	jr nc, .bag_full
;>     PrintText(BillsHouseBillSSTicketText.SSTicketReceivedText)
	ld hl, .SSTicketReceivedText
	call PrintText
;>     set_event(EVENT_GOT_SS_TICKET)
	ld hl, wEventFlags + $AB
	set (EVENT_GOT_SS_TICKET) % 8, [hl]
;>     wToggleableObjectIndex = TOGGLE_CERULEAN_GUARD_1
	ld a, TOGGLE_CERULEAN_GUARD_1
	ld [wToggleableObjectIndex], a
;>     ShowObject()
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;>     wToggleableObjectIndex = TOGGLE_CERULEAN_GUARD_2
	ld a, TOGGLE_CERULEAN_GUARD_2
	ld [wToggleableObjectIndex], a
;>     HideObject()
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> PrintText(BillsHouseBillSSTicketText.WhyDontYouGoInsteadOfMeText)
.got_ss_ticket
	ld hl, .WhyDontYouGoInsteadOfMeText
	call PrintText
	jr .text_script_end
.bag_full
	ld hl, .SSTicketNoRoomText
	call PrintText
;> return TextScriptEnd()
.text_script_end
	jp TextScriptEnd

.ThankYouText:
	db TX_FAR
	dw _BillsHouseBillThankYouText
	db BANK(_BillsHouseBillThankYouText)
	db TX_END

.SSTicketReceivedText:
	db TX_FAR
	dw _SSTicketReceivedText
	db BANK(_SSTicketReceivedText)
	db TX_SOUND_GET_KEY_ITEM
	db TX_PROMPT_BUTTON
	db TX_END

.SSTicketNoRoomText:
	db TX_FAR
	dw _SSTicketNoRoomText
	db BANK(_SSTicketNoRoomText)
	db TX_END

.WhyDontYouGoInsteadOfMeText:
	db TX_FAR
	dw _BillsHouseBillWhyDontYouGoInsteadOfMeText
	db BANK(_BillsHouseBillWhyDontYouGoInsteadOfMeText)
	db TX_END

