	dw PokemonMansion1F_Object
;@ path: scripts/PokemonMansion1F
;@ def PokemonMansion1F_Script()
;@ Pokémon Mansion 1F's map script: first the map callback (Mansion1CheckReplaceSwitchDoorBlocks), then run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
PokemonMansion1F_Script:
;> Mansion1CheckReplaceSwitchDoorBlocks()
	call Mansion1CheckReplaceSwitchDoorBlocks
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wPokemonMansion1FCurScript = ExecuteCurMapScriptInTable(wPokemonMansion1FCurScript, Mansion1TrainerHeaders, PokemonMansion1F_ScriptPointers)
	ld hl, Mansion1TrainerHeaders
	ld de, PokemonMansion1F_ScriptPointers
	ld a, [wPokemonMansion1FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wPokemonMansion1FCurScript], a
	ret

;@ path: scripts/PokemonMansion1F
;@ def Mansion1CheckReplaceSwitchDoorBlocks()
;@ On entering the mansion's 1F: draw the gates the secret switch controls - one set open and the other
;@ closed, swapped when the switch is on.
;@ test: hLoadedROMBank = 0x11; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
Mansion1CheckReplaceSwitchDoorBlocks:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> if event(EVENT_MANSION_SWITCH_ON):        # the gates swap places
	ld a, [wEventFlags + $4F]
	bit (EVENT_MANSION_SWITCH_ON) % 8, a
	jr nz, .switchTurnedOn
;>@on1     Mansion1LoadHorizontalGateBlock(6, 12)
;>@on2     Mansion1LoadEmptyFloorTileBlock(3, 8)
;>@on3     Mansion1LoadEmptyFloorTileBlock(8, 10)
;>@on4     return Mansion1LoadEmptyFloorTileBlock(13, 13)
;> else:
;>     Mansion1LoadEmptyFloorTileBlock(6, 12)
	ld bc, ((6) & $ff) << 8 + ((12) & $ff)
	call Mansion1LoadEmptyFloorTileBlock
;>     Mansion1LoadHorizontalGateBlock(3, 8)
	ld bc, ((3) & $ff) << 8 + ((8) & $ff)
	call Mansion1LoadHorizontalGateBlock
;>     Mansion1LoadHorizontalGateBlock(8, 10)
	ld bc, ((8) & $ff) << 8 + ((10) & $ff)
	call Mansion1LoadHorizontalGateBlock
;>     return Mansion1LoadHorizontalGateBlock(13, 13)
	ld bc, ((13) & $ff) << 8 + ((13) & $ff)
	jp Mansion1LoadHorizontalGateBlock
.switchTurnedOn
;=@on1
	ld bc, ((6) & $ff) << 8 + ((12) & $ff)
	call Mansion1LoadHorizontalGateBlock
;=@on2
	ld bc, ((3) & $ff) << 8 + ((8) & $ff)
	call Mansion1LoadEmptyFloorTileBlock
;=@on3
	ld bc, ((8) & $ff) << 8 + ((10) & $ff)
	call Mansion1LoadEmptyFloorTileBlock
;=@on4
	ld bc, ((13) & $ff) << 8 + ((13) & $ff)
	jp Mansion1LoadEmptyFloorTileBlock

;@ path: scripts/PokemonMansion1F
;@ def Mansion1LoadHorizontalGateBlock(y: b, x: c)
;@ Put a closed gate (block $2D) at block (x, y) of the map.
;@ test: hLoadedROMBank = 0x11; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20); y = rand(0, 8); x = rand(0, 8)    # the bank this code runs in; no map redraw, blocks on the map
Mansion1LoadHorizontalGateBlock:
;> wNewTileBlockID = 0x2D
;> return Mansion1ReplaceBlock(y, x)
	ld a, $2d
	ld [wNewTileBlockID], a
	jr Mansion1ReplaceBlock

;@ path: scripts/PokemonMansion1F
;@ def Mansion1LoadEmptyFloorTileBlock(y: b, x: c)
;@ Put plain floor (block $0E, an open gate) at block (x, y) of the map.
;@ test: hLoadedROMBank = 0x11; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20); y = rand(0, 8); x = rand(0, 8)    # the bank this code runs in; no map redraw, blocks on the map
Mansion1LoadEmptyFloorTileBlock:
;> wNewTileBlockID = 0x0E
;> return Mansion1ReplaceBlock(y, x)
	ld a, $e
	ld [wNewTileBlockID], a
;@ path: scripts/PokemonMansion1F
;@ def Mansion1ReplaceBlock(y: b, x: c)
;@ Put block wNewTileBlockID at block (x, y) of the map.
;@ test: hLoadedROMBank = 0x11; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20); y = rand(0, 8); x = rand(0, 8)    # the bank this code runs in; no map redraw, blocks on the map
Mansion1ReplaceBlock:
;> predef(ReplaceTileBlock, bc=y << 8 | x)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	ret

;@ path: scripts/PokemonMansion1F
;@ def Mansion1Script_Switches()
;@ Checking a statue switch in the mansion (facing up at it): ask whether to press it.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
Mansion1Script_Switches::
;> if mem[wSpritePlayerStateData1FacingDirection] != SPRITE_FACING_UP:
;>     return
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	ret nz
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hTextID = TEXT_POKEMONMANSION1F_SWITCH
;> return DisplayTextID()
	ld a, TEXT_POKEMONMANSION1F_SWITCH
	ldh [hTextID], a
	jp DisplayTextID

