;@ path: scripts/PokemonMansion1F
;@ def PokemonMansion1FSwitchText() -> hl
;@ The secret switch: "Press it?" - on yes, the switch flips (on/off) and the map redraws its gates the
;@ next time the map script runs.
;@ test: skip a text script: the code after text_asm is run by the text engine
PokemonMansion1FSwitchText:
	db TX_START_ASM
;> PrintText(PokemonMansion1FSwitchText.Text)
	ld hl, .Text
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .not_pressed
;>@early     PrintText(PokemonMansion1FSwitchText.NotPressedText)
;> else:
;>     wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;>     wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1     # redraw the gates
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
;>     PrintText(PokemonMansion1FSwitchText.PressedText)
	ld hl, .PressedText
	call PrintText
;>     PlaySound(SFX_GO_INSIDE)
	ld a, SFX_GO_INSIDE
	call PlaySound
;>     if event(EVENT_MANSION_SWITCH_ON):
	ld hl, wEventFlags + $4F
	bit (EVENT_MANSION_SWITCH_ON) % 8, [hl]
	set (EVENT_MANSION_SWITCH_ON) % 8, [hl]
	jr z, .done
;>         reset_event(EVENT_MANSION_SWITCH_ON)
;>     else:
;>         set_event(EVENT_MANSION_SWITCH_ON)
	res (EVENT_MANSION_SWITCH_ON) % 8, [hl]
	jr .done
.not_pressed
;=@early
	ld hl, .NotPressedText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _PokemonMansion1FSwitchText
	db BANK(_PokemonMansion1FSwitchText)
	db TX_END

.PressedText:
	db TX_FAR
	dw _PokemonMansion1FSwitchPressedText
	db BANK(_PokemonMansion1FSwitchPressedText)
	db TX_END

.NotPressedText:
	db TX_FAR
	dw _PokemonMansion1FSwitchNotPressedText
	db BANK(_PokemonMansion1FSwitchNotPressedText)
	db TX_END
