SeafoamIslands1F_h::
	db CAVERN
	db $9, $F
	dw SeafoamIslands1F_Blocks
	dw SeafoamIslands1F_TextPointers
	dw SeafoamIslands1F_Script
	db 0
	dw SeafoamIslands1F_Object
;@ path: scripts/SeafoamIslands1F
;@ def SeafoamIslands1F_Script()
;@ Seafoam Islands 1F: a boulder pushed into one of the two holes falls to B1F (hidden here, shown there);
;@ otherwise, stepping into a hole drops the player to B1F.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslands1F_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> set_event(EVENT_IN_SEAFOAM_ISLANDS)
	ld hl, wEventFlags + $A0
	set (EVENT_IN_SEAFOAM_ISLANDS) % 8, [hl]
;> pushed = wMiscFlags >> BIT_PUSHED_BOULDER & 1
	ld hl, wMiscFlags
	bit BIT_PUSHED_BOULDER, [hl]
;> wMiscFlags &= ~(1 << BIT_PUSHED_BOULDER)
	res BIT_PUSHED_BOULDER, [hl]
;> if not pushed:
	jr z, .noBoulderWasPushed
;>@map     wDungeonWarpDestinationMap = SEAFOAM_ISLANDS_B1F
;>@warp     return IsPlayerOnDungeonWarp(Seafoam1HolesCoords)
;> if not CheckBoulderCoords(Seafoam1HolesCoords):      # no boulder fell down a hole
;>     return
	ld hl, Seafoam1HolesCoords
	call CheckBoulderCoords
	ret nc
;> if wCoordIndex == 1:                # (hl: the byte with both boulders' flags)
	ld hl, wEventFlags + $A1
	ld a, [wCoordIndex]
	cp $1
	jr nz, .boulder2FellDownHole
;>     set_event(EVENT_SEAFOAM1_BOULDER1_DOWN_HOLE)
	set (EVENT_SEAFOAM1_BOULDER1_DOWN_HOLE) % 8, [hl]
;>     wObjectToHide = TOGGLE_SEAFOAM_ISLANDS_1F_BOULDER_1
	ld a, TOGGLE_SEAFOAM_ISLANDS_1F_BOULDER_1
	ld [wObjectToHide], a
;>     wObjectToShow = TOGGLE_SEAFOAM_ISLANDS_B1F_BOULDER_1
	ld a, TOGGLE_SEAFOAM_ISLANDS_B1F_BOULDER_1
	ld [wObjectToShow], a
	jr .hideAndShowBoulderObjects
.boulder2FellDownHole
;> else:
;>     set_event(EVENT_SEAFOAM1_BOULDER2_DOWN_HOLE)
	set (EVENT_SEAFOAM1_BOULDER2_DOWN_HOLE) % 8, [hl]
;>     wObjectToHide = TOGGLE_SEAFOAM_ISLANDS_1F_BOULDER_2
	ld a, TOGGLE_SEAFOAM_ISLANDS_1F_BOULDER_2
	ld [wObjectToHide], a
;>     wObjectToShow = TOGGLE_SEAFOAM_ISLANDS_B1F_BOULDER_2
	ld a, TOGGLE_SEAFOAM_ISLANDS_B1F_BOULDER_2
	ld [wObjectToShow], a
.hideAndShowBoulderObjects
;> wToggleableObjectIndex = wObjectToHide
	ld a, [wObjectToHide]
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = wObjectToShow
	ld a, [wObjectToShow]
	ld [wToggleableObjectIndex], a
;> return predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	jp Predef
.noBoulderWasPushed
;=@map
	ld a, SEAFOAM_ISLANDS_B1F
	ld [wDungeonWarpDestinationMap], a
;=@warp
	ld hl, Seafoam1HolesCoords
	jp IsPlayerOnDungeonWarp

