	db TEXT_SEAFOAMISLANDS1F_BOULDER1
	db SPRITE_BOULDER
	db 7 + 4
	db 26 + 4
	db STAY
	db BOULDER_MOVEMENT_BYTE_2
	db TEXT_SEAFOAMISLANDS1F_BOULDER2

	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_1F_WIDTH) + ((SEAFOAM_ISLANDS_1F_WIDTH) + 6) * (($11) >> 1) + ((4) >> 1))
	db $11, 4
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_1F_WIDTH) + ((SEAFOAM_ISLANDS_1F_WIDTH) + 6) * (($11) >> 1) + ((5) >> 1))
	db $11, 5
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_1F_WIDTH) + ((SEAFOAM_ISLANDS_1F_WIDTH) + 6) * (($11) >> 1) + (($1A) >> 1))
	db $11, $1A
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_1F_WIDTH) + ((SEAFOAM_ISLANDS_1F_WIDTH) + 6) * (($11) >> 1) + (($1B) >> 1))
	db $11, $1B
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_1F_WIDTH) + ((SEAFOAM_ISLANDS_1F_WIDTH) + 6) * ((5) >> 1) + ((7) >> 1))
	db 5, 7
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_1F_WIDTH) + ((SEAFOAM_ISLANDS_1F_WIDTH) + 6) * ((3) >> 1) + (($19) >> 1))
