;@ path: scripts/VictoryRoad3F
;@ def VictoryRoad3F_Script()
;@ Victory Road 3F's map script: first the map callback (VictoryRoad3FCheckBoulderEventScript), then run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
VictoryRoad3F_Script:
;> VictoryRoad3FCheckBoulderEventScript()
	call VictoryRoad3FCheckBoulderEventScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wVictoryRoad3FCurScript = ExecuteCurMapScriptInTable(wVictoryRoad3FCurScript, VictoryRoad3TrainerHeaders, VictoryRoad3F_ScriptPointers)
	ld hl, VictoryRoad3TrainerHeaders
	ld de, VictoryRoad3F_ScriptPointers
	ld a, [wVictoryRoad3FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wVictoryRoad3FCurScript], a
	ret

;@ path: scripts/VictoryRoad3F
;@ def VictoryRoad3FCheckBoulderEventScript()
;@ On entering Victory Road 3F: once a boulder sits on the floor switch, draw the opened passage (block $1D).
;@ test: hLoadedROMBank = 0x11; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
VictoryRoad3FCheckBoulderEventScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded or not event(EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH1):
;>     return
	ret z
	ld hl, wEventFlags + $CC
	bit (EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH1) % 8, [hl]
	ret z
;> wNewTileBlockID = 0x1D
	ld a, $1d
	ld [wNewTileBlockID], a
;> return predef(ReplaceTileBlock, bc=5 << 8 | 3)
	ld bc, ((5) & $ff) << 8 + ((3) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/VictoryRoad3F
VictoryRoad3F_ScriptPointers:
	dw VictoryRoad3FDefaultScript
DEF SCRIPT_VICTORYROAD3F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_VICTORYROAD3F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_VICTORYROAD3F_END_BATTLE EQU 2

;@ path: scripts/VictoryRoad3F
;@ def VictoryRoad3FDefaultScript()
;@ Victory Road 3F each step: a boulder pushed onto the switch opens the passage; one pushed into the hole
;@ falls to 2F. The player stepping into the hole drops to 2F (the switch spot is no warp); otherwise the
;@ trainers watch for the player.
;@ test: skip the switch and hole spots sit under a local label, which the pseudo-code can only name
VictoryRoad3FDefaultScript:
;> pushed = wMiscFlags >> BIT_PUSHED_BOULDER & 1
	ld hl, wMiscFlags
	bit BIT_PUSHED_BOULDER, [hl]
;> wMiscFlags &= ~(1 << BIT_PUSHED_BOULDER)
	res BIT_PUSHED_BOULDER, [hl]
;> if pushed and CheckBoulderCoords(VictoryRoad3FDefaultScript.SwitchOrHoleCoords):
	jp z, .check_switch_hole
	ld hl, .SwitchOrHoleCoords
	call CheckBoulderCoords
	jp nc, .check_switch_hole
;>     if wCoordIndex == 1:                      # on the switch
	ld a, [wCoordIndex]
	cp $1
	jr nz, .handle_hole
;>         wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
;>         set_event(EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH1)
	ld hl, wEventFlags + $CC
	set (EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH1) % 8, [hl]
;>         return
	ret
.handle_hole
;>     fell = event(EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH2)
	ld hl, wEventFlags + $CC
	bit (EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH2) % 8, [hl]
;>     set_event(EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH2)
	set (EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH2) % 8, [hl]
	jr nz, .check_switch_hole
;>     if not fell:                              # into the hole
;>         wToggleableObjectIndex = TOGGLE_VICTORY_ROAD_3F_BOULDER
	ld a, TOGGLE_VICTORY_ROAD_3F_BOULDER
	ld [wToggleableObjectIndex], a
;>         predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;>         wToggleableObjectIndex = TOGGLE_VICTORY_ROAD_2F_BOULDER
	ld a, TOGGLE_VICTORY_ROAD_2F_BOULDER
	ld [wToggleableObjectIndex], a
;>         return predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	jp Predef

.SwitchOrHoleCoords:
	; switch
	db 5, 3
	; hole
	db 15, 23
	db -1 ; end

.check_switch_hole
;> wDungeonWarpDestinationMap = VICTORY_ROAD_2F
	ld a, VICTORY_ROAD_2F
	ld [wDungeonWarpDestinationMap], a
;> IsPlayerOnDungeonWarp(VictoryRoad3FDefaultScript.SwitchOrHoleCoords)
	ld hl, .SwitchOrHoleCoords
	call IsPlayerOnDungeonWarp
;> if wCoordIndex == 1:                          # the switch is not a hole
	ld a, [wCoordIndex]
	cp $1
	jr nz, .hole
;>     wStatusFlags3 &= ~(1 << BIT_ON_DUNGEON_WARP)
	ld hl, wStatusFlags3
	res BIT_ON_DUNGEON_WARP, [hl]
;>     wStatusFlags6 &= ~(1 << BIT_DUNGEON_WARP)
	ld hl, wStatusFlags6
	res BIT_DUNGEON_WARP, [hl]
;>     return
	ret
.hole
;> if not wStatusFlags3 >> BIT_ON_DUNGEON_WARP & 1:
;>     return CheckFightingMapTrainers()
	ld a, [wStatusFlags3]
	bit BIT_ON_DUNGEON_WARP, a
	jp z, CheckFightingMapTrainers
	ret

