;@ path: scripts/RocketHideoutB1F
;@ def RocketHideoutB1F_Script()
;@ Rocket Hideout B1F's map script: first the map callback (RocketHideoutB1FDoorCallbackScript), then run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutB1F_Script:
;> RocketHideoutB1FDoorCallbackScript()
	call RocketHideoutB1FDoorCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRocketHideoutB1FCurScript = ExecuteCurMapScriptInTable(wRocketHideoutB1FCurScript, RocketHideout1TrainerHeaders, RocketHideoutB1F_ScriptPointers)
	ld hl, RocketHideout1TrainerHeaders
	ld de, RocketHideoutB1F_ScriptPointers
	ld a, [wRocketHideoutB1FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wRocketHideoutB1FCurScript], a
	ret

;@ path: scripts/RocketHideoutB1F
;@ def RocketHideoutB1FDoorCallbackScript()
;@ On entering the hideout's B1F: the door stays shut (block $54) until its last Rocket is beaten, then it is
;@ open floor - with the door sound, which plays on every visit because the "entered" event is only
;@ checked, never set.
;@ test: hLoadedROMBank = 0x11; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
RocketHideoutB1FDoorCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> if event(EVENT_ENTERED_ROCKET_HIDEOUT):
;>     wNewTileBlockID = 0x0E                    # floor
	ld a, [wEventFlags + $CE]
	bit (EVENT_ENTERED_ROCKET_HIDEOUT) % 8, a
	jr nz, .door_open
;> elif event(EVENT_BEAT_ROCKET_HIDEOUT_1_TRAINER_4):
	bit (EVENT_BEAT_ROCKET_HIDEOUT_1_TRAINER_4) % 8, a
	jr nz, .play_sound_door_open
	ld a, $54 ; Door Block
	jr .set_door_block
.play_sound_door_open
;>     PlaySound(SFX_GO_INSIDE)
	ld a, SFX_GO_INSIDE
	call PlaySound
	; BUG: should be SetEvent to avoid the SFX playing every time you enter the map
	ld hl, wEventFlags + $CE
	bit (EVENT_ENTERED_ROCKET_HIDEOUT) % 8, [hl]
.door_open
;>     wNewTileBlockID = 0x0E
	ld a, $e ; Floor Block
.set_door_block
;> else:
;>     wNewTileBlockID = 0x54                    # door
	ld [wNewTileBlockID], a
;> return predef(ReplaceTileBlock, bc=8 << 8 | 12)
	ld bc, ((8) & $ff) << 8 + ((12) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

