;@ def RocketHideoutB2F_Script()
;@ Rocket Hideout B2F's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutB2F_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRocketHideoutB2FCurScript = ExecuteCurMapScriptInTable(wRocketHideoutB2FCurScript, RocketHideout2TrainerHeaders, RocketHideoutB2F_ScriptPointers)
	ld hl, RocketHideout2TrainerHeaders
	ld de, RocketHideoutB2F_ScriptPointers
	ld a, [wRocketHideoutB2FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wRocketHideoutB2FCurScript], a
	ret

