RocketHideoutB2F_ScriptPointers:
	dw RocketHideoutB2FDefaultScript
DEF SCRIPT_ROCKETHIDEOUTB2F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROCKETHIDEOUTB2F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROCKETHIDEOUTB2F_END_BATTLE EQU 2
	dw RocketHideoutB2FPlayerSpinningScript
DEF SCRIPT_ROCKETHIDEOUTB2F_PLAYER_SPINNING EQU 3

;@ path: scripts/RocketHideoutB2F
;@ def RocketHideoutB2FDefaultScript()
;@ Each step on B2F: stepping on an arrow tile spins the player along its path (simulated input from the
;@ floor's arrow list, with the spinning sound); otherwise the trainers watch for the player.
;@ test: skip the arrow lookup's pseudo-code does not give back the $FF it leaves in a when no arrow matched
RocketHideoutB2FDefaultScript:
;> DecodeArrowMovementRLE(RocketHideout2ArrowTilePlayerMovement, wYCoord, wXCoord)
	ld a, [wYCoord]
	ld b, a
	ld a, [wXCoord]
	ld c, a
	ld hl, RocketHideout2ArrowTilePlayerMovement
	call DecodeArrowMovementRLE
;> if a == 0xFF:                                 # not on an arrow
;>     return CheckFightingMapTrainers()
	cp $ff
	jp z, CheckFightingMapTrainers
;> wMovementFlags |= 1 << BIT_SPINNING
	ld hl, wMovementFlags
	set BIT_SPINNING, [hl]
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> PlaySound(SFX_ARROW_TILES)
	ld a, SFX_ARROW_TILES
	call PlaySound
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wCurMapScript = SCRIPT_ROCKETHIDEOUTB2F_PLAYER_SPINNING
	ld a, SCRIPT_ROCKETHIDEOUTB2F_PLAYER_SPINNING
	ld [wCurMapScript], a
	ret

