;@ path: scripts/RocketHideoutB2F
;@ def RocketHideoutB2FPlayerSpinningScript()
;@ While the player spins along the arrows, animate the arrow tiles; at the end, give the controls back.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutB2FPlayerSpinningScript:
;> if wSimulatedJoypadStatesIndex:       # still spinning
;>     return LoadSpinnerArrowTiles()
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	jr nz, LoadSpinnerArrowTiles
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wMovementFlags &= ~(1 << BIT_SPINNING)
	ld hl, wMovementFlags
	res BIT_SPINNING, [hl]
;> wCurMapScript = SCRIPT_ROCKETHIDEOUTB2F_DEFAULT
	ld a, SCRIPT_ROCKETHIDEOUTB2F_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/RocketHideoutB2F
;@ def LoadSpinnerArrowTiles()
;@ One step of the spinning animation: turn the player to the next facing direction and copy the next frame
;@ of the arrow tiles (Rocket Hideout or Viridian Gym set, the two frames alternating each step) into VRAM.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
LoadSpinnerArrowTiles::
;> img = mem[wSpritePlayerStateData1ImageIndex]
	ld a, [wSpritePlayerStateData1ImageIndex]
;> i = img >> 2
	srl a
	srl a
;> next_img = mem[SpinnerPlayerFacingDirections + i]     # the next direction round
	ld hl, SpinnerPlayerFacingDirections
	ld c, a
	ld b, $0
	add hl, bc
	ld a, [hl]
;> mem[wSpritePlayerStateData1ImageIndex] = next_img
	ld [wSpritePlayerStateData1ImageIndex], a
;> arrows = FacilitySpinnerArrows if wCurMapTileset == FACILITY else GymSpinnerArrows
	ld a, [wCurMapTileset]
	cp FACILITY
	ld hl, FacilitySpinnerArrows
	jr z, .gotSpinnerArrows
	ld hl, GymSpinnerArrows
.gotSpinnerArrows
;> if not wSimulatedJoypadStatesIndex & 1:
	ld a, [wSimulatedJoypadStatesIndex]
	bit 0, a ; even or odd?
	jr nz, .alternateGraphics
;>     arrows += 6 * 4                           # the other frame
	ld de, 6 * 4
	add hl, de
.alternateGraphics
;>@loop for i in range(4):                       # entries: source, tile count, bank, destination
	ld a, $4
	ld bc, $0
.loop
	push af
	push hl
	push bc
;>     e = arrows + 6 * i
	add hl, bc
;>     source = mem16[e]
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
;>     count, bank = mem[e + 2], mem[e + 3]
	ld a, [hli]
	ld c, a
	ld a, [hli]
	ld b, a
;>     dest = mem16[e + 4]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     CopyVideoData(dest, source, bank, count)
	call CopyVideoData
;=@loop
	pop bc
	ld a, $6
	add c
	ld c, a
;=@loop
	pop hl
	pop af
	dec a
	jr nz, .loop
	ret


