	dw SpinnerArrowAnimTiles + TILE_SIZE * 1
	db 1
	db BANK(SpinnerArrowAnimTiles)
	dw vTileset + TILE_SIZE * $21
	dw SpinnerArrowAnimTiles + TILE_SIZE * 2
	db 1
	db BANK(SpinnerArrowAnimTiles)
	dw vTileset + TILE_SIZE * $30
	dw SpinnerArrowAnimTiles + TILE_SIZE * 3
	db 1
	db BANK(SpinnerArrowAnimTiles)
	dw vTileset + TILE_SIZE * $31
	dw Facility_GFX + TILE_SIZE * $20
	db 1
	db BANK(Facility_GFX)
	dw vTileset + TILE_SIZE * $20
	dw Facility_GFX + TILE_SIZE * $21
	db 1
	db BANK(Facility_GFX)
	dw vTileset + TILE_SIZE * $21
	dw Facility_GFX + TILE_SIZE * $30
	db 1
	db BANK(Facility_GFX)
	dw vTileset + TILE_SIZE * $30
	dw Facility_GFX + TILE_SIZE * $31
	db 1
	db BANK(Facility_GFX)
	dw vTileset + TILE_SIZE * $31

;@ path: scripts/RocketHideoutB2F
GymSpinnerArrows:
	dw SpinnerArrowAnimTiles + TILE_SIZE * 1
	db 1
