	dw vTileset + TILE_SIZE * $3d
	dw SpinnerArrowAnimTiles + TILE_SIZE * 0
	db 1
	db BANK(SpinnerArrowAnimTiles)
	dw vTileset + TILE_SIZE * $4c
	dw SpinnerArrowAnimTiles + TILE_SIZE * 2
	db 1
	db BANK(SpinnerArrowAnimTiles)
