;@ path: scripts/RocketHideoutB3F
;@ def RocketHideoutB3F_Script()
;@ Rocket Hideout B3F's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutB3F_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRocketHideoutB3FCurScript = ExecuteCurMapScriptInTable(wRocketHideoutB3FCurScript, RocketHideout3TrainerHeaders, RocketHideoutB3F_ScriptPointers)
	ld hl, RocketHideout3TrainerHeaders
	ld de, RocketHideoutB3F_ScriptPointers
	ld a, [wRocketHideoutB3FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wRocketHideoutB3FCurScript], a
	ret

;@ path: scripts/RocketHideoutB3F
RocketHideoutB3F_ScriptPointers:
	dw RocketHideoutB3FDefaultScript
DEF SCRIPT_ROCKETHIDEOUTB3F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROCKETHIDEOUTB3F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROCKETHIDEOUTB3F_END_BATTLE EQU 2
	dw RocketHideoutB3FPlayerSpinningScript
DEF SCRIPT_ROCKETHIDEOUTB3F_PLAYER_SPINNING EQU 3

;@ path: scripts/RocketHideoutB3F
;@ def RocketHideoutB3FDefaultScript()
;@ Each step on B3F: stepping on an arrow tile spins the player along its path; otherwise the trainers
;@ watch for the player.
;@ test: skip the arrow lookup's pseudo-code does not give back the $FF it leaves in a when no arrow matched
RocketHideoutB3FDefaultScript:
;> DecodeArrowMovementRLE(RocketHideout3ArrowTilePlayerMovement, wYCoord, wXCoord)
	ld a, [wYCoord]
	ld b, a
	ld a, [wXCoord]
	ld c, a
	ld hl, RocketHideout3ArrowTilePlayerMovement
	call DecodeArrowMovementRLE
;> if a == 0xFF:                                 # not on an arrow
;>     return CheckFightingMapTrainers()
	cp $ff
	jp z, CheckFightingMapTrainers
;> wMovementFlags |= 1 << BIT_SPINNING
	ld hl, wMovementFlags
	set BIT_SPINNING, [hl]
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> PlaySound(SFX_ARROW_TILES)
	ld a, SFX_ARROW_TILES
	call PlaySound
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wCurMapScript = SCRIPT_ROCKETHIDEOUTB3F_PLAYER_SPINNING
	ld a, SCRIPT_ROCKETHIDEOUTB3F_PLAYER_SPINNING
	ld [wCurMapScript], a
	ret

