;@ path: scripts/RocketHideoutB4F
;@ def RocketHideoutB4F_Script()
;@ Rocket Hideout B4F's map script: first the map callback (RocketHideoutB4FDoorCallbackScript), then run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutB4F_Script:
;> RocketHideoutB4FDoorCallbackScript()
	call RocketHideoutB4FDoorCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRocketHideoutB4FCurScript = ExecuteCurMapScriptInTable(wRocketHideoutB4FCurScript, RocketHideout4TrainerHeaders, RocketHideoutB4F_ScriptPointers)
	ld hl, RocketHideout4TrainerHeaders
	ld de, RocketHideoutB4F_ScriptPointers
	ld a, [wRocketHideoutB4FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wRocketHideoutB4FCurScript], a
	ret

;@ path: scripts/RocketHideoutB4F
;@ def RocketHideoutB4FDoorCallbackScript()
;@ On entering B4F: the door to Giovanni stays shut (block $2D) until both Rockets guarding it are beaten;
;@ then, with the door sound the first time, it is open floor.
;@ test: hLoadedROMBank = 0x11; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
RocketHideoutB4FDoorCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> if event(EVENT_ROCKET_HIDEOUT_4_DOOR_UNLOCKED):
;>     wNewTileBlockID = 0x0E                    # floor
	ld a, [wEventFlags + $D4]
	bit (EVENT_ROCKET_HIDEOUT_4_DOOR_UNLOCKED) % 8, a
	jr nz, .door_already_unlocked
;> elif event(EVENT_BEAT_ROCKET_HIDEOUT_4_TRAINER_0) and event(EVENT_BEAT_ROCKET_HIDEOUT_4_TRAINER_1):
	and (1 << ((EVENT_BEAT_ROCKET_HIDEOUT_4_TRAINER_0) % 8)) | (1 << ((EVENT_BEAT_ROCKET_HIDEOUT_4_TRAINER_1) % 8))
	cp (1 << ((EVENT_BEAT_ROCKET_HIDEOUT_4_TRAINER_0) % 8)) | (1 << ((EVENT_BEAT_ROCKET_HIDEOUT_4_TRAINER_1) % 8))
	jr z, .unlock_door
	ld a, $2d ; Door block
	jr .set_block
.unlock_door
;>     PlaySound(SFX_GO_INSIDE)
	ld a, SFX_GO_INSIDE
	call PlaySound
;>     set_event(EVENT_ROCKET_HIDEOUT_4_DOOR_UNLOCKED)
	ld hl, wEventFlags + $D4
	set (EVENT_ROCKET_HIDEOUT_4_DOOR_UNLOCKED) % 8, [hl]
.door_already_unlocked
;>     wNewTileBlockID = 0x0E
	ld a, $e ; Floor block
.set_block
;> else:
;>     wNewTileBlockID = 0x2D                    # door
	ld [wNewTileBlockID], a
;> return predef(ReplaceTileBlock, bc=5 << 8 | 12)
	ld bc, ((5) & $ff) << 8 + ((12) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/RocketHideoutB4F
;@ def RocketHideoutB4FSetDefaultScript()
;@ Back to B4F's default step, with the controls given back.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutB4FSetDefaultScript:
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wRocketHideoutB4FCurScript = SCRIPT_ROCKETHIDEOUTB4F_DEFAULT
	ld [wRocketHideoutB4FCurScript], a
;> wCurMapScript = SCRIPT_ROCKETHIDEOUTB4F_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/RocketHideoutB4F
RocketHideoutB4F_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_ROCKETHIDEOUTB4F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROCKETHIDEOUTB4F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROCKETHIDEOUTB4F_END_BATTLE EQU 2
	dw RocketHideoutB4FBeatGiovanniScript
DEF SCRIPT_ROCKETHIDEOUTB4F_BEAT_GIOVANNI EQU 3

;@ path: scripts/RocketHideoutB4F
;@ def RocketHideoutB4FBeatGiovanniScript()
;@ After the battle with Giovanni: lost, start over; won, "I hope we meet again", and in a fade to black
;@ Giovanni disappears and the Silph Scope appears where he stood.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutB4FBeatGiovanniScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return RocketHideoutB4FSetDefaultScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, RocketHideoutB4FSetDefaultScript
;> UpdateSprites()
	call UpdateSprites
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> set_event(EVENT_BEAT_ROCKET_HIDEOUT_GIOVANNI)
	ld hl, wEventFlags + $D4
	set (EVENT_BEAT_ROCKET_HIDEOUT_GIOVANNI) % 8, [hl]
;> hTextID = TEXT_ROCKETHIDEOUTB4F_GIOVANNI_HOPE_WE_MEET_AGAIN
	ld a, TEXT_ROCKETHIDEOUTB4F_GIOVANNI_HOPE_WE_MEET_AGAIN
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> GBFadeOutToBlack()
	call GBFadeOutToBlack
;> wToggleableObjectIndex = TOGGLE_ROCKET_HIDEOUT_B4F_GIOVANNI
	ld a, TOGGLE_ROCKET_HIDEOUT_B4F_GIOVANNI
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_ROCKET_HIDEOUT_B4F_ITEM_4
	ld a, TOGGLE_ROCKET_HIDEOUT_B4F_ITEM_4
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> UpdateSprites()
	call UpdateSprites
;> GBFadeInFromBlack()
	call GBFadeInFromBlack
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
;> wRocketHideoutB4FCurScript = SCRIPT_ROCKETHIDEOUTB4F_DEFAULT
	ld a, SCRIPT_ROCKETHIDEOUTB4F_DEFAULT
	ld [wRocketHideoutB4FCurScript], a
;> wCurMapScript = SCRIPT_ROCKETHIDEOUTB4F_DEFAULT
	ld [wCurMapScript], a
	ret

