	dw wEventFlags + (EVENT_BEAT_ROCKET_HIDEOUT_4_TRAINER_0 - $2) / 8
	dw RocketHideoutB4FRocket1BattleText, RocketHideoutB4FRocket1AfterBattleText, RocketHideoutB4FRocket1EndBattleText, RocketHideoutB4FRocket1EndBattleText
