	db $3
	db 0 << 4
	dw wEventFlags + (EVENT_BEAT_ROCKET_HIDEOUT_4_TRAINER_1 - $3) / 8
	dw RocketHideoutB4FRocket2BattleText, RocketHideoutB4FRocket2AfterBattleText, RocketHideoutB4FRocket2EndBattleText, RocketHideoutB4FRocket2EndBattleText
