RocketHideout4TrainerHeader2:
	db $4
	db 1 << 4
	dw wEventFlags + (EVENT_BEAT_ROCKET_HIDEOUT_4_TRAINER_2 - $4) / 8
	dw RocketHideoutB4FRocket3BattleText, RocketHideoutB4FRocket3AfterBattleText, RocketHideoutB4FRocket3EndBattleText, RocketHideoutB4FRocket3EndBattleText
	db -1 ; end

;@ path: scripts/RocketHideoutB4F
;@ def RocketHideoutB4FGiovanniText() -> hl
;@ Giovanni in his hideout: before the battle, "I'm impressed you got here" and he engages the player;
;@ afterwards, "I hope we meet again".
;@ test: skip a text script: the code after text_asm is run by the text engine
RocketHideoutB4FGiovanniText:
	db TX_START_ASM
;> if event(EVENT_BEAT_ROCKET_HIDEOUT_GIOVANNI):
	ld a, [wEventFlags + $D4]
	bit (EVENT_BEAT_ROCKET_HIDEOUT_GIOVANNI) % 8, a
	jp nz, .beat_giovanni
;>@hope     PrintText(RocketHideoutB4FGiovanniHopeWeMeetAgainText)
;> else:
;>     PrintText(RocketHideoutB4FGiovanniText.ImpressedYouGotHereText)
	ld hl, .ImpressedYouGotHereText
	call PrintText
;>     wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;>     SaveEndBattleTextPointers(RocketHideoutB4FGiovanniText.WhatCannotBeText, RocketHideoutB4FGiovanniText.WhatCannotBeText)
	ld hl, .WhatCannotBeText
	ld de, .WhatCannotBeText
	call SaveEndBattleTextPointers
;>     wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;>     EngageMapTrainer()
	call EngageMapTrainer
;>     InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;>     hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;>     wRocketHideoutB4FCurScript = SCRIPT_ROCKETHIDEOUTB4F_BEAT_GIOVANNI
	ld a, SCRIPT_ROCKETHIDEOUTB4F_BEAT_GIOVANNI
	ld [wRocketHideoutB4FCurScript], a
;>     wCurMapScript = SCRIPT_ROCKETHIDEOUTB4F_BEAT_GIOVANNI
	ld [wCurMapScript], a
	jr .done
.beat_giovanni
;=@hope
	ld hl, RocketHideoutB4FGiovanniHopeWeMeetAgainText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.ImpressedYouGotHereText:
	db TX_FAR
	dw _RocketHideoutB4FGiovanniImpressedYouGotHereText
	db BANK(_RocketHideoutB4FGiovanniImpressedYouGotHereText)
	db TX_END

.WhatCannotBeText:
	db TX_FAR
	dw _RocketHideoutB4FGiovanniWhatCannotBeText
	db BANK(_RocketHideoutB4FGiovanniWhatCannotBeText)
	db TX_END

