;@ path: scripts/RocketHideoutB4F
;@ def RocketHideoutB4FRocket3AfterBattleText() -> hl
;@ The third Rocket after his defeat: his line, and the first time he drops the Lift Key.
;@ test: skip a text script: the code after text_asm is run by the text engine
RocketHideoutB4FRocket3AfterBattleText:
	db TX_START_ASM
;> PrintText(RocketHideoutB4FRocket3AfterBattleText.Text)
	ld hl, .Text
	call PrintText
;> dropped = event(EVENT_ROCKET_DROPPED_LIFT_KEY)
	ld hl, wEventFlags + $D4
	bit (EVENT_ROCKET_DROPPED_LIFT_KEY) % 8, [hl]
;> set_event(EVENT_ROCKET_DROPPED_LIFT_KEY)
	set (EVENT_ROCKET_DROPPED_LIFT_KEY) % 8, [hl]
;> if not dropped:
	jr nz, .done
;>     wToggleableObjectIndex = TOGGLE_ROCKET_HIDEOUT_B4F_ITEM_5
	ld a, TOGGLE_ROCKET_HIDEOUT_B4F_ITEM_5
	ld [wToggleableObjectIndex], a
;>     predef(ShowObject)                    # the Lift Key appears on the floor
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _RocketHideoutB4FRocket3AfterBattleText
	db BANK(_RocketHideoutB4FRocket3AfterBattleText)
	db TX_END
