RocketHideoutElevator_h::
	db LOBBY
	db $4, $3
	dw RocketHideoutElevator_Blocks
	dw RocketHideoutElevator_TextPointers
	dw RocketHideoutElevator_Script
	db 0
	dw RocketHideoutElevator_Object
;@ path: scripts/RocketHideoutElevator
;@ def RocketHideoutElevator_Script()
;@ The hideout's elevator: on entering, its door leads back where the player came from; after a ride, the
;@ shaking. Its texts draw their own box and do not wait for a button.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutElevator_Script:
;> loaded1 = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if loaded1:
;>     RocketHideoutElevatorStoreWarpEntriesScript()
	push hl
	call nz, RocketHideoutElevatorStoreWarpEntriesScript
;> used_elevator = wCurrentMapScriptFlags >> BIT_CUR_MAP_USED_ELEVATOR & 1
	pop hl
	bit BIT_CUR_MAP_USED_ELEVATOR, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_USED_ELEVATOR)
	res BIT_CUR_MAP_USED_ELEVATOR, [hl]
;> if used_elevator:
;>     RocketHideoutElevatorShakeScript()
	call nz, RocketHideoutElevatorShakeScript
;> wAutoTextBoxDrawingControl = 0
	xor a
	ld [wAutoTextBoxDrawingControl], a
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	inc a
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
	ret

;@ path: scripts/RocketHideoutElevator
;@ def RocketHideoutElevatorStoreWarpEntriesScript()
;@ Point both elevator doors back to where the player came from: the warp and map the player arrived from
;@ go into the elevator's two warp entries.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutElevatorStoreWarpEntriesScript:
;> entry = addr(wWarpEntries)               # each warp entry: y, x, warp, map
	ld hl, wWarpEntries
;> warp, map = wWarpedFromWhichWarp, wWarpedFromWhichMap
	ld a, [wWarpedFromWhichWarp]
	ld b, a
	ld a, [wWarpedFromWhichMap]
	ld c, a
;> for _ in range(2):                       # first as a call, then by falling into it
	call .StoreWarpEntry
	; fallthrough
.StoreWarpEntry:
;>     entry += 2                           # past y and x
	inc hl
	inc hl
;>     mem[entry] = warp; mem[entry + 1] = map; entry += 2
	ld a, b
	ld [hli], a
	ld a, c
	ld [hli], a
	ret

;@ path: scripts/RocketHideoutElevator
;@ def RocketHideoutElevatorScript()
;@ Set up the floor menu: the list of floors (B1F, B2F, B4F), and the warp and map each floor leads to.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutElevatorScript:
;> LoadItemList(RocketHideoutElevatorFloors)
	ld hl, RocketHideoutElevatorFloors
	call LoadItemList
;> CopyData(RocketHideoutElevatorWarpMaps, addr(wElevatorWarpMaps), 6)     # 3 floors: warp, map
	ld hl, RocketHideoutElevatorWarpMaps
	ld de, wElevatorWarpMaps
	ld bc, RocketHideoutElevatorWarpMaps.End - RocketHideoutElevatorWarpMaps
	call CopyData
	ret

;@ path: scripts/RocketHideoutElevator
RocketHideoutElevatorFloors:
	db 3 ; #
	db FLOOR_B1F
	db FLOOR_B2F
	db FLOOR_B4F
	db -1 ; end

; These specify where the player goes after getting out of the elevator.
;@ path: scripts/RocketHideoutElevator
RocketHideoutElevatorWarpMaps:
	; warp number, map id
	db 4, ROCKET_HIDEOUT_B1F
	db 4, ROCKET_HIDEOUT_B2F
	db 2, ROCKET_HIDEOUT_B4F
.End:

;@ path: scripts/RocketHideoutElevator
;@ def RocketHideoutElevatorShakeScript()
;@ The elevator ride's shaking and sounds.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
RocketHideoutElevatorShakeScript:
;> Delay3()
;> farcall(ShakeElevator)
	call Delay3
	ld b, BANK(ShakeElevator)
	ld hl, ShakeElevator
	call Bankswitch
	ret

;@ path: scripts/RocketHideoutElevator
RocketHideoutElevator_TextPointers:
	dw RocketHideoutElevatorText
DEF TEXT_ROCKETHIDEOUTELEVATOR EQU 1

;@ path: scripts/RocketHideoutElevator
;@ def RocketHideoutElevatorText() -> hl
;@ The elevator's panel: the floor menu - but only with the Lift Key; without it, it needs a key.
;@ test: skip a text script: the code after text_asm is run by the text engine
RocketHideoutElevatorText:
	db TX_START_ASM
;> if IsItemInBag(LIFT_KEY):                     # no key
;>     PrintText(RocketHideoutElevatorText.AppearsToNeedKeyText)
	ld b, LIFT_KEY
	call IsItemInBag
	jr z, .no_key
;> else:
;>     RocketHideoutElevatorScript()
	call RocketHideoutElevatorScript
;>     predef(DisplayElevatorFloorMenu, hl=RocketHideoutElevatorWarpMaps)
	ld hl, RocketHideoutElevatorWarpMaps
	ld a, (DisplayElevatorFloorMenuPredef - PredefPointers) / 3
	call Predef
;> return TextScriptEnd()
	jr .text_script_end
.no_key
	ld hl, .AppearsToNeedKeyText
	call PrintText
.text_script_end
	jp TextScriptEnd

.AppearsToNeedKeyText:
	db TX_FAR
	dw _RocketHideoutElevatorAppearsToNeedKeyText
	db BANK(_RocketHideoutElevatorAppearsToNeedKeyText)
	db TX_WAIT_BUTTON
	db TX_END
;@ path: data/maps/objects/RocketHideoutElevator
RocketHideoutElevator_Object:
	db $f ; border block

	db 2
	db 1, 2, 3 - 1, ROCKET_HIDEOUT_B1F
	db 1, 3, 5 - 1, ROCKET_HIDEOUT_B1F

	db 1
	db 1, 1, TEXT_ROCKETHIDEOUTELEVATOR

	db 0

	dw (wOverworldMap + 7 + (ROCKET_HIDEOUT_ELEVATOR_WIDTH) + ((ROCKET_HIDEOUT_ELEVATOR_WIDTH) + 6) * ((1) >> 1) + ((2) >> 1))
	db 1, 2
	dw (wOverworldMap + 7 + (ROCKET_HIDEOUT_ELEVATOR_WIDTH) + ((ROCKET_HIDEOUT_ELEVATOR_WIDTH) + 6) * ((1) >> 1) + ((3) >> 1))
	db 1, 3
;@ path: maps
RocketHideoutElevator_Blocks:
	db $44, $4d, $47, $4a, $4c, $4b, $4a, $20, $4b, $48, $46, $49

