SeafoamIslandsB1F_h::
	db CAVERN
	db $9, $F
	dw SeafoamIslandsB1F_Blocks
	dw SeafoamIslandsB1F_TextPointers
	dw SeafoamIslandsB1F_Script
	db 0
	dw SeafoamIslandsB1F_Object
;@ path: scripts/SeafoamIslandsB1F
;@ def SeafoamIslandsB1F_Script()
;@ Seafoam Islands B1F: a boulder pushed into one of the two holes falls to B2F (hidden here, shown there);
;@ otherwise, stepping into a hole drops the player to B2F.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB1F_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> pushed = wMiscFlags >> BIT_PUSHED_BOULDER & 1
	ld hl, wMiscFlags
	bit BIT_PUSHED_BOULDER, [hl]
;> wMiscFlags &= ~(1 << BIT_PUSHED_BOULDER)
	res BIT_PUSHED_BOULDER, [hl]
;> if not pushed:
	jr z, .noBoulderWasPushed
;>@e1     wDungeonWarpDestinationMap = SEAFOAM_ISLANDS_B2F
;>@e2     return IsPlayerOnDungeonWarp(Seafoam2HolesCoords)
;> if not CheckBoulderCoords(Seafoam2HolesCoords):
;>     return
	ld hl, Seafoam2HolesCoords
	call CheckBoulderCoords
	ret nc
;> if wCoordIndex == 1:
	ld hl, wEventFlags + $138
	ld a, [wCoordIndex]
	cp $1
	jr nz, .boulder2FellDownHole
;>     set_event(EVENT_SEAFOAM2_BOULDER1_DOWN_HOLE)
	set (EVENT_SEAFOAM2_BOULDER1_DOWN_HOLE) % 8, [hl]
;>     wObjectToHide = TOGGLE_SEAFOAM_ISLANDS_B1F_BOULDER_1
	ld a, TOGGLE_SEAFOAM_ISLANDS_B1F_BOULDER_1
	ld [wObjectToHide], a
;>     wObjectToShow = TOGGLE_SEAFOAM_ISLANDS_B2F_BOULDER_1
	ld a, TOGGLE_SEAFOAM_ISLANDS_B2F_BOULDER_1
	ld [wObjectToShow], a
	jr .hideAndShowBoulderObjects
.boulder2FellDownHole
;> else:
;>     set_event(EVENT_SEAFOAM2_BOULDER2_DOWN_HOLE)
	set (EVENT_SEAFOAM2_BOULDER2_DOWN_HOLE) % 8, [hl]
;>     wObjectToHide = TOGGLE_SEAFOAM_ISLANDS_B1F_BOULDER_2
	ld a, TOGGLE_SEAFOAM_ISLANDS_B1F_BOULDER_2
	ld [wObjectToHide], a
;>     wObjectToShow = TOGGLE_SEAFOAM_ISLANDS_B2F_BOULDER_2
	ld a, TOGGLE_SEAFOAM_ISLANDS_B2F_BOULDER_2
	ld [wObjectToShow], a
.hideAndShowBoulderObjects
;> wToggleableObjectIndex = wObjectToHide
	ld a, [wObjectToHide]
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = wObjectToShow
	ld a, [wObjectToShow]
	ld [wToggleableObjectIndex], a
;> return predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	jp Predef
.noBoulderWasPushed
;=@e1
	ld a, SEAFOAM_ISLANDS_B2F
	ld [wDungeonWarpDestinationMap], a
;=@e2
	ld hl, Seafoam2HolesCoords
	jp IsPlayerOnDungeonWarp

;@ path: scripts/SeafoamIslandsB1F
Seafoam2HolesCoords:
	db 6, 18
	db 6, 23
	db -1 ; end

