SeafoamIslandsB2F_h::
	db CAVERN
	db $9, $F
	dw SeafoamIslandsB2F_Blocks
	dw SeafoamIslandsB2F_TextPointers
	dw SeafoamIslandsB2F_Script
	db 0
	dw SeafoamIslandsB2F_Object
;@ path: scripts/SeafoamIslandsB2F
;@ def SeafoamIslandsB2F_Script()
;@ Seafoam Islands B2F: a boulder pushed into one of the two holes falls to B3F (hidden here, shown there);
;@ otherwise, stepping into a hole drops the player to B3F.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB2F_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> pushed = wMiscFlags >> BIT_PUSHED_BOULDER & 1
	ld hl, wMiscFlags
	bit BIT_PUSHED_BOULDER, [hl]
;> wMiscFlags &= ~(1 << BIT_PUSHED_BOULDER)
	res BIT_PUSHED_BOULDER, [hl]
;> if not pushed:
	jr z, .noBoulderWasPushed
;>@e1     wDungeonWarpDestinationMap = SEAFOAM_ISLANDS_B3F
;>@e2     return IsPlayerOnDungeonWarp(Seafoam3HolesCoords)
;> if not CheckBoulderCoords(Seafoam3HolesCoords):
;>     return
	ld hl, Seafoam3HolesCoords
	call CheckBoulderCoords
	ret nc
;> if wCoordIndex == 1:
	ld hl, wEventFlags + $139
	ld a, [wCoordIndex]
	cp $1
	jr nz, .boulder2FellDownHole
;>     set_event(EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE)
	set (EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) % 8, [hl]
;>     wObjectToHide = TOGGLE_SEAFOAM_ISLANDS_B2F_BOULDER_1
	ld a, TOGGLE_SEAFOAM_ISLANDS_B2F_BOULDER_1
	ld [wObjectToHide], a
;>     wObjectToShow = TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_3
	ld a, TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_3
	ld [wObjectToShow], a
	jr .hideAndShowBoulderObjects
.boulder2FellDownHole
;> else:
;>     set_event(EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE)
	set (EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE) % 8, [hl]
;>     wObjectToHide = TOGGLE_SEAFOAM_ISLANDS_B2F_BOULDER_2
	ld a, TOGGLE_SEAFOAM_ISLANDS_B2F_BOULDER_2
	ld [wObjectToHide], a
;>     wObjectToShow = TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_4
	ld a, TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_4
	ld [wObjectToShow], a
.hideAndShowBoulderObjects
;> wToggleableObjectIndex = wObjectToHide
	ld a, [wObjectToHide]
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = wObjectToShow
	ld a, [wObjectToShow]
	ld [wToggleableObjectIndex], a
;> return predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	jp Predef
.noBoulderWasPushed
;=@e1
	ld a, SEAFOAM_ISLANDS_B3F
	ld [wDungeonWarpDestinationMap], a
;=@e2
	ld hl, Seafoam3HolesCoords
	jp IsPlayerOnDungeonWarp

;@ path: scripts/SeafoamIslandsB2F
Seafoam3HolesCoords:
	db 6, 19
	db 6, 22
	db -1 ; end

;@ path: scripts/SeafoamIslandsB2F
