DEF TEXT_SEAFOAMISLANDSB2F_BOULDER2 EQU 2
DEF SEAFOAMISLANDSB2F_BOULDER1 EQU 1
	EXPORT SEAFOAMISLANDSB2F_BOULDER1
DEF SEAFOAMISLANDSB2F_BOULDER2 EQU 2
	EXPORT SEAFOAMISLANDSB2F_BOULDER2

