SeafoamIslandsB2F_Object:
	db $7d ; border block

	db 7
	db 3, 5, 1 - 1, SEAFOAM_ISLANDS_B1F
	db 13, 5, 1 - 1, SEAFOAM_ISLANDS_B3F
	db 7, 13, 3 - 1, SEAFOAM_ISLANDS_B1F
	db 15, 19, 4 - 1, SEAFOAM_ISLANDS_B1F
	db 3, 25, 4 - 1, SEAFOAM_ISLANDS_B3F
	db 11, 25, 6 - 1, SEAFOAM_ISLANDS_B1F
	db 14, 25, 5 - 1, SEAFOAM_ISLANDS_B3F

	db 0

	db 2
	db SPRITE_BOULDER
	db 6 + 4
	db 18 + 4
	db STAY
	db BOULDER_MOVEMENT_BYTE_2
	db TEXT_SEAFOAMISLANDSB2F_BOULDER1
	db SPRITE_BOULDER
	db 6 + 4
	db 23 + 4
	db STAY
	db BOULDER_MOVEMENT_BYTE_2
	db TEXT_SEAFOAMISLANDSB2F_BOULDER2

	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B2F_WIDTH) + ((SEAFOAM_ISLANDS_B2F_WIDTH) + 6) * ((3) >> 1) + ((5) >> 1))
	db 3, 5
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B2F_WIDTH) + ((SEAFOAM_ISLANDS_B2F_WIDTH) + 6) * (($D) >> 1) + ((5) >> 1))
	db $D, 5
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B2F_WIDTH) + ((SEAFOAM_ISLANDS_B2F_WIDTH) + 6) * ((7) >> 1) + (($D) >> 1))
	db 7, $D
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B2F_WIDTH) + ((SEAFOAM_ISLANDS_B2F_WIDTH) + 6) * (($F) >> 1) + (($13) >> 1))
	db $F, $13
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B2F_WIDTH) + ((SEAFOAM_ISLANDS_B2F_WIDTH) + 6) * ((3) >> 1) + (($19) >> 1))
	db 3, $19
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B2F_WIDTH) + ((SEAFOAM_ISLANDS_B2F_WIDTH) + 6) * (($B) >> 1) + (($19) >> 1))
	db $B, $19
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B2F_WIDTH) + ((SEAFOAM_ISLANDS_B2F_WIDTH) + 6) * (($E) >> 1) + (($19) >> 1))
	db $E, $19
