	db $15, $19, $19, $19, $15, $15, $16, $01, $01, $01, $2e, $2e, $1c, $1d, $29, $1d
	db $1d, $1d, $2b, $19, $19, $1a, $14, $7c, $16, $2e, $2e, $01, $28, $01, $01, $01
	db $01, $1c, $2d, $1d, $1e, $18, $19, $1a, $2e, $2e, $01, $01, $01, $01, $01, $01
	db $10, $01, $3e, $01, $1c, $79, $1e, $2e, $2e, $2e, $2e, $2e, $2e, $2e, $2e, $2e
	db $2e, $2e, $2e, $2e, $2e, $2e, $2e

SeafoamIslandsB3F_h::
	db CAVERN
	db $9, $F
	dw SeafoamIslandsB3F_Blocks
	dw SeafoamIslandsB3F_TextPointers
	dw SeafoamIslandsB3F_Script
	db 0
	dw SeafoamIslandsB3F_Object
;@ path: scripts/SeafoamIslandsB3F
;@ def SeafoamIslandsB3F_Script()
;@ Seafoam Islands B3F: a boulder pushed into a hole falls to B4F; stepping into a hole drops the player to
;@ B4F. Otherwise run the current step of the floor's script (the strong current near the stairs).
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB3F_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> pushed = wMiscFlags >> BIT_PUSHED_BOULDER & 1
	ld hl, wMiscFlags
	bit BIT_PUSHED_BOULDER, [hl]
;> wMiscFlags &= ~(1 << BIT_PUSHED_BOULDER)
	res BIT_PUSHED_BOULDER, [hl]
;> if pushed:
	jr z, .noBoulderWasPushed
;>     if not CheckBoulderCoords(Seafoam4HolesCoords):
;>         return
	ld hl, Seafoam4HolesCoords
	call CheckBoulderCoords
	ret nc
;>     if wCoordIndex == 1:
	ld hl, wEventFlags + $13A
	ld a, [wCoordIndex]
	cp $1
	jr nz, .boulder2FellDownHole
;>         set_event(EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE)
	set (EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) % 8, [hl]
;>         wObjectToHide = TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_1
	ld a, TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_1
	ld [wObjectToHide], a
;>         wObjectToShow = TOGGLE_SEAFOAM_ISLANDS_B4F_BOULDER_1
	ld a, TOGGLE_SEAFOAM_ISLANDS_B4F_BOULDER_1
	ld [wObjectToShow], a
	jr .hideAndShowBoulderObjects
.boulder2FellDownHole
;>     else:
;>         set_event(EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE)
	set (EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE) % 8, [hl]
;>         wObjectToHide = TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_2
	ld a, TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_2
	ld [wObjectToHide], a
;>         wObjectToShow = TOGGLE_SEAFOAM_ISLANDS_B4F_BOULDER_2
	ld a, TOGGLE_SEAFOAM_ISLANDS_B4F_BOULDER_2
	ld [wObjectToShow], a
.hideAndShowBoulderObjects
;>     wToggleableObjectIndex = wObjectToHide
	ld a, [wObjectToHide]
	ld [wToggleableObjectIndex], a
;>     predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;>     wToggleableObjectIndex = wObjectToShow
	ld a, [wObjectToShow]
	ld [wToggleableObjectIndex], a
;>     predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
	jr .runCurrentMapScript
.noBoulderWasPushed
;> else:
;>     wDungeonWarpDestinationMap = SEAFOAM_ISLANDS_B4F
	ld a, SEAFOAM_ISLANDS_B4F
	ld [wDungeonWarpDestinationMap], a
;>     IsPlayerOnDungeonWarp(Seafoam4HolesCoords)
	ld hl, Seafoam4HolesCoords
	call IsPlayerOnDungeonWarp
;>     if wStatusFlags6 >> BIT_DUNGEON_WARP & 1:
;>         return
	ld a, [wStatusFlags6]
	bit BIT_DUNGEON_WARP, a
	ret nz
.runCurrentMapScript
;> CallFunctionInTable(wSeafoamIslandsB3FCurScript, SeafoamIslandsB3F_ScriptPointers)
	ld hl, SeafoamIslandsB3F_ScriptPointers
	ld a, [wSeafoamIslandsB3FCurScript]
	jp CallFunctionInTable

;@ path: scripts/SeafoamIslandsB3F
Seafoam4HolesCoords:
	db 16, 3
	db 16, 6
	db -1 ; end

;@ path: scripts/SeafoamIslandsB3F
SeafoamIslandsB3F_ScriptPointers:
	dw SeafoamIslandsB3FDefaultScript
DEF SCRIPT_SEAFOAMISLANDSB3F_DEFAULT EQU 0
	dw SeafoamIslandsB3FObjectMoving1Script
DEF SCRIPT_SEAFOAMISLANDSB3F_OBJECT_MOVING1 EQU 1
	dw SeafoamIslandsB3FMoveObjectScript
DEF SCRIPT_SEAFOAMISLANDSB3F_MOVE_OBJECT EQU 2
	dw SeafoamIslandsB3FObjectMoving2Script
DEF SCRIPT_SEAFOAMISLANDSB3F_OBJECT_MOVING2 EQU 3
	EXPORT SCRIPT_SEAFOAMISLANDSB3F_MOVE_OBJECT ; used by engine/overworld/player_state.asm

;@ path: scripts/SeafoamIslandsB3F
;@ def SeafoamIslandsB3FDefaultScript()
;@ Until both boulders from B2F have fallen into the water here and calmed it, surfing onto the spot near
;@ the steps sweeps the player away with the strong current (simulated input) down to B4F.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB3FDefaultScript:
;> if event(EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) and event(EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE):
;>     return
	ld a, [wEventFlags + ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) / 8)]
	and (1 << ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE) % 8))
	cp (1 << ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE) % 8))
	ret z
;> if wYCoord != 8 or wXCoord != 15:
;>     return
	ld a, [wYCoord]
	cp 8
	ret nz
	ld a, [wXCoord]
	cp 15
	ret nz
;> n = DecodeRLEList(addr(wSimulatedJoypadStatesEnd), RLEList_ForcedSurfingStrongCurrentNearSteps)
	ld hl, wSimulatedJoypadStatesEnd
	ld de, RLEList_ForcedSurfingStrongCurrentNearSteps
	call DecodeRLEList
;> wSimulatedJoypadStatesIndex = (n - 1) & 0xFF
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wStatusFlags7 |= 1 << BIT_FORCED_WARP
	ld hl, wStatusFlags7
	set BIT_FORCED_WARP, [hl]
;> wSeafoamIslandsB3FCurScript = SCRIPT_SEAFOAMISLANDSB3F_OBJECT_MOVING1
	ld a, SCRIPT_SEAFOAMISLANDSB3F_OBJECT_MOVING1
	ld [wSeafoamIslandsB3FCurScript], a
	ret

;@ path: scripts/SeafoamIslandsB3F
RLEList_ForcedSurfingStrongCurrentNearSteps:
	db PAD_DOWN, 6
	db PAD_RIGHT, 5
	db PAD_DOWN, 3
	db -1 ; end

;@ path: scripts/SeafoamIslandsB3F
;@ def SeafoamIslandsB3FObjectMoving1Script()
;@ Once the current has carried the player along, back to the default step.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB3FObjectMoving1Script:
;> if wSimulatedJoypadStatesIndex:
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> wSeafoamIslandsB3FCurScript = SCRIPT_SEAFOAMISLANDSB3F_DEFAULT
	ld a, SCRIPT_SEAFOAMISLANDSB3F_DEFAULT
	ld [wSeafoamIslandsB3FCurScript], a
	ret

;@ path: scripts/SeafoamIslandsB3F
;@ def SeafoamIslandsB3FMoveObjectScript()
;@ Until the current is calmed: having dropped in next to one of the boulders' holes, the player is swept
;@ along by the current (a path for the left or the right spot).
;@ test: skip the current's paths sit under local labels, which the pseudo-code can only name
SeafoamIslandsB3FMoveObjectScript:
;> if event(EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) and event(EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE):
;>     return                              # both boulders down: the current is gone
	ld a, [wEventFlags + ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) / 8)]
	and (1 << ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE) % 8))
	cp (1 << ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE) % 8))
	ret z
;> if wXCoord == 18:
	ld a, [wXCoord]
	cp 18
	jr z, .playerFellThroughHoleLeft
;>@left     path = SeafoamIslandsB3FMoveObjectScript.RLEList_StrongCurrentNearLeftBoulder
;>@x19 elif wXCoord == 19:
	cp 19
;=@def
	ld a, SCRIPT_SEAFOAMISLANDSB3F_DEFAULT
;=@x19
	jr nz, .playerNotInStrongCurrent
;>     path = SeafoamIslandsB3FMoveObjectScript.RLEList_StrongCurrentNearRightBoulder
	ld de, .RLEList_StrongCurrentNearRightBoulder
	jr .forceSurfMovement
.playerFellThroughHoleLeft
;> else:
;>@def     wSeafoamIslandsB3FCurScript = SCRIPT_SEAFOAMISLANDSB3F_DEFAULT
;>@ret     return
;=@left
	ld de, .RLEList_StrongCurrentNearLeftBoulder
.forceSurfMovement
;> wSimulatedJoypadStatesIndex = (DecodeRLEList(addr(wSimulatedJoypadStatesEnd), path) - 1) & 0xFF
	ld hl, wSimulatedJoypadStatesEnd
	call DecodeRLEList
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> mem[wSpritePlayerStateData2MovementByte1] = 0
	xor a
	ld [wSpritePlayerStateData2MovementByte1], a
;> wStatusFlags5 |= 1 << BIT_SCRIPTED_MOVEMENT_STATE
	ld hl, wStatusFlags5
	set BIT_SCRIPTED_MOVEMENT_STATE, [hl]
;> wStatusFlags7 |= 1 << BIT_FORCED_WARP
	ld hl, wStatusFlags7
	set BIT_FORCED_WARP, [hl]
;> wSeafoamIslandsB3FCurScript = SCRIPT_SEAFOAMISLANDSB3F_OBJECT_MOVING2
	ld a, SCRIPT_SEAFOAMISLANDSB3F_OBJECT_MOVING2
.playerNotInStrongCurrent
	ld [wSeafoamIslandsB3FCurScript], a
;=@ret
	ret

.RLEList_StrongCurrentNearRightBoulder:
	db PAD_DOWN, 6
	db PAD_RIGHT, 2
	db PAD_DOWN, 4
	db PAD_LEFT, 1
	db -1 ; end

.RLEList_StrongCurrentNearLeftBoulder:
	db PAD_DOWN, 6
	db PAD_RIGHT, 2
	db PAD_DOWN, 4
	db -1 ; end

;@ path: scripts/SeafoamIslandsB3F
;@ def SeafoamIslandsB3FObjectMoving2Script()
;@ Once the current has carried the player along, back to the default step.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB3FObjectMoving2Script:
;> if wSimulatedJoypadStatesIndex:
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> wSeafoamIslandsB3FCurScript = SCRIPT_SEAFOAMISLANDSB3F_DEFAULT
	ld a, SCRIPT_SEAFOAMISLANDSB3F_DEFAULT
	ld [wSeafoamIslandsB3FCurScript], a
	ret

