	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B3F_WIDTH) + ((SEAFOAM_ISLANDS_B3F_WIDTH) + 6) * (($C) >> 1) + ((5) >> 1))
	db $C, 5
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B3F_WIDTH) + ((SEAFOAM_ISLANDS_B3F_WIDTH) + 6) * ((6) >> 1) + ((8) >> 1))
	db 6, 8
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B3F_WIDTH) + ((SEAFOAM_ISLANDS_B3F_WIDTH) + 6) * ((4) >> 1) + (($19) >> 1))
	db 4, $19
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B3F_WIDTH) + ((SEAFOAM_ISLANDS_B3F_WIDTH) + 6) * ((3) >> 1) + (($19) >> 1))
	db 3, $19
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B3F_WIDTH) + ((SEAFOAM_ISLANDS_B3F_WIDTH) + 6) * (($E) >> 1) + (($19) >> 1))
	db $E, $19
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B3F_WIDTH) + ((SEAFOAM_ISLANDS_B3F_WIDTH) + 6) * (($11) >> 1) + (($14) >> 1))
	db $11, $14
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B3F_WIDTH) + ((SEAFOAM_ISLANDS_B3F_WIDTH) + 6) * (($11) >> 1) + (($15) >> 1))
	db $11, $15
