	db $19, $19, $19, $1a, $76, $76, $76, $76, $76, $18, $19, $3d, $19, $1a, $18, $19
	db $2c, $29, $1e, $14, $15, $15, $16, $76, $1c, $1d, $79, $1d, $1e, $18, $19, $1a
	db $01, $27, $18, $2c, $2d, $1e, $76, $14, $15, $15, $15, $16, $18, $19, $19, $15
	db $15, $19, $1a, $76, $76, $76, $1c, $2d, $2b, $19, $1a, $18, $19, $19, $2c, $1d
	db $2b, $1a, $76, $76, $76, $76, $76, $18, $19, $1a, $1c, $1d, $61, $1e, $01, $18
