SeafoamIslandsB4F_h::
	db CAVERN
	db $9, $F
	dw SeafoamIslandsB4F_Blocks
	dw SeafoamIslandsB4F_TextPointers
	dw SeafoamIslandsB4F_Script
	db 0
	dw SeafoamIslandsB4F_Object
;@ path: scripts/SeafoamIslandsB4F
;@ def SeafoamIslandsB4F_Script()
;@ Seafoam Islands B4F's map script: run the current step (the strong currents, Articuno).
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB4F_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wSeafoamIslandsB4FCurScript, SeafoamIslandsB4F_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld a, [wSeafoamIslandsB4FCurScript]
	ld hl, SeafoamIslandsB4F_ScriptPointers
	jp CallFunctionInTable

;@ path: scripts/SeafoamIslandsB4F
;@ def SeafoamIslandsB4FResetScript()
;@ Back to B4F's default step, with the controls given back.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB4FResetScript:
;> wSeafoamIslandsB4FCurScript = SCRIPT_SEAFOAMISLANDSB4F_DEFAULT
;> wJoyIgnore = 0
	xor a
	ld [wSeafoamIslandsB4FCurScript], a
	ld [wJoyIgnore], a
	ret

;@ path: scripts/SeafoamIslandsB4F
SeafoamIslandsB4F_ScriptPointers:
	dw SeafoamIslandsB4FDefaultScript
DEF SCRIPT_SEAFOAMISLANDSB4F_DEFAULT EQU 0
	dw SeafoamIslandsB4FObjectMoving1Script
DEF SCRIPT_SEAFOAMISLANDSB4F_OBJECT_MOVING1 EQU 1
	dw SeafoamIslandsB4FMoveObjectScript
DEF SCRIPT_SEAFOAMISLANDSB4F_MOVE_OBJECT EQU 2
	dw SeafoamIslandsB4FObjectMoving2Script
DEF SCRIPT_SEAFOAMISLANDSB4F_OBJECT_MOVING2 EQU 3
	dw SeafoamIslandsB4FObjectMoving3Script
DEF SCRIPT_SEAFOAMISLANDSB4F_OBJECT_MOVING3 EQU 4
	EXPORT SCRIPT_SEAFOAMISLANDSB4F_MOVE_OBJECT ; used by engine/overworld/player_state.asm

;@ path: scripts/SeafoamIslandsB4F
;@ def SeafoamIslandsB4FObjectMoving3Script()
;@ After the battle with Articuno: lost, start over; otherwise end the battle as a trainer battle (Articuno
;@ disappears) and go back to the default step.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB4FObjectMoving3Script:
;> if wIsInBattle == LOST_BATTLE:
;>     return SeafoamIslandsB4FResetScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jr z, SeafoamIslandsB4FResetScript
;> EndTrainerBattle()
	call EndTrainerBattle
;> wSeafoamIslandsB4FCurScript = SCRIPT_SEAFOAMISLANDSB4F_DEFAULT
	ld a, SCRIPT_SEAFOAMISLANDSB4F_DEFAULT
	ld [wSeafoamIslandsB4FCurScript], a
	ret

;@ path: scripts/SeafoamIslandsB4F
;@ def SeafoamIslandsB4FDefaultScript()
;@ Until both boulders from B3F have calmed the water: surfing out at the bottom-right exit, the player is
;@ pushed up (two steps from the lower spots, one from the upper).
;@ test: skip the exit spots sit under a local label, which the pseudo-code can only name
SeafoamIslandsB4FDefaultScript:
;> if event(EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) and event(EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE):
;>     return
	ld a, [wEventFlags + ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) / 8)]
	and (1 << ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE) % 8))
	cp (1 << ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE) % 8))
	ret z
;> if not ArePlayerCoordsInArray(SeafoamIslandsB4FDefaultScript.Coords):
;>     return
	ld hl, .Coords
	call ArePlayerCoordsInArray
	ret nc
;> if wCoordIndex < 3:
	ld a, [wCoordIndex]
	cp $3
	jr nc, .only1UpInputNeeded
;>     mem[addr(wSimulatedJoypadStatesEnd) + 1] = PAD_UP
	ld a, PAD_UP
	ld [wSimulatedJoypadStatesEnd + 1], a
;>     wSimulatedJoypadStatesIndex = 2
	ld a, 2
	jr .forcePlayerUpFromSurfExit
.only1UpInputNeeded
;> else:
;>     wSimulatedJoypadStatesIndex = 1
	ld a, 1
.forcePlayerUpFromSurfExit
	ld [wSimulatedJoypadStatesIndex], a
;> wSimulatedJoypadStatesEnd = PAD_UP
	ld a, PAD_UP
	ld [wSimulatedJoypadStatesEnd], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wStatusFlags7 &= ~(1 << BIT_FORCED_WARP)
	ld hl, wStatusFlags7
	res BIT_FORCED_WARP, [hl]
;> wSeafoamIslandsB4FCurScript = SCRIPT_SEAFOAMISLANDSB4F_OBJECT_MOVING1
	ld a, SCRIPT_SEAFOAMISLANDSB4F_OBJECT_MOVING1
	ld [wSeafoamIslandsB4FCurScript], a
	ret

.Coords
	db 17, 20
	db 17, 21
	db 16, 20
	db 16, 21
	db -1 ; end

;@ path: scripts/SeafoamIslandsB4F
;@ def SeafoamIslandsB4FObjectMoving1Script()
;@ Once the push up is walked, give the controls back and return to the default step.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB4FObjectMoving1Script:
;> if wSimulatedJoypadStatesIndex:
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wSeafoamIslandsB4FCurScript = SCRIPT_SEAFOAMISLANDSB4F_DEFAULT
	ld a, SCRIPT_SEAFOAMISLANDSB4F_DEFAULT
	ld [wSeafoamIslandsB4FCurScript], a
	ret

;@ path: scripts/SeafoamIslandsB4F
;@ def SeafoamIslandsB4FMoveObjectScript()
;@ Until both boulders on B3F have fallen down here and calmed the water: having dropped in next to them, the
;@ player is swept along by the current (a path for the left or the right spot).
;@ test: skip the spots and paths sit under local labels, which the pseudo-code can only name
SeafoamIslandsB4FMoveObjectScript:
;> if (event(EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) and event(EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE)     # the current is gone
	ld a, [wEventFlags + ((EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) / 8)]
	and (1 << ((EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE) % 8))
	cp (1 << ((EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE) % 8))
	ld a, SCRIPT_SEAFOAMISLANDSB4F_DEFAULT
	jr z, .playerNotInStrongCurrent
;>         or not ArePlayerCoordsInArray(SeafoamIslandsB4FMoveObjectScript.Coords)):     # or the player is not in it
	ld hl, .Coords
	call ArePlayerCoordsInArray
	ld a, SCRIPT_SEAFOAMISLANDSB4F_DEFAULT
	jr nc, .playerNotInStrongCurrent
;>@def     wSeafoamIslandsB4FCurScript = SCRIPT_SEAFOAMISLANDSB4F_DEFAULT      # (loaded into a with each test)
;>@ret     return
	ld a, [wCoordIndex]
	cp $1
	jr nz, .nearRightBoulder
;>     path = SeafoamIslandsB4FMoveObjectScript.RLEList_StrongCurrentNearLeftBoulder
	ld de, .RLEList_StrongCurrentNearLeftBoulder
	jr .forceSurfMovement
.nearRightBoulder
;> else:
;>     path = SeafoamIslandsB4FMoveObjectScript.RLEList_StrongCurrentNearRightBoulder
	ld de, .RLEList_StrongCurrentNearRightBoulder
.forceSurfMovement
;> wSimulatedJoypadStatesIndex = (DecodeRLEList(addr(wSimulatedJoypadStatesEnd), path) - 1) & 0xFF
	ld hl, wSimulatedJoypadStatesEnd
	call DecodeRLEList
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wSeafoamIslandsB4FCurScript = SCRIPT_SEAFOAMISLANDSB4F_OBJECT_MOVING2
	ld a, SCRIPT_SEAFOAMISLANDSB4F_OBJECT_MOVING2
.playerNotInStrongCurrent
	ld [wSeafoamIslandsB4FCurScript], a
;=@ret
	ret

.Coords
	db 14, 4
	db 14, 5
	db -1 ; end

.RLEList_StrongCurrentNearRightBoulder:
	db PAD_UP, 3
	db PAD_RIGHT, 2
	db PAD_UP, 1
	db -1 ; end

.RLEList_StrongCurrentNearLeftBoulder:
	db PAD_UP, 3
	db PAD_RIGHT, 3
	db PAD_UP, 1
	db -1 ; end

;@ path: scripts/SeafoamIslandsB4F
;@ def SeafoamIslandsB4FObjectMoving2Script()
;@ While the current carries the player: on its last step the player is put back to walking (and then surfs
;@ again or walks, as the tile demands); at the end, back to the default step.
;@ test: hLoadedROMBank = 0x11    # the bank this code runs in
SeafoamIslandsB4FObjectMoving2Script:
;> n = wSimulatedJoypadStatesIndex
	ld a, [wSimulatedJoypadStatesIndex]
;> if n == 1:                         # the last step: back to walking
	ld b, a
	cp $1
	call z, .doneForcedSurfMovement
;>@walk     wWalkBikeSurfState = wWalkBikeSurfStateCopy = 0
;>@force     ForceBikeOrSurf()
;> if n:
;>     return
	ld a, b
	and a
	ret nz
;> wSeafoamIslandsB4FCurScript = SCRIPT_SEAFOAMISLANDSB4F_DEFAULT
	ld a, SCRIPT_SEAFOAMISLANDSB4F_DEFAULT
	ld [wSeafoamIslandsB4FCurScript], a
	ret

.doneForcedSurfMovement:
;=@walk
	xor a
	ld [wWalkBikeSurfState], a
	ld [wWalkBikeSurfStateCopy], a
;=@force
	jp ForceBikeOrSurf

;@ path: scripts/SeafoamIslandsB4F
SeafoamIslandsB4F_TextPointers:
	dw BoulderText
DEF TEXT_SEAFOAMISLANDSB4F_BOULDER1 EQU 1
	dw BoulderText
DEF TEXT_SEAFOAMISLANDSB4F_BOULDER2 EQU 2
	dw SeafoamIslandsB4FArticunoText
DEF TEXT_SEAFOAMISLANDSB4F_ARTICUNO EQU 3
	dw SeafoamIslandsB4FBouldersSignText
DEF TEXT_SEAFOAMISLANDSB4F_BOULDERS_SIGN EQU 4
	dw SeafoamIslandsB4FDangerSignText
DEF TEXT_SEAFOAMISLANDSB4F_DANGER_SIGN EQU 5

; Articuno is object 3, but its event flag is bit 2.
; This is not a problem because its sight range is 0, and
; trainer headers were not stored by ExecuteCurMapScriptInTable.
;@ path: scripts/SeafoamIslandsB4F
ArticunoTrainerHeader:
	db $2
	db 0 << 4
	dw wEventFlags + (EVENT_BEAT_ARTICUNO - $2) / 8
	dw SeafoamIslandsB4FArticunoBattleText, SeafoamIslandsB4FArticunoBattleText, SeafoamIslandsB4FArticunoBattleText, SeafoamIslandsB4FArticunoBattleText
	db -1 ; end

;@ path: scripts/SeafoamIslandsB4F
;@ def SeafoamIslandsB4FArticunoText() -> hl
;@ Articuno: the battle when spoken to; afterwards its step ends the battle.
;@ test: skip a text script: the code after text_asm is run by the text engine
SeafoamIslandsB4FArticunoText:
	db TX_START_ASM
;> TalkToTrainer(ArticunoTrainerHeader)
	ld hl, ArticunoTrainerHeader
	call TalkToTrainer
;> wSeafoamIslandsB4FCurScript = SCRIPT_SEAFOAMISLANDSB4F_OBJECT_MOVING3
	ld a, SCRIPT_SEAFOAMISLANDSB4F_OBJECT_MOVING3
	ld [wSeafoamIslandsB4FCurScript], a
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: scripts/SeafoamIslandsB4F
;@ def SeafoamIslandsB4FArticunoBattleText() -> hl
;@ Articuno's battle cry: "Gyaoo!", then its cry.
;@ test: skip a text script: the code after text_asm is run by the text engine
SeafoamIslandsB4FArticunoBattleText:
	db TX_FAR
	dw _SeafoamIslandsB4FArticunoBattleText
	db BANK(_SeafoamIslandsB4FArticunoBattleText)
	db TX_START_ASM
;> PlayCry(ARTICUNO)
	ld a, ARTICUNO
	call PlayCry
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: scripts/SeafoamIslandsB4F
SeafoamIslandsB4FBouldersSignText:
	db TX_FAR
	dw _SeafoamIslandsB4FBouldersSignText
	db BANK(_SeafoamIslandsB4FBouldersSignText)
	db TX_END

;@ path: scripts/SeafoamIslandsB4F
SeafoamIslandsB4FDangerSignText:
	db TX_FAR
	dw _SeafoamIslandsB4FDangerSignText
	db BANK(_SeafoamIslandsB4FDangerSignText)
	db TX_END
DEF SEAFOAMISLANDSB4F_BOULDER1 EQU 1
	EXPORT SEAFOAMISLANDSB4F_BOULDER1
DEF SEAFOAMISLANDSB4F_BOULDER2 EQU 2
	EXPORT SEAFOAMISLANDSB4F_BOULDER2
DEF SEAFOAMISLANDSB4F_ARTICUNO EQU 3
	EXPORT SEAFOAMISLANDSB4F_ARTICUNO

