	db 5 + 4
	db STAY
	db NONE
	db TEXT_SEAFOAMISLANDSB4F_BOULDER2
	db SPRITE_BIRD
	db 1 + 4
	db 6 + 4
	db STAY
	db DOWN
	db TRAINER | TEXT_SEAFOAMISLANDSB4F_ARTICUNO
	db ARTICUNO
	db 50

	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B4F_WIDTH) + ((SEAFOAM_ISLANDS_B4F_WIDTH) + 6) * (($11) >> 1) + (($14) >> 1))
	db $11, $14
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B4F_WIDTH) + ((SEAFOAM_ISLANDS_B4F_WIDTH) + 6) * (($11) >> 1) + (($15) >> 1))
	db $11, $15
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B4F_WIDTH) + ((SEAFOAM_ISLANDS_B4F_WIDTH) + 6) * ((7) >> 1) + (($B) >> 1))
	db 7, $B
