;@ path: scripts/RedsHouse1F
;@ def RedsHouse1FMomText() -> hl
;@ Mom: before the player has a Pokémon, "time to get going"; afterwards she heals the party.
;@ test: skip a text script: the code after text_asm is run by the text engine
RedsHouse1FMomText:
	db TX_START_ASM
;> if wStatusFlags4 >> BIT_GOT_STARTER & 1:
;>@heal     RedsHouse1FMomHealScript()
	ld a, [wStatusFlags4]
	bit BIT_GOT_STARTER, a
	jr nz, .heal
;> else:
;>     PrintText(RedsHouse1FMomText.WakeUpText)
	ld hl, .WakeUpText
	call PrintText
	jr .done
.heal
;=@heal
	call RedsHouse1FMomHealScript
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.WakeUpText:
	db TX_FAR
	dw _RedsHouse1FMomWakeUpText
	db BANK(_RedsHouse1FMomWakeUpText)
	db TX_END

;@ path: scripts/RedsHouse1F
;@ def RedsHouse1FMomHealScript()
;@ Mom heals the party: "You should rest", a fade to white with the healing jingle, then "Looking great!".
;@ test: skip waits for the sound engine (which runs from an interrupt) to finish the jingle
RedsHouse1FMomHealScript:
;> PrintText(RedsHouse1FMomYouShouldRestText)
	ld hl, RedsHouse1FMomYouShouldRestText
	call PrintText
;> GBFadeOutToWhite()
	call GBFadeOutToWhite
;> ReloadMapData()
	call ReloadMapData
;> predef(HealParty)
	ld a, (HealPartyPredef - PredefPointers) / 3
	call Predef
;> wNewSoundID = MUSIC_PKMN_HEALED
	ld a, MUSIC_PKMN_HEALED
	ld [wNewSoundID], a
;> PlaySound(MUSIC_PKMN_HEALED)
	call PlaySound
;> while wChannelSoundIDs[0] == MUSIC_PKMN_HEALED:
.next
	ld a, [wChannelSoundIDs]
	cp MUSIC_PKMN_HEALED
	jr z, .next
;>     pass
;> wNewSoundID = wMapMusicSoundID
	ld a, [wMapMusicSoundID]
	ld [wNewSoundID], a
;> PlaySound(wMapMusicSoundID)
	call PlaySound
;> GBFadeInFromWhite()
	call GBFadeInFromWhite
;> return PrintText(RedsHouse1FMomLookingGreatText)
	ld hl, RedsHouse1FMomLookingGreatText
	jp PrintText

;@ path: scripts/RedsHouse1F
RedsHouse1FMomYouShouldRestText:
	db TX_FAR
	dw _RedsHouse1FMomYouShouldRestText
	db BANK(_RedsHouse1FMomYouShouldRestText)
	db TX_END
;@ path: scripts/RedsHouse1F
RedsHouse1FMomLookingGreatText:
	db TX_FAR
	dw _RedsHouse1FMomLookingGreatText
	db BANK(_RedsHouse1FMomLookingGreatText)
	db TX_END

;@ path: scripts/RedsHouse1F
;@ def RedsHouse1FTVText() -> hl
;@ The TV: a movie (Stand By Me) when watched from the front, otherwise "oops, wrong side".
;@ test: skip a text script: the code after text_asm is run by the text engine
RedsHouse1FTVText:
	db TX_START_ASM
;> if mem[wSpritePlayerStateData1FacingDirection] != SPRITE_FACING_UP:
;>     text = RedsHouse1FTVText.WrongSideText
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	ld hl, .WrongSideText
	jr nz, .got_text
;> else:
;>     text = RedsHouse1FTVText.StandByMeMovieText
	ld hl, .StandByMeMovieText
.got_text
;> PrintText(text)
;> return TextScriptEnd()
	call PrintText
	jp TextScriptEnd

.StandByMeMovieText:
	db TX_FAR
	dw _RedsHouse1FTVStandByMeMovieText
	db BANK(_RedsHouse1FTVStandByMeMovieText)
	db TX_END

.WrongSideText:
	db TX_FAR
	dw _RedsHouse1FTVWrongSideText
	db BANK(_RedsHouse1FTVWrongSideText)
	db TX_END
