;@ path: scripts/CeladonMart3F
;@ def CeladonMart3FClerkText() -> hl
;@ The clerk who gives TM18 (COUNTER) once, if the bag has room, and explains it afterwards.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeladonMart3FClerkText:
	db TX_START_ASM
;> if event(EVENT_GOT_TM18):
	ld a, [wEventFlags + $31]
	bit (EVENT_GOT_TM18) % 8, a
;>     PrintText(CeladonMart3FClerkText.TM18ExplanationText)
;>     return TextScriptEnd()
	jr nz, .got_item
;> PrintText(CeladonMart3FClerkText.TM18PreReceiveText)
	ld hl, .TM18PreReceiveText
	call PrintText
;> if GiveItem(TM_COUNTER, 1):
	ld bc, ((TM_COUNTER) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>     set_event(EVENT_GOT_TM18)
	ld hl, wEventFlags + $31
	set (EVENT_GOT_TM18) % 8, [hl]
;>     PrintText(CeladonMart3FClerkText.ReceivedTM18Text)
	ld hl, .ReceivedTM18Text
	jr .done
;> else:
.bag_full
;>     PrintText(CeladonMart3FClerkText.TM18NoRoomText)
	ld hl, .TM18NoRoomText
	jr .done
.got_item
	ld hl, .TM18ExplanationText
.done
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.TM18PreReceiveText:
	db TX_FAR
	dw _CeladonMart3FClerkTM18PreReceiveText
	db BANK(_CeladonMart3FClerkTM18PreReceiveText)
	db TX_END

.ReceivedTM18Text:
	db TX_FAR
	dw _CeladonMart3FClerkReceivedTM18Text
	db BANK(_CeladonMart3FClerkReceivedTM18Text)
	db TX_SOUND_GET_ITEM_1
	db TX_END

.TM18ExplanationText:
	db TX_FAR
	dw _CeladonMart3FClerkTM18ExplanationText
	db BANK(_CeladonMart3FClerkTM18ExplanationText)
	db TX_END

.TM18NoRoomText:
