;@ path: scripts/CeladonMartRoof
;@ def CeladonMartRoofScript_GetDrinksInBag()
;@ List the drinks the player carries (Fresh Water, Soda Pop, Lemonade) in wFilteredBagItems, ending in $FF,
;@ with their number in wFilteredBagItemsCount.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
CeladonMartRoofScript_GetDrinksInBag:
; construct a list of all drinks in the player's bag
;> wFilteredBagItemsCount = 0
	xor a
	ld [wFilteredBagItemsCount], a
;> out = addr(wFilteredBagItems)
	ld de, wFilteredBagItems
;> p = CeladonMartRoofDrinkList
	ld hl, CeladonMartRoofDrinkList
;> while mem[p]:
.loop
	ld a, [hli]
	and a
	jr z, .done
;>     wTempByteValue = mem[p]
	push hl
	push de
	ld [wTempByteValue], a
;>     p += 1
;>     count = GetQuantityOfItemInBag()       # b = the drink, through the predef
	ld b, a
	ld a, (GetQuantityOfItemInBagPredef - PredefPointers) / 3
	call Predef
	pop de
	pop hl
	ld a, b
;>     if count:
	and a
	jr z, .loop
;>         mem[out] = wTempByteValue
	; A drink is in the bag
	ld a, [wTempByteValue]
	ld [de], a
;>         out += 1
	inc de
;>         wFilteredBagItemsCount += 1
	push hl
	ld hl, wFilteredBagItemsCount
	inc [hl]
	pop hl
	jr .loop
.done
;> mem[out] = 0xFF
	ld a, $ff
	ld [de], a
	ret

;@ path: scripts/CeladonMartRoof
CeladonMartRoofDrinkList:
	db FRESH_WATER
	db SODA_POP
	db LEMONADE
	db 0 ; end

;@ path: scripts/CeladonMartRoof
;@ def CeladonMartRoofScript_GiveDrinkToGirl()
;@ The drink menu: the girl takes the chosen drink and gives a TM for it, once per kind of drink:
;@ Fresh Water → TM13 (ICE BEAM), Soda Pop → TM48 (ROCK SLIDE), Lemonade → TM49 (TRI ATTACK).
;@ test: skip waits for the player
CeladonMartRoofScript_GiveDrinkToGirl:
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> PrintText(CeladonMartRoofLittleGirlGiveHerWhichDrinkText)
	ld hl, CeladonMartRoofLittleGirlGiveHerWhichDrinkText
	call PrintText
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = wFilteredBagItemsCount - 1
	ld a, [wFilteredBagItemsCount]
	dec a
	ld [wMaxMenuItem], a
;> wTopMenuItemY = 2
	ld a, 2
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemX], a
;> rows = (AddNTimes(3, 2, wFilteredBagItemsCount - 1) & 0xFF) - 1    # two rows per drink
	ld a, [wFilteredBagItemsCount]
	dec a
	ld bc, 2
	ld hl, 3
	call AddNTimes
;> TextBoxBorder(coord(0, 0), rows, 12)
	dec l
	ld b, l
	ld c, 12
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	call TextBoxBorder
;> UpdateSprites()
	call UpdateSprites
;> CeladonMartRoofScript_PrintDrinksInBag()
	call CeladonMartRoofScript_PrintDrinksInBag
;> wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY)
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> if HandleMenuInput() >> B_PAD_B & 1:
	call HandleMenuInput
	bit B_PAD_B, a
;>     return
	ret nz
;> drink = mem[addr(wFilteredBagItems) + wCurrentMenuItem]
	ld hl, wFilteredBagItems
	ld a, [wCurrentMenuItem]
	ld d, 0
	ld e, a
	add hl, de
	ld a, [hl]
;> hItemToRemoveID = drink
	ldh [hItemToRemoveID], a
;> if drink == FRESH_WATER:
;>@fw1     if event(EVENT_GOT_TM13):
;>@fw2         return PrintText(CeladonMartRoofLittleGirlImNotThirstyText)
;>@fw3     PrintText(CeladonMartRoofLittleGirlYayFreshWaterText)
;>@fw4     RemoveItemByIDBank12()
;>@fw5     if not GiveItem(TM_ICE_BEAM, 1):
;>@fw6         return PrintText(CeladonMartRoofLittleGirlNoRoomText)
;>@fw7     PrintText(CeladonMartRoofLittleGirlReceivedTM13Text)
;>@fw8     set_event(EVENT_GOT_TM13)
	cp FRESH_WATER
	jr z, .gaveFreshWater
;> elif drink == SODA_POP:
;>@sp1     if event(EVENT_GOT_TM48):
;>@sp2         return PrintText(CeladonMartRoofLittleGirlImNotThirstyText)
;>@sp3     PrintText(CeladonMartRoofLittleGirlYaySodaPopText)
;>@sp4     RemoveItemByIDBank12()
;>@sp5     if not GiveItem(TM_ROCK_SLIDE, 1):
;>@sp6         return PrintText(CeladonMartRoofLittleGirlNoRoomText)
;>@sp7     PrintText(CeladonMartRoofLittleGirlReceivedTM48Text)
;>@sp8     set_event(EVENT_GOT_TM48)
	cp SODA_POP
	jr z, .gaveSodaPop
;> else:                                   # Lemonade
; gave Lemonade
;>     if event(EVENT_GOT_TM49):           # one TM per kind of drink
	ld a, [wEventFlags + $31]
	bit (EVENT_GOT_TM49) % 8, a
;>@thirsty         return PrintText(CeladonMartRoofLittleGirlImNotThirstyText)
	jr nz, .alreadyGaveDrink
;>     PrintText(CeladonMartRoofLittleGirlYayLemonadeText)
	ld hl, CeladonMartRoofLittleGirlYayLemonadeText
	call PrintText
;>     RemoveItemByIDBank12()
	call RemoveItemByIDBank12
;>     if not GiveItem(TM_TRI_ATTACK, 1):
	ld bc, ((TM_TRI_ATTACK) & $ff) << 8 + ((1) & $ff)
	call GiveItem
;>@full         return PrintText(CeladonMartRoofLittleGirlNoRoomText)
	jr nc, .bagFull
;>     PrintText(CeladonMartRoofLittleGirlReceivedTM49Text)
	ld hl, CeladonMartRoofLittleGirlReceivedTM49Text
	call PrintText
;>     set_event(EVENT_GOT_TM49)
	ld hl, wEventFlags + $31
	set (EVENT_GOT_TM49) % 8, [hl]
	ret
.gaveSodaPop
;=@sp1
	ld a, [wEventFlags + $31]
	bit (EVENT_GOT_TM48) % 8, a
;=@sp2
	jr nz, .alreadyGaveDrink
;=@sp3
	ld hl, CeladonMartRoofLittleGirlYaySodaPopText
	call PrintText
;=@sp4
	call RemoveItemByIDBank12
;=@sp5
	ld bc, ((TM_ROCK_SLIDE) & $ff) << 8 + ((1) & $ff)
	call GiveItem
;=@sp6
	jr nc, .bagFull
;=@sp7
	ld hl, CeladonMartRoofLittleGirlReceivedTM48Text
	call PrintText
;=@sp8
	ld hl, wEventFlags + $31
	set (EVENT_GOT_TM48) % 8, [hl]
	ret
.gaveFreshWater
;=@fw1
	ld a, [wEventFlags + $31]
	bit (EVENT_GOT_TM13) % 8, a
;=@fw2
	jr nz, .alreadyGaveDrink
;=@fw3
	ld hl, CeladonMartRoofLittleGirlYayFreshWaterText
	call PrintText
;=@fw4
	call RemoveItemByIDBank12
;=@fw5
	ld bc, ((TM_ICE_BEAM) & $ff) << 8 + ((1) & $ff)
	call GiveItem
;=@fw6
	jr nc, .bagFull
;=@fw7
	ld hl, CeladonMartRoofLittleGirlReceivedTM13Text
	call PrintText
;=@fw8
	ld hl, wEventFlags + $31
	set (EVENT_GOT_TM13) % 8, [hl]
	ret
.bagFull
;=@full
	ld hl, CeladonMartRoofLittleGirlNoRoomText
	jp PrintText
.alreadyGaveDrink
;=@thirsty
	ld hl, CeladonMartRoofLittleGirlImNotThirstyText
	jp PrintText

;@ path: scripts/CeladonMartRoof
;@ def RemoveItemByIDBank12()
;@ Take one of item hItemToRemoveID out of the bag (from this bank).
;@ test: [mem.__setitem__(wBagItems + i, rand(1, 30) if i % 2 == 0 else rand(1, 99)) for i in range(40)]; n = rand(1, 19); mem[wBagItems + 2 * n] = 0xFF; mem[wBagItems - 1] = n; hItemToRemoveID = rand(1, 30)
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
RemoveItemByIDBank12:
;> RemoveItemByID()
	ld b, BANK(RemoveItemByID)
	ld hl, RemoveItemByID
	jp Bankswitch

