;@ path: scripts/CeladonMartRoof
;@ def CeladonMartRoofScript_PrintDrinksInBag()
;@ Write the names of the listed drinks into the menu box, one every two rows.
CeladonMartRoofScript_PrintDrinksInBag:
;> p = addr(wFilteredBagItems)
	ld hl, wFilteredBagItems
;> hItemCounter = 0
	xor a
	ldh [hItemCounter], a
;> while mem[p] != 0xFF:
.loop
	ld a, [hli]
	cp $ff
	ret z
;>     wNamedObjectIndex = mem[p]
	push hl
	ld [wNamedObjectIndex], a
;>     p += 1
;>     GetItemName()
	call GetItemName
;>     PlaceString(addr(wNameBuffer), AddNTimes(coord(2, 2), SCREEN_WIDTH * 2, hItemCounter))
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ldh a, [hItemCounter]
	ld bc, SCREEN_WIDTH * 2
	call AddNTimes
	ld de, wNameBuffer
	call PlaceString
;>     hItemCounter += 1
	ld hl, hItemCounter
	inc [hl]
	pop hl
	jr .loop

