;@ path: scripts/CeladonMartRoof
;@ def CeladonMartRoofLittleGirlText() -> hl
;@ The thirsty girl on the roof: with drinks in the bag she asks for one and opens the drink menu.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeladonMartRoofLittleGirlText:
	db TX_START_ASM
;> CeladonMartRoofScript_GetDrinksInBag()
	call CeladonMartRoofScript_GetDrinksInBag
;> if wFilteredBagItemsCount == 0:
	ld a, [wFilteredBagItemsCount]
;>     PrintText(CeladonMartRoofLittleGirlText.ImThirstyText)
;>     return TextScriptEnd()
	and a
	jr z, .noDrinksInBag
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, 1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> PrintText(CeladonMartRoofLittleGirlText.GiveHerADrinkText)
	ld hl, .GiveHerADrinkText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem == 0:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .done
;>     CeladonMartRoofScript_GiveDrinkToGirl()
	call CeladonMartRoofScript_GiveDrinkToGirl
	jr .done
;> return TextScriptEnd()
.noDrinksInBag
	ld hl, .ImThirstyText
	call PrintText
.done
	jp TextScriptEnd

.ImThirstyText:
	db TX_FAR
	dw _CeladonMartRoofLittleGirlImThirstyText
	db BANK(_CeladonMartRoofLittleGirlImThirstyText)
