CeladonMartElevator_h::
	db LOBBY
	db $2, $2
	dw CeladonMartElevator_Blocks
	dw CeladonMartElevator_TextPointers
	dw CeladonMartElevator_Script
	db 0
	dw CeladonMartElevator_Object
;@ path: scripts/CeladonMartElevator
;@ def CeladonMartElevator_Script()
;@ The department store elevator: on arrival note where the doors lead; after a ride, shake the elevator.
CeladonMartElevator_Script:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if loaded:
;>     CeladonMartElevatorStoreWarpEntriesScript()
	push hl
	call nz, CeladonMartElevatorStoreWarpEntriesScript
;> used = wCurrentMapScriptFlags >> BIT_CUR_MAP_USED_ELEVATOR & 1
	pop hl
	bit BIT_CUR_MAP_USED_ELEVATOR, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_USED_ELEVATOR)
	res BIT_CUR_MAP_USED_ELEVATOR, [hl]
;> if used:
;>     CeladonMartElevatorShakeScript()
	call nz, CeladonMartElevatorShakeScript
;> wAutoTextBoxDrawingControl = 0
	xor a
	ld [wAutoTextBoxDrawingControl], a
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	inc a
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
	ret

;@ path: scripts/CeladonMartElevator
;@ def CeladonMartElevatorStoreWarpEntriesScript()
;@ Point both elevator doors back to where the player came from: the warp and map the player arrived from
;@ go into the elevator's two warp entries.
CeladonMartElevatorStoreWarpEntriesScript:
;> entry = addr(wWarpEntries)               # each warp entry: y, x, warp, map
	ld hl, wWarpEntries
;> warp, map = wWarpedFromWhichWarp, wWarpedFromWhichMap
	ld a, [wWarpedFromWhichWarp]
	ld b, a
	ld a, [wWarpedFromWhichMap]
	ld c, a
;> for _ in range(2):                       # first as a call, then by falling into it
	call .StoreWarpEntry
	; fallthrough
.StoreWarpEntry:
;>     entry += 2                           # past y and x
	inc hl
	inc hl
;>     mem[entry] = warp; mem[entry + 1] = map; entry += 2
	ld a, b
	ld [hli], a
	ld a, c
	ld [hli], a
	ret

;@ path: scripts/CeladonMartElevator
;@ def CeladonMartElevatorCopyWarpMapsScript()
;@ Set up the floor menu: the list of floors, and the warp and map each floor leads to.
CeladonMartElevatorCopyWarpMapsScript:
;> LoadItemList(CeladonMartElevatorFloors)
;> CopyData(CeladonMartElevatorWarpMaps, wElevatorWarpMaps, 10)    # 5 floors: warp, map
	ld hl, CeladonMartElevatorFloors
	call LoadItemList
	ld hl, CeladonMartElevatorWarpMaps
	ld de, wElevatorWarpMaps
	ld bc, CeladonMartElevatorWarpMaps.End - CeladonMartElevatorWarpMaps
	jp CopyData

;@ path: scripts/CeladonMartElevator
CeladonMartElevatorFloors:
	db 5 ; #
	db FLOOR_1F
	db FLOOR_2F
	db FLOOR_3F
	db FLOOR_4F
	db FLOOR_5F
	db -1 ; end

; These specify where the player goes after getting out of the elevator.
;@ path: scripts/CeladonMartElevator
CeladonMartElevatorWarpMaps:
	; warp number, map id
	db 5, CELADON_MART_1F
	db 2, CELADON_MART_2F
	db 2, CELADON_MART_3F
	db 2, CELADON_MART_4F
	db 2, CELADON_MART_5F
.End:

;@ path: scripts/CeladonMartElevator
;@ def CeladonMartElevatorShakeScript()
;@ The elevator ride's shaking and sounds.
CeladonMartElevatorShakeScript:
;> ShakeElevator()
	ld b, BANK(ShakeElevator)
	ld hl, ShakeElevator
	jp Bankswitch

