;@ path: scripts/CeladonMansion3F
;@ def CeladonMansion3FGameDesignerText() -> hl
;@ The game designer: once the player owns every Pokémon except Mew he congratulates the player and
;@ shows the diploma; before that he asks the player to complete the Pokédex.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeladonMansion3FGameDesignerText:
	db TX_START_ASM
;> CountSetBits(addr(wPokedexOwned), wPokedexOwnedEnd - wPokedexOwned)
	ld hl, wPokedexOwned
	ld b, wPokedexOwnedEnd - wPokedexOwned
	call CountSetBits
;> if wNumSetBits >= NUM_POKEMON - 1:          # Mew does not count
	ld a, [wNumSetBits]
	cp NUM_POKEMON - 1 ; discount Mew
	jr nc, .completed_dex
;>@dex     text = CeladonMansion3FGameDesignerText.CompletedDexText    # which shows the diploma
;> else:
;>     text = CeladonMansion3FGameDesignerText.Text
	ld hl, .Text
	jr .done
.completed_dex
;=@dex
	ld hl, .CompletedDexText
.done
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _CeladonMansion3FGameDesignerText
	db BANK(_CeladonMansion3FGameDesignerText)
	db TX_END

.CompletedDexText:
	db TX_FAR
	dw _CeladonMansion3FGameDesignerCompletedDexText
	db BANK(_CeladonMansion3FGameDesignerCompletedDexText)
	db TX_PROMPT_BUTTON
	db TX_START_ASM
;> # the text ends in code: farcall(DisplayDiploma), then wDoNotWaitForButtonPressAfterDisplayingText = TRUE
	ld hl, DisplayDiploma
	ld b, BANK(DisplayDiploma)
	call Bankswitch
	ld a, TRUE
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
	jp TextScriptEnd

