;@ path: scripts/CeladonGym
;@ def CeladonGym_Script()
;@ Celadon Gym's map script: on entering, set the city and leader names (Celadon City, Erika) for the
;@ badge texts, then run the current step of the gym's script (its trainers and Erika).
;@ test: skip the names sit under local labels, which the pseudo-code cannot reach
CeladonGym_Script:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if loaded:
	call nz, .LoadNames
;>@e1     LoadGymLeaderAndCityName(CeladonGym_Script.CityName, CeladonGym_Script.LeaderName)
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wCeladonGymCurScript = ExecuteCurMapScriptInTable(wCeladonGymCurScript, CeladonGymTrainerHeaders, CeladonGym_ScriptPointers)
	ld hl, CeladonGymTrainerHeaders
	ld de, CeladonGym_ScriptPointers
	ld a, [wCeladonGymCurScript]
	call ExecuteCurMapScriptInTable
	ld [wCeladonGymCurScript], a
	ret

.LoadNames:
;=@e1
	ld hl, .CityName
	ld de, .LeaderName
	jp LoadGymLeaderAndCityName

.CityName:
	db "CELADON CITY@"

.LeaderName:
	db "ERIKA@"

;@ path: scripts/CeladonGym
;@ def CeladonGymResetScripts()
;@ Back to the gym's default step (after a lost battle or after the badge), with the controls given back.
CeladonGymResetScripts:
;> wJoyIgnore = 0
	xor a ; SCRIPT_CELADONGYM_DEFAULT
	ld [wJoyIgnore], a
;> wCeladonGymCurScript = SCRIPT_CELADONGYM_DEFAULT
	ld [wCeladonGymCurScript], a
;> wCurMapScript = SCRIPT_CELADONGYM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/CeladonGym
CeladonGym_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_CELADONGYM_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_CELADONGYM_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_CELADONGYM_END_BATTLE EQU 2
	dw CeladonGymErikaPostBattleScript
DEF SCRIPT_CELADONGYM_ERIKA_POST_BATTLE EQU 3

;@ path: scripts/CeladonGym
;@ def CeladonGymErikaPostBattleScript()
;@ After the battle with Erika: lost, start over; won, go on to the badge and TM21.
CeladonGymErikaPostBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return CeladonGymResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, CeladonGymResetScripts
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a

;> return CeladonGymReceiveTM21()

;@ path: scripts/CeladonGym
;@ def CeladonGymReceiveTM21()
;@ Erika's reward: the Rainbow Badge text, TM21 (MEGA DRAIN) if the bag has room, the badge itself, and
;@ all the gym's trainers count as beaten.
CeladonGymReceiveTM21:
;> hTextID = TEXT_CELADONGYM_RAINBOWBADGE_INFO
	ld a, TEXT_CELADONGYM_RAINBOWBADGE_INFO
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_BEAT_ERIKA)
	ld hl, wEventFlags + $35
	set (EVENT_BEAT_ERIKA) % 8, [hl]
;> if GiveItem(TM_MEGA_DRAIN, 1):
	ld bc, ((TM_MEGA_DRAIN) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .BagFull
;>     hTextID = TEXT_CELADONGYM_RECEIVED_TM21
	ld a, TEXT_CELADONGYM_RECEIVED_TM21
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     set_event(EVENT_GOT_TM21)
	ld hl, wEventFlags + $35
	set (EVENT_GOT_TM21) % 8, [hl]
	jr .gymVictory
;> else:
.BagFull
;>     hTextID = TEXT_CELADONGYM_TM21_NO_ROOM
	ld a, TEXT_CELADONGYM_TM21_NO_ROOM
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;> wObtainedBadges |= 1 << BIT_RAINBOWBADGE
.gymVictory
	ld hl, wObtainedBadges
	set BIT_RAINBOWBADGE, [hl]
;> wBeatGymFlags |= 1 << BIT_RAINBOWBADGE
	ld hl, wBeatGymFlags
	set BIT_RAINBOWBADGE, [hl]
;> for e in range(EVENT_BEAT_CELADON_GYM_TRAINER_0, EVENT_BEAT_CELADON_GYM_TRAINER_6 + 1):

	; deactivate gym trainers
	ld a, [wEventFlags + $35]
	or $ff - ((1 << ((EVENT_BEAT_CELADON_GYM_TRAINER_0) % 8)) - 1)
;>     set_event(e)
	ld [wEventFlags + $35], a
	ld hl, wEventFlags + $36
	set 0, [hl]

;> return CeladonGymResetScripts()
	jp CeladonGymResetScripts

