;@ path: scripts/CeladonGym
;@ def CeladonGymErikaText() -> hl
;@ Erika: before the battle she engages the player; after it she gives TM21 if she still owes it, and
;@ otherwise has advice.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeladonGymErikaText:
	db TX_START_ASM
;> if event(EVENT_BEAT_ERIKA):
	ld a, [wEventFlags + $35]
	bit (EVENT_BEAT_ERIKA) % 8, a
	jr z, .beforeBeat
;>     if event(EVENT_GOT_TM21):
	bit (EVENT_GOT_TM21) % 8, a
	jr nz, .afterBeat
;>         PrintText(CeladonGymErikaText.PostBattleAdviceText)
;>     else:
;>         CeladonGymReceiveTM21()
	call z, CeladonGymReceiveTM21
;>         DisableWaitingAfterTextDisplay()
	call DisableWaitingAfterTextDisplay
;>     return TextScriptEnd()
	jr .done
.afterBeat
	ld hl, .PostBattleAdviceText
	call PrintText
	jr .done
.beforeBeat
;> PrintText(CeladonGymErikaText.PreBattleText)
	ld hl, .PreBattleText
	call PrintText
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(CeladonGymErikaText.ReceivedRainbowBadgeText, CeladonGymErikaText.ReceivedRainbowBadgeText)
	ld hl, .ReceivedRainbowBadgeText
	ld de, .ReceivedRainbowBadgeText
	call SaveEndBattleTextPointers
;> wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;> EngageMapTrainer()
	call EngageMapTrainer
;> InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;> wGymLeaderNo = 4
	ld a, $4
	ld [wGymLeaderNo], a
;> wCeladonGymCurScript = SCRIPT_CELADONGYM_ERIKA_POST_BATTLE
	ld a, SCRIPT_CELADONGYM_ERIKA_POST_BATTLE
	ld [wCeladonGymCurScript], a
;> wCurMapScript = SCRIPT_CELADONGYM_ERIKA_POST_BATTLE
	ld [wCurMapScript], a
;> return TextScriptEnd()
.done
	jp TextScriptEnd

.PreBattleText:
	db TX_FAR
	dw _CeladonGymErikaPreBattleText
	db BANK(_CeladonGymErikaPreBattleText)
	db TX_END

