;@ path: data/maps/objects/CeladonGym
CeladonGym_Object:
	db $3 ; border block

	db 2
	db 17, 4, 7 - 1, LAST_MAP
	db 17, 5, 7 - 1, LAST_MAP

	db 0

	db 8
	db SPRITE_SILPH_WORKER_F
	db 3 + 4
	db 4 + 4
	db STAY
	db DOWN
	db TRAINER | TEXT_CELADONGYM_ERIKA
	db OPP_ERIKA
	db 1
	db SPRITE_COOLTRAINER_F
	db 11 + 4
	db 2 + 4
	db STAY
	db RIGHT
	db TRAINER | TEXT_CELADONGYM_COOLTRAINER_F1
	db OPP_LASS
	db 17
	db SPRITE_BEAUTY
	db 10 + 4
	db 7 + 4
	db STAY
	db LEFT
	db TRAINER | TEXT_CELADONGYM_BEAUTY1
	db OPP_BEAUTY
	db 1
	db SPRITE_COOLTRAINER_F
	db 5 + 4
	db 9 + 4
	db STAY
	db DOWN
	db TRAINER | TEXT_CELADONGYM_COOLTRAINER_F2
	db OPP_JR_TRAINER_F
	db 11
	db SPRITE_BEAUTY
	db 5 + 4
	db 1 + 4
	db STAY
	db DOWN
	db TRAINER | TEXT_CELADONGYM_BEAUTY2
	db OPP_BEAUTY
	db 2
	db SPRITE_COOLTRAINER_F
	db 3 + 4
	db 6 + 4
	db STAY
	db DOWN
	db TRAINER | TEXT_CELADONGYM_COOLTRAINER_F3
	db OPP_LASS
	db 18
	db SPRITE_BEAUTY
	db 3 + 4
	db 3 + 4
	db STAY
	db DOWN
