	db OPP_BEAUTY
	db 3
	db SPRITE_COOLTRAINER_F
	db 3 + 4
	db 5 + 4
	db STAY
	db DOWN
	db TRAINER | TEXT_CELADONGYM_COOLTRAINER_F4
	db OPP_COOLTRAINER_F
	db 1

	dw (wOverworldMap + 7 + (CELADON_GYM_WIDTH) + ((CELADON_GYM_WIDTH) + 6) * (($11) >> 1) + ((4) >> 1))
	db $11, 4
	dw (wOverworldMap + 7 + (CELADON_GYM_WIDTH) + ((CELADON_GYM_WIDTH) + 6) * (($11) >> 1) + ((5) >> 1))
	db $11, 5
