CeladonGym_Blocks:
	db $01, $01, $01, $01, $01, $33, $38, $3a, $39, $33, $33, $3c, $33, $3d, $33, $33
	db $3b, $3f, $3e, $33, $33, $34, $05, $34, $33, $35, $05, $05, $05, $36, $33, $34
	db $05, $34, $33, $05, $32, $05, $31, $05, $05, $05, $04, $05, $05

GameCorner_h::
	db LOBBY
	db $9, $A
	dw GameCorner_Blocks
	dw GameCorner_TextPointers
	dw GameCorner_Script
	db 0
	dw GameCorner_Object
;@ path: scripts/GameCorner
;@ def GameCorner_Script()
;@ The Game Corner's map script: pick the lucky slot machine on entering, open the hidden door to the
;@ Rocket Hideout once found, then run the current step.
GameCorner_Script:
;> GameCornerSelectLuckySlotMachine()
	call GameCornerSelectLuckySlotMachine
;> GameCornerSetRocketHideoutDoorTile()
	call GameCornerSetRocketHideoutDoorTile
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> CallFunctionInTable(wGameCornerCurScript, GameCorner_ScriptPointers)
	ld hl, GameCorner_ScriptPointers
	ld a, [wGameCornerCurScript]
	jp CallFunctionInTable

;@ path: scripts/GameCorner
;@ def GameCornerSelectLuckySlotMachine(carry_in: carry = False)
;@ On entering, pick at random which slot machine pays out more often (0 to 31; 1 when the roll is below 7).
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
GameCornerSelectLuckySlotMachine:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if not loaded:
;>     return
	ret z
;> Random(carry_in)                    # the carry flag goes into the random number
	call Random
;> r = hRandomAdd
	ldh a, [hRandomAdd]
;> if r < 7:
	cp $7
	jr nc, .not_max
;>     r = 8
	ld a, $8
.not_max
;> wLuckySlotHiddenEventIndex = r >> 3
	srl a
	srl a
	srl a
	ld [wLuckySlotHiddenEventIndex], a
	ret

;@ path: scripts/GameCorner
;@ def GameCornerSetRocketHideoutDoorTile()
;@ When the map has just loaded and the hidden switch has not been found yet, cover the stairs to the
;@ Rocket Hideout with a wall block.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
GameCornerSetRocketHideoutDoorTile:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded or event(EVENT_FOUND_ROCKET_HIDEOUT):
	ret z
	ld a, [wEventFlags + $37]
	bit (EVENT_FOUND_ROCKET_HIDEOUT) % 8, a
;>     return
	ret nz
;> wNewTileBlockID = 0x2A
	ld a, $2a
	ld [wNewTileBlockID], a
;> ReplaceTileBlock()                  # block row 2, column 8 (b, c through the predef)
	ld bc, ((2) & $ff) << 8 + ((8) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/GameCorner
;@ def GameCornerReenterMapAfterPlayerLoss()
;@ Back to the default step after losing to the Rocket, with the controls given back.
GameCornerReenterMapAfterPlayerLoss:
;> wJoyIgnore = 0
	xor a ; SCRIPT_GAMECORNER_DEFAULT
	ld [wJoyIgnore], a
;> wGameCornerCurScript = SCRIPT_GAMECORNER_DEFAULT
	ld [wGameCornerCurScript], a
;> wCurMapScript = SCRIPT_GAMECORNER_DEFAULT
	ld [wCurMapScript], a
	ret

