GameCorner_ScriptPointers:
	dw GameCornerDefaultScript
DEF SCRIPT_GAMECORNER_DEFAULT EQU 0
	dw GameCornerRocketBattleScript
DEF SCRIPT_GAMECORNER_ROCKET_BATTLE EQU 1
	dw GameCornerRocketExitScript
DEF SCRIPT_GAMECORNER_ROCKET_EXIT EQU 2

;@ path: scripts/GameCorner
;@ def GameCornerDefaultScript()
;@ The Game Corner's idle step: nothing happens.
GameCornerDefaultScript:
;> return
	ret

;@ path: scripts/GameCorner
;@ def GameCornerRocketBattleScript()
;@ After the fight with the Rocket by the poster: lost, start over; won, his words, then he runs off,
;@ around the player or straight to the door depending on where the player stands.
GameCornerRocketBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return GameCornerReenterMapAfterPlayerLoss()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, GameCornerReenterMapAfterPlayerLoss
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hTextID = TEXT_GAMECORNER_ROCKET_AFTER_BATTLE
	ld a, TEXT_GAMECORNER_ROCKET_AFTER_BATTLE
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hSpriteIndex = GAMECORNER_ROCKET
	ld a, GAMECORNER_ROCKET
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> moves = GameCornerMovement_Rocket_WalkAroundPlayer
	ld de, GameCornerMovement_Rocket_WalkAroundPlayer
;> if wYCoord == 6:                    # in line with the stairs: straight there
	ld a, [wYCoord]
	cp 6
	jr nz, .not_direct_movement
;>     moves = GameCornerMovement_Rocket_WalkDirect
	ld de, GameCornerMovement_Rocket_WalkDirect
	jr .got_rocket_movement
.not_direct_movement
;> elif wXCoord == 8:
	ld a, [wXCoord]
	cp 8
	jr nz, .got_rocket_movement
;>     moves = GameCornerMovement_Rocket_WalkDirect
	ld de, GameCornerMovement_Rocket_WalkDirect
.got_rocket_movement
;> hSpriteIndex = GAMECORNER_ROCKET
	ld a, GAMECORNER_ROCKET
	ldh [hSpriteIndex], a
;> MoveSprite(moves)
	call MoveSprite
;> wGameCornerCurScript = SCRIPT_GAMECORNER_ROCKET_EXIT
	ld a, SCRIPT_GAMECORNER_ROCKET_EXIT
	ld [wGameCornerCurScript], a
	ret

;@ path: scripts/GameCorner
GameCornerMovement_Rocket_WalkAroundPlayer:
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db -1 ; end

;@ path: scripts/GameCorner
GameCornerMovement_Rocket_WalkDirect:
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db -1 ; end

