;@ When the Rocket has left: remove him, and redo the map's entry setup (lucky machine, hidden door).
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
GameCornerRocketExitScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
;>     return
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wToggleableObjectIndex = TOGGLE_GAME_CORNER_ROCKET
	ld a, TOGGLE_GAME_CORNER_ROCKET
	ld [wToggleableObjectIndex], a
;> HideObject()
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1 | 1 << BIT_CUR_MAP_LOADED_2
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
	set BIT_CUR_MAP_LOADED_2, [hl]
;> wGameCornerCurScript = SCRIPT_GAMECORNER_DEFAULT
	ld a, SCRIPT_GAMECORNER_DEFAULT
	ld [wGameCornerCurScript], a
	ret

