;@ path: scripts/GameCorner
;@ def GameCornerClerk1Text() -> hl
;@ The coin clerk: sells 50 coins for ¥1000, if the player has the Coin Case, room for 9 more coins
;@ (under 9990) and the money; the money and coins box stays on screen.
;@ test: skip a text script: the code after text_asm is run by the text engine
GameCornerClerk1Text:
	db TX_START_ASM
	; Show player's coins
;> GameCornerDrawCoinBox()
	call GameCornerDrawCoinBox
;> PrintText(GameCornerClerk1Text.DoYouNeedSomeGameCoins)
	ld hl, .DoYouNeedSomeGameCoins
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .declined
;>     text = GameCornerClerk1Text.PleaseComePlaySometime
;> elif IsItemInBag(COIN_CASE):                # zero flag: no Coin Case
	; Can only get more coins if you
	; - have the Coin Case
	ld b, COIN_CASE
	call IsItemInBag
	jr z, .no_coin_case
;>     text = GameCornerClerk1Text.DontHaveCoinCase
;> elif not Has9990Coins()[0]:                 # no carry: 9990 coins or more
	; - have room in the Coin Case for at least 9 coins
	call Has9990Coins
	jr nc, .coin_case_full
;>     text = GameCornerClerk1Text.CoinCaseIsFull
;> else:
;>     hMoney[0], hMoney[1], hMoney[2] = 0x00, 0x10, 0x00    # ¥1000 in BCD
	; - have at least 1000 yen
	xor a
	ldh [hMoney], a
	ldh [hMoney + 2], a
	ld a, $10
	ldh [hMoney + 1], a
;>     if HasEnoughMoney()[0]:
	call HasEnoughMoney
	jr nc, .buy_coins
;>         text = GameCornerClerk1Text.CantAffordTheCoins
	ld hl, .CantAffordTheCoins
	jr .print_ret
;>     else:
.buy_coins
;>         hMoney[0], hMoney[1], hMoney[2] = 0x00, 0x10, 0x00
	; Spend 1000 yen
	xor a
	ldh [hMoney], a
	ldh [hMoney + 2], a
	ld a, $10
	ldh [hMoney + 1], a
;>         SubBCDPredef()                  # wPlayerMoney -= hMoney (3 BCD bytes)
	ld hl, hMoney + 2
	ld de, wPlayerMoney + 2
	ld c, $3
	ld a, (SubBCDPredefPredef - PredefPointers) / 3
	call Predef
;>         hUnusedCoinsByte = 0
	; Receive 50 coins
	xor a
	ldh [hUnusedCoinsByte], a
;>         hCoins[0], hCoins[1] = 0x00, 0x50
	ldh [hCoins], a
	ld a, $50
	ldh [hCoins + 1], a
;>         AddBCDPredef()                  # wPlayerCoins += hCoins (2 BCD bytes)
	ld de, wPlayerCoins + 1
	ld hl, hCoins + 1
	ld c, $2
	ld a, (AddBCDPredefPredef - PredefPointers) / 3
	call Predef
;>         GameCornerDrawCoinBox()
	; Update display
	call GameCornerDrawCoinBox
;>         text = GameCornerClerk1Text.ThanksHereAre50Coins
	ld hl, .ThanksHereAre50Coins
	jr .print_ret
;> PrintText(text)
.declined
	ld hl, .PleaseComePlaySometime
	jr .print_ret
.coin_case_full
	ld hl, .CoinCaseIsFull
	jr .print_ret
.no_coin_case
	ld hl, .DontHaveCoinCase
.print_ret
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

