;@ def GameCornerFishingGuruText() -> hl
;@ A gambler who gives 10 coins once, if the player has the Coin Case and fewer than 9990 coins.
;@ test: skip a text script: the code after text_asm is run by the text engine
GameCornerFishingGuruText:
	db TX_START_ASM
;> if event(EVENT_GOT_10_COINS):
	ld a, [wEventFlags + $37]
	bit (EVENT_GOT_10_COINS) % 8, a
	jr nz, .alreadyGotNpcCoins
;>     text = GameCornerFishingGuruText.WinsComeAndGoText
;> else:
;>     PrintText(GameCornerFishingGuruText.WantToPlayText)
	ld hl, .WantToPlayText
	call PrintText
;>     if IsItemInBag(COIN_CASE):            # zero flag: no Coin Case
	ld b, COIN_CASE
	call IsItemInBag
	jr z, .dontHaveCoinCase
;>         text = GameCornerOopsForgotCoinCaseText
;>     elif not Has9990Coins()[0]:
	call Has9990Coins
	jr nc, .coinCaseFull
;>         text = GameCornerFishingGuruText.DontNeedMyCoinsText
;>     else:
;>         hUnusedCoinsByte = 0
	xor a
	ldh [hUnusedCoinsByte], a
;>         hCoins[0], hCoins[1] = 0x00, 0x10
	ldh [hCoins], a
	ld a, $10
	ldh [hCoins + 1], a
;>         AddBCDPredef()                  # wPlayerCoins += hCoins (2 BCD bytes)
	ld de, wPlayerCoins + 1
	ld hl, hCoins + 1
	ld c, $2
	ld a, (AddBCDPredefPredef - PredefPointers) / 3
	call Predef
;>         set_event(EVENT_GOT_10_COINS)
	ld hl, wEventFlags + $37
	set (EVENT_GOT_10_COINS) % 8, [hl]
;>         wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;>         text = GameCornerFishingGuruText.Received10CoinsText
	ld hl, .Received10CoinsText
	jr .print_ret
;> PrintText(text)
.alreadyGotNpcCoins
	ld hl, .WinsComeAndGoText
	jr .print_ret
.coinCaseFull
	ld hl, .DontNeedMyCoinsText
	jr .print_ret
.dontHaveCoinCase
	ld hl, GameCornerOopsForgotCoinCaseText
.print_ret
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

