	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(GameCornerRocketText.BattleEndText, GameCornerRocketText.BattleEndText)
	ld hl, .BattleEndText
	ld de, .BattleEndText
	call SaveEndBattleTextPointers
;> wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;> EngageMapTrainer()
	call EngageMapTrainer
;> InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hJoyPressed = 0
	ldh [hJoyPressed], a
;> hJoyReleased = 0
	ldh [hJoyReleased], a
;> wGameCornerCurScript = SCRIPT_GAMECORNER_ROCKET_BATTLE
	ld a, SCRIPT_GAMECORNER_ROCKET_BATTLE
	ld [wGameCornerCurScript], a
;> return TextScriptEnd()
	jp TextScriptEnd

