;@ path: scripts/GameCorner
;@ def GameCornerPosterText() -> hl
;@ The poster: the player finds a switch behind it (with a click), presses it, and the stairs to the
;@ Rocket Hideout open with the "go inside" sound.
;@ test: skip a text script: the code after text_asm is run by the text engine
GameCornerPosterText:
	db TX_START_ASM
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> PrintText(GameCornerPosterText.SwitchBehindPosterText)    # its own text_asm plays SFX_SWITCH
	ld hl, .SwitchBehindPosterText
	call PrintText
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> PlaySound(SFX_GO_INSIDE)
	ld a, SFX_GO_INSIDE
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> set_event(EVENT_FOUND_ROCKET_HIDEOUT)
	ld hl, wEventFlags + $37
	set (EVENT_FOUND_ROCKET_HIDEOUT) % 8, [hl]
;> wNewTileBlockID = 0x43
	ld a, $43
	ld [wNewTileBlockID], a
;> ReplaceTileBlock()                  # block row 2, column 8 (b, c through the predef)
	ld bc, ((2) & $ff) << 8 + ((8) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
;> return TextScriptEnd()
	jp TextScriptEnd

.SwitchBehindPosterText:
	db TX_FAR
	dw _GameCornerPosterSwitchBehindPosterText
	db BANK(_GameCornerPosterSwitchBehindPosterText)
	db TX_START_ASM
	ld a, SFX_SWITCH
	call PlaySound
	call WaitForSoundToFinish
	jp TextScriptEnd

