;@ path: scripts/GameCorner
;@ def GameCornerDrawCoinBox()
;@ The box in the top right corner with the player's money and coins.
GameCornerDrawCoinBox:
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> TextBoxBorder(coord(11, 0), 5, 7)
	ld hl, (0) * SCREEN_WIDTH + (11) + wTileMap
	ld b, 5
	ld c, 7
	call TextBoxBorder
;> UpdateSprites()
	call UpdateSprites
;> ClearScreenArea(coord(12, 1), 7, 4)
	ld hl, (1) * SCREEN_WIDTH + (12) + wTileMap
	ld b, 4
	ld c, 7
	call ClearScreenArea
;> PlaceString(GameCornerMoneyText, coord(12, 2))
	ld hl, (2) * SCREEN_WIDTH + (12) + wTileMap
	ld de, GameCornerMoneyText
	call PlaceString
;> PlaceString(GameCornerBlankText1, coord(12, 3))
	ld hl, (3) * SCREEN_WIDTH + (12) + wTileMap
	ld de, GameCornerBlankText1
	call PlaceString
;> PrintBCDNumber(wPlayerMoney, coord(12, 3), 3 | MONEY_SIGN | LEADING_ZEROES)
	ld hl, (3) * SCREEN_WIDTH + (12) + wTileMap
	ld de, wPlayerMoney
	ld c, 3 | MONEY_SIGN | LEADING_ZEROES
	call PrintBCDNumber
;> PlaceString(GameCornerCoinText, coord(12, 4))
	ld hl, (4) * SCREEN_WIDTH + (12) + wTileMap
	ld de, GameCornerCoinText
	call PlaceString
;> PlaceString(GameCornerBlankText2, coord(12, 5))
	ld hl, (5) * SCREEN_WIDTH + (12) + wTileMap
	ld de, GameCornerBlankText2
	call PlaceString
;> PrintBCDNumber(wPlayerCoins, coord(15, 5), 2 | LEADING_ZEROES)
	ld hl, (5) * SCREEN_WIDTH + (15) + wTileMap
	ld de, wPlayerCoins
	ld c, 2 | LEADING_ZEROES
	call PrintBCDNumber
;> wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY)
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
	ret

