;@ path: scripts/GameCorner
;@ def Has9990Coins() -> (carry, zero)
;@ Compare the player's coins with 9990: carry if fewer, zero if exactly 9990.
Has9990Coins:
;> hCoins[0] = 0x99                        # 9990 in BCD
;> hCoins[1] = 0x90
	ld a, $99
	ldh [hCoins], a
	ld a, $90
	ldh [hCoins + 1], a
;> return HasEnoughCoins()
	jp HasEnoughCoins
