;@ path: scripts/CeladonDiner
;@ def CeladonDinerGymGuideText() -> hl
;@ The man who lost everything at the slots: gives the Coin Case once, if the bag has room.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeladonDinerGymGuideText:
	db TX_START_ASM
;> if event(EVENT_GOT_COIN_CASE):
;>@got     PrintText(CeladonDinerGymGuideText.WinItBackText)
	ld a, [wEventFlags + $3C]
	bit (EVENT_GOT_COIN_CASE) % 8, a
	jr nz, .got_item
;> else:
;>     PrintText(CeladonDinerGymGuideText.ImFlatOutBustedText)
	ld hl, .ImFlatOutBustedText
	call PrintText
;>     if GiveItem(COIN_CASE, 1):
	ld bc, ((COIN_CASE) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         set_event(EVENT_GOT_COIN_CASE)
	ld hl, wEventFlags + $3C
	set (EVENT_GOT_COIN_CASE) % 8, [hl]
;>         PrintText(CeladonDinerGymGuideText.ReceivedCoinCaseText)
	ld hl, .ReceivedCoinCaseText
	call PrintText
	jr .done
.bag_full
;>     else:
;>         PrintText(CeladonDinerGymGuideText.CoinCaseNoRoomText)
	ld hl, .CoinCaseNoRoomText
	call PrintText
	jr .done
.got_item
;=@got
	ld hl, .WinItBackText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.ImFlatOutBustedText:
	db TX_FAR
	dw _CeladonDinerGymGuideImFlatOutBustedText
	db BANK(_CeladonDinerGymGuideImFlatOutBustedText)
	db TX_END

