	db BANK(_MtMoonPokecenterGentlemanText)
	db TX_END

;@ path: scripts/MtMoonPokecenter
;@ def MtMoonPokecenterMagikarpSalesmanText() -> hl
;@ The Magikarp salesman: sells a level 5 Magikarp for ¥500, once (no refunds).
;@ test: skip a text script: the code after text_asm is run by the text engine
MtMoonPokecenterMagikarpSalesmanText:
	db TX_START_ASM
;> if event(EVENT_BOUGHT_MAGIKARP):           # (bit 7 of the byte: add a moves it into carry)
	ld a, [wEventFlags + $7F]
	add a
	jp c, .alreadyBoughtMagikarp
;>@refund     PrintText(MtMoonPokecenterMagikarpSalesmanText.NoRefundsText)
;>@refundend     return TextScriptEnd()
;> PrintText(MtMoonPokecenterMagikarpSalesmanText.IGotADealText)
	ld hl, .IGotADealText
	call PrintText
;> wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;> DisplayTextBoxID()
	call DisplayTextBoxID
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:                         # "no"
	ld a, [wCurrentMenuItem]
	and a
	jp nz, .choseNo
;>@no     PrintText(MtMoonPokecenterMagikarpSalesmanText.NoText)
;>@noend     return TextScriptEnd()
;> hMoney[0] = hMoney[2] = 0x00            # 500, in BCD
	ldh [hMoney], a
	ldh [hMoney + 2], a
;> hMoney[1] = 0x05
	ld a, $5
	ldh [hMoney + 1], a
;> if HasEnoughMoney():                         # carry: not enough
	call HasEnoughMoney
	jr nc, .enoughMoney
;>     PrintText(MtMoonPokecenterMagikarpSalesmanText.NoMoneyText)
	ld hl, .NoMoneyText
;>     return TextScriptEnd()
	jr .printText
.enoughMoney
;> if GivePokemon(MAGIKARP, 5):
	ld bc, ((MAGIKARP) & $ff) << 8 + ((5) & $ff)
	call GivePokemon
	jr nc, .done
;>     wPriceTemp[0] = wPriceTemp[2] = 0x00
	xor a
	ld [wPriceTemp], a
	ld [wPriceTemp + 2], a
;>     wPriceTemp[1] = 0x05
	ld a, $5
	ld [wPriceTemp + 1], a
;>     predef(SubBCDPredef, hl=addr(wPriceTemp) + 2, de=addr(wPlayerMoney) + 2, bc=3)     # pay the 500
	ld hl, wPriceTemp + 2
	ld de, wPlayerMoney + 2
	ld c, $3
	ld a, (SubBCDPredefPredef - PredefPointers) / 3
	call Predef
;>     wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;>     DisplayTextBoxID()
	call DisplayTextBoxID
;>     set_event(EVENT_BOUGHT_MAGIKARP)
	ld hl, wEventFlags + $7F
	set (EVENT_BOUGHT_MAGIKARP) % 8, [hl]
;> return TextScriptEnd()
	jr .done
.choseNo
;=@no
	ld hl, .NoText
;=@noend
	jr .printText
.alreadyBoughtMagikarp
;=@refund
	ld hl, .NoRefundsText
.printText
	call PrintText
.done
;=@refundend
	jp TextScriptEnd

.IGotADealText
	db TX_FAR
	dw _MtMoonPokecenterMagikarpSalesmanIGotADealText
	db BANK(_MtMoonPokecenterMagikarpSalesmanIGotADealText)
	db TX_END

.NoText
	db TX_FAR
	dw _MtMoonPokecenterMagikarpSalesmanNoText
	db BANK(_MtMoonPokecenterMagikarpSalesmanNoText)
	db TX_END

.NoMoneyText
	db TX_FAR
	dw _MtMoonPokecenterMagikarpSalesmanNoMoneyText
	db BANK(_MtMoonPokecenterMagikarpSalesmanNoMoneyText)
	db TX_END

.NoRefundsText
	db TX_FAR
	dw _MtMoonPokecenterMagikarpSalesmanNoRefundsText
	db BANK(_MtMoonPokecenterMagikarpSalesmanNoRefundsText)
	db TX_END

