;@ The youngster: the in-game trade of a Nidoran♂ for his Nidoran♀ (TERRY).
;@ test: skip a text script: the code after text_asm is run by the text engine
Route11Gate2FYoungsterText:
	db TX_START_ASM
;> wWhichTrade = TRADE_FOR_TERRY
	xor a ; TRADE_FOR_TERRY
	ld [wWhichTrade], a
;> predef(DoInGameTradeDialogue)
	ld a, (DoInGameTradeDialoguePredef - PredefPointers) / 3
	call Predef

;> return Route11Gate2FScriptEnd()
;@ path: scripts/Route11Gate2F
;@ def Route11Gate2FScriptEnd() -> hl
;@ The shared end of the gate's text scripts.
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
Route11Gate2FScriptEnd:
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: scripts/Route11Gate2F
;@ def Route11Gate2FOaksAideText() -> hl
;@ Oak's aide: once 30 kinds of Pokémon are registered as owned, he gives the Itemfinder, and then explains it.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route11Gate2FOaksAideText:
	db TX_START_ASM
;> if not event(EVENT_GOT_ITEMFINDER):
	ld a, [wEventFlags + $8F]
	add a
	jr c, .got_item
;>     hOaksAideRequirement = 30
	ld a, 30
	ldh [hOaksAideRequirement], a
;>     hOaksAideRewardItem = wNamedObjectIndex = ITEMFINDER
	ld a, ITEMFINDER
	ldh [hOaksAideRewardItem], a
	ld [wNamedObjectIndex], a
;>     CopyData(GetItemName(), addr(wOaksAideRewardItemName), ITEM_NAME_LENGTH)
	call GetItemName
	ld h, d
	ld l, e
	ld de, wOaksAideRewardItemName
	ld bc, ITEM_NAME_LENGTH
	call CopyData
;>     predef(OaksAideScript)
	ld a, (OaksAideScriptPredef - PredefPointers) / 3
	call Predef
;>     if hOaksAideResult != OAKS_AIDE_GOT_ITEM:
;>         return Route11Gate2FScriptEnd()
	ldh a, [hOaksAideResult]
	dec a ; OAKS_AIDE_GOT_ITEM?
	jr nz, .no_item
;>     set_event(EVENT_GOT_ITEMFINDER)
	ld hl, wEventFlags + $8F
	set (EVENT_GOT_ITEMFINDER) % 8, [hl]
.got_item
;> PrintText(Route11Gate2FOaksAideText.ItemfinderDescriptionText)
	ld hl, .ItemfinderDescriptionText
	call PrintText
.no_item
;> return Route11Gate2FScriptEnd()
	jr Route11Gate2FScriptEnd

.ItemfinderDescriptionText:
	db TX_FAR
	dw _Route11Gate2FOaksAideItemfinderDescriptionText
	db BANK(_Route11Gate2FOaksAideItemfinderDescriptionText)
	db TX_END

;@ path: scripts/Route11Gate2F
;@ def Route11Gate2FLeftBinocularsText() -> hl
;@ The left binoculars: looking out (facing up) shows the Snorlax blocking Route 12 - or, once it is beaten,
;@ the clear road.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route11Gate2FLeftBinocularsText:
	db TX_START_ASM
;> if mem[wSpritePlayerStateData1FacingDirection] != SPRITE_FACING_UP:
;>     return GateUpstairsScript_PrintIfFacingUp(0)     # not facing up: prints nothing
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	jp nz, GateUpstairsScript_PrintIfFacingUp
;> if event(EVENT_BEAT_ROUTE12_SNORLAX):
	ld a, [wEventFlags + $91]
	bit (EVENT_BEAT_ROUTE12_SNORLAX) % 8, a
	ld hl, .SnorlaxText
	jr z, .print
;>     PrintText(Route11Gate2FLeftBinocularsText.NoSnorlaxText)
	ld hl, .NoSnorlaxText
.print
	call PrintText
;> else:
;>     PrintText(Route11Gate2FLeftBinocularsText.SnorlaxText)
;> return TextScriptEnd()
	jp TextScriptEnd

.SnorlaxText:
	db TX_FAR
	dw _Route11Gate2FLeftBinocularsSnorlaxText
	db BANK(_Route11Gate2FLeftBinocularsSnorlaxText)
	db TX_END

.NoSnorlaxText:
	db TX_FAR
	dw _Route11Gate2FLeftBinocularsNoSnorlaxText
	db BANK(_Route11Gate2FLeftBinocularsNoSnorlaxText)
	db TX_END

