;@ path: scripts/Route12Gate2F
;@ def Route12Gate2FBrunetteGirlText() -> hl
;@ The girl upstairs: gives TM39 (SWIFT) once, if the bag has room, and explains it afterwards.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route12Gate2FBrunetteGirlText:
	db TX_START_ASM
;> if event(EVENT_GOT_TM39):
	ld a, [wEventFlags + $90]
	rrca
	jr c, .got_item
;>@early     PrintText(Route12Gate2FBrunetteGirlText.TM39ExplanationText)
;> else:
;>     PrintText(Route12Gate2FBrunetteGirlText.YouCanHaveThisText)
	ld hl, .YouCanHaveThisText
	call PrintText
;>     if GiveItem(TM_SWIFT, 1):
	ld bc, ((TM_SWIFT) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         PrintText(Route12Gate2FBrunetteGirlText.ReceivedTM39Text)
	ld hl, .ReceivedTM39Text
	call PrintText
;>         set_event(EVENT_GOT_TM39)
	ld hl, wEventFlags + $90
	set (EVENT_GOT_TM39) % 8, [hl]
	jr .done
.bag_full
;>     else:
;>         PrintText(Route12Gate2FBrunetteGirlText.TM39NoRoomText)
	ld hl, .TM39NoRoomText
	call PrintText
	jr .done
.got_item
;=@early
	ld hl, .TM39ExplanationText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.YouCanHaveThisText:
	db TX_FAR
	dw _Route12Gate2FBrunetteGirlYouCanHaveThisText
	db BANK(_Route12Gate2FBrunetteGirlYouCanHaveThisText)
	db TX_END

.ReceivedTM39Text:
	db TX_FAR
	dw _Route12Gate2FBrunetteGirlReceivedTM39Text
	db BANK(_Route12Gate2FBrunetteGirlReceivedTM39Text)
	db TX_SOUND_GET_ITEM_1
	db TX_END

.TM39ExplanationText:
	db TX_FAR
	dw _Route12Gate2FBrunetteGirlTM39ExplanationText
	db BANK(_Route12Gate2FBrunetteGirlTM39ExplanationText)
	db TX_END

.TM39NoRoomText:
	db TX_FAR
	dw _Route12Gate2FBrunetteGirlTM39NoRoomText
	db BANK(_Route12Gate2FBrunetteGirlTM39NoRoomText)
	db TX_END

