;@ path: scripts/Route12Gate2F
;@ def GateUpstairsScript_PrintIfFacingUp(text: hl) -> hl
;@ The binoculars upstairs in the gates: print what the player sees only when looking out (facing up);
;@ otherwise nothing happens (and no button press is waited for).
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
GateUpstairsScript_PrintIfFacingUp:
;> if mem[wSpritePlayerStateData1FacingDirection] == SPRITE_FACING_UP:
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	jr z, .up
	ld a, TRUE
	jr .done
.up
;>     PrintText(text)
	call PrintText
;>     wDoNotWaitForButtonPressAfterDisplayingText = 0
	xor a
.done
;> else:
;>     wDoNotWaitForButtonPressAfterDisplayingText = TRUE
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> return TextScriptEnd()
	jp TextScriptEnd
