;@ path: scripts/Route15Gate2F
;@ def Route15Gate2FOaksAideText() -> hl
;@ Oak's aide: once 50 kinds of Pokémon are registered as owned, he gives the Exp. All, and then explains it.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route15Gate2FOaksAideText:
	db TX_START_ASM
;> if not event(EVENT_GOT_EXP_ALL):
	ld a, [wEventFlags + $96]
	bit (EVENT_GOT_EXP_ALL) % 8, a
	jr nz, .got_item
;>     hOaksAideRequirement = 50
	ld a, 50
	ldh [hOaksAideRequirement], a
;>     hOaksAideRewardItem = wNamedObjectIndex = EXP_ALL
	ld a, EXP_ALL
	ldh [hOaksAideRewardItem], a
	ld [wNamedObjectIndex], a
;>     GetItemName()
	call GetItemName
;>     CopyData(addr(wNameBuffer), addr(wOaksAideRewardItemName), ITEM_NAME_LENGTH)
	ld hl, wNameBuffer
	ld de, wOaksAideRewardItemName
	ld bc, ITEM_NAME_LENGTH
	call CopyData
;>     predef(OaksAideScript)
	ld a, (OaksAideScriptPredef - PredefPointers) / 3
	call Predef
;>     if hOaksAideResult != OAKS_AIDE_GOT_ITEM:
;>         return TextScriptEnd()
	ldh a, [hOaksAideResult]
	cp OAKS_AIDE_GOT_ITEM
	jr nz, .no_item
;>     set_event(EVENT_GOT_EXP_ALL)
	ld hl, wEventFlags + $96
	set (EVENT_GOT_EXP_ALL) % 8, [hl]
.got_item
;> PrintText(Route15Gate2FOaksAideText.ExpAllText)
	ld hl, .ExpAllText
	call PrintText
.no_item
;> return TextScriptEnd()
	jp TextScriptEnd

.ExpAllText:
	db TX_FAR
	dw _Route15Gate2FOaksAideExpAllText
	db BANK(_Route15Gate2FOaksAideExpAllText)
	db TX_END

