;@ path: scripts/Route18Gate1F
;@ def Route18Gate1F_Script()
;@ The Cycling Road gate on Route 18: here the player gets off the bike for good; run the current step of the
;@ gate's script (the guard who stops anyone without a Bicycle).
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
Route18Gate1F_Script:
;> wStatusFlags6 &= ~(1 << BIT_ALWAYS_ON_BIKE)
	ld hl, wStatusFlags6
	res BIT_ALWAYS_ON_BIKE, [hl]
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> CallFunctionInTable(wRoute18Gate1FCurScript, Route18Gate1F_ScriptPointers)
	ld a, [wRoute18Gate1FCurScript]
	ld hl, Route18Gate1F_ScriptPointers
	jp CallFunctionInTable

;@ path: scripts/Route18Gate1F
Route18Gate1F_ScriptPointers:
	dw Route18Gate1FDefaultScript
DEF SCRIPT_ROUTE18GATE1F_DEFAULT EQU 0
	dw Route18Gate1FPlayerMovingUpScript
DEF SCRIPT_ROUTE18GATE1F_PLAYER_MOVING_UP EQU 1
	dw Route18Gate1FGuardScript
DEF SCRIPT_ROUTE18GATE1F_GUARD EQU 2
	dw Route18Gate1FPlayerMovingRightScript
DEF SCRIPT_ROUTE18GATE1F_PLAYER_MOVING_RIGHT EQU 3

;@ path: scripts/Route18Gate1F
;@ def Route18Gate1FDefaultScript()
;@ Without a Bicycle, walking past the guard's counter makes him call out; from further down the player is
;@ walked up to the counter first, then the guard sends him back.
;@ test: skip the guard's spots sit under a local label, which the pseudo-code can only name
Route18Gate1FDefaultScript:
;> if not Route16Gate1FIsBicycleInBagScript():     # has the Bicycle
;>     return
	call Route16Gate1FIsBicycleInBagScript
	ret nz
;> if not ArePlayerCoordsInArray(Route18Gate1FDefaultScript.StopsPlayerCoords):
;>     return
	ld hl, .StopsPlayerCoords
	call ArePlayerCoordsInArray
	ret nc
;> hTextID = TEXT_ROUTE18GATE1F_GUARD_EXCUSE_ME
	ld a, TEXT_ROUTE18GATE1F_GUARD_EXCUSE_ME
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> if wCoordIndex == 1:                          # right at the counter
	ld a, [wCoordIndex]
	cp $1
	jr z, .next_to_counter
;>@e1     wRoute18Gate1FCurScript = SCRIPT_ROUTE18GATE1F_GUARD
;>@e2     return
;> wSimulatedJoypadStatesIndex = wCoordIndex - 1
	ld a, [wCoordIndex]
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> FillMemory(addr(wSimulatedJoypadStatesEnd), wCoordIndex - 1, PAD_UP)
	ld b, 0
	ld c, a
	ld a, PAD_UP
	ld hl, wSimulatedJoypadStatesEnd
	call FillMemory
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wRoute18Gate1FCurScript = SCRIPT_ROUTE18GATE1F_PLAYER_MOVING_UP
	ld a, SCRIPT_ROUTE18GATE1F_PLAYER_MOVING_UP
	ld [wRoute18Gate1FCurScript], a
	ret
.next_to_counter
;=@e1
	ld a, SCRIPT_ROUTE18GATE1F_GUARD
	ld [wRoute18Gate1FCurScript], a
;=@e2
	ret

.StopsPlayerCoords:
	db 3, 4
	db 4, 4
	db 5, 4
	db 6, 4
	db -1 ; end

