	db $1f, $01, $01, $2a, $01, $01, $01, $1f, $01, $01, $01, $01, $1f, $01, $01, $1b
	db $1b, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $02, $01, $01, $01, $01
	db $17, $01, $01, $1b, $1b, $01, $01, $01, $01, $01, $01, $01, $14, $16, $20, $22
	db $01, $14, $16, $01, $1f, $01, $01, $1b, $1b, $01, $01, $01, $01, $01, $01, $01
	db $18, $1a, $01, $01, $01, $18, $1a, $01, $01, $01, $01, $1b, $1b, $01, $01, $01
	db $01, $14, $16, $01, $18, $1a, $01, $01, $01, $1c, $1e, $01, $01, $01, $01, $1b
	db $1b, $01, $01, $01, $01, $18, $1a, $01, $18, $1a, $01, $01, $01, $01, $01, $01
	db $01, $01, $01, $1f, $1f, $20, $21, $21, $22, $1c, $1e, $24, $1c, $1e, $20, $21
	db $21, $21, $21, $21, $21, $21, $21, $22

MtMoonB2F_h::
	db CAVERN
	db $12, $14
	dw MtMoonB2F_Blocks
	dw MtMoonB2F_TextPointers
	dw MtMoonB2F_Script
	db 0
	dw MtMoonB2F_Object
;@ path: scripts/MtMoonB2F
;@ def MtMoonB2F_Script()
;@ Mt. Moon B2F's map script: run the current step (the trainers, the fossil collector); once he is beaten,
;@ there are no wild battles in the fossil corner.
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
MtMoonB2F_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wMtMoonB2FCurScript = ExecuteCurMapScriptInTable(wMtMoonB2FCurScript, MtMoon3TrainerHeaders, MtMoonB2F_ScriptPointers)
	ld hl, MtMoon3TrainerHeaders
	ld de, MtMoonB2F_ScriptPointers
	ld a, [wMtMoonB2FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wMtMoonB2FCurScript], a
;> if not event(EVENT_BEAT_MT_MOON_EXIT_SUPER_NERD):
;>     return
	ld a, [wEventFlags + $AF]
	bit (EVENT_BEAT_MT_MOON_EXIT_SUPER_NERD) % 8, a
	ret z
;> if ArePlayerCoordsInArray(MtMoonB2FFossilAreaCoords):
	ld hl, MtMoonB2FFossilAreaCoords
	call ArePlayerCoordsInArray
	jr nc, .enable_battles
;>     wStatusFlags4 |= 1 << BIT_NO_BATTLES
	ld hl, wStatusFlags4
	set BIT_NO_BATTLES, [hl]
	ret
.enable_battles
;> else:
	ld hl, wStatusFlags4
;>     wStatusFlags4 &= ~(1 << BIT_NO_BATTLES)
	res BIT_NO_BATTLES, [hl]
	ret

;@ path: scripts/MtMoonB2F
MtMoonB2FFossilAreaCoords:
	db 5, 11
	db 5, 12
	db 5, 13
	db 5, 14
	db 6, 11
	db 6, 12
	db 6, 13
	db 6, 14
	db 7, 11
	db 7, 12
	db 7, 13
	db 7, 14
	db 8, 11
	db 8, 12
	db 8, 13
	db 8, 14
	db -1 ; end

;@ path: scripts/MtMoonB2F
;@ def MtMoonB2FResetScripts()
;@ Back to the default step, with the controls given back.
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
MtMoonB2FResetScripts:
;> wJoyIgnore = 0
	xor a ; SCRIPT_MTMOONB2F_DEFAULT
	ld [wJoyIgnore], a
;> wMtMoonB2FCurScript = SCRIPT_MTMOONB2F_DEFAULT
	ld [wMtMoonB2FCurScript], a
;> wCurMapScript = SCRIPT_MTMOONB2F_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/MtMoonB2F
MtMoonB2F_ScriptPointers:
	dw MtMoonB2FDefaultScript
DEF SCRIPT_MTMOONB2F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_MTMOONB2F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_MTMOONB2F_END_BATTLE EQU 2
	dw MtMoonB2FDefeatedSuperNerdScript
DEF SCRIPT_MTMOONB2F_DEFEATED_SUPER_NERD EQU 3
	dw MtMoonB2FMoveSuperNerdScript
DEF SCRIPT_MTMOONB2F_MOVE_SUPER_NERD EQU 4
	dw MtMoonB2FSuperNerdTakesOtherFossilScript
DEF SCRIPT_MTMOONB2F_SUPER_NERD_TAKES_OTHER_FOSSIL EQU 5

;@ path: scripts/MtMoonB2F
;@ def MtMoonB2FDefaultScript()
;@ Until the fossil collector is beaten, stepping in front of him (8, 13) makes him challenge the player;
;@ otherwise see whether the trainers spot the player.
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
MtMoonB2FDefaultScript:
;> if event(EVENT_BEAT_MT_MOON_EXIT_SUPER_NERD):
;>     return MtMoonB2FCheckGotAFossil()
	ld a, [wEventFlags + $AF]
	bit (EVENT_BEAT_MT_MOON_EXIT_SUPER_NERD) % 8, a
	jp nz, MtMoonB2FCheckGotAFossil
;> if wYCoord != 8:
;>     return MtMoonB2FCheckGotAFossil()
	ld a, [wYCoord]
	cp 8
	jp nz, MtMoonB2FCheckGotAFossil
;> if wXCoord != 13:
;>     return MtMoonB2FCheckGotAFossil()
	ld a, [wXCoord]
	cp 13
	jp nz, MtMoonB2FCheckGotAFossil
;> hJoyHeld = 0                            # in front of him: he speaks
	xor a
	ldh [hJoyHeld], a
;> hTextID = TEXT_MTMOONB2F_SUPER_NERD
;> return DisplayTextID()
	ld a, TEXT_MTMOONB2F_SUPER_NERD
	ldh [hTextID], a
	jp DisplayTextID

;@ path: scripts/MtMoonB2F
;@ def MtMoonB2FCheckGotAFossil()
;@ Until a fossil has been taken, the trainers keep watching for the player.
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
MtMoonB2FCheckGotAFossil:
;> if not event(EVENT_GOT_DOME_FOSSIL) and not event(EVENT_GOT_HELIX_FOSSIL):
;>     return CheckFightingMapTrainers()
	ld a, [wEventFlags + ((EVENT_GOT_DOME_FOSSIL) / 8)]
	and (1 << ((EVENT_GOT_DOME_FOSSIL) % 8)) | (1 << ((EVENT_GOT_HELIX_FOSSIL) % 8))
	jp z, CheckFightingMapTrainers
	ret

;@ path: scripts/MtMoonB2F
;@ def MtMoonB2FDefeatedSuperNerdScript()
;@ After the battle with the fossil collector: lost, start over; won, note it and give the controls back.
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
MtMoonB2FDefeatedSuperNerdScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return MtMoonB2FResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, MtMoonB2FResetScripts
;> UpdateSprites()
	call UpdateSprites
;> Delay3()
	call Delay3
;> set_event(EVENT_BEAT_MT_MOON_EXIT_SUPER_NERD)
	ld hl, wEventFlags + $AF
	set (EVENT_BEAT_MT_MOON_EXIT_SUPER_NERD) % 8, [hl]
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wMtMoonB2FCurScript = SCRIPT_MTMOONB2F_DEFAULT
	ld a, SCRIPT_MTMOONB2F_DEFAULT
	ld [wMtMoonB2FCurScript], a
;> wCurMapScript = SCRIPT_MTMOONB2F_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/MtMoonB2F
;@ def MtMoonB2FMoveSuperNerdScript()
;@ After the player took a fossil: the collector walks over to the other one (right or up, depending on
;@ which fossil the player stands at).
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
MtMoonB2FMoveSuperNerdScript:
;> hSpriteIndex = MTMOONB2F_SUPER_NERD
	ld a, MTMOONB2F_SUPER_NERD
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> if ArePlayerCoordsInArray(MtMoonB2FPlayerNearDomeFossilCoords):
;>     moves = MtMoon3FSuperNerdMoveRightMovementData
	ld hl, MtMoonB2FPlayerNearDomeFossilCoords
	call ArePlayerCoordsInArray
	jr c, .player_near_dome_fossil
;> elif ArePlayerCoordsInArray(MtMoonB2FPlayerNearHelixFossilCoords):
	ld hl, MtMoonB2FPlayerNearHelixFossilCoords
	call ArePlayerCoordsInArray
;>     moves = MtMoon3FSuperNerdMoveUpMovementData
;> else:
;>     return CheckFightingMapTrainers()
	jp nc, CheckFightingMapTrainers
	ld de, MtMoon3FSuperNerdMoveUpMovementData
	jr .continue
.player_near_dome_fossil
	ld de, MtMoon3FSuperNerdMoveRightMovementData
.continue
;> hSpriteIndex = MTMOONB2F_SUPER_NERD
	ld a, MTMOONB2F_SUPER_NERD
	ldh [hSpriteIndex], a
;> MoveSprite(moves)
	call MoveSprite
;> wMtMoonB2FCurScript = SCRIPT_MTMOONB2F_SUPER_NERD_TAKES_OTHER_FOSSIL
	ld a, SCRIPT_MTMOONB2F_SUPER_NERD_TAKES_OTHER_FOSSIL
	ld [wMtMoonB2FCurScript], a
;> wCurMapScript = SCRIPT_MTMOONB2F_SUPER_NERD_TAKES_OTHER_FOSSIL
	ld [wCurMapScript], a
	ret

;@ path: scripts/MtMoonB2F
MtMoonB2FPlayerNearDomeFossilCoords:
	db 7, 12
	db 6, 11
	db 5, 12
	db -1 ; end

;@ path: scripts/MtMoonB2F
MtMoonB2FPlayerNearHelixFossilCoords:
	db 7, 13
	db 6, 14
	db 5, 14
	db -1 ; end

;@ path: scripts/MtMoonB2F
MtMoon3FSuperNerdMoveRightMovementData:
	db NPC_MOVEMENT_RIGHT
;@ path: scripts/MtMoonB2F
MtMoon3FSuperNerdMoveUpMovementData:
	db NPC_MOVEMENT_UP
	db -1 ; end

;@ path: scripts/MtMoonB2F
;@ def MtMoonB2FSuperNerdTakesOtherFossilScript()
;@ When the collector reaches the other fossil: "Then this one is mine!" and it disappears.
;@ test: hLoadedROMBank = 0x12    # the bank this code runs in
MtMoonB2FSuperNerdTakesOtherFossilScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> hTextID = TEXT_MTMOONB2F_SUPER_NERD_THEN_THIS_IS_MINE
	ld a, TEXT_MTMOONB2F_SUPER_NERD_THEN_THIS_IS_MINE
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> if event(EVENT_GOT_DOME_FOSSIL):
	ld a, [wEventFlags + $AF]
	bit (EVENT_GOT_DOME_FOSSIL) % 8, a
	jr z, .got_dome_fossil
;>     wToggleableObjectIndex = TOGGLE_MT_MOON_B2F_FOSSIL_2   # he takes the Helix Fossil
	ld a, TOGGLE_MT_MOON_B2F_FOSSIL_2
	jr .continue
.got_dome_fossil
;> else:
;>     wToggleableObjectIndex = TOGGLE_MT_MOON_B2F_FOSSIL_1   # he takes the Dome Fossil
	ld a, TOGGLE_MT_MOON_B2F_FOSSIL_1
.continue
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wMtMoonB2FCurScript = SCRIPT_MTMOONB2F_DEFAULT
	ld a, SCRIPT_MTMOONB2F_DEFAULT
	ld [wMtMoonB2FCurScript], a
;> wCurMapScript = SCRIPT_MTMOONB2F_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/MtMoonB2F
MtMoonB2F_TextPointers:
	dw MtMoonB2FSuperNerdText
DEF TEXT_MTMOONB2F_SUPER_NERD EQU 1
	dw MtMoonB2FRocket1Text
DEF TEXT_MTMOONB2F_ROCKET1 EQU 2
	dw MtMoonB2FRocket2Text
DEF TEXT_MTMOONB2F_ROCKET2 EQU 3
	dw MtMoonB2FRocket3Text
DEF TEXT_MTMOONB2F_ROCKET3 EQU 4
	dw MtMoonB2FRocket4Text
DEF TEXT_MTMOONB2F_ROCKET4 EQU 5
	dw MtMoonB2FDomeFossilText
DEF TEXT_MTMOONB2F_DOME_FOSSIL EQU 6
	dw MtMoonB2FHelixFossilText
DEF TEXT_MTMOONB2F_HELIX_FOSSIL EQU 7
	dw PickUpItemText
DEF TEXT_MTMOONB2F_HP_UP EQU 8
	dw PickUpItemText
DEF TEXT_MTMOONB2F_TM_MEGA_PUNCH EQU 9
	dw MtMoonB2FSuperNerdThenThisIsMineText
DEF TEXT_MTMOONB2F_SUPER_NERD_THEN_THIS_IS_MINE EQU $A

;@ path: scripts/MtMoonB2F
MtMoon3TrainerHeaders:
;@ path: scripts/MtMoonB2F
MtMoon3TrainerHeader0:
	db $2
	db 4 << 4
	dw wEventFlags + (EVENT_BEAT_MT_MOON_3_TRAINER_0 - $2) / 8
	dw MtMoonB2FRocket1BattleText, MtMoonB2FRocket1AfterBattleText, MtMoonB2FRocket1EndBattleText, MtMoonB2FRocket1EndBattleText
;@ path: scripts/MtMoonB2F
MtMoon3TrainerHeader1:
	db $3
	db 4 << 4
	dw wEventFlags + (EVENT_BEAT_MT_MOON_3_TRAINER_1 - $3) / 8
	dw MtMoonB2FRocket2BattleText, MtMoonB2FRocket2AfterBattleText, MtMoonB2FRocket2EndBattleText, MtMoonB2FRocket2EndBattleText
;@ path: scripts/MtMoonB2F
MtMoon3TrainerHeader2:
	db $4
	db 4 << 4
	dw wEventFlags + (EVENT_BEAT_MT_MOON_3_TRAINER_2 - $4) / 8
	dw MtMoonB2FRocket3BattleText, MtMoonB2FRocket3AfterBattleText, MtMoonB2FRocket3EndBattleText, MtMoonB2FRocket3EndBattleText
;@ path: scripts/MtMoonB2F
MtMoon3TrainerHeader3:
	db $5
	db 4 << 4
	dw wEventFlags + (EVENT_BEAT_MT_MOON_3_TRAINER_3 - $5) / 8
	dw MtMoonB2FRocket4BattleText, MtMoonB2FRocket4AfterBattleText, MtMoonB2FRocket4EndBattleText, MtMoonB2FRocket4EndBattleText
	db -1 ; end

;@ path: scripts/MtMoonB2F
;@ def MtMoonB2FSuperNerdText() -> hl
;@ The fossil collector: before the battle "they're both mine!" and he engages the player; afterwards, take
;@ one each - and once a fossil is taken, he mentions the Pokémon lab.
;@ test: skip a text script: the code after text_asm is run by the text engine
MtMoonB2FSuperNerdText:
	db TX_START_ASM
;> if event(EVENT_BEAT_MT_MOON_EXIT_SUPER_NERD):
	ld a, [wEventFlags + $AF]
	bit (EVENT_BEAT_MT_MOON_EXIT_SUPER_NERD) % 8, a
	jr z, .beat_super_nerd
;>     if event(EVENT_GOT_DOME_FOSSIL) or event(EVENT_GOT_HELIX_FOSSIL):     # (in the same byte)
	and (1 << ((EVENT_GOT_DOME_FOSSIL) % 8)) | (1 << ((EVENT_GOT_HELIX_FOSSIL) % 8))
	jr nz, .got_a_fossil
;>@lab         PrintText(MtMoonB2FSuperNerdTheresAPokemonLabText)
;>     else:
;>         PrintText(MtMoonB2fSuperNerdEachTakeOneText)
	ld hl, MtMoonB2fSuperNerdEachTakeOneText
	call PrintText
	jr .done
.beat_super_nerd
;> else:
;>     PrintText(MtMoonB2FSuperNerdTheyreBothMineText)
	ld hl, MtMoonB2FSuperNerdTheyreBothMineText
	call PrintText
;>     wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;>     SaveEndBattleTextPointers(MtMoonB2FSuperNerdOkIllShareText, MtMoonB2FSuperNerdOkIllShareText)
	ld hl, MtMoonB2FSuperNerdOkIllShareText
	ld de, MtMoonB2FSuperNerdOkIllShareText
	call SaveEndBattleTextPointers
;>     wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;>     EngageMapTrainer()
	call EngageMapTrainer
;>     InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;>     wMtMoonB2FCurScript = SCRIPT_MTMOONB2F_DEFEATED_SUPER_NERD
	ld a, SCRIPT_MTMOONB2F_DEFEATED_SUPER_NERD
	ld [wMtMoonB2FCurScript], a
;>     wCurMapScript = SCRIPT_MTMOONB2F_DEFEATED_SUPER_NERD
	ld [wCurMapScript], a
	jr .done
.got_a_fossil
;=@lab
	ld hl, MtMoonB2FSuperNerdTheresAPokemonLabText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: scripts/MtMoonB2F
;@ def MtMoonB2FRocket1Text() -> hl
;@ Rocket 1, a trainer in Mt Moon B2F: the trainer talk and battle.
;@ test: skip a text script: the code after text_asm is run by the text engine
MtMoonB2FRocket1Text:
	db TX_START_ASM
;> TalkToTrainer(MtMoon3TrainerHeader0)
;> return TextScriptEnd()
	ld hl, MtMoon3TrainerHeader0
	call TalkToTrainer
	jp TextScriptEnd

