;@ path: scripts/MtMoonB2F
;@ def MtMoonB2FDomeFossilText() -> hl
;@ The Dome Fossil: "You want the Dome Fossil?" - on yes, if the bag has room, take it; the collector then
;@ goes for the other one.
;@ test: skip a text script: the code after text_asm is run by the text engine
MtMoonB2FDomeFossilText:
	db TX_START_ASM
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> PrintText(MtMoonB2FDomeFossilText.YouWantText)
	ld hl, .YouWantText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:
;>     return TextScriptEnd()
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .done
;> if not GiveItem(DOME_FOSSIL, 1):
;>     return MtMoonB2FYouHaveNoRoomText()
	ld bc, ((DOME_FOSSIL) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jp nc, MtMoonB2FYouHaveNoRoomText
;> MtMoonB2FReceivedFossilText()
	call MtMoonB2FReceivedFossilText
;> wToggleableObjectIndex = TOGGLE_MT_MOON_B2F_FOSSIL_1
	ld a, TOGGLE_MT_MOON_B2F_FOSSIL_1
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> set_event(EVENT_GOT_DOME_FOSSIL)
	ld hl, wEventFlags + $AF
	set (EVENT_GOT_DOME_FOSSIL) % 8, [hl]
;> wMtMoonB2FCurScript = SCRIPT_MTMOONB2F_MOVE_SUPER_NERD
	ld a, SCRIPT_MTMOONB2F_MOVE_SUPER_NERD
	ld [wMtMoonB2FCurScript], a
;> wCurMapScript = SCRIPT_MTMOONB2F_MOVE_SUPER_NERD
	ld [wCurMapScript], a
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.YouWantText:
	db TX_FAR
	dw _MtMoonB2FDomeFossilYouWantText
	db BANK(_MtMoonB2FDomeFossilYouWantText)
	db TX_END

;@ path: scripts/MtMoonB2F
;@ def MtMoonB2FHelixFossilText() -> hl
;@ The Helix Fossil: "You want the Helix Fossil?" - on yes, if the bag has room, take it; the collector then
;@ goes for the other one.
