SafariZoneSecretHouse_TextPointers:
	dw SafariZoneSecretHouseFishingGuruText
DEF TEXT_SAFARIZONESECRETHOUSE_FISHING_GURU EQU 1

;@ path: scripts/SafariZoneSecretHouse
;@ def SafariZoneSecretHouseFishingGuruText() -> hl
;@ The man in the Safari Zone's secret house: gives HM03 (SURF) once, if the bag has room, and explains it
;@ afterwards.
;@ test: skip a text script: the code after text_asm is run by the text engine
SafariZoneSecretHouseFishingGuruText:
	db TX_START_ASM
;> if event(EVENT_GOT_HM03):
	ld a, [wEventFlags + $110]
	bit (EVENT_GOT_HM03) % 8, a
	jr nz, .got_item
;>@e1     PrintText(SafariZoneSecretHouseFishingGuruText.HM03ExplanationText)
;>@e2     return TextScriptEnd()
;> PrintText(SafariZoneSecretHouseFishingGuruText.YouHaveWonText)
	ld hl, .YouHaveWonText
	call PrintText
;> if GiveItem(HM_SURF, 1):
	ld bc, ((HM_SURF) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>     PrintText(SafariZoneSecretHouseFishingGuruText.ReceivedHM03Text)
	ld hl, .ReceivedHM03Text
	call PrintText
;>     set_event(EVENT_GOT_HM03)
	ld hl, wEventFlags + $110
	set (EVENT_GOT_HM03) % 8, [hl]
	jr .done
.bag_full
;> else:
;>     PrintText(SafariZoneSecretHouseFishingGuruText.HM03NoRoomText)
	ld hl, .HM03NoRoomText
	call PrintText
	jr .done
.got_item
;=@e1
	ld hl, .HM03ExplanationText
	call PrintText
;=@e2
.done
;> return TextScriptEnd()
	jp TextScriptEnd

