SECTION "Maps 9", ROMX

TradeCenter_h::
	db CLUB
	db $4, $5
	dw TradeCenter_Blocks
	dw TradeCenter_TextPointers
	dw TradeCenter_Script
	db 0
	dw TradeCenter_Object
;@ path: scripts/TradeCenter
;@ def TradeCenter_Script()
;@ The link Trade Center: the partner's sprite faces the player across the table (left or right, depending
;@ on which Game Boy drives the link clock); on first entering, place it on its side of the table.
;@ test: hLoadedROMBank = 0x13    # the bank this code runs in
TradeCenter_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> master = hSerialConnectionStatus == USING_INTERNAL_CLOCK
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
;> hSpriteFacingDirection = SPRITE_FACING_LEFT if master else SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_LEFT
	jr z, .next
	ld a, SPRITE_FACING_RIGHT
.next
	ldh [hSpriteFacingDirection], a
;> hSpriteIndex = TRADECENTER_OPPONENT
	ld a, TRADECENTER_OPPONENT
	ldh [hSpriteIndex], a
;> SetSpriteFacingDirection()
	call SetSpriteFacingDirection
;> done = wStatusFlags3 >> BIT_INIT_TRADE_CENTER_FACING & 1
	ld hl, wStatusFlags3
	bit BIT_INIT_TRADE_CENTER_FACING, [hl]
;> wStatusFlags3 |= 1 << BIT_INIT_TRADE_CENTER_FACING
	set BIT_INIT_TRADE_CENTER_FACING, [hl]
;> if done:
;>     return
	ret nz
;> mem[wSprite01StateData2MapY] = 8
	ld hl, wSprite01StateData2MapY
	ld a, 8 ; y
;> mem[wSprite01StateData2MapY + 1] = 10        # map x
	ld [hli], a
	ld a, 10 ; x
	ld [hl], a
;> mem[wSprite01StateData1FacingDirection] = SPRITE_FACING_LEFT
	ld a, SPRITE_FACING_LEFT
	ld [wSprite01StateData1FacingDirection], a
;> if master:
;>     return
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
	ret z
;> mem[wSprite01StateData2MapX] = 7
	ld a, 7 ; x
	ld [wSprite01StateData2MapX], a
;> mem[wSprite01StateData1FacingDirection] = SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_RIGHT
	ld [wSprite01StateData1FacingDirection], a
	ret

