;@ path: scripts/Route20
;@ def Route20_Script()
;@ Route 20's map script: coming out of the Seafoam Islands resets their boulder puzzles that are not
;@ finished; then run the current step of the route's script (its trainers).
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route20_Script:
;> was = event(EVENT_IN_SEAFOAM_ISLANDS)
	ld hl, wEventFlags + $A0
	bit (EVENT_IN_SEAFOAM_ISLANDS) % 8, [hl]
;> reset_event(EVENT_IN_SEAFOAM_ISLANDS)
	res (EVENT_IN_SEAFOAM_ISLANDS) % 8, [hl]
;> if was:
;>     Route20BoulderScript()
	call nz, Route20BoulderScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute20CurScript = ExecuteCurMapScriptInTable(wRoute20CurScript, Route20TrainerHeaders, Route20_ScriptPointers)
	ld hl, Route20TrainerHeaders
	ld de, Route20_ScriptPointers
	ld a, [wRoute20CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute20CurScript], a
	ret

;@ path: scripts/Route20
;@ def Route20BoulderScript()
;@ Reset unfinished Seafoam boulder puzzles: unless both boulders went down the holes of a floor, they are
;@ put back on the floor above and taken away from the floors below.
;@ test: skip the list of boulders sits under a local label, which the pseudo-code can only name
Route20BoulderScript:
;> if not (event(EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) and event(EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE)):
	ld a, [wEventFlags + ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) / 8)]
	and (1 << ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE) % 8))
	cp (1 << ((EVENT_SEAFOAM3_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM3_BOULDER2_DOWN_HOLE) % 8))
	jr z, .next_boulder_check
;>     Route20ShowObjectScript(TOGGLE_SEAFOAM_ISLANDS_1F_BOULDER_1)
	ld a, TOGGLE_SEAFOAM_ISLANDS_1F_BOULDER_1
	call Route20ShowObjectScript
;>     Route20ShowObjectScript(TOGGLE_SEAFOAM_ISLANDS_1F_BOULDER_2)
	ld a, TOGGLE_SEAFOAM_ISLANDS_1F_BOULDER_2
	call Route20ShowObjectScript
;>     p = Route20BoulderScript.ToggleableObjectIDs  # the boulders on B1F to B3F
	ld hl, .ToggleableObjectIDs
;>     while mem[p] != 0xFF:
.hide_toggleable_objects
	ld a, [hli]
	cp $ff
	jr z, .next_boulder_check
;>         Route20HideObjectScript(mem[p])
	push hl
	call Route20HideObjectScript
;>         p += 1
	pop hl
	jr .hide_toggleable_objects

.ToggleableObjectIDs:
	db TOGGLE_SEAFOAM_ISLANDS_B1F_BOULDER_1
	db TOGGLE_SEAFOAM_ISLANDS_B1F_BOULDER_2
	db TOGGLE_SEAFOAM_ISLANDS_B2F_BOULDER_1
	db TOGGLE_SEAFOAM_ISLANDS_B2F_BOULDER_2
	db TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_3
	db TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_4
	db -1 ; end

.next_boulder_check
;> if event(EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) and event(EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE):
;>     return
	ld a, [wEventFlags + ((EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) / 8)]
	and (1 << ((EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE) % 8))
	cp (1 << ((EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE) % 8))
	ret z
;> Route20ShowObjectScript(TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_1)
	ld a, TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_1
	call Route20ShowObjectScript
;> Route20ShowObjectScript(TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_2)
	ld a, TOGGLE_SEAFOAM_ISLANDS_B3F_BOULDER_2
	call Route20ShowObjectScript
;> Route20HideObjectScript(TOGGLE_SEAFOAM_ISLANDS_B4F_BOULDER_1)
	ld a, TOGGLE_SEAFOAM_ISLANDS_B4F_BOULDER_1
	call Route20HideObjectScript
;> Route20HideObjectScript(TOGGLE_SEAFOAM_ISLANDS_B4F_BOULDER_2)
	ld a, TOGGLE_SEAFOAM_ISLANDS_B4F_BOULDER_2
	call Route20HideObjectScript
	ret

;@ path: scripts/Route20
;@ def Route20ShowObjectScript(obj: a)
;@ Show toggleable object `obj`.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route20ShowObjectScript:
;> wToggleableObjectIndex = obj
;> return predef(ShowObject)
	ld [wToggleableObjectIndex], a
	ld a, (ShowObjectPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/Route20
;@ def Route20HideObjectScript(obj: a)
;@ Hide toggleable object `obj`.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route20HideObjectScript:
;> wToggleableObjectIndex = obj
;> return predef(HideObject)
	ld [wToggleableObjectIndex], a
	ld a, (HideObjectPredef - PredefPointers) / 3
	jp Predef

