;@ path: scripts/Route22
;@ def Route22_Script()
;@ Route 22's map script: run the current step (the two rival battles by the gate to the League).
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route22_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wRoute22CurScript, Route22_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld hl, Route22_ScriptPointers
	ld a, [wRoute22CurScript]
	jp CallFunctionInTable

;@ path: scripts/Route22
Route22_ScriptPointers:
	dw Route22DefaultScript
DEF SCRIPT_ROUTE22_DEFAULT EQU 0
	dw Route22Rival1StartBattleScript
DEF SCRIPT_ROUTE22_RIVAL1_START_BATTLE EQU 1
	dw Route22Rival1AfterBattleScript
DEF SCRIPT_ROUTE22_RIVAL1_AFTER_BATTLE EQU 2
	dw Route22Rival1ExitScript
DEF SCRIPT_ROUTE22_RIVAL1_EXIT EQU 3
	dw Route22Rival2StartBattleScript
DEF SCRIPT_ROUTE22_RIVAL2_START_BATTLE EQU 4
	dw Route22Rival2AfterBattleScript
DEF SCRIPT_ROUTE22_RIVAL2_AFTER_BATTLE EQU 5
	dw Route22Rival2ExitScript
DEF SCRIPT_ROUTE22_RIVAL2_EXIT EQU 6
	dw Route22NoopScript
DEF SCRIPT_ROUTE22_NOOP EQU 7

;@ path: scripts/Route22
;@ def Route22SetDefaultScript()
;@ Back to the default step (after a lost rival battle), with the controls given back.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route22SetDefaultScript:
;> wJoyIgnore = 0
;> wRoute22CurScript = SCRIPT_ROUTE22_DEFAULT
	xor a ; SCRIPT_ROUTE22_DEFAULT
	ld [wJoyIgnore], a
	ld [wRoute22CurScript], a
;@ path: scripts/Route22
;@ def Route22NoopScript()
;@ After the second rival battle: nothing more happens.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route22NoopScript:
;> return
	ret

;@ path: scripts/Route22
;@ def Route22GetRivalTrainerNoByStarterScript(table: hl)
;@ Pick the rival's team: find his starter in a table of (starter, trainer number) pairs.
;@ test: s = rand(1, 190); wRivalStarter = s; table = rand_ram(6); mem[table + 4] = s
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route22GetRivalTrainerNoByStarterScript:
;> starter = wRivalStarter
	ld a, [wRivalStarter]
	ld b, a
;> while mem[table] != starter:              # pairs: starter, trainer number
.next_trainer_no
	ld a, [hli]
	cp b
	jr z, .got_trainer_no
;>     table += 2
	inc hl
	jr .next_trainer_no
.got_trainer_no
;> wTrainerNo = mem[table + 1]
	ld a, [hl]
	ld [wTrainerNo], a
	ret

;@ path: scripts/Route22
;@ def Route22MoveRivalRightScript()
;@ The rival (sprite hSpriteIndex) walks right up to the player (one step less when the player stands on
;@ the upper spot), then faces right.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route22MoveRivalRightScript:
;> moves = Route22RivalMovementData
	ld de, Route22RivalMovementData
;> if wSavedCoordIndex != 1:
	ld a, [wSavedCoordIndex]
	cp $1
	jr z, .skip_first_right
;>     moves += 1                          # without the first step right
	inc de
.skip_first_right
;> MoveSprite(moves)
	call MoveSprite
;> hSpriteFacingDirection = SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_RIGHT
	ldh [hSpriteFacingDirection], a
;> return SetSpriteFacingDirectionAndDelay()
	jp SetSpriteFacingDirectionAndDelay

;@ path: scripts/Route22
Route22RivalMovementData:
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db -1 ; end

;@ path: scripts/Route22
;@ def Route22DefaultScript()
;@ While the rival waits on Route 22, walking past him stops the player (controls locked, facing left) and
;@ starts the first or the second rival battle.
;@ test: skip the two spots sit under a local label, which the pseudo-code can only name
Route22DefaultScript:
;> if not event(EVENT_ROUTE22_RIVAL_WANTS_BATTLE):
;>     return
	ld a, [wEventFlags + $A4]
	bit (EVENT_ROUTE22_RIVAL_WANTS_BATTLE) % 8, a
	ret z
;> if not ArePlayerCoordsInArray(Route22DefaultScript.Route22RivalBattleCoords):
;>     return
	ld hl, .Route22RivalBattleCoords
	call ArePlayerCoordsInArray
	ret nc
;> wSavedCoordIndex = wCoordIndex
	ld a, [wCoordIndex]
	ld [wSavedCoordIndex], a
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wPlayerMovingDirection = PLAYER_DIR_LEFT
	ld a, PLAYER_DIR_LEFT
	ld [wPlayerMovingDirection], a
;> if event(EVENT_1ST_ROUTE22_RIVAL_BATTLE):
;>     return Route22FirstRivalBattleScript()
	ld a, [wEventFlags + $A4]
	bit (EVENT_1ST_ROUTE22_RIVAL_BATTLE) % 8, a
	jr nz, Route22FirstRivalBattleScript
;> if event(EVENT_2ND_ROUTE22_RIVAL_BATTLE):
;>     return Route22SecondRivalBattleScript()
	bit (EVENT_2ND_ROUTE22_RIVAL_BATTLE) % 8, a
	jp nz, Route22SecondRivalBattleScript
	ret

.Route22RivalBattleCoords
	db 4, 29
	db 5, 29
	db -1 ; end

;@ path: scripts/Route22
;@ def Route22FirstRivalBattleScript()
;@ The first rival battle: a "!" over the rival, his music, and he walks up to the player.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route22FirstRivalBattleScript:
;> wEmotionBubbleSpriteIndex = ROUTE22_RIVAL1
	ld a, ROUTE22_RIVAL1
	ld [wEmotionBubbleSpriteIndex], a
;> wWhichEmotionBubble = EXCLAMATION_BUBBLE
	xor a ; EXCLAMATION_BUBBLE
	ld [wWhichEmotionBubble], a
;> predef(EmotionBubble)
	ld a, (EmotionBubblePredef - PredefPointers) / 3
	call Predef
;> if wWalkBikeSurfState:
	ld a, [wWalkBikeSurfState]
	and a
	jr z, .walking
;>     wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;>     PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
.walking
;> PlayMusic(MUSIC_MEET_RIVAL, BANK(Music_MeetRival))
	ld c, BANK(Music_MeetRival)
	ld a, MUSIC_MEET_RIVAL
	call PlayMusic
;> hSpriteIndex = ROUTE22_RIVAL1
	ld a, ROUTE22_RIVAL1
	ldh [hSpriteIndex], a
;> Route22MoveRivalRightScript()
	call Route22MoveRivalRightScript
;> wRoute22CurScript = SCRIPT_ROUTE22_RIVAL1_START_BATTLE
	ld a, SCRIPT_ROUTE22_RIVAL1_START_BATTLE
	ld [wRoute22CurScript], a
	ret

;@ path: scripts/Route22
;@ def Route22Rival1StartBattleScript()
;@ When the rival has walked up: he faces the player, speaks, and the battle starts with the team picked by
;@ his starter.
;@ test: skip the starter table sits under a local label, which the pseudo-code can only name
Route22Rival1StartBattleScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> if wSavedCoordIndex == 1:
	ld a, [wSavedCoordIndex]
	cp 1 ; index of second, lower entry in Route22DefaultScript.Route22RivalBattleCoords
	jr nz, .set_rival_facing_right
;>     wPlayerMovingDirection = PLAYER_DIR_DOWN
	ld a, PLAYER_DIR_DOWN
	ld [wPlayerMovingDirection], a
;>     hSpriteFacingDirection = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	jr .set_rival_facing_direction
.set_rival_facing_right
;> else:
;>     hSpriteFacingDirection = SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_RIGHT
.set_rival_facing_direction
	ldh [hSpriteFacingDirection], a
;> hSpriteIndex = ROUTE22_RIVAL1
	ld a, ROUTE22_RIVAL1
	ldh [hSpriteIndex], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> hTextID = TEXT_ROUTE22_RIVAL1
	ld a, TEXT_ROUTE22_RIVAL1
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(Route22Rival1DefeatedText, Route22Rival1VictoryText)
	ld hl, Route22Rival1DefeatedText
	ld de, Route22Rival1VictoryText
	call SaveEndBattleTextPointers
;> wCurOpponent = OPP_RIVAL1
	ld a, OPP_RIVAL1
	ld [wCurOpponent], a
;> Route22GetRivalTrainerNoByStarterScript(Route22Rival1StartBattleScript.StarterTable)   # teams 4, 5, 6
	ld hl, .StarterTable
	call Route22GetRivalTrainerNoByStarterScript
;> wRoute22CurScript = SCRIPT_ROUTE22_RIVAL1_AFTER_BATTLE
	ld a, SCRIPT_ROUTE22_RIVAL1_AFTER_BATTLE
	ld [wRoute22CurScript], a
	ret

.StarterTable:
; starter the rival picked, rival trainer number
	db STARTER2, 4
	db STARTER3, 5
	db STARTER1, 6

;@ path: scripts/Route22
;@ def Route22Rival1AfterBattleScript()
;@ After the first rival battle: lost, start over; won, his parting words and tune, and he walks away.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route22Rival1AfterBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return Route22SetDefaultScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, Route22SetDefaultScript
;> if mem[wSpritePlayerStateData1FacingDirection] == SPRITE_FACING_DOWN:
	ld a, [wSpritePlayerStateData1FacingDirection]
	and a ; cp SPRITE_FACING_DOWN
	jr nz, .not_facing_down
;>     hSpriteFacingDirection = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	jr .set_rival_facing
.not_facing_down
;> else:
;>     hSpriteFacingDirection = SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_RIGHT
.set_rival_facing
	ldh [hSpriteFacingDirection], a
;> hSpriteIndex = ROUTE22_RIVAL1
	ld a, ROUTE22_RIVAL1
	ldh [hSpriteIndex], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> set_event(EVENT_BEAT_ROUTE22_RIVAL_1ST_BATTLE)
	ld hl, wEventFlags + $A4
	set (EVENT_BEAT_ROUTE22_RIVAL_1ST_BATTLE) % 8, [hl]
;> hTextID = TEXT_ROUTE22_RIVAL1
	ld a, TEXT_ROUTE22_RIVAL1
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
