;@ def Route23_Script()
;@ Route 23's map script (the badge checks before Victory Road): on entering, reset Victory Road's boulder
;@ switches; then run the current step of the route's script.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route23_Script:
;> Route23SetVictoryRoadBoulders()
	call Route23SetVictoryRoadBoulders
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> CallFunctionInTable(wRoute23CurScript, Route23_ScriptPointers)
	ld hl, Route23_ScriptPointers
	ld a, [wRoute23CurScript]
	jp CallFunctionInTable

;@ path: scripts/Route23
;@ def Route23SetVictoryRoadBoulders()
;@ On arriving at Route 23: put Victory Road's boulder puzzles back (switches off, the 3F boulder back in
;@ place and not yet fallen to 2F).
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route23SetVictoryRoadBoulders:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if not loaded:
;>     return
	ret z
;> for e in (EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH1, EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH2,
;>           EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH1, EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH2):
	ld hl, wEventFlags + $A7
;>     reset_event(e)
	res (EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH1) % 8, [hl]
	res (EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH2) % 8, [hl]
	ld hl, wEventFlags + $CC
	res (EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH1) % 8, [hl]
	res (EVENT_VICTORY_ROAD_3_BOULDER_ON_SWITCH2) % 8, [hl]
;> wToggleableObjectIndex = TOGGLE_VICTORY_ROAD_3F_BOULDER
	ld a, TOGGLE_VICTORY_ROAD_3F_BOULDER
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_VICTORY_ROAD_2F_BOULDER
	ld a, TOGGLE_VICTORY_ROAD_2F_BOULDER
	ld [wToggleableObjectIndex], a
;> return predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	jp Predef

