DEF SCRIPT_ROUTE23_RESET_TO_DEFAULT EQU 2

;@ path: scripts/Route23
;@ def Route23DefaultScript()
;@ Walking north past a guard's row (Route23GuardsYCoords) whose badge check is not yet passed makes that
;@ guard ask for his badge (badges from Cascade at the top down to Earth at the bottom; the row at y 35 only
;@ counts left of x 14).
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route23DefaultScript:
;> p = Route23GuardsYCoords
	ld hl, Route23GuardsYCoords
;> player_y = wYCoord
	ld a, [wYCoord]
	ld b, a
;> guard = 0
	ld e, $0
;> badge = EVENT_PASSED_CASCADEBADGE_CHECK % 8 + (EVENT_PASSED_EARTHBADGE_CHECK + 1 - EVENT_PASSED_CASCADEBADGE_CHECK)
	ld c, ((EVENT_PASSED_CASCADEBADGE_CHECK) % 8) + ((EVENT_PASSED_EARTHBADGE_CHECK + 1) - (EVENT_PASSED_CASCADEBADGE_CHECK))
;>@loop while True:
.loop
;>     y = mem[p]
;>     p += 1
	ld a, [hli]
;>     if y == 0xFF:
;>         return
	cp -1
	ret z
;>     guard += 1
	inc e
;>     badge -= 1
	dec c
;>     if y == player_y:
;>         break
	cp b
	jr nz, .loop
;> if y == 35 and wXCoord >= 14:
;>     return
	cp 35
	jr nz, .not_past_victory_road
	ld a, [wXCoord]
	cp 14
	ret nc
.not_past_victory_road
;> hSpriteIndex = guard
	ld a, e
	ldh [hSpriteIndex], a
;> wWhichBadge = badge
	ld a, c
	ld [wWhichBadge], a
;> passed = predef(FlagActionPredef, hl=addr(wEventFlags) + EVENT_PASSED_CASCADEBADGE_CHECK // 8, bc=FLAG_TEST << 8 | badge)
	ld b, FLAG_TEST
	ld hl, wEventFlags + $A6
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> if passed:                                     # this check is passed (c)
;>     return
	ld a, c
	and a
	ret nz
;> Route23CopyBadgeTextScript()
	call Route23CopyBadgeTextScript
;> DisplayTextID()                               # the guard's text (hSpriteIndex)
	call DisplayTextID
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
	ret

;@ path: scripts/Route23
Route23GuardsYCoords:
	db 35
	db 56
	db 85
	db 96
	db 105
	db 119
	db 136
	db -1 ; end

;@ path: scripts/Route23
;@ def Route23CopyBadgeTextScript()
;@ Copy the name of badge wWhichBadge (from BadgeTextPointers, up to its '@') into wNameBuffer for the guard's
;@ text.
;@ test: wWhichBadge = rand(0, 7)
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route23CopyBadgeTextScript:
;> p = BadgeTextPointers + 2 * wWhichBadge
	ld hl, BadgeTextPointers
	ld a, [wWhichBadge]
	ld c, a
	ld b, 0
	add hl, bc
	add hl, bc
;> src = mem16[p]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> dst = addr(wNameBuffer)
	ld de, wNameBuffer
;> while True:
.copyTextLoop
;>     ch = mem[src]
	ld a, [hli]
;>     mem[dst] = ch
	ld [de], a
;>     src += 1
;>     dst += 1
	inc de
;>     if ch == 0x50:                            # '@'
;>         return
	cp '@'
	jr nz, .copyTextLoop
	ret

