;@ path: scripts/Route23
;@ def Route23MovePlayerDownScript()
;@ Push the player one step back down by simulated input.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route23MovePlayerDownScript:
;> wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> wSimulatedJoypadStatesEnd = PAD_DOWN
	ld a, PAD_DOWN
	ld [wSimulatedJoypadStatesEnd], a
;> wSpritePlayerStateData1FacingDirection = SPRITE_FACING_DOWN
;> wJoyIgnore = 0
	xor a
	ld [wSpritePlayerStateData1FacingDirection], a
	ld [wJoyIgnore], a
;> return StartSimulatingJoypadStates()
	jp StartSimulatingJoypadStates

;@ path: scripts/Route23
;@ def Route23PlayerMovingScript()
;@ Once the push back is walked, back to the default step.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route23PlayerMovingScript:
;> if wSimulatedJoypadStatesIndex:
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz

;> return Route23ResetToDefaultScript()
