;@ path: scripts/Route23
;@ def Route23Guard1Text() -> hl
;@ The guard checking for the Earth Badge.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route23Guard1Text:
	db TX_START_ASM
;> Route23CheckForBadgeScript(EVENT_PASSED_CASCADEBADGE_CHECK % 8 + EVENT_PASSED_EARTHBADGE_CHECK - EVENT_PASSED_CASCADEBADGE_CHECK)
;> return TextScriptEnd()
	ld a, ((EVENT_PASSED_CASCADEBADGE_CHECK) % 8) + ((EVENT_PASSED_EARTHBADGE_CHECK) - (EVENT_PASSED_CASCADEBADGE_CHECK))
	call Route23CheckForBadgeScript
	jp TextScriptEnd

