;@ path: scripts/Route23
;@ def Route23CheckForBadgeScript(badge: a)
;@ A Route 23 guard asks for his badge: without it, a buzzer and the player is pushed back; with it, "Oh!
;@ That is the badge!" and his check is noted as passed.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route23CheckForBadgeScript:
;> wWhichBadge = badge
	ld [wWhichBadge], a
;> Route23CopyBadgeTextScript()
	call Route23CopyBadgeTextScript
;> bit = wWhichBadge + 1
	ld a, [wWhichBadge]
	inc a
	ld c, a
;> have = predef(FlagActionPredef, hl=addr(wObtainedBadges), bc=FLAG_TEST << 8 | bit)    # (in c)
	ld b, FLAG_TEST
	ld hl, wObtainedBadges
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> if not have:
	ld a, c
	and a
	jr nz, .have_badge
;>     PrintText(Route23YouDontHaveTheBadgeYetText)
	ld hl, Route23YouDontHaveTheBadgeYetText
	call PrintText
;>     Route23MovePlayerDownScript()
	call Route23MovePlayerDownScript
;>     wRoute23CurScript = SCRIPT_ROUTE23_PLAYER_MOVING
	ld a, SCRIPT_ROUTE23_PLAYER_MOVING
	ld [wRoute23CurScript], a
;>     return
	ret
.have_badge
;> PrintText(Route23OhThatIsTheBadgeText)
	ld hl, Route23OhThatIsTheBadgeText
	call PrintText
;> predef(FlagActionPredef, hl=addr(wEventFlags) + EVENT_PASSED_CASCADEBADGE_CHECK // 8, bc=FLAG_SET << 8 | wWhichBadge)
	ld a, [wWhichBadge]
	ld c, a
	ld b, FLAG_SET
	ld hl, wEventFlags + $A6
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> wRoute23CurScript = SCRIPT_ROUTE23_RESET_TO_DEFAULT
	ld a, SCRIPT_ROUTE23_RESET_TO_DEFAULT
	ld [wRoute23CurScript], a
	ret

