;@ path: scripts/Route24
;@ def Route24_Script()
;@ Route 24's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route24_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute24CurScript = ExecuteCurMapScriptInTable(wRoute24CurScript, Route24TrainerHeaders, Route24_ScriptPointers)
	ld hl, Route24TrainerHeaders
	ld de, Route24_ScriptPointers
	ld a, [wRoute24CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute24CurScript], a
	ret

;@ path: scripts/Route24
;@ def Route24SetDefaultScript()
;@ Back to the default step (after a lost battle), with the controls given back.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route24SetDefaultScript:
;> wJoyIgnore = 0
	xor a ; SCRIPT_ROUTE24_DEFAULT
	ld [wJoyIgnore], a
;> wRoute24CurScript = SCRIPT_ROUTE24_DEFAULT
	ld [wRoute24CurScript], a
;> wCurMapScript = SCRIPT_ROUTE24_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/Route24
Route24_ScriptPointers:
	dw Route24DefaultScript
DEF SCRIPT_ROUTE24_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROUTE24_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROUTE24_END_BATTLE EQU 2
	dw Route24AfterRocketBattleScript
DEF SCRIPT_ROUTE24_AFTER_ROCKET_BATTLE EQU 3
	dw Route24PlayerMovingScript
DEF SCRIPT_ROUTE24_PLAYER_MOVING EQU 4

;@ path: scripts/Route24
;@ def Route24DefaultScript()
;@ Until the player has the Nugget, crossing the end of Nugget Bridge makes the Rocket there speak (and if
;@ the bag was too full for the Nugget, push the player back); otherwise the trainers watch for the player.
;@ test: skip the bridge's end spot sits under a local label, which the pseudo-code can only name
Route24DefaultScript:
;> if event(EVENT_GOT_NUGGET) or not ArePlayerCoordsInArray(Route24DefaultScript.PlayerCoordsArray):
;>     return CheckFightingMapTrainers()
	ld a, [wEventFlags + $A8]
	bit (EVENT_GOT_NUGGET) % 8, a
	jp nz, CheckFightingMapTrainers
	ld hl, .PlayerCoordsArray
	call ArePlayerCoordsInArray
	jp nc, CheckFightingMapTrainers
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hTextID = TEXT_ROUTE24_COOLTRAINER_M1
	ld a, TEXT_ROUTE24_COOLTRAINER_M1
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> available = event(EVENT_NUGGET_REWARD_AVAILABLE)
	ld hl, wEventFlags + $A9
	bit (EVENT_NUGGET_REWARD_AVAILABLE) % 8, [hl]
;> reset_event(EVENT_NUGGET_REWARD_AVAILABLE)
	res (EVENT_NUGGET_REWARD_AVAILABLE) % 8, [hl]
;> if not available:
;>     return
	ret z
;> wSimulatedJoypadStatesEnd = PAD_DOWN
	ld a, PAD_DOWN
	ld [wSimulatedJoypadStatesEnd], a
;> wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wRoute24CurScript = SCRIPT_ROUTE24_PLAYER_MOVING
	ld a, SCRIPT_ROUTE24_PLAYER_MOVING
	ld [wRoute24CurScript], a
;> wCurMapScript = SCRIPT_ROUTE24_PLAYER_MOVING
	ld [wCurMapScript], a
	ret

.PlayerCoordsArray:
	db 15, 10
	db -1 ; end

;@ path: scripts/Route24
;@ def Route24PlayerMovingScript()
;@ Once the push back is walked, back to the default step.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route24PlayerMovingScript:
;> if wSimulatedJoypadStatesIndex:       # still walking
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> Delay3()
	call Delay3
;> wRoute24CurScript = SCRIPT_ROUTE24_DEFAULT
;> wCurMapScript = SCRIPT_ROUTE24_DEFAULT
	ld a, SCRIPT_ROUTE24_DEFAULT
	ld [wRoute24CurScript], a
	ld [wCurMapScript], a
	ret

;@ path: scripts/Route24
;@ def Route24AfterRocketBattleScript()
;@ After the battle with the Rocket on the bridge: lost, start over; won, his last words.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route24AfterRocketBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return Route24SetDefaultScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, Route24SetDefaultScript
;> UpdateSprites()
	call UpdateSprites
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> set_event(EVENT_BEAT_ROUTE24_ROCKET)
	ld hl, wEventFlags + $A8
	set (EVENT_BEAT_ROUTE24_ROCKET) % 8, [hl]
;> hTextID = TEXT_ROUTE24_COOLTRAINER_M1
	ld a, TEXT_ROUTE24_COOLTRAINER_M1
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wRoute24CurScript = SCRIPT_ROUTE24_DEFAULT
	ld a, SCRIPT_ROUTE24_DEFAULT
	ld [wRoute24CurScript], a
;> wCurMapScript = SCRIPT_ROUTE24_DEFAULT
	ld [wCurMapScript], a
	ret

