;@ path: scripts/Route24
;@ def Route24CooltrainerM1Text() -> hl
;@ The man at the end of Nugget Bridge: hands out the Nugget for beating the five trainers, then reveals he
;@ is from Team Rocket and battles; with a full bag he keeps the Nugget for later. Afterwards he says the
;@ player could become a top leader.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route24CooltrainerM1Text:
	db TX_START_ASM
;> reset_event(EVENT_NUGGET_REWARD_AVAILABLE)
	ld hl, wEventFlags + $A9
	res (EVENT_NUGGET_REWARD_AVAILABLE) % 8, [hl]
;> if event(EVENT_GOT_NUGGET):
	ld a, [wEventFlags + $A8]
	bit (EVENT_GOT_NUGGET) % 8, a
	jr nz, .got_item
;>@e1     PrintText(Route24CooltrainerM1Text.YouCouldBecomeATopLeaderText)
;>@e2     return TextScriptEnd()
;> PrintText(Route24CooltrainerM1Text.YouBeatOurContestText)
	ld hl, .YouBeatOurContestText
	call PrintText
;> if not GiveItem(NUGGET, 1):
	ld bc, ((NUGGET) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>@e3     PrintText(Route24CooltrainerM1Text.NoRoomText)
;>@e4     set_event(EVENT_NUGGET_REWARD_AVAILABLE)
;>@e5     return TextScriptEnd()
;> set_event(EVENT_GOT_NUGGET)
	ld hl, wEventFlags + $A8
	set (EVENT_GOT_NUGGET) % 8, [hl]
;> PrintText(Route24CooltrainerM1Text.ReceivedNuggetText)
	ld hl, .ReceivedNuggetText
	call PrintText
;> PrintText(Route24CooltrainerM1Text.JoinTeamRocketText)
	ld hl, .JoinTeamRocketText
	call PrintText
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(Route24CooltrainerM1Text.DefeatedText, Route24CooltrainerM1Text.DefeatedText)
	ld hl, .DefeatedText
	ld de, .DefeatedText
	call SaveEndBattleTextPointers
;> wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;> EngageMapTrainer()
	call EngageMapTrainer
;> InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wRoute24CurScript = SCRIPT_ROUTE24_AFTER_ROCKET_BATTLE
	ld a, SCRIPT_ROUTE24_AFTER_ROCKET_BATTLE
	ld [wRoute24CurScript], a
;> wCurMapScript = SCRIPT_ROUTE24_AFTER_ROCKET_BATTLE
	ld [wCurMapScript], a
;> return TextScriptEnd()
	jp TextScriptEnd
.got_item
;=@e1
	ld hl, .YouCouldBecomeATopLeaderText
	call PrintText
;=@e2
	jp TextScriptEnd
.bag_full
;=@e3
	ld hl, .NoRoomText
	call PrintText
;=@e4
	ld hl, wEventFlags + $A9
	set (EVENT_NUGGET_REWARD_AVAILABLE) % 8, [hl]
;=@e5
	jp TextScriptEnd

.YouBeatOurContestText:
	db TX_FAR
