;@ path: scripts/Route25
;@ def Route25_Script()
;@ Route 25's map script: first the map callback (Route25ToggleBillsScript), then run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route25_Script:
;> Route25ToggleBillsScript()
	call Route25ToggleBillsScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute25CurScript = ExecuteCurMapScriptInTable(wRoute25CurScript, Route25TrainerHeaders, Route25_ScriptPointers)
	ld hl, Route25TrainerHeaders
	ld de, Route25_ScriptPointers
	ld a, [wRoute25CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute25CurScript], a
	ret

;@ path: scripts/Route25
;@ def Route25ToggleBillsScript()
;@ On arriving at Route 25: before the player has met Bill, Bill is the Pokémon in his house; once he has
;@ helped Bill and has the S.S. Ticket, the bridge's Rocket leaves and Bill is shown in his human form.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Route25ToggleBillsScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if not loaded or event(EVENT_LEFT_BILLS_HOUSE_AFTER_HELPING):
;>     return
	ret z
	ld hl, wEventFlags + $AB
	bit (EVENT_LEFT_BILLS_HOUSE_AFTER_HELPING) % 8, [hl]
	ret nz
;> if not event(EVENT_MET_BILL_2):
	bit (EVENT_MET_BILL_2) % 8, [hl]
	jr nz, .met_bill
;>     reset_event(EVENT_BILL_SAID_USE_CELL_SEPARATOR)
	res (EVENT_BILL_SAID_USE_CELL_SEPARATOR) % 8, [hl]
;>     wToggleableObjectIndex = TOGGLE_BILL_POKEMON
	ld a, TOGGLE_BILL_POKEMON
	ld [wToggleableObjectIndex], a
;>     return predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	jp Predef
.met_bill
;> if not event(EVENT_GOT_SS_TICKET):
;>     return
	bit (EVENT_GOT_SS_TICKET) % 8, [hl]
	ret z
;> set_event(EVENT_LEFT_BILLS_HOUSE_AFTER_HELPING)
	set (EVENT_LEFT_BILLS_HOUSE_AFTER_HELPING) % 8, [hl]
;> wToggleableObjectIndex = TOGGLE_NUGGET_BRIDGE_GUY
	ld a, TOGGLE_NUGGET_BRIDGE_GUY
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_BILL_1
	ld a, TOGGLE_BILL_1
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_BILL_2
	ld a, TOGGLE_BILL_2
	ld [wToggleableObjectIndex], a
;> return predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	jp Predef

