VictoryRoad2F_h::
	db CAVERN
	db $9, $F
	dw VictoryRoad2F_Blocks
	dw VictoryRoad2F_TextPointers
	dw VictoryRoad2F_Script
	db 0
	dw VictoryRoad2F_Object
;@ path: scripts/VictoryRoad2F
;@ def VictoryRoad2F_Script()
;@ Victory Road 2F's map script: on arriving from outside, the 1F switch is reset; on entering, the passages
;@ opened by boulders on this floor's switches are redrawn; then run the current step (the trainers, Moltres).
;@ test: hLoadedROMBank = 0x14; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
VictoryRoad2F_Script:
;> flags = wCurrentMapScriptFlags
	ld hl, wCurrentMapScriptFlags
;> wCurrentMapScriptFlags = flags & ~(1 << BIT_CUR_MAP_LOADED_2)
;> if flags >> BIT_CUR_MAP_LOADED_2 & 1:
	bit BIT_CUR_MAP_LOADED_2, [hl]
	res BIT_CUR_MAP_LOADED_2, [hl]
;>     VictoryRoad2FResetBoulderEventScript()
	call nz, VictoryRoad2FResetBoulderEventScript
;> flags = wCurrentMapScriptFlags
	ld hl, wCurrentMapScriptFlags
;> wCurrentMapScriptFlags = flags & ~(1 << BIT_CUR_MAP_LOADED_1)
;> if flags >> BIT_CUR_MAP_LOADED_1 & 1:
	bit BIT_CUR_MAP_LOADED_1, [hl]
	res BIT_CUR_MAP_LOADED_1, [hl]
;>     VictoryRoad2FCheckBoulderEventScript()
	call nz, VictoryRoad2FCheckBoulderEventScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wVictoryRoad2FCurScript = ExecuteCurMapScriptInTable(wVictoryRoad2FCurScript, VictoryRoad2TrainerHeaders, VictoryRoad2F_ScriptPointers)
	ld hl, VictoryRoad2TrainerHeaders
	ld de, VictoryRoad2F_ScriptPointers
	ld a, [wVictoryRoad2FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wVictoryRoad2FCurScript], a
	ret

;@ path: scripts/VictoryRoad2F
;@ def VictoryRoad2FResetBoulderEventScript()
;@ Arriving on 2F from the floor below: the 1F switch counts as released again; then redraw this floor's
;@ opened passages.
;@ test: hLoadedROMBank = 0x14; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
VictoryRoad2FResetBoulderEventScript:
;> reset_event(EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH)
;> return VictoryRoad2FCheckBoulderEventScript()
	ld hl, wEventFlags + $122
	res (EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH) % 8, [hl]
; fallthrough
;@ path: scripts/VictoryRoad2F
;@ def VictoryRoad2FCheckBoulderEventScript()
;@ Draw the passages opened by a boulder on each of 2F's two switches (blocks $15 and $1D).
;@ test: hLoadedROMBank = 0x14; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
VictoryRoad2FCheckBoulderEventScript:
;> if event(EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH1):
	ld a, [wEventFlags + $A7]
	bit (EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH1) % 8, a
	jr z, .not_on_switch
;>     VictoryRoad2FReplaceTileBlockScript(0x15, 4, 3)
	push af
	ld a, $15
	ld bc, ((4) & $ff) << 8 + ((3) & $ff)
	call VictoryRoad2FReplaceTileBlockScript
	pop af
.not_on_switch
;> if not event(EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH2):
;>     return
	bit (EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH2) % 8, a
	ret z
;> return VictoryRoad2FReplaceTileBlockScript(0x1D, 7, 11)   # (it follows right below)
	ld a, $1d
	ld bc, ((7) & $ff) << 8 + ((11) & $ff)
;@ path: scripts/VictoryRoad2F
;@ def VictoryRoad2FReplaceTileBlockScript(block: a, y: b, x: c)
;@ Put `block` at block (x, y) of the map.
;@ test: hLoadedROMBank = 0x14; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20); y = rand(0, 8); x = rand(0, 8)    # the bank this code runs in; no map redraw, blocks on the map
VictoryRoad2FReplaceTileBlockScript:
;> wNewTileBlockID = block
;> predef(ReplaceTileBlock, bc=y << 8 | x)
	ld [wNewTileBlockID], a
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	ret

;@ path: scripts/VictoryRoad2F
VictoryRoad2F_ScriptPointers:
	dw VictoryRoad2FDefaultScript
DEF SCRIPT_VICTORYROAD2F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_VICTORYROAD2F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_VICTORYROAD2F_END_BATTLE EQU 2

;@ path: scripts/VictoryRoad2F
;@ def VictoryRoad2FDefaultScript()
;@ A boulder pushed onto one of 2F's switches (first time) opens its passage the next time the map script
;@ runs; otherwise the trainers watch for the player.
;@ test: skip the switch spots sit under a local label, which the pseudo-code can only name
VictoryRoad2FDefaultScript:
;> if not CheckBoulderCoords(VictoryRoad2FDefaultScript.SwitchCoords):
;>     return CheckFightingMapTrainers()
	ld hl, .SwitchCoords
	call CheckBoulderCoords
	jp nc, CheckFightingMapTrainers
;> switch = EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH2 if wCoordIndex == 2 else EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH1
	ld hl, wEventFlags + $A7
	ld a, [wCoordIndex]
	cp $2
	jr z, .second_switch
;> was_on = event(switch)
	bit (EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH1) % 8, [hl]
;> set_event(switch)
	set (EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH1) % 8, [hl]
;> if not was_on:
	ret nz
	jr .set_script_flag
.second_switch
	bit (EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH2) % 8, [hl]
	set (EVENT_VICTORY_ROAD_2_BOULDER_ON_SWITCH2) % 8, [hl]
	ret nz
.set_script_flag
;>     wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
	ret

.SwitchCoords:
	db 16, 1
	db 16, 9
	db -1 ; end

