SilphCo7F_h::
	db FACILITY
	db $9, $D
	dw SilphCo7F_Blocks
	dw SilphCo7F_TextPointers
	dw SilphCo7F_Script
	db 0
	dw SilphCo7F_Object
;@ path: scripts/SilphCo7F
;@ def SilphCo7F_Script()
;@ Silph Co. 7F's map script: on entering, redraw the card-key doors; then run the current step of the
;@ floor's script (its trainers, the rival).
;@ test: skip runs the floor's door callback, whose door list sits under a local label
SilphCo7F_Script:
;> SilphCo7F_GateCallbackScript()
	call SilphCo7F_GateCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSilphCo7FCurScript = ExecuteCurMapScriptInTable(wSilphCo7FCurScript, SilphCo7TrainerHeaders, SilphCo7F_ScriptPointers)
	ld hl, SilphCo7TrainerHeaders
	ld de, SilphCo7F_ScriptPointers
	ld a, [wSilphCo7FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSilphCo7FCurScript], a
	ret

;@ path: scripts/SilphCo7F
;@ def SilphCo7F_GateCallbackScript()
;@ On entering the floor: if a card-key door here was just opened, note it, then draw each of the three doors
;@ still locked (block $54) into the map.
;@ test: skip the door list sits under a local label, which the pseudo-code can only name
SilphCo7F_GateCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> SilphCo7F_SetCardKeyDoorYScript(SilphCo7F_GateCallbackScript.GateCoordinates)
	ld hl, .GateCoordinates
	call SilphCo7F_SetCardKeyDoorYScript
;> SilphCo7F_UnlockedDoorEventScript()
	call SilphCo7F_UnlockedDoorEventScript
;> if not event(EVENT_SILPH_CO_7_UNLOCKED_DOOR1):     # door 1 still locked
	ld a, [wEventFlags + $E9]
	bit (EVENT_SILPH_CO_7_UNLOCKED_DOOR1) % 8, a
	jr nz, .unlock_door1
;>     wNewTileBlockID = 0x54
	push af
	ld a, $54
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=3 << 8 | 5)        # at row 3, column 5
	ld bc, ((3) & $ff) << 8 + ((5) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	pop af
.unlock_door1
;> if not event(EVENT_SILPH_CO_7_UNLOCKED_DOOR2):
	bit (EVENT_SILPH_CO_7_UNLOCKED_DOOR2) % 8, a
	jr nz, .unlock_door2
;>     wNewTileBlockID = 0x54
	push af
	ld a, $54
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=2 << 8 | 10)
	ld bc, ((2) & $ff) << 8 + ((10) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	pop af
.unlock_door2
;> if event(EVENT_SILPH_CO_7_UNLOCKED_DOOR3):
;>     return
	bit (EVENT_SILPH_CO_7_UNLOCKED_DOOR3) % 8, a
	ret nz
;> wNewTileBlockID = 0x54
	ld a, $54
	ld [wNewTileBlockID], a
;> return predef(ReplaceTileBlock, bc=6 << 8 | 10)
	ld bc, ((6) & $ff) << 8 + ((10) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

.GateCoordinates:
	db 3, 5
	db 2, 10
	db 6, 10
	db -1 ; end

;@ path: scripts/SilphCo7F
;@ def SilphCo7F_SetCardKeyDoorYScript(doors: hl)
;@ Look up the door the card key just opened (wCardKeyDoorY/X) in the floor's door list: hUnlockedSilphCoDoors
;@ becomes its number (1, 2...) and the opened door is forgotten; 0 if it is not one of them.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
SilphCo7F_SetCardKeyDoorYScript:
;> y = wCardKeyDoorY
	push hl
	ld hl, wCardKeyDoorY
	ld a, [hli]
	ld b, a
;> x = wCardKeyDoorX
	ld a, [hl]
	ld c, a
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
;> while mem[doors] != 0xFF:
	pop hl
.loop_check_doors
	ld a, [hli]
	cp $ff
	jr z, .exit_loop
;>     hUnlockedSilphCoDoors += 1
	push hl
	ld hl, hUnlockedSilphCoDoors
	inc [hl]
	pop hl
;>@match     if mem[doors] == y and mem[doors + 1] == x:
	cp b
	jr z, .check_y_coord
;>@clear         wCardKeyDoorY = wCardKeyDoorX = 0
;>@ret         return
;>     doors += 2
	inc hl
	jr .loop_check_doors
.check_y_coord
;=@match
	ld a, [hli]
	cp c
	jr nz, .loop_check_doors
;=@clear
	ld hl, wCardKeyDoorY
	xor a
	ld [hli], a
	ld [hl], a
;=@ret
	ret
.exit_loop
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
	ret

;@ path: scripts/SilphCo7F
;@ def SilphCo7F_UnlockedDoorEventScript()
;@ Note the door the card key just opened (door 1, 2 or 3 of this floor) as an event.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
SilphCo7F_UnlockedDoorEventScript:
;> if hUnlockedSilphCoDoors == 1:
	ld hl, wEventFlags + $E9
	ldh a, [hUnlockedSilphCoDoors]
	and a
	ret z
	cp $1
	jr nz, .unlock_door1
;>     set_event(EVENT_SILPH_CO_7_UNLOCKED_DOOR1)
	set (EVENT_SILPH_CO_7_UNLOCKED_DOOR1) % 8, [hl]
	ret
.unlock_door1
;> elif hUnlockedSilphCoDoors == 2:
	cp $2
	jr nz, .unlock_door2
;>     set_event(EVENT_SILPH_CO_7_UNLOCKED_DOOR2)
	set (EVENT_SILPH_CO_7_UNLOCKED_DOOR2) % 8, [hl]
	ret
.unlock_door2
;> elif hUnlockedSilphCoDoors:
;>     set_event(EVENT_SILPH_CO_7_UNLOCKED_DOOR3)
	set (EVENT_SILPH_CO_7_UNLOCKED_DOOR3) % 8, [hl]
	ret

;@ path: scripts/SilphCo7F
;@ def SilphCo7FSetDefaultScript()
;@ Back to the floor's default step, with the controls given back.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
SilphCo7FSetDefaultScript:
;> wJoyIgnore = 0
;> return SilphCo7FSetCurScript(SCRIPT_SILPHCO7F_DEFAULT)
	xor a
	ld [wJoyIgnore], a

;@ path: scripts/SilphCo7F
;@ def SilphCo7FSetCurScript(script: a)
;@ Make `script` the floor's current step.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
SilphCo7FSetCurScript:
;> wSilphCo7FCurScript = script
;> wCurMapScript = script
	ld [wSilphCo7FCurScript], a
	ld [wCurMapScript], a
	ret

;@ path: scripts/SilphCo7F
SilphCo7F_ScriptPointers:
	dw SilphCo7FDefaultScript
DEF SCRIPT_SILPHCO7F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_SILPHCO7F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_SILPHCO7F_END_BATTLE EQU 2
	dw SilphCo7FRivalStartBattleScript
DEF SCRIPT_SILPHCO7F_RIVAL_START_BATTLE EQU 3
	dw SilphCo7FRivalAfterBattleScript
DEF SCRIPT_SILPHCO7F_RIVAL_AFTER_BATTLE EQU 4
	dw SilphCo7FRivalExitScript
DEF SCRIPT_SILPHCO7F_RIVAL_EXIT EQU 5

;@ path: scripts/SilphCo7F
;@ def SilphCo7FDefaultScript()
;@ Until the rival here is beaten, stepping next to him starts his scene: his music, his greeting, and he walks
;@ up to the player (one step less from the upper spot); otherwise the trainers watch for the player.
;@ test: skip the spots and the walk sit under local labels, which the pseudo-code can only name
SilphCo7FDefaultScript:
;> if event(EVENT_BEAT_SILPH_CO_RIVAL) or not ArePlayerCoordsInArray(SilphCo7FDefaultScript.RivalEncounterCoordinates):
;>     return CheckFightingMapTrainers()
	ld a, [wEventFlags + $E8]
	bit (EVENT_BEAT_SILPH_CO_RIVAL) % 8, a
	jp nz, CheckFightingMapTrainers
	ld hl, .RivalEncounterCoordinates
	call ArePlayerCoordsInArray
	jp nc, CheckFightingMapTrainers
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wPlayerMovingDirection = PLAYER_DIR_DOWN
	ld a, PLAYER_DIR_DOWN
	ld [wPlayerMovingDirection], a
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> PlayMusic(MUSIC_MEET_RIVAL, BANK(Music_MeetRival))
	ld c, BANK(Music_MeetRival)
	ld a, MUSIC_MEET_RIVAL
	call PlayMusic
;> hTextID = TEXT_SILPHCO7F_RIVAL
	ld a, TEXT_SILPHCO7F_RIVAL
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hSpriteIndex = SILPHCO7F_RIVAL
	ld a, SILPHCO7F_RIVAL
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> wSavedCoordIndex = wCoordIndex
;> moves = SilphCo7FDefaultScript.RivalMovementUp
	ld de, .RivalMovementUp
	ld a, [wCoordIndex]
	ld [wSavedCoordIndex], a
;> if wCoordIndex != 1:
	cp 1 ; index of second, lower entry in .RivalEncounterCoordinates
	jr z, .full_rival_movement
;>     moves += 1
	inc de
.full_rival_movement
;> hSpriteIndex = SILPHCO7F_RIVAL
	ld a, SILPHCO7F_RIVAL
	ldh [hSpriteIndex], a
;> MoveSprite(moves)
	call MoveSprite
;> return SilphCo7FSetCurScript(SCRIPT_SILPHCO7F_RIVAL_START_BATTLE)
	ld a, SCRIPT_SILPHCO7F_RIVAL_START_BATTLE
	jp SilphCo7FSetCurScript

.RivalEncounterCoordinates:
	db 2, 3
	db 3, 3
	db -1 ; end

.RivalMovementUp:
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db -1 ; end

;@ path: scripts/SilphCo7F
;@ def SilphCo7FRivalStartBattleScript()
;@ When the rival has walked up: "I waited here", and the battle starts with the team picked by his starter.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
SilphCo7FRivalStartBattleScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> hTextID = TEXT_SILPHCO7F_RIVAL_WAITED_HERE
	ld a, TEXT_SILPHCO7F_RIVAL_WAITED_HERE
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> Delay3()
	call Delay3
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(SilphCo7FRivalDefeatedText, SilphCo7FRivalVictoryText)
	ld hl, SilphCo7FRivalDefeatedText
	ld de, SilphCo7FRivalVictoryText
	call SaveEndBattleTextPointers
;> wCurOpponent = OPP_RIVAL2
	ld a, OPP_RIVAL2
	ld [wCurOpponent], a
;> if wRivalStarter == STARTER2:
	ld a, [wRivalStarter]
	cp STARTER2
	jr nz, .not_starter_2
;>     wTrainerNo = 7
	ld a, $7
	jr .set_trainer_no
.not_starter_2
;> elif wRivalStarter == STARTER3:
	cp STARTER3
	jr nz, .no_starter_3
;>     wTrainerNo = 8
	ld a, $8
	jr .set_trainer_no
.no_starter_3
;> else:
;>     wTrainerNo = 9
	ld a, $9
.set_trainer_no
	ld [wTrainerNo], a
;> return SilphCo7FSetCurScript(SCRIPT_SILPHCO7F_RIVAL_AFTER_BATTLE)
	ld a, SCRIPT_SILPHCO7F_RIVAL_AFTER_BATTLE
	jp SilphCo7FSetCurScript

;@ path: scripts/SilphCo7F
;@ def SilphCo7FRivalAfterBattleScript()
;@ After the rival battle: lost, start over; won, "good luck to you", his tune, and he leaves (to the right,
;@ or around the player).
;@ test: skip the walks sit under local labels, which the pseudo-code can only name
SilphCo7FRivalAfterBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return SilphCo7FSetDefaultScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, SilphCo7FSetDefaultScript
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> set_event(EVENT_BEAT_SILPH_CO_RIVAL)
	ld hl, wEventFlags + $E8
	set (EVENT_BEAT_SILPH_CO_RIVAL) % 8, [hl]
;> wPlayerMovingDirection = PLAYER_DIR_DOWN
	ld a, PLAYER_DIR_DOWN
	ld [wPlayerMovingDirection], a
;> hSpriteIndex = SILPHCO7F_RIVAL
	ld a, SILPHCO7F_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hTextID = TEXT_SILPHCO7F_RIVAL_GOOD_LUCK_TO_YOU
	ld a, TEXT_SILPHCO7F_RIVAL_GOOD_LUCK_TO_YOU
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> farcall(Music_RivalAlternateStart)
	ld b, BANK(Music_RivalAlternateStart)
	ld hl, Music_RivalAlternateStart
	call Bankswitch
;> if wSavedCoordIndex == 1:
	ld de, .RivalWalkAroundPlayerMovement
	ld a, [wSavedCoordIndex]
	cp 1 ; index of second, lower entry in SilphCo7FDefaultScript.RivalEncounterCoordinates
	jr nz, .walk_around_player
;>     moves = SilphCo7FRivalAfterBattleScript.RivalExitRightMovement
	ld de, .RivalExitRightMovement
.walk_around_player
;> else:
;>     moves = SilphCo7FRivalAfterBattleScript.RivalWalkAroundPlayerMovement
;> hSpriteIndex = SILPHCO7F_RIVAL
	ld a, SILPHCO7F_RIVAL
	ldh [hSpriteIndex], a
;> MoveSprite(moves)
	call MoveSprite
;> return SilphCo7FSetCurScript(SCRIPT_SILPHCO7F_RIVAL_EXIT)
	ld a, SCRIPT_SILPHCO7F_RIVAL_EXIT
	jp SilphCo7FSetCurScript

.RivalExitRightMovement:
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db -1 ; end

.RivalWalkAroundPlayerMovement:
	db NPC_MOVEMENT_LEFT
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_DOWN
	db -1 ; end

;@ path: scripts/SilphCo7F
;@ def SilphCo7FRivalExitScript()
;@ When the rival has walked off: hide him, the map music again, and back to the default step.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
SilphCo7FRivalExitScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> wToggleableObjectIndex = TOGGLE_SILPH_CO_7F_RIVAL
	ld a, TOGGLE_SILPH_CO_7F_RIVAL
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> PlayDefaultMusic()
	call PlayDefaultMusic
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> return SilphCo7FSetCurScript(SCRIPT_SILPHCO7F_DEFAULT)
	jp SilphCo7FSetCurScript

