;@ path: scripts/SilphCo7F
;@ def SilphCo7FSilphWorkerM1Text() -> hl
;@ The Silph worker hiding with a Lapras: gives the player the Lapras (level 15) once; afterwards asks if the
;@ president is OK - or, after Giovanni is beaten, thanks the player.
;@ test: skip a text script: the code after text_asm is run by the text engine
SilphCo7FSilphWorkerM1Text:
; lapras guy
	db TX_START_ASM
;> if wStatusFlags4 >> BIT_GOT_LAPRAS & 1:
	ld a, [wStatusFlags4]
	bit BIT_GOT_LAPRAS, a
	jr z, .give_lapras
;>     if event(EVENT_BEAT_SILPH_CO_GIOVANNI):
	ld a, [wEventFlags + $F1]
	bit (EVENT_BEAT_SILPH_CO_GIOVANNI) % 8, a
	jr nz, .saved_silph
;>@saved         PrintText(SilphCo7FSilphWorkerM1Text.SavedText)
;>     else:
;>         PrintText(SilphCo7FSilphWorkerM1Text.IsOurPresidentOkText)
	ld hl, .IsOurPresidentOkText
	call PrintText
	jr .done
.give_lapras
;> else:
;>     PrintText(SilphCo7FSilphWorkerM1Text.HaveThisPokemonText)
	ld hl, .HaveThisPokemonText
	call PrintText
;>     if GivePokemon(LAPRAS, 15):
	ld bc, ((LAPRAS) & $ff) << 8 + ((15) & $ff)
	call GivePokemon
	jr nc, .done
;>         if not wAddedToParty:                   # sent to the PC: wait for a button first
;>             WaitForTextScrollButtonPress()
	ld a, [wAddedToParty]
	and a
	call z, WaitForTextScrollButtonPress
;>         EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;>         PrintText(SilphCo7FSilphWorkerM1Text.LaprasDescriptionText)
	ld hl, .LaprasDescriptionText
	call PrintText
;>         wStatusFlags4 |= 1 << BIT_GOT_LAPRAS
	ld hl, wStatusFlags4
	set BIT_GOT_LAPRAS, [hl]
	jr .done
.saved_silph
;=@saved
	ld hl, .SavedText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.HaveThisPokemonText
	db TX_FAR
	dw _SilphCo7FSilphWorkerM1HaveThisPokemonText
	db BANK(_SilphCo7FSilphWorkerM1HaveThisPokemonText)
	db TX_END

.LaprasDescriptionText
	db TX_FAR
	dw _SilphCo7FSilphWorkerM1LaprasDescriptionText
	db BANK(_SilphCo7FSilphWorkerM1LaprasDescriptionText)
	db TX_END

.IsOurPresidentOkText
	db TX_FAR
	dw _SilphCo7FSilphWorkerM1IsOurPresidentOkText
	db BANK(_SilphCo7FSilphWorkerM1IsOurPresidentOkText)
	db TX_END

.SavedText
	db TX_FAR
	dw _SilphCo7FSilphWorkerM1SavedText
	db BANK(_SilphCo7FSilphWorkerM1SavedText)
	db TX_END

