PokemonMansion2F_h::
	db FACILITY
	db $E, $F
	dw PokemonMansion2F_Blocks
	dw PokemonMansion2F_TextPointers
	dw PokemonMansion2F_Script
	db 0
	dw PokemonMansion2F_Object
;@ path: scripts/PokemonMansion2F
;@ def PokemonMansion2F_Script()
;@ Pokémon Mansion 2F's map script: first the map callback (Mansion2CheckReplaceSwitchDoorBlocks), then run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
PokemonMansion2F_Script:
;> Mansion2CheckReplaceSwitchDoorBlocks()
	call Mansion2CheckReplaceSwitchDoorBlocks
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wPokemonMansion2FCurScript = ExecuteCurMapScriptInTable(wPokemonMansion2FCurScript, Mansion2TrainerHeaders, PokemonMansion2F_ScriptPointers)
	ld hl, Mansion2TrainerHeaders
	ld de, PokemonMansion2F_ScriptPointers
	ld a, [wPokemonMansion2FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wPokemonMansion2FCurScript], a
	ret

;@ path: scripts/PokemonMansion2F
;@ def Mansion2CheckReplaceSwitchDoorBlocks()
;@ On entering the mansion's 2F: draw the three gates the secret switch controls - open or closed depending
;@ on the switch.
;@ test: hLoadedROMBank = 0x14; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
Mansion2CheckReplaceSwitchDoorBlocks:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> if event(EVENT_MANSION_SWITCH_ON):
;>@on1     Mansion2ReplaceBlock(0x5F, 2, 4)
;>@on2     Mansion2ReplaceBlock(0x0E, 4, 9)
;>@on3     Mansion2ReplaceBlock(0x0E, 11, 3)
	ld a, [wEventFlags + $4F]
	bit (EVENT_MANSION_SWITCH_ON) % 8, a
	jr nz, .switchTurnedOn
;> else:
;>     Mansion2ReplaceBlock(0x0E, 2, 4)
	ld a, $e
	ld bc, ((2) & $ff) << 8 + ((4) & $ff)
	call Mansion2ReplaceBlock
;>     Mansion2ReplaceBlock(0x54, 4, 9)
	ld a, $54
	ld bc, ((4) & $ff) << 8 + ((9) & $ff)
	call Mansion2ReplaceBlock
;>     Mansion2ReplaceBlock(0x5F, 11, 3)
	ld a, $5f
	ld bc, ((11) & $ff) << 8 + ((3) & $ff)
	call Mansion2ReplaceBlock
	ret
.switchTurnedOn
;=@on1
	ld a, $5f
	ld bc, ((2) & $ff) << 8 + ((4) & $ff)
	call Mansion2ReplaceBlock
;=@on2
	ld a, $e
	ld bc, ((4) & $ff) << 8 + ((9) & $ff)
	call Mansion2ReplaceBlock
;=@on3
	ld a, $e
	ld bc, ((11) & $ff) << 8 + ((3) & $ff)
	call Mansion2ReplaceBlock
	ret

;@ path: scripts/PokemonMansion2F
;@ def Mansion2ReplaceBlock(block: a, y: b, x: c)
;@ Put `block` at block (x, y) of the map (used on all the mansion's floors for the switch gates).
;@ test: hLoadedROMBank = 0x14; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20); y = rand(0, 8); x = rand(0, 8)    # the bank this code runs in; no map redraw, blocks on the map
Mansion2ReplaceBlock:
;> wNewTileBlockID = block
;> return predef(ReplaceTileBlock, bc=y << 8 | x)
	ld [wNewTileBlockID], a
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/PokemonMansion2F
;@ def Mansion2Script_Switches()
;@ Checking a statue switch on 2F (facing up at it): ask whether to press it.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Mansion2Script_Switches::
;> if mem[wSpritePlayerStateData1FacingDirection] != SPRITE_FACING_UP:
;>     return
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	ret nz
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hTextID = TEXT_POKEMONMANSION2F_SWITCH
;> return DisplayTextID()
	ld a, TEXT_POKEMONMANSION2F_SWITCH
	ldh [hTextID], a
	jp DisplayTextID

;@ path: scripts/PokemonMansion2F
PokemonMansion2F_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_POKEMONMANSION2F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_POKEMONMANSION2F_START_BATTLE EQU 1
	dw EndTrainerBattle
