;@ path: scripts/PokemonMansion2F
;@ def PokemonMansion2FSwitchText() -> hl
;@ The secret switch on 2F: "Press it?" - on yes, the switch flips (on/off) and the map redraws its gates the
;@ next time the map script runs.
;@ test: skip a text script: the code after text_asm is run by the text engine
PokemonMansion2FSwitchText:
	db TX_START_ASM
;> PrintText(PokemonMansion2FSwitchText.Text)
	ld hl, .Text
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .not_pressed
;>@e1     PrintText(PokemonMansion2FSwitchText.NotPressed)
;>@e2     return TextScriptEnd()
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1     # redraw the gates
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
;> PrintText(PokemonMansion2FSwitchText.PressedText)
	ld hl, .PressedText
	call PrintText
;> PlaySound(SFX_GO_INSIDE)
	ld a, SFX_GO_INSIDE
	call PlaySound
;> if event(EVENT_MANSION_SWITCH_ON):
	ld hl, wEventFlags + $4F
	bit (EVENT_MANSION_SWITCH_ON) % 8, [hl]
	set (EVENT_MANSION_SWITCH_ON) % 8, [hl]
	jr z, .done
;>     reset_event(EVENT_MANSION_SWITCH_ON)
;> else:
;>     set_event(EVENT_MANSION_SWITCH_ON)
	res (EVENT_MANSION_SWITCH_ON) % 8, [hl]
	jr .done
.not_pressed
;=@e1
	ld hl, .NotPressed
	call PrintText
;=@e2
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _PokemonMansion2FSwitchText
	db BANK(_PokemonMansion2FSwitchText)
	db TX_END

.PressedText:
	db TX_FAR
	dw _PokemonMansion2FSwitchPressedText
	db BANK(_PokemonMansion2FSwitchPressedText)
	db TX_END

.NotPressed:
	db TX_FAR
	dw _PokemonMansion2FSwitchNotPressedText
	db BANK(_PokemonMansion2FSwitchNotPressedText)
	db TX_END
