	db 0
	dw PokemonMansion3F_Object
;@ path: scripts/PokemonMansion3F
;@ def PokemonMansion3F_Script()
;@ Pokémon Mansion 3F's map script: first the map callback (Mansion3CheckReplaceSwitchDoorBlocks), then run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
PokemonMansion3F_Script:
;> Mansion3CheckReplaceSwitchDoorBlocks()
	call Mansion3CheckReplaceSwitchDoorBlocks
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wPokemonMansion3FCurScript = ExecuteCurMapScriptInTable(wPokemonMansion3FCurScript, Mansion3TrainerHeaders, PokemonMansion3F_ScriptPointers)
	ld hl, Mansion3TrainerHeaders
	ld de, PokemonMansion3F_ScriptPointers
	ld a, [wPokemonMansion3FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wPokemonMansion3FCurScript], a
	ret

;@ path: scripts/PokemonMansion3F
;@ def Mansion3CheckReplaceSwitchDoorBlocks()
;@ On entering the mansion's 3F: draw the two gates the secret switch controls.
;@ test: hLoadedROMBank = 0x14; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
Mansion3CheckReplaceSwitchDoorBlocks:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> if event(EVENT_MANSION_SWITCH_ON):
;>@on1     Mansion2ReplaceBlock(0x5F, 2, 7)
;>@on2     Mansion2ReplaceBlock(0x0E, 5, 7)
	ld a, [wEventFlags + $4F]
	bit (EVENT_MANSION_SWITCH_ON) % 8, a
	jr nz, .switchTurnedOn
;> else:
;>     Mansion2ReplaceBlock(0x0E, 2, 7)
	ld a, $e
	ld bc, ((2) & $ff) << 8 + ((7) & $ff)
	call Mansion2ReplaceBlock
;>     Mansion2ReplaceBlock(0x5F, 5, 7)
	ld a, $5f
	ld bc, ((5) & $ff) << 8 + ((7) & $ff)
	call Mansion2ReplaceBlock
	ret
.switchTurnedOn
;=@on1
	ld a, $5f
	ld bc, ((2) & $ff) << 8 + ((7) & $ff)
	call Mansion2ReplaceBlock
;=@on2
	ld a, $e
	ld bc, ((5) & $ff) << 8 + ((7) & $ff)
	call Mansion2ReplaceBlock
	ret

