DEF SCRIPT_POKEMONMANSION3F_END_BATTLE EQU 2

;@ path: scripts/PokemonMansion3F
;@ def PokemonMansion3FDefaultScript()
;@ 3F each step: stepping into one of the floor's holes drops the player - the right one to 2F, the others to
;@ 1F; otherwise the trainers watch for the player.
;@ test: skip the holes sit under a local label, which the pseudo-code can only name
PokemonMansion3FDefaultScript:
;> # has the player stepped into a hole? (the check is the local routine .isPlayerFallingDownHole)
;>@w0 wWhichDungeonWarp = 0
;>@on if not wStatusFlags3 >> BIT_ON_DUNGEON_WARP & 1:            # not still standing on one
;=@hole
	ld hl, .holeCoords
;>@hole     if ArePlayerCoordsInArray(PokemonMansion3FDefaultScript.holeCoords):
;>@idx         wWhichDungeonWarp = wCoordIndex      # which hole (1-3)
	call .isPlayerFallingDownHole
;>@f3         wStatusFlags3 |= 1 << BIT_ON_DUNGEON_WARP
;>@f6         wStatusFlags6 |= 1 << BIT_DUNGEON_WARP
;> if not wWhichDungeonWarp:
;>     return CheckFightingMapTrainers()
	ld a, [wWhichDungeonWarp]
	and a
	jp z, CheckFightingMapTrainers
;> if wWhichDungeonWarp == 3:
	cp $3
	ld a, POKEMON_MANSION_1F
	jr nz, .fellDownHoleTo1F
;>@e1     wDungeonWarpDestinationMap = POKEMON_MANSION_2F
	ld a, POKEMON_MANSION_2F
;> else:
;>     wDungeonWarpDestinationMap = POKEMON_MANSION_1F     # (loaded into a above)
.fellDownHoleTo1F
;=@e1
	ld [wDungeonWarpDestinationMap], a
	ret

.holeCoords:
	db 14, 16
	db 14, 17
	db 14, 19
	db -1 ; end

.isPlayerFallingDownHole:
;=@w0
	xor a
	ld [wWhichDungeonWarp], a
;=@on
	ld a, [wStatusFlags3]
	bit BIT_ON_DUNGEON_WARP, a
	ret nz
;=@hole
	call ArePlayerCoordsInArray
	ret nc
;=@idx
	ld a, [wCoordIndex]
	ld [wWhichDungeonWarp], a
;=@f3
	ld hl, wStatusFlags3
	set BIT_ON_DUNGEON_WARP, [hl]
;=@f6
	ld hl, wStatusFlags6
	set BIT_DUNGEON_WARP, [hl]
	ret

;@ path: scripts/PokemonMansion3F
;@ def Mansion3Script_Switches()
;@ Checking a statue switch on 3F (facing up at it): ask whether to press it.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Mansion3Script_Switches::
;> if mem[wSpritePlayerStateData1FacingDirection] != SPRITE_FACING_UP:
;>     return
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	ret nz
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hTextID = TEXT_POKEMONMANSION3F_SWITCH
;> return DisplayTextID()
	ld a, TEXT_POKEMONMANSION3F_SWITCH
	ldh [hTextID], a
	jp DisplayTextID

