PokemonMansionB1F_h::
	db FACILITY
	db $E, $F
	dw PokemonMansionB1F_Blocks
	dw PokemonMansionB1F_TextPointers
	dw PokemonMansionB1F_Script
	db 0
	dw PokemonMansionB1F_Object
;@ path: scripts/PokemonMansionB1F
;@ def PokemonMansionB1F_Script()
;@ Pokémon Mansion B1F's map script: first the map callback (MansionB1FCheckReplaceSwitchDoorBlocks), then run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
PokemonMansionB1F_Script:
;> MansionB1FCheckReplaceSwitchDoorBlocks()
	call MansionB1FCheckReplaceSwitchDoorBlocks
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wPokemonMansionB1FCurScript = ExecuteCurMapScriptInTable(wPokemonMansionB1FCurScript, Mansion4TrainerHeaders, PokemonMansionB1F_ScriptPointers)
	ld hl, Mansion4TrainerHeaders
	ld de, PokemonMansionB1F_ScriptPointers
	ld a, [wPokemonMansionB1FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wPokemonMansionB1FCurScript], a
	ret

;@ path: scripts/PokemonMansionB1F
;@ def MansionB1FCheckReplaceSwitchDoorBlocks()
;@ On entering the mansion's B1F: draw the four gates the secret switch controls.
;@ test: hLoadedROMBank = 0x14; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
MansionB1FCheckReplaceSwitchDoorBlocks:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> if event(EVENT_MANSION_SWITCH_ON):
;>@on1     Mansion2ReplaceBlock(0x2D, 8, 13)
;>@on2     Mansion2ReplaceBlock(0x5F, 11, 6)
;>@on3     Mansion2ReplaceBlock(0x0E, 3, 4)
;>@on4     Mansion2ReplaceBlock(0x0E, 8, 8)
	ld a, [wEventFlags + $4F]
	bit (EVENT_MANSION_SWITCH_ON) % 8, a
	jr nz, .switchTurnedOn
;> else:
;>     Mansion2ReplaceBlock(0x0E, 8, 13)
	ld a, $e
	ld bc, ((8) & $ff) << 8 + ((13) & $ff)
	call Mansion2ReplaceBlock
;>     Mansion2ReplaceBlock(0x0E, 11, 6)
	ld a, $e
	ld bc, ((11) & $ff) << 8 + ((6) & $ff)
	call Mansion2ReplaceBlock
;>     Mansion2ReplaceBlock(0x5F, 3, 4)
	ld a, $5f
	ld bc, ((3) & $ff) << 8 + ((4) & $ff)
	call Mansion2ReplaceBlock
;>     Mansion2ReplaceBlock(0x54, 8, 8)
	ld a, $54
	ld bc, ((8) & $ff) << 8 + ((8) & $ff)
	call Mansion2ReplaceBlock
	ret
.switchTurnedOn
;=@on1
	ld a, $2d
	ld bc, ((8) & $ff) << 8 + ((13) & $ff)
	call Mansion2ReplaceBlock
;=@on2
	ld a, $5f
	ld bc, ((11) & $ff) << 8 + ((6) & $ff)
	call Mansion2ReplaceBlock
;=@on3
	ld a, $e
	ld bc, ((3) & $ff) << 8 + ((4) & $ff)
	call Mansion2ReplaceBlock
;=@on4
	ld a, $e
	ld bc, ((8) & $ff) << 8 + ((8) & $ff)
	call Mansion2ReplaceBlock
	ret

;@ path: scripts/PokemonMansionB1F
;@ def Mansion4Script_Switches()
;@ Checking a statue switch on B1F (facing up at it): ask whether to press it.
;@ test: hLoadedROMBank = 0x14    # the bank this code runs in
Mansion4Script_Switches::
;> if mem[wSpritePlayerStateData1FacingDirection] != SPRITE_FACING_UP:
;>     return
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	ret nz
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hTextID = TEXT_POKEMONMANSIONB1F_SWITCH
;> return DisplayTextID()
	ld a, TEXT_POKEMONMANSIONB1F_SWITCH
	ldh [hTextID], a
	jp DisplayTextID

