;@ path: scripts/Route2
;@ def Route2_Script()
;@ Route 2's map script: only lets texts draw their box.
;@ test: hLoadedROMBank = 0x15    # the bank this code runs in
Route2_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/Route2
Route2_TextPointers:
	dw PickUpItemText
DEF TEXT_ROUTE2_MOON_STONE EQU 1
	dw PickUpItemText
DEF TEXT_ROUTE2_HP_UP EQU 2
	dw Route2SignText
DEF TEXT_ROUTE2_SIGN EQU 3
	dw Route2DiglettsCaveSignText
DEF TEXT_ROUTE2_DIGLETTS_CAVE_SIGN EQU 4

;@ path: scripts/Route2
Route2SignText:
	db TX_FAR
	dw _Route2SignText
	db BANK(_Route2SignText)
	db TX_END

;@ path: scripts/Route2
Route2DiglettsCaveSignText:
	db TX_FAR
	dw _Route2DiglettsCaveSignText
	db BANK(_Route2DiglettsCaveSignText)
	db TX_END
;@ path: scripts/Route3
;@ def Route3_Script()
;@ Route 3's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x15    # the bank this code runs in
Route3_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute3CurScript = ExecuteCurMapScriptInTable(wRoute3CurScript, Route3TrainerHeaders, Route3_ScriptPointers)
	ld hl, Route3TrainerHeaders
	ld de, Route3_ScriptPointers
	ld a, [wRoute3CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute3CurScript], a
	ret

;@ path: scripts/Route3
Route3_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_ROUTE3_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROUTE3_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROUTE3_END_BATTLE EQU 2

;@ path: scripts/Route3
Route3_TextPointers:
	dw Route3SuperNerdText
DEF TEXT_ROUTE3_SUPER_NERD EQU 1
	dw Route3Youngster1Text
DEF TEXT_ROUTE3_YOUNGSTER1 EQU 2
	dw Route3Youngster2Text
DEF TEXT_ROUTE3_YOUNGSTER2 EQU 3
