;@ path: scripts/Route4
;@ def Route4_Script()
;@ Route 4's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x15    # the bank this code runs in
Route4_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute4CurScript = ExecuteCurMapScriptInTable(wRoute4CurScript, Route4TrainerHeaders, Route4_ScriptPointers)
	ld hl, Route4TrainerHeaders
	ld de, Route4_ScriptPointers
	ld a, [wRoute4CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute4CurScript], a
	ret

;@ path: scripts/Route4
Route4_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_ROUTE4_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROUTE4_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROUTE4_END_BATTLE EQU 2

;@ path: scripts/Route4
Route4_TextPointers:
	dw Route4CooltrainerF1Text
DEF TEXT_ROUTE4_COOLTRAINER_F1 EQU 1
	dw Route4CooltrainerF2Text
DEF TEXT_ROUTE4_COOLTRAINER_F2 EQU 2
	dw PickUpItemText
DEF TEXT_ROUTE4_TM_WHIRLWIND EQU 3
	dw PokeCenterSignText
DEF TEXT_ROUTE4_POKECENTER_SIGN EQU 4
	dw Route4MtMoonSignText
DEF TEXT_ROUTE4_MT_MOON_SIGN EQU 5
	dw Route4SignText
DEF TEXT_ROUTE4_SIGN EQU 6

;@ path: scripts/Route4
Route4TrainerHeaders:
;@ path: scripts/Route4
Route4TrainerHeader0:
	db $2
	db 3 << 4
	dw wEventFlags + (EVENT_BEAT_ROUTE_4_TRAINER_0 - $2) / 8
	dw Route4CooltrainerF2BattleText, Route4CooltrainerF2AfterBattleText, Route4CooltrainerF2EndBattleText, Route4CooltrainerF2EndBattleText
	db -1 ; end

