;@ path: scripts/Route17
;@ def Route17_Script()
;@ Route 17's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x15    # the bank this code runs in
Route17_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute17CurScript = ExecuteCurMapScriptInTable(wRoute17CurScript, Route17TrainerHeaders, Route17_ScriptPointers)
	ld hl, Route17TrainerHeaders
	ld de, Route17_ScriptPointers
	ld a, [wRoute17CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute17CurScript], a
	ret

;@ path: scripts/Route17
Route17_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_ROUTE17_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROUTE17_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROUTE17_END_BATTLE EQU 2

;@ path: scripts/Route17
Route17_TextPointers:
	dw Route17Biker1Text
DEF TEXT_ROUTE17_BIKER1 EQU 1
	dw Route17Biker2Text
DEF TEXT_ROUTE17_BIKER2 EQU 2
	dw Route17Biker3Text
DEF TEXT_ROUTE17_BIKER3 EQU 3
	dw Route17Biker4Text
DEF TEXT_ROUTE17_BIKER4 EQU 4
	dw Route17Biker5Text
DEF TEXT_ROUTE17_BIKER5 EQU 5
	dw Route17Biker6Text
DEF TEXT_ROUTE17_BIKER6 EQU 6
	dw Route17Biker7Text
DEF TEXT_ROUTE17_BIKER7 EQU 7
	dw Route17Biker8Text
DEF TEXT_ROUTE17_BIKER8 EQU 8
	dw Route17Biker9Text
DEF TEXT_ROUTE17_BIKER9 EQU 9
	dw Route17Biker10Text
DEF TEXT_ROUTE17_BIKER10 EQU $A
	dw Route17NoticeSign1Text
DEF TEXT_ROUTE17_NOTICE_SIGN1 EQU $B
	dw Route17TrainerTips1Text
DEF TEXT_ROUTE17_TRAINER_TIPS1 EQU $C
	dw Route17TrainerTips2Text
DEF TEXT_ROUTE17_TRAINER_TIPS2 EQU $D
	dw Route17SignText
DEF TEXT_ROUTE17_SIGN EQU $E
	dw Route17NoticeSign2Text
DEF TEXT_ROUTE17_NOTICE_SIGN2 EQU $F
	dw Route17CyclingRoadEndsSignText
DEF TEXT_ROUTE17_CYCLING_ROAD_ENDS_SIGN EQU $10

;@ path: scripts/Route17
Route17TrainerHeaders:
;@ path: scripts/Route17
Route17TrainerHeader0:
	db $1
	db 3 << 4
	dw wEventFlags + (EVENT_BEAT_ROUTE_17_TRAINER_0 - $1) / 8
	dw Route17Biker1BattleText, Route17Biker1AfterBattleText, Route17Biker1EndBattleText, Route17Biker1EndBattleText
