VermilionOldRodHouse_h::
	db HOUSE
	db $4, $4
	dw VermilionOldRodHouse_Blocks
	dw VermilionOldRodHouse_TextPointers
	dw VermilionOldRodHouse_Script
	db 0
	dw VermilionOldRodHouse_Object
;@ path: scripts/VermilionOldRodHouse
;@ def VermilionOldRodHouse_Script()
;@ Vermilion Old Rod House's map script: only lets texts draw their box.
;@ test: hLoadedROMBank = 0x15    # the bank this code runs in
VermilionOldRodHouse_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/VermilionOldRodHouse
VermilionOldRodHouse_TextPointers:
	dw VermilionOldRodHouseFishingGuruText
DEF TEXT_VERMILIONOLDRODHOUSE_FISHING_GURU EQU 1

;@ path: scripts/VermilionOldRodHouse
;@ def VermilionOldRodHouseFishingGuruText() -> hl
;@ The fishing guru in Vermilion: "Do you like to fish?" - on yes he gives the Old Rod (if the bag has room);
;@ later he asks how the fish are biting.
;@ test: skip a text script: the code after text_asm is run by the text engine
VermilionOldRodHouseFishingGuruText:
	db TX_START_ASM
;> if wStatusFlags1 >> BIT_GOT_OLD_ROD & 1:
;>     text = VermilionOldRodHouseFishingGuruText.HowAreTheFishBitingText
	ld a, [wStatusFlags1]
	bit BIT_GOT_OLD_ROD, a
	jr nz, .got_old_rod
;> else:
;>     PrintText(VermilionOldRodHouseFishingGuruText.DoYouLikeToFishText)
	ld hl, .DoYouLikeToFishText
	call PrintText
;>     YesNoChoice()
	call YesNoChoice
;>     if wCurrentMenuItem:
;>         text = VermilionOldRodHouseFishingGuruText.ThatsSoDisappointingText
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .refused
;>     elif GiveItem(OLD_ROD, 1):
	ld bc, ((OLD_ROD) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         wStatusFlags1 |= 1 << BIT_GOT_OLD_ROD
	ld hl, wStatusFlags1
	set BIT_GOT_OLD_ROD, [hl]
;>         text = VermilionOldRodHouseFishingGuruText.TakeThisText
	ld hl, .TakeThisText
	jr .print_text
.bag_full
;>     else:
;>         text = VermilionOldRodHouseFishingGuruText.NoRoomText
	ld hl, .NoRoomText
	jr .print_text
.refused
	ld hl, .ThatsSoDisappointingText
	jr .print_text
.got_old_rod
	ld hl, .HowAreTheFishBitingText
.print_text
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.DoYouLikeToFishText:
	db TX_FAR
	dw _VermilionOldRodHouseFishingGuruDoYouLikeToFishText
	db BANK(_VermilionOldRodHouseFishingGuruDoYouLikeToFishText)
	db TX_END

.TakeThisText:
	db TX_FAR
	dw _VermilionOldRodHouseFishingGuruTakeThisText
	db BANK(_VermilionOldRodHouseFishingGuruTakeThisText)
	db TX_SOUND_GET_ITEM_1
	db TX_FAR
	dw _VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText
	db BANK(_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText)
	db TX_END

.ThatsSoDisappointingText:
	db TX_FAR
	dw _VermilionOldRodHouseFishingGuruThatsSoDisappointingText
	db BANK(_VermilionOldRodHouseFishingGuruThatsSoDisappointingText)
	db TX_END

.HowAreTheFishBitingText:
	db TX_FAR
	dw _VermilionOldRodHouseFishingGuruHowAreTheFishBitingText
	db BANK(_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText)
	db TX_END

.NoRoomText:
	db TX_FAR
	dw _VermilionOldRodHouseFishingGuruNoRoomText
	db BANK(_VermilionOldRodHouseFishingGuruNoRoomText)
	db TX_END
DEF VERMILIONOLDRODHOUSE_FISHING_GURU EQU 1
	EXPORT VERMILIONOLDRODHOUSE_FISHING_GURU

