VermilionOldRodHouse_Object:
	db $a ; border block

	db 2
	db 7, 2, 9 - 1, LAST_MAP
	db 7, 3, 9 - 1, LAST_MAP

	db 0

	db 1
	db SPRITE_FISHING_GURU
	db 4 + 4
