	dw (wOverworldMap + 7 + (VERMILION_OLD_ROD_HOUSE_WIDTH) + ((VERMILION_OLD_ROD_HOUSE_WIDTH) + 6) * ((7) >> 1) + ((2) >> 1))
	db 7, 2
