FuchsiaGoodRodHouse_h::
	db SHIP
	db $4, $4
	dw FuchsiaGoodRodHouse_Blocks
	dw FuchsiaGoodRodHouse_TextPointers
	dw FuchsiaGoodRodHouse_Script
	db 0
	dw FuchsiaGoodRodHouse_Object
;@ path: scripts/FuchsiaGoodRodHouse
;@ def FuchsiaGoodRodHouse_Script()
;@ The fishing guru's house in Fuchsia City: only lets texts draw their box.
FuchsiaGoodRodHouse_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/FuchsiaGoodRodHouse
FuchsiaGoodRodHouse_TextPointers:
	dw FuchsiaGoodRodHouseFishingGuruText
DEF TEXT_FUCHSIAGOODRODHOUSE_FISHING_GURU EQU 1

;@ path: scripts/FuchsiaGoodRodHouse
;@ def FuchsiaGoodRodHouseFishingGuruText() -> hl
;@ The fishing guru: offers the Good Rod; accepted, it goes into the bag if there is room.
;@ test: skip a text script: the code after text_asm is run by the text engine
FuchsiaGoodRodHouseFishingGuruText:
	db TX_START_ASM
;> if wStatusFlags1 >> BIT_GOT_GOOD_ROD & 1:
	ld a, [wStatusFlags1]
	bit BIT_GOT_GOOD_ROD, a
	jr nz, .got_item
;>     text = FuchsiaGoodRodHouseFishingGuruText.HowAreTheFishText
;> else:
;>     PrintText(FuchsiaGoodRodHouseFishingGuruText.Text)
	ld hl, .Text
	call PrintText
;>     YesNoChoice()
	call YesNoChoice
;>     if wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .refused
;>         text = FuchsiaGoodRodHouseFishingGuruText.ThatsSoDisappointingText
;>     elif GiveItem(GOOD_ROD, 1):
	ld bc, ((GOOD_ROD) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         wStatusFlags1 |= 1 << BIT_GOT_GOOD_ROD
	ld hl, wStatusFlags1
	set BIT_GOT_GOOD_ROD, [hl]
;>         text = FuchsiaGoodRodHouseFishingGuruText.ReceivedGoodRodText
	ld hl, .ReceivedGoodRodText
	jr .done
;>     else:
.bag_full
;>         text = FuchsiaGoodRodHouseFishingGuruText.NoRoomText
	ld hl, .NoRoomText
	jr .done
;> PrintText(text)
.refused
	ld hl, .ThatsSoDisappointingText
	jr .done
.got_item
	ld hl, .HowAreTheFishText
.done
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _FuchsiaGoodRodHouseFishingGuruText
	db BANK(_FuchsiaGoodRodHouseFishingGuruText)
	db TX_END

.ReceivedGoodRodText:
	db TX_FAR
	dw _FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText
	db BANK(_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText)
	db TX_SOUND_GET_ITEM_1
	db TX_END

