Daycare_h::
	db HOUSE
	db $4, $4
	dw Daycare_Blocks
	dw Daycare_TextPointers
	dw Daycare_Script
	db 0
	dw Daycare_Object
;@ path: scripts/Daycare
;@ def Daycare_Script()
;@ The Day Care's map script: only lets texts draw their box.
Daycare_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/Daycare
Daycare_TextPointers:
	dw DaycareGentlemanText
DEF TEXT_DAYCARE_GENTLEMAN EQU 1

;@ path: scripts/Daycare
;@ def DaycareGentlemanText() -> hl
;@ The Day Care man. With no Pokémon in his care he takes one from the party (not the last one, and none
;@ that knows an HM move). With one in his care he tells how many levels it has grown and gives it back
;@ for ¥100 plus ¥100 per level; it relearns the moves of its new level and comes back with full HP.
;@ test: skip a text script: the code after text_asm is run by the text engine
DaycareGentlemanText:
	db TX_START_ASM
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> if not wDayCareInUse:
	ld a, [wDayCareInUse]
	and a
	jp nz, .daycareInUse
;>     PrintText(DaycareGentlemanText.IntroText)
	ld hl, .IntroText
	call PrintText
;>     YesNoChoice()
	call YesNoChoice
;>     if wCurrentMenuItem:
;>         text = DaycareGentlemanText.ComeAgainText
	ld a, [wCurrentMenuItem]
	and a
	ld hl, .ComeAgainText
	jp nz, .done
;>     elif wPartyCount == 1:
	ld a, [wPartyCount]
	dec a
;>         text = DaycareGentlemanText.OnlyHaveOneMonText
	ld hl, .OnlyHaveOneMonText
	jp z, .done
;>     else:
;>         PrintText(DaycareGentlemanText.WhichMonText)
	ld hl, .WhichMonText
	call PrintText
;>         wUpdateSpritesEnabled = 0
	xor a
	ld [wUpdateSpritesEnabled], a
;>         wPartyMenuTypeOrMessageID = 0
	ld [wPartyMenuTypeOrMessageID], a
;>         wMenuItemToSwap = 0
	ld [wMenuItemToSwap], a
;>         cancelled = DisplayPartyMenu()
	call DisplayPartyMenu
;>         GBPalWhiteOutWithDelay3()
	push af
	call GBPalWhiteOutWithDelay3
;>         RestoreScreenTilesAndReloadTilePatterns()
	call RestoreScreenTilesAndReloadTilePatterns
;>         LoadGBPal()
	call LoadGBPal
;>         if cancelled:
;>             text = DaycareGentlemanText.AllRightThenText
	pop af
	ld hl, .AllRightThenText
	jp c, .done
;>         elif KnowsHMMove():
	ld hl, KnowsHMMove
	ld b, BANK(KnowsHMMove)
	call Bankswitch
;>             text = DaycareGentlemanText.CantAcceptMonWithHMText
	ld hl, .CantAcceptMonWithHMText
	jp c, .done
;>         else:
;>             wPartyAndBillsPCSavedMenuItem = 0
	xor a
	ld [wPartyAndBillsPCSavedMenuItem], a
;>             GetPartyMonName(wWhichPokemon, addr(wPartyMonNicks))
	ld a, [wWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
;>             PrintText(DaycareGentlemanText.WillLookAfterMonText)
	ld hl, .WillLookAfterMonText
	call PrintText
;>             wDayCareInUse = 1
	ld a, 1
	ld [wDayCareInUse], a
;>             wMoveMonType = PARTY_TO_DAYCARE
	ld a, PARTY_TO_DAYCARE
	ld [wMoveMonType], a
;>             MoveMon()
	call MoveMon
;>             wRemoveMonFromBox = 0
	xor a
	ld [wRemoveMonFromBox], a
;>             RemovePokemon()
	call RemovePokemon
;>             PlayCry(wCurPartySpecies)
	ld a, [wCurPartySpecies]
	call PlayCry
;>             text = DaycareGentlemanText.ComeSeeMeInAWhileText
	ld hl, .ComeSeeMeInAWhileText
	jp .done
;>@pt     PrintText(text)
;>@rt     return TextScriptEnd()

.daycareInUse
;> GetPartyMonName(0, addr(wDayCareMonName))
	xor a
	ld hl, wDayCareMonName
	call GetPartyMonName
;> wMonDataLocation = DAYCARE_DATA
	ld a, DAYCARE_DATA
	ld [wMonDataLocation], a
;> LoadMonData()
	call LoadMonData
;> level = CalcLevelFromExperience()
	ld hl, CalcLevelFromExperience
	ld b, BANK(CalcLevelFromExperience)
	call Bankswitch
;> if level >= MAX_LEVEL:
	ld a, d
	cp MAX_LEVEL
	jr c, .skipCalcExp
;>     CalcExperience(MAX_LEVEL)          # the experience of level 100

	ld d, MAX_LEVEL
	ld hl, CalcExperience
	ld b, BANK(CalcExperience)
	call Bankswitch
;>     wDayCareMonExp[0] = hExperience[0]       # no more than that
	ld hl, wDayCareMonExp
	ldh a, [hExperience]
	ld [hli], a
;>     wDayCareMonExp[1] = hExperience[1]
	ldh a, [hExperience + 1]
	ld [hli], a
;>     wDayCareMonExp[2] = hExperience[2]
	ldh a, [hExperience + 2]
	ld [hl], a
;>     level = MAX_LEVEL
	ld d, MAX_LEVEL

.skipCalcExp
;> wDayCareNumLevelsGrown = 0
	xor a
	ld [wDayCareNumLevelsGrown], a
;> wDayCareStartLevel = wDayCareMonBoxLevel
	ld hl, wDayCareMonBoxLevel
	ld a, [hl]
	ld [wDayCareStartLevel], a
;>@box wDayCareMonBoxLevel = level
;>@same if level == wDayCareStartLevel:
	cp d
;=@box
	ld [hl], d
;>     text = DaycareGentlemanText.MonNeedsMoreTimeText
	ld hl, .MonNeedsMoreTimeText
;=@same
	jr z, .next
;> else:
;>     wDayCareNumLevelsGrown = level - wDayCareStartLevel
	ld a, [wDayCareStartLevel]
	ld b, a
	ld a, d
	sub b
	ld [wDayCareNumLevelsGrown], a
;>     text = DaycareGentlemanText.MonHasGrownText
	ld hl, .MonHasGrownText

.next
;> PrintText(text)
	call PrintText
;> leave = True
;> if wPartyCount == PARTY_LENGTH:
	ld a, [wPartyCount]
	cp PARTY_LENGTH
;>     text = DaycareGentlemanText.NoRoomForMonText
	ld hl, .NoRoomForMonText
	jp z, .leaveMonInDayCare
;> else:
;>     wDayCareTotalCost[0], wDayCareTotalCost[1] = 0, 0
	ld de, wDayCareTotalCost
	xor a
	ld [de], a
	inc de
	ld [de], a
;>     wDayCarePerLevelCost[0], wDayCarePerLevelCost[1] = 0x01, 0x00    # ¥100 in BCD
	ld hl, wDayCarePerLevelCost
	ld a, $1
	ld [hli], a
	ld [hl], $0
;>     for _ in range(wDayCareNumLevelsGrown + 1):
	ld a, [wDayCareNumLevelsGrown]
	inc a
	ld b, a
	ld c, 2
.calcPriceLoop
;>@add         AddBCDPredef()                  # wDayCareTotalCost += wDayCarePerLevelCost (2 BCD bytes)
	push hl
	push de
	push bc
	ld a, (AddBCDPredefPredef - PredefPointers) / 3
	call Predef
;=@add
	pop bc
	pop de
	pop hl
	dec b
	jr nz, .calcPriceLoop
;>     PrintText(DaycareGentlemanText.OweMoneyText)
	ld hl, .OweMoneyText
	call PrintText
;>     wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;>     DisplayTextBoxID()
	call DisplayTextBoxID
;>     YesNoChoice()
	call YesNoChoice
;>     if wCurrentMenuItem:
	ld hl, .AllRightThenText
	ld a, [wCurrentMenuItem]
	and a
	jp nz, .leaveMonInDayCare
;>         text = DaycareGentlemanText.AllRightThenText
;>     else:
;>         hMoney[0], hMoney[1], hMoney[2] = 0, wDayCareTotalCost[0], wDayCareTotalCost[1]
	ld hl, wDayCareTotalCost
	ldh [hMoney], a
	ld a, [hli]
	ldh [hMoney + 1], a
	ld a, [hl]
	ldh [hMoney + 2], a
;>         if HasEnoughMoney()[0]:
	call HasEnoughMoney
	jr nc, .enoughMoney
;>             text = DaycareGentlemanText.NotEnoughMoneyText
	ld hl, .NotEnoughMoneyText
	jp .leaveMonInDayCare
;>         else:
;>             leave = False
;>             wDayCareInUse = 0

.enoughMoney
	xor a
	ld [wDayCareInUse], a
;>             wDayCareNumLevelsGrown = 0
	ld hl, wDayCareNumLevelsGrown
	ld [hli], a
;>             SubBCDPredef()              # wPlayerMoney -= wDayCareTotalCost (3 BCD bytes from wDayCareNumLevelsGrown)
	inc hl
	ld de, wPlayerMoney + 2
	ld c, $3
	ld a, (SubBCDPredefPredef - PredefPointers) / 3
	call Predef
;>             PlaySoundWaitForCurrent(SFX_PURCHASE)
	ld a, SFX_PURCHASE
	call PlaySoundWaitForCurrent
;>             wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;>             DisplayTextBoxID()
	call DisplayTextBoxID
;>             PrintText(DaycareGentlemanText.HeresYourMonText)
	ld hl, .HeresYourMonText
	call PrintText
;>             wMoveMonType = DAYCARE_TO_PARTY
	ld a, DAYCARE_TO_PARTY
	ld [wMoveMonType], a
;>             MoveMon()
	call MoveMon
;>             wCurPartySpecies = wDayCareMonSpecies
	ld a, [wDayCareMonSpecies]
	ld [wCurPartySpecies], a
;>             last = wPartyCount - 1
	ld a, [wPartyCount]
	dec a
	push af
;>             moves = AddNTimes(addr(wPartyMon1Moves), PARTYMON_STRUCT_LENGTH, last)
	ld bc, PARTYMON_STRUCT_LENGTH
	push bc
	ld hl, wPartyMon1Moves
	call AddNTimes
	ld d, h
	ld e, l
;>             wLearningMovesFromDayCare = 1
	ld a, 1
	ld [wLearningMovesFromDayCare], a
;>             WriteMonMoves(moves)            # the moves it learned while it grew
	ld a, (WriteMonMovesPredef - PredefPointers) / 3
	call Predef
;>             mon = AddNTimes(addr(wPartyMon1HP), PARTYMON_STRUCT_LENGTH, last)
	pop bc
	pop af

; set mon's HP to max
	ld hl, wPartyMon1HP
	call AddNTimes
;>             maxhp = mon + MON_MAXHP - MON_HP
	ld d, h
	ld e, l
	ld bc, MON_MAXHP - MON_HP
	add hl, bc
;>             mem[mon] = mem[maxhp]                     # HP = max HP
	ld a, [hli]
	ld [de], a
;>             mem[mon + 1] = mem[maxhp + 1]
	inc de
	ld a, [hl]
	ld [de], a

;>             PlayCry(wCurPartySpecies)
	ld a, [wCurPartySpecies]
	call PlayCry
;>             text = DaycareGentlemanText.GotMonBackText
	ld hl, .GotMonBackText
	jr .done
;> if leave:
;>     wDayCareMonBoxLevel = wDayCareStartLevel

.leaveMonInDayCare
	ld a, [wDayCareStartLevel]
	ld [wDayCareMonBoxLevel], a
;> PrintText(text)

.done
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

