;@ path: scripts/Route12SuperRodHouse
;@ def Route12SuperRodHouse_Script()
;@ Route 12 Super Rod House's map script: only lets texts draw their box.
;@ test: hLoadedROMBank = 0x15    # the bank this code runs in
Route12SuperRodHouse_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/Route12SuperRodHouse
Route12SuperRodHouse_TextPointers:
	dw Route12SuperRodHouseFishingGuruText
DEF TEXT_ROUTE12SUPERRODHOUSE_FISHING_GURU EQU 1

;@ path: scripts/Route12SuperRodHouse
;@ def Route12SuperRodHouseFishingGuruText() -> hl
;@ The fishing guru on Route 12: "Do you like to fish?" - on yes he gives the Super Rod (if the bag has room);
;@ later he tells the player to try fishing everywhere.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route12SuperRodHouseFishingGuruText:
	db TX_START_ASM
;> if wStatusFlags1 >> BIT_GOT_SUPER_ROD & 1:
;>     text = Route12SuperRodHouseFishingGuruText.TryFishingText
	ld a, [wStatusFlags1]
	bit BIT_GOT_SUPER_ROD, a
	jr nz, .got_item
;> else:
;>     PrintText(Route12SuperRodHouseFishingGuruText.DoYouLikeToFishText)
	ld hl, .DoYouLikeToFishText
	call PrintText
;>     YesNoChoice()
	call YesNoChoice
;>     if wCurrentMenuItem:
;>         text = Route12SuperRodHouseFishingGuruText.ThatsDisappointingText
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .refused
;>     elif GiveItem(SUPER_ROD, 1):
	ld bc, ((SUPER_ROD) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         wStatusFlags1 |= 1 << BIT_GOT_SUPER_ROD
	ld hl, wStatusFlags1
	set BIT_GOT_SUPER_ROD, [hl]
;>         text = Route12SuperRodHouseFishingGuruText.ReceivedSuperRodText
	ld hl, .ReceivedSuperRodText
	jr .done
.bag_full
;>     else:
;>         text = Route12SuperRodHouseFishingGuruText.NoRoomText
	ld hl, .NoRoomText
	jr .done
.refused
	ld hl, .ThatsDisappointingText
	jr .done
.got_item
	ld hl, .TryFishingText
.done
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.DoYouLikeToFishText:
	db TX_FAR
	dw _Route12SuperRodHouseFishingGuruDoYouLikeToFishText
	db BANK(_Route12SuperRodHouseFishingGuruDoYouLikeToFishText)
	db TX_END

.ReceivedSuperRodText:
	db TX_FAR
	dw _Route12SuperRodHouseFishingGuruReceivedSuperRodText
	db BANK(_Route12SuperRodHouseFishingGuruReceivedSuperRodText)
	db TX_SOUND_GET_ITEM_1
	db TX_FAR
