SilphCo8F_h::
	db FACILITY
	db $9, $D
	dw SilphCo8F_Blocks
	dw SilphCo8F_TextPointers
	dw SilphCo8F_Script
	db 0
	dw SilphCo8F_Object
;@ path: scripts/SilphCo8F
;@ def SilphCo8F_Script()
;@ Silph Co. 8F's map script: first the map callback (SilphCo8FGateCallbackScript), then run the current step of the map's script (its trainers).
;@ test: skip runs SilphCo8FGateCallbackScript, whose data sits under a local label
SilphCo8F_Script:
;> SilphCo8FGateCallbackScript()
	call SilphCo8FGateCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSilphCo8FCurScript = ExecuteCurMapScriptInTable(wSilphCo8FCurScript, SilphCo8TrainerHeaders, SilphCo8F_ScriptPointers)
	ld hl, SilphCo8TrainerHeaders
	ld de, SilphCo8F_ScriptPointers
	ld a, [wSilphCo8FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSilphCo8FCurScript], a
	ret

;@ path: scripts/SilphCo8F
;@ def SilphCo8FGateCallbackScript()
;@ On entering the floor: if the card-key door here was just opened, note it; while it is locked, draw it
;@ (block $5F) into the map.
;@ test: skip the door list sits under a local label, which the pseudo-code can only name
SilphCo8FGateCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> SilphCo8F_SetCardKeyDoorYScript(SilphCo8FGateCallbackScript.GateCoordinates)
	ld hl, .GateCoordinates
	call SilphCo8F_SetCardKeyDoorYScript
;> SilphCo8F_UnlockedDoorEventScript()
	call SilphCo8F_UnlockedDoorEventScript
;> if not event(EVENT_SILPH_CO_8_UNLOCKED_DOOR):
	ld a, [wEventFlags + $EB]
	bit (EVENT_SILPH_CO_8_UNLOCKED_DOOR) % 8, a
	ret nz
;>     wNewTileBlockID = 0x5F
	ld a, $5f
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=4 << 8 | 3)
	ld bc, ((4) & $ff) << 8 + ((3) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

.GateCoordinates:
	db 4, 3
	db -1 ; end

;@ path: scripts/SilphCo8F
;@ def SilphCo8F_SetCardKeyDoorYScript(doors: hl)
;@ Look up the door the card key just opened (wCardKeyDoorY/X) in the floor's door list: hUnlockedSilphCoDoors
;@ becomes its number (1, 2...) and the opened door is forgotten; 0 if it is not one of them.
;@ test: hLoadedROMBank = 0x15    # the bank this code runs in
SilphCo8F_SetCardKeyDoorYScript:
;> y = wCardKeyDoorY
	push hl
	ld hl, wCardKeyDoorY
	ld a, [hli]
	ld b, a
;> x = wCardKeyDoorX
	ld a, [hl]
	ld c, a
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
;> while mem[doors] != 0xFF:
	pop hl
.loop_check_doors
	ld a, [hli]
	cp $ff
	jr z, .exit_loop
;>     hUnlockedSilphCoDoors += 1
	push hl
	ld hl, hUnlockedSilphCoDoors
	inc [hl]
	pop hl
;>@match     if mem[doors] == y and mem[doors + 1] == x:
	cp b
	jr z, .check_y_coord
;>@clear         wCardKeyDoorY = wCardKeyDoorX = 0
;>@ret         return
;>     doors += 2
	inc hl
	jr .loop_check_doors
.check_y_coord
;=@match
	ld a, [hli]
	cp c
	jr nz, .loop_check_doors
;=@clear
	ld hl, wCardKeyDoorY
	xor a
	ld [hli], a
	ld [hl], a
;=@ret
	ret
.exit_loop
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
	ret

;@ path: scripts/SilphCo8F
;@ def SilphCo8F_UnlockedDoorEventScript()
;@ If the card key just opened this floor's door, note it as an event.
;@ test: hLoadedROMBank = 0x15    # the bank this code runs in
SilphCo8F_UnlockedDoorEventScript:
;> if hUnlockedSilphCoDoors:
;>     set_event(EVENT_SILPH_CO_8_UNLOCKED_DOOR)
	ldh a, [hUnlockedSilphCoDoors]
	and a
	ret z
	ld hl, wEventFlags + $EB
	set (EVENT_SILPH_CO_8_UNLOCKED_DOOR) % 8, [hl]
	ret

