;@ path: scripts/SilphCo8F
;@ def SilphCo8FSilphWorkerMText() -> hl
;@ The Silph worker on 8F: Silph is finished - after Giovanni is beaten, thanks for saving us.
;@ test: skip a text script: the code after text_asm is run by the text engine
SilphCo8FSilphWorkerMText:
	db TX_START_ASM
;> if event(EVENT_BEAT_SILPH_CO_GIOVANNI):
;>     text = SilphCo8FSilphWorkerMText.ThanksForSavingUsText
	ld a, [wEventFlags + $F1]
	bit (EVENT_BEAT_SILPH_CO_GIOVANNI) % 8, a
	ld hl, .ThanksForSavingUsText
	jr nz, .beat_giovanni
;> else:
;>     text = SilphCo8FSilphWorkerMText.SilphIsFinishedText
	ld hl, .SilphIsFinishedText
.beat_giovanni
;> PrintText(text)
;> return TextScriptEnd()
	call PrintText
	jp TextScriptEnd

.SilphIsFinishedText:
	db TX_FAR
	dw _SilphCo8FSilphWorkerMSilphIsFinishedText
	db BANK(_SilphCo8FSilphWorkerMSilphIsFinishedText)
	db TX_END

.ThanksForSavingUsText:
	db TX_FAR
	dw _SilphCo8FSilphWorkerMThanksForSavingUsText
	db BANK(_SilphCo8FSilphWorkerMThanksForSavingUsText)
	db TX_END

;@ path: scripts/SilphCo8F
;@ def SilphCo8FRocket1Text() -> hl
;@ Rocket 1, a trainer in Silph Co. 8F: the trainer talk and battle.
;@ test: skip a text script: the code after text_asm is run by the text engine
SilphCo8FRocket1Text:
	db TX_START_ASM
;> TalkToTrainer(SilphCo8TrainerHeader0)
;> return TextScriptEnd()
	ld hl, SilphCo8TrainerHeader0
	call TalkToTrainer
	jp TextScriptEnd

;@ path: scripts/SilphCo8F
