SECTION "Maps 14", ROMX

;@ path: scripts/Route6
;@ def Route6_Script()
;@ Route 6's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route6_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute6CurScript = ExecuteCurMapScriptInTable(wRoute6CurScript, Route6TrainerHeaders, Route6_ScriptPointers)
	ld hl, Route6TrainerHeaders
	ld de, Route6_ScriptPointers
	ld a, [wRoute6CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute6CurScript], a
	ret

;@ path: scripts/Route6
Route6_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_ROUTE6_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROUTE6_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROUTE6_END_BATTLE EQU 2

;@ path: scripts/Route6
Route6_TextPointers:
	dw Route6CooltrainerM1Text
DEF TEXT_ROUTE6_COOLTRAINER_M1 EQU 1
	dw Route6CooltrainerF1Text
DEF TEXT_ROUTE6_COOLTRAINER_F1 EQU 2
	dw Route6Youngster1Text
DEF TEXT_ROUTE6_YOUNGSTER1 EQU 3
	dw Route6CooltrainerM2Text
DEF TEXT_ROUTE6_COOLTRAINER_M2 EQU 4
	dw Route6CooltrainerF2Text
DEF TEXT_ROUTE6_COOLTRAINER_F2 EQU 5
