;@ path: scripts/Route6
Route6TrainerHeaders:
;@ path: scripts/Route6
Route6TrainerHeader0:
	db $1
	db 0 << 4
	dw wEventFlags + (EVENT_BEAT_ROUTE_6_TRAINER_0 - $1) / 8
	dw Route6CooltrainerM1BattleText, Route6CooltrainerAfterBattleText, Route6CooltrainerM1EndBattleText, Route6CooltrainerM1EndBattleText
;@ path: scripts/Route6
Route6TrainerHeader1:
	db $2
	db 0 << 4
	dw wEventFlags + (EVENT_BEAT_ROUTE_6_TRAINER_1 - $2) / 8
