;@ path: scripts/Route6
;@ def Route6CooltrainerM1Text() -> hl
;@ Cooltrainer M1, a trainer in Route 6: the trainer talk and battle.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route6CooltrainerM1Text:
	db TX_START_ASM
;> TalkToTrainer(Route6TrainerHeader0)
;> return TextScriptEnd()
	ld hl, Route6TrainerHeader0
	call TalkToTrainer
	jp TextScriptEnd

;@ path: scripts/Route6
