;@ path: scripts/Route8
;@ def Route8_Script()
;@ Route 8's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route8_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute8CurScript = ExecuteCurMapScriptInTable(wRoute8CurScript, Route8TrainerHeaders, Route8_ScriptPointers)
	ld hl, Route8TrainerHeaders
	ld de, Route8_ScriptPointers
	ld a, [wRoute8CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute8CurScript], a
	ret

;@ path: scripts/Route8
Route8_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_ROUTE8_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROUTE8_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROUTE8_END_BATTLE EQU 2

;@ path: scripts/Route8
Route8_TextPointers:
	dw Route8SuperNerd1Text
DEF TEXT_ROUTE8_SUPER_NERD1 EQU 1
	dw Route8Gambler1Text
DEF TEXT_ROUTE8_GAMBLER1 EQU 2
	dw Route8SuperNerd2Text
DEF TEXT_ROUTE8_SUPER_NERD2 EQU 3
	dw Route8CooltrainerF1Text
DEF TEXT_ROUTE8_COOLTRAINER_F1 EQU 4
	dw Route8SuperNerd3Text
DEF TEXT_ROUTE8_SUPER_NERD3 EQU 5
	dw Route8CooltrainerF2Text
DEF TEXT_ROUTE8_COOLTRAINER_F2 EQU 6
	dw Route8CooltrainerF3Text
DEF TEXT_ROUTE8_COOLTRAINER_F3 EQU 7
	dw Route8Gambler2Text
DEF TEXT_ROUTE8_GAMBLER2 EQU 8
	dw Route8CooltrainerF4Text
DEF TEXT_ROUTE8_COOLTRAINER_F4 EQU 9
	dw Route8UndergroundSignText
DEF TEXT_ROUTE8_UNDERGROUND_SIGN EQU $A

;@ path: scripts/Route8
Route8TrainerHeaders:
;@ path: scripts/Route8
Route8TrainerHeader0:
	db $1
	db 4 << 4
	dw wEventFlags + (EVENT_BEAT_ROUTE_8_TRAINER_0 - $1) / 8
	dw Route8SuperNerd1BattleText, Route8SuperNerd1AfterBattleText, Route8SuperNerd1EndBattleText, Route8SuperNerd1EndBattleText
