;@ def Route11_Script()
;@ Route 11's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route11_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute11CurScript = ExecuteCurMapScriptInTable(wRoute11CurScript, Route11TrainerHeaders, Route11_ScriptPointers)
	ld hl, Route11TrainerHeaders
	ld de, Route11_ScriptPointers
	ld a, [wRoute11CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute11CurScript], a
	ret

;@ path: scripts/Route11
