DEF TEXT_ROUTE11_GAMBLER2 EQU 2
	dw Route11Youngster1Text
DEF TEXT_ROUTE11_YOUNGSTER1 EQU 3
	dw Route11SuperNerd1Text
DEF TEXT_ROUTE11_SUPER_NERD1 EQU 4
	dw Route11Youngster2Text
DEF TEXT_ROUTE11_YOUNGSTER2 EQU 5
	dw Route11Gambler3Text
