	dw Route11Youngster3Text
DEF TEXT_ROUTE11_YOUNGSTER3 EQU 8
	dw Route11SuperNerd2Text
DEF TEXT_ROUTE11_SUPER_NERD2 EQU 9
	dw Route11Youngster4Text
