;@ def Route12_Script()
;@ Route 12's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route12_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute12CurScript = ExecuteCurMapScriptInTable(wRoute12CurScript, Route12TrainerHeaders, Route12_ScriptPointers)
	ld hl, Route12TrainerHeaders
	ld de, Route12_ScriptPointers
	ld a, [wRoute12CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute12CurScript], a
	ret

;@ path: scripts/Route12
;@ def Route12ResetScripts()
;@ Back to the default step (after a lost battle), with the controls given back.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route12ResetScripts:
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wRoute12CurScript = SCRIPT_ROUTE12_DEFAULT
	ld [wRoute12CurScript], a
;> wCurMapScript = SCRIPT_ROUTE12_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/Route12
Route12_ScriptPointers:
	dw Route12DefaultScript
DEF SCRIPT_ROUTE12_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROUTE12_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROUTE12_END_BATTLE EQU 2
	dw Route12SnorlaxPostBattleScript
DEF SCRIPT_ROUTE12_SNORLAX_POST_BATTLE EQU 3

;@ path: scripts/Route12
;@ def Route12DefaultScript()
;@ Once the Poké Flute has woken the Snorlax on Route 12 (and it is not beaten yet): it attacks - a level 30
;@ Snorlax battle - and disappears from the map; otherwise the trainers watch for the player.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route12DefaultScript:
;> if event(EVENT_BEAT_ROUTE12_SNORLAX):
;>     return CheckFightingMapTrainers()
	ld hl, wEventFlags + $91
	bit (EVENT_BEAT_ROUTE12_SNORLAX) % 8, [hl]
	jp nz, CheckFightingMapTrainers
;> fight = event(EVENT_FIGHT_ROUTE12_SNORLAX)
	bit (EVENT_FIGHT_ROUTE12_SNORLAX) % 8, [hl]
;> reset_event(EVENT_FIGHT_ROUTE12_SNORLAX)
	res (EVENT_FIGHT_ROUTE12_SNORLAX) % 8, [hl]
;> if not fight:
;>     return CheckFightingMapTrainers()
	jp z, CheckFightingMapTrainers
;> hTextID = TEXT_ROUTE12_SNORLAX_WOKE_UP
	ld a, TEXT_ROUTE12_SNORLAX_WOKE_UP
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wCurOpponent = SNORLAX
	ld a, SNORLAX
	ld [wCurOpponent], a
;> wCurEnemyLevel = 30
	ld a, 30
	ld [wCurEnemyLevel], a
;> wToggleableObjectIndex = TOGGLE_ROUTE_12_SNORLAX
	ld a, TOGGLE_ROUTE_12_SNORLAX
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wRoute12CurScript = SCRIPT_ROUTE12_SNORLAX_POST_BATTLE
	ld a, SCRIPT_ROUTE12_SNORLAX_POST_BATTLE
	ld [wRoute12CurScript], a
;> wCurMapScript = SCRIPT_ROUTE12_SNORLAX_POST_BATTLE
	ld [wCurMapScript], a
	ret

;@ path: scripts/Route12
;@ def Route12SnorlaxPostBattleScript()
;@ After the Snorlax battle: lost, start over; otherwise (unless it was caught) "Snorlax calmed down and went
;@ home", and it is gone for good.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route12SnorlaxPostBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return Route12ResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jr z, Route12ResetScripts
;> UpdateSprites()
	call UpdateSprites
;> if wBattleResult != 2:                        # not caught
	ld a, [wBattleResult]
	cp $2
	jr z, .caught_snorlax
;>     hTextID = TEXT_ROUTE12_SNORLAX_CALMED_DOWN
	ld a, TEXT_ROUTE12_SNORLAX_CALMED_DOWN
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
.caught_snorlax
;> set_event(EVENT_BEAT_ROUTE12_SNORLAX)
	ld hl, wEventFlags + $91
	set (EVENT_BEAT_ROUTE12_SNORLAX) % 8, [hl]
;> Delay3()
	call Delay3
;> wRoute12CurScript = SCRIPT_ROUTE12_DEFAULT
	ld a, SCRIPT_ROUTE12_DEFAULT
	ld [wRoute12CurScript], a
;> wCurMapScript = SCRIPT_ROUTE12_DEFAULT
	ld [wCurMapScript], a
	ret

