;@ def Route15_Script()
;@ Route 15's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route15_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute15CurScript = ExecuteCurMapScriptInTable(wRoute15CurScript, Route15TrainerHeaders, Route15_ScriptPointers)
	ld hl, Route15TrainerHeaders
	ld de, Route15_ScriptPointers
	ld a, [wRoute15CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute15CurScript], a
	ret

