;@ path: scripts/Route16
;@ def Route16_Script()
;@ Route 16's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route16_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wRoute16CurScript = ExecuteCurMapScriptInTable(wRoute16CurScript, Route16TrainerHeaders, Route16_ScriptPointers)
	ld hl, Route16TrainerHeaders
	ld de, Route16_ScriptPointers
	ld a, [wRoute16CurScript]
	call ExecuteCurMapScriptInTable
	ld [wRoute16CurScript], a
	ret

;@ path: scripts/Route16
;@ def Route16ResetScripts()
;@ Back to the default step (after a lost battle), with the controls given back.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route16ResetScripts:
;> wJoyIgnore = 0
	xor a ; SCRIPT_ROUTE16_DEFAULT
	ld [wJoyIgnore], a
;> wRoute16CurScript = SCRIPT_ROUTE16_DEFAULT
	ld [wRoute16CurScript], a
;> wCurMapScript = SCRIPT_ROUTE16_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/Route16
Route16_ScriptPointers:
	dw Route16DefaultScript
DEF SCRIPT_ROUTE16_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_ROUTE16_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_ROUTE16_END_BATTLE EQU 2
	dw Route16SnorlaxPostBattleScript
DEF SCRIPT_ROUTE16_SNORLAX_POST_BATTLE EQU 3

;@ path: scripts/Route16
;@ def Route16DefaultScript()
;@ Once the Poké Flute has woken the Snorlax on Route 16 (and it is not beaten yet): it attacks - a level 30
;@ Snorlax battle - and disappears from the map; otherwise the trainers watch for the player.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route16DefaultScript:
;> if event(EVENT_BEAT_ROUTE16_SNORLAX):
;>     return CheckFightingMapTrainers()
	ld hl, wEventFlags + $99
	bit (EVENT_BEAT_ROUTE16_SNORLAX) % 8, [hl]
	jp nz, CheckFightingMapTrainers
;> fight = event(EVENT_FIGHT_ROUTE16_SNORLAX)
	bit (EVENT_FIGHT_ROUTE16_SNORLAX) % 8, [hl]
;> reset_event(EVENT_FIGHT_ROUTE16_SNORLAX)
	res (EVENT_FIGHT_ROUTE16_SNORLAX) % 8, [hl]
;> if not fight:
;>     return CheckFightingMapTrainers()
	jp z, CheckFightingMapTrainers
;> hTextID = TEXT_ROUTE16_SNORLAX_WOKE_UP
	ld a, TEXT_ROUTE16_SNORLAX_WOKE_UP
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wCurOpponent = SNORLAX
	ld a, SNORLAX
	ld [wCurOpponent], a
;> wCurEnemyLevel = 30
	ld a, 30
	ld [wCurEnemyLevel], a
;> wToggleableObjectIndex = TOGGLE_ROUTE_16_SNORLAX
	ld a, TOGGLE_ROUTE_16_SNORLAX
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> UpdateSprites()
	call UpdateSprites
;> wRoute16CurScript = SCRIPT_ROUTE16_SNORLAX_POST_BATTLE
	ld a, SCRIPT_ROUTE16_SNORLAX_POST_BATTLE
	ld [wRoute16CurScript], a
;> wCurMapScript = SCRIPT_ROUTE16_SNORLAX_POST_BATTLE
	ld [wCurMapScript], a
	ret

;@ path: scripts/Route16
;@ def Route16SnorlaxPostBattleScript()
;@ After the Snorlax battle: lost, start over; otherwise (unless it was caught) "Snorlax returned to the
;@ mountains", and it is gone for good.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
Route16SnorlaxPostBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return Route16ResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, Route16ResetScripts
;> UpdateSprites()
	call UpdateSprites
;> if wBattleResult != 2:                        # not caught
	ld a, [wBattleResult]
	cp $2
	jr z, .caught
;>     hTextID = TEXT_ROUTE16_SNORLAX_RETURNED_TO_MOUNTAINS
	ld a, TEXT_ROUTE16_SNORLAX_RETURNED_TO_MOUNTAINS
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
.caught
;> set_event(EVENT_BEAT_ROUTE16_SNORLAX)
	ld hl, wEventFlags + $99
	set (EVENT_BEAT_ROUTE16_SNORLAX) % 8, [hl]
;> Delay3()
	call Delay3
;> wRoute16CurScript = SCRIPT_ROUTE16_DEFAULT
	ld a, SCRIPT_ROUTE16_DEFAULT
	ld [wRoute16CurScript], a
;> wCurMapScript = SCRIPT_ROUTE16_DEFAULT
	ld [wCurMapScript], a
	ret

