DEF TEXT_ROUTE16_CYCLING_ROAD_SIGN EQU 8
	dw Route16SignText
DEF TEXT_ROUTE16_SIGN EQU 9
	dw Route16SnorlaxWokeUpText
DEF TEXT_ROUTE16_SNORLAX_WOKE_UP EQU $A
	dw Route16SnorlaxReturnedToMountainsText
DEF TEXT_ROUTE16_SNORLAX_RETURNED_TO_MOUNTAINS EQU $B

