;@ Zero flag if the player has nothing to do with bikes yet: no Bike Voucher received, and neither a Bicycle
;@ nor the voucher in the bag.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
PokemonFanClub_CheckBikeInBag:
; check if any bike paraphernalia in bag
;> if event(EVENT_GOT_BIKE_VOUCHER):
;>     return False
	ld a, [wEventFlags + $2A]
	bit (EVENT_GOT_BIKE_VOUCHER) % 8, a
	ret nz
;> if not IsItemInBag(BICYCLE):
;>     return False
	ld b, BICYCLE
	call IsItemInBag
	ret nz
;> return IsItemInBag(BIKE_VOUCHER)
	ld b, BIKE_VOUCHER
	jp IsItemInBag

