;@ path: scripts/PokemonFanClub
;@ def PokemonFanClubChairmanText() -> hl
;@ The Fan Club chairman: offers to tell the story of his Rapidash; listening earns the Bike Voucher (if the
;@ bag has room). Once the player has the voucher or a Bicycle, he has nothing left to give.
;@ test: skip a text script: the code after text_asm is run by the text engine
PokemonFanClubChairmanText:
	db TX_START_ASM
;> if not PokemonFanClub_CheckBikeInBag():
	call PokemonFanClub_CheckBikeInBag
	jr nz, .nothingleft
;>@e1     PrintText(PokemonFanClubChairmanText.FinalText)
;>@e2     return TextScriptEnd()

;> PrintText(PokemonFanClubChairmanText.IntroText)
	ld hl, .IntroText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .nothanks

;>@early     PrintText(PokemonFanClubChairmanText.NoStoryText)
;> else:
;>     PrintText(PokemonFanClubChairmanText.StoryText)
	; tell the story
	ld hl, .StoryText
	call PrintText
;>     if GiveItem(BIKE_VOUCHER, 1):
	ld bc, ((BIKE_VOUCHER) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         PrintText(PokemonFanClubChairmanText.BikeVoucherText)
	ld hl, .BikeVoucherText
	call PrintText
;>         set_event(EVENT_GOT_BIKE_VOUCHER)
	ld hl, wEventFlags + $2A
	set (EVENT_GOT_BIKE_VOUCHER) % 8, [hl]
	jr .done
.bag_full
;>     else:
;>         PrintText(PokemonFanClubChairmanText.BagFullText)
	ld hl, .BagFullText
	call PrintText
	jr .done
.nothanks
;=@early
	ld hl, .NoStoryText
	call PrintText
	jr .done
.nothingleft
;=@e1
	ld hl, .FinalText
	call PrintText
;=@e2
.done
;> return TextScriptEnd()
	jp TextScriptEnd

