SilphCo2F_h::
	db FACILITY
	db $9, $F
	dw SilphCo2F_Blocks
	dw SilphCo2F_TextPointers
	dw SilphCo2F_Script
	db 0
	dw SilphCo2F_Object
;@ path: scripts/SilphCo2F
;@ def SilphCo2F_Script()
;@ Silph Co. 2F's map script: first the map callback (SilphCo2FGateCallbackScript), then run the current step of the map's script (its trainers).
;@ test: skip runs SilphCo2FGateCallbackScript, whose data sits under a local label
SilphCo2F_Script:
;> SilphCo2FGateCallbackScript()
	call SilphCo2FGateCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSilphCo2FCurScript = ExecuteCurMapScriptInTable(wSilphCo2FCurScript, SilphCo2TrainerHeaders, SilphCo2F_ScriptPointers)
	ld hl, SilphCo2TrainerHeaders
	ld de, SilphCo2F_ScriptPointers
	ld a, [wSilphCo2FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSilphCo2FCurScript], a
	ret

;@ path: scripts/SilphCo2F
;@ def SilphCo2FGateCallbackScript()
;@ On entering the floor: if a card-key door here was just opened, note it, then draw each of the two doors
;@ still locked (block $54) into the map.
;@ test: skip the door list sits under a local label, which the pseudo-code can only name
SilphCo2FGateCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> SilphCo2F_SetCardKeyDoorYScript(SilphCo2FGateCallbackScript.GateCoordinates)
	ld hl, .GateCoordinates
	call SilphCo2F_SetCardKeyDoorYScript
;> SilphCo2F_UnlockedDoorEventScript()
	call SilphCo2F_UnlockedDoorEventScript
;> if not event(EVENT_SILPH_CO_2_UNLOCKED_DOOR1):     # door 1 still locked
	ld a, [wEventFlags + $DF]
	bit (EVENT_SILPH_CO_2_UNLOCKED_DOOR1) % 8, a
	jr nz, .unlock_door1
;>     wNewTileBlockID = 0x54
	push af
	ld a, $54
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=2 << 8 | 2)        # at row 2, column 2
	ld bc, ((2) & $ff) << 8 + ((2) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	pop af
.unlock_door1
;> if event(EVENT_SILPH_CO_2_UNLOCKED_DOOR2):
;>     return
	bit (EVENT_SILPH_CO_2_UNLOCKED_DOOR2) % 8, a
	ret nz
;> wNewTileBlockID = 0x54
	ld a, $54
	ld [wNewTileBlockID], a
;> return predef(ReplaceTileBlock, bc=5 << 8 | 2)
	ld bc, ((5) & $ff) << 8 + ((2) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

.GateCoordinates:
	db 2, 2
	db 5, 2
	db -1 ; end

;@ path: scripts/SilphCo2F
;@ def SilphCo2F_SetCardKeyDoorYScript(doors: hl)
;@ Look up the door the card key just opened (wCardKeyDoorY/X) in the floor's door list: hUnlockedSilphCoDoors
;@ becomes its number (1, 2...) and the opened door is forgotten; 0 if it is not one of them.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
SilphCo2F_SetCardKeyDoorYScript:
;> y = wCardKeyDoorY
	push hl
	ld hl, wCardKeyDoorY
	ld a, [hli]
	ld b, a
;> x = wCardKeyDoorX
	ld a, [hl]
	ld c, a
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
;> while mem[doors] != 0xFF:
	pop hl
.loop_check_doors
	ld a, [hli]
	cp $ff
	jr z, .exit_loop
;>     hUnlockedSilphCoDoors += 1
	push hl
	ld hl, hUnlockedSilphCoDoors
	inc [hl]
	pop hl
;>@match     if mem[doors] == y and mem[doors + 1] == x:
	cp b
	jr z, .check_y_coord
;>@clear         wCardKeyDoorY = wCardKeyDoorX = 0
;>@ret         return
;>     doors += 2
	inc hl
	jr .loop_check_doors
.check_y_coord
;=@match
	ld a, [hli]
	cp c
	jr nz, .loop_check_doors
;=@clear
	ld hl, wCardKeyDoorY
	xor a
	ld [hli], a
	ld [hl], a
;=@ret
	ret
.exit_loop
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
	ret

;@ path: scripts/SilphCo2F
;@ def SilphCo2F_UnlockedDoorEventScript()
;@ Note the door the card key just opened (door 1 or 2 of this floor) as an event.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
SilphCo2F_UnlockedDoorEventScript:
;> if hUnlockedSilphCoDoors == 0:      # (hl: the byte holding both door flags)
;>     return
	ld hl, wEventFlags + $DF
	ldh a, [hUnlockedSilphCoDoors]
	and a
	ret z
;> if hUnlockedSilphCoDoors == 1:
	cp $1
	jr nz, .unlock_door1
;>     set_event(EVENT_SILPH_CO_2_UNLOCKED_DOOR1)
	set (EVENT_SILPH_CO_2_UNLOCKED_DOOR1) % 8, [hl]
	ret
.unlock_door1
;> else:
;>     set_event(EVENT_SILPH_CO_2_UNLOCKED_DOOR2)
	set (EVENT_SILPH_CO_2_UNLOCKED_DOOR2) % 8, [hl]
	ret

