;@ path: scripts/SilphCo2F
SilphCo2TrainerHeader0:
	db $2
	db 3 << 4
	dw wEventFlags + (EVENT_BEAT_SILPH_CO_2F_TRAINER_0 - $2) / 8
	dw SilphCo2FScientist1BattleText, SilphCo2FScientist1AfterBattleText, SilphCo2FScientist1EndBattleText, SilphCo2FScientist1EndBattleText
;@ path: scripts/SilphCo2F
SilphCo2TrainerHeader1:
	db $3
	db 4 << 4
	dw wEventFlags + (EVENT_BEAT_SILPH_CO_2F_TRAINER_1 - $3) / 8
	dw SilphCo2FScientist2BattleText, SilphCo2FScientist2AfterBattleText, SilphCo2FScientist2EndBattleText, SilphCo2FScientist2EndBattleText
;@ path: scripts/SilphCo2F
SilphCo2TrainerHeader2:
