;@ path: scripts/SilphCo2F
;@ def SilphCo2FSilphWorkerFText() -> hl
;@ The Silph worker on 2F: gives TM36 (SELFDESTRUCT) once, if the bag has room, and explains it afterwards.
;@ test: skip a text script: the code after text_asm is run by the text engine
SilphCo2FSilphWorkerFText:
	db TX_START_ASM
;> if event(EVENT_GOT_TM36):
;>     text = SilphCo2FSilphWorkerFText.TM36ExplanationText
	ld a, [wEventFlags + $DF]
	bit (EVENT_GOT_TM36) % 8, a
	jr nz, .already_have_tm
;> else:
;>     PrintText(SilphCo2FSilphWorkerFText.PleaseTakeThisText)
	ld hl, .PleaseTakeThisText
	call PrintText
;>     if GiveItem(TM_SELFDESTRUCT, 1):
	ld bc, ((TM_SELFDESTRUCT) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	ld hl, .TM36NoRoomText
	jr nc, .print_text
;>         set_event(EVENT_GOT_TM36)
	ld hl, wEventFlags + $DF
	set (EVENT_GOT_TM36) % 8, [hl]
;>         text = SilphCo2FSilphWorkerFText.ReceivedTM36Text
;>     else:
;>         text = SilphCo2FSilphWorkerFText.TM36NoRoomText
	ld hl, .ReceivedTM36Text
	jr .print_text
.already_have_tm
	ld hl, .TM36ExplanationText
.print_text
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.PleaseTakeThisText:
	db TX_FAR
	dw SilphCo2FSilphWorkerFPleaseTakeThisText
	db BANK(SilphCo2FSilphWorkerFPleaseTakeThisText)
	db TX_END

.ReceivedTM36Text:
	db TX_FAR
	dw _SilphCo2FSilphWorkerFReceivedTM36Text
	db BANK(_SilphCo2FSilphWorkerFReceivedTM36Text)
	db TX_SOUND_GET_ITEM_1
	db TX_END

.TM36ExplanationText:
	db TX_FAR
	dw _SilphCo2FSilphWorkerFTM36ExplanationText
	db BANK(_SilphCo2FSilphWorkerFTM36ExplanationText)
	db TX_END

.TM36NoRoomText:
	db TX_FAR
	dw _SilphCo2FSilphWorkerFTM36NoRoomText
	db BANK(_SilphCo2FSilphWorkerFTM36NoRoomText)
	db TX_END

