;@ path: scripts/SilphCo3F
;@ def SilphCo3F_Script()
;@ Silph Co. 3F's map script: first the map callback (SilphCo3FGateCallbackScript), then run the current step of the map's script (its trainers).
;@ test: skip runs SilphCo3FGateCallbackScript, whose data sits under a local label
SilphCo3F_Script:
;> SilphCo3FGateCallbackScript()
	call SilphCo3FGateCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSilphCo3FCurScript = ExecuteCurMapScriptInTable(wSilphCo3FCurScript, SilphCo3TrainerHeaders, SilphCo3F_ScriptPointers)
	ld hl, SilphCo3TrainerHeaders
	ld de, SilphCo3F_ScriptPointers
	ld a, [wSilphCo3FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSilphCo3FCurScript], a
	ret

;@ path: scripts/SilphCo3F
;@ def SilphCo3FGateCallbackScript()
;@ On entering the floor: if a card-key door here was just opened, note it, then draw each of the two doors
;@ still locked (block $5F) into the map.
;@ test: skip the door list sits under a local label, which the pseudo-code can only name
SilphCo3FGateCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> SilphCo2F_SetCardKeyDoorYScript(SilphCo3FGateCallbackScript.GateCoordinates)
	ld hl, .GateCoordinates
	call SilphCo2F_SetCardKeyDoorYScript
;> SilphCo3F_UnlockedDoorEventScript()
	call SilphCo3F_UnlockedDoorEventScript
;> if not event(EVENT_SILPH_CO_3_UNLOCKED_DOOR1):     # door 1 still locked
	ld a, [wEventFlags + $E1]
	bit (EVENT_SILPH_CO_3_UNLOCKED_DOOR1) % 8, a
	jr nz, .unlock_door1
;>     wNewTileBlockID = 0x5F
	push af
	ld a, $5f
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=4 << 8 | 4)        # at row 4, column 4
	ld bc, ((4) & $ff) << 8 + ((4) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	pop af
.unlock_door1
;> if event(EVENT_SILPH_CO_3_UNLOCKED_DOOR2):
;>     return
	bit (EVENT_SILPH_CO_3_UNLOCKED_DOOR2) % 8, a
	ret nz
;> wNewTileBlockID = 0x5F
	ld a, $5f
	ld [wNewTileBlockID], a
;> return predef(ReplaceTileBlock, bc=4 << 8 | 8)
	ld bc, ((4) & $ff) << 8 + ((8) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

.GateCoordinates:
	db 4, 4
	db 4, 8
	db -1 ; end

;@ path: scripts/SilphCo3F
;@ def SilphCo3F_UnlockedDoorEventScript()
;@ Note the door the card key just opened (door 1 or 2 of this floor) as an event.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
SilphCo3F_UnlockedDoorEventScript:
;> if hUnlockedSilphCoDoors == 0:      # (hl: the byte holding both door flags)
;>     return
	ld hl, wEventFlags + $E1
	ldh a, [hUnlockedSilphCoDoors]
	and a
	ret z
;> if hUnlockedSilphCoDoors == 1:
	cp $1
	jr nz, .unlock_door1
;>     set_event(EVENT_SILPH_CO_3_UNLOCKED_DOOR1)
	set (EVENT_SILPH_CO_3_UNLOCKED_DOOR1) % 8, [hl]
	ret
.unlock_door1
;> else:
;>     set_event(EVENT_SILPH_CO_3_UNLOCKED_DOOR2)
	set (EVENT_SILPH_CO_3_UNLOCKED_DOOR2) % 8, [hl]
	ret

