;@ def SilphCo3FSilphWorkerMText() -> hl
;@ The Silph worker on 3F: what should I do? - after Giovanni is beaten, you saved us.
;@ test: skip a text script: the code after text_asm is run by the text engine
SilphCo3FSilphWorkerMText:
	db TX_START_ASM
;> if event(EVENT_BEAT_SILPH_CO_GIOVANNI):
;>     text = SilphCo3FSilphWorkerMText.YouSavedUsText
	ld a, [wEventFlags + $F1]
	bit (EVENT_BEAT_SILPH_CO_GIOVANNI) % 8, a
	ld hl, .YouSavedUsText
	jr nz, .beat_giovanni
;> else:
;>     text = SilphCo3FSilphWorkerMText.WhatShouldIDoText
	ld hl, .WhatShouldIDoText
.beat_giovanni
;> PrintText(text)
;> return TextScriptEnd()
	call PrintText
	jp TextScriptEnd

.WhatShouldIDoText:
