	dw (wOverworldMap + 7 + (SILPH_CO_3F_WIDTH) + ((SILPH_CO_3F_WIDTH) + 6) * (($B) >> 1) + (($17) >> 1))
	db $B, $17
	dw (wOverworldMap + 7 + (SILPH_CO_3F_WIDTH) + ((SILPH_CO_3F_WIDTH) + 6) * ((3) >> 1) + ((3) >> 1))
	db 3, 3
	dw (wOverworldMap + 7 + (SILPH_CO_3F_WIDTH) + ((SILPH_CO_3F_WIDTH) + 6) * (($F) >> 1) + ((3) >> 1))
	db $F, 3
	dw (wOverworldMap + 7 + (SILPH_CO_3F_WIDTH) + ((SILPH_CO_3F_WIDTH) + 6) * ((3) >> 1) + (($1B) >> 1))
	db 3, $1B
	dw (wOverworldMap + 7 + (SILPH_CO_3F_WIDTH) + ((SILPH_CO_3F_WIDTH) + 6) * (($B) >> 1) + ((3) >> 1))
	db $B, 3
	dw (wOverworldMap + 7 + (SILPH_CO_3F_WIDTH) + ((SILPH_CO_3F_WIDTH) + 6) * (($B) >> 1) + (($B) >> 1))
	db $B, $B
	dw (wOverworldMap + 7 + (SILPH_CO_3F_WIDTH) + ((SILPH_CO_3F_WIDTH) + 6) * (($F) >> 1) + (($1B) >> 1))
	db $F, $1B
