SilphCo10F_h::
	db FACILITY
	db $9, $8
	dw SilphCo10F_Blocks
	dw SilphCo10F_TextPointers
	dw SilphCo10F_Script
	db 0
	dw SilphCo10F_Object
;@ path: scripts/SilphCo10F
;@ def SilphCo10F_Script()
;@ Silph Co. 10F's map script: first the map callback (SilphCo10FGateCallbackScript), then run the current step of the map's script (its trainers).
;@ test: skip runs SilphCo10FGateCallbackScript, whose data sits under a local label
SilphCo10F_Script:
;> SilphCo10FGateCallbackScript()
	call SilphCo10FGateCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSilphCo10FCurScript = ExecuteCurMapScriptInTable(wSilphCo10FCurScript, SilphCo10TrainerHeaders, SilphCo10F_ScriptPointers)
	ld hl, SilphCo10TrainerHeaders
	ld de, SilphCo10F_ScriptPointers
	ld a, [wSilphCo10FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSilphCo10FCurScript], a
	ret

;@ path: scripts/SilphCo10F
;@ def SilphCo10FGateCallbackScript()
;@ On entering the floor: if the card-key door here was just opened, note it; while it is locked, draw it
;@ (block $54) into the map.
;@ test: skip the door list sits under a local label, which the pseudo-code can only name
SilphCo10FGateCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> SilphCo2F_SetCardKeyDoorYScript(SilphCo10FGateCallbackScript.GateCoordinates)
	ld hl, .GateCoordinates
	call SilphCo2F_SetCardKeyDoorYScript
;> SilphCo10F_SetUnlockedSilphCoDoorsScript()
	call SilphCo10F_SetUnlockedSilphCoDoorsScript
;> if not event(EVENT_SILPH_CO_10_UNLOCKED_DOOR):
	ld a, [wEventFlags + $EF]
	bit (EVENT_SILPH_CO_10_UNLOCKED_DOOR) % 8, a
	ret nz
;>     wNewTileBlockID = 0x54
	ld a, $54
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=4 << 8 | 5)
	ld bc, ((4) & $ff) << 8 + ((5) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

.GateCoordinates:
	db 4, 5
	db -1 ; end

;@ path: scripts/SilphCo10F
;@ def SilphCo10F_SetUnlockedSilphCoDoorsScript()
;@ If the card key just opened this floor's door, note it as an event.
;@ test: hLoadedROMBank = 0x16    # the bank this code runs in
SilphCo10F_SetUnlockedSilphCoDoorsScript:
;> if hUnlockedSilphCoDoors:
;>     set_event(EVENT_SILPH_CO_10_UNLOCKED_DOOR)
	ldh a, [hUnlockedSilphCoDoors]
	and a
	ret z
	ld hl, wEventFlags + $EF
	set (EVENT_SILPH_CO_10_UNLOCKED_DOOR) % 8, [hl]
	ret

