;> return TextScriptEnd()
	ld hl, SilphCo10TrainerHeader1
	call TalkToTrainer
	jp TextScriptEnd

;@ path: scripts/SilphCo10F
;@ def SilphCo10FSilphWorkerFText() -> hl
;@ The Silph worker on 10F: I'm scared - after Giovanni is beaten, keep quiet about my crying.
;@ test: skip a text script: the code after text_asm is run by the text engine
SilphCo10FSilphWorkerFText:
	db TX_START_ASM
;> if event(EVENT_BEAT_SILPH_CO_GIOVANNI):
;>     text = SilphCo10FSilphWorkerFText.QuietAboutMyCryingText
	ld a, [wEventFlags + $F1]
	bit (EVENT_BEAT_SILPH_CO_GIOVANNI) % 8, a
	ld hl, .QuietAboutMyCryingText
	jr nz, .beat_giovanni
;> else:
;>     text = SilphCo10FSilphWorkerFText.ImScaredText
	ld hl, .ImScaredText
.beat_giovanni
;> PrintText(text)
;> return TextScriptEnd()
	call PrintText
	jp TextScriptEnd

.ImScaredText:
	db TX_FAR
	dw _SilphCo10FSilphWorkerFImScaredText
	db BANK(_SilphCo10FSilphWorkerFImScaredText)
	db TX_END

.QuietAboutMyCryingText:
	db TX_FAR
	dw _SilphCo10FSilphWorkerFQuietAboutMyCryingText
	db BANK(_SilphCo10FSilphWorkerFQuietAboutMyCryingText)
	db TX_END

