	dw (wOverworldMap + 7 + (SILPH_CO_10F_WIDTH) + ((SILPH_CO_10F_WIDTH) + 6) * ((0) >> 1) + ((8) >> 1))
	db 0, 8
	dw (wOverworldMap + 7 + (SILPH_CO_10F_WIDTH) + ((SILPH_CO_10F_WIDTH) + 6) * ((0) >> 1) + (($A) >> 1))
	db 0, $A
	dw (wOverworldMap + 7 + (SILPH_CO_10F_WIDTH) + ((SILPH_CO_10F_WIDTH) + 6) * ((0) >> 1) + (($C) >> 1))
	db 0, $C
