	db $3c, $3d, $3d, $3d, $24, $7d, $7c, $3e, $44, $0e, $0e, $0e, $0e, $0e, $0e, $46
	db $44, $0e, $0e, $5a, $63, $0e, $67, $42, $44, $0e, $0e, $46, $0d, $0e, $2f, $46
	db $40, $2a, $2b, $42, $63, $0e, $67, $42, $44, $35, $18, $46, $2f, $0e, $7b, $46
	db $44, $1e, $35, $46, $0e, $7b, $37, $46, $44, $0a, $1e, $46, $0e, $37, $2f, $46
