LancesRoom_h::
	db DOJO
	db $D, $D
	dw LancesRoom_Blocks
	dw LancesRoom_TextPointers
	dw LancesRoom_Script
	db 0
	dw LancesRoom_Object
;@ path: scripts/LancesRoom
;@ def LancesRoom_Script()
;@ Lance's room map script: open or close the entrance, then run the current step of the room's script.
LancesRoom_Script:
;> LanceShowOrHideEntranceBlocks()
	call LanceShowOrHideEntranceBlocks
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wLancesRoomCurScript = ExecuteCurMapScriptInTable(wLancesRoomCurScript, LancesRoomTrainerHeaders, LancesRoom_ScriptPointers)
	ld hl, LancesRoomTrainerHeaders
	ld de, LancesRoom_ScriptPointers
	ld a, [wLancesRoomCurScript]
	call ExecuteCurMapScriptInTable
	ld [wLancesRoomCurScript], a
	ret

;@ path: scripts/LancesRoom
;@ def LanceShowOrHideEntranceBlocks()
;@ When the map has just loaded: draw the two blocks of the room's entrance as open stairs, or, once the
;@ player is inside (the door locked behind them), as a wall.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
LanceShowOrHideEntranceBlocks:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> if event(EVENT_LANCES_ROOM_LOCK_DOOR):
	ld a, [wEventFlags + $11F]
	bit (EVENT_LANCES_ROOM_LOCK_DOOR) % 8, a
	jr nz, .closeEntrance
	; open entrance
	ld a, $31
	ld b, $32
	jp .setEntranceBlocks
.closeEntrance
;>     left, right = 0x72, 0x73                # closed
	ld a, $72
	ld b, $73
;> else:
;>     left, right = 0x31, 0x32                # open
.setEntranceBlocks
;> wNewTileBlockID = left
; Replaces the tile blocks so the player can't leave.
	push bc
	ld [wNewTileBlockID], a
;> ReplaceTileBlock()                          # block row 6, column 2 (b, c through the predef)
	ld bc, ((6) & $ff) << 8 + ((2) & $ff)
	call .SetEntranceBlock
;> wNewTileBlockID = right
	pop bc
	ld a, b
	ld [wNewTileBlockID], a
;> ReplaceTileBlock()                          # block row 6, column 3
	ld bc, ((6) & $ff) << 8 + ((3) & $ff)
.SetEntranceBlock:
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/LancesRoom
;@ def ResetLanceScript()
;@ Back to the room's default step.
ResetLanceScript:
;> wLancesRoomCurScript = SCRIPT_LANCESROOM_DEFAULT
	xor a ; SCRIPT_LANCESROOM_DEFAULT
	ld [wLancesRoomCurScript], a
	ret

;@ path: scripts/LancesRoom
LancesRoom_ScriptPointers:
	dw LancesRoomDefaultScript
DEF SCRIPT_LANCESROOM_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_LANCESROOM_LANCE_START_BATTLE EQU 1
	dw LancesRoomLanceEndBattleScript
DEF SCRIPT_LANCESROOM_LANCE_END_BATTLE EQU 2
	dw LancesRoomPlayerIsMovingScript
DEF SCRIPT_LANCESROOM_PLAYER_IS_MOVING EQU 3
	dw LancesRoomNoopScript
DEF SCRIPT_LANCESROOM_NOOP EQU 4

;@ path: scripts/LancesRoom
;@ def LancesRoomNoopScript()
;@ The room's idle step: nothing happens.
LancesRoomNoopScript:
;> return
	ret

;@ path: scripts/LancesRoom
;@ def LancesRoomDefaultScript()
;@ Every step until Lance is beaten: next to Lance he speaks; on the entrance stairs the player is walked up
;@ the hallway; the first step past the entrance locks the door behind the player.
LancesRoomDefaultScript:
;> if event(EVENT_BEAT_LANCE):
	ld a, [wEventFlags + $11F]
	bit (EVENT_BEAT_LANCE) % 8, a
;>     return
	ret nz
;> if not ArePlayerCoordsInArray(LanceTriggerMovementCoords):
	ld hl, LanceTriggerMovementCoords
	call ArePlayerCoordsInArray
;>     return CheckFightingMapTrainers()
	jp nc, CheckFightingMapTrainers
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> if wCoordIndex < 3:                         # next to Lance
	ld a, [wCoordIndex]
	cp $3  ; Is player standing next to Lance's sprite?
	jr nc, .notStandingNextToLance
;>     hTextID = TEXT_LANCESROOM_LANCE
	ld a, TEXT_LANCESROOM_LANCE
	ldh [hTextID], a
;>     return DisplayTextID()
	jp DisplayTextID
;> if wCoordIndex == 5:                        # on the entrance stairs
;>     return WalkToLance()
.notStandingNextToLance
	cp $5  ; Is player standing on the entrance staircase?
	jr z, WalkToLance
;> locked = event(EVENT_LANCES_ROOM_LOCK_DOOR)
	ld hl, wEventFlags + $11F
	bit (EVENT_LANCES_ROOM_LOCK_DOOR) % 8, [hl]
;> set_event(EVENT_LANCES_ROOM_LOCK_DOOR)
	set (EVENT_LANCES_ROOM_LOCK_DOOR) % 8, [hl]
;> if locked:
;>     return
	ret nz
;> wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
;> PlaySound(SFX_GO_INSIDE)
	ld a, SFX_GO_INSIDE
	call PlaySound
;> return LanceShowOrHideEntranceBlocks()
	jp LanceShowOrHideEntranceBlocks

;@ path: scripts/LancesRoom
LanceTriggerMovementCoords:
	db 1, 5
	db 2, 6
	db 11, 5
	db 11, 6
	db 16, 24
	db -1 ; end

;@ path: scripts/LancesRoom
;@ def LancesRoomLanceEndBattleScript()
;@ After the battle with Lance: lost, start over; won, his words after the battle.
LancesRoomLanceEndBattleScript:
;> EndTrainerBattle()
	call EndTrainerBattle
;> if wIsInBattle == LOST_BATTLE:
;>     return ResetLanceScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, ResetLanceScript
;> hTextID = TEXT_LANCESROOM_LANCE
;> return DisplayTextID()
	ld a, TEXT_LANCESROOM_LANCE
	ldh [hTextID], a
	jp DisplayTextID

;@ path: scripts/LancesRoom
;@ def WalkToLance()
;@ Walk the player up the hallway to Lance by simulated button presses.
WalkToLance:
; Moves the player down the hallway to Lance's room.
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> count = DecodeRLEList(addr(wSimulatedJoypadStatesEnd), WalkToLance_RLEList)   # the steps, run-length coded
	ld hl, wSimulatedJoypadStatesEnd
	ld de, WalkToLance_RLEList
	call DecodeRLEList
;> wSimulatedJoypadStatesIndex = count - 1
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wLancesRoomCurScript = SCRIPT_LANCESROOM_PLAYER_IS_MOVING
;> wCurMapScript = SCRIPT_LANCESROOM_PLAYER_IS_MOVING
	ld a, SCRIPT_LANCESROOM_PLAYER_IS_MOVING
	ld [wLancesRoomCurScript], a
	ld [wCurMapScript], a
	ret

;@ path: scripts/LancesRoom
WalkToLance_RLEList:
	db PAD_UP, 12
	db PAD_LEFT, 12
	db PAD_DOWN, 7
	db PAD_LEFT, 6
	db -1 ; end

;@ path: scripts/LancesRoom
;@ def LancesRoomPlayerIsMovingScript()
;@ Wait until the walk is over, then give the controls back and return to the default step.
LancesRoomPlayerIsMovingScript:
;> if wSimulatedJoypadStatesIndex:
	ld a, [wSimulatedJoypadStatesIndex]
	and a
;>     return
	ret nz
;> Delay3()
	call Delay3
;> wJoyIgnore = 0
	xor a ; SCRIPT_LANCESROOM_DEFAULT
	ld [wJoyIgnore], a
;> wLancesRoomCurScript = SCRIPT_LANCESROOM_DEFAULT
	ld [wLancesRoomCurScript], a
;> wCurMapScript = SCRIPT_LANCESROOM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/LancesRoom
LancesRoom_TextPointers:
	dw LancesRoomLanceText
DEF TEXT_LANCESROOM_LANCE EQU 1

;@ path: scripts/LancesRoom
LancesRoomTrainerHeaders:
;@ path: scripts/LancesRoom
LancesRoomTrainerHeader0:
	db $1
	db 0 << 4
	dw wEventFlags + (EVENT_BEAT_LANCES_ROOM_TRAINER_0 - $1) / 8
	dw LancesRoomLanceBeforeBattleText, LancesRoomLanceAfterBattleText, LancesRoomLanceEndBattleText, LancesRoomLanceEndBattleText
	db -1 ; end

;@ path: scripts/LancesRoom
;@ def LancesRoomLanceText() -> hl
;@ Lance: talking to him starts the battle.
;@ test: skip a text script: the code after text_asm is run by the text engine
LancesRoomLanceText:
	db TX_START_ASM
;> TalkToTrainer(LancesRoomTrainerHeader0)
;> return TextScriptEnd()
	ld hl, LancesRoomTrainerHeader0
	call TalkToTrainer
	jp TextScriptEnd

;@ path: scripts/LancesRoom
LancesRoomLanceBeforeBattleText:
	db TX_FAR
	dw _LancesRoomLanceBeforeBattleText
	db BANK(_LancesRoomLanceBeforeBattleText)
	db TX_END

;@ path: scripts/LancesRoom
LancesRoomLanceEndBattleText:
	db TX_FAR
	dw _LancesRoomLanceEndBattleText
	db BANK(_LancesRoomLanceEndBattleText)
	db TX_END

;@ path: scripts/LancesRoom
;@ def LancesRoomLanceAfterBattleText() -> hl
;@ Lance's words after his defeat; from then on he counts as beaten.
;@ test: skip a text script: the text engine prints the text and then runs the code after text_asm
LancesRoomLanceAfterBattleText:
	db TX_FAR
	dw _LancesRoomLanceAfterBattleText
	db BANK(_LancesRoomLanceAfterBattleText)
	db TX_START_ASM
;> set_event(EVENT_BEAT_LANCE)
;> return TextScriptEnd()
	ld hl, wEventFlags + $11F
	set (EVENT_BEAT_LANCE) % 8, [hl]
	jp TextScriptEnd
DEF LANCESROOM_LANCE EQU 1
	EXPORT LANCESROOM_LANCE

;@ path: data/maps/objects/LancesRoom
LancesRoom_Object:
	db $3 ; border block

	db 3
	db 16, 24, 3 - 1, AGATHAS_ROOM
	db 0, 5, 1 - 1, CHAMPIONS_ROOM
	db 0, 6, 1 - 1, CHAMPIONS_ROOM

	db 0

	db 1
	db SPRITE_LANCE
	db 1 + 4
	db 6 + 4
	db STAY
	db DOWN
	db TRAINER | TEXT_LANCESROOM_LANCE
	db OPP_LANCE
	db 1

	dw (wOverworldMap + 7 + (LANCES_ROOM_WIDTH) + ((LANCES_ROOM_WIDTH) + 6) * (($10) >> 1) + (($18) >> 1))
	db $10, $18
	dw (wOverworldMap + 7 + (LANCES_ROOM_WIDTH) + ((LANCES_ROOM_WIDTH) + 6) * ((0) >> 1) + ((5) >> 1))
	db 0, 5
	dw (wOverworldMap + 7 + (LANCES_ROOM_WIDTH) + ((LANCES_ROOM_WIDTH) + 6) * ((0) >> 1) + ((6) >> 1))
	db 0, 6
