	db $05, $31, $4c, $03, $03, $03, $4b, $05, $05, $4c, $4b, $32, $05, $05, $31, $4c
	db $03, $03, $03, $4b, $05, $05, $4c, $4b, $32, $05, $05, $31, $4c, $03, $03, $03
	db $52, $31, $32, $6f, $4b, $32, $05, $05, $31, $4c, $03, $03, $03, $03, $03, $03
	db $03, $4b, $32, $05, $05, $31, $4c, $03, $03, $03, $03, $03, $03, $03, $52, $56
	db $72, $73, $4e, $6f, $03, $03, $03, $03, $03, $03, $03, $03, $4b, $05, $05, $4c
	db $03, $03, $03, $49, $01, $01, $01, $4a, $03, $4b, $05, $05, $4c, $03, $03, $03
	db $4b, $05, $05, $05, $70, $03, $4b, $05, $05, $4c, $03, $03, $03, $4b, $53, $46
	db $46, $6f, $03, $4b, $05, $05, $4c, $03, $03, $03, $4b, $4c, $03, $03, $03, $03
	db $4b, $05, $05, $55, $48, $48, $48, $5b, $4c, $03, $03, $03, $03, $52, $46, $46
