HallOfFame_h::
	db GYM
	db $4, $5
	dw HallOfFame_Blocks
	dw HallOfFame_TextPointers
	dw HallOfFame_Script
	db 0
	dw HallOfFame_Object
;@ path: scripts/HallOfFame
;@ def HallOfFame_Script()
;@ The Hall of Fame map script: run the current step of the room's script.
HallOfFame_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wHallOfFameCurScript, HallOfFame_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld hl, HallOfFame_ScriptPointers
	ld a, [wHallOfFameCurScript]
	jp CallFunctionInTable

;@ path: scripts/HallOfFame
;@ def HallofFameRoomClearScripts()
;@ Give the controls back and return to the room's first step (not used).
HallofFameRoomClearScripts: ; unreferenced
;> wJoyIgnore = 0
;> wHallOfFameCurScript = 0
	xor a
	ld [wJoyIgnore], a
	ld [wHallOfFameCurScript], a
	ret

;@ path: scripts/HallOfFame
HallOfFame_ScriptPointers:
	dw HallOfFameDefaultScript
DEF SCRIPT_HALLOFFAME_DEFAULT EQU 0
	dw HallOfFameOakCongratulationsScript
DEF SCRIPT_HALLOFFAME_OAK_CONGRATULATIONS EQU 1
	dw HallOfFameResetEventsAndSaveScript
DEF SCRIPT_HALLOFFAME_RESET_EVENTS_AND_SAVE EQU 2
	dw HallOfFameNoopScript
DEF SCRIPT_HALLOFFAME_NOOP EQU 3

;@ path: scripts/HallOfFame
;@ def HallOfFameNoopScript()
;@ The room's idle step: nothing happens.
HallOfFameNoopScript:
;> return
	ret

;@ path: scripts/HallOfFame
;@ def HallOfFameResetEventsAndSaveScript()
;@ After Oak's speech: the Hall of Fame record, then all Elite Four progress is reset, the player will
;@ black out to Pallet Town, the game is saved, and after a pause and a button press the game restarts.
;@ test: skip never returns: restarts the game
HallOfFameResetEventsAndSaveScript:
;> Delay3()
	call Delay3
;> saved = wLetterPrintingDelayFlags
	ld a, [wLetterPrintingDelayFlags]
	push af
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> HallOfFamePC()
	ld a, (HallOfFamePCPredef - PredefPointers) / 3
	call Predef
;> wLetterPrintingDelayFlags = saved
	pop af
	ld [wLetterPrintingDelayFlags], a
;> wStatusFlags7 &= ~(1 << BIT_NO_MAP_MUSIC)
	ld hl, wStatusFlags7
	res BIT_NO_MAP_MUSIC, [hl]
;> wElite4Flags |= 1 << BIT_UNUSED_BEAT_ELITE_4      # never read
	ASSERT wStatusFlags7 + 1 == wElite4Flags
	inc hl
	set BIT_UNUSED_BEAT_ELITE_4, [hl] ; unused
;> wLoreleisRoomCurScript = 0
	xor a ; SCRIPT_*_DEFAULT
	ld hl, wLoreleisRoomCurScript
	ld [hli], a ; wLoreleisRoomCurScript
;> wBrunosRoomCurScript = 0
	ld [hli], a ; wBrunosRoomCurScript
;> wAgathasRoomCurScript = 0
	ld [hl], a ; wAgathasRoomCurScript
;> wLancesRoomCurScript = 0
	ld [wLancesRoomCurScript], a
;> wHallOfFameCurScript = 0
	ld [wHallOfFameCurScript], a
;> for e in range(INDIGO_PLATEAU_EVENTS_START, INDIGO_PLATEAU_EVENTS_END + 1):
;>     reset_event(e)
	; Elite 4 events
	ld hl, wEventFlags + $11C
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wHallOfFameCurScript = 0
	xor a
	ld [wHallOfFameCurScript], a
;> wLastBlackoutMap = PALLET_TOWN
	ld a, PALLET_TOWN
	ld [wLastBlackoutMap], a
;> SaveGameData()
	ld b, BANK(SaveGameData)
	ld hl, SaveGameData
	call Bankswitch
;> for _ in range(5):
;>     DelayFrames(600 // 5)
	ld b, 5
.delayLoop
	ld c, 600 / 5
	call DelayFrames
	dec b
	jr nz, .delayLoop
;> WaitForTextScrollButtonPress()
	call WaitForTextScrollButtonPress
;> return Init()
	jp Init

;@ path: scripts/HallOfFame
;@ def HallOfFameDefaultScript()
;@ Entering the Hall of Fame: the player is walked up to Oak by simulated button presses.
HallOfFameDefaultScript:
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> count = DecodeRLEList(addr(wSimulatedJoypadStatesEnd), HallOfFameEntryMovement)   # the steps, run-length coded
	ld hl, wSimulatedJoypadStatesEnd
	ld de, HallOfFameEntryMovement
	call DecodeRLEList
;> wSimulatedJoypadStatesIndex = count - 1
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wHallOfFameCurScript = SCRIPT_HALLOFFAME_OAK_CONGRATULATIONS
	ld a, SCRIPT_HALLOFFAME_OAK_CONGRATULATIONS
	ld [wHallOfFameCurScript], a
	ret

;@ path: scripts/HallOfFame
HallOfFameEntryMovement:
	db PAD_UP, 5
	db -1 ; end

;@ path: scripts/HallOfFame
;@ def HallOfFameOakCongratulationsScript()
;@ When the walk is over, Oak and the player face each other and Oak congratulates the new champion; the man
;@ blocking Cerulean Cave leaves.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
HallOfFameOakCongratulationsScript:
;> if wSimulatedJoypadStatesIndex:
	ld a, [wSimulatedJoypadStatesIndex]
	and a
;>     return
	ret nz
;> wPlayerMovingDirection = PLAYER_DIR_RIGHT
	ld a, PLAYER_DIR_RIGHT
	ld [wPlayerMovingDirection], a
;> hSpriteIndex = HALLOFFAME_OAK
	ld a, HALLOFFAME_OAK
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> hSpriteFacingDirection = SPRITE_FACING_LEFT
	ld a, SPRITE_FACING_LEFT
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> Delay3()
	call Delay3
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wPlayerMovingDirection = PLAYER_DIR_RIGHT
	inc a ; PLAYER_DIR_RIGHT
	ld [wPlayerMovingDirection], a
;> hTextID = TEXT_HALLOFFAME_OAK
	ld a, TEXT_HALLOFFAME_OAK
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wToggleableObjectIndex = TOGGLE_CERULEAN_CAVE_GUY
	ld a, TOGGLE_CERULEAN_CAVE_GUY
	ld [wToggleableObjectIndex], a
;> HideObject()
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wHallOfFameCurScript = SCRIPT_HALLOFFAME_RESET_EVENTS_AND_SAVE
	ld a, SCRIPT_HALLOFFAME_RESET_EVENTS_AND_SAVE
	ld [wHallOfFameCurScript], a
	ret

