HallOfFame_TextPointers:
	dw HallOfFameOakText
DEF TEXT_HALLOFFAME_OAK EQU 1

;@ path: scripts/HallOfFame
HallOfFameOakText:
	db TX_FAR
	dw _HallOfFameOakText
	db BANK(_HallOfFameOakText)
	db TX_END
DEF HALLOFFAME_OAK EQU 1
	EXPORT HALLOFFAME_OAK

;@ path: data/maps/objects/HallOfFame
HallOfFame_Object:
	db $3 ; border block

	db 2
	db 7, 4, 3 - 1, CHAMPIONS_ROOM
	db 7, 5, 4 - 1, CHAMPIONS_ROOM

