	dw (wOverworldMap + 7 + (HALL_OF_FAME_WIDTH) + ((HALL_OF_FAME_WIDTH) + 6) * ((7) >> 1) + ((4) >> 1))
	db 7, 4
	dw (wOverworldMap + 7 + (HALL_OF_FAME_WIDTH) + ((HALL_OF_FAME_WIDTH) + 6) * ((7) >> 1) + ((5) >> 1))
	db 7, 5
