Museum1F_h::
	db MUSEUM
	db $4, $A
	dw Museum1F_Blocks
	dw Museum1F_TextPointers
	dw Museum1F_Script
	db 0
	dw Museum1F_Object
;@ path: scripts/Museum1F
;@ def Museum1F_Script()
;@ The museum's 1F: its texts draw their own boxes; run the current step (the ticket check at the entrance).
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
Museum1F_Script:
;> wAutoTextBoxDrawingControl = 1 << BIT_NO_AUTO_TEXT_BOX
	ld a, 1 << BIT_NO_AUTO_TEXT_BOX
	ld [wAutoTextBoxDrawingControl], a
;> wDoNotWaitForButtonPressAfterDisplayingText = 0
	xor a
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> CallFunctionInTable(wMuseum1FCurScript, Museum1F_ScriptPointers)
	ld hl, Museum1F_ScriptPointers
	ld a, [wMuseum1FCurScript]
	jp CallFunctionInTable

;@ path: scripts/Museum1F
Museum1F_ScriptPointers:
	dw Museum1FDefaultScript
DEF SCRIPT_MUSEUM1F_DEFAULT EQU 0
	dw Museum1FNoopScript
DEF SCRIPT_MUSEUM1F_NOOP EQU 1

;@ path: scripts/Museum1F
;@ def Museum1FDefaultScript()
;@ Walking past the ticket desk (row 4, x 9 or 10) makes the clerk speak.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
Museum1FDefaultScript:
;> if wYCoord != 4:
;>     return
	ld a, [wYCoord]
	cp 4
	ret nz
;> if wXCoord != 9:
	ld a, [wXCoord]
	cp 9
	jr z, .continue
;>     if wXCoord != 10:
;>         return
	ld a, [wXCoord]
	cp 10
	ret nz
.continue
;> hJoyHeld = 0                            # at the desk: the clerk speaks
	xor a
	ldh [hJoyHeld], a
;> hTextID = TEXT_MUSEUM1F_SCIENTIST1
;> return DisplayTextID()
	ld a, TEXT_MUSEUM1F_SCIENTIST1
	ldh [hTextID], a
	jp DisplayTextID

;@ path: scripts/Museum1F
;@ def Museum1FNoopScript()
;@ After the ticket is bought: nothing more happens at the desk.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
Museum1FNoopScript:
;> return
	ret

;@ path: scripts/Museum1F
Museum1F_TextPointers:
	dw Museum1FScientist1Text
DEF TEXT_MUSEUM1F_SCIENTIST1 EQU 1
	dw Museum1FGamblerText
DEF TEXT_MUSEUM1F_GAMBLER EQU 2
	dw Museum1FScientist2Text
DEF TEXT_MUSEUM1F_SCIENTIST2 EQU 3
	dw Museum1FScientist3Text
DEF TEXT_MUSEUM1F_SCIENTIST3 EQU 4
	dw Museum1FOldAmberText
DEF TEXT_MUSEUM1F_OLD_AMBER EQU 5

;@ path: scripts/Museum1F
;@ def Museum1FScientist1Text() -> hl
;@ The museum's ticket clerk: sells a ¥50 ticket (or sends the player back without one); from behind the
;@ counter he talks about amber; from the side, he asks the player to come round to the other side.
;@ test: skip a text script: the code after text_asm is run by the text engine
Museum1FScientist1Text:
	db TX_START_ASM
;> T = Museum1FScientist1Text
;> if not ((wYCoord == 4
	ld a, [wYCoord]
	cp 4
	jr nz, .not_right_of_scientist
;>          and wXCoord == 13)                  # behind the counter
	ld a, [wXCoord]
	cp 13
	jp z, .behind_counter
	jr .check_ticket
.not_right_of_scientist
;>         or (wYCoord == 3 and wXCoord == 12)):   # behind the counter too
	cp 3
	jr nz, .not_behind_counter
	ld a, [wXCoord]
	cp 12
	jp z, .behind_counter
.not_behind_counter
;>@bought     if event(EVENT_BOUGHT_MUSEUM_TICKET):
	ld a, [wEventFlags + $D]
	bit (EVENT_BOUGHT_MUSEUM_TICKET) % 8, a
	jr nz, .already_bought_ticket
;>@plenty         PrintText(T.TakePlentyOfTimeText)
;>     elif wYCoord != 4:                       # talking to him from the side
;>         PrintText(T.GoToOtherSideText)
	ld hl, .GoToOtherSideText
	call PrintText
;=@end
	jp .done
.check_ticket
;=@bought
	ld a, [wEventFlags + $D]
	bit (EVENT_BOUGHT_MUSEUM_TICKET) % 8, a
	jr z, .no_ticket
.already_bought_ticket
;=@plenty
	ld hl, .TakePlentyOfTimeText
	call PrintText
;=@end
	jp .done
.no_ticket
;>     else:                                    # at the desk without a ticket
;>         wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;>         DisplayTextBoxID()
	call DisplayTextBoxID
;>         hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;>         PrintText(T.WouldYouLikeToComeInText)
	ld hl, .WouldYouLikeToComeInText
	call PrintText
;>         YesNoChoice()
	call YesNoChoice
;>         entered = False
;>         if wCurrentMenuItem == 0:            # Yes
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .deny_entry
;>             hMoney[0] = hMoney[1] = 0x00     # 50, in BCD
	xor a
	ldh [hMoney], a
	ldh [hMoney + 1], a
;>             hMoney[2] = 0x50
	ld a, $50
	ldh [hMoney + 2], a
;>             if HasEnoughMoney():             # carry: not enough
	call HasEnoughMoney
	jr nc, .buy_ticket
;>                 PrintText(T.DontHaveEnoughMoneyText)
	ld hl, .DontHaveEnoughMoneyText
	call PrintText
	jp .deny_entry
.buy_ticket
;>             else:
;>                 PrintText(T.ThankYouText)
	ld hl, .ThankYouText
	call PrintText
;>                 set_event(EVENT_BOUGHT_MUSEUM_TICKET)
	ld hl, wEventFlags + $D
	set (EVENT_BOUGHT_MUSEUM_TICKET) % 8, [hl]
;>                 wPriceTemp[0] = wPriceTemp[1] = 0x00
	xor a
	ld [wPriceTemp], a
	ld [wPriceTemp + 1], a
;>                 wPriceTemp[2] = 0x50
	ld a, $50
	ld [wPriceTemp + 2], a
;>                 predef(SubBCDPredef, hl=addr(wPriceTemp) + 2, de=addr(wPlayerMoney) + 2, bc=3)   # pay
	ld hl, wPriceTemp + 2
	ld de, wPlayerMoney + 2
	ld c, $3
	ld a, (SubBCDPredefPredef - PredefPointers) / 3
	call Predef
;>                 wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;>                 DisplayTextBoxID()
	call DisplayTextBoxID
;>                 PlaySoundWaitForCurrent(SFX_PURCHASE)
	ld a, SFX_PURCHASE
	call PlaySoundWaitForCurrent
;>                 WaitForSoundToFinish()
	call WaitForSoundToFinish
;>                 entered = True
	jr .allow_entry
;>         if entered:
;>@allow             wMuseum1FCurScript = SCRIPT_MUSEUM1F_NOOP
;>         else:                                # turned away: one step back down
.deny_entry
;>             PrintText(T.ComeAgainText)
	ld hl, .ComeAgainText
	call PrintText
;>             wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;>             wSimulatedJoypadStatesEnd = PAD_DOWN
	ld a, PAD_DOWN
	ld [wSimulatedJoypadStatesEnd], a
;>             StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;>             UpdateSprites()
	call UpdateSprites
;=@end
	jr .done
.allow_entry
;=@allow
	ld a, SCRIPT_MUSEUM1F_NOOP
	ld [wMuseum1FCurScript], a
;=@end
	jr .done

.behind_counter
;> else:                                        # behind the counter: about amber
;>     PrintText(T.DoYouKnowWhatAmberIsText)
	ld hl, .DoYouKnowWhatAmberIsText
	call PrintText
;>     YesNoChoice()
	call YesNoChoice
;>     if wCurrentMenuItem == 0:
	ld a, [wCurrentMenuItem]
	cp $0
	jr nz, .explain_amber
;>         PrintText(T.TheresALabSomewhereText)
	ld hl, .TheresALabSomewhereText
	call PrintText
;=@end
	jr .done
.explain_amber
;>     else:
;>         PrintText(T.AmberIsFossilizedTreeSapText)
	ld hl, .AmberIsFossilizedTreeSapText
	call PrintText
.done
;>@end return TextScriptEnd()
	jp TextScriptEnd

