;@ path: scripts/Museum1F
;@ def Museum1FScientist2Text() -> hl
;@ The scientist with the Old Amber: gives it once (if the bag has room) and asks the player to take it to a
;@ Pokémon lab; later he asks to have it checked.
;@ test: skip a text script: the code after text_asm is run by the text engine
Museum1FScientist2Text:
	db TX_START_ASM
;> if event(EVENT_GOT_OLD_AMBER):
;>     text = Museum1FScientist2Text.GetTheOldAmberCheckText
	ld a, [wEventFlags + $D]
	bit (EVENT_GOT_OLD_AMBER) % 8, a
	jr nz, .got_item
;> else:
;>     PrintText(Museum1FScientist2Text.TakeThisToAPokemonLabText)
	ld hl, .TakeThisToAPokemonLabText
	call PrintText
;>     if GiveItem(OLD_AMBER, 1):
	ld bc, ((OLD_AMBER) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         set_event(EVENT_GOT_OLD_AMBER)
	ld hl, wEventFlags + $D
	set (EVENT_GOT_OLD_AMBER) % 8, [hl]
;>         wToggleableObjectIndex = TOGGLE_OLD_AMBER
	ld a, TOGGLE_OLD_AMBER
	ld [wToggleableObjectIndex], a
;>         predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;>         text = Museum1FScientist2Text.ReceivedOldAmberText
	ld hl, .ReceivedOldAmberText
	jr .done
.bag_full
;>     else:
;>         text = Museum1FScientist2Text.YouDontHaveSpaceText
	ld hl, .YouDontHaveSpaceText
	jr .done
.got_item
	ld hl, .GetTheOldAmberCheckText
.done
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

