PewterGym_h::
	db GYM
	db $7, $5
	dw PewterGym_Blocks
	dw PewterGym_TextPointers
	dw PewterGym_Script
	db 0
	dw PewterGym_Object
;@ path: scripts/PewterGym
;@ def PewterGym_Script()
;@ Pewter Gym's map script: on entering, set the city and leader names (Pewter City, Brock) for the badge
;@ texts; then run the current step of the gym's script (its trainer and Brock).
;@ test: skip the names sit under local labels, which the pseudo-code can only name
PewterGym_Script:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if loaded:
	call nz, .LoadNames
;>@e1     LoadGymLeaderAndCityName(PewterGym_Script.CityName, PewterGym_Script.LeaderName)
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wPewterGymCurScript = ExecuteCurMapScriptInTable(wPewterGymCurScript, PewterGymTrainerHeaders, PewterGym_ScriptPointers)
	ld hl, PewterGymTrainerHeaders
	ld de, PewterGym_ScriptPointers
	ld a, [wPewterGymCurScript]
	call ExecuteCurMapScriptInTable
	ld [wPewterGymCurScript], a
	ret

.LoadNames:
;=@e1
	ld hl, .CityName
	ld de, .LeaderName
	jp LoadGymLeaderAndCityName

.CityName:
	db "PEWTER CITY@"

.LeaderName:
	db "BROCK@"

;@ path: scripts/PewterGym
;@ def PewterGymResetScripts()
;@ Back to the gym's default step, with the controls given back.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
PewterGymResetScripts:
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wPewterGymCurScript = SCRIPT_PEWTERGYM_DEFAULT
	ld [wPewterGymCurScript], a
;> wCurMapScript = SCRIPT_PEWTERGYM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/PewterGym
PewterGym_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_PEWTERGYM_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_PEWTERGYM_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_PEWTERGYM_END_BATTLE EQU 2
	dw PewterGymBrockPostBattle
DEF SCRIPT_PEWTERGYM_BROCK_POST_BATTLE EQU 3

;@ path: scripts/PewterGym
;@ def PewterGymBrockPostBattle()
;@ After the battle with Brock: lost, start over; won, go on to the badge and TM34.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
PewterGymBrockPostBattle:
;> if wIsInBattle == LOST_BATTLE:
;>     return PewterGymResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, PewterGymResetScripts
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
; fallthrough

;> return PewterGymScriptReceiveTM34()
;@ path: scripts/PewterGym
;@ def PewterGymScriptReceiveTM34()
;@ Brock's reward: "Wait! Take this", TM34 (BIDE) if the bag has room, the Boulder Badge; the gym guide and
;@ the rival on Route 22 leave, and the gym's trainer no longer battles.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
PewterGymScriptReceiveTM34:
;> hTextID = TEXT_PEWTERGYM_BROCK_WAIT_TAKE_THIS
	ld a, TEXT_PEWTERGYM_BROCK_WAIT_TAKE_THIS
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_BEAT_BROCK)
	ld hl, wEventFlags + $E
	set (EVENT_BEAT_BROCK) % 8, [hl]
;> if GiveItem(TM_BIDE, 1):
	ld bc, ((TM_BIDE) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .BagFull
;>     hTextID = TEXT_PEWTERGYM_RECEIVED_TM34
	ld a, TEXT_PEWTERGYM_RECEIVED_TM34
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     set_event(EVENT_GOT_TM34)
	ld hl, wEventFlags + $E
	set (EVENT_GOT_TM34) % 8, [hl]
	jr .gymVictory
.BagFull
;> else:
;>     hTextID = TEXT_PEWTERGYM_TM34_NO_ROOM
	ld a, TEXT_PEWTERGYM_TM34_NO_ROOM
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
.gymVictory
;> wObtainedBadges |= 1 << BIT_BOULDERBADGE
	ld hl, wObtainedBadges
	set BIT_BOULDERBADGE, [hl]
;> wBeatGymFlags |= 1 << BIT_BOULDERBADGE
	ld hl, wBeatGymFlags
	set BIT_BOULDERBADGE, [hl]

;> wToggleableObjectIndex = TOGGLE_GYM_GUY
	ld a, TOGGLE_GYM_GUY
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_ROUTE_22_RIVAL_1
	ld a, TOGGLE_ROUTE_22_RIVAL_1
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef

;> reset_event(EVENT_1ST_ROUTE22_RIVAL_BATTLE)
	ld hl, wEventFlags + $A4
	res (EVENT_1ST_ROUTE22_RIVAL_BATTLE) % 8, [hl]
;> reset_event(EVENT_ROUTE22_RIVAL_WANTS_BATTLE)
	res (EVENT_ROUTE22_RIVAL_WANTS_BATTLE) % 8, [hl]

;> set_event(EVENT_BEAT_PEWTER_GYM_TRAINER_0)
	; deactivate gym trainers
	ld hl, wEventFlags + $E
	set (EVENT_BEAT_PEWTER_GYM_TRAINER_0) % 8, [hl]

;> return PewterGymResetScripts()
	jp PewterGymResetScripts

