PewterGymTrainerHeader0:
	db $2
	db 5 << 4
	dw wEventFlags + (EVENT_BEAT_PEWTER_GYM_TRAINER_0 - $2) / 8
	dw PewterGymCooltrainerMBattleText, PewterGymCooltrainerMAfterBattleText, PewterGymCooltrainerMEndBattleText, PewterGymCooltrainerMEndBattleText
	db -1 ; end

;@ path: scripts/PewterGym
;@ def PewterGymBrockText() -> hl
;@ Brock: before the battle his challenge (and he engages the player); after it, TM34 if the bag had no room
;@ before, otherwise his advice.
;@ test: skip a text script: the code after text_asm is run by the text engine
PewterGymBrockText:
	db TX_START_ASM
;> if event(EVENT_BEAT_BROCK):
	ld a, [wEventFlags + $E]
	bit (EVENT_BEAT_BROCK) % 8, a
	jr z, .beforeBeat
;>     if event(EVENT_GOT_TM34):
;>@advice         PrintText(PewterGymBrockText.PostBattleAdviceText)
	bit (EVENT_GOT_TM34) % 8, a
	jr nz, .afterBeat
;>     else:                                # the bag had no room for it after the battle
;>         PewterGymScriptReceiveTM34()
	call z, PewterGymScriptReceiveTM34
;>         DisableWaitingAfterTextDisplay()
	call DisableWaitingAfterTextDisplay
	jr .done
.afterBeat
;=@advice
	ld hl, .PostBattleAdviceText
	call PrintText
	jr .done
.beforeBeat
;> else:
;>     PrintText(PewterGymBrockText.PreBattleText)
	ld hl, .PreBattleText
	call PrintText
;>     wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;>     SaveEndBattleTextPointers(PewterGymBrockReceivedBoulderBadgeText, PewterGymBrockReceivedBoulderBadgeText)
	ld hl, PewterGymBrockReceivedBoulderBadgeText
	ld de, PewterGymBrockReceivedBoulderBadgeText
	call SaveEndBattleTextPointers
;>     wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;>     EngageMapTrainer()
	call EngageMapTrainer
;>     InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;>     wGymLeaderNo = 1
	ld a, $1
	ld [wGymLeaderNo], a
;>     hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;>     wPewterGymCurScript = SCRIPT_PEWTERGYM_BROCK_POST_BATTLE
	ld a, SCRIPT_PEWTERGYM_BROCK_POST_BATTLE
	ld [wPewterGymCurScript], a
;>     wCurMapScript = SCRIPT_PEWTERGYM_BROCK_POST_BATTLE
	ld [wCurMapScript], a
.done
;> return TextScriptEnd()
	jp TextScriptEnd

