;@ path: scripts/PewterGym
;@ def PewterGymGuideText() -> hl
;@ The gym guide: before Brock is beaten he offers advice (free of charge, either way) about rock Pokémon;
;@ afterwards he congratulates the player.
;@ test: skip a text script: the code after text_asm is run by the text engine
PewterGymGuideText:
	db TX_START_ASM
;> if wBeatGymFlags >> BIT_BOULDERBADGE & 1:
	ld a, [wBeatGymFlags]
	bit BIT_BOULDERBADGE, a
	jr nz, .afterBeat
;>@e1     PrintText(PewterGymGuidePostBattleText)
;>@e2     return TextScriptEnd()
;> PrintText(PewterGymGuidePreAdviceText)
	ld hl, PewterGymGuidePreAdviceText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .PewterGymGuideBeginAdviceText
;>     PrintText(PewterGymGuideFreeServiceText)
;> else:
;>     PrintText(PewterGymGuideBeginAdviceText)
	ld hl, PewterGymGuideBeginAdviceText
	call PrintText
	jr .PewterGymGuideAdviceText
.PewterGymGuideBeginAdviceText
	ld hl, PewterGymGuideFreeServiceText
	call PrintText
.PewterGymGuideAdviceText
;> PrintText(PewterGymGuideAdviceText)
	ld hl, PewterGymGuideAdviceText
	call PrintText
	jr .done
.afterBeat
;=@e1
	ld hl, PewterGymGuidePostBattleText
	call PrintText
;=@e2
.done
;> return TextScriptEnd()
	jp TextScriptEnd

