;@ path: scripts/PewterPokecenter
;@ def PewterPokecenterJigglypuffText() -> hl
;@ The Jigglypuff: its line, then it sings its song while spinning round (turning every 24 frames) until the
;@ song is over; then the map music returns.
;@ test: skip a text script: the code after text_asm is run by the text engine
PewterPokecenterJigglypuffText:
	db TX_START_ASM
;> wDoNotWaitForButtonPressAfterDisplayingText = TRUE
	ld a, TRUE
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> PrintText(PewterPokecenterJigglypuffText.Text)
	ld hl, .Text
	call PrintText

;> PlaySound(SFX_STOP_ALL_MUSIC)
	ld a, SFX_STOP_ALL_MUSIC
	call PlaySound
;> DelayFrames(32)
	ld c, 32
	call DelayFrames

;> dirs = addr(wJigglypuffFacingDirections)
	ld hl, .FacingDirections
	ld de, wJigglypuffFacingDirections
;> CopyData(PewterPokecenterJigglypuffText.FacingDirections, dirs, 4)     # down, left, up, right
	ld bc, .FacingDirectionsEnd - .FacingDirections
	call CopyData

;> p = dirs
;> while mem[p] != mem[wSprite03StateData1ImageIndex]:
	ld a, [wSprite03StateData1ImageIndex]
	ld hl, wJigglypuffFacingDirections
.findMatchingFacingDirectionLoop
	cp [hl]
;>     p += 1
	inc hl
	jr nz, .findMatchingFacingDirectionLoop
	dec hl

	push hl
;> PlayMusic(MUSIC_JIGGLYPUFF_SONG, BANK(Music_JigglypuffSong))
	ld c, BANK(Music_JigglypuffSong)
	ld a, MUSIC_JIGGLYPUFF_SONG
	call PlayMusic
	pop hl

;> while True:
.spinMovementLoop
;>     mem[wSprite03StateData1ImageIndex] = mem[p]
	ld a, [hl]
	ld [wSprite03StateData1ImageIndex], a
;>     CopyData(dirs, dirs - 1, 4)               # rotate the four directions by one
; rotate the array
	push hl
	ld hl, wJigglypuffFacingDirections
	ld de, wJigglypuffFacingDirections - 1
	ld bc, .FacingDirectionsEnd - .FacingDirections
	call CopyData
;>     mem[dirs + 3] = mem[dirs - 1]
	ld a, [wJigglypuffFacingDirections - 1]
	ld [wJigglypuffFacingDirections + 3], a
;>     DelayFrames(24)
	pop hl
	ld c, 24
	call DelayFrames
;>     if not (wChannelSoundIDs[0] | wChannelSoundIDs[CHAN2]):
	ld a, [wChannelSoundIDs]
	ld b, a
	ld a, [wChannelSoundIDs + CHAN2]
	or b
;>         break
	jr nz, .spinMovementLoop

;> DelayFrames(48)
	ld c, 48
	call DelayFrames
;> PlayDefaultMusic()
	call PlayDefaultMusic
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _PewterPokecenterJigglypuffText
	db BANK(_PewterPokecenterJigglypuffText)
	db TX_END

.FacingDirections:
	db $30 | SPRITE_FACING_DOWN
	db $30 | SPRITE_FACING_LEFT
	db $30 | SPRITE_FACING_UP
	db $30 | SPRITE_FACING_RIGHT
.FacingDirectionsEnd:

