;@ path: scripts/CeruleanGym
;@ def CeruleanGym_Script()
;@ Cerulean Gym's map script: on entering, set the city and leader names (Cerulean City, Misty) for the
;@ badge texts, then run the current step of the gym's script (its trainers and Misty).
;@ test: skip the names sit under local labels, which the pseudo-code cannot reach
CeruleanGym_Script:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if loaded:
	call nz, .LoadNames
;>@e1     LoadGymLeaderAndCityName(CeruleanGym_Script.CityName, CeruleanGym_Script.LeaderName)
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wCeruleanGymCurScript = ExecuteCurMapScriptInTable(wCeruleanGymCurScript, CeruleanGymTrainerHeaders, CeruleanGym_ScriptPointers)
	ld hl, CeruleanGymTrainerHeaders
	ld de, CeruleanGym_ScriptPointers
	ld a, [wCeruleanGymCurScript]
	call ExecuteCurMapScriptInTable
	ld [wCeruleanGymCurScript], a
	ret

.LoadNames:
;=@e1
	ld hl, .CityName
	ld de, .LeaderName
	jp LoadGymLeaderAndCityName

.CityName:
	db "CERULEAN CITY@"

.LeaderName:
	db "MISTY@"

;@ path: scripts/CeruleanGym
;@ def CeruleanGymResetScripts()
;@ Back to the gym's default step (after a lost battle or after the badge), with the controls given back.
CeruleanGymResetScripts:
;> wJoyIgnore = 0
	xor a ; SCRIPT_CERULEANGYM_DEFAULT
	ld [wJoyIgnore], a
;> wCeruleanGymCurScript = SCRIPT_CERULEANGYM_DEFAULT
	ld [wCeruleanGymCurScript], a
;> wCurMapScript = SCRIPT_CERULEANGYM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/CeruleanGym
CeruleanGym_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_CERULEANGYM_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_CERULEANGYM_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_CERULEANGYM_END_BATTLE EQU 2
	dw CeruleanGymMistyPostBattleScript
DEF SCRIPT_CERULEANGYM_MISTY_POST_BATTLE EQU 3

;@ path: scripts/CeruleanGym
;@ def CeruleanGymMistyPostBattleScript()
;@ After the battle with Misty: lost, start over; won, go on to the badge and TM11.
CeruleanGymMistyPostBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return CeruleanGymResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, CeruleanGymResetScripts
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a

;> return CeruleanGymReceiveTM11()

;@ path: scripts/CeruleanGym
;@ def CeruleanGymReceiveTM11()
;@ Misty's reward: the Cascade Badge text, TM11 (BUBBLEBEAM) if the bag has room, the badge itself, and
;@ the gym's two trainers count as beaten.
CeruleanGymReceiveTM11:
;> hTextID = TEXT_CERULEANGYM_MISTY_CASCADE_BADGE_INFO
	ld a, TEXT_CERULEANGYM_MISTY_CASCADE_BADGE_INFO
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_BEAT_MISTY)
	ld hl, wEventFlags + $17
	set (EVENT_BEAT_MISTY) % 8, [hl]
;> if GiveItem(TM_BUBBLEBEAM, 1):
	ld bc, ((TM_BUBBLEBEAM) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .BagFull
;>     hTextID = TEXT_CERULEANGYM_MISTY_RECEIVED_TM11
	ld a, TEXT_CERULEANGYM_MISTY_RECEIVED_TM11
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     set_event(EVENT_GOT_TM11)
	ld hl, wEventFlags + $17
	set (EVENT_GOT_TM11) % 8, [hl]
	jr .gymVictory
;> else:
.BagFull
;>     hTextID = TEXT_CERULEANGYM_MISTY_TM11_NO_ROOM
	ld a, TEXT_CERULEANGYM_MISTY_TM11_NO_ROOM
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;> wObtainedBadges |= 1 << BIT_CASCADEBADGE
.gymVictory
	ld hl, wObtainedBadges
	set BIT_CASCADEBADGE, [hl]
;> wBeatGymFlags |= 1 << BIT_CASCADEBADGE
	ld hl, wBeatGymFlags
	set BIT_CASCADEBADGE, [hl]
;> set_event(EVENT_BEAT_CERULEAN_GYM_TRAINER_0)

	; deactivate gym trainers
	ld hl, wEventFlags + $17
	set (EVENT_BEAT_CERULEAN_GYM_TRAINER_0) % 8, [hl]
;> set_event(EVENT_BEAT_CERULEAN_GYM_TRAINER_1)
	set (EVENT_BEAT_CERULEAN_GYM_TRAINER_1) % 8, [hl]
;> return CeruleanGymResetScripts()

	jp CeruleanGymResetScripts

