DEF TEXT_CERULEANGYM_MISTY_RECEIVED_TM11 EQU 6
	dw CeruleanGymMistyTM11NoRoomText
DEF TEXT_CERULEANGYM_MISTY_TM11_NO_ROOM EQU 7

;@ path: scripts/CeruleanGym
CeruleanGymTrainerHeaders:
;@ path: scripts/CeruleanGym
CeruleanGymTrainerHeader0:
	db $2
	db 3 << 4
	dw wEventFlags + (EVENT_BEAT_CERULEAN_GYM_TRAINER_0 - $2) / 8
	dw CeruleanGymBattleText1, CeruleanGymAfterBattleText1, CeruleanGymEndBattleText1, CeruleanGymEndBattleText1
;@ path: scripts/CeruleanGym
CeruleanGymTrainerHeader1:
	db $3
	db 3 << 4
	dw wEventFlags + (EVENT_BEAT_CERULEAN_GYM_TRAINER_1 - $3) / 8
	dw CeruleanGymBattleText2, CeruleanGymAfterBattleText2, CeruleanGymEndBattleText2, CeruleanGymEndBattleText2
	db -1 ; end

;@ path: scripts/CeruleanGym
;@ def CeruleanGymMistyText() -> hl
;@ Misty: before the battle she engages the player; after it she gives TM11 if she still owes it, and
;@ otherwise explains it.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeruleanGymMistyText:
	db TX_START_ASM
;> if event(EVENT_BEAT_MISTY):
	ld a, [wEventFlags + $17]
	bit (EVENT_BEAT_MISTY) % 8, a
	jr z, .beforeBeat
;>     if event(EVENT_GOT_TM11):
	bit (EVENT_GOT_TM11) % 8, a
	jr nz, .afterBeat
;>         PrintText(CeruleanGymMistyText.TM11ExplanationText)
;>     else:
;>         CeruleanGymReceiveTM11()
	call z, CeruleanGymReceiveTM11
;>         DisableWaitingAfterTextDisplay()
	call DisableWaitingAfterTextDisplay
;>     return TextScriptEnd()
	jr .done
.afterBeat
	ld hl, .TM11ExplanationText
	call PrintText
	jr .done
.beforeBeat
;> PrintText(CeruleanGymMistyText.PreBattleText)
	ld hl, .PreBattleText
	call PrintText
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(CeruleanGymMistyReceivedCascadeBadgeText, CeruleanGymMistyReceivedCascadeBadgeText)
	ld hl, CeruleanGymMistyReceivedCascadeBadgeText
	ld de, CeruleanGymMistyReceivedCascadeBadgeText
	call SaveEndBattleTextPointers
;> wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;> EngageMapTrainer()
	call EngageMapTrainer
;> InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;> wGymLeaderNo = 2
	ld a, $2
	ld [wGymLeaderNo], a
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wCeruleanGymCurScript = SCRIPT_CERULEANGYM_MISTY_POST_BATTLE
	ld a, SCRIPT_CERULEANGYM_MISTY_POST_BATTLE
	ld [wCeruleanGymCurScript], a
;> return TextScriptEnd()
.done
	jp TextScriptEnd

.PreBattleText:
	db TX_FAR
	dw _CeruleanGymMistyPreBattleText
	db BANK(_CeruleanGymMistyPreBattleText)
	db TX_END

.TM11ExplanationText:
	db TX_FAR
	dw _CeruleanGymMistyTM11ExplanationText
	db BANK(_CeruleanGymMistyTM11ExplanationText)
	db TX_END

