VermilionGym_h::
	db GYM
	db $9, $5
	dw VermilionGym_Blocks
	dw VermilionGym_TextPointers
	dw VermilionGym_Script
	db 0
	dw VermilionGym_Object
;@ path: scripts/VermilionGym
;@ def VermilionGym_Script()
;@ Vermilion Gym's map script: on entering, set the city and leader names (Vermilion City, Lt. Surge) and
;@ draw the door to Surge (open once both locks are solved); then run the current step of the gym's script.
;@ test: skip the names sit under local labels, which the pseudo-code can only name
VermilionGym_Script:
;> loaded1 = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if loaded1:
	push hl
	call nz, .LoadNames
;>@e1     LoadGymLeaderAndCityName(VermilionGym_Script.CityName, VermilionGym_Script.LeaderName)
;> loaded2 = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	pop hl
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if loaded2:
;>     VermilionGymSetDoorTile()
	call nz, VermilionGymSetDoorTile
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wVermilionGymCurScript = ExecuteCurMapScriptInTable(wVermilionGymCurScript, VermilionGymTrainerHeaders, VermilionGym_ScriptPointers)
	ld hl, VermilionGymTrainerHeaders
	ld de, VermilionGym_ScriptPointers
	ld a, [wVermilionGymCurScript]
	call ExecuteCurMapScriptInTable
	ld [wVermilionGymCurScript], a
	ret

.LoadNames:
;=@e1
	ld hl, .CityName
	ld de, .LeaderName
	jp LoadGymLeaderAndCityName

.CityName:
	db "VERMILION CITY@"

.LeaderName:
	db "LT.SURGE@"

;@ path: scripts/VermilionGym
;@ def VermilionGymSetDoorTile()
;@ The double door to Lt. Surge: closed (block $24) until the second lock is opened, then open floor ($05)
;@ with the door sound.
;@ test: hLoadedROMBank = 0x17; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
VermilionGymSetDoorTile:
;> if event(EVENT_2ND_LOCK_OPENED):
	ld a, [wEventFlags + $2C]
	bit (EVENT_2ND_LOCK_OPENED) % 8, a
	jr nz, .doorsOpen
	ld a, $24 ; double door tile ID
	jr .replaceTile
.doorsOpen
;>     PlaySound(SFX_GO_INSIDE)
	ld a, SFX_GO_INSIDE
	call PlaySound
;>     wNewTileBlockID = 0x05
	ld a, $5 ; clear floor tile ID
.replaceTile
;> else:
;>     wNewTileBlockID = 0x24
	ld [wNewTileBlockID], a
;> return predef(ReplaceTileBlock, bc=2 << 8 | 2)
	ld bc, ((2) & $ff) << 8 + ((2) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/VermilionGym
;@ def VermilionGymResetScripts()
;@ Back to the gym's default step, with the controls given back.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
VermilionGymResetScripts:
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wVermilionGymCurScript = SCRIPT_VERMILIONGYM_DEFAULT
	ld [wVermilionGymCurScript], a
;> wCurMapScript = SCRIPT_VERMILIONGYM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/VermilionGym
VermilionGym_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_VERMILIONGYM_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_VERMILIONGYM_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_VERMILIONGYM_END_BATTLE EQU 2
	dw VermilionGymLTSurgeAfterBattleScript
DEF SCRIPT_VERMILIONGYM_LT_SURGE_AFTER_BATTLE EQU 3

;@ path: scripts/VermilionGym
;@ def VermilionGymLTSurgeAfterBattleScript()
;@ After the battle with Lt. Surge: lost, start over; won, go on to the badge and TM24.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
VermilionGymLTSurgeAfterBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return VermilionGymResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, VermilionGymResetScripts
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a

;> return VermilionGymLTSurgeReceiveTM24Script()

;@ path: scripts/VermilionGym
;@ def VermilionGymLTSurgeReceiveTM24Script()
;@ Lt. Surge's reward: the Thunder Badge text, TM24 (THUNDERBOLT) if the bag has room, the badge, and the gym's
;@ trainers no longer battle.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
VermilionGymLTSurgeReceiveTM24Script:
;> hTextID = TEXT_VERMILIONGYM_LT_SURGE_THUNDER_BADGE_INFO
	ld a, TEXT_VERMILIONGYM_LT_SURGE_THUNDER_BADGE_INFO
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_BEAT_LT_SURGE)
	ld hl, wEventFlags + $2C
	set (EVENT_BEAT_LT_SURGE) % 8, [hl]
;> if GiveItem(TM_THUNDERBOLT, 1):
	ld bc, ((TM_THUNDERBOLT) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>     hTextID = TEXT_VERMILIONGYM_LT_SURGE_RECEIVED_TM24
	ld a, TEXT_VERMILIONGYM_LT_SURGE_RECEIVED_TM24
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     set_event(EVENT_GOT_TM24)
	ld hl, wEventFlags + $2C
	set (EVENT_GOT_TM24) % 8, [hl]
	jr .gym_victory
.bag_full
;> else:
;>     hTextID = TEXT_VERMILIONGYM_LT_SURGE_TM24_NO_ROOM
	ld a, TEXT_VERMILIONGYM_LT_SURGE_TM24_NO_ROOM
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
.gym_victory
;> wObtainedBadges |= 1 << BIT_THUNDERBADGE
	ld hl, wObtainedBadges
	set BIT_THUNDERBADGE, [hl]
;> wBeatGymFlags |= 1 << BIT_THUNDERBADGE
	ld hl, wBeatGymFlags
	set BIT_THUNDERBADGE, [hl]

;> for e in range(EVENT_BEAT_VERMILION_GYM_TRAINER_0, EVENT_BEAT_VERMILION_GYM_TRAINER_2 + 1):
	; deactivate gym trainers
	ld a, [wEventFlags + $2C]
;>     set_event(e)
	or (1 << (((EVENT_BEAT_VERMILION_GYM_TRAINER_2) % 8) + 1)) - (1 << ((EVENT_BEAT_VERMILION_GYM_TRAINER_0) % 8))
	ld [wEventFlags + $2C], a

;> return VermilionGymResetScripts()
	jp VermilionGymResetScripts

;@ path: scripts/VermilionGym
VermilionGym_TextPointers:
	dw VermilionGymLTSurgeText
DEF TEXT_VERMILIONGYM_LT_SURGE EQU 1
	dw VermilionGymGentlemanText
DEF TEXT_VERMILIONGYM_GENTLEMAN EQU 2
	dw VermilionGymSuperNerdText
DEF TEXT_VERMILIONGYM_SUPER_NERD EQU 3
	dw VermilionGymSailorText
DEF TEXT_VERMILIONGYM_SAILOR EQU 4
