DEF TEXT_VERMILIONGYM_GYM_GUIDE EQU 5
	dw VermilionGymLTSurgeThunderBadgeInfoText
DEF TEXT_VERMILIONGYM_LT_SURGE_THUNDER_BADGE_INFO EQU 6
	dw VermilionGymLTSurgeReceivedTM24Text
DEF TEXT_VERMILIONGYM_LT_SURGE_RECEIVED_TM24 EQU 7
	dw VermilionGymLTSurgeTM24NoRoomText
DEF TEXT_VERMILIONGYM_LT_SURGE_TM24_NO_ROOM EQU 8

;@ path: scripts/VermilionGym
VermilionGymTrainerHeaders:
;@ path: scripts/VermilionGym
VermilionGymTrainerHeader0:
	db $2
	db 3 << 4
	dw wEventFlags + (EVENT_BEAT_VERMILION_GYM_TRAINER_0 - $2) / 8
	dw VermilionGymGentlemanBattleText, VermilionGymGentlemanAfterBattleText, VermilionGymGentlemanEndBattleText, VermilionGymGentlemanEndBattleText
;@ path: scripts/VermilionGym
VermilionGymTrainerHeader1:
	db $3
	db 2 << 4
	dw wEventFlags + (EVENT_BEAT_VERMILION_GYM_TRAINER_1 - $3) / 8
	dw VermilionGymSuperNerdBattleText, VermilionGymSuperNerdAfterBattleText, VermilionGymSuperNerdEndBattleText, VermilionGymSuperNerdEndBattleText
;@ path: scripts/VermilionGym
VermilionGymTrainerHeader2:
	db $4
	db 3 << 4
	dw wEventFlags + (EVENT_BEAT_VERMILION_GYM_TRAINER_2 - $4) / 8
	dw VermilionGymSailorBattleText, VermilionGymSailorAfterBattleText, VermilionGymSailorEndBattleText, VermilionGymSailorEndBattleText
	db -1 ; end

;@ path: scripts/VermilionGym
;@ def VermilionGymLTSurgeText() -> hl
;@ Lt. Surge: before the battle his challenge (and he engages the player); after it, TM24 if the bag had no
;@ room before, otherwise his advice.
;@ test: skip a text script: the code after text_asm is run by the text engine
VermilionGymLTSurgeText:
	db TX_START_ASM
;> if event(EVENT_BEAT_LT_SURGE):
	ld a, [wEventFlags + $2C]
	bit (EVENT_BEAT_LT_SURGE) % 8, a
	jr z, .before_beat
;>     if event(EVENT_GOT_TM24):
;>@advice         PrintText(VermilionGymLTSurgeText.PostBattleAdviceText)
	bit (EVENT_GOT_TM24) % 8, a
	jr nz, .got_tm24_already
;>     else:                                # the bag had no room for it after the battle
;>         VermilionGymLTSurgeReceiveTM24Script()
	call z, VermilionGymLTSurgeReceiveTM24Script
;>         DisableWaitingAfterTextDisplay()
	call DisableWaitingAfterTextDisplay
	jr .text_script_end
.got_tm24_already
;=@advice
	ld hl, .PostBattleAdviceText
	call PrintText
	jr .text_script_end
.before_beat
;> else:
;>     PrintText(VermilionGymLTSurgeText.PreBattleText)
	ld hl, .PreBattleText
	call PrintText
;>     wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;>     SaveEndBattleTextPointers(VermilionGymLTSurgeReceivedThunderBadgeText, VermilionGymLTSurgeReceivedThunderBadgeText)
	ld hl, VermilionGymLTSurgeReceivedThunderBadgeText
	ld de, VermilionGymLTSurgeReceivedThunderBadgeText
	call SaveEndBattleTextPointers
;>     wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;>     EngageMapTrainer()
	call EngageMapTrainer
;>     InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;>     wGymLeaderNo = 3
	ld a, $3
	ld [wGymLeaderNo], a
;>     hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;>     wVermilionGymCurScript = SCRIPT_VERMILIONGYM_LT_SURGE_AFTER_BATTLE
	ld a, SCRIPT_VERMILIONGYM_LT_SURGE_AFTER_BATTLE
	ld [wVermilionGymCurScript], a
;>     wCurMapScript = SCRIPT_VERMILIONGYM_LT_SURGE_AFTER_BATTLE
	ld [wCurMapScript], a
.text_script_end
;> return TextScriptEnd()
	jp TextScriptEnd

.PreBattleText:
	db TX_FAR
	dw _VermilionGymLTSurgePreBattleText
	db BANK(_VermilionGymLTSurgePreBattleText)
	db TX_END

.PostBattleAdviceText:
	db TX_FAR
	dw _VermilionGymLTSurgePostBattleAdviceText
	db BANK(_VermilionGymLTSurgePostBattleAdviceText)
