CopycatsHouse2F_TextPointers:
	dw CopycatsHouse2FCopycatText
DEF TEXT_COPYCATSHOUSE2F_COPYCAT EQU 1
	dw CopycatsHouse2FDoduoText
DEF TEXT_COPYCATSHOUSE2F_DODUO EQU 2
	dw CopycatsHouse2FRareDollText
DEF TEXT_COPYCATSHOUSE2F_MONSTER EQU 3
	dw CopycatsHouse2FRareDollText
DEF TEXT_COPYCATSHOUSE2F_BIRD EQU 4
	dw CopycatsHouse2FRareDollText
DEF TEXT_COPYCATSHOUSE2F_FAIRY EQU 5
	dw CopycatsHouse2FSNESText
DEF TEXT_COPYCATSHOUSE2F_SNES EQU 6
	dw CopycatsHouse2FPCText
DEF TEXT_COPYCATSHOUSE2F_PC EQU 7

;@ path: scripts/CopycatsHouse2F
;@ def CopycatsHouse2FCopycatText() -> hl
;@ Copycat: if the player brings a Poké Doll she swaps it for TM31 (MIMIC), if the bag has room.
;@ test: skip a text script: the code after text_asm is run by the text engine
CopycatsHouse2FCopycatText:
	db TX_START_ASM
;> if event(EVENT_GOT_TM31):
	ld a, [wEventFlags + $68]
	bit (EVENT_GOT_TM31) % 8, a
;>     PrintText(CopycatsHouse2FCopycatText.TM31Explanation2Text)
;>     return TextScriptEnd()
	jr nz, .got_item
;> wDoNotWaitForButtonPressAfterDisplayingText = TRUE
	ld a, TRUE
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> PrintText(CopycatsHouse2FCopycatText.DoYouLikePokemonText)
	ld hl, .DoYouLikePokemonText
	call PrintText
;> if IsItemInBag(POKE_DOLL):                  # zero flag: no Poké Doll
	ld b, POKE_DOLL
	call IsItemInBag
;>     return TextScriptEnd()
	jr z, .done
;> PrintText(CopycatsHouse2FCopycatText.TM31PreReceiveText)
	ld hl, .TM31PreReceiveText
	call PrintText
;> if GiveItem(TM_MIMIC, 1):
	ld bc, ((TM_MIMIC) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>     PrintText(CopycatsHouse2FCopycatText.ReceivedTM31Text)
	ld hl, .ReceivedTM31Text
	call PrintText
;>     hItemToRemoveID = POKE_DOLL
	ld a, POKE_DOLL
	ldh [hItemToRemoveID], a
;>     RemoveItemByID()
	ld b, BANK(RemoveItemByID)
	ld hl, RemoveItemByID
	call Bankswitch
;>     set_event(EVENT_GOT_TM31)
	ld hl, wEventFlags + $68
	set (EVENT_GOT_TM31) % 8, [hl]
	jr .done
;> else:
.bag_full
;>     PrintText(CopycatsHouse2FCopycatText.TM31NoRoomText)
	ld hl, .TM31NoRoomText
	call PrintText
	jr .done
.got_item
	ld hl, .TM31Explanation2Text
	call PrintText
;> return TextScriptEnd()
.done
	jp TextScriptEnd

.DoYouLikePokemonText:
	db TX_FAR
	dw _CopycatsHouse2FCopycatDoYouLikePokemonText
	db BANK(_CopycatsHouse2FCopycatDoYouLikePokemonText)
