;@ path: scripts/CopycatsHouse2F
;@ def CopycatsHouse2FPCText() -> hl
;@ Copycat's PC: readable only from the front (facing up); from the side the player cannot see the screen.
;@ test: skip a text script: the code after text_asm is run by the text engine
CopycatsHouse2FPCText:
	db TX_START_ASM
;> if wSpritePlayerStateData1FacingDirection != SPRITE_FACING_UP:
;>     text = CopycatsHouse2FPCText.CantSeeText
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	ld hl, .CantSeeText
	jr nz, .notUp
;> else:
;>     text = CopycatsHouse2FPCText.MySecretsText
	ld hl, .MySecretsText
.notUp
;> PrintText(text)
;> return TextScriptEnd()
	call PrintText
	jp TextScriptEnd

.MySecretsText:
	db TX_FAR
	dw _CopycatsHouse2FPCMySecretsText
	db BANK(_CopycatsHouse2FPCMySecretsText)
	db TX_END

.CantSeeText:
	db TX_FAR
	dw _CopycatsHouse2FPCCantSeeText
	db BANK(_CopycatsHouse2FPCCantSeeText)
	db TX_END
