FightingDojo_h::
	db DOJO
	db $6, $5
	dw FightingDojo_Blocks
	dw FightingDojo_TextPointers
	dw FightingDojo_Script
	db 0
	dw FightingDojo_Object
;@ path: scripts/FightingDojo
;@ def FightingDojo_Script()
;@ The Fighting Dojo's map script: run the current step of the dojo's script (its trainers and the Karate Master).
FightingDojo_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wFightingDojoCurScript = ExecuteCurMapScriptInTable(wFightingDojoCurScript, FightingDojoTrainerHeaders, FightingDojo_ScriptPointers)
	ld hl, FightingDojoTrainerHeaders
	ld de, FightingDojo_ScriptPointers
	ld a, [wFightingDojoCurScript]
	call ExecuteCurMapScriptInTable
	ld [wFightingDojoCurScript], a
	ret

;@ path: scripts/FightingDojo
;@ def FightingDojoResetScripts()
;@ Back to the dojo's default step, with the controls given back.
FightingDojoResetScripts:
;> wJoyIgnore = 0
	xor a ; SCRIPT_FIGHTINGDOJO_DEFAULT
	ld [wJoyIgnore], a
;> wFightingDojoCurScript = SCRIPT_FIGHTINGDOJO_DEFAULT
	ld [wFightingDojoCurScript], a
;> wCurMapScript = SCRIPT_FIGHTINGDOJO_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/FightingDojo
FightingDojo_ScriptPointers:
	dw FightingDojoDefaultScript
DEF SCRIPT_FIGHTINGDOJO_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_FIGHTINGDOJO_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_FIGHTINGDOJO_END_BATTLE EQU 2
	dw FightingDojoKarateMasterPostBattleScript
DEF SCRIPT_FIGHTINGDOJO_KARATE_MASTER_POST_BATTLE EQU 3

;@ path: scripts/FightingDojo
;@ def FightingDojoDefaultScript()
;@ Every step until the dojo is beaten: the trainers watch for the player, and stepping on the square left of
;@ the Karate Master makes him turn and challenge the player.
FightingDojoDefaultScript:
;> if event(EVENT_DEFEATED_FIGHTING_DOJO):
	ld a, [wEventFlags + $6A]
	bit (EVENT_DEFEATED_FIGHTING_DOJO) % 8, a
;>     return
	ret nz
;> CheckFightingMapTrainers()
	call CheckFightingMapTrainers
;> if wTrainerHeaderFlagBit or event(EVENT_BEAT_KARATE_MASTER):
	ld a, [wTrainerHeaderFlagBit]
	and a
	ret nz
	ld a, [wEventFlags + $6A]
	bit (EVENT_BEAT_KARATE_MASTER) % 8, a
;>     return
	ret nz
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wSavedCoordIndex = 0
	ld [wSavedCoordIndex], a
;> if wYCoord != 3 or wXCoord != 4:
	ld a, [wYCoord]
	cp 3
	ret nz
	ld a, [wXCoord]
	cp 4
;>     return
	ret nz
;> wSavedCoordIndex = 1
	ld a, 1
	ld [wSavedCoordIndex], a
;> wPlayerMovingDirection = PLAYER_DIR_RIGHT
	ld a, PLAYER_DIR_RIGHT
	ld [wPlayerMovingDirection], a
;> hSpriteIndex = FIGHTINGDOJO_KARATE_MASTER
	ld a, FIGHTINGDOJO_KARATE_MASTER
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_LEFT
	ld a, SPRITE_FACING_LEFT
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hTextID = TEXT_FIGHTINGDOJO_KARATE_MASTER
	ld a, TEXT_FIGHTINGDOJO_KARATE_MASTER
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
	ret

;@ path: scripts/FightingDojo
;@ def FightingDojoKarateMasterPostBattleScript()
;@ After the battle with the Karate Master: lost, start over; won, all the dojo's fighters count as beaten
;@ and he offers one of his Pokémon.
FightingDojoKarateMasterPostBattleScript:
;> if wIsInBattle == LOST_BATTLE:
	ld a, [wIsInBattle]
	cp LOST_BATTLE
;>     return FightingDojoResetScripts()
	jp z, FightingDojoResetScripts
;> if wSavedCoordIndex:                        # the player stood left of him: face each other again
	ld a, [wSavedCoordIndex]
	and a ; nz if the player was at (4, 3), left of the Karate Master
	jr z, .already_facing
;>     wPlayerMovingDirection = PLAYER_DIR_RIGHT
	ld a, PLAYER_DIR_RIGHT
	ld [wPlayerMovingDirection], a
;>     hSpriteIndex = FIGHTINGDOJO_KARATE_MASTER
	ld a, FIGHTINGDOJO_KARATE_MASTER
	ldh [hSpriteIndex], a
;>     hSpriteFacingDirection = SPRITE_FACING_LEFT
	ld a, SPRITE_FACING_LEFT
	ldh [hSpriteFacingDirection], a
;>     SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> wJoyIgnore = PAD_CTRL_PAD
.already_facing
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> for e in range(EVENT_BEAT_KARATE_MASTER, EVENT_BEAT_FIGHTING_DOJO_TRAINER_3 + 1):
	ld a, [wEventFlags + $6A]
	or (1 << (((EVENT_BEAT_FIGHTING_DOJO_TRAINER_3) % 8) + 1)) - (1 << ((EVENT_BEAT_KARATE_MASTER) % 8))
;>     set_event(e)
	ld [wEventFlags + $6A], a
;> hTextID = TEXT_FIGHTINGDOJO_KARATE_MASTER_I_WILL_GIVE_YOU_A_POKEMON
	ld a, TEXT_FIGHTINGDOJO_KARATE_MASTER_I_WILL_GIVE_YOU_A_POKEMON
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wJoyIgnore = 0
	xor a ; SCRIPT_FIGHTINGDOJO_DEFAULT
	ld [wJoyIgnore], a
;> wFightingDojoCurScript = SCRIPT_FIGHTINGDOJO_DEFAULT
	ld [wFightingDojoCurScript], a
;> wCurMapScript = SCRIPT_FIGHTINGDOJO_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/FightingDojo
FightingDojo_TextPointers:
	dw FightingDojoKarateMasterText
DEF TEXT_FIGHTINGDOJO_KARATE_MASTER EQU 1
	dw FightingDojoBlackbelt1Text
DEF TEXT_FIGHTINGDOJO_BLACKBELT1 EQU 2
	dw FightingDojoBlackbelt2Text
DEF TEXT_FIGHTINGDOJO_BLACKBELT2 EQU 3
	dw FightingDojoBlackbelt3Text
DEF TEXT_FIGHTINGDOJO_BLACKBELT3 EQU 4
	dw FightingDojoBlackbelt4Text
DEF TEXT_FIGHTINGDOJO_BLACKBELT4 EQU 5
