DEF TEXT_FIGHTINGDOJO_HITMONLEE_POKE_BALL EQU 6
	dw FightingDojoHitmonchanPokeBallText
DEF TEXT_FIGHTINGDOJO_HITMONCHAN_POKE_BALL EQU 7
	dw FightingDojoKarateMasterText.IWillGiveYouAPokemonText
DEF TEXT_FIGHTINGDOJO_KARATE_MASTER_I_WILL_GIVE_YOU_A_POKEMON EQU 8

