FightingDojoTrainerHeaders:
;@ path: scripts/FightingDojo
FightingDojoTrainerHeader0:
	db $2
	db 4 << 4
	dw wEventFlags + (EVENT_BEAT_FIGHTING_DOJO_TRAINER_0 - $2) / 8
	dw FightingDojoBlackbelt1BattleText, FightingDojoBlackbelt1AfterBattleText, FightingDojoBlackbelt1EndBattleText, FightingDojoBlackbelt1EndBattleText
;@ path: scripts/FightingDojo
FightingDojoTrainerHeader1:
	db $3
	db 4 << 4
	dw wEventFlags + (EVENT_BEAT_FIGHTING_DOJO_TRAINER_1 - $3) / 8
	dw FightingDojoBlackbelt2BattleText, FightingDojoBlackbelt2AfterBattleText, FightingDojoBlackbelt2EndBattleText, FightingDojoBlackbelt2EndBattleText
;@ path: scripts/FightingDojo
FightingDojoTrainerHeader2:
	db $4
	db 3 << 4
	dw wEventFlags + (EVENT_BEAT_FIGHTING_DOJO_TRAINER_2 - $4) / 8
	dw FightingDojoBlackbelt3BattleText, FightingDojoBlackbelt3AfterBattleText, FightingDojoBlackbelt3EndBattleText, FightingDojoBlackbelt3EndBattleText
;@ path: scripts/FightingDojo
FightingDojoTrainerHeader3:
	db $5
	db 3 << 4
	dw wEventFlags + (EVENT_BEAT_FIGHTING_DOJO_TRAINER_3 - $5) / 8
	dw FightingDojoBlackbelt4BattleText, FightingDojoBlackbelt4AfterBattleText, FightingDojoBlackbelt4EndBattleText, FightingDojoBlackbelt4EndBattleText
	db -1 ; end

;@ path: scripts/FightingDojo
;@ def FightingDojoKarateMasterText() -> hl
;@ The Karate Master: challenges the player; once beaten he offers a Pokémon, and once one is taken he
;@ invites the player to stay and train.
;@ test: skip a text script: the code after text_asm is run by the text engine
FightingDojoKarateMasterText:
	db TX_START_ASM
;> if event(EVENT_DEFEATED_FIGHTING_DOJO):
	ld a, [wEventFlags + $6A]
	bit (EVENT_DEFEATED_FIGHTING_DOJO) % 8, a
;>     PrintText(FightingDojoKarateMasterText.StayAndTrainWithUsText)
;> elif event(EVENT_BEAT_KARATE_MASTER):
	jp nz, .defeated_dojo
	bit (EVENT_BEAT_KARATE_MASTER) % 8, a
	jp nz, .defeated_master
;>     PrintText(FightingDojoKarateMasterText.IWillGiveYouAPokemonText)
;> else:
;>     PrintText(FightingDojoKarateMasterText.Text)
	ld hl, .Text
	call PrintText
;>     wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;>     SaveEndBattleTextPointers(FightingDojoKarateMasterText.DefeatedText, FightingDojoKarateMasterText.DefeatedText)
	ld hl, .DefeatedText
	ld de, .DefeatedText
	call SaveEndBattleTextPointers
;>     wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;>     EngageMapTrainer()
	call EngageMapTrainer
;>     InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;>     wFightingDojoCurScript = SCRIPT_FIGHTINGDOJO_KARATE_MASTER_POST_BATTLE
	ld a, SCRIPT_FIGHTINGDOJO_KARATE_MASTER_POST_BATTLE
	ld [wFightingDojoCurScript], a
;>     wCurMapScript = SCRIPT_FIGHTINGDOJO_KARATE_MASTER_POST_BATTLE
	ld [wCurMapScript], a
	jr .end
;> return TextScriptEnd()
.defeated_dojo
	ld hl, .StayAndTrainWithUsText
	call PrintText
	jr .end
.defeated_master
	ld hl, .IWillGiveYouAPokemonText
	call PrintText
.end
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _FightingDojoKarateMasterText
	db BANK(_FightingDojoKarateMasterText)
	db TX_END

.DefeatedText:
	db TX_FAR
	dw _FightingDojoKarateMasterDefeatedText
	db BANK(_FightingDojoKarateMasterDefeatedText)
	db TX_END

.IWillGiveYouAPokemonText:
	db TX_FAR
	dw _FightingDojoKarateMasterIWillGiveYouAPokemonText
	db BANK(_FightingDojoKarateMasterIWillGiveYouAPokemonText)
	db TX_END

.StayAndTrainWithUsText:
	db TX_FAR
	dw _FightingDojoKarateMasterStayAndTrainWithUsText
	db BANK(_FightingDojoKarateMasterStayAndTrainWithUsText)
	db TX_END

