;@ path: scripts/FightingDojo
;@ def FightingDojoHitmonleePokeBallText() -> hl
;@ The left Poké Ball: Hitmonlee's Pokédex page, then the offer; taken, the player gets it at level 30 and
;@ the other ball can no longer be taken.
;@ test: skip a text script: the code after text_asm is run by the text engine
FightingDojoHitmonleePokeBallText:
	db TX_START_ASM
;> if event(EVENT_GOT_HITMONLEE) or event(EVENT_GOT_HITMONCHAN):     # (in the same byte)
	ld a, [wEventFlags + ((EVENT_GOT_HITMONLEE) / 8)]
	and (1 << ((EVENT_GOT_HITMONLEE) % 8)) | (1 << ((EVENT_GOT_HITMONCHAN) % 8))
	jr z, .GetMon
;>     PrintText(FightingDojoBetterNotGetGreedyText)
	ld hl, FightingDojoBetterNotGetGreedyText
	call PrintText
;>     return TextScriptEnd()
	jr .done
.GetMon
;> DisplayPokedex(HITMONLEE)
	ld a, HITMONLEE
	call DisplayPokedex
;> PrintText(FightingDojoHitmonleePokeBallText.Text)
	ld hl, .Text
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if (wCurrentMenuItem == 0
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .done
;>         and GivePokemon(wCurPartySpecies, 30)):     # the species the Pokédex page set
	ld a, [wCurPartySpecies]
	ld b, a
	ld c, 30
	call GivePokemon
	jr nc, .done
;>     wToggleableObjectIndex = TOGGLE_FIGHTING_DOJO_GIFT_1

	; once Poké Ball is taken, hide sprite
	ld a, TOGGLE_FIGHTING_DOJO_GIFT_1
	ld [wToggleableObjectIndex], a
;>     HideObject()
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;>     set_event(EVENT_GOT_HITMONLEE)
	ld hl, wEventFlags + $6A
	set (EVENT_GOT_HITMONLEE) % 8, [hl]
;>     set_event(EVENT_DEFEATED_FIGHTING_DOJO)
	set (EVENT_DEFEATED_FIGHTING_DOJO) % 8, [hl]
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _FightingDojoHitmonleePokeBallText
	db BANK(_FightingDojoHitmonleePokeBallText)
	db TX_END

;@ path: scripts/FightingDojo
