	db OPP_BLACKBELT
	db 2
	db SPRITE_HIKER
	db 6 + 4
	db 3 + 4
	db STAY
	db RIGHT
	db TRAINER | TEXT_FIGHTINGDOJO_BLACKBELT2
	db OPP_BLACKBELT
	db 3
	db SPRITE_HIKER
	db 5 + 4
	db 5 + 4
