	dw (wOverworldMap + 7 + (FIGHTING_DOJO_WIDTH) + ((FIGHTING_DOJO_WIDTH) + 6) * (($B) >> 1) + ((4) >> 1))
	db $B, 4
	dw (wOverworldMap + 7 + (FIGHTING_DOJO_WIDTH) + ((FIGHTING_DOJO_WIDTH) + 6) * (($B) >> 1) + ((5) >> 1))
	db $B, 5
