FightingDojo_Blocks:
	db $49, $4a, $67, $49, $4a, $4b, $51, $05, $50, $4c, $4b, $05, $05, $05, $4c, $4b
	db $05, $05, $05, $4c, $4b, $32, $05, $31, $4c, $52, $46, $04, $46, $6f

SaffronGym_h::
	db FACILITY
	db $9, $A
	dw SaffronGym_Blocks
	dw SaffronGym_TextPointers
	dw SaffronGym_Script
	db 0
	dw SaffronGym_Object
;@ path: scripts/SaffronGym
;@ def SaffronGym_Script()
;@ Saffron Gym's map script: on entering, set the city and leader names (Saffron City, Sabrina) for the badge
;@ texts; then run the current step of the gym's script (its trainers and Sabrina).
;@ test: skip the names sit under local labels, which the pseudo-code can only name
SaffronGym_Script:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if loaded:
	call nz, .LoadNames
;>@e1     LoadGymLeaderAndCityName(SaffronGym_Script.CityName, SaffronGym_Script.LeaderName)
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSaffronGymCurScript = ExecuteCurMapScriptInTable(wSaffronGymCurScript, SaffronGymTrainerHeaders, SaffronGym_ScriptPointers)
	ld hl, SaffronGymTrainerHeaders
	ld de, SaffronGym_ScriptPointers
	ld a, [wSaffronGymCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSaffronGymCurScript], a
	ret

.LoadNames:
;=@e1
	ld hl, .CityName
	ld de, .LeaderName
	jp LoadGymLeaderAndCityName

.CityName:
	db "SAFFRON CITY@"

.LeaderName:
	db "SABRINA@"

;@ path: scripts/SaffronGym
;@ def SaffronGymResetScripts()
;@ Back to the gym's default step, with the controls given back.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
SaffronGymResetScripts:
;> wJoyIgnore = 0
	xor a ; SCRIPT_SAFFRONGYM_DEFAULT
	ld [wJoyIgnore], a
;> wSaffronGymCurScript = SCRIPT_SAFFRONGYM_DEFAULT
	ld [wSaffronGymCurScript], a
;> wCurMapScript = SCRIPT_SAFFRONGYM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/SaffronGym
SaffronGym_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_SAFFRONGYM_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_SAFFRONGYM_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_SAFFRONGYM_END_BATTLE EQU 2
	dw SaffronGymSabrinaPostBattle
DEF SCRIPT_SAFFRONGYM_SABRINA_POST_BATTLE EQU 3

;@ path: scripts/SaffronGym
;@ def SaffronGymSabrinaPostBattle()
;@ After the battle with Sabrina: lost, start over; won, go on to the badge and TM46.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
SaffronGymSabrinaPostBattle:
;> if wIsInBattle == LOST_BATTLE:
;>     return SaffronGymResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, SaffronGymResetScripts
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a

;> return SaffronGymSabrinaReceiveTM46Script()

;@ path: scripts/SaffronGym
;@ def SaffronGymSabrinaReceiveTM46Script()
;@ Sabrina's reward: the Marsh Badge text, TM46 (PSYWAVE) if the bag has room, the badge, and the gym's
;@ trainers no longer battle.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
SaffronGymSabrinaReceiveTM46Script:
;> hTextID = TEXT_SAFFRONGYM_SABRINA_MARSH_BADGE_INFO
	ld a, TEXT_SAFFRONGYM_SABRINA_MARSH_BADGE_INFO
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_BEAT_SABRINA)
	ld hl, wEventFlags + $6C
	set (EVENT_BEAT_SABRINA) % 8, [hl]
;> if GiveItem(TM_PSYWAVE, 1):
	ld bc, ((TM_PSYWAVE) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .BagFull
;>     hTextID = TEXT_SAFFRONGYM_SABRINA_RECEIVED_TM46
	ld a, TEXT_SAFFRONGYM_SABRINA_RECEIVED_TM46
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     set_event(EVENT_GOT_TM46)
	ld hl, wEventFlags + $6C
	set (EVENT_GOT_TM46) % 8, [hl]
	jr .gymVictory
.BagFull
;> else:
;>     hTextID = TEXT_SAFFRONGYM_SABRINA_TM46_NO_ROOM
	ld a, TEXT_SAFFRONGYM_SABRINA_TM46_NO_ROOM
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
.gymVictory
;> wObtainedBadges |= 1 << BIT_MARSHBADGE
	ld hl, wObtainedBadges
	set BIT_MARSHBADGE, [hl]
;> wBeatGymFlags |= 1 << BIT_MARSHBADGE
	ld hl, wBeatGymFlags
	set BIT_MARSHBADGE, [hl]

;> for e in range(EVENT_BEAT_SAFFRON_GYM_TRAINER_0, EVENT_BEAT_SAFFRON_GYM_TRAINER_6 + 1):
	; deactivate gym trainers
	ld a, [wEventFlags + $6C]
;>     set_event(e)
	or $ff - ((1 << ((EVENT_BEAT_SAFFRON_GYM_TRAINER_0) % 8)) - 1)
	ld [wEventFlags + $6C], a
	ld hl, wEventFlags + $6D
	set 0, [hl]

;> return SaffronGymResetScripts()
	jp SaffronGymResetScripts

;@ path: scripts/SaffronGym
SaffronGym_TextPointers:
	dw SaffronGymSabrinaText
DEF TEXT_SAFFRONGYM_SABRINA EQU 1
	dw SaffronGymChanneler1Text
DEF TEXT_SAFFRONGYM_CHANNELER1 EQU 2
	dw SaffronGymYoungster1Text
DEF TEXT_SAFFRONGYM_YOUNGSTER1 EQU 3
	dw SaffronGymChanneler2Text
DEF TEXT_SAFFRONGYM_CHANNELER2 EQU 4
	dw SaffronGymYoungster2Text
DEF TEXT_SAFFRONGYM_YOUNGSTER2 EQU 5
	dw SaffronGymChanneler3Text
DEF TEXT_SAFFRONGYM_CHANNELER3 EQU 6
	dw SaffronGymYoungster3Text
DEF TEXT_SAFFRONGYM_YOUNGSTER3 EQU 7
	dw SaffronGymYoungster4Text
DEF TEXT_SAFFRONGYM_YOUNGSTER4 EQU 8
	dw SaffronGymGymGuideText
DEF TEXT_SAFFRONGYM_GYM_GUIDE EQU 9
	dw SaffronGymSabrinaMarshBadgeInfoText
DEF TEXT_SAFFRONGYM_SABRINA_MARSH_BADGE_INFO EQU $A
	dw SaffronGymSabrinaReceivedTM46Text
DEF TEXT_SAFFRONGYM_SABRINA_RECEIVED_TM46 EQU $B
