;@ path: scripts/SaffronGym
;@ def SaffronGymSabrinaText() -> hl
;@ Sabrina: before the battle her challenge (and she engages the player); after it, TM46 if the bag had no
;@ room before, otherwise her advice.
;@ test: skip a text script: the code after text_asm is run by the text engine
SaffronGymSabrinaText:
	db TX_START_ASM
;> if event(EVENT_BEAT_SABRINA):
	ld a, [wEventFlags + $6C]
	bit (EVENT_BEAT_SABRINA) % 8, a
	jr z, .beforeBeat
;>     if event(EVENT_GOT_TM46):
;>@advice         PrintText(SaffronGymSabrinaText.PostBattleAdviceText)
	bit (EVENT_GOT_TM46) % 8, a
	jr nz, .afterBeat
;>     else:                                # the bag had no room for it after the battle
;>         SaffronGymSabrinaReceiveTM46Script()
	call z, SaffronGymSabrinaReceiveTM46Script
;>         DisableWaitingAfterTextDisplay()
	call DisableWaitingAfterTextDisplay
	jr .done
.afterBeat
;=@advice
	ld hl, .PostBattleAdviceText
	call PrintText
	jr .done
.beforeBeat
;> else:
;>     PrintText(SaffronGymSabrinaText.Text)
	ld hl, .Text
	call PrintText
;>     wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;>     SaveEndBattleTextPointers(SaffronGymSabrinaText.ReceivedMarshBadgeText, SaffronGymSabrinaText.ReceivedMarshBadgeText)
	ld hl, .ReceivedMarshBadgeText
	ld de, .ReceivedMarshBadgeText
	call SaveEndBattleTextPointers
;>     wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;>     EngageMapTrainer()
	call EngageMapTrainer
;>     InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;>     wGymLeaderNo = 6
	ld a, $6
	ld [wGymLeaderNo], a
;>     wSaffronGymCurScript = SCRIPT_SAFFRONGYM_SABRINA_POST_BATTLE
	ld a, SCRIPT_SAFFRONGYM_SABRINA_POST_BATTLE
	ld [wSaffronGymCurScript], a
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _SaffronGymSabrinaText
	db BANK(_SaffronGymSabrinaText)
	db TX_END

.ReceivedMarshBadgeText:
	db TX_FAR
	dw _SaffronGymSabrinaReceivedMarshBadgeText
	db BANK(_SaffronGymSabrinaReceivedMarshBadgeText)
	; actually plays the second channel of SFX_BALL_POOF due to the wrong music bank being loaded
	db TX_SOUND_GET_KEY_ITEM
	db TX_PROMPT_BUTTON
	db TX_END

.PostBattleAdviceText:
	db TX_FAR
	dw _SaffronGymSabrinaPostBattleAdviceText
	db BANK(_SaffronGymSabrinaPostBattleAdviceText)
	db TX_END

