;@ The gym guide: "you're a champ in the making" - after Sabrina is beaten, praise for the player.
;@ test: skip a text script: the code after text_asm is run by the text engine
SaffronGymGymGuideText:
	db TX_START_ASM
;> if not event(EVENT_BEAT_SABRINA):
	ld a, [wEventFlags + $6C]
	bit (EVENT_BEAT_SABRINA) % 8, a
	jr nz, .afterBeat
;>     PrintText(SaffronGymGymGuideText.ChampInMakingText)
	ld hl, .ChampInMakingText
	call PrintText
	jr .done
.afterBeat
;> else:
;>     PrintText(SaffronGymGymGuideText.BeatSabrinaText)
	ld hl, .BeatSabrinaText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

