;@ path: scripts/SilphCo1F
;@ def SilphCo1F_Script()
;@ Silph Co.'s lobby: once Giovanni has been beaten, the receptionist is back at her desk.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
SilphCo1F_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> if not event(EVENT_BEAT_SILPH_CO_GIOVANNI):
;>     return
	ld a, [wEventFlags + $F1]
	bit (EVENT_BEAT_SILPH_CO_GIOVANNI) % 8, a
	ret z
;> back = event(EVENT_SILPH_CO_RECEPTIONIST_AT_DESK)
	ld hl, wEventFlags + $72
	bit (EVENT_SILPH_CO_RECEPTIONIST_AT_DESK) % 8, [hl]
;> set_event(EVENT_SILPH_CO_RECEPTIONIST_AT_DESK)
	set (EVENT_SILPH_CO_RECEPTIONIST_AT_DESK) % 8, [hl]
;> if back:
;>     return
	ret nz
;> wToggleableObjectIndex = TOGGLE_SILPH_CO_1F_RECEPTIONIST
	ld a, TOGGLE_SILPH_CO_1F_RECEPTIONIST
	ld [wToggleableObjectIndex], a
;> return predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	jp Predef

