;@ path: scripts/Route2Gate
;@ def Route2Gate_Script()
;@ Route 2 Gate's map script: only lets texts draw their box.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
Route2Gate_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/Route2Gate
Route2Gate_TextPointers:
	dw Route2GateOaksAideText
DEF TEXT_ROUTE2GATE_OAKS_AIDE EQU 1
	dw Route2GateYoungsterText
DEF TEXT_ROUTE2GATE_YOUNGSTER EQU 2

;@ path: scripts/Route2Gate
;@ def Route2GateOaksAideText() -> hl
;@ Oak's aide in the Route 2 gate: once 10 kinds of Pokémon are registered as owned, he gives HM05 (FLASH),
;@ and then explains it.
;@ test: skip a text script: the code after text_asm is run by the text engine
Route2GateOaksAideText:
	db TX_START_ASM
;> if not event(EVENT_GOT_HM05):
	ld a, [wEventFlags + $7B]
	bit (EVENT_GOT_HM05) % 8, a
	jr nz, .got_item
;>     hOaksAideRequirement = 10
	ld a, 10
	ldh [hOaksAideRequirement], a
;>     hOaksAideRewardItem = wNamedObjectIndex = HM_FLASH
	ld a, HM_FLASH
	ldh [hOaksAideRewardItem], a
	ld [wNamedObjectIndex], a
;>     GetItemName()
	call GetItemName
;>     CopyData(addr(wNameBuffer), addr(wOaksAideRewardItemName), ITEM_NAME_LENGTH)
	ld hl, wNameBuffer
	ld de, wOaksAideRewardItemName
	ld bc, ITEM_NAME_LENGTH
	call CopyData
;>     predef(OaksAideScript)
	ld a, (OaksAideScriptPredef - PredefPointers) / 3
	call Predef
;>     if hOaksAideResult != OAKS_AIDE_GOT_ITEM:
;>         return TextScriptEnd()
	ldh a, [hOaksAideResult]
	cp OAKS_AIDE_GOT_ITEM
	jr nz, .no_item
;>     set_event(EVENT_GOT_HM05)
	ld hl, wEventFlags + $7B
	set (EVENT_GOT_HM05) % 8, [hl]
.got_item
;> PrintText(Route2GateOaksAideText.FlashExplanationText)
	ld hl, .FlashExplanationText
	call PrintText
.no_item
;> return TextScriptEnd()
	jp TextScriptEnd

.FlashExplanationText:
	db TX_FAR
	dw _Route2GateOaksAideFlashExplanationText
	db BANK(_Route2GateOaksAideFlashExplanationText)
	db TX_END

;@ path: scripts/Route2Gate
Route2GateYoungsterText:
	db TX_FAR
	dw _Route2GateYoungsterText
	db BANK(_Route2GateYoungsterText)
	db TX_END
DEF ROUTE2GATE_OAKS_AIDE EQU 1
	EXPORT ROUTE2GATE_OAKS_AIDE
DEF ROUTE2GATE_YOUNGSTER EQU 2
	EXPORT ROUTE2GATE_YOUNGSTER

;@ path: data/maps/objects/Route2Gate
Route2Gate_Object:
	db $a ; border block

	db 4
	db 0, 4, 4 - 1, LAST_MAP
	db 0, 5, 4 - 1, LAST_MAP
	db 7, 4, 5 - 1, LAST_MAP
	db 7, 5, 5 - 1, LAST_MAP

	db 0

	db 2
	db SPRITE_SCIENTIST
	db 4 + 4
	db 1 + 4
	db STAY
	db LEFT
	db TEXT_ROUTE2GATE_OAKS_AIDE
	db SPRITE_YOUNGSTER
	db 4 + 4
	db 5 + 4
	db WALK
	db LEFT_RIGHT
	db TEXT_ROUTE2GATE_YOUNGSTER

	dw (wOverworldMap + 7 + (ROUTE_2_GATE_WIDTH) + ((ROUTE_2_GATE_WIDTH) + 6) * ((0) >> 1) + ((4) >> 1))
	db 0, 4
	dw (wOverworldMap + 7 + (ROUTE_2_GATE_WIDTH) + ((ROUTE_2_GATE_WIDTH) + 6) * ((0) >> 1) + ((5) >> 1))
	db 0, 5
	dw (wOverworldMap + 7 + (ROUTE_2_GATE_WIDTH) + ((ROUTE_2_GATE_WIDTH) + 6) * ((7) >> 1) + ((4) >> 1))
	db 7, 4
	dw (wOverworldMap + 7 + (ROUTE_2_GATE_WIDTH) + ((ROUTE_2_GATE_WIDTH) + 6) * ((7) >> 1) + ((5) >> 1))
	db 7, 5

