;@ path: scripts/SilphCo9F
;@ def SilphCo9F_Script()
;@ Silph Co. 9F's map script: first the map callback (SilphCo9FGateCallbackScript), then run the current step of the map's script (its trainers).
;@ test: skip runs SilphCo9FGateCallbackScript, whose data sits under a local label
SilphCo9F_Script:
;> SilphCo9FGateCallbackScript()
	call SilphCo9FGateCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSilphCo9FCurScript = ExecuteCurMapScriptInTable(wSilphCo9FCurScript, SilphCo9TrainerHeaders, SilphCo9F_ScriptPointers)
	ld hl, SilphCo9TrainerHeaders
	ld de, SilphCo9F_ScriptPointers
	ld a, [wSilphCo9FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSilphCo9FCurScript], a
	ret

;@ path: scripts/SilphCo9F
;@ def SilphCo9FGateCallbackScript()
;@ On entering the floor: if a card-key door here was just opened, note it, then draw each of the four doors
;@ still locked into the map.
;@ test: skip the door list sits under a local label, which the pseudo-code can only name
SilphCo9FGateCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> SilphCo9F_SetCardKeyDoorYScript(SilphCo9FGateCallbackScript.GateCoordinates)
	ld hl, .GateCoordinates
	call SilphCo9F_SetCardKeyDoorYScript
;> SilphCo9F_SetUnlockedSilphCoDoorsScript()
	call SilphCo9F_SetUnlockedSilphCoDoorsScript
;> if not event(EVENT_SILPH_CO_9_UNLOCKED_DOOR1):     # door 1 still locked
	ld a, [wEventFlags + $ED]
	bit (EVENT_SILPH_CO_9_UNLOCKED_DOOR1) % 8, a
	jr nz, .unlock_door1
;>     wNewTileBlockID = 0x5F
	push af
	ld a, $5f
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=4 << 8 | 1)        # at row 4, column 1
	ld bc, ((4) & $ff) << 8 + ((1) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	pop af
.unlock_door1
;> if not event(EVENT_SILPH_CO_9_UNLOCKED_DOOR2):
	bit (EVENT_SILPH_CO_9_UNLOCKED_DOOR2) % 8, a
	jr nz, .unlock_door2
;>     wNewTileBlockID = 0x54
	push af
	ld a, $54
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=2 << 8 | 9)
	ld bc, ((2) & $ff) << 8 + ((9) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	pop af
.unlock_door2
;> if not event(EVENT_SILPH_CO_9_UNLOCKED_DOOR3):
	bit (EVENT_SILPH_CO_9_UNLOCKED_DOOR3) % 8, a
	jr nz, .unlock_door3
;>     wNewTileBlockID = 0x54
	push af
	ld a, $54
	ld [wNewTileBlockID], a
;>     predef(ReplaceTileBlock, bc=5 << 8 | 9)
	ld bc, ((5) & $ff) << 8 + ((9) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
	pop af
.unlock_door3
;> if event(EVENT_SILPH_CO_9_UNLOCKED_DOOR4):
;>     return
	bit (EVENT_SILPH_CO_9_UNLOCKED_DOOR4) % 8, a
	ret nz
;> wNewTileBlockID = 0x5F
	ld a, $5f
	ld [wNewTileBlockID], a
;> return predef(ReplaceTileBlock, bc=6 << 8 | 5)
	ld bc, ((6) & $ff) << 8 + ((5) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

.GateCoordinates:
	db 4, 1
	db 2, 9
	db 5, 9
	db 6, 5
	db -1 ; end

;@ path: scripts/SilphCo9F
;@ def SilphCo9F_SetCardKeyDoorYScript(doors: hl)
;@ Look up the door the card key just opened (wCardKeyDoorY/X) in the floor's door list: hUnlockedSilphCoDoors
;@ becomes its number (1, 2...) and the opened door is forgotten; 0 if it is not one of them.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
SilphCo9F_SetCardKeyDoorYScript:
;> y = wCardKeyDoorY
	push hl
	ld hl, wCardKeyDoorY
	ld a, [hli]
	ld b, a
;> x = wCardKeyDoorX
	ld a, [hl]
	ld c, a
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
;> while mem[doors] != 0xFF:
	pop hl
.loop_card_key_doors
	ld a, [hli]
	cp $ff
	jr z, .exit_loop
;>     hUnlockedSilphCoDoors += 1
	push hl
	ld hl, hUnlockedSilphCoDoors
	inc [hl]
	pop hl
;>@match     if mem[doors] == y and mem[doors + 1] == x:
	cp b
	jr z, .check_door
;>@clear         wCardKeyDoorY = wCardKeyDoorX = 0
;>@ret         return
;>     doors += 2
	inc hl
	jr .loop_card_key_doors
.check_door
;=@match
	ld a, [hli]
	cp c
	jr nz, .loop_card_key_doors
;=@clear
	ld hl, wCardKeyDoorY
	xor a
	ld [hli], a
	ld [hl], a
;=@ret
	ret
.exit_loop
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
	ret

;@ path: scripts/SilphCo9F
;@ def SilphCo9F_SetUnlockedSilphCoDoorsScript()
;@ Note the door the card key just opened (door 1 to 4 of this floor) as an event.
;@ test: hLoadedROMBank = 0x17    # the bank this code runs in
SilphCo9F_SetUnlockedSilphCoDoorsScript:
;> n = hUnlockedSilphCoDoors              # 0: no door opened (hl: the byte with the door flags)
	ld hl, wEventFlags + $ED
	ldh a, [hUnlockedSilphCoDoors]
;> if n == 0:
;>     return
	and a
	ret z
;> if n == 1:
	cp $1
	jr nz, .unlock_door1
;>     set_event(EVENT_SILPH_CO_9_UNLOCKED_DOOR1)
	set (EVENT_SILPH_CO_9_UNLOCKED_DOOR1) % 8, [hl]
;>     return
	ret
.unlock_door1
;> if n == 2:
	cp $2
	jr nz, .unlock_door2
;>     set_event(EVENT_SILPH_CO_9_UNLOCKED_DOOR2)
	set (EVENT_SILPH_CO_9_UNLOCKED_DOOR2) % 8, [hl]
;>     return
	ret
.unlock_door2
;> if n == 3:
	cp $3
	jr nz, .unlock_door3
;>     set_event(EVENT_SILPH_CO_9_UNLOCKED_DOOR3)
	set (EVENT_SILPH_CO_9_UNLOCKED_DOOR3) % 8, [hl]
;>     return
	ret
.unlock_door3
;> if n == 4:
	cp $4
	ret nz
;>     set_event(EVENT_SILPH_CO_9_UNLOCKED_DOOR4)
	set (EVENT_SILPH_CO_9_UNLOCKED_DOOR4) % 8, [hl]
	ret

