;@ path: scripts/SilphCo9F
;@ def SilphCo9FNurseText() -> hl
;@ The nurse hiding on 9F: while Team Rocket is here she heals the player's party; afterwards she thanks the
;@ player.
;@ test: skip a text script: the code after text_asm is run by the text engine
SilphCo9FNurseText:
	db TX_START_ASM
;> if event(EVENT_BEAT_SILPH_CO_GIOVANNI):
	ld a, [wEventFlags + $F1]
	bit (EVENT_BEAT_SILPH_CO_GIOVANNI) % 8, a
	jr nz, .beat_giovanni
;>@e1     PrintText(SilphCo9FNurseText.ThankYouText)
;>@e2     return TextScriptEnd()
;> PrintText(SilphCo9FNurseText.YouLookTiredText)
	ld hl, .YouLookTiredText
	call PrintText
;> predef(HealParty)
	ld a, (HealPartyPredef - PredefPointers) / 3
	call Predef
;> GBFadeOutToWhite()
	call GBFadeOutToWhite
;> Delay3()
	call Delay3
;> GBFadeInFromWhite()
	call GBFadeInFromWhite
;> PrintText(SilphCo9FNurseText.DontGiveUpText)
	ld hl, .DontGiveUpText
	call PrintText
	jr .text_script_end
.beat_giovanni
;=@e1
	ld hl, .ThankYouText
	call PrintText
;=@e2
.text_script_end
;> return TextScriptEnd()
	jp TextScriptEnd

.YouLookTiredText:
	db TX_FAR
	dw SilphCo9FNurseYouLookTiredText
	db BANK(SilphCo9FNurseYouLookTiredText)
	db TX_END

.DontGiveUpText:
	db TX_FAR
	dw SilphCo9FNurseDontGiveUpText
	db BANK(SilphCo9FNurseDontGiveUpText)
	db TX_END

.ThankYouText:
