VictoryRoad1F_h::
	db CAVERN
	db $9, $A
	dw VictoryRoad1F_Blocks
	dw VictoryRoad1F_TextPointers
	dw VictoryRoad1F_Script
	db 0
	dw VictoryRoad1F_Object
;@ path: scripts/VictoryRoad1F
;@ def VictoryRoad1F_Script()
;@ Victory Road 1F's map script: on entering, if a boulder sits on the switch, draw the opened passage (block
;@ $1D); then run the current step (the trainers, the switch).
;@ test: hLoadedROMBank = 0x17; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
VictoryRoad1F_Script:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if loaded:                              # (the local routine .next)
;>@sw     if event(EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH):
;>@blk         wNewTileBlockID = 0x1D
;>@rep         predef(ReplaceTileBlock, bc=6 << 8 | 4)
	call nz, .next
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wVictoryRoad1FCurScript = ExecuteCurMapScriptInTable(wVictoryRoad1FCurScript, VictoryRoad1TrainerHeaders, VictoryRoad1F_ScriptPointers)
	ld hl, VictoryRoad1TrainerHeaders
	ld de, VictoryRoad1F_ScriptPointers
	ld a, [wVictoryRoad1FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wVictoryRoad1FCurScript], a
	ret
.next
;=@sw
	ld a, [wEventFlags + $122]
	bit (EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH) % 8, a
	ret z
;=@blk
	ld a, $1d
	ld [wNewTileBlockID], a
;=@rep
	ld bc, ((6) & $ff) << 8 + ((4) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

