VictoryRoad1F_ScriptPointers:
	dw VictoryRoad1FDefaultScript
DEF SCRIPT_VICTORYROAD1F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_VICTORYROAD1F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_VICTORYROAD1F_END_BATTLE EQU 2

;@ path: scripts/VictoryRoad1F
;@ def VictoryRoad1FDefaultScript()
;@ A boulder pushed onto 1F's switch opens the passage (redrawn the next time the map script runs);
;@ otherwise the trainers watch for the player.
;@ test: skip the switch spot sits under a local label, which the pseudo-code can only name
VictoryRoad1FDefaultScript:
;> if event(EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH):
;>     return CheckFightingMapTrainers()
	ld a, [wEventFlags + $122]
	bit (EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH) % 8, a
	jp nz, CheckFightingMapTrainers
;> if not CheckBoulderCoords(VictoryRoad1FDefaultScript.SwitchCoords):   # no boulder on the switch
;>     return CheckFightingMapTrainers()
	ld hl, .SwitchCoords
	call CheckBoulderCoords
	jp nc, CheckFightingMapTrainers
;> wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1     # redraw the map
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
;> set_event(EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH)
	ld hl, wEventFlags + $122
	set (EVENT_VICTORY_ROAD_1_BOULDER_ON_SWITCH) % 8, [hl]
	ret

.SwitchCoords:
	db 13, 17
	db -1 ; end

