;@ path: scripts/VictoryRoad1F
VictoryRoad1TrainerHeader0:
	db $1
	db 2 << 4
	dw wEventFlags + (EVENT_BEAT_VICTORY_ROAD_1_TRAINER_0 - $1) / 8
	dw VictoryRoad1FCooltrainerFBattleText, VictoryRoad1FCooltrainerFAfterBattleText, VictoryRoad1FCooltrainerFEndBattleText, VictoryRoad1FCooltrainerFEndBattleText
;@ path: scripts/VictoryRoad1F
VictoryRoad1TrainerHeader1:
	db $2
	db 2 << 4
	dw wEventFlags + (EVENT_BEAT_VICTORY_ROAD_1_TRAINER_1 - $2) / 8
	dw VictoryRoad1FCooltrainerMBattleText, VictoryRoad1FCooltrainerMAfterBattleText, VictoryRoad1FCooltrainerMEndBattleText, VictoryRoad1FCooltrainerMEndBattleText
	db -1 ; end

;@ path: scripts/VictoryRoad1F
;@ def VictoryRoad1FCooltrainerFText() -> hl
;@ Cooltrainer F, a trainer in Victory Road 1F: the trainer talk and battle.
;@ test: skip a text script: the code after text_asm is run by the text engine
VictoryRoad1FCooltrainerFText:
	db TX_START_ASM
;> TalkToTrainer(VictoryRoad1TrainerHeader0)
;> return TextScriptEnd()
	ld hl, VictoryRoad1TrainerHeader0
	call TalkToTrainer
	jp TextScriptEnd

;@ path: scripts/VictoryRoad1F
;@ def VictoryRoad1FCooltrainerMText() -> hl
