VictoryRoad1FCooltrainerMText:
	db TX_START_ASM
;> TalkToTrainer(VictoryRoad1TrainerHeader1)
;> return TextScriptEnd()
	ld hl, VictoryRoad1TrainerHeader1
	call TalkToTrainer
	jp TextScriptEnd

