	dw (wOverworldMap + 7 + (POKEMON_TOWER_1F_WIDTH) + ((POKEMON_TOWER_1F_WIDTH) + 6) * (($11) >> 1) + (($A) >> 1))
	db $11, $A
	dw (wOverworldMap + 7 + (POKEMON_TOWER_1F_WIDTH) + ((POKEMON_TOWER_1F_WIDTH) + 6) * (($11) >> 1) + (($B) >> 1))
	db $11, $B
	dw (wOverworldMap + 7 + (POKEMON_TOWER_1F_WIDTH) + ((POKEMON_TOWER_1F_WIDTH) + 6) * ((9) >> 1) + (($12) >> 1))
	db 9, $12
