PokemonTower1F_Blocks:
	db $01, $01, $01, $03, $0a, $06, $07, $03, $01, $01, $01, $01, $10, $06, $0e, $0e
	db $0e, $06, $08, $01, $01, $0c, $39, $0e, $0e, $0e, $0e, $0e, $20, $0d, $01, $0a
	db $0e, $0e, $0e, $0e, $0e, $0e, $0e, $07, $01, $39, $0e, $0e, $0e, $0e, $0e, $0e
	db $0e, $12, $01, $1c, $0e, $0e, $0e, $0e, $0e, $0e, $0e, $1e, $01, $0c, $0e, $0e
	db $0e, $0e, $25, $3f, $3f, $0d, $01, $01, $14, $0e, $0e, $0e, $25, $0e, $0b, $01
	db $01, $01, $01, $05, $1c, $0e, $1e, $05, $01, $01

PokemonTower2F_h::
	db CEMETERY
	db $9, $A
	dw PokemonTower2F_Blocks
	dw PokemonTower2F_TextPointers
	dw PokemonTower2F_Script
	db 0
	dw PokemonTower2F_Object
;@ path: scripts/PokemonTower2F
;@ def PokemonTower2F_Script()
;@ Pokémon Tower 2F's map script: run the current step (the rival battle).
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower2F_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wPokemonTower2FCurScript, PokemonTower2F_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld hl, PokemonTower2F_ScriptPointers
	ld a, [wPokemonTower2FCurScript]
	jp CallFunctionInTable

;@ path: scripts/PokemonTower2F
;@ def PokemonTower2FResetRivalEncounter()
;@ Back to the default step (after a lost battle), with the controls given back.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower2FResetRivalEncounter:
;> wJoyIgnore = 0
	xor a ; SCRIPT_POKEMONTOWER2F_DEFAULT
	ld [wJoyIgnore], a
;> wPokemonTower2FCurScript = SCRIPT_POKEMONTOWER2F_DEFAULT
	ld [wPokemonTower2FCurScript], a
;> wCurMapScript = SCRIPT_POKEMONTOWER2F_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/PokemonTower2F
PokemonTower2F_ScriptPointers:
	dw PokemonTower2FDefaultScript
DEF SCRIPT_POKEMONTOWER2F_DEFAULT EQU 0
	dw PokemonTower2FDefeatedRivalScript
DEF SCRIPT_POKEMONTOWER2F_DEFEATED_RIVAL EQU 1
	dw PokemonTower2FRivalExitsScript
DEF SCRIPT_POKEMONTOWER2F_RIVAL_EXITS EQU 2

;@ path: scripts/PokemonTower2F
;@ def PokemonTower2FDefaultScript()
;@ Until the rival here is beaten, walking next to him plays his music; he turns to the player (who stands to
;@ his right or below him) and speaks.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower2FDefaultScript:
;> if event(EVENT_BEAT_POKEMON_TOWER_RIVAL) or not ArePlayerCoordsInArray(PokemonTower2FRivalEncounterEventCoords):
;>     return
	ld a, [wEventFlags + $1D]
	bit (EVENT_BEAT_POKEMON_TOWER_RIVAL) % 8, a
	ret nz
	ld hl, PokemonTower2FRivalEncounterEventCoords
	call ArePlayerCoordsInArray
	ret nc
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> PlayMusic(MUSIC_MEET_RIVAL, BANK(Music_MeetRival))
	ld c, BANK(Music_MeetRival)
	ld a, MUSIC_MEET_RIVAL
	call PlayMusic
;> reset_event(EVENT_POKEMON_TOWER_RIVAL_ON_LEFT)
	ld hl, wEventFlags + $1D
	res (EVENT_POKEMON_TOWER_RIVAL_ON_LEFT) % 8, [hl]
;> if wCoordIndex == 1:                          # the player is to the rival's right
	ld a, [wCoordIndex]
	cp $1
	ld a, PLAYER_DIR_UP
	ld b, SPRITE_FACING_DOWN
	jr nz, .player_below_rival
;>     set_event(EVENT_POKEMON_TOWER_RIVAL_ON_LEFT)
; the rival is on the left side and the player is on the right side
	ld hl, wEventFlags + $1D
	set (EVENT_POKEMON_TOWER_RIVAL_ON_LEFT) % 8, [hl]
;>     wPlayerMovingDirection = PLAYER_DIR_LEFT
	ld a, PLAYER_DIR_LEFT
;>     hSpriteFacingDirection = SPRITE_FACING_RIGHT
	ld b, SPRITE_FACING_RIGHT
.player_below_rival
;> else:                                         # the player is below him
;>     wPlayerMovingDirection = PLAYER_DIR_UP
	ld [wPlayerMovingDirection], a
;>     hSpriteFacingDirection = SPRITE_FACING_DOWN
;> hSpriteIndex = POKEMONTOWER2F_RIVAL
	ld a, POKEMONTOWER2F_RIVAL
	ldh [hSpriteIndex], a
;> SetSpriteFacingDirectionAndDelay()
	ld a, b
	ldh [hSpriteFacingDirection], a
	call SetSpriteFacingDirectionAndDelay
;> hTextID = TEXT_POKEMONTOWER2F_RIVAL
	ld a, TEXT_POKEMONTOWER2F_RIVAL
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hJoyHeld = hJoyPressed = 0
	xor a
	ldh [hJoyHeld], a
	ldh [hJoyPressed], a
	ret

;@ path: scripts/PokemonTower2F
PokemonTower2FRivalEncounterEventCoords:
	db 5, 15
	db 6, 14
	db $0F ; end? (should be $ff?)

;@ path: scripts/PokemonTower2F
;@ def PokemonTower2FDefeatedRivalScript()
;@ After the battle with the rival: lost, start over; won, his parting words, his tune, and he walks off
;@ (around the player).
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower2FDefeatedRivalScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return PokemonTower2FResetRivalEncounter()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, PokemonTower2FResetRivalEncounter
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> set_event(EVENT_BEAT_POKEMON_TOWER_RIVAL)
	ld hl, wEventFlags + $1D
	set (EVENT_BEAT_POKEMON_TOWER_RIVAL) % 8, [hl]
;> hTextID = TEXT_POKEMONTOWER2F_RIVAL
	ld a, TEXT_POKEMONTOWER2F_RIVAL
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> if event(EVENT_POKEMON_TOWER_RIVAL_ON_LEFT):
;>     moves = PokemonTower2FRivalDownThenRightMovement
	ld de, PokemonTower2FRivalDownThenRightMovement
	ld a, [wEventFlags + $1D]
	bit (EVENT_POKEMON_TOWER_RIVAL_ON_LEFT) % 8, a
	jr nz, .got_movement
;> else:
;>     moves = PokemonTower2FRivalRightThenDownMovement
	ld de, PokemonTower2FRivalRightThenDownMovement
.got_movement
;> hSpriteIndex = POKEMONTOWER2F_RIVAL
	ld a, POKEMONTOWER2F_RIVAL
	ldh [hSpriteIndex], a
;> MoveSprite(moves)
	call MoveSprite
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> farcall(Music_RivalAlternateStart)
	ld b, BANK(Music_RivalAlternateStart)
	ld hl, Music_RivalAlternateStart
	call Bankswitch
;> wPokemonTower2FCurScript = SCRIPT_POKEMONTOWER2F_RIVAL_EXITS
	ld a, SCRIPT_POKEMONTOWER2F_RIVAL_EXITS
	ld [wPokemonTower2FCurScript], a
;> wCurMapScript = SCRIPT_POKEMONTOWER2F_RIVAL_EXITS
	ld [wCurMapScript], a
	ret

;@ path: scripts/PokemonTower2F
PokemonTower2FRivalRightThenDownMovement:
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db -1 ; end

;@ path: scripts/PokemonTower2F
PokemonTower2FRivalDownThenRightMovement:
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db -1 ; end

;@ path: scripts/PokemonTower2F
;@ def PokemonTower2FRivalExitsScript()
;@ When the rival has walked off: hide him, give the controls back and restore the map music.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower2FRivalExitsScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> wToggleableObjectIndex = TOGGLE_POKEMON_TOWER_2F_RIVAL
	ld a, TOGGLE_POKEMON_TOWER_2F_RIVAL
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> PlayDefaultMusic()
	call PlayDefaultMusic
;> wPokemonTower2FCurScript = SCRIPT_POKEMONTOWER2F_DEFAULT
	ld a, SCRIPT_POKEMONTOWER2F_DEFAULT
	ld [wPokemonTower2FCurScript], a
;> wCurMapScript = SCRIPT_POKEMONTOWER2F_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/PokemonTower2F
PokemonTower2F_TextPointers:
	dw PokemonTower2FRivalText
DEF TEXT_POKEMONTOWER2F_RIVAL EQU 1
	dw PokemonTower2FChannelerText
DEF TEXT_POKEMONTOWER2F_CHANNELER EQU 2

;@ path: scripts/PokemonTower2F
;@ def PokemonTower2FRivalText() -> hl
;@ The rival in the tower: "What brings you here?" and the battle, with the team picked by his starter;
;@ afterwards he asks how the Pokédex is going.
;@ test: skip a text script: the code after text_asm is run by the text engine
PokemonTower2FRivalText:
	db TX_START_ASM
;> if event(EVENT_BEAT_POKEMON_TOWER_RIVAL):
	ld a, [wEventFlags + $1D]
	bit (EVENT_BEAT_POKEMON_TOWER_RIVAL) % 8, a
	jr z, .do_battle
;>     PrintText(PokemonTower2FRivalText.HowsYourDexText)
	ld hl, .HowsYourDexText
	call PrintText
;>     return TextScriptEnd()
	jr .text_script_end
.do_battle
;> PrintText(PokemonTower2FRivalText.WhatBringsYouHereText)
	ld hl, .WhatBringsYouHereText
	call PrintText
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(PokemonTower2FRivalText.DefeatedText, PokemonTower2FRivalText.VictoryText)
	ld hl, .DefeatedText
	ld de, .VictoryText
	call SaveEndBattleTextPointers
;> wCurOpponent = OPP_RIVAL2
	ld a, OPP_RIVAL2
	ld [wCurOpponent], a

;> if wRivalStarter == STARTER2:
	; select which team to use during the encounter
	ld a, [wRivalStarter]
	cp STARTER2
	jr nz, .NotSquirtle
;>     wTrainerNo = 4
	ld a, $4
	jr .done
.NotSquirtle
;> elif wRivalStarter == STARTER3:
	cp STARTER3
	jr nz, .Charmander
;>     wTrainerNo = 5
	ld a, $5
	jr .done
.Charmander
;> else:
;>     wTrainerNo = 6
	ld a, $6
.done
	ld [wTrainerNo], a

;> wPokemonTower2FCurScript = SCRIPT_POKEMONTOWER2F_DEFEATED_RIVAL
	ld a, SCRIPT_POKEMONTOWER2F_DEFEATED_RIVAL
	ld [wPokemonTower2FCurScript], a
;> wCurMapScript = SCRIPT_POKEMONTOWER2F_DEFEATED_RIVAL
	ld [wCurMapScript], a
.text_script_end
;> return TextScriptEnd()
	jp TextScriptEnd

.WhatBringsYouHereText:
	db TX_FAR
	dw _PokemonTower2FRivalWhatBringsYouHereText
	db BANK(_PokemonTower2FRivalWhatBringsYouHereText)
	db TX_END

.DefeatedText:
	db TX_FAR
	dw _PokemonTower2FRivalDefeatedText
	db BANK(_PokemonTower2FRivalDefeatedText)
	db TX_END

.VictoryText:
	db TX_FAR
	dw _PokemonTower2FRivalVictoryText
	db BANK(_PokemonTower2FRivalVictoryText)
	db TX_END

.HowsYourDexText:
