	dw (wOverworldMap + 7 + (POKEMON_TOWER_2F_WIDTH) + ((POKEMON_TOWER_2F_WIDTH) + 6) * ((9) >> 1) + ((3) >> 1))
	db 9, 3
	dw (wOverworldMap + 7 + (POKEMON_TOWER_2F_WIDTH) + ((POKEMON_TOWER_2F_WIDTH) + 6) * ((9) >> 1) + (($12) >> 1))
