	db $0e, $36, $52, $4c, $4c, $36, $0e, $07, $01, $15, $0e, $52, $52, $0e, $52, $52
	db $0e, $16, $01, $1c, $0e, $36, $52, $0e, $0e, $36, $0e, $1e, $01, $0c, $57, $52
