;@ Pokémon Tower 3F's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower3F_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wPokemonTower3FCurScript = ExecuteCurMapScriptInTable(wPokemonTower3FCurScript, PokemonTower3TrainerHeaders, PokemonTower3F_ScriptPointers)
	ld hl, PokemonTower3TrainerHeaders
	ld de, PokemonTower3F_ScriptPointers
