	dw PokemonTower5FDefaultScript
DEF SCRIPT_POKEMONTOWER5F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_POKEMONTOWER5F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_POKEMONTOWER5F_END_BATTLE EQU 2

;@ path: scripts/PokemonTower5F
;@ def PokemonTower5FDefaultScript()
;@ The purified zone on 5F: stepping in heals the party (once per visit to the zone) and no wild battles
;@ happen there; outside it the trainers watch for the player.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower5FDefaultScript:
;> if not ArePlayerCoordsInArray(PokemonTower5FPurifiedZoneCoords):
	ld hl, PokemonTower5FPurifiedZoneCoords
	call ArePlayerCoordsInArray
	jr c, .in_purified_zone
;>     wStatusFlags4 &= ~(1 << BIT_NO_BATTLES)
	ld hl, wStatusFlags4
	res BIT_NO_BATTLES, [hl]
;>     reset_event(EVENT_IN_PURIFIED_ZONE)
	ld hl, wEventFlags + $20
	res (EVENT_IN_PURIFIED_ZONE) % 8, [hl]
;>     return CheckFightingMapTrainers()
	jp CheckFightingMapTrainers
.in_purified_zone
;> inside = event(EVENT_IN_PURIFIED_ZONE)
	ld hl, wEventFlags + $20
	bit (EVENT_IN_PURIFIED_ZONE) % 8, [hl]
;> set_event(EVENT_IN_PURIFIED_ZONE)
	set (EVENT_IN_PURIFIED_ZONE) % 8, [hl]
;> if inside:
;>     return
	ret nz
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wStatusFlags4 |= 1 << BIT_NO_BATTLES
	ld hl, wStatusFlags4
	set BIT_NO_BATTLES, [hl]
;> predef(HealParty)
	ld a, (HealPartyPredef - PredefPointers) / 3
	call Predef
;> GBFadeOutToWhite()
	call GBFadeOutToWhite
;> Delay3()
	call Delay3
;> Delay3()
	call Delay3
;> GBFadeInFromWhite()
	call GBFadeInFromWhite
;> hTextID = TEXT_POKEMONTOWER5F_PURIFIEDZONE
	ld a, TEXT_POKEMONTOWER5F_PURIFIEDZONE
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
	ret

;@ path: scripts/PokemonTower5F
PokemonTower5FPurifiedZoneCoords:
	db 8, 10
	db 8, 11
	db 9, 10
	db 9, 11
	db -1 ; end

