;@ path: scripts/PokemonTower6F
;@ def PokemonTower6F_Script()
;@ Pokémon Tower 6F's map script: run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower6F_Script:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wPokemonTower6FCurScript = ExecuteCurMapScriptInTable(wPokemonTower6FCurScript, PokemonTower6TrainerHeaders, PokemonTower6F_ScriptPointers)
	ld hl, PokemonTower6TrainerHeaders
	ld de, PokemonTower6F_ScriptPointers
	ld a, [wPokemonTower6FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wPokemonTower6FCurScript], a
	ret

;@ path: scripts/PokemonTower6F
;@ def PokemonTower6FSetDefaultScript()
;@ Back to the default step (after a lost battle), with the controls given back.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower6FSetDefaultScript:
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wPokemonTower6FCurScript = SCRIPT_POKEMONTOWER6F_DEFAULT
	ld [wPokemonTower6FCurScript], a ; SCRIPT_POKEMONTOWER6F_DEFAULT
;> wCurMapScript = SCRIPT_POKEMONTOWER6F_DEFAULT
	ld [wCurMapScript], a ; SCRIPT_POKEMONTOWER6F_DEFAULT
	ret

;@ path: scripts/PokemonTower6F
PokemonTower6F_ScriptPointers:
	dw PokemonTower6FDefaultScript
DEF SCRIPT_POKEMONTOWER6F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_POKEMONTOWER6F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_POKEMONTOWER6F_END_BATTLE EQU 2
	dw PokemonTower6FPlayerMovingScript
DEF SCRIPT_POKEMONTOWER6F_PLAYER_MOVING EQU 3
	dw PokemonTower6FMarowakBattleScript
DEF SCRIPT_POKEMONTOWER6F_MAROWAK_BATTLE EQU 4

;@ path: scripts/PokemonTower6F
;@ def PokemonTower6FDefaultScript()
;@ Until the ghost is laid to rest, stepping onto its spot makes it cry "Be gone... Intruders..." and starts
;@ the battle with the level 30 ghost Marowak.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower6FDefaultScript:
;> if event(EVENT_BEAT_GHOST_MAROWAK) or not ArePlayerCoordsInArray(PokemonTower6FMarowakCoords):
;>     return CheckFightingMapTrainers()
	ld a, [wEventFlags + $21]
	bit (EVENT_BEAT_GHOST_MAROWAK) % 8, a
	jp nz, CheckFightingMapTrainers
	ld hl, PokemonTower6FMarowakCoords
	call ArePlayerCoordsInArray
	jp nc, CheckFightingMapTrainers
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hTextID = TEXT_POKEMONTOWER6F_BEGONE
	ld a, TEXT_POKEMONTOWER6F_BEGONE
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wCurOpponent = RESTLESS_SOUL
	ld a, RESTLESS_SOUL
	ld [wCurOpponent], a
;> wCurEnemyLevel = 30
	ld a, 30
	ld [wCurEnemyLevel], a
;> wPokemonTower6FCurScript = SCRIPT_POKEMONTOWER6F_MAROWAK_BATTLE
	ld a, SCRIPT_POKEMONTOWER6F_MAROWAK_BATTLE
	ld [wPokemonTower6FCurScript], a
;> wCurMapScript = SCRIPT_POKEMONTOWER6F_MAROWAK_BATTLE
	ld [wCurMapScript], a
	ret

;@ path: scripts/PokemonTower6F
PokemonTower6FMarowakCoords:
	db 16, 10
	db -1 ; end

;@ path: scripts/PokemonTower6F
;@ def PokemonTower6FMarowakBattleScript()
;@ After the ghost battle: lost, start over; won, the ghost - Cubone's mother - departs; otherwise (the
;@ player ran or had no Silph Scope) the player is pushed one step right.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower6FMarowakBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return PokemonTower6FSetDefaultScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, PokemonTower6FSetDefaultScript
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> if wStatusFlags3 >> BIT_TALKED_TO_TRAINER & 1:
;>     return
	ld a, [wStatusFlags3]
	bit BIT_TALKED_TO_TRAINER, a
	ret nz
;> UpdateSprites()
	call UpdateSprites
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> if not wBattleResult:                         # won
	ld a, [wBattleResult]
	and a
	jr nz, .did_not_defeat
;>     set_event(EVENT_BEAT_GHOST_MAROWAK)
	ld hl, wEventFlags + $21
	set (EVENT_BEAT_GHOST_MAROWAK) % 8, [hl]
;>     hTextID = TEXT_POKEMONTOWER6F_MAROWAK_DEPARTED
	ld a, TEXT_POKEMONTOWER6F_MAROWAK_DEPARTED
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;>     wPokemonTower6FCurScript = SCRIPT_POKEMONTOWER6F_DEFAULT
	ld a, SCRIPT_POKEMONTOWER6F_DEFAULT
	ld [wPokemonTower6FCurScript], a
;>     wCurMapScript = SCRIPT_POKEMONTOWER6F_DEFAULT
	ld [wCurMapScript], a
;>     return
	ret
.did_not_defeat
;> wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> wSimulatedJoypadStatesEnd = PAD_RIGHT
	ld a, PAD_RIGHT
	ld [wSimulatedJoypadStatesEnd], a
;> mem[wSpritePlayerStateData2MovementByte1] = 0
	xor a
	ld [wSpritePlayerStateData2MovementByte1], a
;> wOverrideSimulatedJoypadStatesMask = 0
	ld [wOverrideSimulatedJoypadStatesMask], a
;> wStatusFlags5 |= 1 << BIT_SCRIPTED_MOVEMENT_STATE
	ld hl, wStatusFlags5
	set BIT_SCRIPTED_MOVEMENT_STATE, [hl]
;> wPokemonTower6FCurScript = SCRIPT_POKEMONTOWER6F_PLAYER_MOVING
	ld a, SCRIPT_POKEMONTOWER6F_PLAYER_MOVING
	ld [wPokemonTower6FCurScript], a
;> wCurMapScript = SCRIPT_POKEMONTOWER6F_PLAYER_MOVING
	ld [wCurMapScript], a
	ret

;@ path: scripts/PokemonTower6F
;@ def PokemonTower6FPlayerMovingScript()
;@ Once the push is walked, back to the default step.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower6FPlayerMovingScript:
;> if wSimulatedJoypadStatesIndex:       # still walking
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> Delay3()
	call Delay3
;> wPokemonTower6FCurScript = SCRIPT_POKEMONTOWER6F_DEFAULT
;> wCurMapScript = SCRIPT_POKEMONTOWER6F_DEFAULT
	xor a
	ld [wPokemonTower6FCurScript], a
	ld [wCurMapScript], a
	ret

