;@ path: scripts/PokemonTower6F
;@ def PokemonTower6FMarowakDepartedText() -> hl
;@ After the ghost battle: "The ghost was Cubone's mother", her cry, and "the mother's soul was calmed".
;@ test: skip a text script: the code after text_asm is run by the text engine
PokemonTower6FMarowakDepartedText:
	db TX_START_ASM
;> PrintText(PokemonTower6FGhostWasCubonesMotherText)
	ld hl, PokemonTower6FGhostWasCubonesMotherText
	call PrintText
;> PlayCry(RESTLESS_SOUL)
	ld a, RESTLESS_SOUL
	call PlayCry
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> DelayFrames(30)
	ld c, 30
	call DelayFrames
;> PrintText(PokemonTower6FSoulWasCalmedText)
	ld hl, PokemonTower6FSoulWasCalmedText
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

