;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower7FEndBattleScript:
;> wMiscFlags &= ~(1 << BIT_SEEN_BY_TRAINER)
	ld hl, wMiscFlags
	res BIT_SEEN_BY_TRAINER, [hl]
;> if wIsInBattle == LOST_BATTLE:
;>     return PokemonTower7FSetDefaultScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, PokemonTower7FSetDefaultScript
;> EndTrainerBattle()
	call EndTrainerBattle
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hSpriteIndex = wSpriteIndex
	ld a, [wSpriteIndex]
	ldh [hSpriteIndex], a
;> DisplayTextID()
	call DisplayTextID
;> PokemonTower7FRocketLeaveMovementScript()
	call PokemonTower7FRocketLeaveMovementScript
;> wPokemonTower7FCurScript = SCRIPT_POKEMONTOWER7F_HIDE_NPC
	ld a, SCRIPT_POKEMONTOWER7F_HIDE_NPC
	ld [wPokemonTower7FCurScript], a
;> wCurMapScript = SCRIPT_POKEMONTOWER7F_HIDE_NPC
	ld [wCurMapScript], a
	ret

;@ path: scripts/PokemonTower7F
;@ def PokemonTower7FHideNPCScript()
;@ When the beaten Rocket has walked off: hide him (his toggleable object, found in the map's list by sprite
;@ number) and go back to the default step.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower7FHideNPCScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> p = addr(wToggleableObjectList)               # entries: sprite, toggleable object
	ld hl, wToggleableObjectList
;> while True:
	ld a, [wSpriteIndex]
	ld b, a
.toggleableObjectsListLoop
;>     sprite, obj = mem[p], mem[p + 1]
;>     p += 2
	ld a, [hli]
;>     if sprite == wSpriteIndex:
	cp b            ; search for sprite ID in toggleable objects list
	ld a, [hli]
;>         break
	jr nz, .toggleableObjectsListLoop
;> wToggleableObjectIndex = obj
	ld [wToggleableObjectIndex], a   ; remove toggleable object
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wJoyIgnore = wSpriteIndex = wTrainerHeaderFlagBit = wOpponentAfterWrongAnswer = 0
	xor a
	ld [wJoyIgnore], a
	ld [wSpriteIndex], a
	ld [wTrainerHeaderFlagBit], a
	ld [wOpponentAfterWrongAnswer], a ; not used here; likely a mistake copied from maps/CinnabarGym.asm
;> wPokemonTower7FCurScript = SCRIPT_POKEMONTOWER7F_DEFAULT
	ld a, SCRIPT_POKEMONTOWER7F_DEFAULT
	ld [wPokemonTower7FCurScript], a
;> wCurMapScript = SCRIPT_POKEMONTOWER7F_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/PokemonTower7F
;@ def PokemonTower7FWarpToMrFujiHouseScript()
;@ After rescuing Mr. Fuji: he disappears and the player is warped to Mr. Fuji's house in Lavender Town.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
PokemonTower7FWarpToMrFujiHouseScript:
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wToggleableObjectIndex = TOGGLE_POKEMON_TOWER_7F_MR_FUJI
	ld a, TOGGLE_POKEMON_TOWER_7F_MR_FUJI
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> mem[wSpritePlayerStateData1FacingDirection] = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	ld [wSpritePlayerStateData1FacingDirection], a
;> hWarpDestinationMap = MR_FUJIS_HOUSE
	ld a, MR_FUJIS_HOUSE
	ldh [hWarpDestinationMap], a
;> wDestinationWarpID = 1
	ld a, $1
	ld [wDestinationWarpID], a
;> wLastMap = LAVENDER_TOWN
	ld a, LAVENDER_TOWN
	ld [wLastMap], a
;> wStatusFlags3 |= 1 << BIT_WARP_FROM_CUR_SCRIPT
	ld hl, wStatusFlags3
	set BIT_WARP_FROM_CUR_SCRIPT, [hl]
;> wPokemonTower7FCurScript = SCRIPT_POKEMONTOWER7F_DEFAULT
	ld a, SCRIPT_POKEMONTOWER7F_DEFAULT
	ld [wPokemonTower7FCurScript], a
;> wCurMapScript = SCRIPT_POKEMONTOWER7F_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/PokemonTower7F
;@ def PokemonTower7FRocketLeaveMovementScript()
;@ Start the beaten Rocket (wSpriteIndex) walking away: his 16-byte part of PokemonTower7FNPCCoordMovementTable
;@ lists, for each spot the player may stand on, the path to take.
;@ test: skip searches its table until the player's position matches, which a random position never does
PokemonTower7FRocketLeaveMovementScript:
;> p = PokemonTower7FNPCCoordMovementTable
	ld hl, PokemonTower7FNPCCoordMovementTable
;> p += ((wSpriteIndex - 1) & 0xFF) * 16 % 256      # 16 bytes for each Rocket
	ld a, [wSpriteIndex]
	dec a
	swap a
	ld d, $0
	ld e, a
	add hl, de
;> y, x = wYCoord, wXCoord
	ld a, [wYCoord]
	ld b, a
	ld a, [wXCoord]
	ld c, a
;>@loop while True:                             # entries: y, x, path
.loop
;>     if (mem[p] == y
	ld a, [hli]
	cp b
	jr nz, .inc_and_skip
;>             and mem[p + 1] == x):           # the entry for the player's spot
	ld a, [hli]
	cp c
	jr nz, .skip
;>         path = mem16[p + 2]
	ld a, [hli]
	ld d, [hl]
	ld e, a
;>         hSpriteIndex = wSpriteIndex
	ld a, [wSpriteIndex]
	ldh [hSpriteIndex], a
;>         return MoveSprite(path)
	jp MoveSprite
.inc_and_skip
;>     p += 4
	inc hl
.skip
	inc hl
	inc hl
;=@loop
	jr .loop

