	db 11, 11
	dw PokemonTower7FRocketExitDownMovement
	db 11, 12
	dw PokemonTower7FRocketExitDownMovement
	db 10, 12
	dw PokemonTower7FRocket2ExitLeftDownMovement
	db 9, 11
	dw PokemonTower7FRocket2ExitDownLeftMovement
	db 9, 10
	dw PokemonTower7FRocketExitDownMovement
	db 9, 9
	dw PokemonTower7FRocketExitDownMovement
	db 8, 9
	dw PokemonTower7FRocket3ExitRightDownMovement
	db 7, 10
	dw PokemonTower7FRocketExitDownMovement
	db 7, 11
	dw PokemonTower7FRocketExitDownMovement
	db 7, 12
	dw PokemonTower7FRocketExitDownMovement

