;@ def PokemonTower7FMrFujiText() -> hl
;@ Mr. Fuji, rescued: he thanks the player; he is now at home, the Saffron guard changes places, and the warp
;@ to his house follows.
;@ test: skip a text script: the code after text_asm is run by the text engine
PokemonTower7FMrFujiText:
	db TX_START_ASM
;> PrintText(PokemonTower7FMrFujiText.RescueText)
	ld hl, .RescueText
	call PrintText
;> set_event(EVENT_RESCUED_MR_FUJI)
	ld hl, wEventFlags + $99
	set (EVENT_RESCUED_MR_FUJI) % 8, [hl]
;> set_event(EVENT_RESCUED_MR_FUJI_2)
	ld hl, wEventFlags + $22
	set (EVENT_RESCUED_MR_FUJI_2) % 8, [hl]
;> wToggleableObjectIndex = TOGGLE_MR_FUJIS_HOUSE_MR_FUJI
	ld a, TOGGLE_MR_FUJIS_HOUSE_MR_FUJI
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
