	ld a, TOGGLE_SAFFRON_CITY_E
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_SAFFRON_CITY_F
	ld a, TOGGLE_SAFFRON_CITY_F
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> wPokemonTower7FCurScript = SCRIPT_POKEMONTOWER7F_WARP_TO_MR_FUJI_HOUSE
	ld a, SCRIPT_POKEMONTOWER7F_WARP_TO_MR_FUJI_HOUSE
	ld [wPokemonTower7FCurScript], a
;> wCurMapScript = SCRIPT_POKEMONTOWER7F_WARP_TO_MR_FUJI_HOUSE
	ld [wCurMapScript], a
;> return TextScriptEnd()
	jp TextScriptEnd

