	dw SSAnne2F_Script
	db 0
	dw SSAnne2F_Object
;@ path: scripts/SSAnne2F
;@ def SSAnne2F_Script()
;@ The S.S. Anne's 2F: run the current step (the rival battle in the corridor).
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SSAnne2F_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wSSAnne2FCurScript, SSAnne2F_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld hl, SSAnne2F_ScriptPointers
	ld a, [wSSAnne2FCurScript]
	jp CallFunctionInTable

;@ path: scripts/SSAnne2F
;@ def SSAnne2FResetScripts()
;@ Back to the default step (after a lost battle), with the controls given back.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SSAnne2FResetScripts:
;> wJoyIgnore = 0
;> wSSAnne2FCurScript = SCRIPT_SSANNE2F_DEFAULT
	xor a
	ld [wJoyIgnore], a
	ld [wSSAnne2FCurScript], a
	ret

;@ path: scripts/SSAnne2F
SSAnne2F_ScriptPointers:
	dw SSAnne2FDefaultScript
DEF SCRIPT_SSANNE2F_DEFAULT EQU 0
	dw SSAnne2FRivalStartBattleScript
DEF SCRIPT_SSANNE2F_RIVAL_START_BATTLE EQU 1
	dw SSAnne2FRivalAfterBattleScript
DEF SCRIPT_SSANNE2F_RIVAL_AFTER_BATTLE EQU 2
	dw SSAnne2FRivalExitScript
DEF SCRIPT_SSANNE2F_RIVAL_EXIT EQU 3
	dw SSAnne2FNoopScript
DEF SCRIPT_SSANNE2F_NOOP EQU 4

;@ path: scripts/SSAnne2F
;@ def SSAnne2FNoopScript()
;@ After the rival battle: nothing more happens.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SSAnne2FNoopScript:
;> return
	ret

;@ path: scripts/SSAnne2F
;@ def SSAnne2FDefaultScript()
;@ Stepping onto the corridor in front of the cabins: the rival's music, and he appears and walks down to the
;@ player.
;@ test: skip the spots and the walks sit under local labels, which the pseudo-code can only name
SSAnne2FDefaultScript:
;> if not ArePlayerCoordsInArray(SSAnne2FDefaultScript.PlayerCoordinatesArray):
;>     return
	ld hl, .PlayerCoordinatesArray
	call ArePlayerCoordsInArray
	ret nc
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> PlayMusic(MUSIC_MEET_RIVAL, BANK(Music_MeetRival))
	ld c, BANK(Music_MeetRival)
	ld a, MUSIC_MEET_RIVAL
	call PlayMusic
;> hSavedCoordIndex = wCoordIndex
	ld a, [wCoordIndex]
	ldh [hSavedCoordIndex], a
;> wToggleableObjectIndex = TOGGLE_SS_ANNE_2F_RIVAL
	ld a, TOGGLE_SS_ANNE_2F_RIVAL
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> Delay3()
	call Delay3
;> hSpriteIndex = SSANNE2F_RIVAL
	ld a, SSANNE2F_RIVAL
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> if hSavedCoordIndex == 2:
	ldh a, [hSavedCoordIndex]
	cp $2
	jr nz, .player_standing_right
;>     MoveSprite(SSAnne2FDefaultScript.RivalDownFourMovement)
	ld de, .RivalDownFourMovement
	jr .move_sprite
.player_standing_right
;> else:
;>     MoveSprite(SSAnne2FDefaultScript.RivalDownThreeMovement)
	ld de, .RivalDownThreeMovement
.move_sprite
	call MoveSprite
;> wSSAnne2FCurScript = SCRIPT_SSANNE2F_RIVAL_START_BATTLE
	ld a, SCRIPT_SSANNE2F_RIVAL_START_BATTLE
	ld [wSSAnne2FCurScript], a
	ret

.RivalDownFourMovement:
	db NPC_MOVEMENT_DOWN
.RivalDownThreeMovement:
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db -1 ; end

.PlayerCoordinatesArray:
	db 8, 36
	db 8, 37
