;@ path: scripts/SSAnne2F
;@ def SSAnne2FSetFacingDirectionScript()
;@ Turn the rival to the player: right when the player stands at x 37 (who then faces left), else down.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SSAnne2FSetFacingDirectionScript:
;> if wXCoord == 37:
	ld a, [wXCoord]
	cp 37
	jr nz, .player_standing_left
;>     wPlayerMovingDirection = PLAYER_DIR_LEFT
	ld a, PLAYER_DIR_LEFT
	ld [wPlayerMovingDirection], a
;>     hSpriteFacingDirection = SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_RIGHT
	jr .set_facing_direction
.player_standing_left
;> else:
;>     hSpriteFacingDirection = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
.set_facing_direction
	ldh [hSpriteFacingDirection], a
;> hSpriteIndex = SSANNE2F_RIVAL
	ld a, SSANNE2F_RIVAL
	ldh [hSpriteIndex], a
;> return SetSpriteFacingDirectionAndDelay()
	jp SetSpriteFacingDirectionAndDelay

;@ path: scripts/SSAnne2F
;@ def SSAnne2FRivalStartBattleScript()
;@ When the rival has walked down: he faces the player, speaks, and the battle starts with the team picked by
;@ his starter.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SSAnne2FRivalStartBattleScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> SSAnne2FSetFacingDirectionScript()
	call SSAnne2FSetFacingDirectionScript
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> hTextID = TEXT_SSANNE2F_RIVAL
	ld a, TEXT_SSANNE2F_RIVAL
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> Delay3()
	call Delay3
;> wCurOpponent = OPP_RIVAL2
	ld a, OPP_RIVAL2
	ld [wCurOpponent], a

;> if wRivalStarter == STARTER2:
	; select which team to use during the encounter
	ld a, [wRivalStarter]
	cp STARTER2
	jr nz, .NotSquirtle
;>     wTrainerNo = 1
	ld a, $1
	jr .done
.NotSquirtle
;> elif wRivalStarter == STARTER3:
	cp STARTER3
	jr nz, .Charmander
;>     wTrainerNo = 2
	ld a, $2
	jr .done
.Charmander
;> else:
;>     wTrainerNo = 3
	ld a, $3
.done
	ld [wTrainerNo], a

;> SSAnne2FSetFacingDirectionScript()
	call SSAnne2FSetFacingDirectionScript
;> wSSAnne2FCurScript = SCRIPT_SSANNE2F_RIVAL_AFTER_BATTLE
	ld a, SCRIPT_SSANNE2F_RIVAL_AFTER_BATTLE
	ld [wSSAnne2FCurScript], a
	ret

;@ path: scripts/SSAnne2F
;@ def SSAnne2FRivalAfterBattleScript()
;@ After the rival battle: lost, start over; won, his words about the Cut master, and he walks off (around
;@ the player) to his tune.
;@ test: skip the walks sit under local labels, which the pseudo-code can only name
SSAnne2FRivalAfterBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return SSAnne2FResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, SSAnne2FResetScripts
;> SSAnne2FSetFacingDirectionScript()
	call SSAnne2FSetFacingDirectionScript
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hTextID = TEXT_SSANNE2F_RIVAL_CUT_MASTER
	ld a, TEXT_SSANNE2F_RIVAL_CUT_MASTER
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hSpriteIndex = SSANNE2F_RIVAL
	ld a, SSANNE2F_RIVAL
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> if wXCoord == 37:
	ld a, [wXCoord]
	cp 37
	jr nz, .player_standing_left
;>     moves = SSAnne2FRivalAfterBattleScript.RivalDownFourMovement
	ld de, .RivalDownFourMovement
	jr .move_sprite
.player_standing_left
;> else:
;>     moves = SSAnne2FRivalAfterBattleScript.RivalWalkAroundPlayerMovement
	ld de, .RivalWalkAroundPlayerMovement
.move_sprite
;> hSpriteIndex = SSANNE2F_RIVAL
	ld a, SSANNE2F_RIVAL
	ldh [hSpriteIndex], a
;> MoveSprite(moves)
	call MoveSprite
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> farcall(Music_RivalAlternateStart)
	ld b, BANK(Music_RivalAlternateStart)
	ld hl, Music_RivalAlternateStart
	call Bankswitch
;> wSSAnne2FCurScript = SCRIPT_SSANNE2F_RIVAL_EXIT
	ld a, SCRIPT_SSANNE2F_RIVAL_EXIT
	ld [wSSAnne2FCurScript], a
	ret

.RivalWalkAroundPlayerMovement:
	db NPC_MOVEMENT_RIGHT
	db NPC_MOVEMENT_DOWN
.RivalDownFourMovement:
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db -1 ; end

;@ path: scripts/SSAnne2F
;@ def SSAnne2FRivalExitScript()
;@ When the rival has walked off: hide him, give the controls back and restore the map music.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SSAnne2FRivalExitScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wToggleableObjectIndex = TOGGLE_SS_ANNE_2F_RIVAL
	ld a, TOGGLE_SS_ANNE_2F_RIVAL
	ld [wToggleableObjectIndex], a
;> predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> PlayDefaultMusic()
	call PlayDefaultMusic
;> wSSAnne2FCurScript = SCRIPT_SSANNE2F_NOOP
	ld a, SCRIPT_SSANNE2F_NOOP
	ld [wSSAnne2FCurScript], a
	ret

