;@ path: scripts/SSAnne2F
;@ def SSAnne2FRivalText() -> hl
;@ The rival on the ship: his greeting, and the texts for the end of the battle.
;@ test: skip a text script: the code after text_asm is run by the text engine
SSAnne2FRivalText:
	db TX_START_ASM
;> PrintText(SSAnne2FRivalText.Text)
	ld hl, .Text
	call PrintText
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(SSAnne2FRivalDefeatedText, SSAnne2FRivalVictoryText)
	ld hl, SSAnne2FRivalDefeatedText
	ld de, SSAnne2FRivalVictoryText
	call SaveEndBattleTextPointers
;> return TextScriptEnd()
	jp TextScriptEnd

