	dw SSAnneCaptainsRoom_Object
;@ path: scripts/SSAnneCaptainsRoom
;@ def SSAnneCaptainsRoom_Script()
;@ The captain's cabin: until his back is rubbed, the seasick captain does not turn to face the player.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SSAnneCaptainsRoom_Script:
;> SSAnneCaptainsRoomEventScript()
;> return EnableAutoTextBoxDrawing()
	call SSAnneCaptainsRoomEventScript
	jp EnableAutoTextBoxDrawing

;@ path: scripts/SSAnneCaptainsRoom
;@ def SSAnneCaptainsRoomEventScript()
;@ Until the player has rubbed the captain's back, people here do not turn to face the player.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SSAnneCaptainsRoomEventScript:
;> if not event(EVENT_RUBBED_CAPTAINS_BACK):
;>     wStatusFlags3 |= 1 << BIT_NO_NPC_FACE_PLAYER
	ld a, [wEventFlags + $BC]
	bit (EVENT_RUBBED_CAPTAINS_BACK) % 8, a
	ret nz
	ld hl, wStatusFlags3
	set BIT_NO_NPC_FACE_PLAYER, [hl]
	ret

;@ path: scripts/SSAnneCaptainsRoom
SSAnneCaptainsRoom_TextPointers:
	dw SSAnneCaptainsRoomCaptainText
DEF TEXT_SSANNECAPTAINSROOM_CAPTAIN EQU 1
	dw SSAnneCaptainsRoomTrashText
DEF TEXT_SSANNECAPTAINSROOM_TRASH EQU 2
	dw SSAnneCaptainsRoomSeasickBookText
DEF TEXT_SSANNECAPTAINSROOM_SEASICK_BOOK EQU 3

;@ path: scripts/SSAnneCaptainsRoom
;@ def SSAnneCaptainsRoomCaptainText() -> hl
;@ The captain: the player rubs his back, he feels better and gives HM01 (CUT) if the bag has room;
;@ afterwards, he is not sick any more.
;@ test: skip a text script: the code after text_asm is run by the text engine
SSAnneCaptainsRoomCaptainText:
	db TX_START_ASM
;> if event(EVENT_GOT_HM01):
	ld a, [wEventFlags + $BC]
	bit (EVENT_GOT_HM01) % 8, a
	jr nz, .got_item
;>@e1     PrintText(SSAnneCaptainsRoomCaptainNotSickAnymoreText)
;>@e2     return TextScriptEnd()
;> PrintText(SSAnneCaptainsRoomRubCaptainsBackText)
	ld hl, SSAnneCaptainsRoomRubCaptainsBackText
	call PrintText
;> PrintText(SSAnneCaptainsRoomCaptainIFeelMuchBetterText)
	ld hl, SSAnneCaptainsRoomCaptainIFeelMuchBetterText
	call PrintText
;> if GiveItem(HM_CUT, 1):
	ld bc, ((HM_CUT) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>     PrintText(SSAnneCaptainsRoomCaptainReceivedHM01Text)
	ld hl, SSAnneCaptainsRoomCaptainReceivedHM01Text
	call PrintText
;>     set_event(EVENT_GOT_HM01)
	ld hl, wEventFlags + $BC
	set (EVENT_GOT_HM01) % 8, [hl]
	jr .done
.bag_full
;> else:
;>     PrintText(SSAnneCaptainsRoomCaptainHM01NoRoomText)
	ld hl, SSAnneCaptainsRoomCaptainHM01NoRoomText
	call PrintText
;>     wStatusFlags3 |= 1 << BIT_NO_NPC_FACE_PLAYER
	ld hl, wStatusFlags3
	set BIT_NO_NPC_FACE_PLAYER, [hl]
;> return TextScriptEnd()
	jr .done
.got_item
;=@e1
	ld hl, SSAnneCaptainsRoomCaptainNotSickAnymoreText
	call PrintText
;=@e2
.done
	jp TextScriptEnd

;@ path: scripts/SSAnneCaptainsRoom
;@ def SSAnneCaptainsRoomRubCaptainsBackText() -> hl
;@ Rubbing the captain's back: the healing jingle plays to its end, then the map music; his back is rubbed and
;@ he now faces the player.
;@ test: skip a text script: the code after text_asm is run by the text engine
SSAnneCaptainsRoomRubCaptainsBackText:
;> engine3 = wAudioROMBank == BANK(PlayPokedexRatingSfx)       # the bank of Audio Engine 3
	db TX_FAR
	dw _SSAnneCaptainsRoomRubCaptainsBackText
	db BANK(_SSAnneCaptainsRoomRubCaptainsBackText)
	db TX_START_ASM
	ld a, [wAudioROMBank]
	cp BANK("Audio Engine 3")
;> wAudioSavedROMBank = wAudioROMBank
	ld [wAudioSavedROMBank], a
;> if engine3:
	jr nz, .not_audio_engine_3
;>     wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;>     PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;>     wAudioROMBank = BANK(Music_PkmnHealed)
	ld a, BANK(Music_PkmnHealed)
	ld [wAudioROMBank], a
.not_audio_engine_3
;> wNewSoundID = MUSIC_PKMN_HEALED
	ld a, MUSIC_PKMN_HEALED
	ld [wNewSoundID], a
;> PlaySound(MUSIC_PKMN_HEALED)
	call PlaySound
;> while wChannelSoundIDs[0] == MUSIC_PKMN_HEALED:
.loop
	ld a, [wChannelSoundIDs]
	cp MUSIC_PKMN_HEALED
	jr z, .loop
;>     pass
;> PlayDefaultMusic()
	call PlayDefaultMusic
;> set_event(EVENT_RUBBED_CAPTAINS_BACK)
	ld hl, wEventFlags + $BC
	set (EVENT_RUBBED_CAPTAINS_BACK) % 8, [hl]
;> wStatusFlags3 &= ~(1 << BIT_NO_NPC_FACE_PLAYER)
	ld hl, wStatusFlags3
	res BIT_NO_NPC_FACE_PLAYER, [hl]
;> return TextScriptEnd()
	jp TextScriptEnd

