;@ path: scripts/SSAnne2FRooms
;@ def SSAnne2FRooms_Script()
;@ The S.S. Anne's 2F cabins: their texts draw their own boxes; run the current step (the cabins' trainers).
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SSAnne2FRooms_Script:
;> wAutoTextBoxDrawingControl = 1 << BIT_NO_AUTO_TEXT_BOX
	ld a, 1 << BIT_NO_AUTO_TEXT_BOX
	ld [wAutoTextBoxDrawingControl], a
;> wDoNotWaitForButtonPressAfterDisplayingText = 0
	xor a
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> wSSAnne2FRoomsCurScript = ExecuteCurMapScriptInTable(wSSAnne2FRoomsCurScript, SSAnne9TrainerHeaders, SSAnne2FRooms_ScriptPointers)
	ld hl, SSAnne9TrainerHeaders
	ld de, SSAnne2FRooms_ScriptPointers
	ld a, [wSSAnne2FRoomsCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSSAnne2FRoomsCurScript], a
	ret

