SilphCo11F_h::
	db INTERIOR
	db $9, $9
	dw SilphCo11F_Blocks
	dw SilphCo11F_TextPointers
	dw SilphCo11F_Script
	db 0
	dw SilphCo11F_Object
;@ path: scripts/SilphCo11F
;@ def SilphCo11F_Script()
;@ Silph Co. 11F's map script: first the map callback (SilphCo11FGateCallbackScript), then run the current step of the map's script (its trainers).
;@ test: hLoadedROMBank = 0x18; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
SilphCo11F_Script:
;> SilphCo11FGateCallbackScript()
	call SilphCo11FGateCallbackScript
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wSilphCo11FCurScript = ExecuteCurMapScriptInTable(wSilphCo11FCurScript, SilphCo11TrainerHeaders, SilphCo11F_ScriptPointers)
	ld hl, SilphCo11TrainerHeaders
	ld de, SilphCo11F_ScriptPointers
	ld a, [wSilphCo11FCurScript]
	call ExecuteCurMapScriptInTable
	ld [wSilphCo11FCurScript], a
	ret

;@ path: scripts/SilphCo11F
;@ def SilphCo11FGateCallbackScript()
;@ On entering the top floor: if the card-key door here was just opened, note it; while it is locked, draw it
;@ (block $20) into the map.
;@ test: hLoadedROMBank = 0x18; wIsInBattle = 0xFF; wCurMapWidth = rand(1, 20)    # the bank this code runs in; no map redraw, blocks on the map
SilphCo11FGateCallbackScript:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> SilphCo11F_SetCardKeyDoorYScript(SilphCo11GateCoords)
	ld hl, SilphCo11GateCoords
	call SilphCo11F_SetCardKeyDoorYScript
;> SilphCo11FSetUnlockedDoorEventScript()
	call SilphCo11FSetUnlockedDoorEventScript
;> if not event(EVENT_SILPH_CO_11_UNLOCKED_DOOR):
	ld a, [wEventFlags + $F1]
	bit (EVENT_SILPH_CO_11_UNLOCKED_DOOR) % 8, a
	ret nz
;>     wNewTileBlockID = 0x20
	ld a, $20
	ld [wNewTileBlockID], a
;>     return predef(ReplaceTileBlock, bc=6 << 8 | 3)
	ld bc, ((6) & $ff) << 8 + ((3) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/SilphCo11F
SilphCo11GateCoords:
	db 6, 3
	db -1 ; end

;@ path: scripts/SilphCo11F
;@ def SilphCo11F_SetCardKeyDoorYScript(doors: hl)
;@ Look up the door the card key just opened (wCardKeyDoorY/X) in the floor's door list: hUnlockedSilphCoDoors
;@ becomes its number (1, 2...) and the opened door is forgotten; 0 if it is not one of them.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SilphCo11F_SetCardKeyDoorYScript:
;> y = wCardKeyDoorY
	push hl
	ld hl, wCardKeyDoorY
	ld a, [hli]
	ld b, a
;> x = wCardKeyDoorX
	ld a, [hl]
	ld c, a
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
;> while mem[doors] != 0xFF:
	pop hl
.loop_check_doors
	ld a, [hli]
	cp $ff
	jr z, .exit_loop
;>     hUnlockedSilphCoDoors += 1
	push hl
	ld hl, hUnlockedSilphCoDoors
	inc [hl]
	pop hl
;>@match     if mem[doors] == y and mem[doors + 1] == x:
	cp b
	jr z, .check_y_coord
;>@clear         wCardKeyDoorY = wCardKeyDoorX = 0
;>@ret         return
;>     doors += 2
	inc hl
	jr .loop_check_doors
.check_y_coord
;=@match
	ld a, [hli]
	cp c
	jr nz, .loop_check_doors
;=@clear
	ld hl, wCardKeyDoorY
	xor a
	ld [hli], a
	ld [hl], a
;=@ret
	ret
.exit_loop
;> hUnlockedSilphCoDoors = 0
	xor a
	ldh [hUnlockedSilphCoDoors], a
	ret

;@ path: scripts/SilphCo11F
;@ def SilphCo11FSetUnlockedDoorEventScript()
;@ If the card key just opened this floor's door, note it as an event.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SilphCo11FSetUnlockedDoorEventScript:
;> if hUnlockedSilphCoDoors:
;>     set_event(EVENT_SILPH_CO_11_UNLOCKED_DOOR)
	ldh a, [hUnlockedSilphCoDoors]
	and a
	ret z
	ld hl, wEventFlags + $F1
	set (EVENT_SILPH_CO_11_UNLOCKED_DOOR) % 8, [hl]
	ret

;@ path: scripts/SilphCo11F
;@ def SilphCo11FTeamRocketLeavesScript()
;@ Team Rocket leaves Saffron: hide every Rocket in the city and in Silph Co., and show the city's ordinary
;@ people again.
;@ test: skip the two object lists sit under local labels, which the pseudo-code can only name
SilphCo11FTeamRocketLeavesScript:
;> p = SilphCo11FTeamRocketLeavesScript.HideToggleableObjectIDs
	ld hl, .HideToggleableObjectIDs
;> while mem[p] != 0xFF:
.hide_loop
	ld a, [hli]
	cp $ff
	jr z, .done_hiding
;>     wToggleableObjectIndex = mem[p]
	push hl
	ld [wToggleableObjectIndex], a
;>     predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;>     p += 1
	pop hl
	jr .hide_loop
.done_hiding
;> p = SilphCo11FTeamRocketLeavesScript.ShowToggleableObjectIDs
	ld hl, .ShowToggleableObjectIDs
;> while mem[p] != 0xFF:
.show_loop
	ld a, [hli]
	cp -1
	ret z
;>     wToggleableObjectIndex = mem[p]
	push hl
	ld [wToggleableObjectIndex], a
;>     predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;>     p += 1
	pop hl
	jr .show_loop

.ShowToggleableObjectIDs:
	db TOGGLE_SAFFRON_CITY_8
	db TOGGLE_SAFFRON_CITY_9
	db TOGGLE_SAFFRON_CITY_A
	db TOGGLE_SAFFRON_CITY_B
	db TOGGLE_SAFFRON_CITY_C
	db TOGGLE_SAFFRON_CITY_D
	db -1 ; end

.HideToggleableObjectIDs:
	db TOGGLE_SAFFRON_CITY_1
	db TOGGLE_SAFFRON_CITY_2
	db TOGGLE_SAFFRON_CITY_3
	db TOGGLE_SAFFRON_CITY_4
	db TOGGLE_SAFFRON_CITY_5
	db TOGGLE_SAFFRON_CITY_6
	db TOGGLE_SAFFRON_CITY_7
	db TOGGLE_SAFFRON_CITY_E
	db TOGGLE_SAFFRON_CITY_F
	db TOGGLE_SILPH_CO_2F_2
	db TOGGLE_SILPH_CO_2F_3
	db TOGGLE_SILPH_CO_2F_4
	db TOGGLE_SILPH_CO_2F_5
	db TOGGLE_SILPH_CO_3F_1
	db TOGGLE_SILPH_CO_3F_2
	db TOGGLE_SILPH_CO_4F_1
	db TOGGLE_SILPH_CO_4F_2
	db TOGGLE_SILPH_CO_4F_3
	db TOGGLE_SILPH_CO_5F_1
	db TOGGLE_SILPH_CO_5F_2
	db TOGGLE_SILPH_CO_5F_3
	db TOGGLE_SILPH_CO_5F_4
	db TOGGLE_SILPH_CO_6F_1
	db TOGGLE_SILPH_CO_6F_2
	db TOGGLE_SILPH_CO_6F_3
	db TOGGLE_SILPH_CO_7F_1
	db TOGGLE_SILPH_CO_7F_2
	db TOGGLE_SILPH_CO_7F_3
	db TOGGLE_SILPH_CO_7F_4
	db TOGGLE_SILPH_CO_8F_1
	db TOGGLE_SILPH_CO_8F_2
	db TOGGLE_SILPH_CO_8F_3
	db TOGGLE_SILPH_CO_9F_1
	db TOGGLE_SILPH_CO_9F_2
	db TOGGLE_SILPH_CO_9F_3
	db TOGGLE_SILPH_CO_10F_1
	db TOGGLE_SILPH_CO_10F_2
	db TOGGLE_SILPH_CO_11F_1
	db TOGGLE_SILPH_CO_11F_2
	db TOGGLE_SILPH_CO_11F_3
