;@ path: scripts/SilphCo11F
;@ def SilphCo11FResetCurScript()
;@ Back to the floor's default step, with the controls given back.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SilphCo11FResetCurScript:
;> wJoyIgnore = 0
;> return SilphCo11FSetCurScript(SCRIPT_SILPHCO11F_DEFAULT)
	xor a
	ld [wJoyIgnore], a
; fallthrough
;@ path: scripts/SilphCo11F
;@ def SilphCo11FSetCurScript(script: a)
;@ Make `script` the floor's current step.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SilphCo11FSetCurScript:
;> wSilphCo11FCurScript = script
;> wCurMapScript = script
	ld [wSilphCo11FCurScript], a
	ld [wCurMapScript], a
	ret

;@ path: scripts/SilphCo11F
SilphCo11F_ScriptPointers:
	dw SilphCo11FDefaultScript
DEF SCRIPT_SILPHCO11F_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_SILPHCO11F_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_SILPHCO11F_END_BATTLE EQU 2
	dw SilphCo11FGiovanniBattleFacingScript
DEF SCRIPT_SILPHCO11F_GIOVANNI_FACING EQU 3
	dw SilphCo11FGiovanniStartBattleScript
DEF SCRIPT_SILPHCO11F_GIOVANNI_START_BATTLE EQU 4
	dw SilphCo11FGiovanniAfterBattleScript
DEF SCRIPT_SILPHCO11F_GIOVANNI_AFTER_BATTLE EQU 5

;@ path: scripts/SilphCo11F
;@ def SilphCo11FDefaultScript()
;@ Until Giovanni is beaten, walking up to the president's desk makes Giovanni speak and step down to the
;@ player; otherwise the trainers watch for the player.
;@ test: skip the spots and the walk sit under local labels, which the pseudo-code can only name
SilphCo11FDefaultScript:
;> if event(EVENT_BEAT_SILPH_CO_GIOVANNI):
;>     return
	ld a, [wEventFlags + $F1]
	bit (EVENT_BEAT_SILPH_CO_GIOVANNI) % 8, a
	ret nz
;> if not ArePlayerCoordsInArray(SilphCo11FDefaultScript.PlayerCoordsArray):
;>     return CheckFightingMapTrainers()
	ld hl, .PlayerCoordsArray
	call ArePlayerCoordsInArray
	jp nc, CheckFightingMapTrainers
;> wSavedCoordIndex = wCoordIndex
	ld a, [wCoordIndex]
	ld [wSavedCoordIndex], a
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hTextID = TEXT_SILPHCO11F_GIOVANNI
	ld a, TEXT_SILPHCO11F_GIOVANNI
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> hSpriteIndex = SILPHCO11F_GIOVANNI
	ld a, SILPHCO11F_GIOVANNI
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> MoveSprite(SilphCo11FDefaultScript.GiovanniMovement)     # three steps down
	ld de, .GiovanniMovement
	call MoveSprite
;> return SilphCo11FSetCurScript(SCRIPT_SILPHCO11F_GIOVANNI_FACING)
	ld a, SCRIPT_SILPHCO11F_GIOVANNI_FACING
	jp SilphCo11FSetCurScript

.PlayerCoordsArray:
	db 13, 6
	db 12, 7
	db -1 ; end

.GiovanniMovement:
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db NPC_MOVEMENT_DOWN
	db -1 ; end

;@ path: scripts/SilphCo11F
;@ def SilphCo11FSetPlayerAndSpriteFacingDirectionScript(player: a, giovanni: b)
;@ Set the player's direction and turn Giovanni to `giovanni`.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SilphCo11FSetPlayerAndSpriteFacingDirectionScript:
;> wPlayerMovingDirection = player
	ld [wPlayerMovingDirection], a
;> hSpriteIndex = SILPHCO11F_GIOVANNI
	ld a, SILPHCO11F_GIOVANNI
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = giovanni
	ld a, b
	ldh [hSpriteFacingDirection], a
;> return SetSpriteFacingDirectionAndDelay()
	jp SetSpriteFacingDirectionAndDelay

;@ path: scripts/SilphCo11F
;@ def SilphCo11FGiovanniAfterBattleScript()
;@ After the battle with Giovanni: lost, start over; won, "you ruined our plans", and in a fade to black Team
;@ Rocket leaves Silph Co. and Saffron.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SilphCo11FGiovanniAfterBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return SilphCo11FResetCurScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, SilphCo11FResetCurScript
;> if wSavedCoordIndex == 1:
	ld a, [wSavedCoordIndex]
	cp 1 ; index of second, upper-right entry in SilphCo11FDefaultScript.PlayerCoordsArray
	jr z, .face_player_up
;>     SilphCo11FSetPlayerAndSpriteFacingDirectionScript(PLAYER_DIR_UP, SPRITE_FACING_DOWN)
;> else:
;>     SilphCo11FSetPlayerAndSpriteFacingDirectionScript(PLAYER_DIR_LEFT, SPRITE_FACING_RIGHT)
	ld a, PLAYER_DIR_LEFT
	ld b, SPRITE_FACING_RIGHT
	jr .continue
.face_player_up
	ld a, PLAYER_DIR_UP
	ld b, SPRITE_FACING_DOWN
.continue
	call SilphCo11FSetPlayerAndSpriteFacingDirectionScript
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hTextID = TEXT_SILPHCO11F_GIOVANNI_YOU_RUINED_OUR_PLANS
	ld a, TEXT_SILPHCO11F_GIOVANNI_YOU_RUINED_OUR_PLANS
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> GBFadeOutToBlack()
	call GBFadeOutToBlack
;> SilphCo11FTeamRocketLeavesScript()
	call SilphCo11FTeamRocketLeavesScript
;> UpdateSprites()
	call UpdateSprites
;> Delay3()
	call Delay3
;> GBFadeInFromBlack()
	call GBFadeInFromBlack
;> set_event(EVENT_BEAT_SILPH_CO_GIOVANNI)
	ld hl, wEventFlags + $F1
	set (EVENT_BEAT_SILPH_CO_GIOVANNI) % 8, [hl]
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> return SilphCo11FSetCurScript(SCRIPT_SILPHCO11F_DEFAULT)
	jp SilphCo11FSetCurScript

;@ path: scripts/SilphCo11F
;@ def SilphCo11FGiovanniBattleFacingScript()
;@ When Giovanni has stepped down: he and the player face each other.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SilphCo11FGiovanniBattleFacingScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> hSpriteIndex = SILPHCO11F_GIOVANNI
	ld a, SILPHCO11F_GIOVANNI
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> if wSavedCoordIndex == 1:
	ld a, [wSavedCoordIndex]
	cp 1 ; index of second, upper-right entry in SilphCo11FDefaultScript.PlayerCoordsArray
	jr z, .face_player_up
;>     SilphCo11FSetPlayerAndSpriteFacingDirectionScript(PLAYER_DIR_UP, SPRITE_FACING_DOWN)
;> else:
;>     SilphCo11FSetPlayerAndSpriteFacingDirectionScript(PLAYER_DIR_LEFT, SPRITE_FACING_RIGHT)
	ld a, PLAYER_DIR_LEFT
	ld b, SPRITE_FACING_RIGHT
	jr .continue
.face_player_up
	ld a, PLAYER_DIR_UP
	ld b, SPRITE_FACING_DOWN
.continue
	call SilphCo11FSetPlayerAndSpriteFacingDirectionScript
;> Delay3()
	call Delay3
;> return SilphCo11FSetCurScript(SCRIPT_SILPHCO11F_GIOVANNI_START_BATTLE)
	ld a, SCRIPT_SILPHCO11F_GIOVANNI_START_BATTLE
	jp SilphCo11FSetCurScript

;@ path: scripts/SilphCo11F
;@ def SilphCo11FGiovanniStartBattleScript()
;@ Start the battle with Giovanni.
;@ test: hLoadedROMBank = 0x18    # the bank this code runs in
SilphCo11FGiovanniStartBattleScript:
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(SilphCo11FGiovanniILostAgainText, SilphCo11FGiovanniILostAgainText)
	ld hl, SilphCo11FGiovanniILostAgainText
	ld de, SilphCo11FGiovanniILostAgainText
	call SaveEndBattleTextPointers
;> wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;> EngageMapTrainer()
	call EngageMapTrainer
;> InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> return SilphCo11FSetCurScript(SCRIPT_SILPHCO11F_GIOVANNI_AFTER_BATTLE)
	ld a, SCRIPT_SILPHCO11F_GIOVANNI_AFTER_BATTLE
	jp SilphCo11FSetCurScript

