;@ path: scripts/SilphCo11F
;@ def SilphCo11FSilphPresidentText() -> hl
;@ Silph's president: as thanks he gives the Master Ball (if the bag has room), and later describes it.
;@ test: skip a text script: the code after text_asm is run by the text engine
SilphCo11FSilphPresidentText:
	db TX_START_ASM
;> if event(EVENT_GOT_MASTER_BALL):
	ld a, [wEventFlags + $F1]
	bit (EVENT_GOT_MASTER_BALL) % 8, a
	jp nz, .got_item
;>@e1     PrintText(SilphCo11FSilphPresidentText.MasterBallDescriptionText)
;>@e2     return TextScriptEnd()
;> PrintText(SilphCo11FSilphPresidentText.Text)
	ld hl, .Text
	call PrintText
;> if GiveItem(MASTER_BALL, 1):
	ld bc, ((MASTER_BALL) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>     PrintText(SilphCo11FSilphPresidentText.ReceivedMasterBallText)
	ld hl, .ReceivedMasterBallText
	call PrintText
;>     set_event(EVENT_GOT_MASTER_BALL)
	ld hl, wEventFlags + $F1
	set (EVENT_GOT_MASTER_BALL) % 8, [hl]
	jr .done
.bag_full
;> else:
;>     PrintText(SilphCo11FSilphPresidentText.NoRoomText)
	ld hl, .NoRoomText
	call PrintText
	jr .done
.got_item
;=@e1
	ld hl, .MasterBallDescriptionText
	call PrintText
;=@e2
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _SilphCo11FSilphPresidentText
	db BANK(_SilphCo11FSilphPresidentText)
	db TX_END

.ReceivedMasterBallText:
	db TX_FAR
	dw _SilphCo11FSilphPresidentReceivedMasterBallText
	db BANK(_SilphCo11FSilphPresidentReceivedMasterBallText)
	db TX_SOUND_GET_KEY_ITEM
	db TX_END

.MasterBallDescriptionText:
