;@ path: scripts/CeruleanCity_2
;@ def CeruleanHideRocket()
;@ After the Rocket thief hands back TM28: fade out, move the city's guard to his other post, remove the
;@ thief, and fade back in.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
CeruleanHideRocket:
; code similar to this appears in a lot of banks; this particular
; one is called after you beat the Rocket that gives you TM28 DIG.
; the screen then fades out, he disappears, and fades back in
;> GBFadeOutToBlack()
	call GBFadeOutToBlack
;> wToggleableObjectIndex = TOGGLE_CERULEAN_GUARD_1
	ld a, TOGGLE_CERULEAN_GUARD_1
	ld [wToggleableObjectIndex], a
;> ShowObject()
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_CERULEAN_GUARD_2
	ld a, TOGGLE_CERULEAN_GUARD_2
	ld [wToggleableObjectIndex], a
;> HideObject()
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wToggleableObjectIndex = TOGGLE_CERULEAN_ROCKET
	ld a, TOGGLE_CERULEAN_ROCKET
	ld [wToggleableObjectIndex], a
;> HideObject()
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> GBFadeInFromBlack()
	call GBFadeInFromBlack
	ret

ViridianGym_h::
	db GYM
	db $9, $A
	dw ViridianGym_Blocks
	dw ViridianGym_TextPointers
	dw ViridianGym_Script
	db 0
	dw ViridianGym_Object
;@ path: scripts/ViridianGym
;@ def ViridianGym_Script()
;@ Viridian Gym's map script: set the city and leader names (Viridian City, Giovanni) for the badge texts;
;@ then run the current step of the gym's script (the arrow floor, the trainers, Giovanni).
;@ test: skip the names sit under local labels, which the pseudo-code can only name
ViridianGym_Script:
;> LoadGymLeaderAndCityName(ViridianGym_Script.CityName, ViridianGym_Script.LeaderName)
	ld hl, .CityName
	ld de, .LeaderName
	call LoadGymLeaderAndCityName
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wViridianGymCurScript = ExecuteCurMapScriptInTable(wViridianGymCurScript, ViridianGymTrainerHeaders, ViridianGym_ScriptPointers)
	ld hl, ViridianGymTrainerHeaders
	ld de, ViridianGym_ScriptPointers
	ld a, [wViridianGymCurScript]
	call ExecuteCurMapScriptInTable
	ld [wViridianGymCurScript], a
	ret

.CityName:
	db "VIRIDIAN CITY@"

.LeaderName:
	db "GIOVANNI@"

;@ path: scripts/ViridianGym
;@ def ViridianGymResetScripts()
;@ Back to the gym's default step, with the controls given back.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
ViridianGymResetScripts:
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wViridianGymCurScript = SCRIPT_VIRIDIANGYM_DEFAULT
	ld [wViridianGymCurScript], a
;> wCurMapScript = SCRIPT_VIRIDIANGYM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/ViridianGym
ViridianGym_ScriptPointers:
	dw ViridianGymDefaultScript
DEF SCRIPT_VIRIDIANGYM_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_VIRIDIANGYM_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_VIRIDIANGYM_END_BATTLE EQU 2
	dw ViridianGymGiovanniPostBattle
DEF SCRIPT_VIRIDIANGYM_GIOVANNI_POST_BATTLE EQU 3
	dw ViridianGymPlayerSpinningScript
DEF SCRIPT_VIRIDIANGYM_PLAYER_SPINNING EQU 4

;@ path: scripts/ViridianGym
;@ def ViridianGymDefaultScript()
;@ Each step in the gym: stepping on an arrow tile spins the player along its path; otherwise the trainers
;@ watch for the player.
;@ test: skip the arrow lookup's pseudo-code does not give back the $FF it leaves in a when no arrow matched
ViridianGymDefaultScript:
;> DecodeArrowMovementRLE(ViridianGymArrowTilePlayerMovement, wYCoord, wXCoord)
	ld a, [wYCoord]
	ld b, a
	ld a, [wXCoord]
	ld c, a
	ld hl, ViridianGymArrowTilePlayerMovement
	call DecodeArrowMovementRLE
;> if a == 0xFF:                                 # not on an arrow
;>     return CheckFightingMapTrainers()
	cp $ff
	jp z, CheckFightingMapTrainers
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wMovementFlags |= 1 << BIT_SPINNING
	ld hl, wMovementFlags
	set BIT_SPINNING, [hl]
;> PlaySound(SFX_ARROW_TILES)
	ld a, SFX_ARROW_TILES
	call PlaySound
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wCurMapScript = SCRIPT_VIRIDIANGYM_PLAYER_SPINNING
	ld a, SCRIPT_VIRIDIANGYM_PLAYER_SPINNING
	ld [wCurMapScript], a
	ret

