;@ path: scripts/ViridianGym
;@ def ViridianGymPlayerSpinningScript()
;@ While the player spins along the arrows, animate the arrow tiles; at the end, give the controls back.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
ViridianGymPlayerSpinningScript:
;> if wSimulatedJoypadStatesIndex:       # still spinning
;>@arrows     return farcall(LoadSpinnerArrowTiles)
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	jr nz, .ViridianGymLoadSpinnerArrow
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wMovementFlags &= ~(1 << BIT_SPINNING)
	ld hl, wMovementFlags
	res BIT_SPINNING, [hl]
;> wCurMapScript = SCRIPT_VIRIDIANGYM_DEFAULT
	ld a, SCRIPT_VIRIDIANGYM_DEFAULT
	ld [wCurMapScript], a
	ret
.ViridianGymLoadSpinnerArrow
;=@arrows
	ld b, BANK(LoadSpinnerArrowTiles)
	ld hl, LoadSpinnerArrowTiles
	jp Bankswitch

;@ path: scripts/ViridianGym
;@ def ViridianGymGiovanniPostBattle()
;@ After the battle with Giovanni: lost, start over; won, go on to the badge and TM27.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
ViridianGymGiovanniPostBattle:
;> if wIsInBattle == LOST_BATTLE:
;>     return ViridianGymResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, ViridianGymResetScripts
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
; fallthrough

;> return ViridianGymReceiveTM27()
;@ path: scripts/ViridianGym
;@ def ViridianGymReceiveTM27()
;@ Giovanni's reward: the Earth Badge text, TM27 (FISSURE) if the bag has room, the badge; the gym's trainers no
;@ longer battle and the rival now waits on Route 22 for the second battle.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
ViridianGymReceiveTM27:
;> hTextID = TEXT_VIRIDIANGYM_GIOVANNI_EARTH_BADGE_INFO
	ld a, TEXT_VIRIDIANGYM_GIOVANNI_EARTH_BADGE_INFO
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_BEAT_VIRIDIAN_GYM_GIOVANNI)
	ld hl, wEventFlags + $A
	set (EVENT_BEAT_VIRIDIAN_GYM_GIOVANNI) % 8, [hl]
;> if GiveItem(TM_FISSURE, 1):
	ld bc, ((TM_FISSURE) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>     hTextID = TEXT_VIRIDIANGYM_GIOVANNI_RECEIVED_TM27
	ld a, TEXT_VIRIDIANGYM_GIOVANNI_RECEIVED_TM27
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     set_event(EVENT_GOT_TM27)
	ld hl, wEventFlags + $A
	set (EVENT_GOT_TM27) % 8, [hl]
	jr .gym_victory
.bag_full
;> else:
;>     hTextID = TEXT_VIRIDIANGYM_GIOVANNI_TM27_NO_ROOM
	ld a, TEXT_VIRIDIANGYM_GIOVANNI_TM27_NO_ROOM
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
.gym_victory
;> wObtainedBadges |= 1 << BIT_EARTHBADGE
	ld hl, wObtainedBadges
	set BIT_EARTHBADGE, [hl]
;> wBeatGymFlags |= 1 << BIT_EARTHBADGE
	ld hl, wBeatGymFlags
	set BIT_EARTHBADGE, [hl]

;> for e in range(EVENT_BEAT_VIRIDIAN_GYM_TRAINER_0, EVENT_BEAT_VIRIDIAN_GYM_TRAINER_7 + 1):
	; deactivate gym trainers
;>     set_event(e)
	ld a, [wEventFlags + $A]
	or $ff - ((1 << ((EVENT_BEAT_VIRIDIAN_GYM_TRAINER_0) % 8)) - 1)
	ld [wEventFlags + $A], a
	ld a, [wEventFlags + $B]
	or (1 << (((EVENT_BEAT_VIRIDIAN_GYM_TRAINER_7) % 8) + 1)) - 1
	ld [wEventFlags + $B], a

;> wToggleableObjectIndex = TOGGLE_ROUTE_22_RIVAL_2
	ld a, TOGGLE_ROUTE_22_RIVAL_2
	ld [wToggleableObjectIndex], a
;> predef(ShowObject)
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> set_event(EVENT_2ND_ROUTE22_RIVAL_BATTLE)
	ld hl, wEventFlags + $A4
	set (EVENT_2ND_ROUTE22_RIVAL_BATTLE) % 8, [hl]
;> set_event(EVENT_ROUTE22_RIVAL_WANTS_BATTLE)
	set (EVENT_ROUTE22_RIVAL_WANTS_BATTLE) % 8, [hl]
;> return ViridianGymResetScripts()
	jp ViridianGymResetScripts

