;@ path: scripts/ViridianGym
;@ def ViridianGymGiovanniText() -> hl
;@ Giovanni: before the battle his challenge (and he engages the player); after it, TM27 if the bag had no room
;@ before - otherwise his farewell, and in a fade to black he is gone.
;@ test: skip a text script: the code after text_asm is run by the text engine
ViridianGymGiovanniText:
	db TX_START_ASM
;> if event(EVENT_BEAT_VIRIDIAN_GYM_GIOVANNI):
	ld a, [wEventFlags + $A]
	bit (EVENT_BEAT_VIRIDIAN_GYM_GIOVANNI) % 8, a
	jr z, .beforeBeat
;>     if not event(EVENT_GOT_TM27):        # the bag had no room for it after the battle
	bit (EVENT_GOT_TM27) % 8, a
	jr nz, .afterBeat
;>         ViridianGymReceiveTM27()
	call z, ViridianGymReceiveTM27
;>         DisableWaitingAfterTextDisplay()
	call DisableWaitingAfterTextDisplay
	jr .text_script_end
.afterBeat
;>     else:
;>         wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;>         PrintText(ViridianGymGiovanniText.PostBattleAdviceText)
	ld hl, .PostBattleAdviceText
	call PrintText
;>         GBFadeOutToBlack()                # and in the dark he leaves
	call GBFadeOutToBlack
;>         wToggleableObjectIndex = TOGGLE_VIRIDIAN_GYM_GIOVANNI
	ld a, TOGGLE_VIRIDIAN_GYM_GIOVANNI
	ld [wToggleableObjectIndex], a
;>         predef(HideObject)
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;>         UpdateSprites()
	call UpdateSprites
;>         Delay3()
	call Delay3
;>         GBFadeInFromBlack()
	call GBFadeInFromBlack
	jr .text_script_end
.beforeBeat
;> else:
;>     PrintText(ViridianGymGiovanniText.PreBattleText)
	ld hl, .PreBattleText
	call PrintText
;>     wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;>     SaveEndBattleTextPointers(ViridianGymGiovanniText.ReceivedEarthBadgeText, ViridianGymGiovanniText.ReceivedEarthBadgeText)
	ld hl, .ReceivedEarthBadgeText
	ld de, .ReceivedEarthBadgeText
	call SaveEndBattleTextPointers
;>     wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;>     EngageMapTrainer()
	call EngageMapTrainer
;>     InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;>     wGymLeaderNo = 8
	ld a, $8
	ld [wGymLeaderNo], a
;>     wViridianGymCurScript = SCRIPT_VIRIDIANGYM_GIOVANNI_POST_BATTLE
	ld a, SCRIPT_VIRIDIANGYM_GIOVANNI_POST_BATTLE
	ld [wViridianGymCurScript], a
.text_script_end
;> return TextScriptEnd()
	jp TextScriptEnd

.PreBattleText:
	db TX_FAR
	dw _ViridianGymGiovanniPreBattleText
	db BANK(_ViridianGymGiovanniPreBattleText)
	db TX_END

.ReceivedEarthBadgeText:
	db TX_FAR
	dw _ViridianGymGiovanniReceivedEarthBadgeText
	db BANK(_ViridianGymGiovanniReceivedEarthBadgeText)
	; probably supposed to play SFX_GET_ITEM_1 but the wrong music bank is loaded
	db TX_SOUND_GET_ITEM_1
	db TX_END

.PostBattleAdviceText:
	db TX_FAR
	dw _ViridianGymGiovanniPostBattleAdviceText
	db BANK(_ViridianGymGiovanniPostBattleAdviceText)
	db TX_WAIT_BUTTON
	db TX_END

