;@ path: scripts/PewterMart
;@ def PewterMart_Script()
;@ Pewter's Poké Mart: its texts draw their own boxes.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
PewterMart_Script:
;> EnableAutoTextBoxDrawing()
;> wAutoTextBoxDrawingControl = 1 << BIT_NO_AUTO_TEXT_BOX
	call EnableAutoTextBoxDrawing
	ld a, 1 << BIT_NO_AUTO_TEXT_BOX
	ld [wAutoTextBoxDrawingControl], a
	ret

