CeruleanBadgeHouse_h::
	db SHIP
	db $4, $4
	dw CeruleanBadgeHouse_Blocks
	dw CeruleanBadgeHouse_TextPointers
	dw CeruleanBadgeHouse_Script
	db 0
	dw CeruleanBadgeHouse_Object
;@ path: scripts/CeruleanBadgeHouse
;@ def CeruleanBadgeHouse_Script()
;@ The badge expert's house: no automatic text boxes (his badge menu draws its own), and texts wait for a
;@ button press.
CeruleanBadgeHouse_Script:
;> wAutoTextBoxDrawingControl = 1 << BIT_NO_AUTO_TEXT_BOX
;> wDoNotWaitForButtonPressAfterDisplayingText = 0
	ld a, 1 << BIT_NO_AUTO_TEXT_BOX
	ld [wAutoTextBoxDrawingControl], a
	dec a
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
	ret

;@ path: scripts/CeruleanBadgeHouse
CeruleanBadgeHouse_TextPointers:
	dw CeruleanBadgeHouseMiddleAgedManText
DEF TEXT_CERULEANBADGEHOUSE_MIDDLE_AGED_MAN EQU 1

;@ path: scripts/CeruleanBadgeHouse
;@ def CeruleanBadgeHouseMiddleAgedManText() -> hl
;@ The badge expert: a menu of the eight badges; for each one picked he explains what it does, until the
;@ player cancels.
;@ test: skip a text script: the code after text_asm is run by the text engine
CeruleanBadgeHouseMiddleAgedManText:
	db TX_START_ASM
;> PrintText(CeruleanBadgeHouseMiddleAgedManText.Text)
	ld hl, .Text
	call PrintText
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wListScrollOffset = 0
	ld [wListScrollOffset], a
;> while True:
;>     PrintText(CeruleanBadgeHouseMiddleAgedManText.WhichBadgeText)
.loop
	ld hl, .WhichBadgeText
	call PrintText
;>     LoadItemList(CeruleanBadgeHouseMiddleAgedManText.BadgeItemList)
	ld hl, .BadgeItemList
	call LoadItemList
;>     wListPointer[0], wListPointer[1] = addr(wItemList) & 0xFF, addr(wItemList) >> 8
	ld hl, wItemList
	ld a, l
	ld [wListPointer], a
	ld a, h
	ld [wListPointer + 1], a
;>     wPrintItemPrices = 0
	xor a
	ld [wPrintItemPrices], a
;>     wMenuItemToSwap = 0
	ld [wMenuItemToSwap], a
;>     wListMenuID = SPECIALLISTMENU
	ld a, SPECIALLISTMENU
	ld [wListMenuID], a
;>     if DisplayListMenuID():                 # carry: the player cancelled
;>         break
	call DisplayListMenuID
	jr c, .done
;>     t = CeruleanBadgeHouseBadgeTextPointers
	ld hl, CeruleanBadgeHouseBadgeTextPointers
;>     t += 2 * (wCurItem - BOULDERBADGE)
	ld a, [wCurItem]
	sub BOULDERBADGE
	add a
	ld d, $0
	ld e, a
	add hl, de
;>     PrintText(mem[t] | mem[t + 1] << 8)
	ld a, [hli]
	ld h, [hl]
	ld l, a
	call PrintText
	jr .loop
;> wListScrollOffset = 0
.done
	xor a
	ld [wListScrollOffset], a
;> PrintText(CeruleanBadgeHouseMiddleAgedManText.VisitAnyTimeText)
	ld hl, .VisitAnyTimeText
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.BadgeItemList:
	db NUM_BADGES ; #
	db BOULDERBADGE
	db CASCADEBADGE
	db THUNDERBADGE
	db RAINBOWBADGE
	db SOULBADGE
	db MARSHBADGE
	db VOLCANOBADGE
	db EARTHBADGE
	db -1 ; end

.Text:
	db TX_FAR
	dw _CeruleanBadgeHouseMiddleAgedManText
	db BANK(_CeruleanBadgeHouseMiddleAgedManText)
	db TX_END

.WhichBadgeText:
	db TX_FAR
	dw _CeruleanBadgeHouseMiddleAgedManWhichBadgeText
	db BANK(_CeruleanBadgeHouseMiddleAgedManWhichBadgeText)
	db TX_END

.VisitAnyTimeText:
	db TX_FAR
	dw _CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText
	db BANK(_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText)
	db TX_END

