WardensHouse_h::
	db LAB
	db $4, $5
	dw WardensHouse_Blocks
	dw WardensHouse_TextPointers
	dw WardensHouse_Script
	db 0
	dw WardensHouse_Object
;@ path: scripts/WardensHouse
;@ def WardensHouse_Script()
;@ Wardens House's map script: only lets texts draw their box.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
WardensHouse_Script:
;> EnableAutoTextBoxDrawing()
	jp EnableAutoTextBoxDrawing

;@ path: scripts/WardensHouse
WardensHouse_TextPointers:
	dw WardensHouseWardenText
DEF TEXT_WARDENSHOUSE_WARDEN EQU 1
	dw PickUpItemText
DEF TEXT_WARDENSHOUSE_RARE_CANDY EQU 2
	dw BoulderText
DEF TEXT_WARDENSHOUSE_BOULDER EQU 3
	dw WardensHouseDisplayText
DEF TEXT_WARDENSHOUSE_DISPLAY_LEFT EQU 4
	dw WardensHouseDisplayText
DEF TEXT_WARDENSHOUSE_DISPLAY_RIGHT EQU 5

;@ path: scripts/WardensHouse
;@ def WardensHouseWardenText() -> hl
;@ The Safari Zone warden, who lost his gold teeth: without them only gibberish; given the Gold Teeth, he
;@ thanks the player with HM04 (STRENGTH), if the bag has room, and explains it afterwards.
;@ test: skip a text script: the code after text_asm is run by the text engine
WardensHouseWardenText:
	db TX_START_ASM
;> T = WardensHouseWardenText
;> if event(EVENT_GOT_HM04):
;>@expl     PrintText(T.HM04ExplanationText)
	ld a, [wEventFlags + $47]
	bit (EVENT_GOT_HM04) % 8, a
	jr nz, .got_item
;> else:
;>     if not IsItemInBag(GOLD_TEETH):       # (zero means none) the player has the Gold Teeth
;>@gave         PrintText(T.GaveTheGoldTeethText)
;>@rm1         hItemToRemoveID = GOLD_TEETH
;>@rm2         farcall(RemoveItemByID)
;>@set         set_event(EVENT_GAVE_GOLD_TEETH)
	ld b, GOLD_TEETH
	call IsItemInBag
	jr nz, .have_gold_teeth
;>     elif not event(EVENT_GAVE_GOLD_TEETH):   # no teeth: only gibberish
	ld a, [wEventFlags + $47]
	bit (EVENT_GAVE_GOLD_TEETH) % 8, a
	jr nz, .gave_gold_teeth
;>         PrintText(T.Gibberish1Text)
	ld hl, .Gibberish1Text
	call PrintText
;>         YesNoChoice()
	call YesNoChoice
;>         PrintText(T.Gibberish3Text if wCurrentMenuItem else T.Gibberish2Text)
	ld a, [wCurrentMenuItem]
	and a
	ld hl, .Gibberish3Text
	jr nz, .refused
	ld hl, .Gibberish2Text
.refused
	call PrintText
;>         return TextScriptEnd()
	jr .done
.have_gold_teeth
;=@gave
	ld hl, .GaveTheGoldTeethText
	call PrintText
;=@rm1
	ld a, GOLD_TEETH
	ldh [hItemToRemoveID], a
;=@rm2
	ld b, BANK(RemoveItemByID)
	ld hl, RemoveItemByID
	call Bankswitch
;=@set
	ld hl, wEventFlags + $47
	set (EVENT_GAVE_GOLD_TEETH) % 8, [hl]
.gave_gold_teeth
;>     PrintText(T.ThanksText)
	ld hl, .ThanksText
	call PrintText
;>     if GiveItem(HM_STRENGTH, 1):
	ld bc, ((HM_STRENGTH) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>         PrintText(T.ReceivedHM04Text)
	ld hl, .ReceivedHM04Text
	call PrintText
;>         set_event(EVENT_GOT_HM04)
	ld hl, wEventFlags + $47
	set (EVENT_GOT_HM04) % 8, [hl]
	jr .done
.got_item
;=@expl
	ld hl, .HM04ExplanationText
	call PrintText
	jr .done
.bag_full
;>     else:
;>         PrintText(T.HM04NoRoomText)
	ld hl, .HM04NoRoomText
	call PrintText
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.Gibberish1Text:
	db TX_FAR
	dw _WardensHouseWardenGibberish1Text
	db BANK(_WardensHouseWardenGibberish1Text)
	db TX_END

.Gibberish2Text:
	db TX_FAR
	dw _WardensHouseWardenGibberish2Text
	db BANK(_WardensHouseWardenGibberish2Text)
	db TX_END

.Gibberish3Text:
	db TX_FAR
	dw _WardensHouseWardenGibberish3Text
	db BANK(_WardensHouseWardenGibberish3Text)
	db TX_END

.GaveTheGoldTeethText:
	db TX_FAR
	dw _WardensHouseWardenGaveTheGoldTeethText
	db BANK(_WardensHouseWardenGaveTheGoldTeethText)
	db TX_SOUND_GET_ITEM_1

.PoppedInHisTeethText: ; unreferenced
	db TX_FAR
	dw _WardensHouseWardenTeethPoppedInHisTeethText
	db BANK(_WardensHouseWardenTeethPoppedInHisTeethText)
	db TX_END

.ThanksText:
	db TX_FAR
	dw _WardensHouseWardenThanksText
	db BANK(_WardensHouseWardenThanksText)
	db TX_END

.ReceivedHM04Text:
	db TX_FAR
	dw _WardensHouseWardenReceivedHM04Text
	db BANK(_WardensHouseWardenReceivedHM04Text)
	db TX_SOUND_GET_ITEM_1
	db TX_END

.HM04ExplanationText:
	db TX_FAR
	dw _WardensHouseWardenHM04ExplanationText
	db BANK(_WardensHouseWardenHM04ExplanationText)
	db TX_END

.HM04NoRoomText:
	db TX_FAR
	dw _WardensHouseWardenHM04NoRoomText
	db BANK(_WardensHouseWardenHM04NoRoomText)
	db TX_END

;@ path: scripts/WardensHouse
;@ def WardensHouseDisplayText() -> hl
;@ The warden's display cases: photos and fossils on the left, merchandise on the right.
;@ test: skip a text script: the code after text_asm is run by the text engine
WardensHouseDisplayText:
	db TX_START_ASM
;> if hTextID != TEXT_WARDENSHOUSE_DISPLAY_LEFT:
;>     text = WardensHouseDisplayText.MerchandiseText
	ldh a, [hTextID]
	cp TEXT_WARDENSHOUSE_DISPLAY_LEFT
	ld hl, .MerchandiseText
	jr nz, .print_text
;> else:
;>     text = WardensHouseDisplayText.PhotosAndFossilsText
	ld hl, .PhotosAndFossilsText
.print_text
;> PrintText(text)
;> return TextScriptEnd()
	call PrintText
	jp TextScriptEnd

.PhotosAndFossilsText:
	db TX_FAR
	dw _WardensHouseDisplayPhotosAndFossilsText
	db BANK(_WardensHouseDisplayPhotosAndFossilsText)
	db TX_END

.MerchandiseText:
	db TX_FAR
	dw _WardensHouseDisplayMerchandiseText
	db BANK(_WardensHouseDisplayMerchandiseText)
	db TX_END
;> # the house's objects: the warden, a Rare Candy, a boulder
DEF WARDENSHOUSE_WARDEN EQU 1
	EXPORT WARDENSHOUSE_WARDEN
DEF WARDENSHOUSE_RARE_CANDY EQU 2
	EXPORT WARDENSHOUSE_RARE_CANDY
DEF WARDENSHOUSE_BOULDER EQU 3
	EXPORT WARDENSHOUSE_BOULDER

;@ path: data/maps/objects/WardensHouse
WardensHouse_Object:
	db $17 ; border block

	db 2
	db 7, 4, 4 - 1, LAST_MAP
	db 7, 5, 4 - 1, LAST_MAP

	db 2
	db 3, 4, TEXT_WARDENSHOUSE_DISPLAY_LEFT
	db 3, 5, TEXT_WARDENSHOUSE_DISPLAY_RIGHT

	db 3
	db SPRITE_WARDEN
	db 3 + 4
	db 2 + 4
	db STAY
	db NONE
	db TEXT_WARDENSHOUSE_WARDEN
	db SPRITE_POKE_BALL
	db 3 + 4
	db 8 + 4
	db STAY
	db NONE
	db ITEM | TEXT_WARDENSHOUSE_RARE_CANDY
	db RARE_CANDY
	db SPRITE_BOULDER
	db 4 + 4
	db 8 + 4
	db STAY
	db BOULDER_MOVEMENT_BYTE_2
	db TEXT_WARDENSHOUSE_BOULDER

	dw (wOverworldMap + 7 + (WARDENS_HOUSE_WIDTH) + ((WARDENS_HOUSE_WIDTH) + 6) * ((7) >> 1) + ((4) >> 1))
	db 7, 4
	dw (wOverworldMap + 7 + (WARDENS_HOUSE_WIDTH) + ((WARDENS_HOUSE_WIDTH) + 6) * ((7) >> 1) + ((5) >> 1))
	db 7, 5
;@ path: maps
WardensHouse_Blocks:
	db $01, $01, $01, $01, $01, $29, $07, $20, $1d, $1e, $07, $07, $07, $07, $07, $0d
	db $07, $0c, $07, $0e

SafariZoneGate_h::
	db GATE
	db $3, $4
	dw SafariZoneGate_Blocks
	dw SafariZoneGate_TextPointers
	dw SafariZoneGate_Script
	db 0
	dw SafariZoneGate_Object
;@ path: scripts/SafariZoneGate
;@ def SafariZoneGate_Script()
;@ The Safari Zone's entrance: run the current step (paying the entry fee, leaving the zone).
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
SafariZoneGate_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wSafariZoneGateCurScript, SafariZoneGate_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld hl, SafariZoneGate_ScriptPointers
	ld a, [wSafariZoneGateCurScript]
	jp CallFunctionInTable

;@ path: scripts/SafariZoneGate
SafariZoneGate_ScriptPointers:
	dw SafariZoneGateDefaultScript
DEF SCRIPT_SAFARIZONEGATE_DEFAULT EQU 0
	dw SafariZoneGatePlayerMovingRightScript
DEF SCRIPT_SAFARIZONEGATE_PLAYER_MOVING_RIGHT EQU 1
	dw SafariZoneGateWouldYouLikeToJoinScript
DEF SCRIPT_SAFARIZONEGATE_WOULD_YOU_LIKE_TO_JOIN EQU 2
	dw SafariZoneGatePlayerMovingUpScript
DEF SCRIPT_SAFARIZONEGATE_PLAYER_MOVING EQU 3
	dw SafariZoneGatePlayerMovingDownScript
DEF SCRIPT_SAFARIZONEGATE_PLAYER_MOVING_DOWN EQU 4
	dw SafariZoneGateLeavingSafariScript
DEF SCRIPT_SAFARIZONEGATE_LEAVING_SAFARI EQU 5
	dw SafariZoneGateSetScriptAfterMoveScript
DEF SCRIPT_SAFARIZONEGATE_SET_SCRIPT_AFTER_MOVE EQU 6
	EXPORT SCRIPT_SAFARIZONEGATE_LEAVING_SAFARI ; used by engine/events/hidden_events/safari_game.asm

;@ path: scripts/SafariZoneGate
;@ def SafariZoneGateDefaultScript()
;@ Walking up to the counter: the worker greets the player, who is turned right (and walked up next to the
;@ worker first if needed) before being asked to join.
;@ test: skip the counter spots sit under a local label, which the pseudo-code can only name
SafariZoneGateDefaultScript:
;> if not ArePlayerCoordsInArray(SafariZoneGateDefaultScript.PlayerNextToSafariZoneWorker1CoordsArray):
;>     return
	ld hl, .PlayerNextToSafariZoneWorker1CoordsArray
	call ArePlayerCoordsInArray
	ret nc
;> hTextID = TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER1_1
	ld a, TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER1_1
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> mem[wSpritePlayerStateData1FacingDirection] = SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_RIGHT
	ld [wSpritePlayerStateData1FacingDirection], a
;> if wCoordIndex != 1:
	ld a, [wCoordIndex]
	cp 1 ; index of second, lower entry in .PlayerNextToSafariZoneWorker1CoordsArray
	jr z, .player_not_next_to_worker
;>     wSafariZoneGateCurScript = SCRIPT_SAFARIZONEGATE_WOULD_YOU_LIKE_TO_JOIN
	ld a, SCRIPT_SAFARIZONEGATE_WOULD_YOU_LIKE_TO_JOIN
	ld [wSafariZoneGateCurScript], a
;>     return
	ret
.player_not_next_to_worker
;> SafariZoneEntranceAutoWalk(PAD_RIGHT, 1)
	ld a, PAD_RIGHT
	ld c, 1
	call SafariZoneEntranceAutoWalk
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wSafariZoneGateCurScript = SCRIPT_SAFARIZONEGATE_PLAYER_MOVING_RIGHT
	ld a, SCRIPT_SAFARIZONEGATE_PLAYER_MOVING_RIGHT
	ld [wSafariZoneGateCurScript], a
	ret

.PlayerNextToSafariZoneWorker1CoordsArray:
	db 2, 3
	db 2, 4
	db -1 ; end

;@ path: scripts/SafariZoneGate
;@ def SafariZoneGatePlayerMovingRightScript()
;@ Once the step to the worker is walked, he asks the player to join.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
SafariZoneGatePlayerMovingRightScript:
;> if not SafariZoneGateReturnSimulatedJoypadStateScript():
;>     return
	call SafariZoneGateReturnSimulatedJoypadStateScript
	ret nz

;> return SafariZoneGateWouldYouLikeToJoinScript()
;@ path: scripts/SafariZoneGate
;@ def SafariZoneGateWouldYouLikeToJoinScript()
;@ The worker asks whether the player would like to join the Safari Game.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
SafariZoneGateWouldYouLikeToJoinScript:
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wJoyIgnore = 0
	ld [wJoyIgnore], a
;> UpdateSprites()
	call UpdateSprites
;> hTextID = TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER1_WOULD_YOU_LIKE_TO_JOIN
	ld a, TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER1_WOULD_YOU_LIKE_TO_JOIN
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
	ret

;@ path: scripts/SafariZoneGate
;@ def SafariZoneGatePlayerMovingUpScript()
;@ Once the player has walked in, the next step handles coming back out.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
SafariZoneGatePlayerMovingUpScript:
;> if not SafariZoneGateReturnSimulatedJoypadStateScript():
;>     return
	call SafariZoneGateReturnSimulatedJoypadStateScript
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wSafariZoneGateCurScript = SCRIPT_SAFARIZONEGATE_LEAVING_SAFARI
	ld a, SCRIPT_SAFARIZONEGATE_LEAVING_SAFARI
	ld [wSafariZoneGateCurScript], a
	ret

;@ path: scripts/SafariZoneGate
;@ def SafariZoneGateLeavingSafariScript()
;@ Coming back through the gate: after a finished game the worker says "good haul, come again", the balls are
;@ taken back and the player walks out; leaving early, the worker asks whether the player is done.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
SafariZoneGateLeavingSafariScript:
;> wPlayerMovingDirection = PLAYER_DIR_DOWN
	ld a, PLAYER_DIR_DOWN
	ld [wPlayerMovingDirection], a
;> over = event(EVENT_SAFARI_GAME_OVER)
	ld hl, wEventFlags + $49
	bit (EVENT_SAFARI_GAME_OVER) % 8, [hl]
;> reset_event(EVENT_SAFARI_GAME_OVER)
	res (EVENT_SAFARI_GAME_OVER) % 8, [hl]
;> if not over:
	jr z, .leaving_early
;>@e1     hTextID = TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER1_LEAVING_EARLY
;>@e2     DisplayTextID()
;>@e3     return
;> reset_event(EVENT_IN_SAFARI_ZONE)
	res (EVENT_IN_SAFARI_ZONE) % 8, [hl]
;> UpdateSprites()
	call UpdateSprites
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hTextID = TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER1_GOOD_HAUL_COME_AGAIN
	ld a, TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER1_GOOD_HAUL_COME_AGAIN
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wNumSafariBalls = 0
	xor a
	ld [wNumSafariBalls], a
;> SafariZoneEntranceAutoWalk(PAD_DOWN, 3)
	ld a, PAD_DOWN
	ld c, 3
	call SafariZoneEntranceAutoWalk
;> wSafariZoneGateCurScript = SCRIPT_SAFARIZONEGATE_PLAYER_MOVING_DOWN
	ld a, SCRIPT_SAFARIZONEGATE_PLAYER_MOVING_DOWN
	ld [wSafariZoneGateCurScript], a
	jr .return
.leaving_early
;=@e1
	ld a, TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER1_LEAVING_EARLY
	ldh [hTextID], a
;=@e2
	call DisplayTextID
;=@e3
.return
	ret

;@ path: scripts/SafariZoneGate
;@ def SafariZoneGatePlayerMovingDownScript()
;@ Once the player has walked out, give the controls back and return to the default step.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
SafariZoneGatePlayerMovingDownScript:
;> if not SafariZoneGateReturnSimulatedJoypadStateScript():
;>     return
	call SafariZoneGateReturnSimulatedJoypadStateScript
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wSafariZoneGateCurScript = SCRIPT_SAFARIZONEGATE_DEFAULT
	ld a, SCRIPT_SAFARIZONEGATE_DEFAULT
	ld [wSafariZoneGateCurScript], a
	ret

;@ path: scripts/SafariZoneGate
;@ def SafariZoneGateSetScriptAfterMoveScript()
;@ Once the walk is over, go on to the step chosen beforehand (wNextSafariZoneGateScript).
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
SafariZoneGateSetScriptAfterMoveScript:
;> if not SafariZoneGateReturnSimulatedJoypadStateScript():
;>     return
	call SafariZoneGateReturnSimulatedJoypadStateScript
	ret nz
;> Delay3()
	call Delay3
;> wSafariZoneGateCurScript = wNextSafariZoneGateScript
	ld a, [wNextSafariZoneGateScript]
	ld [wSafariZoneGateCurScript], a
	ret

;@ path: scripts/SafariZoneGate
;@ def SafariZoneEntranceAutoWalk(button: a, count: c)
;@ Walk the player `count` steps by pressing `button` (simulated input).
;@ test: count = rand(1, 3)
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
SafariZoneEntranceAutoWalk:
;> wSimulatedJoypadStatesIndex = count
	push af
	ld b, 0
	ld a, c
	ld [wSimulatedJoypadStatesIndex], a
;> FillMemory(addr(wSimulatedJoypadStatesEnd), count, button)
	ld hl, wSimulatedJoypadStatesEnd
	pop af
	call FillMemory
;> return StartSimulatingJoypadStates()
	jp StartSimulatingJoypadStates

;@ path: scripts/SafariZoneGate
;@ def SafariZoneGateReturnSimulatedJoypadStateScript() -> zero
;@ Zero flag once the simulated walk is over.
;@ test: hLoadedROMBank = 0x1D    # the bank this code runs in
SafariZoneGateReturnSimulatedJoypadStateScript:
;> return wSimulatedJoypadStatesIndex == 0
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret

;@ path: scripts/SafariZoneGate
SafariZoneGate_TextPointers:
	dw SafariZoneGateSafariZoneWorker1Text
DEF TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER1 EQU 1
