	db BANK(_SafariZoneGateSafariZoneWorker1Text)
	db TX_END

;@ path: scripts/SafariZoneGate
;@ def SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText() -> hl
;@ The entry fee: ¥500 buys 30 Safari Balls and 502 steps in the zone, and the player walks in; without the
;@ money, or on "no", the player walks back down.
;@ test: skip a text script: the code after text_asm is run by the text engine
SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText:
;> T = SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText
;> wTextBoxID = MONEY_BOX
	db TX_FAR
	dw _SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText
	db BANK(_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText)
	db TX_START_ASM
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;> DisplayTextBoxID()
	call DisplayTextBoxID
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
	jp nz, .PleaseComeAgain
;>@e1     PrintText(T.PleaseComeAgainText)
;> else:
;>     hMoney[0] = 0x00                        # 500, in BCD
	xor a
	ldh [hMoney], a
;>     hMoney[1] = 0x05
	ld a, $05
	ldh [hMoney + 1], a
;>     hMoney[2] = 0x00
	ld a, $00
	ldh [hMoney + 2], a
;>     if not HasEnoughMoney():
	call HasEnoughMoney
	jr nc, .success
;=@ne
	ld hl, .NotEnoughMoneyText
	call PrintText
	jr .CantPayWalkDown

.success
;>         wPriceTemp[0] = 0x00
	xor a
	ld [wPriceTemp], a
;>         wPriceTemp[1] = 0x05
	ld a, $05
	ld [wPriceTemp + 1], a
;>         wPriceTemp[2] = 0x00
	ld a, $00
	ld [wPriceTemp + 2], a
;>         predef(SubBCDPredef, hl=addr(wPriceTemp) + 2, de=addr(wPlayerMoney) + 2, bc=3)     # pay
	ld hl, wPriceTemp + 2
	ld de, wPlayerMoney + 2
	ld c, 3
	ld a, (SubBCDPredefPredef - PredefPointers) / 3
	call Predef
;>         wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;>         DisplayTextBoxID()
	call DisplayTextBoxID
;>         PrintText(T.MakePaymentText)
	ld hl, .MakePaymentText
	call PrintText
;>         wNumSafariBalls = 30
	ld a, 30
	ld [wNumSafariBalls], a
;>         mem[addr(wSafariSteps)], mem[addr(wSafariSteps) + 1] = 502 >> 8, 502 & 0xFF   # big-endian
	ld a, HIGH(502)
	ld [wSafariSteps], a
	ld a, LOW(502)
	ld [wSafariSteps + 1], a
;>         SafariZoneEntranceAutoWalk(PAD_UP, 3)
	ld a, PAD_UP
	ld c, 3
	call SafariZoneEntranceAutoWalk
;>         set_event(EVENT_IN_SAFARI_ZONE)
	ld hl, wEventFlags + $49
	set (EVENT_IN_SAFARI_ZONE) % 8, [hl]
;>         reset_event(EVENT_SAFARI_GAME_OVER)
	res (EVENT_SAFARI_GAME_OVER) % 8, [hl]
;>         wSafariZoneGateCurScript = SCRIPT_SAFARIZONEGATE_PLAYER_MOVING
	ld a, SCRIPT_SAFARIZONEGATE_PLAYER_MOVING
	ld [wSafariZoneGateCurScript], a
;>         return TextScriptEnd()
;>@ne     PrintText(T.NotEnoughMoneyText)
	jr .done

.PleaseComeAgain
;=@e1
	ld hl, .PleaseComeAgainText
	call PrintText
.CantPayWalkDown
;> SafariZoneEntranceAutoWalk(PAD_DOWN, 1)
	ld a, PAD_DOWN
	ld c, 1
	call SafariZoneEntranceAutoWalk
;> wSafariZoneGateCurScript = SCRIPT_SAFARIZONEGATE_PLAYER_MOVING_DOWN
	ld a, SCRIPT_SAFARIZONEGATE_PLAYER_MOVING_DOWN
	ld [wSafariZoneGateCurScript], a
.done
;> return TextScriptEnd()
	jp TextScriptEnd

.MakePaymentText
	db TX_FAR
	dw _SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText
	db BANK(_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText)
	db TX_SOUND_GET_ITEM_1
	db TX_FAR
	dw _SafariZoneGateSafariZoneWorker1CallYouOnThePAText
	db BANK(_SafariZoneGateSafariZoneWorker1CallYouOnThePAText)
	db TX_END

.PleaseComeAgainText
	db TX_FAR
	dw _SafariZoneGateSafariZoneWorker1PleaseComeAgainText
	db BANK(_SafariZoneGateSafariZoneWorker1PleaseComeAgainText)
	db TX_END

.NotEnoughMoneyText
	db TX_FAR
	dw _SafariZoneGateSafariZoneWorker1NotEnoughMoneyText
	db BANK(_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText)
	db TX_END

;@ path: scripts/SafariZoneGate
;@ def SafariZoneGateSafariZoneWorker1LeavingEarlyText() -> hl
;@ Leaving the zone before the game is over: on "yes" the player returns the Safari Balls and walks out; on "no",
;@ good luck, and the player walks back in.
;@ test: skip a text script: the code after text_asm is run by the text engine
SafariZoneGateSafariZoneWorker1LeavingEarlyText:
;> YesNoChoice()
	db TX_FAR
	dw _SafariZoneGateSafariZoneWorker1LeavingEarlyText
	db BANK(_SafariZoneGateSafariZoneWorker1LeavingEarlyText)
	db TX_START_ASM
	call YesNoChoice
;> if not wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .not_ready_to_leave
;>     PrintText(SafariZoneGateSafariZoneWorker1LeavingEarlyText.ReturnSafariBallsText)
	ld hl, .ReturnSafariBallsText
	call PrintText
;>     mem[wSpritePlayerStateData1FacingDirection] = SPRITE_FACING_DOWN
	xor a
	ld [wSpritePlayerStateData1FacingDirection], a
;>     SafariZoneEntranceAutoWalk(PAD_DOWN, 3)
	ld a, PAD_DOWN
	ld c, 3
	call SafariZoneEntranceAutoWalk
;>     reset_event(EVENT_SAFARI_GAME_OVER)
	ld hl, wEventFlags + $49
	res (EVENT_SAFARI_GAME_OVER) % 8, [hl]
;>     reset_event(EVENT_IN_SAFARI_ZONE)
	res (EVENT_IN_SAFARI_ZONE) % 8, [hl]
;>     wNextSafariZoneGateScript = SCRIPT_SAFARIZONEGATE_DEFAULT
	ld a, SCRIPT_SAFARIZONEGATE_DEFAULT
	ld [wNextSafariZoneGateScript], a
	jr .set_current_script
.not_ready_to_leave
;> else:
;>     PrintText(SafariZoneGateSafariZoneWorker1LeavingEarlyText.GoodLuckText)
	ld hl, .GoodLuckText
	call PrintText
;>     mem[wSpritePlayerStateData1FacingDirection] = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	ld [wSpritePlayerStateData1FacingDirection], a
;>     SafariZoneEntranceAutoWalk(PAD_UP, 1)
	ld a, PAD_UP
	ld c, 1
	call SafariZoneEntranceAutoWalk
;>     wNextSafariZoneGateScript = SCRIPT_SAFARIZONEGATE_LEAVING_SAFARI
	ld a, SCRIPT_SAFARIZONEGATE_LEAVING_SAFARI
	ld [wNextSafariZoneGateScript], a
.set_current_script
;> wSafariZoneGateCurScript = SCRIPT_SAFARIZONEGATE_SET_SCRIPT_AFTER_MOVE
	ld a, SCRIPT_SAFARIZONEGATE_SET_SCRIPT_AFTER_MOVE
	ld [wSafariZoneGateCurScript], a
;> return TextScriptEnd()
	jp TextScriptEnd

.ReturnSafariBallsText
	db TX_FAR
	dw _SafariZoneGateSafariZoneWorker1ReturnSafariBallsText
	db BANK(_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText)
	db TX_END

.GoodLuckText
	db TX_FAR
	dw _SafariZoneGateSafariZoneWorker1GoodLuckText
	db BANK(_SafariZoneGateSafariZoneWorker1GoodLuckText)
	db TX_END

;@ path: scripts/SafariZoneGate
SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText:
	db TX_FAR
	dw _SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText
	db BANK(_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText)
	db TX_END

;@ path: scripts/SafariZoneGate
;@ def SafariZoneGateSafariZoneWorker2Text() -> hl
;@ The second worker: "first time here?" - on yes he explains the Safari Zone, otherwise "you're a regular".
;@ test: skip a text script: the code after text_asm is run by the text engine
SafariZoneGateSafariZoneWorker2Text:
