	call YesNoChoice
;> if wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
;>     PrintText(SafariZoneGateSafariZoneWorker2Text.YoureARegularHereText)
	ld hl, .YoureARegularHereText
	jr nz, .print_text
;> else:
;>     PrintText(SafariZoneGateSafariZoneWorker2Text.SafariZoneExplanationText)
	ld hl, .SafariZoneExplanationText
.print_text
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.FirstTimeHereText
	db TX_FAR
	dw _SafariZoneGateSafariZoneWorker2FirstTimeHereText
	db BANK(_SafariZoneGateSafariZoneWorker2FirstTimeHereText)
