DEF SAFARIZONEGATE_SAFARI_ZONE_WORKER1 EQU 1
	EXPORT SAFARIZONEGATE_SAFARI_ZONE_WORKER1
DEF SAFARIZONEGATE_SAFARI_ZONE_WORKER2 EQU 2
	EXPORT SAFARIZONEGATE_SAFARI_ZONE_WORKER2

;@ path: data/maps/objects/SafariZoneGate
SafariZoneGate_Object:
	db $a ; border block

	db 4
	db 5, 3, 5 - 1, LAST_MAP
	db 5, 4, 5 - 1, LAST_MAP
	db 0, 3, 1 - 1, SAFARI_ZONE_CENTER
	db 0, 4, 2 - 1, SAFARI_ZONE_CENTER

	db 0

	db 2
	db SPRITE_SAFARI_ZONE_WORKER
	db 2 + 4
	db 6 + 4
	db STAY
	db LEFT
	db TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER1
	db SPRITE_SAFARI_ZONE_WORKER
	db 4 + 4
	db 1 + 4
	db STAY
	db RIGHT
	db TEXT_SAFARIZONEGATE_SAFARI_ZONE_WORKER2

	dw (wOverworldMap + 7 + (SAFARI_ZONE_GATE_WIDTH) + ((SAFARI_ZONE_GATE_WIDTH) + 6) * ((5) >> 1) + ((3) >> 1))
	db 5, 3
	dw (wOverworldMap + 7 + (SAFARI_ZONE_GATE_WIDTH) + ((SAFARI_ZONE_GATE_WIDTH) + 6) * ((5) >> 1) + ((4) >> 1))
	db 5, 4
	dw (wOverworldMap + 7 + (SAFARI_ZONE_GATE_WIDTH) + ((SAFARI_ZONE_GATE_WIDTH) + 6) * ((0) >> 1) + ((3) >> 1))
	db 0, 3
	dw (wOverworldMap + 7 + (SAFARI_ZONE_GATE_WIDTH) + ((SAFARI_ZONE_GATE_WIDTH) + 6) * ((0) >> 1) + ((4) >> 1))
	db 0, 4
;@ path: maps
SafariZoneGate_Blocks:
	db $16, $6b, $6a, $17, $02, $09, $08, $01, $18, $6c, $69, $19

FuchsiaGym_h::
	db GYM
	db $9, $5
	dw FuchsiaGym_Blocks
	dw FuchsiaGym_TextPointers
	dw FuchsiaGym_Script
	db 0
	dw FuchsiaGym_Object
;@ path: scripts/FuchsiaGym
;@ def FuchsiaGym_Script()
;@ Fuchsia Gym's map script: on entering, set the city and leader names (Fuchsia City, Koga) for the badge
;@ texts, then run the current step of the gym's script (its trainers and Koga).
;@ test: skip the names sit under local labels, which the pseudo-code cannot reach
FuchsiaGym_Script:
;> # the names, once on entering (the local routine .LoadNames):
;>@ld loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
;>@res wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	call .LoadNames
;>@if if loaded:
;>@names     LoadGymLeaderAndCityName(FuchsiaGym_Script.CityName, FuchsiaGym_Script.LeaderName)
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wFuchsiaGymCurScript = ExecuteCurMapScriptInTable(wFuchsiaGymCurScript, FuchsiaGymTrainerHeaders, FuchsiaGym_ScriptPointers)
	ld hl, FuchsiaGymTrainerHeaders
	ld de, FuchsiaGym_ScriptPointers
	ld a, [wFuchsiaGymCurScript]
	call ExecuteCurMapScriptInTable
	ld [wFuchsiaGymCurScript], a
	ret

.LoadNames:
;=@ld
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;=@res
	res BIT_CUR_MAP_LOADED_2, [hl]
;=@if
	ret z
;=@names
	ld hl, .CityName
	ld de, .LeaderName
	call LoadGymLeaderAndCityName
	ret

.CityName:
	db "FUCHSIA CITY@"

.LeaderName:
	db "KOGA@"

;@ path: scripts/FuchsiaGym
;@ def FuchsiaGymResetScripts()
;@ Back to the gym's default step (after a lost battle or after the badge), with the controls given back.
FuchsiaGymResetScripts:
;> wJoyIgnore = 0
	xor a ; SCRIPT_FUCHSIAGYM_DEFAULT
	ld [wJoyIgnore], a
;> wFuchsiaGymCurScript = SCRIPT_FUCHSIAGYM_DEFAULT
	ld [wFuchsiaGymCurScript], a
;> wCurMapScript = SCRIPT_FUCHSIAGYM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/FuchsiaGym
FuchsiaGym_ScriptPointers:
	dw CheckFightingMapTrainers
DEF SCRIPT_FUCHSIAGYM_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_FUCHSIAGYM_START_BATTLE EQU 1
	dw EndTrainerBattle
DEF SCRIPT_FUCHSIAGYM_END_BATTLE EQU 2
	dw FuchsiaGymKogaPostBattleScript
DEF SCRIPT_FUCHSIAGYM_KOGA_POST_BATTLE EQU 3

;@ path: scripts/FuchsiaGym
;@ def FuchsiaGymKogaPostBattleScript()
;@ After the battle with Koga: lost, start over; won, go on to the badge and TM06.
FuchsiaGymKogaPostBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return FuchsiaGymResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, FuchsiaGymResetScripts
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
; fallthrough

;> return FuchsiaGymReceiveTM06()
;@ path: scripts/FuchsiaGym
;@ def FuchsiaGymReceiveTM06()
;@ Koga's reward: the Soul Badge text, TM06 (TOXIC) if the bag has room, the badge itself, and all the gym's
;@ trainers count as beaten.
FuchsiaGymReceiveTM06:
;> hTextID = TEXT_FUCHSIAGYM_KOGA_SOUL_BADGE_INFO
	ld a, TEXT_FUCHSIAGYM_KOGA_SOUL_BADGE_INFO
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_BEAT_KOGA)
	ld hl, wEventFlags + $4B
	set (EVENT_BEAT_KOGA) % 8, [hl]
;> if GiveItem(TM_TOXIC, 1):
	ld bc, ((TM_TOXIC) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .BagFull
;>     hTextID = TEXT_FUCHSIAGYM_KOGA_RECEIVED_TM06
	ld a, TEXT_FUCHSIAGYM_KOGA_RECEIVED_TM06
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     set_event(EVENT_GOT_TM06)
	ld hl, wEventFlags + $4B
	set (EVENT_GOT_TM06) % 8, [hl]
	jr .gymVictory
;> else:
.BagFull
;>     hTextID = TEXT_FUCHSIAGYM_KOGA_TM06_NO_ROOM
	ld a, TEXT_FUCHSIAGYM_KOGA_TM06_NO_ROOM
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;> wObtainedBadges |= 1 << BIT_SOULBADGE
.gymVictory
	ld hl, wObtainedBadges
	set BIT_SOULBADGE, [hl]
;> wBeatGymFlags |= 1 << BIT_SOULBADGE
	ld hl, wBeatGymFlags
	set BIT_SOULBADGE, [hl]
;> for e in range(EVENT_BEAT_FUCHSIA_GYM_TRAINER_0, EVENT_BEAT_FUCHSIA_GYM_TRAINER_5 + 1):

	; deactivate gym trainers
	ld a, [wEventFlags + $4B]
	or (1 << (((EVENT_BEAT_FUCHSIA_GYM_TRAINER_5) % 8) + 1)) - (1 << ((EVENT_BEAT_FUCHSIA_GYM_TRAINER_0) % 8))
;>     set_event(e)
	ld [wEventFlags + $4B], a

;> return FuchsiaGymResetScripts()
	jp FuchsiaGymResetScripts

;@ path: scripts/FuchsiaGym
FuchsiaGym_TextPointers:
	dw FuchsiaGymKogaText
DEF TEXT_FUCHSIAGYM_KOGA EQU 1
	dw FuchsiaGymRocker1Text
DEF TEXT_FUCHSIAGYM_ROCKER1 EQU 2
	dw FuchsiaGymRocker2Text
DEF TEXT_FUCHSIAGYM_ROCKER2 EQU 3
	dw FuchsiaGymRocker3Text
DEF TEXT_FUCHSIAGYM_ROCKER3 EQU 4
	dw FuchsiaGymRocker4Text
DEF TEXT_FUCHSIAGYM_ROCKER4 EQU 5
	dw FuchsiaGymRocker5Text
DEF TEXT_FUCHSIAGYM_ROCKER5 EQU 6
	dw FuchsiaGymRocker6Text
DEF TEXT_FUCHSIAGYM_ROCKER6 EQU 7
	dw FuchsiaGymGymGuideText
DEF TEXT_FUCHSIAGYM_GYM_GUIDE EQU 8
	dw FuchsiaGymKogaSoulBadgeInfoText
DEF TEXT_FUCHSIAGYM_KOGA_SOUL_BADGE_INFO EQU 9
	dw FuchsiaGymKogaReceivedTM06Text
DEF TEXT_FUCHSIAGYM_KOGA_RECEIVED_TM06 EQU $A
	dw FuchsiaGymKogaTM06NoRoomText
DEF TEXT_FUCHSIAGYM_KOGA_TM06_NO_ROOM EQU $B

