;@ path: scripts/FuchsiaGym
;@ def FuchsiaGymKogaText() -> hl
;@ Koga: before the battle he engages the player; after it he gives TM06 if he still owes it, and otherwise
;@ has advice.
;@ test: skip a text script: the code after text_asm is run by the text engine
FuchsiaGymKogaText:
	db TX_START_ASM
;> if event(EVENT_BEAT_KOGA):
	ld a, [wEventFlags + $4B]
	bit (EVENT_BEAT_KOGA) % 8, a
	jr z, .beforeBeat
;>     if event(EVENT_GOT_TM06):
	bit (EVENT_GOT_TM06) % 8, a
	jr nz, .afterBeat
;>         PrintText(FuchsiaGymKogaText.PostBattleAdviceText)
;>     else:
;>         FuchsiaGymReceiveTM06()
	call z, FuchsiaGymReceiveTM06
;>         DisableWaitingAfterTextDisplay()
	call DisableWaitingAfterTextDisplay
;>     return TextScriptEnd()
	jr .done
.afterBeat
	ld hl, .PostBattleAdviceText
	call PrintText
	jr .done
.beforeBeat
;> PrintText(FuchsiaGymKogaText.BeforeBattleText)
	ld hl, .BeforeBattleText
	call PrintText
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(FuchsiaGymKogaText.ReceivedSoulBadgeText, FuchsiaGymKogaText.ReceivedSoulBadgeText)
	ld hl, .ReceivedSoulBadgeText
	ld de, .ReceivedSoulBadgeText
	call SaveEndBattleTextPointers
;> wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;> EngageMapTrainer()
	call EngageMapTrainer
;> InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;> wGymLeaderNo = 5
	ld a, $5
	ld [wGymLeaderNo], a
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> wFuchsiaGymCurScript = SCRIPT_FUCHSIAGYM_KOGA_POST_BATTLE
	ld a, SCRIPT_FUCHSIAGYM_KOGA_POST_BATTLE
	ld [wFuchsiaGymCurScript], a
;> return TextScriptEnd()
.done
	jp TextScriptEnd

.BeforeBattleText:
	db TX_FAR
	dw _FuchsiaGymKogaBeforeBattleText
	db BANK(_FuchsiaGymKogaBeforeBattleText)
	db TX_END

.ReceivedSoulBadgeText:
	db TX_FAR
	dw _FuchsiaGymKogaReceivedSoulBadgeText
	db BANK(_FuchsiaGymKogaReceivedSoulBadgeText)
	db TX_END

.PostBattleAdviceText:
	db TX_FAR
	dw _FuchsiaGymKogaPostBattleAdviceText
	db BANK(_FuchsiaGymKogaPostBattleAdviceText)
	db TX_END

;@ path: scripts/FuchsiaGym
FuchsiaGymKogaSoulBadgeInfoText:
	db TX_FAR
	dw _FuchsiaGymKogaSoulBadgeInfoText
	db BANK(_FuchsiaGymKogaSoulBadgeInfoText)
	db TX_END

;@ path: scripts/FuchsiaGym
FuchsiaGymKogaReceivedTM06Text:
