;@ path: scripts/FuchsiaGym
;@ def FuchsiaGymGymGuideText() -> hl
;@ The gym guide: advice before the battle with Koga, praise after it.
;@ test: skip a text script: the code after text_asm is run by the text engine
FuchsiaGymGymGuideText:
	db TX_START_ASM
;> if event(EVENT_BEAT_KOGA):
;>     text = FuchsiaGymGymGuideText.BeatKogaText
	ld a, [wEventFlags + $4B]
	bit (EVENT_BEAT_KOGA) % 8, a
	ld hl, .BeatKogaText
	jr nz, .afterBeat
;> else:
;>     text = FuchsiaGymGymGuideText.ChampInMakingText
	ld hl, .ChampInMakingText
.afterBeat
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.ChampInMakingText:
	db TX_FAR
	dw _FuchsiaGymGymGuideChampInMakingText
	db BANK(_FuchsiaGymGymGuideChampInMakingText)
	db TX_END

.BeatKogaText:
	db TX_FAR
	dw _FuchsiaGymGymGuideBeatKogaText
	db BANK(_FuchsiaGymGymGuideBeatKogaText)
	db TX_END
