;@ path: scripts/CinnabarGym
;@ def CinnabarGym_Script()
;@ Cinnabar Gym's map script: set up names and gates, then run the current step of the gym's script.
;@ test: skip CinnabarGymSetMapAndTiles names local labels, which the pseudo-code cannot reach
CinnabarGym_Script:
;> CinnabarGymSetMapAndTiles()
	call CinnabarGymSetMapAndTiles
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> CallFunctionInTable(wCinnabarGymCurScript, CinnabarGym_ScriptPointers)
	ld hl, CinnabarGym_ScriptPointers
	ld a, [wCinnabarGymCurScript]
	jp CallFunctionInTable

;@ path: scripts/CinnabarGym
;@ def CinnabarGymSetMapAndTiles()
;@ On entering, set the city and leader names (Cinnabar Island, Blaine) for the badge texts; when the gates
;@ need redrawing, draw each one open or closed.
;@ test: skip the names sit under local labels, which the pseudo-code cannot reach
CinnabarGymSetMapAndTiles:
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_2 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_2, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_2)
	res BIT_CUR_MAP_LOADED_2, [hl]
;> if loaded:
	push hl
;>     LoadGymLeaderAndCityName(CinnabarGymSetMapAndTiles.CityName, CinnabarGymSetMapAndTiles.LeaderName)
	call nz, .LoadNames
;> redraw = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	pop hl
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if redraw:
;>     UpdateCinnabarGymGateTileBlocks()
	call nz, UpdateCinnabarGymGateTileBlocks
;> reset_event(EVENT_2A7)
	ld hl, wEventFlags + $54
	res (EVENT_2A7) % 8, [hl]
	ret

.LoadNames:
	ld hl, .CityName
	ld de, .LeaderName
	jp LoadGymLeaderAndCityName

.CityName:
	db "CINNABAR ISLAND@"

.LeaderName:
	db "BLAINE@"

;@ path: scripts/CinnabarGym
;@ def CinnabarGymResetScripts()
;@ Back to the gym's default step, with the controls given back and no trainer coming after a wrong quiz answer.
CinnabarGymResetScripts:
;> wJoyIgnore = 0
	xor a ; SCRIPT_CINNABARGYM_DEFAULT
	ld [wJoyIgnore], a
;> wCinnabarGymCurScript = SCRIPT_CINNABARGYM_DEFAULT
	ld [wCinnabarGymCurScript], a
;> wCurMapScript = SCRIPT_CINNABARGYM_DEFAULT
	ld [wCurMapScript], a
;> wOpponentAfterWrongAnswer = 0
	ld [wOpponentAfterWrongAnswer], a
	ret

;@ path: scripts/CinnabarGym
;@ def CinnabarGymSetTrainerHeader()
;@ Note which trainer is talking: his text ID is also the number his gate and his "beaten" flag go by.
CinnabarGymSetTrainerHeader:
;> wTrainerHeaderFlagBit = hTextID
	ldh a, [hTextID]
	ld [wTrainerHeaderFlagBit], a
	ret

;@ path: scripts/CinnabarGym
CinnabarGym_ScriptPointers:
	dw CinnabarGymDefaultScript
DEF SCRIPT_CINNABARGYM_DEFAULT EQU 0
	dw CinnabarGymGetOpponentTextScript
DEF SCRIPT_CINNABARGYM_GET_OPPONENT_TEXT EQU 1
	dw CinnabarGymOpenGateScript
DEF SCRIPT_CINNABARGYM_OPEN_GATE EQU 2
	dw CinnabarGymBlainePostBattleScript
DEF SCRIPT_CINNABARGYM_BLAINE_POST_BATTLE EQU 3

;@ path: scripts/CinnabarGym
;@ def CinnabarGymDefaultScript()
;@ After a wrong answer at a quiz machine the trainer behind it walks up to the player (one of them comes
;@ from below, the others from the right).
CinnabarGymDefaultScript:
;> opponent = wOpponentAfterWrongAnswer
	ld a, [wOpponentAfterWrongAnswer]
;> if not opponent:
;>     return
	and a
	ret z
;> hSpriteIndex = opponent
	ldh [hSpriteIndex], a
;> if opponent == CINNABARGYM_SUPER_NERD3:
	cp CINNABARGYM_SUPER_NERD3
	jr nz, .not_super_nerd3
;>     wPlayerMovingDirection = PLAYER_DIR_DOWN
	ld a, PLAYER_DIR_DOWN
	ld [wPlayerMovingDirection], a
;>     moves = MovementNpcToLeftAndUp
	ld de, MovementNpcToLeftAndUp
	jr .MoveSprite
;> else:
.not_super_nerd3
;>     moves = MovementNpcToLeft
	ld de, MovementNpcToLeft
;>     wPlayerMovingDirection = PLAYER_DIR_RIGHT
	ld a, PLAYER_DIR_RIGHT
	ld [wPlayerMovingDirection], a
;> MoveSprite(moves)
.MoveSprite
	call MoveSprite
;> wCinnabarGymCurScript = SCRIPT_CINNABARGYM_GET_OPPONENT_TEXT
	ld a, SCRIPT_CINNABARGYM_GET_OPPONENT_TEXT
	ld [wCinnabarGymCurScript], a
;> wCurMapScript = SCRIPT_CINNABARGYM_GET_OPPONENT_TEXT
	ld [wCurMapScript], a
	ret

;@ path: scripts/CinnabarGym
MovementNpcToLeftAndUp:
	db NPC_MOVEMENT_LEFT
	db NPC_MOVEMENT_UP
	db -1 ; end

;@ path: scripts/CinnabarGym
MovementNpcToLeft:
	db NPC_MOVEMENT_LEFT
	db -1 ; end

;@ path: scripts/CinnabarGym
;@ def CinnabarGymGetOpponentTextScript()
;@ When the trainer has walked up: give the controls back and let him speak (and battle).
CinnabarGymGetOpponentTextScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
;>     return
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wTrainerHeaderFlagBit = wOpponentAfterWrongAnswer
	ld a, [wOpponentAfterWrongAnswer]
	ld [wTrainerHeaderFlagBit], a
;> hTextID = wOpponentAfterWrongAnswer
	ldh [hTextID], a
;> return DisplayTextID()
	jp DisplayTextID

;@ path: scripts/CinnabarGym
;@ def CinnabarGymFlagAction() -> c
;@ Test, set or reset bit c of the flags at hl (b says which), for the gym's trainer and gate flags.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
CinnabarGymFlagAction:
;> return FlagActionPredef()
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/CinnabarGym
;@ def CinnabarGymOpenGateScript()
;@ After a battle with one of the quiz trainers: lost, start over; won, he counts as beaten and his gate
;@ opens (with a sound the first time).
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
CinnabarGymOpenGateScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return CinnabarGymResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, CinnabarGymResetScripts
;> trainer = wTrainerHeaderFlagBit - 2         # the quiz trainers have text IDs 2 to 8
;> hGymGateIndex = wTrainerHeaderFlagBit
	ld a, [wTrainerHeaderFlagBit]
	ldh [hGymGateIndex], a
;> beaten = event(EVENT_BEAT_CINNABAR_GYM_TRAINER_0 + trainer)     # CinnabarGymFlagAction, FLAG_TEST
	ld c, a
	ld b, FLAG_TEST
	ld hl, wEventFlags + $53
	call CinnabarGymFlagAction
;> if not beaten:
	ld a, c
	and a
	jr nz, .no_sound
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
;>     PlaySound(SFX_GO_INSIDE)
	ld a, SFX_GO_INSIDE
	call PlaySound
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
;> hGymGateIndex = wTrainerHeaderFlagBit
.no_sound
	ld a, [wTrainerHeaderFlagBit]
	ldh [hGymGateIndex], a
;> set_event(EVENT_BEAT_CINNABAR_GYM_TRAINER_0 + trainer)         # CinnabarGymFlagAction, FLAG_SET
	ld c, a
	ld b, FLAG_SET
	ld hl, wEventFlags + $53
	call CinnabarGymFlagAction
;> set_event(EVENT_CINNABAR_GYM_GATE0_UNLOCKED + trainer)         # CinnabarGymFlagAction, FLAG_SET
	ld a, [wTrainerHeaderFlagBit]
	sub $2
	ld c, a
	ld b, FLAG_SET
	ld hl, wEventFlags + $55
	call CinnabarGymFlagAction
;> UpdateCinnabarGymGateTileBlocks()
	call UpdateCinnabarGymGateTileBlocks
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wOpponentAfterWrongAnswer = 0
	ld [wOpponentAfterWrongAnswer], a
;> wCinnabarGymCurScript = SCRIPT_CINNABARGYM_DEFAULT
	ld a, SCRIPT_CINNABARGYM_DEFAULT
	ld [wCinnabarGymCurScript], a
;> wCurMapScript = SCRIPT_CINNABARGYM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/CinnabarGym
;@ def CinnabarGymBlainePostBattleScript()
;@ After the battle with Blaine: lost, start over; won, go on to the badge and TM38.
CinnabarGymBlainePostBattleScript:
;> if wIsInBattle == LOST_BATTLE:
;>     return CinnabarGymResetScripts()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, CinnabarGymResetScripts
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
; fallthrough

;> return CinnabarGymReceiveTM38()
;@ path: scripts/CinnabarGym
;@ def CinnabarGymReceiveTM38()
;@ Blaine's reward: the Volcano Badge text, TM38 (FIRE BLAST) if the bag has room, the badge itself; all the
;@ gym's trainers count as beaten, and the gates get redrawn.
CinnabarGymReceiveTM38:
;> hTextID = TEXT_CINNABARGYM_BLAINE_VOLCANO_BADGE_INFO
	ld a, TEXT_CINNABARGYM_BLAINE_VOLCANO_BADGE_INFO
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> set_event(EVENT_BEAT_BLAINE)
	ld hl, wEventFlags + $53
	set (EVENT_BEAT_BLAINE) % 8, [hl]
;> if GiveItem(TM_FIRE_BLAST, 1):
	ld bc, ((TM_FIRE_BLAST) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .BagFull
;>     hTextID = TEXT_CINNABARGYM_BLAINE_RECEIVED_TM38
	ld a, TEXT_CINNABARGYM_BLAINE_RECEIVED_TM38
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;>     set_event(EVENT_GOT_TM38)
	ld hl, wEventFlags + $53
	set (EVENT_GOT_TM38) % 8, [hl]
	jr .gymVictory
;> else:
.BagFull
;>     hTextID = TEXT_CINNABARGYM_BLAINE_TM38_NO_ROOM
	ld a, TEXT_CINNABARGYM_BLAINE_TM38_NO_ROOM
	ldh [hTextID], a
;>     DisplayTextID()
	call DisplayTextID
;> wObtainedBadges |= 1 << BIT_VOLCANOBADGE
.gymVictory
	ld hl, wObtainedBadges
	set BIT_VOLCANOBADGE, [hl]
;> wBeatGymFlags |= 1 << BIT_VOLCANOBADGE
	ld hl, wBeatGymFlags
	set BIT_VOLCANOBADGE, [hl]
;> for e in range(EVENT_BEAT_CINNABAR_GYM_TRAINER_0, EVENT_BEAT_CINNABAR_GYM_TRAINER_6 + 1):

	; deactivate gym trainers
	ld a, [wEventFlags + $53]
	or $ff - ((1 << ((EVENT_BEAT_CINNABAR_GYM_TRAINER_0) % 8)) - 1)
;>     set_event(e)
	ld [wEventFlags + $53], a
	ld hl, wEventFlags + $54
	set 0, [hl]

;> wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
;> return CinnabarGymResetScripts()

	jp CinnabarGymResetScripts

;@ path: scripts/CinnabarGym
CinnabarGym_TextPointers:
	dw CinnabarGymBlaineText
DEF TEXT_CINNABARGYM_BLAINE EQU 1
	dw CinnabarGymSuperNerd1
DEF TEXT_CINNABARGYM_SUPER_NERD1 EQU 2
	dw CinnabarGymSuperNerd2
DEF TEXT_CINNABARGYM_SUPER_NERD2 EQU 3
	dw CinnabarGymSuperNerd3
DEF TEXT_CINNABARGYM_SUPER_NERD3 EQU 4
	dw CinnabarGymSuperNerd4
DEF TEXT_CINNABARGYM_SUPER_NERD4 EQU 5
	dw CinnabarGymSuperNerd5
DEF TEXT_CINNABARGYM_SUPER_NERD5 EQU 6
	dw CinnabarGymSuperNerd6
DEF TEXT_CINNABARGYM_SUPER_NERD6 EQU 7
	dw CinnabarGymSuperNerd7
DEF TEXT_CINNABARGYM_SUPER_NERD7 EQU 8
	dw CinnabarGymGymGuideText
DEF TEXT_CINNABARGYM_GYM_GUIDE EQU 9
	dw CinnabarGymBlaineVolcanoBadgeInfoText
DEF TEXT_CINNABARGYM_BLAINE_VOLCANO_BADGE_INFO EQU $A
	dw CinnabarGymBlaineReceivedTM38Text
DEF TEXT_CINNABARGYM_BLAINE_RECEIVED_TM38 EQU $B
	dw CinnabarGymBlaineTM38NoRoomText
DEF TEXT_CINNABARGYM_BLAINE_TM38_NO_ROOM EQU $C

;@ path: scripts/CinnabarGym
;@ def CinnabarGymStartBattleScript() -> hl
;@ End of a trainer's text in this gym: start the battle with the trainer being talked to, and go to the
;@ after-battle step (Blaine's, or the one that opens a quiz trainer's gate).
CinnabarGymStartBattleScript:
;> wSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wSpriteIndex], a
;> EngageMapTrainer()
	call EngageMapTrainer
;> InitBattleEnemyParameters()
	call InitBattleEnemyParameters
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> if wSpriteIndex == CINNABARGYM_BLAINE:
	ld a, [wSpriteIndex]
	cp CINNABARGYM_BLAINE
	jr z, .blaine
	ld a, SCRIPT_CINNABARGYM_OPEN_GATE
	jr .not_blaine
.blaine
;>     script = SCRIPT_CINNABARGYM_BLAINE_POST_BATTLE
	ld a, SCRIPT_CINNABARGYM_BLAINE_POST_BATTLE
;> else:
.not_blaine
;>     script = SCRIPT_CINNABARGYM_OPEN_GATE
;> wCinnabarGymCurScript = script
	ld [wCinnabarGymCurScript], a
;> wCurMapScript = script
	ld [wCurMapScript], a
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: scripts/CinnabarGym
;@ def CinnabarGymBlaineText() -> hl
;@ Blaine: before the battle he challenges the player; after it he gives TM38 if he still owes it, and
;@ otherwise has advice.
;@ test: skip a text script: the code after text_asm is run by the text engine
CinnabarGymBlaineText:
	db TX_START_ASM
;> if event(EVENT_BEAT_BLAINE):
	ld a, [wEventFlags + $53]
	bit (EVENT_BEAT_BLAINE) % 8, a
	jr z, .beforeBeat
;>     if event(EVENT_GOT_TM38):
	bit (EVENT_GOT_TM38) % 8, a
	jr nz, .afterBeat
;>         PrintText(CinnabarGymBlaineText.PostBattleAdviceText)
;>     else:
;>         CinnabarGymReceiveTM38()
	call z, CinnabarGymReceiveTM38
;>         DisableWaitingAfterTextDisplay()
	call DisableWaitingAfterTextDisplay
;>     return TextScriptEnd()
	jp TextScriptEnd
.afterBeat
	ld hl, .PostBattleAdviceText
	call PrintText
	jp TextScriptEnd
;> PrintText(CinnabarGymBlaineText.PreBattleText)
.beforeBeat
	ld hl, .PreBattleText
	call PrintText
;> SaveEndBattleTextPointers(CinnabarGymBlaineText.ReceivedVolcanoBadgeText, CinnabarGymBlaineText.ReceivedVolcanoBadgeText)
	ld hl, .ReceivedVolcanoBadgeText
	ld de, .ReceivedVolcanoBadgeText
	call SaveEndBattleTextPointers
;> wGymLeaderNo = 7
	ld a, $7
	ld [wGymLeaderNo], a
;> return CinnabarGymStartBattleScript()
	jp CinnabarGymStartBattleScript

.PreBattleText:
	db TX_FAR
	dw _CinnabarGymBlainePreBattleText
	db BANK(_CinnabarGymBlainePreBattleText)
	db TX_END

.ReceivedVolcanoBadgeText:
	db TX_FAR
	dw _CinnabarGymBlaineReceivedVolcanoBadgeText
	db BANK(_CinnabarGymBlaineReceivedVolcanoBadgeText)
	; actually plays the second channel of SFX_BALL_POOF due to the wrong music bank being loaded
	db TX_SOUND_GET_KEY_ITEM
	db TX_WAIT_BUTTON
	db TX_END

.PostBattleAdviceText:
	db TX_FAR
	dw _CinnabarGymBlainePostBattleAdviceText
	db BANK(_CinnabarGymBlainePostBattleAdviceText)
	db TX_END

