;@ path: scripts/CinnabarGym
;@ def CinnabarGymGymGuideText() -> hl
;@ The gym guide: advice before the battle with Blaine, praise after it.
;@ test: skip a text script: the code after text_asm is run by the text engine
CinnabarGymGymGuideText:
	db TX_START_ASM
;> if not event(EVENT_BEAT_BLAINE):
	ld a, [wEventFlags + $53]
	bit (EVENT_BEAT_BLAINE) % 8, a
	jr nz, .afterBeat
;>     text = CinnabarGymGymGuideText.ChampInMakingText
	ld hl, .ChampInMakingText
	jr .done
.afterBeat
;> else:
;>     text = CinnabarGymGymGuideText.BeatBlaineText
	ld hl, .BeatBlaineText
.done
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.ChampInMakingText:
	db TX_FAR
	dw _CinnabarGymGymGuideChampInMakingText
	db BANK(_CinnabarGymGymGuideChampInMakingText)
	db TX_END

.BeatBlaineText:
	db TX_FAR
	dw _CinnabarGymGymGuideBeatBlaineText
	db BANK(_CinnabarGymGymGuideBeatBlaineText)
	db TX_END
;> # the gym's people: Blaine and the first three quiz trainers,
DEF CINNABARGYM_BLAINE EQU 1
	EXPORT CINNABARGYM_BLAINE
DEF CINNABARGYM_SUPER_NERD1 EQU 2
	EXPORT CINNABARGYM_SUPER_NERD1
DEF CINNABARGYM_SUPER_NERD2 EQU 3
	EXPORT CINNABARGYM_SUPER_NERD2
;> # (more object numbers)
DEF CINNABARGYM_SUPER_NERD3 EQU 4
	EXPORT CINNABARGYM_SUPER_NERD3
;> # trainers 4-7,
DEF CINNABARGYM_SUPER_NERD4 EQU 5
	EXPORT CINNABARGYM_SUPER_NERD4
