;@ path: scripts/CinnabarLabMetronomeRoom
;@ def CinnabarLabMetronomeRoomScientist1Text() -> hl
;@ The scientist who gives TM35 (METRONOME) once, if the bag has room, and explains it afterwards.
;@ test: skip a text script: the code after text_asm is run by the text engine
CinnabarLabMetronomeRoomScientist1Text:
	db TX_START_ASM
;> if event(EVENT_GOT_TM35):
	ld a, [wEventFlags + $5A]
	bit (EVENT_GOT_TM35) % 8, a
;>     PrintText(CinnabarLabMetronomeRoomScientist1Text.TM35ExplanationText)
;>     return TextScriptEnd()
	jr nz, .got_item
;> PrintText(CinnabarLabMetronomeRoomScientist1Text.Text)
	ld hl, .Text
	call PrintText
;> if GiveItem(TM_METRONOME, 1):
	ld bc, ((TM_METRONOME) & $ff) << 8 + ((1) & $ff)
	call GiveItem
	jr nc, .bag_full
;>     PrintText(CinnabarLabMetronomeRoomScientist1Text.ReceivedTM35Text)
	ld hl, .ReceivedTM35Text
	call PrintText
;>     set_event(EVENT_GOT_TM35)
	ld hl, wEventFlags + $5A
	set (EVENT_GOT_TM35) % 8, [hl]
	jr .done
;> else:
.bag_full
;>     PrintText(CinnabarLabMetronomeRoomScientist1Text.TM35NoRoomText)
	ld hl, .TM35NoRoomText
	call PrintText
	jr .done
.got_item
	ld hl, .TM35ExplanationText
	call PrintText
;> return TextScriptEnd()
.done
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _CinnabarLabMetronomeRoomScientist1Text
	db BANK(_CinnabarLabMetronomeRoomScientist1Text)
	db TX_END

.ReceivedTM35Text:
	db TX_FAR
	dw _CinnabarLabMetronomeRoomScientist1ReceivedTM35Text
	db BANK(_CinnabarLabMetronomeRoomScientist1ReceivedTM35Text)
	db TX_SOUND_GET_ITEM_1
	db TX_END

.TM35ExplanationText:
	db TX_FAR
	dw _CinnabarLabMetronomeRoomScientist1TM35ExplanationText
	db BANK(_CinnabarLabMetronomeRoomScientist1TM35ExplanationText)
	db TX_END

.TM35NoRoomText:
	db TX_FAR
	dw _CinnabarLabMetronomeRoomScientist1TM35NoRoomText
	db BANK(_CinnabarLabMetronomeRoomScientist1TM35NoRoomText)
	db TX_END

