;@ path: scripts/CinnabarLabFossilRoom
;@ def Lab4Script_GetFossilsInBag()
;@ List the fossils the player carries (Dome Fossil, Helix Fossil, Old Amber) in wFilteredBagItems, ending
;@ in $FF, with their number in wFilteredBagItemsCount.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
Lab4Script_GetFossilsInBag:
; construct a list of all fossils in the player's bag
;> wFilteredBagItemsCount = 0
	xor a
	ld [wFilteredBagItemsCount], a
;> out = addr(wFilteredBagItems)
	ld de, wFilteredBagItems
;> p = FossilsList
	ld hl, FossilsList
;> while mem[p]:
.loop
	ld a, [hli]
	and a
	jr z, .done
;>     wTempByteValue = mem[p]
	push hl
	push de
	ld [wTempByteValue], a
;>     p += 1
;>     count = GetQuantityOfItemInBag()       # b = the fossil, through the predef
	ld b, a
	ld a, (GetQuantityOfItemInBagPredef - PredefPointers) / 3
	call Predef
	pop de
	pop hl
;>     if count:
	ld a, b
	and a
	jr z, .loop
;>         mem[out] = wTempByteValue
	; A fossil is in the bag
	ld a, [wTempByteValue]
	ld [de], a
;>         out += 1
	inc de
;>         wFilteredBagItemsCount += 1
	push hl
	ld hl, wFilteredBagItemsCount
	inc [hl]
	pop hl
	jr .loop
.done
;> mem[out] = 0xFF
	ld a, $ff
	ld [de], a
	ret

;@ path: scripts/CinnabarLabFossilRoom
FossilsList:
	db DOME_FOSSIL
	db HELIX_FOSSIL
	db OLD_AMBER
	db 0 ; end

;@ path: scripts/CinnabarLabFossilRoom
;@ def CinnabarLabFossilRoomScientist1Text() -> hl
;@ The fossil scientist: takes a fossil from the player to revive it; while it is being revived the player
;@ should go for a walk (leave the island); afterwards he hands over the Pokémon at level 30.
;@ test: skip a text script: the code after text_asm is run by the text engine
CinnabarLabFossilRoomScientist1Text:
	db TX_START_ASM
;> if not event(EVENT_GAVE_FOSSIL_TO_LAB):
	ld a, [wEventFlags + $5C]
	bit (EVENT_GAVE_FOSSIL_TO_LAB) % 8, a
	jr nz, .check_done_reviving
;>     PrintText(CinnabarLabFossilRoomScientist1Text.Text)
	ld hl, .Text
	call PrintText
;>     Lab4Script_GetFossilsInBag()
	call Lab4Script_GetFossilsInBag
;>     if wFilteredBagItemsCount:
	ld a, [wFilteredBagItemsCount]
	and a
	jr z, .no_fossils
;>         GiveFossilToCinnabarLab()
	ld b, BANK(GiveFossilToCinnabarLab)
	ld hl, GiveFossilToCinnabarLab
	call Bankswitch
	jr .done
;>     else:
.no_fossils
;>         PrintText(CinnabarLabFossilRoomScientist1Text.NoFossilsText)
	ld hl, .NoFossilsText
	call PrintText
.done
	jp TextScriptEnd
.check_done_reviving
;> elif event(EVENT_LAB_STILL_REVIVING_FOSSIL):
	bit (EVENT_LAB_STILL_REVIVING_FOSSIL) % 8, a
	jr z, .done_reviving
;>     PrintText(CinnabarLabFossilRoomScientist1Text.GoForAWalkText)
	ld hl, .GoForAWalkText
	call PrintText
	jr .done
;> else:
.done_reviving
;>     LoadFossilItemAndMonNameBank1D()
	call LoadFossilItemAndMonNameBank1D
;>     PrintText(CinnabarLabFossilRoomScientist1Text.FossilIsBackToLifeText)
	ld hl, .FossilIsBackToLifeText
	call PrintText
;>     set_event(EVENT_LAB_HANDING_OVER_FOSSIL_MON)
	ld hl, wEventFlags + $5C
	set (EVENT_LAB_HANDING_OVER_FOSSIL_MON) % 8, [hl]
;>     if GivePokemon(wFossilMon, 30):
	ld a, [wFossilMon]
	ld b, a
	ld c, 30
	call GivePokemon
	jr nc, .done
;>         reset_event(EVENT_GAVE_FOSSIL_TO_LAB)
	ld hl, wEventFlags + $5C
	res (EVENT_GAVE_FOSSIL_TO_LAB) % 8, [hl]
;>         reset_event(EVENT_LAB_STILL_REVIVING_FOSSIL)
	res (EVENT_LAB_STILL_REVIVING_FOSSIL) % 8, [hl]
;>         reset_event(EVENT_LAB_HANDING_OVER_FOSSIL_MON)
	res (EVENT_LAB_HANDING_OVER_FOSSIL_MON) % 8, [hl]
;> return TextScriptEnd()
	jr .done

.Text:
	db TX_FAR
	dw _CinnabarLabFossilRoomScientist1Text
