ChampionsRoom_h::
	db GYM
	db $4, $4
	dw ChampionsRoom_Blocks
	dw ChampionsRoom_TextPointers
	dw ChampionsRoom_Script
	db 0
	dw ChampionsRoom_Object
;@ path: scripts/ChampionsRoom
;@ def ChampionsRoom_Script()
;@ The Champion's room map script: run the current step of the room's script (the final battle with the
;@ rival, then Oak).
ChampionsRoom_Script:
;> EnableAutoTextBoxDrawing()
;> CallFunctionInTable(wChampionsRoomCurScript, ChampionsRoom_ScriptPointers)
	call EnableAutoTextBoxDrawing
	ld hl, ChampionsRoom_ScriptPointers
	ld a, [wChampionsRoomCurScript]
	jp CallFunctionInTable

;@ path: scripts/ChampionsRoom
;@ def ResetRivalScript()
;@ Back to the room's default step, with the controls given back.
ResetRivalScript:
;> wJoyIgnore = 0
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_DEFAULT
	xor a ; SCRIPT_CHAMPIONSROOM_DEFAULT
	ld [wJoyIgnore], a
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
ChampionsRoom_ScriptPointers:
	dw ChampionsRoomDefaultScript
DEF SCRIPT_CHAMPIONSROOM_DEFAULT EQU 0
	dw ChampionsRoomPlayerEntersScript
DEF SCRIPT_CHAMPIONSROOM_PLAYER_ENTERS EQU 1
	dw ChampionsRoomRivalReadyToBattleScript
DEF SCRIPT_CHAMPIONSROOM_RIVAL_READY_TO_BATTLE EQU 2
	dw ChampionsRoomRivalDefeatedScript
DEF SCRIPT_CHAMPIONSROOM_RIVAL_DEFEATED EQU 3
	dw ChampionsRoomOakArrivesScript
DEF SCRIPT_CHAMPIONSROOM_OAK_ARRIVES EQU 4
	dw ChampionsRoomOakCongratulatesPlayerScript
DEF SCRIPT_CHAMPIONSROOM_OAK_CONGRATULATES_PLAYER EQU 5
	dw ChampionsRoomOakDisappointedWithRivalScript
DEF SCRIPT_CHAMPIONSROOM_OAK_DISAPPOINTED_WITH_RIVAL EQU 6
	dw ChampionsRoomOakComeWithMeScript
DEF SCRIPT_CHAMPIONSROOM_OAK_COME_WITH_ME EQU 7
	dw ChampionsRoomOakExitsScript
DEF SCRIPT_CHAMPIONSROOM_OAK_EXITS EQU 8
	dw ChampionsRoomPlayerFollowsOakScript
DEF SCRIPT_CHAMPIONSROOM_PLAYER_FOLLOWS_OAK EQU 9
	dw ChampionsRoomCleanupScript
DEF SCRIPT_CHAMPIONSROOM_CLEANUP_SCRIPT EQU $A

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomDefaultScript()
;@ The room's idle step: nothing happens.
ChampionsRoomDefaultScript:
;> return
	ret

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomPlayerEntersScript()
;@ Entering: the player is walked up to the rival by simulated button presses.
ChampionsRoomPlayerEntersScript:
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> count = DecodeRLEList(addr(wSimulatedJoypadStatesEnd), RivalEntrance_RLEMovement)   # the steps, run-length coded
	ld hl, wSimulatedJoypadStatesEnd
	ld de, RivalEntrance_RLEMovement
	call DecodeRLEList
;> wSimulatedJoypadStatesIndex = count - 1
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_RIVAL_READY_TO_BATTLE
	ld a, SCRIPT_CHAMPIONSROOM_RIVAL_READY_TO_BATTLE
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
RivalEntrance_RLEMovement:
	db PAD_UP, 1
	db PAD_RIGHT, 1
	db PAD_UP, 3
	db -1 ; end

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomRivalReadyToBattleScript()
;@ When the walk is over: battle animations are switched on, the rival speaks, and the final battle is set
;@ up with the team that beats the player's starter.
ChampionsRoomRivalReadyToBattleScript:
;> if wSimulatedJoypadStatesIndex:
	ld a, [wSimulatedJoypadStatesIndex]
	and a
;>     return
	ret nz
;> Delay3()
	call Delay3
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wOptions &= ~(1 << BIT_BATTLE_ANIMATION)
	ld hl, wOptions
	res BIT_BATTLE_ANIMATION, [hl]
;> hTextID = TEXT_CHAMPIONSROOM_RIVAL
	ld a, TEXT_CHAMPIONSROOM_RIVAL
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> Delay3()
	call Delay3
;> wStatusFlags3 |= 1 << BIT_TALKED_TO_TRAINER | 1 << BIT_PRINT_END_BATTLE_TEXT
	ld hl, wStatusFlags3
	set BIT_TALKED_TO_TRAINER, [hl]
	set BIT_PRINT_END_BATTLE_TEXT, [hl]
;> SaveEndBattleTextPointers(RivalDefeatedText, RivalVictoryText)
	ld hl, RivalDefeatedText
	ld de, RivalVictoryText
	call SaveEndBattleTextPointers
;> wCurOpponent = OPP_RIVAL3
	ld a, OPP_RIVAL3
	ld [wCurOpponent], a
;> if wRivalStarter == STARTER2:

	; select which team to use during the encounter
	ld a, [wRivalStarter]
	cp STARTER2
	jr nz, .NotStarter2
;>     wTrainerNo = 1
	ld a, $1
	jr .saveTrainerId
;> elif wRivalStarter == STARTER3:
.NotStarter2
	cp STARTER3
	jr nz, .NotStarter3
;>     wTrainerNo = 2
	ld a, $2
	jr .saveTrainerId
;> else:
.NotStarter3
;>     wTrainerNo = 3
	ld a, $3
.saveTrainerId
	ld [wTrainerNo], a
;> hJoyHeld = 0

	xor a
	ldh [hJoyHeld], a
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_RIVAL_DEFEATED
	ld a, SCRIPT_CHAMPIONSROOM_RIVAL_DEFEATED
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomRivalDefeatedScript()
;@ After the final battle: lost, start over; won, the player is the champion and the rival has his say.
ChampionsRoomRivalDefeatedScript:
;> if wIsInBattle == LOST_BATTLE:
	ld a, [wIsInBattle]
	cp LOST_BATTLE
;>     return ResetRivalScript()
	jp z, ResetRivalScript
;> UpdateSprites()
	call UpdateSprites
;> set_event(EVENT_BEAT_CHAMPION_RIVAL)
	ld hl, wEventFlags + $120
	set (EVENT_BEAT_CHAMPION_RIVAL) % 8, [hl]
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> hTextID = TEXT_CHAMPIONSROOM_RIVAL
	ld a, TEXT_CHAMPIONSROOM_RIVAL
	ldh [hTextID], a
;> ChampionsRoom_DisplayTextID_AllowABSelectStart()
	call ChampionsRoom_DisplayTextID_AllowABSelectStart
;> hSpriteIndex = CHAMPIONSROOM_RIVAL
	ld a, CHAMPIONSROOM_RIVAL
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_OAK_ARRIVES
	ld a, SCRIPT_CHAMPIONSROOM_OAK_ARRIVES
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomOakArrivesScript()
;@ Oak calls out and walks in, to a faster version of the city music.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
ChampionsRoomOakArrivesScript:
;> Music_Cities1AlternateTempo()
	ld b, BANK(Music_Cities1AlternateTempo)
	ld hl, Music_Cities1AlternateTempo
	call Bankswitch
;> hTextID = TEXT_CHAMPIONSROOM_OAK
	ld a, TEXT_CHAMPIONSROOM_OAK
	ldh [hTextID], a
;> ChampionsRoom_DisplayTextID_AllowABSelectStart()
	call ChampionsRoom_DisplayTextID_AllowABSelectStart
;> hSpriteIndex = CHAMPIONSROOM_OAK
	ld a, CHAMPIONSROOM_OAK
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	call SetSpriteMovementBytesToFF
;> hSpriteIndex = CHAMPIONSROOM_OAK
	ld de, OakEntranceAfterVictoryMovement
	ld a, CHAMPIONSROOM_OAK
	ldh [hSpriteIndex], a
;> MoveSprite(OakEntranceAfterVictoryMovement)
	call MoveSprite
;> wToggleableObjectIndex = TOGGLE_CHAMPIONS_ROOM_OAK
	ld a, TOGGLE_CHAMPIONS_ROOM_OAK
	ld [wToggleableObjectIndex], a
;> ShowObject()
	ld a, (ShowObjectPredef - PredefPointers) / 3
	call Predef
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_OAK_CONGRATULATES_PLAYER
	ld a, SCRIPT_CHAMPIONSROOM_OAK_CONGRATULATES_PLAYER
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
OakEntranceAfterVictoryMovement:
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db -1 ; end

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomOakCongratulatesPlayerScript()
;@ When Oak has arrived: the player and the rival turn towards him, and he congratulates the player.
ChampionsRoomOakCongratulatesPlayerScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
;>     return
	ret nz
;> wPlayerMovingDirection = PLAYER_DIR_LEFT
	ld a, PLAYER_DIR_LEFT
	ld [wPlayerMovingDirection], a
;> hSpriteIndex = CHAMPIONSROOM_RIVAL
	ld a, CHAMPIONSROOM_RIVAL
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_LEFT
	ld a, SPRITE_FACING_LEFT
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hSpriteIndex = CHAMPIONSROOM_OAK
	ld a, CHAMPIONSROOM_OAK
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hTextID = TEXT_CHAMPIONSROOM_OAK_CONGRATULATES_PLAYER
	ld a, TEXT_CHAMPIONSROOM_OAK_CONGRATULATES_PLAYER
	ldh [hTextID], a
;> ChampionsRoom_DisplayTextID_AllowABSelectStart()
	call ChampionsRoom_DisplayTextID_AllowABSelectStart
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_OAK_DISAPPOINTED_WITH_RIVAL
	ld a, SCRIPT_CHAMPIONSROOM_OAK_DISAPPOINTED_WITH_RIVAL
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomOakDisappointedWithRivalScript()
;@ Oak turns to the rival and tells him why he lost.
ChampionsRoomOakDisappointedWithRivalScript:
;> hSpriteIndex = CHAMPIONSROOM_OAK
	ld a, CHAMPIONSROOM_OAK
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_RIGHT
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hTextID = TEXT_CHAMPIONSROOM_OAK_DISAPPOINTED_WITH_RIVAL
	ld a, TEXT_CHAMPIONSROOM_OAK_DISAPPOINTED_WITH_RIVAL
	ldh [hTextID], a
;> ChampionsRoom_DisplayTextID_AllowABSelectStart()
	call ChampionsRoom_DisplayTextID_AllowABSelectStart
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_OAK_COME_WITH_ME
	ld a, SCRIPT_CHAMPIONSROOM_OAK_COME_WITH_ME
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomOakComeWithMeScript()
;@ Oak asks the player to come with him and walks to the Hall of Fame.
ChampionsRoomOakComeWithMeScript:
;> hSpriteIndex = CHAMPIONSROOM_OAK
	ld a, CHAMPIONSROOM_OAK
	ldh [hSpriteIndex], a
;> hSpriteFacingDirection = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
	ldh [hSpriteFacingDirection], a
;> SetSpriteFacingDirectionAndDelay()
	call SetSpriteFacingDirectionAndDelay
;> hTextID = TEXT_CHAMPIONSROOM_OAK_COME_WITH_ME
	ld a, TEXT_CHAMPIONSROOM_OAK_COME_WITH_ME
	ldh [hTextID], a
;> ChampionsRoom_DisplayTextID_AllowABSelectStart()
	call ChampionsRoom_DisplayTextID_AllowABSelectStart
;> hSpriteIndex = CHAMPIONSROOM_OAK
	ld de, OakExitChampionsRoomMovement
	ld a, CHAMPIONSROOM_OAK
	ldh [hSpriteIndex], a
;> MoveSprite(OakExitChampionsRoomMovement)
	call MoveSprite
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_OAK_EXITS
	ld a, SCRIPT_CHAMPIONSROOM_OAK_EXITS
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
OakExitChampionsRoomMovement:
	db NPC_MOVEMENT_UP
	db NPC_MOVEMENT_UP
	db -1 ; end

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomOakExitsScript()
;@ When Oak has walked out, remove him.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
ChampionsRoomOakExitsScript:
;> if wStatusFlags5 >> BIT_SCRIPTED_NPC_MOVEMENT & 1:   # still walking
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> wToggleableObjectIndex = TOGGLE_CHAMPIONS_ROOM_OAK
;> predef(HideObject)
	ld a, TOGGLE_CHAMPIONS_ROOM_OAK
	ld [wToggleableObjectIndex], a
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_PLAYER_FOLLOWS_OAK
	ld a, SCRIPT_CHAMPIONSROOM_PLAYER_FOLLOWS_OAK
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomPlayerFollowsOakScript()
;@ The player follows Oak to the Hall of Fame by simulated button presses.
ChampionsRoomPlayerFollowsOakScript:
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> count = DecodeRLEList(addr(wSimulatedJoypadStatesEnd), WalkToHallOfFame_RLEMovement)   # the steps, run-length coded
	ld hl, wSimulatedJoypadStatesEnd
	ld de, WalkToHallOfFame_RLEMovement
	call DecodeRLEList
;> wSimulatedJoypadStatesIndex = count - 1
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_CLEANUP_SCRIPT
	ld a, SCRIPT_CHAMPIONSROOM_CLEANUP_SCRIPT
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
WalkToHallOfFame_RLEMovement:
	db PAD_UP, 4
	db PAD_LEFT, 1
	db -1 ; end

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomCleanupScript()
;@ When the walk is over, give the controls back and return to the default step.
ChampionsRoomCleanupScript:
;> if wSimulatedJoypadStatesIndex:
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wChampionsRoomCurScript = SCRIPT_CHAMPIONSROOM_DEFAULT
	ld a, SCRIPT_CHAMPIONSROOM_DEFAULT
	ld [wChampionsRoomCurScript], a
	ret

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoom_DisplayTextID_AllowABSelectStart()
;@ Show text hTextID with the buttons usable (only the D-pad blocked), then block all input again.
ChampionsRoom_DisplayTextID_AllowABSelectStart:
;> wJoyIgnore = PAD_CTRL_PAD
	ld a, PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> DisplayTextID()
	call DisplayTextID
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
	ret

;@ path: scripts/ChampionsRoom
ChampionsRoom_TextPointers:
	dw ChampionsRoomRivalText
DEF TEXT_CHAMPIONSROOM_RIVAL EQU 1
	dw ChampionsRoomOakText
DEF TEXT_CHAMPIONSROOM_OAK EQU 2
