DEF TEXT_CHAMPIONSROOM_OAK_CONGRATULATES_PLAYER EQU 3
	dw ChampionsRoomOakDisappointedWithRivalText
DEF TEXT_CHAMPIONSROOM_OAK_DISAPPOINTED_WITH_RIVAL EQU 4
	dw ChampionsRoomOakComeWithMeText
DEF TEXT_CHAMPIONSROOM_OAK_COME_WITH_ME EQU 5

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomRivalText() -> hl
;@ The rival as Champion: his speech before the battle, or his words after losing.
;@ test: skip a text script: the code after text_asm is run by the text engine
ChampionsRoomRivalText:
	db TX_START_ASM
;> if not event(EVENT_BEAT_CHAMPION_RIVAL):
;>     text = ChampionsRoomRivalText.IntroText
	ld a, [wEventFlags + $120]
	bit (EVENT_BEAT_CHAMPION_RIVAL) % 8, a
	ld hl, .IntroText
	jr z, .printText
;> else:
;>     text = ChampionsRoomRivalAfterBattleText
	ld hl, ChampionsRoomRivalAfterBattleText
.printText
;> PrintText(text)
;> return TextScriptEnd()
	call PrintText
	jp TextScriptEnd

.IntroText:
	db TX_FAR
	dw _ChampionsRoomRivalIntroText
	db BANK(_ChampionsRoomRivalIntroText)
	db TX_END

;@ path: scripts/ChampionsRoom
RivalDefeatedText:
	db TX_FAR
	dw _RivalDefeatedText
	db BANK(_RivalDefeatedText)
	db TX_END

;@ path: scripts/ChampionsRoom
RivalVictoryText:
	db TX_FAR
	dw _RivalVictoryText
	db BANK(_RivalVictoryText)
	db TX_END

;@ path: scripts/ChampionsRoom
ChampionsRoomRivalAfterBattleText:
