	db BANK(_ChampionsRoomOakText)
	db TX_END

;@ path: scripts/ChampionsRoom
;@ def ChampionsRoomOakCongratulatesPlayerText() -> hl
;@ Oak's congratulations, naming the player's starter Pokémon.
;@ test: skip a text script: the code after text_asm is run by the text engine
ChampionsRoomOakCongratulatesPlayerText:
	db TX_START_ASM
;> wNamedObjectIndex = wPlayerStarter
	ld a, [wPlayerStarter]
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> PrintText(ChampionsRoomOakCongratulatesPlayerText.Text)
	ld hl, .Text
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

.Text:
	db TX_FAR
	dw _ChampionsRoomOakCongratulatesPlayerText
	db BANK(_ChampionsRoomOakCongratulatesPlayerText)
	db TX_END

