DEF CHAMPIONSROOM_RIVAL EQU 1
	EXPORT CHAMPIONSROOM_RIVAL
DEF CHAMPIONSROOM_OAK EQU 2
	EXPORT CHAMPIONSROOM_OAK

;@ path: data/maps/objects/ChampionsRoom
ChampionsRoom_Object:
	db $3 ; border block

	db 4
	db 7, 3, 2 - 1, LANCES_ROOM
	db 7, 4, 3 - 1, LANCES_ROOM
	db 0, 3, 1 - 1, HALL_OF_FAME
	db 0, 4, 1 - 1, HALL_OF_FAME

	db 0

	db 2
	db SPRITE_BLUE
	db 2 + 4
	db 4 + 4
	db STAY
	db DOWN
	db TEXT_CHAMPIONSROOM_RIVAL
	db SPRITE_OAK
	db 7 + 4
	db 3 + 4
	db STAY
	db UP
	db TEXT_CHAMPIONSROOM_OAK

	dw (wOverworldMap + 7 + (CHAMPIONS_ROOM_WIDTH) + ((CHAMPIONS_ROOM_WIDTH) + 6) * ((7) >> 1) + ((3) >> 1))
	db 7, 3
	dw (wOverworldMap + 7 + (CHAMPIONS_ROOM_WIDTH) + ((CHAMPIONS_ROOM_WIDTH) + 6) * ((7) >> 1) + ((4) >> 1))
	db 7, 4
	dw (wOverworldMap + 7 + (CHAMPIONS_ROOM_WIDTH) + ((CHAMPIONS_ROOM_WIDTH) + 6) * ((0) >> 1) + ((3) >> 1))
	db 0, 3
	dw (wOverworldMap + 7 + (CHAMPIONS_ROOM_WIDTH) + ((CHAMPIONS_ROOM_WIDTH) + 6) * ((0) >> 1) + ((4) >> 1))
	db 0, 4
;@ path: maps
ChampionsRoom_Blocks:
	db $49, $31, $32, $4a, $4b, $05, $05, $4c, $4b, $05, $05, $4c, $52, $31, $32, $6f

LoreleisRoom_h::
	db GYM
	db $6, $5
	dw LoreleisRoom_Blocks
	dw LoreleisRoom_TextPointers
	dw LoreleisRoom_Script
	db 0
	dw LoreleisRoom_Object
;@ path: scripts/LoreleisRoom
;@ def LoreleisRoom_Script()
;@ Lorelei's room map script: open or close the exit, then run the current step of the room's script.
LoreleisRoom_Script:
;> LoreleiShowOrHideExitBlock()
	call LoreleiShowOrHideExitBlock
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wLoreleisRoomCurScript = ExecuteCurMapScriptInTable(wLoreleisRoomCurScript, LoreleisRoomTrainerHeaders, LoreleisRoom_ScriptPointers)
	ld hl, LoreleisRoomTrainerHeaders
	ld de, LoreleisRoom_ScriptPointers
	ld a, [wLoreleisRoomCurScript]
	call ExecuteCurMapScriptInTable
	ld [wLoreleisRoomCurScript], a
	ret

;@ path: scripts/LoreleisRoom
;@ def LoreleiShowOrHideExitBlock()
;@ When the map has just loaded: draw the exit to Bruno's room open once Lorelei is beaten, closed before.
;@ Entering this first room also marks the Elite Four challenge as started.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
LoreleiShowOrHideExitBlock:
; Blocks or clears the exit to the next room.
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> wElite4Flags |= 1 << BIT_STARTED_ELITE_4
	ld hl, wElite4Flags
	set BIT_STARTED_ELITE_4, [hl]
;> if event(EVENT_BEAT_LORELEIS_ROOM_TRAINER_0):          # beaten: the exit opens
	ld a, [wEventFlags + $11C]
	bit (EVENT_BEAT_LORELEIS_ROOM_TRAINER_0) % 8, a
	jr z, .blockExitToNextRoom
;>     block = 0x05
	ld a, $5
	jr .setExitBlock
.blockExitToNextRoom
;> else:
;>     block = 0x24
	ld a, $24
.setExitBlock
;> wNewTileBlockID = block
	ld [wNewTileBlockID], a
;> ReplaceTileBlock()                          # block row 0, column 2 (b, c through the predef)
	ld bc, ((0) & $ff) << 8 + ((2) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/LoreleisRoom
;@ def ResetLoreleiScript()
;@ Back to the room's default step.
ResetLoreleiScript:
;> wLoreleisRoomCurScript = SCRIPT_LORELEISROOM_DEFAULT
	xor a ; SCRIPT_LORELEISROOM_DEFAULT
	ld [wLoreleisRoomCurScript], a
	ret

;@ path: scripts/LoreleisRoom
LoreleisRoom_ScriptPointers:
	dw LoreleisRoomDefaultScript
DEF SCRIPT_LORELEISROOM_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_LORELEISROOM_LORELEI_START_BATTLE EQU 1
	dw LoreleisRoomLoreleiEndBattleScript
DEF SCRIPT_LORELEISROOM_LORELEI_END_BATTLE EQU 2
	dw LoreleisRoomPlayerIsMovingScript
DEF SCRIPT_LORELEISROOM_PLAYER_IS_MOVING EQU 3
	dw LoreleisRoomNoopScript
DEF SCRIPT_LORELEISROOM_NOOP EQU 4

;@ path: scripts/LoreleisRoom
;@ def LoreleisRoomNoopScript()
;@ The room's idle step: nothing happens.
LoreleisRoomNoopScript:
;> return
	ret

;@ path: scripts/LoreleisRoom
;@ def LoreleiScriptWalkIntoRoom()
;@ Walk the player six steps up into the room by simulated button presses.
LoreleiScriptWalkIntoRoom:
; Walk six steps upward.
;> p = addr(wSimulatedJoypadStatesEnd)
	ld hl, wSimulatedJoypadStatesEnd
;> mem[p:p + 3] = [PAD_UP] * 3             # six steps up
	ld a, PAD_UP
	ld [hli], a
	ld [hli], a
	ld [hli], a
;> mem[p + 3:p + 6] = [PAD_UP] * 3
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wSimulatedJoypadStatesIndex = 6
	ld a, $6
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wLoreleisRoomCurScript = SCRIPT_LORELEISROOM_PLAYER_IS_MOVING
	ld a, SCRIPT_LORELEISROOM_PLAYER_IS_MOVING
	ld [wLoreleisRoomCurScript], a
;> wCurMapScript = SCRIPT_LORELEISROOM_PLAYER_IS_MOVING
	ld [wCurMapScript], a
	ret

;@ path: scripts/LoreleisRoom
;@ def LoreleisRoomDefaultScript()
;@ Every step: the trainers watch for the player. At the entrance the player is walked into the room the
;@ first time; stepping back towards the exit gets "Don't run away!" and a step back up.
LoreleisRoomDefaultScript:
;> if not ArePlayerCoordsInArray(LoreleiEntranceCoords):
	ld hl, LoreleiEntranceCoords
	call ArePlayerCoordsInArray
;>     return CheckFightingMapTrainers()
	jp nc, CheckFightingMapTrainers
;> hJoyPressed = 0
	xor a
	ldh [hJoyPressed], a
;> hJoyHeld = 0
	ldh [hJoyHeld], a
;> wSimulatedJoypadStatesEnd = 0
	ld [wSimulatedJoypadStatesEnd], a
;> wSimulatedJoypadStatesIndex = 0
	ld [wSimulatedJoypadStatesIndex], a
;> if wCoordIndex >= 3:                        # not just above the exit
	ld a, [wCoordIndex]
	cp $3  ; Is player standing one tile above the exit?
	jr c, .stopPlayerFromLeaving
;>     walked_in = event(EVENT_AUTOWALKED_INTO_LORELEIS_ROOM)
	ld hl, wEventFlags + $11C
	bit (EVENT_AUTOWALKED_INTO_LORELEIS_ROOM) % 8, [hl]
;>     set_event(EVENT_AUTOWALKED_INTO_LORELEIS_ROOM)
	set (EVENT_AUTOWALKED_INTO_LORELEIS_ROOM) % 8, [hl]
;>     if not walked_in:
;>         return LoreleiScriptWalkIntoRoom()
	jr z, LoreleiScriptWalkIntoRoom
;> hTextID = TEXT_LORELEISROOM_DONT_RUN_AWAY
.stopPlayerFromLeaving
	ld a, TEXT_LORELEISROOM_DONT_RUN_AWAY
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID  ; "Don't run away!"
;> wSimulatedJoypadStatesEnd = PAD_UP
	ld a, PAD_UP
	ld [wSimulatedJoypadStatesEnd], a
;> wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wLoreleisRoomCurScript = SCRIPT_LORELEISROOM_PLAYER_IS_MOVING
	ld a, SCRIPT_LORELEISROOM_PLAYER_IS_MOVING
	ld [wLoreleisRoomCurScript], a
;> wCurMapScript = SCRIPT_LORELEISROOM_PLAYER_IS_MOVING
	ld [wCurMapScript], a
	ret

;@ path: scripts/LoreleisRoom
LoreleiEntranceCoords:
	db 10, 4
	db 10, 5
	db 11, 4
	db 11, 5
	db -1 ; end

;@ path: scripts/LoreleisRoom
;@ def LoreleisRoomPlayerIsMovingScript()
;@ Wait until the simulated steps are done, then give the controls back and return to the default step.
LoreleisRoomPlayerIsMovingScript:
;> if wSimulatedJoypadStatesIndex:
	ld a, [wSimulatedJoypadStatesIndex]
	and a
;>     return
	ret nz
;> Delay3()
	call Delay3
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;> wLoreleisRoomCurScript = SCRIPT_LORELEISROOM_DEFAULT
	ld [wLoreleisRoomCurScript], a
;> wCurMapScript = SCRIPT_LORELEISROOM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/LoreleisRoom
;@ def LoreleisRoomLoreleiEndBattleScript()
;@ After the battle with Lorelei: lost, start over; won, her words after the battle.
LoreleisRoomLoreleiEndBattleScript:
;> EndTrainerBattle()
	call EndTrainerBattle
;> if wIsInBattle == LOST_BATTLE:
;>     return ResetLoreleiScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, ResetLoreleiScript
;> hTextID = TEXT_LORELEISROOM_LORELEI
;> return DisplayTextID()
	ld a, TEXT_LORELEISROOM_LORELEI
	ldh [hTextID], a
	jp DisplayTextID

