;@ When the map has just loaded: draw the exit to Agatha's room open once Bruno is beaten, closed before.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
BrunoShowOrHideExitBlock:
; Blocks or clears the exit to the next room.
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> if event(EVENT_BEAT_BRUNOS_ROOM_TRAINER_0):          # beaten: the exit opens
	ld a, [wEventFlags + $11D]
	bit (EVENT_BEAT_BRUNOS_ROOM_TRAINER_0) % 8, a
	jr z, .blockExitToNextRoom
;>     block = 0x05
	ld a, $5
	jp .setExitBlock
.blockExitToNextRoom
;> else:
;>     block = 0x24
	ld a, $24
.setExitBlock
;> wNewTileBlockID = block
	ld [wNewTileBlockID], a
;> ReplaceTileBlock()                          # block row 0, column 2 (b, c through the predef)
	ld bc, ((0) & $ff) << 8 + ((2) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

;@ path: scripts/BrunosRoom
;@ def ResetBrunoScript()
;@ Back to the room's default step.
ResetBrunoScript:
;> wBrunosRoomCurScript = SCRIPT_BRUNOSROOM_DEFAULT
	xor a ; SCRIPT_BRUNOSROOM_DEFAULT
	ld [wBrunosRoomCurScript], a
	ret

;@ path: scripts/BrunosRoom
BrunosRoom_ScriptPointers:
	dw BrunosRoomDefaultScript
DEF SCRIPT_BRUNOSROOM_DEFAULT EQU 0
	dw DisplayEnemyTrainerTextAndStartBattle
DEF SCRIPT_BRUNOSROOM_BRUNO_START_BATTLE EQU 1
	dw BrunosRoomBrunoEndBattleScript
DEF SCRIPT_BRUNOSROOM_BRUNO_END_BATTLE EQU 2
	dw BrunosRoomPlayerIsMovingScript
DEF SCRIPT_BRUNOSROOM_PLAYER_IS_MOVING EQU 3
	dw BrunosRoomNoopScript
DEF SCRIPT_BRUNOSROOM_NOOP EQU 4

;@ path: scripts/BrunosRoom
;@ def BrunosRoomNoopScript()
;@ The room's idle step: nothing happens.
BrunosRoomNoopScript:
;> return
	ret

;@ path: scripts/BrunosRoom
;@ def BrunoScriptWalkIntoRoom()
;@ Walk the player six steps up into the room by simulated button presses.
BrunoScriptWalkIntoRoom:
; Walk six steps upward.
;> p = addr(wSimulatedJoypadStatesEnd)
	ld hl, wSimulatedJoypadStatesEnd
;> mem[p:p + 3] = [PAD_UP] * 3             # six steps up
	ld a, PAD_UP
	ld [hli], a
	ld [hli], a
	ld [hli], a
;> mem[p + 3:p + 6] = [PAD_UP] * 3
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wSimulatedJoypadStatesIndex = 6
	ld a, $6
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wBrunosRoomCurScript = SCRIPT_BRUNOSROOM_PLAYER_IS_MOVING
	ld a, SCRIPT_BRUNOSROOM_PLAYER_IS_MOVING
	ld [wBrunosRoomCurScript], a
;> wCurMapScript = SCRIPT_BRUNOSROOM_PLAYER_IS_MOVING
	ld [wCurMapScript], a
	ret

;@ path: scripts/BrunosRoom
;@ def BrunosRoomDefaultScript()
;@ Every step: the trainers watch for the player. At the entrance the player is walked into the room the
;@ first time; stepping back towards the exit gets "Don't run away!" and a step back up.
BrunosRoomDefaultScript:
;> if not ArePlayerCoordsInArray(BrunoEntranceCoords):
	ld hl, BrunoEntranceCoords
	call ArePlayerCoordsInArray
;>     return CheckFightingMapTrainers()
	jp nc, CheckFightingMapTrainers
;> hJoyPressed = 0
	xor a
	ldh [hJoyPressed], a
;> hJoyHeld = 0
	ldh [hJoyHeld], a
;> wSimulatedJoypadStatesEnd = 0
	ld [wSimulatedJoypadStatesEnd], a
;> wSimulatedJoypadStatesIndex = 0
	ld [wSimulatedJoypadStatesIndex], a
;> if wCoordIndex >= 3:                        # not just above the exit
	ld a, [wCoordIndex]
	cp $3  ; Is player standing one tile above the exit?
	jr c, .stopPlayerFromLeaving
;>     walked_in = event(EVENT_AUTOWALKED_INTO_BRUNOS_ROOM)
	ld hl, wEventFlags + $11D
	bit (EVENT_AUTOWALKED_INTO_BRUNOS_ROOM) % 8, [hl]
;>     set_event(EVENT_AUTOWALKED_INTO_BRUNOS_ROOM)
	set (EVENT_AUTOWALKED_INTO_BRUNOS_ROOM) % 8, [hl]
;>     if not walked_in:
;>         return BrunoScriptWalkIntoRoom()
	jr z, BrunoScriptWalkIntoRoom
;> hTextID = TEXT_BRUNOSROOM_BRUNO_DONT_RUN_AWAY
.stopPlayerFromLeaving
	ld a, TEXT_BRUNOSROOM_BRUNO_DONT_RUN_AWAY
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID  ; "Don't run away!"
;> wSimulatedJoypadStatesEnd = PAD_UP
	ld a, PAD_UP
	ld [wSimulatedJoypadStatesEnd], a
;> wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wBrunosRoomCurScript = SCRIPT_BRUNOSROOM_PLAYER_IS_MOVING
	ld a, SCRIPT_BRUNOSROOM_PLAYER_IS_MOVING
	ld [wBrunosRoomCurScript], a
;> wCurMapScript = SCRIPT_BRUNOSROOM_PLAYER_IS_MOVING
	ld [wCurMapScript], a
	ret

;@ path: scripts/BrunosRoom
BrunoEntranceCoords:
	db 10, 4
	db 10, 5
	db 11, 4
	db 11, 5
	db -1 ; end

;@ path: scripts/BrunosRoom
;@ def BrunosRoomPlayerIsMovingScript()
;@ Wait until the simulated steps are done, then give the controls back and return to the default step.
BrunosRoomPlayerIsMovingScript:
;> if wSimulatedJoypadStatesIndex:
	ld a, [wSimulatedJoypadStatesIndex]
	and a
;>     return
	ret nz
;> Delay3()
	call Delay3
;> wJoyIgnore = 0
	xor a ; SCRIPT_BRUNOSROOM_DEFAULT
	ld [wJoyIgnore], a
;> wBrunosRoomCurScript = SCRIPT_BRUNOSROOM_DEFAULT
	ld [wBrunosRoomCurScript], a
;> wCurMapScript = SCRIPT_BRUNOSROOM_DEFAULT
	ld [wCurMapScript], a
	ret

;@ path: scripts/BrunosRoom
;@ def BrunosRoomBrunoEndBattleScript()
;@ After the battle with Bruno: lost, start over; won, his words after the battle.
BrunosRoomBrunoEndBattleScript:
;> EndTrainerBattle()
	call EndTrainerBattle
;> if wIsInBattle == LOST_BATTLE:
;>     return ResetBrunoScript()
	ld a, [wIsInBattle]
	cp LOST_BATTLE
	jp z, ResetBrunoScript
;> hTextID = TEXT_BRUNOSROOM_BRUNO
;> return DisplayTextID()
	ld a, TEXT_BRUNOSROOM_BRUNO
	ldh [hTextID], a
	jp DisplayTextID

