;@ path: data/maps/objects/BrunosRoom
BrunosRoom_Object:
	db $3 ; border block

	db 4
	db 11, 4, 3 - 1, LORELEIS_ROOM
	db 11, 5, 4 - 1, LORELEIS_ROOM
	db 0, 4, 1 - 1, AGATHAS_ROOM
	db 0, 5, 2 - 1, AGATHAS_ROOM

	db 0

	db 1
	db SPRITE_BRUNO
	db 2 + 4
	db 5 + 4
	db STAY
	db DOWN
	db TRAINER | TEXT_BRUNOSROOM_BRUNO
	db OPP_BRUNO
	db 1

	dw (wOverworldMap + 7 + (BRUNOS_ROOM_WIDTH) + ((BRUNOS_ROOM_WIDTH) + 6) * (($B) >> 1) + ((4) >> 1))
	db $B, 4
	dw (wOverworldMap + 7 + (BRUNOS_ROOM_WIDTH) + ((BRUNOS_ROOM_WIDTH) + 6) * (($B) >> 1) + ((5) >> 1))
	db $B, 5
	dw (wOverworldMap + 7 + (BRUNOS_ROOM_WIDTH) + ((BRUNOS_ROOM_WIDTH) + 6) * ((0) >> 1) + ((4) >> 1))
	db 0, 4
	dw (wOverworldMap + 7 + (BRUNOS_ROOM_WIDTH) + ((BRUNOS_ROOM_WIDTH) + 6) * ((0) >> 1) + ((5) >> 1))
	db 0, 5
