BrunosRoom_Blocks:
	db $01, $01, $05, $01, $01, $08, $05, $05, $05, $0a, $0c, $12, $05, $13, $0d, $0c
	db $0a, $05, $0b, $0c, $08, $07, $05, $0c, $08, $0d, $11, $05, $0a, $0d

