	dw AgathasRoom_Script
	db 0
	dw AgathasRoom_Object
;@ path: scripts/AgathasRoom
;@ def AgathasRoom_Script()
;@ Agatha's room map script: open or close the exit, then run the current step of the room's script.
AgathasRoom_Script:
;> AgathaShowOrHideExitBlock()
	call AgathaShowOrHideExitBlock
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wAgathasRoomCurScript = ExecuteCurMapScriptInTable(wAgathasRoomCurScript, AgathasRoomTrainerHeaders, AgathasRoom_ScriptPointers)
	ld hl, AgathasRoomTrainerHeaders
	ld de, AgathasRoom_ScriptPointers
	ld a, [wAgathasRoomCurScript]
	call ExecuteCurMapScriptInTable
	ld [wAgathasRoomCurScript], a
	ret

;@ path: scripts/AgathasRoom
;@ def AgathaShowOrHideExitBlock()
;@ When the map has just loaded: draw the exit to Lance's room open once Agatha is beaten, closed before.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
AgathaShowOrHideExitBlock:
; Blocks or clears the exit to the next room.
;> loaded = wCurrentMapScriptFlags >> BIT_CUR_MAP_LOADED_1 & 1
	ld hl, wCurrentMapScriptFlags
	bit BIT_CUR_MAP_LOADED_1, [hl]
;> wCurrentMapScriptFlags &= ~(1 << BIT_CUR_MAP_LOADED_1)
	res BIT_CUR_MAP_LOADED_1, [hl]
;> if not loaded:
;>     return
	ret z
;> if event(EVENT_BEAT_AGATHAS_ROOM_TRAINER_0):          # beaten: the exit opens
	ld a, [wEventFlags + $11E]
	bit (EVENT_BEAT_AGATHAS_ROOM_TRAINER_0) % 8, a
	jr z, .blockExitToNextRoom
;>     block = 0x0E
	ld a, $e
	jp .setExitBlock
.blockExitToNextRoom
;> else:
;>     block = 0x3B
	ld a, $3b
.setExitBlock
;> wNewTileBlockID = block
	ld [wNewTileBlockID], a
;> ReplaceTileBlock()                          # block row 0, column 2 (b, c through the predef)
	ld bc, ((0) & $ff) << 8 + ((2) & $ff)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	jp Predef

